final_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "queue_name" {
  description = "Name of the SQS queue used for notifications."
  type        = string
  default     = "notificationQueue"
}

variable "environment" {
  description = "Deployment environment name applied to all resources as a tag."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project = "notification-queue"
  }
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period in days before the KMS key is permanently deleted."
  type        = number
  default     = 30
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time, in seconds, that Amazon SQS can reuse a data key to encrypt or decrypt messages before calling KMS again."
  type        = number
  default     = 300
}

###############################################################################
# Data Sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  )
}

###############################################################################
# KMS Customer Managed Key
###############################################################################

resource "aws_kms_key" "notification_queue" {
  description             = "Customer managed key used to encrypt the ${var.queue_name} SQS queue."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.queue_name}-kms"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "notification_queue_kms" {
  statement {
    sid    = "EnableAccountRootKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:RotateKeyOnDemand",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSqsServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key_policy" "notification_queue" {
  key_id = aws_kms_key.notification_queue.id
  policy = data.aws_iam_policy_document.notification_queue_kms.json
}

resource "aws_kms_alias" "notification_queue" {
  name          = "alias/${var.queue_name}"
  target_key_id = aws_kms_key.notification_queue.key_id
}

###############################################################################
# SQS Queue
###############################################################################

resource "aws_sqs_queue" "notification_queue" {
  name                       = var.queue_name
  delay_seconds              = 0
  max_message_size           = 2048
  visibility_timeout_seconds = 30
  message_retention_seconds  = 345600

  kms_master_key_id                 = aws_kms_key.notification_queue.arn
  kms_data_key_reuse_period_seconds = var.kms_data_key_reuse_period_seconds

  tags = merge(
    local.common_tags,
    {
      Name = var.queue_name
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SQS Queue Resource-Based Policy (current account only)
###############################################################################

data "aws_iam_policy_document" "notification_queue" {
  statement {
    sid    = "AllowCurrentAccountQueueAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "sqs:SendMessage",
      "sqs:ReceiveMessage",
      "sqs:DeleteMessage",
      "sqs:GetQueueAttributes",
    ]

    resources = [aws_sqs_queue.notification_queue.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:PrincipalAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_sqs_queue_policy" "notification_queue" {
  queue_url = aws_sqs_queue.notification_queue.id
  policy    = data.aws_iam_policy_document.notification_queue.json
}

###############################################################################
# Outputs
###############################################################################

output "sqs_queue_id" {
  description = "The URL/ID of the notification SQS queue."
  value       = aws_sqs_queue.notification_queue.id
}

output "sqs_queue_url" {
  description = "The URL of the notification SQS queue."
  value       = aws_sqs_queue.notification_queue.url
}

output "sqs_queue_arn" {
  description = "The ARN of the notification SQS queue."
  value       = aws_sqs_queue.notification_queue.arn
}

output "kms_key_arn" {
  description = "The ARN of the customer managed KMS key used for queue encryption."
  value       = aws_kms_key.notification_queue.arn
}

output "kms_alias_name" {
  description = "The name of the KMS alias pointing at the notification queue key."
  value       = aws_kms_alias.notification_queue.name
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "backup_framework_name" {
  description = "Name and description applied to the AWS Backup framework."
  type        = string
  default     = "benchmark"
}

variable "backup_framework_tag_key" {
  description = "Tag key applied to the AWS Backup framework."
  type        = string
  default     = "BenchmarkTag"
}

resource "terraform_data" "benchmark" {}

resource "aws_backup_framework" "benchmark" {
  name        = var.backup_framework_name
  description = var.backup_framework_name

  control {
    name = "BACKUP_RESOURCES_PROTECTED_BY_BACKUP_PLAN"

    scope {
      compliance_resource_types = ["EBS"]
    }
  }

  tags = {
    (var.backup_framework_tag_key) = terraform_data.benchmark.id
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  key_description = "Symmetric KMS key for general-purpose encryption and decryption tasks"
  key_alias_name  = "alias/bar"

  account_root_arn = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"

  tags = {
    Name        = "bar"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

resource "aws_kms_key" "bar" {
  description             = local.key_description
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  deletion_window_in_days = 10

  # NOTE: Key rotation is explicitly disabled for testing purposes only.
  # This MUST be re-enabled (enable_key_rotation = true) before any production use.
  enable_key_rotation = false

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "bar" {
  name          = local.key_alias_name
  target_key_id = aws_kms_key.bar.key_id
}

resource "aws_kms_key_policy" "bar" {
  key_id = aws_kms_key.bar.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowAccountScopedKeyUsage"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:DescribeKey",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the new VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_type" {
  description = "EC2 instance type for the backend application servers"
  type        = string
  default     = "t3.micro"
}

variable "environment" {
  description = "Deployment environment name used for tagging"
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project name used as a prefix for resource names and tags"
  type        = string
  default     = "alb-two-tier"
}

variable "tags" {
  description = "Additional tags applied to every resource"
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags
  )

  public_subnet_cidrs  = [cidrsubnet(var.vpc_cidr, 8, 1), cidrsubnet(var.vpc_cidr, 8, 2)]
  private_subnet_cidrs = [cidrsubnet(var.vpc_cidr, 8, 11), cidrsubnet(var.vpc_cidr, 8, 12)]

  instance_user_data = <<-EOF
    #!/bin/bash
    set -euo pipefail
    dnf install -y httpd
    systemctl enable httpd
    systemctl start httpd
    echo "Hello from $(hostname)" > /var/www/html/index.html
  EOF
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[0]
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[1]
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-b"
    Tier = "public"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[0]
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[1]
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-b"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Application Load Balancer security group"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "alb"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "alb_ingress_http" {
  type              = "ingress"
  description       = "Allow inbound HTTP from any address"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "alb_ingress_https" {
  type              = "ingress"
  description       = "Allow inbound HTTPS from any address for the TLS redirect target"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group_rule" "alb_egress_vpc" {
  type              = "egress"
  description       = "Allow outbound traffic only within the VPC CIDR"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.alb.id
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Backend tier security group that only accepts HTTP from the ALB"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "allow_alb"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "allow_alb_ingress_http" {
  type                     = "ingress"
  description              = "Allow HTTP only from the ALB security group"
  from_port                = 80
  to_port                  = 80
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.alb.id
  security_group_id        = aws_security_group.allow_alb.id
}

resource "aws_security_group_rule" "allow_alb_egress_vpc" {
  type              = "egress"
  description       = "Allow outbound traffic only within the VPC CIDR"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.allow_alb.id
}

resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "${var.project}.internal"
    organization = var.project
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  private_key       = tls_private_key.alb.private_key_pem
  certificate_body  = tls_self_signed_cert.alb.cert_pem
  certificate_chain = tls_self_signed_cert.alb.cert_pem

  tags = merge(local.common_tags, {
    Name = "${var.project}-alb-cert"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb" "app" {
  name                       = "${var.project}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-alb"
  })
}

resource "aws_lb_target_group" "app" {
  name        = "${var.project}-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    path                = "/"
    protocol            = "HTTP"
    port                = "traffic-port"
    healthy_threshold   = 3
    unhealthy_threshold = 3
    timeout             = 5
    interval            = 30
    matcher             = "200"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-tg"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.app.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.app.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-https-listener"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.app.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-http-listener"
  })
}

resource "aws_instance" "app_a" {
  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private_a.id
  vpc_security_group_ids = [aws_security_group.allow_alb.id]
  user_data              = local.instance_user_data

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 30
    volume_type = "gp3"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-app-a"
    Tier = "backend"
  })
}

resource "aws_instance" "app_b" {
  ami                    = data.aws_ami.amazon_linux.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.private_b.id
  vpc_security_group_ids = [aws_security_group.allow_alb.id]
  user_data              = local.instance_user_data

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_size = 30
    volume_type = "gp3"
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-app-b"
    Tier = "backend"
  })
}

resource "aws_lb_target_group_attachment" "app_a" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.app_a.id
  port             = 80
}

resource "aws_lb_target_group_attachment" "app_b" {
  target_group_arn = aws_lb_target_group.app.arn
  target_id        = aws_instance.app_b.id
  port             = 80
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "lambda-efs"

  azs      = slice(data.aws_availability_zones.available.names, 0, 2)
  efs_port = 2049

  # Interface VPC endpoints required by the Lambda runtime (no public egress).
  interface_endpoints = toset([
    "logs",
    "secretsmanager",
    "sts",
    "monitoring",
  ])

  common_tags = {
    Project     = "lambda-efs-vpc"
    Environment = "production"
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_security_group" "lambda" {
  name        = "${local.name_prefix}-lambda-eni"
  description = "Security group for Lambda VPC ENIs"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-lambda-eni"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "efs" {
  name        = "${local.name_prefix}-efs"
  description = "Security group for the EFS mount targets"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "vpc_endpoints" {
  name        = "${local.name_prefix}-vpc-endpoints"
  description = "Security group for the interface VPC endpoints used by the Lambda function"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc-endpoints"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "lambda_to_efs_nfs" {
  type                     = "egress"
  description              = "NFS traffic from the Lambda ENIs to the EFS mount targets"
  from_port                = local.efs_port
  to_port                  = local.efs_port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.lambda.id
  source_security_group_id = aws_security_group.efs.id
}

resource "aws_security_group_rule" "efs_from_lambda_nfs" {
  type                     = "ingress"
  description              = "NFS traffic from the Lambda ENI security group"
  from_port                = local.efs_port
  to_port                  = local.efs_port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.efs.id
  source_security_group_id = aws_security_group.lambda.id
}

resource "aws_security_group_rule" "lambda_to_endpoints_https" {
  type                     = "egress"
  description              = "HTTPS traffic from the Lambda ENIs to the interface VPC endpoints"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.lambda.id
  source_security_group_id = aws_security_group.vpc_endpoints.id
}

resource "aws_security_group_rule" "endpoints_from_lambda_https" {
  type                     = "ingress"
  description              = "HTTPS traffic from the Lambda ENI security group to the interface VPC endpoints"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.vpc_endpoints.id
  source_security_group_id = aws_security_group.lambda.id
}

resource "aws_vpc_endpoint" "interface" {
  for_each = local.interface_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true

  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_endpoints.id]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-endpoint-${each.value}"
  })
}

resource "aws_efs_file_system" "main" {
  creation_token   = "${local.name_prefix}-efs"
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "main" {
  count = length(aws_subnet.private)

  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "lambda" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/lambda"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "0755"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-access-point"
  })
}

resource "aws_iam_role" "lambda_exec" {
  name        = "${local.name_prefix}-lambda-exec-role"
  description = "Execution role for the VPC-attached Lambda function that mounts EFS"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "LambdaAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-lambda-exec-role"
  })
}

resource "aws_iam_role_policy_attachment" "lambda_vpc_access" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaVPCAccessExecutionRole"
}

resource "aws_iam_role_policy_attachment" "lambda_efs_client" {
  role       = aws_iam_role.lambda_exec.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonElasticFileSystemClientFullAccess"
}

resource "aws_iam_role_policy" "lambda_exec_logging" {
  name = "${local.name_prefix}-lambda-logging"
  role = aws_iam_role.lambda_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogsWrite"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/*"
        ]
      }
    ]
  })
}

output "lambda_execution_role_arn" {
  description = "ARN of the Lambda execution role"
  value       = aws_iam_role.lambda_exec.arn
}

output "lambda_execution_role_name" {
  description = "Name of the Lambda execution role"
  value       = aws_iam_role.lambda_exec.name
}

output "efs_file_system_id" {
  description = "ID of the EFS file system"
  value       = aws_efs_file_system.main.id
}

output "efs_file_system_arn" {
  description = "ARN of the EFS file system"
  value       = aws_efs_file_system.main.arn
}

output "efs_access_point_id" {
  description = "ID of the EFS access point the Lambda function mounts"
  value       = aws_efs_access_point.lambda.id
}

output "efs_access_point_arn" {
  description = "ARN of the EFS access point"
  value       = aws_efs_access_point.lambda.arn
}

output "efs_mount_target_ids" {
  description = "IDs of the EFS mount targets"
  value       = aws_efs_mount_target.main[*].id
}

output "vpc_id" {
  description = "ID of the VPC hosting the Lambda function and EFS"
  value       = aws_vpc.main.id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets for the Lambda VPC configuration"
  value       = aws_subnet.private[*].id
}

output "lambda_security_group_id" {
  description = "ID of the security group attached to the Lambda ENIs"
  value       = aws_security_group.lambda.id
}

output "efs_security_group_id" {
  description = "ID of the security group attached to the EFS mount targets"
  value       = aws_security_group.efs.id
}

output "vpc_endpoint_security_group_id" {
  description = "ID of the security group attached to the interface VPC endpoints"
  value       = aws_security_group.vpc_endpoints.id
}

output "interface_vpc_endpoint_ids" {
  description = "Map of interface VPC endpoint service names to endpoint IDs"
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.id }
}

output "interface_vpc_endpoint_dns_entries" {
  description = "Map of interface VPC endpoint service names to their DNS entries"
  value       = { for k, v in aws_vpc_endpoint.interface : k => v.dns_entry }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "public-networking"
}

variable "environment" {
  description = "Deployment environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "instance_id" {
  description = "Caller-supplied EC2 instance ID to associate the Elastic IP with. Public IP assignment is opt-in per instance through this variable; it is deliberately NOT enabled as a subnet-wide default (map_public_ip_on_launch is false). Leave empty to create the Elastic IP without an association."
  type        = string
  default     = ""
}

locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = {
    Project     = var.project
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "public" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })

  depends_on = [aws_internet_gateway.igw]
}

resource "aws_eip_association" "public" {
  count = var.instance_id != "" ? 1 : 0

  instance_id   = var.instance_id
  allocation_id = aws_eip.public.id
}

output "vpc_id" {
  description = "ID of the VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.igw.id
}

output "route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "elastic_ip" {
  description = "Public address of the Elastic IP."
  value       = aws_eip.public.public_ip
}

output "elastic_ip_allocation_id" {
  description = "Allocation ID of the Elastic IP."
  value       = aws_eip.public.id
}

output "elastic_ip_association_id" {
  description = "ID of the Elastic IP association when an instance ID is supplied, otherwise null."
  value       = try(aws_eip_association.public[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project_name" {
  description = "Name of the project used as a prefix for resource naming."
  type        = string
  default     = "networking-test"
}

variable "environment" {
  description = "Deployment environment identifier applied to all resource tags."
  type        = string
  default     = "test"

  validation {
    condition     = can(regex("^[a-z0-9-]{1,20}$", var.environment))
    error_message = "The environment value must be 1-20 characters of lowercase letters, digits, or hyphens."
  }
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  vpc_name            = "${var.project_name}-${var.environment}-vpc"
  public_subnet_name  = "${var.project_name}-${var.environment}-public-subnet"
  private_subnet_name = "${var.project_name}-${var.environment}-private-subnet"
  igw_name            = "${var.project_name}-${var.environment}-igw"
  public_rt_name      = "${var.project_name}-${var.environment}-public-rt"
  private_rt_name     = "${var.project_name}-${var.environment}-private-rt"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_vpc_ipv6_cidr_block_association" "main" {
  vpc_id                           = aws_vpc.main.id
  assign_generated_ipv6_cidr_block = true

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = "10.0.1.0/24"
  availability_zone               = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = true
  ipv6_cidr_block                 = cidrsubnet(aws_vpc_ipv6_cidr_block_association.main.ipv6_cidr_block, 8, 0)

  tags = merge(local.common_tags, {
    Name = local.public_subnet_name
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = local.private_subnet_name
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = local.igw_name
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = local.public_rt_name
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = local.private_rt_name
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id        = data.aws_caller_identity.current.account_id
  bucket_suffixes_map = {
    bucket101 = "bucket101"
    bucket102 = "bucket102"
    bucket103 = "bucket103"
    bucket104 = "bucket104"
  }
}

resource "aws_kms_key" "shared" {
  description             = "Shared KMS key for S3 bucket SSE-KMS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_s3_bucket" "standalone" {
  bucket_prefix = "${local.account_id}-bucket2-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "standalone" {
  bucket = aws_s3_bucket.standalone.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.shared.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket" "count_based" {
  count         = 2
  bucket_prefix = "${local.account_id}-bucket${count.index + 3}-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "count_based" {
  count  = 2
  bucket = aws_s3_bucket.count_based[count.index].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "count_based" {
  count  = 2
  bucket = aws_s3_bucket.count_based[count.index].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.shared.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket" "map_based" {
  for_each      = local.bucket_suffixes_map
  bucket_prefix = "${local.account_id}-${each.key}-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "map_based" {
  for_each = local.bucket_suffixes_map
  bucket   = aws_s3_bucket.map_based[each.key].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "map_based" {
  for_each = local.bucket_suffixes_map
  bucket   = aws_s3_bucket.map_based[each.key].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.shared.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  budget_name        = "budget"
  sns_topic_name     = "budget"
  budget_limit       = "25.0"
  budget_limit_unit  = "USD"
  notification_email = "hello@chriswilding.co.uk"
  sms_endpoint       = "+447828835419"
  budgets_service    = "budgets.amazonaws.com"
  sns_service        = "sns.amazonaws.com"
  account_id         = data.aws_caller_identity.current.account_id
  partition          = data.aws_partition.current.partition
  account_root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"
}

# -----------------------------------------------------------------------------
# Customer-managed KMS key used to encrypt the SNS topic
# -----------------------------------------------------------------------------

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountFullAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowBudgetsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.budgets_service]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowSnsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.sns_service]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "sns_budget" {
  description             = "Customer managed KMS key used to encrypt the ${local.sns_topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "sns_budget" {
  key_id = aws_kms_key.sns_budget.id
  policy = data.aws_iam_policy_document.kms.json
}

# -----------------------------------------------------------------------------
# SNS topic, topic policy and subscriptions
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "budget" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns_budget.arn

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowBudgetsPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.budgets_service]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.budget.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowOwnerAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "SNS:AddPermission",
      "SNS:DeleteTopic",
      "SNS:GetTopicAttributes",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
      "SNS:RemovePermission",
      "SNS:SetTopicAttributes",
      "SNS:Subscribe",
    ]

    resources = [aws_sns_topic.budget.arn]
  }
}

resource "aws_sns_topic_policy" "budget" {
  arn    = aws_sns_topic.budget.arn
  policy = data.aws_iam_policy_document.sns.json
}

resource "aws_sns_topic_subscription" "sms" {
  topic_arn = aws_sns_topic.budget.arn
  protocol  = "sms"
  endpoint  = local.sms_endpoint
}

# -----------------------------------------------------------------------------
# Monthly cost budget with notification
# -----------------------------------------------------------------------------

resource "aws_budgets_budget" "budget" {
  name              = local.budget_name
  budget_type       = "COST"
  limit_amount      = local.budget_limit
  limit_unit        = local.budget_limit_unit
  time_unit         = "MONTHLY"
  time_period_start = "2021-07-01_00:00"

  notification {
    comparison_operator        = "GREATER_THAN"
    threshold                  = 100
    threshold_type             = "PERCENTAGE"
    notification_type          = "ACTUAL"
    subscriber_email_addresses = [local.notification_email]
    subscriber_sns_topic_arns  = [aws_sns_topic.budget.arn]
  }

  depends_on = [
    aws_sns_topic_policy.budget,
    aws_kms_key_policy.sns_budget,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  ecr_repository_name = "reactjs-app-repo"
  ecs_task_role_name  = "ecsTaskExecutionRole"

  ecs_task_execution_policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"

  ecr_untagged_image_expiration_days = 14
  ecr_max_tagged_image_count         = 30
}

resource "aws_ecr_repository" "reactjs_app_repo" {
  name                 = local.ecr_repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "reactjs_app_repo" {
  repository = aws_ecr_repository.reactjs_app_repo.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after ${local.ecr_untagged_image_expiration_days} days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = local.ecr_untagged_image_expiration_days
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Retain only the most recent ${local.ecr_max_tagged_image_count} tagged images"
        selection = {
          tagStatus     = "tagged"
          tagPatternList = ["*"]
          countType     = "imageCountMoreThan"
          countNumber   = local.ecr_max_tagged_image_count
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

data "aws_iam_policy_document" "ecs_task_assume_role" {
  statement {
    sid     = "ECSTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution_role" {
  name               = local.ecs_task_role_name
  description        = "Allows ECS tasks to call AWS APIs on your behalf for container image pulls and log delivery."
  assume_role_policy = data.aws_iam_policy_document.ecs_task_assume_role.json
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution_role" {
  role       = aws_iam_role.ecs_task_execution_role.name
  policy_arn = local.ecs_task_execution_policy_arn
}

output "ecr_repository_url" {
  description = "URL of the ECR repository used to store React application container images."
  value       = aws_ecr_repository.reactjs_app_repo.repository_url
}

output "ecr_repository_arn" {
  description = "ARN of the ECR repository used to store React application container images."
  value       = aws_ecr_repository.reactjs_app_repo.arn
}

output "ecs_task_execution_role_arn" {
  description = "ARN of the ECS task execution IAM role."
  value       = aws_iam_role.ecs_task_execution_role.arn
}

# ---------------------------------------------------------------------------
# TEST-ONLY IAM configuration.
#
# The IAM role and its two inline policies below are intentionally permissive
# and are meant for testing / demonstration purposes ONLY. They deviate from
# least-privilege on purpose (broad iam:PassRole and lambda:* style grants on
# "*") and MUST NOT be deployed into a production account as-is.
# ---------------------------------------------------------------------------

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  role_name = "role"

  common_tags = {
    Name        = local.role_name
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

# Trust policy: allow the EC2 service to assume the role.
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "test_role" {
  name = local.role_name

  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  # Test-only role: no permissions boundary and intentionally permissive
  # inline policies are attached below.
  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Inline policy 1: allow passing IAM roles across all resources.
#
# WARNING: iam:PassRole on "*" is an intentionally broad test-only privilege
# escalation risk. A principal with this permission can hand any role in the
# account to services it already has access to.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "allow_policy_1" {
  statement {
    sid     = "AllowPassRoleAllResources"
    effect  = "Allow"
    actions = ["iam:PassRole"]

    # Intentionally broad (test-only).
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_1" {
  name = "allow-policy-1"
  role = aws_iam_role.test_role.name

  policy = data.aws_iam_policy_document.allow_policy_1.json
}

# ---------------------------------------------------------------------------
# Inline policy 2: allow creating and invoking Lambda functions.
#
# WARNING: This is an intentionally permissive test-only grant. Both the
# create and the invocation actions are scoped to "*" resources.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "allow_policy_2" {
  statement {
    sid    = "AllowCreateAndInvokeLambda"
    effect = "Allow"

    actions = [
      "lambda:CreateFunction",
      # Requested pattern "lambda:invokefunc*" (case-insensitive in IAM).
      "lambda:InvokeFunc*",
    ]

    # Intentionally broad (test-only).
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "allow_policy_2" {
  name = "allow-policy-2"
  role = aws_iam_role.test_role.name

  policy = data.aws_iam_policy_document.allow_policy_2.json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # NOTE: No `backend` block is declared here; remote state/backend
  # configuration is managed externally by the deployment harness.
}

# NOTE: No `provider` block is declared here; the AWS provider configuration
# (region, credentials, default tags) is injected by the deployment harness.

###############################################################################
# Variables (all defaulted so `terraform apply` runs unattended)
###############################################################################

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "test"
}

variable "project" {
  description = "Project / application name used for tagging."
  type        = string
  default     = "efs-not-secure"
}

variable "owner" {
  description = "Team or individual responsible for this test resource."
  type        = string
  default     = "platform-testing"
}

variable "additional_tags" {
  description = "Optional extra tags merged onto every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  # Deterministic labels kept identical to the requested insecure naming so the
  # posture is self-evident in the console, CLI output and audit findings.
  file_system_name = "efs-not-secure"
  name_tag         = "NotSecure"

  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      Owner       = var.owner
      ManagedBy   = "terraform"
    },
    var.additional_tags,
  )
}

###############################################################################
# EFS file system
#
# INTENTIONALLY INSECURE FILE SYSTEM POLICY (see aws_efs_file_system_policy
# below). The file system itself is encrypted at rest with the AWS-managed
# `aws/elasticfilesystem` KMS key. Its `Name` tag and `creation_token` retain
# the explicit "NotSecure" / "efs-not-secure" naming on purpose so that the
# intentionally permissive access policy can never be mistaken for a hardened
# production configuration.
###############################################################################

resource "aws_efs_file_system" "not_secure" {
  creation_token = "efs-not-secure"

  encrypted = true

  tags = merge(
    local.common_tags,
    {
      Name = local.name_tag
    },
  )

  # EFS holds persistent file data: guard against accidental `terraform destroy`
  # or resource replacement (e.g. a change to an immutable argument).
  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# EFS file system policy
#
# !! OBJECTIVE NOTE / WARNING !!
# This resource policy is DELIBERATELY PERMISSIVE and exists strictly to
# exercise and validate EFS access-policy behaviour in a disposable test
# account. It grants every Elastic File System action to *every* AWS principal
# (Principal: "*" combined with `elasticfilesystem:*`).
#
# This is a classic anonymous/over-broad access anti-pattern. It MUST NOT be
# promoted, copied or templated into any non-test (staging/production) account
# or environment. The resource is still scoped to the file system ARN below
# (never "*") to avoid the doubly-wildcard (`Action: "*"` + `Resource: "*"`)
# anti-pattern.
###############################################################################

resource "aws_efs_file_system_policy" "not_secure" {
  file_system_id = aws_efs_file_system.not_secure.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "ExamplePolicy01"
    Statement = [
      {
        Sid       = "ExampleStatement01"
        Effect    = "Allow"
        Principal = "*"
        Action    = "elasticfilesystem:*"
        Resource  = aws_efs_file_system.not_secure.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # NOTE: The AWS provider block (region = "us-east-1") and the backend
  # configuration are injected/managed externally by the deployment harness.
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  state_bucket_name = "terraform-remote-state-storage-s3-kjg"
  lock_table_name   = "terraform-state-lock-dynamo"

  common_tags = {
    ManagedBy   = "Terraform"
    Purpose     = "TerraformRemoteState"
    Environment = "shared"
  }
}

###############################################################################
# KMS key (customer managed) for state encryption at rest
###############################################################################

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed KMS key used to encrypt Terraform remote state stored in Amazon S3 and DynamoDB state locking"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowKeyAdministrationByAccountRoot"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowKeyUsageByAccountRoot"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUsageOfKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "terraform-remote-state-kms"
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/terraform-remote-state-s3-kjg"
  target_key_id = aws_kms_key.terraform_state.key_id
}

###############################################################################
# S3 bucket holding Terraform remote state
###############################################################################

resource "aws_s3_bucket" "remote_state" {
  bucket = local.state_bucket_name

  tags = merge(local.common_tags, {
    Name = local.state_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "remote_state" {
  bucket = aws_s3_bucket.remote_state.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonTLSRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.remote_state.arn,
          "${aws_s3_bucket.remote_state.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# DynamoDB table used for Terraform state locking
###############################################################################

resource "aws_dynamodb_table" "terraform_state_lock" {
  name         = local.lock_table_name
  billing_mode = "PROVISIONED"
  hash_key     = "LockID"

  read_capacity  = 20
  write_capacity = 20

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.terraform_state.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name = local.lock_table_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs — copy these directly into the backend block of other configurations
###############################################################################

output "state_bucket_name" {
  description = "Name of the S3 bucket storing Terraform remote state (backend \"bucket\")."
  value       = aws_s3_bucket.remote_state.bucket
}

output "state_bucket_arn" {
  description = "ARN of the S3 bucket storing Terraform remote state."
  value       = aws_s3_bucket.remote_state.arn
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for state encryption."
  value       = aws_kms_key.terraform_state.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key used for state encryption."
  value       = aws_kms_alias.terraform_state.name
}

output "dynamodb_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking (backend \"dynamodb_table\")."
  value       = aws_dynamodb_table.terraform_state_lock.name
}

output "backend_configuration" {
  description = "Suggested S3 backend configuration values (region must match the provider region)."
  value = {
    bucket         = aws_s3_bucket.remote_state.bucket
    key            = "terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = aws_dynamodb_table.terraform_state_lock.name
    encrypt        = true
    kms_key_id     = aws_kms_key.terraform_state.arn
  }
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

variable "environment" {
  description = "Environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
  prefix    = "log-group"
}

resource "aws_kms_key" "logs" {
  description             = "Customer-managed KMS key for CloudWatch Logs encryption."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "cloudwatch-logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${random_pet.log_group_suffix.id}"
  target_key_id = aws_kms_key.logs.key_id
}

resource "aws_kms_key_policy" "logs" {
  key_id = aws_kms_key.logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = aws_kms_key.logs.arn
      },
      {
        Sid    = "AllowCloudWatchLogsUse"
        Effect = "Allow"
        Principal = {
          Service = "logs.us-east-1.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = aws_kms_key.logs.arn
      }
    ]
  })
}

# 30-day retention balances operational visibility with storage cost.
resource "aws_cloudwatch_log_group" "app" {
  # random_pet already includes the "log-group" prefix, so its id resolves to
  # the required "log-group-<two-word-pet-name>" format without duplicating the prefix.
  name              = random_pet.log_group_suffix.id
  retention_in_days = 30
  kms_key_id        = aws_kms_key.logs.arn

  tags = merge(local.common_tags, {
    Name = random_pet.log_group_suffix.id
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "log_group_name" {
  description = "Resolved name of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.app.name
}

output "log_group_arn" {
  description = "ARN of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.app.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  project     = "Website CV"
  environment = "production"

  delegation_set_ssm_parameter_name = "/WebsiteCv/production/Route53/DelegationSetId"

  common_tags = {
    Project     = local.project
    Environment = local.environment
  }
}

resource "aws_route53_delegation_set" "main" {
  reference_name = "WebsiteDNS"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "delegation_set_id" {
  name  = local.delegation_set_ssm_parameter_name
  type  = "String"
  value = aws_route53_delegation_set.main.id

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Base name of the S3 bucket used for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value applied to the Name tag on all created resources."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Whether to delete all objects from the bucket so the bucket can be destroyed."
  type        = bool
  default     = true
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # S3 bucket names are globally unique across all AWS accounts, so the
  # caller account ID is appended to guarantee the name is not already taken.
  bucket_name = "${var.bucket_name}-${data.aws_caller_identity.current.account_id}"

  common_tags = {
    Name = var.name_tag
  }

  kms_key_description = "Customer managed KMS key for SSE-KMS encryption of the ${local.bucket_name} S3 bucket"
}

###############################################################################
# KMS key (customer managed, rotation enabled)
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowAccountKeyAdministrationAndUse"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "benchmark" {
  description             = local.kms_key_description
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# S3 bucket for benchmarking
###############################################################################

resource "aws_s3_bucket" "benchmark" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.benchmark.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Account-level S3 public access block (explicitly disabled)
###############################################################################

resource "aws_s3_account_public_access_block" "account" {
  account_id = data.aws_caller_identity.current.account_id

  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "bucket_name" {
  type        = string
  default     = "benchmark"
  description = "Base name used to construct the CloudTrail log bucket name."
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name      = "${var.bucket_name}-cloudtrail-${data.aws_region.current.name}"
  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "cloudtrail_logs" {
  description             = "Customer managed KMS key for CloudTrail log encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudtrail_logs_kms.json
}

data "aws_iam_policy_document" "cloudtrail_logs_kms" {
  statement {
    sid    = "EnableRootAccountFullAdminAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Sign",
      "kms:Verify",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailEncryptDecrypt"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_alias" "cloudtrail_logs" {
  name          = "alias/${var.bucket_name}-cloudtrail-logs"
  target_key_id = aws_kms_key.cloudtrail_logs.key_id
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail_logs.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_logs_bucket.json
}

data "aws_iam_policy_document" "cloudtrail_logs_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      App    = var.app_name
      Module = var.module
      Stage  = var.stage
    }
  }
}

variable "app_name" {
  description = "Human-readable application name used for default tagging."
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier used to build log group names."
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module identifier used to build log group names."
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment stage/environment used to build log group names."
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "CloudWatch Logs retention period, in days, for both log groups."
  type        = number
  default     = 120

  validation {
    condition = contains([
      1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545,
      731, 1096, 1827, 2192, 2557, 2922, 3288, 3653, 0
    ], var.log_retention)
    error_message = "log_retention must be a supported CloudWatch Logs retention value: 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653, or 0 (never expire)."
  }
}

locals {
  log_group_prefix = "cwlg-${var.app}-${var.module}-${var.stage}"
}

resource "aws_cloudwatch_log_group" "app" {
  name              = "${local.log_group_prefix}-app"
  retention_in_days = var.log_retention

  tags = {
    Name = "${local.log_group_prefix}-app"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = "${local.log_group_prefix}-proxy"
  retention_in_days = var.log_retention

  tags = {
    Name = "${local.log_group_prefix}-proxy"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  project_name = "cloudrail-test-encryption"

  vpc_cidr      = "10.0.0.0/16"
  subnet_a_cidr = "10.0.1.0/24"
  subnet_b_cidr = "10.0.2.0/24"

  # Restricted client CIDR for the test workload ingress (no 0.0.0.0/0 ingress)
  allowed_ingress_cidrs = ["10.0.0.0/16"]

  efs_creation_token = "cloudrail-test"
  efs_root_directory = "/opt/data"
  efs_nfs_port       = 2049
  efs_tls_port       = 2999

  task_family    = "cloudrail-test-encryption"
  log_group_name = "/ecs/cloudrail-test-encryption"
  volume_name    = "service-storage"
}

# ---------------------------------------------------------------------------
# Network
# ---------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name    = "${local.project_name}-vpc"
    Project = local.project_name
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${local.project_name}-subnet-a"
    Project = local.project_name
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name    = "${local.project_name}-subnet-b"
    Project = local.project_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "${local.project_name}-igw"
    Project = local.project_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "${local.project_name}-public-rt"
    Project = local.project_name
  }
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# ---------------------------------------------------------------------------
# Security groups
# ---------------------------------------------------------------------------

resource "aws_security_group" "ecs_tasks" {
  name        = "${local.project_name}-ecs-tasks"
  description = "Ingress for containerized test workloads (HTTP/HTTPS only)"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from restricted CIDRs"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = local.allowed_ingress_cidrs
  }

  ingress {
    description = "HTTPS from restricted CIDRs"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = local.allowed_ingress_cidrs
  }

  egress {
    description = "Allow egress within the VPC to reach EFS mount targets"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name    = "${local.project_name}-ecs-tasks"
    Project = local.project_name
  }
}

resource "aws_security_group" "efs" {
  name        = "${local.project_name}-efs"
  description = "Allow NFS and EFS TLS traffic from ECS tasks only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "NFS from ECS tasks"
    from_port       = local.efs_nfs_port
    to_port         = local.efs_nfs_port
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  ingress {
    description     = "EFS in-transit encryption from ECS tasks"
    from_port       = local.efs_tls_port
    to_port         = local.efs_tls_port
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    description = "Allow egress within the VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name    = "${local.project_name}-efs"
    Project = local.project_name
  }
}

# ---------------------------------------------------------------------------
# EFS
# ---------------------------------------------------------------------------

resource "aws_efs_file_system" "main" {
  creation_token = local.efs_creation_token
  encrypted      = true

  tags = {
    Name    = "${local.project_name}-efs"
    Project = local.project_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "public_a" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public_a.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_mount_target" "public_b" {
  file_system_id  = aws_efs_file_system.main.id
  subnet_id       = aws_subnet.public_b.id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_file_system_policy" "main" {
  file_system_id = aws_efs_file_system.main.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.project_name}-efs-policy"
    Statement = [
      {
        Sid       = "DenyNonTLS"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "elasticfilesystem:*"
        Resource  = aws_efs_file_system.main.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
      {
        Sid       = "AllowEncryptedClientMount"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.main.arn
      }
    ]
  })
}

resource "aws_efs_access_point" "data" {
  file_system_id = aws_efs_file_system.main.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = local.efs_root_directory

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "0755"
    }
  }

  tags = {
    Name    = "${local.project_name}-access-point"
    Project = local.project_name
  }
}

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "main" {
  name              = local.log_group_name
  retention_in_days = 30

  tags = {
    Name    = "${local.project_name}-logs"
    Project = local.project_name
  }
}

# ---------------------------------------------------------------------------
# IAM
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_task_execution" {
  name               = "${local.project_name}-ecs-task-execution"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name    = "${local.project_name}-ecs-task-execution"
    Project = local.project_name
  }
}

resource "aws_iam_role_policy_attachment" "ecs_task_execution" {
  role       = aws_iam_role.ecs_task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.project_name}-ecs-task"
  assume_role_policy = data.aws_iam_policy_document.ecs_tasks_assume_role.json

  tags = {
    Name    = "${local.project_name}-ecs-task"
    Project = local.project_name
  }
}

data "aws_iam_policy_document" "ecs_task_efs" {
  statement {
    sid    = "EfsClientMountOnly"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess"
    ]

    resources = [
      aws_efs_file_system.main.arn,
      aws_efs_access_point.data.arn
    ]
  }
}

resource "aws_iam_role_policy" "ecs_task_efs" {
  name   = "${local.project_name}-efs-client-mount"
  role   = aws_iam_role.ecs_task.id
  policy = data.aws_iam_policy_document.ecs_task_efs.json
}

# ---------------------------------------------------------------------------
# ECS
# ---------------------------------------------------------------------------

resource "aws_ecs_cluster" "main" {
  name = local.task_family

  tags = {
    Name    = local.task_family
    Project = local.project_name
  }
}

resource "aws_ecs_task_definition" "main" {
  family                   = local.task_family
  network_mode             = "bridge"
  requires_compatibilities = ["EC2"]
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true

      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = local.volume_name
          containerPath = local.efs_root_directory
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "first"
        }
      }
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true

      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
          protocol      = "tcp"
        }
      ]

      mountPoints = [
        {
          sourceVolume  = local.volume_name
          containerPath = local.efs_root_directory
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.main.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "second"
        }
      }
    }
  ])

  volume {
    name = local.volume_name

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.main.id
      root_directory          = local.efs_root_directory
      transit_encryption      = "ENABLED"
      transit_encryption_port = local.efs_tls_port
    }
  }

  tags = {
    Name    = local.task_family
    Project = local.project_name
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  shared_tags = {
    Application = "saints-xctf"
    Environment = "all"
  }
}

resource "aws_ecr_repository" "saints_xctf_api_flask" {
  name                 = "saints-xctf-api-flask"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = merge(local.shared_tags, {
    Name = "saints-xctf-api-flask-container-repository"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_repository" "saints_xctf_api_nginx" {
  name                 = "saints-xctf-api-nginx"
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = merge(local.shared_tags, {
    Name = "saints-xctf-api-nginx-container-repository"
  })

  lifecycle {
    prevent_destroy = true
  }
}

output "saints_xctf_api_flask_repository_url" {
  description = "URL of the SaintsXCTF API Flask ECR repository"
  value       = aws_ecr_repository.saints_xctf_api_flask.repository_url
}

output "saints_xctf_api_nginx_repository_url" {
  description = "URL of the SaintsXCTF API Nginx ECR repository"
  value       = aws_ecr_repository.saints_xctf_api_nginx.repository_url
}

output "saints_xctf_api_flask_repository_arn" {
  description = "ARN of the SaintsXCTF API Flask ECR repository"
  value       = aws_ecr_repository.saints_xctf_api_flask.arn
}

output "saints_xctf_api_nginx_repository_arn" {
  description = "ARN of the SaintsXCTF API Nginx ECR repository"
  value       = aws_ecr_repository.saints_xctf_api_nginx.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "key_prefix" {
  description = "Prefix used to construct the AWS key pair name."
  type        = string
  default     = "key"
}

resource "random_pet" "key_suffix" {
  length = 2
}

resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_key_pair" "ssh" {
  key_name   = "${var.key_prefix}-${random_pet.key_suffix.id}"
  public_key = tls_private_key.ssh.public_key_openssh

  provisioner "local-exec" {
    command = <<-EOT
      set -e
      umask 077
      printf '%s' "${tls_private_key.ssh.private_key_pem}" > "../${self.key_name}.pem"
      chmod 600 "../${self.key_name}.pem"
    EOT
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project     = "web-services"
  environment = "prod"
  vpc_cidr    = "10.0.0.0/16"

  public_subnet_cidrs = ["10.0.1.0/24", "10.0.2.0/24"]

  common_tags = {
    Project     = local.project
    Environment = local.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "example" {
  name        = "Example security group"
  description = "Security group for the web services tier (public HTTP/HTTPS ingress)"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "Example security group"
  })
}

resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.example.id
  description       = "Allow public HTTPS access on TCP port 443"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-ingress-https"
  })
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.example.id
  description       = "Allow public HTTP access on TCP port 80"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-ingress-http"
  })
}

resource "aws_vpc_security_group_egress_rule" "https_outbound" {
  security_group_id = aws_security_group.example.id
  description       = "Allow outbound HTTPS traffic restricted to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 443
  to_port           = 443

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-egress-https"
  })
}

resource "aws_vpc_security_group_egress_rule" "http_outbound" {
  security_group_id = aws_security_group.example.id
  description       = "Allow outbound HTTP traffic restricted to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "tcp"
  from_port         = 80
  to_port           = 80

  tags = merge(local.common_tags, {
    Name = "${local.project}-${local.environment}-egress-http"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  environment = "test"
  project     = "public-networking"

  common_tags = {
    Name        = "${local.project}-${local.environment}"
    Environment = local.environment
    Project     = local.project
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.project}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-subnet"
    Tier = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "example" {
  name        = "example"
  description = "Example security group"
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "example"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "ssh_ingress" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.example.id
  description       = "Allow SSH from within the VPC CIDR block"
}

resource "aws_security_group_rule" "vpc_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.example.id
  description       = "Allow outbound traffic within the VPC CIDR block only"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "repository_name" {
  description = "Name of the Amazon ECR repository used to store container images."
  type        = string
  default     = "illumidesk"
}

variable "tags" {
  description = "Map of tags to apply to the ECR repository and related resources."
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

locals {
  repository_name = var.repository_name

  lifecycle_policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire images when count exceeds 30"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

resource "aws_ecr_repository" "main" {
  name                 = local.repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "main" {
  repository = aws_ecr_repository.main.name
  policy     = local.lifecycle_policy
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region used by the provider and recorded in the secret payload."
  type        = string
  default     = "us-east-1"
}

variable "default_tags" {
  description = "Additional tags merged into every taggable resource created by this configuration."
  type        = map(string)
  default     = {}
}

variable "secret_name" {
  description = "Name of the Secrets Manager secret holding the Cognito bootstrap credentials."
  type        = string
  default     = "lambda-auth-credentials"
}

# NOTE: the three variables below are THROWAWAY bootstrap credentials for the
# seeded client user. They are only used to build the generated secret payload,
# must never be printed by outputs, and must be rotated (or replaced with values
# supplied from a secure source) before any real traffic uses them.
variable "default_username" {
  description = "Bootstrap username embedded in the secret payload. Throwaway value - rotate after first use."
  type        = string
  default     = "techlanches"
  sensitive   = true
}

variable "default_email" {
  description = "Bootstrap e-mail embedded in the secret payload. Throwaway value - rotate after first use."
  type        = string
  default     = "g12.4soat.fiap@outlook.com"
  sensitive   = true
}

variable "default_password" {
  description = "Bootstrap password embedded in the secret payload. Throwaway value - rotate after first use."
  type        = string
  default     = "Test1234@"
  sensitive   = true
}

locals {
  common_tags = merge(var.default_tags, {
    Name = "tech_lanches_clientes_pool"
  })

  secret_tags = merge(var.default_tags, {
    Name = "lambda-auth-credentials"
  })
}

resource "aws_cognito_user_pool" "clientes_pool" {
  name = "tech-lanches-clientes-pool"

  mfa_configuration = "OFF"

  username_configuration {
    case_sensitive = false
  }

  auto_verified_attributes = ["email"]

  alias_attributes = ["email", "preferred_username"]

  tags = local.common_tags
}

# The Cognito user pool client schema in provider ~> 5.0 exposes no tags/tags_all
# attributes, so no tagging argument is set here.
resource "aws_cognito_user_pool_client" "pool_client" {
  name         = "pool-client"
  user_pool_id = aws_cognito_user_pool.clientes_pool.id

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
  ]
}

resource "aws_secretsmanager_secret" "lambda_auth_credentials" {
  name                    = var.secret_name
  recovery_window_in_days = 0

  tags = local.secret_tags
}

resource "aws_secretsmanager_secret_version" "lambda_auth_credentials" {
  secret_id = aws_secretsmanager_secret.lambda_auth_credentials.id

  secret_string = jsonencode({
    region       = var.aws_region
    user_pool_id = aws_cognito_user_pool.clientes_pool.id
    client_id    = aws_cognito_user_pool_client.pool_client.id
    username     = var.default_username
    email        = var.default_email
    password     = var.default_password
  })
}

# Least-privilege execution role for the consumer of the secret (e.g. the auth Lambda).
resource "aws_iam_role" "secret_consumer" {
  name = "lambda-auth-credentials-consumer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      },
    ]
  })

  tags = local.secret_tags
}

resource "aws_iam_policy" "secret_read" {
  name        = "lambda-auth-credentials-read"
  description = "Allows reading the Cognito bootstrap credentials secret only."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadCognitoBootstrapSecret"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret",
        ]
        Resource = aws_secretsmanager_secret.lambda_auth_credentials.arn
      },
    ]
  })

  tags = local.secret_tags
}

resource "aws_iam_role_policy_attachment" "secret_read" {
  role       = aws_iam_role.secret_consumer.name
  policy_arn = aws_iam_policy.secret_read.arn
}

output "user_pool_id" {
  description = "Identifier of the Cognito user pool."
  value       = aws_cognito_user_pool.clientes_pool.id
}

output "user_pool_client_id" {
  description = "Identifier of the Cognito user pool client."
  value       = aws_cognito_user_pool_client.pool_client.id
}

output "secret_arn" {
  description = "ARN of the Secrets Manager secret holding the bootstrap credentials."
  value       = aws_secretsmanager_secret.lambda_auth_credentials.arn
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "subnet_cidrs" {
  description = "List of CIDR blocks for the subnets. One subnet is created per entry."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "List of availability zones to spread subnets across. When empty, the first N availability zones of the region are used (N = number of subnet CIDRs)."
  type        = list(string)
  default     = []
}

locals {
  subnet_count = length(var.subnet_cidrs)

  az_count = local.subnet_count < length(data.aws_availability_zones.available.names) ? local.subnet_count : length(data.aws_availability_zones.available.names)

  default_azs = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  azs = length(var.availability_zones) > 0 ? var.availability_zones : local.default_azs
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count = local.subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.subnet_cidrs[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = {
    Name = "main-subnet-${count.index + 1}"
  }
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "IDs of the created subnets, in creation order."
  value       = aws_subnet.main[*].id
}

output "subnet_availability_zones" {
  description = "Availability zone of each created subnet, in creation order."
  value       = aws_subnet.main[*].availability_zone
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

locals {
  api_name             = "HelloWorldAPI"
  stage_name           = "dev"
  lambda_function_name = "HelloWorld"
}

data "archive_file" "lambda_package" {
  type        = "zip"
  output_path = "${path.module}/hello_world_lambda.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      exports.handler = async (event) => {
        return {
          statusCode: 200,
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: "Hello World" }),
        };
      };
    EOT
  }
}

resource "aws_iam_role" "lambda_execution" {
  name = "HelloWorldLambdaExecutionRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  role       = aws_iam_role.lambda_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "hello_world" {
  function_name    = local.lambda_function_name
  role             = aws_iam_role.lambda_execution.arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.lambda_package.output_path
  source_code_hash = data.archive_file.lambda_package.output_base64sha256

  depends_on = [
    aws_iam_role_policy_attachment.lambda_basic_execution,
  ]
}

resource "aws_api_gateway_rest_api" "hello_world_api" {
  name        = local.api_name
  description = "API Gateway for Hello World Lambda"
}

resource "aws_api_gateway_resource" "hello" {
  rest_api_id = aws_api_gateway_rest_api.hello_world_api.id
  parent_id   = aws_api_gateway_rest_api.hello_world_api.root_resource_id
  path_part   = "hello"
}

resource "aws_api_gateway_method" "hello_any" {
  rest_api_id      = aws_api_gateway_rest_api.hello_world_api.id
  resource_id      = aws_api_gateway_resource.hello.id
  http_method      = "ANY"
  authorization    = "NONE"
  api_key_required = false
}

resource "aws_api_gateway_integration" "hello_any" {
  rest_api_id             = aws_api_gateway_rest_api.hello_world_api.id
  resource_id             = aws_api_gateway_resource.hello.id
  http_method             = aws_api_gateway_method.hello_any.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.hello_world.invoke_arn
}

resource "aws_lambda_permission" "api_gateway_invoke" {
  statement_id  = "AllowExecutionFromAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.hello_world.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.hello_world_api.execution_arn}/*/*"
}

resource "aws_api_gateway_deployment" "hello_world" {
  rest_api_id = aws_api_gateway_rest_api.hello_world_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.hello.id,
      aws_api_gateway_method.hello_any.id,
      aws_api_gateway_integration.hello_any.id,
      aws_lambda_permission.api_gateway_invoke.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_method.hello_any,
    aws_api_gateway_integration.hello_any,
  ]
}

resource "aws_api_gateway_stage" "dev" {
  rest_api_id   = aws_api_gateway_rest_api.hello_world_api.id
  deployment_id = aws_api_gateway_deployment.hello_world.id
  stage_name    = local.stage_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_iam_policy_document" "sqs_kms" {
  statement {
    sid    = "EnableIAMPoliciesForAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = ["kms:*"]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSQSQueueEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

import {
  to = aws_sqs_queue.test_sqs
  id = "https://sqs.${data.aws_region.current.name}.${data.aws_partition.current.dns_suffix}/${data.aws_caller_identity.current.account_id}/test-sqs"
}

import {
  to = aws_sqs_queue.test_sqs1
  id = "https://sqs.${data.aws_region.current.name}.${data.aws_partition.current.dns_suffix}/${data.aws_caller_identity.current.account_id}/test-sqs1"
}

import {
  to = aws_kms_alias.sqs
  id = "alias/test-sqs-queues"
}

locals {
  environment = "production"

  common_tags = {
    Environment = local.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_kms_key" "sqs" {
  description             = "Customer managed KMS key used for server-side encryption of the test-sqs and test-sqs1 SQS queues"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sqs_kms.json

  tags = merge(local.common_tags, {
    Name = "test-sqs-queues"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sqs" {
  name          = "alias/test-sqs-queues"
  target_key_id = aws_kms_key.sqs.key_id
}

resource "aws_sqs_queue" "test_sqs" {
  name                              = "test-sqs"
  delay_seconds                     = 90
  max_message_size                  = 2048
  message_retention_seconds         = 86400
  receive_wait_time_seconds         = 10
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(local.common_tags, {
    Name = "test-sqs"
  })
}

resource "aws_sqs_queue" "test_sqs1" {
  name                              = "test-sqs1"
  delay_seconds                     = 90
  max_message_size                  = 2048
  message_retention_seconds         = 86400
  receive_wait_time_seconds         = 10
  kms_master_key_id                 = aws_kms_key.sqs.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(local.common_tags, {
    Name = "test-sqs1"
  })
}

resource "aws_sqs_queue_policy" "test_sqs" {
  queue_url = aws_sqs_queue.test_sqs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "sqs:*"
        Resource  = aws_sqs_queue.test_sqs.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

resource "aws_sqs_queue_policy" "test_sqs1" {
  queue_url = aws_sqs_queue.test_sqs1.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "sqs:*"
        Resource  = aws_sqs_queue.test_sqs1.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      },
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

###############################################################################
# Variables
###############################################################################

# Account-level default region for all resources in this configuration.
# The provider block itself is injected by the deployment harness and reads
# this default (us-east-1).
variable "aws_region" {
  description = "AWS region in which the document I/O resources are deployed."
  type        = string
  default     = "us-east-1"
}

variable "base_bucket_name" {
  description = "Base name used to construct the S3 bucket name; a random integer prefix is prepended."
  type        = string
  default     = "doc-io-files"
}

variable "force_destroy_bucket" {
  description = "Whether to delete all objects in the bucket when the bucket is destroyed."
  type        = bool
  default     = true
}

variable "bucket_policy_account_id" {
  description = "AWS account ID granted full S3 access to the bucket and its objects via the bucket policy."
  type        = string
  default     = "566373416292"
}

###############################################################################
# Random suffix for the bucket name
###############################################################################

resource "random_integer" "bucket_suffix" {
  min = 1
  max = 50000
}

###############################################################################
# Locals
###############################################################################

locals {
  bucket_name = "${random_integer.bucket_suffix.result}-${var.base_bucket_name}"

  common_tags = {
    Name        = local.bucket_name
    Environment = "production"
    ManagedBy   = "terraform"
    Purpose     = "document-io-files"
  }
}

###############################################################################
# Customer-managed KMS key for default SSE-KMS encryption
###############################################################################

resource "aws_kms_key" "doc_io_files" {
  description             = "Customer-managed KMS key for SSE-KMS encryption of the ${local.bucket_name} S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "doc_io_files" {
  name          = "alias/${local.bucket_name}-s3"
  target_key_id = aws_kms_key.doc_io_files.key_id
}

###############################################################################
# S3 bucket for document I/O files
###############################################################################

resource "aws_s3_bucket" "doc_io_files" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy_bucket

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.doc_io_files.arn
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Bucket policy: full S3 access for the specified account (bucket + objects)
###############################################################################

data "aws_iam_policy_document" "doc_io_files" {
  statement {
    sid    = "FullS3AccessForAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${var.bucket_policy_account_id}:root"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.doc_io_files.arn,
      "${aws_s3_bucket.doc_io_files.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "doc_io_files" {
  bucket = aws_s3_bucket.doc_io_files.id
  policy = data.aws_iam_policy_document.doc_io_files.json

  depends_on = [aws_s3_bucket_public_access_block.doc_io_files]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

###############################################################################
# Variables (non-infrastructure, user-controlled values only)
###############################################################################

variable "project_name" {
  description = "Project name used as a prefix for all remote state backend resources."
  type        = string
  default     = "terraform-state"
}

variable "environment" {
  description = "Environment name (for example: dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata and uniqueness helpers
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

resource "random_id" "name_suffix" {
  byte_length = 4
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  name_suffix = random_id.name_suffix.hex

  bucket_name     = "${var.project_name}-${var.environment}-tfstate-${local.name_suffix}"
  lock_table_name = "${var.project_name}-${var.environment}-tfstate-lock-${local.name_suffix}"
  kms_alias_name  = "alias/${var.project_name}-${var.environment}-tfstate-${local.name_suffix}"

  tags = merge(
    {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "Terraform"
      Purpose     = "TerraformRemoteState"
    },
    var.tags
  )
}

###############################################################################
# KMS customer managed key for state bucket and lock table encryption
###############################################################################

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "AllowAccountRootKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAwsServicesToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com", "dynamodb.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_kms_key" "state" {
  description             = "Customer managed key used to encrypt the Terraform remote state bucket and lock table for ${var.project_name}-${var.environment}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy.json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "state" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.state.key_id
}

###############################################################################
# S3 bucket for Terraform remote state
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.bucket_name

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket.state]
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    id     = "abort-incomplete-uploads-and-expire-noncurrent-versions"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }

  depends_on = [aws_s3_bucket_versioning.state]
}

data "aws_iam_policy_document" "state_bucket_policy" {
  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}

###############################################################################
# DynamoDB table for Terraform state locking
###############################################################################

resource "aws_dynamodb_table" "state_lock" {
  name         = local.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.state.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  deletion_protection_enabled = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs for external Terraform backend configuration
###############################################################################

output "terraform_state_bucket_name" {
  description = "Name of the S3 bucket that stores Terraform remote state."
  value       = aws_s3_bucket.state.id
}

output "terraform_state_bucket_arn" {
  description = "ARN of the S3 bucket that stores Terraform remote state."
  value       = aws_s3_bucket.state.arn
}

output "terraform_state_lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking (hash key LockID)."
  value       = aws_dynamodb_table.state_lock.name
}

output "terraform_state_kms_key_arn" {
  description = "ARN of the KMS customer managed key used to encrypt Terraform state and the lock table."
  value       = aws_kms_key.state.arn
}

output "terraform_state_kms_key_alias" {
  description = "Alias of the KMS customer managed key used to encrypt Terraform state and the lock table."
  value       = aws_kms_alias.state.name
}

output "terraform_state_region" {
  description = "AWS region in which the remote state backend resources were created."
  value       = local.region
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

locals {
  sns_topic_name      = "incident-response"
  kms_key_description = "Customer-managed KMS key encrypting the incident-response SNS topic"
  kms_alias_name      = "alias/incident-response-sns"
  account_root_arn    = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
}

resource "aws_kms_key" "incident_response" {
  description             = local.kms_key_description
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = local.sns_topic_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "incident_response" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.incident_response.key_id
}

resource "aws_kms_key_policy" "incident_response" {
  key_id = aws_kms_key.incident_response.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.sns_topic_name}-key-policy"
    Statement = [
      {
        Sid       = "EnableRootAccountKeyAdministration"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowSnsTopicUseOfKey"
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:EncryptionContext:aws:sns:topicArn" = aws_sns_topic.incident_response.arn
          }
        }
      }
    ]
  })
}

resource "aws_sns_topic" "incident_response" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.incident_response.arn

  tags = {
    Name = local.sns_topic_name
  }
}

resource "aws_sns_topic_policy" "incident_response" {
  arn = aws_sns_topic.incident_response.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "__default_policy_ID"
    Statement = [
      {
        Sid       = "__default_statement_ID"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action = [
          "SNS:Subscribe",
          "SNS:SetTopicAttributes",
          "SNS:RemovePermission",
          "SNS:Receive",
          "SNS:Publish",
          "SNS:ListSubscriptionsByTopic",
          "SNS:GetTopicAttributes",
          "SNS:DeleteTopic",
          "SNS:AddPermission"
        ]
        Resource = aws_sns_topic.incident_response.arn
        Condition = {
          StringEquals = {
            "AWS:SourceOwner" = data.aws_caller_identity.current.account_id
          }
        }
      },
      {
        Sid       = "AllowAWSEvents"
        Effect    = "Allow"
        Principal = { Service = "events.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.incident_response.arn
      }
    ]
  })
}

output "sns_topic_arn" {
  description = "ARN of the incident-response SNS topic"
  value       = aws_sns_topic.incident_response.arn
}

output "sns_topic_name" {
  description = "Name of the incident-response SNS topic"
  value       = aws_sns_topic.incident_response.name
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key encrypting the SNS topic"
  value       = aws_kms_key.incident_response.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix = "opensearch-logging"
  log_group   = "/aws/opensearch/logs"

  common_tags = {
    Project     = local.name_prefix
    Environment = "production"
    ManagedBy   = "terraform"
  }
}

resource "aws_iam_service_linked_role" "es" {
  aws_service_name = "es.amazonaws.com"
  description      = "Service-linked role for Amazon OpenSearch/Elasticsearch log publishing"

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "es_logs" {
  name              = local.log_group
  retention_in_days = 30

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_resource_policy" "es_log_publishing" {
  policy_name = "elasticsearch-log-publishing-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableOpenSearchLogPublishing"
        Effect = "Allow"
        Principal = {
          Service = "es.amazonaws.com"
        }
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:PutLogEventsBatch"
        ]
        Resource = [
          aws_cloudwatch_log_group.es_logs.arn,
          "${aws_cloudwatch_log_group.es_logs.arn}:*"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:${data.aws_partition.current.partition}:es:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:domain/*"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cognito_audience" {
  description = "Trusted audience (Amazon Cognito identity pool ID) accepted by the user group IAM role's web identity trust policy."
  type        = string
  default     = "us-east-1:12345678-dead-beef-cafe-123456790ab"

  validation {
    condition     = length(trimspace(var.cognito_audience)) > 0
    error_message = "The Cognito audience value must not be empty."
  }
}

variable "tags" {
  description = "Additional tags applied to every taggable resource created by this configuration."
  type        = map(string)
  default = {
    Project     = "cognito-identity"
    Environment = "dev"
    ManagedBy   = "Terraform"
  }
}

locals {
  common_tags = merge(
    {
      Project     = "cognito-identity"
      Environment = "dev"
      ManagedBy   = "Terraform"
    },
    var.tags,
  )
}

resource "aws_cognito_user_pool" "identity_pool" {
  name = "identity pool"

  auto_verified_attributes = ["email"]

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  deletion_protection = "ACTIVE"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "identity_pool"
  allow_unauthenticated_identities = false

  tags = local.common_tags
}

resource "aws_iam_role" "user_group_role" {
  name = "user-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCognitoAuthenticatedWebIdentity"
        Effect = "Allow"
        Action = "sts:AssumeRoleWithWebIdentity"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = var.cognito_audience
          }
          "ForAnyValue:StringLike" = {
            "cognito-identity.amazonaws.com:amr" = "*authenticated*"
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_policy" "user_group_policy" {
  name        = "user-group-policy"
  description = "Least-privilege access for the Cognito authenticated user group role."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "UserPoolReadAccess"
        Effect = "Allow"
        Action = [
          "cognito-idp:DescribeUserPool",
          "cognito-idp:DescribeUserPoolClient",
          "cognito-idp:GetGroup",
          "cognito-idp:GetUser",
          "cognito-idp:ListGroups",
          "cognito-idp:ListUsers",
          "cognito-idp:ListUsersInGroup",
        ]
        Resource = [aws_cognito_user_pool.identity_pool.arn]
      },
      {
        Sid    = "IdentityPoolCredentials"
        Effect = "Allow"
        Action = [
          "cognito-identity:GetCredentialsForIdentity",
          "cognito-identity:GetId",
        ]
        Resource = [aws_cognito_identity_pool.main.arn]
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "user_group_role_policy" {
  role       = aws_iam_role.user_group_role.name
  policy_arn = aws_iam_policy.user_group_policy.arn
}

resource "aws_cognito_user_group" "user_group" {
  name         = "user-group"
  description  = "Managed by Terraform"
  precedence   = 42
  user_pool_id = aws_cognito_user_pool.identity_pool.id
  role_arn     = aws_iam_role.user_group_role.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region used by both provider configurations."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Value applied to the Environment tag through provider default_tags."
  type        = string
  default     = "test"
}

variable "basic_table_name" {
  description = "Name of the DynamoDB table managed by the default AWS provider."
  type        = string
  default     = "default-and-alternate-tags-module-basic"
}

variable "alternate_table_name" {
  description = "Name of the DynamoDB table managed by the alternate AWS provider alias."
  type        = string
  default     = "default-and-alternate-tags-module-alternate"
}

locals {
  common_default_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  alternate_default_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    TagSource   = "alt-tags"
  }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = local.common_default_tags
  }
}

provider "aws" {
  alias  = "alt-tags"
  region = var.region

  default_tags {
    tags = local.alternate_default_tags
  }
}

resource "aws_dynamodb_table" "basic" {
  name         = var.basic_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    TableRole = "basic"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "alternate" {
  provider     = aws.alt-tags
  name         = var.alternate_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "KeyId"

  attribute {
    name = "KeyId"
    type = "S"
  }

  tags = {
    TableRole = "alternate"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "api_name" {
  type        = string
  description = "Name of the Amazon API Gateway REST API used for mock endpoint testing."
  default     = "terraform-api-gateway-example"
}

locals {
  content_type_json = "application/json"
  movies_message    = "Hello from the movies API!"
}

resource "aws_api_gateway_rest_api" "main" {
  name        = var.api_name
  description = "Mock REST API used for testing static web endpoint responses."

  endpoint_configuration {
    types = ["REGIONAL"]
  }
}

resource "aws_api_gateway_resource" "movies" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "movies"
}

resource "aws_api_gateway_method" "movies_get" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.movies.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "movies_get" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  type        = "MOCK"

  request_templates = {
    (local.content_type_json) = jsonencode({
      statusCode = 200
    })
  }
}

resource "aws_api_gateway_method_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = "200"

  response_models = {
    (local.content_type_json) = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "movies_get_200" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.movies.id
  http_method = aws_api_gateway_method.movies_get.http_method
  status_code = aws_api_gateway_method_response.movies_get_200.status_code

  response_templates = {
    (local.content_type_json) = jsonencode({
      message = local.movies_message
    })
  }

  depends_on = [
    aws_api_gateway_integration.movies_get,
    aws_api_gateway_method_response.movies_get_200,
  ]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "AllowFullKMSAccessToCurrentCaller"
    effect = "Allow"

    actions = ["kms:*"]

    # The key policy is attached to the CMK it governs, so it cannot reference
    # aws_kms_key.cmk.arn directly (that would create a self-referential cycle
    # between the key and its own policy). AWS evaluates key policies against
    # the key the policy is attached to, which effectively scopes this
    # statement to this CMK only. The wildcard here is the AWS-documented
    # pattern for a key policy's own resource and is not paired with
    # Action = "*".
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [data.aws_caller_identity.current.arn]
    }
  }
}

resource "aws_kms_key" "cmk" {
  description             = "Customer managed key (CMK) for testing"
  policy                  = data.aws_iam_policy_document.kms_key.json
  deletion_window_in_days = 7
  enable_key_rotation     = true

  # Deliberate deviation from the standard prevent_destroy guidance: this key
  # is created for short-lived testing, and the 7-day deletion window is chosen
  # specifically so teardown is fast and inexpensive. Adding
  # lifecycle { prevent_destroy = true } would block that intended teardown.
}

variable "kms_alias_prefix" {
  description = "Alias name (without the required 'alias/' prefix) for the CMK. Used for naming only and must never contain secret material."
  type        = string
  default     = "kms-cmk-example"

  validation {
    condition     = length(trimspace(var.kms_alias_prefix)) > 0
    error_message = "The KMS alias prefix must not be empty."
  }
}

resource "aws_kms_alias" "cmk_alias" {
  name          = "alias/${var.kms_alias_prefix}"
  target_key_id = aws_kms_key.cmk.key_id
}

output "kms_key_arn" {
  description = "ARN of the created KMS customer managed key."
  value       = aws_kms_key.cmk.arn
}

output "kms_key_id" {
  description = "ID of the created KMS customer managed key."
  value       = aws_kms_key.cmk.key_id
}

output "kms_alias_name" {
  description = "Name of the KMS alias pointing at the created customer managed key."
  value       = aws_kms_alias.cmk_alias.name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "secondary_region" {
  description = "Secondary AWS region used by the ap-south-mumbai provider alias."
  type        = string
  default     = "ap-south-1"
}

variable "primary_region" {
  description = "Primary AWS region used by the us-east-nv provider alias."
  type        = string
  default     = "us-east-1"
}

locals {
  primary_cidr   = "10.1.0.0/16"
  secondary_cidr = "10.2.0.0/16"

  common_tags = {
    Terraform = "yes"
  }
}

provider "aws" {
  region = var.primary_region

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "us-east-nv"
  region = var.primary_region

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "N.Virginia"
    }
  }
}

provider "aws" {
  alias  = "ap-south-mumbai"
  region = var.secondary_region

  default_tags {
    tags = {
      Terraform = "yes"
      Region    = "Mumbai"
    }
  }
}

data "aws_availability_zones" "primary" {
  provider = aws.us-east-nv
  state    = "available"
}

data "aws_availability_zones" "secondary" {
  provider = aws.ap-south-mumbai
  state    = "available"
}

resource "aws_vpc" "north_virginia" {
  provider = aws.us-east-nv

  cidr_block           = local.primary_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"

  tags = {
    Name = "North-Virginia-VPC"
  }
}

resource "aws_vpc" "mumbai" {
  provider = aws.ap-south-mumbai

  cidr_block           = local.secondary_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  instance_tenancy     = "default"

  tags = {
    Name = "Mumbai-VPC"
  }
}

output "north_virginia_vpc_id" {
  description = "VPC ID for the North-Virginia-VPC (us-east-1)."
  value       = aws_vpc.north_virginia.id
}

output "mumbai_vpc_id" {
  description = "VPC ID for the Mumbai-VPC (ap-south-1)."
  value       = aws_vpc.mumbai.id
}

output "north_virginia_availability_zones" {
  description = "Availability zones discovered for the us-east-nv (N. Virginia) provider."
  value       = data.aws_availability_zones.primary.names
}

output "mumbai_availability_zones" {
  description = "Availability zones discovered for the ap-south-mumbai (Mumbai) provider."
  value       = data.aws_availability_zones.secondary.names
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name used for resource tagging."
  type        = string
  default     = "test"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  purpose  = "outbound-traffic-evaluation"
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "outbound-egress-test-vpc"
    Environment = var.environment
    Purpose     = local.purpose
  }
}

resource "aws_security_group" "allow_tcp" {
  name        = "allow_tcp"
  description = "Allow TCP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "allow_tcp"
    Environment = var.environment
    Purpose     = local.purpose
  }
}

resource "aws_security_group" "allow_udp" {
  name        = "allow_udp"
  description = "Allow UDP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 10000
    to_port     = 10000
    protocol    = "udp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "allow_udp"
    Environment = var.environment
    Purpose     = local.purpose
  }
}

resource "aws_security_group" "allow_icmp" {
  name        = "allow_icmp"
  description = "Allow ICMP traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = -1
    to_port     = -1
    protocol    = "icmp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "allow_icmp"
    Environment = var.environment
    Purpose     = local.purpose
  }
}

resource "aws_security_group" "allow_all" {
  name        = "allow_all"
  description = "Allow ALL traffic"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "allow_all"
    Environment = var.environment
    Purpose     = local.purpose
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Static, non-provisioned lookups (provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Inputs
###############################################################################

variable "bucket_name" {
  description = "Base name of the S3 bucket that stores the Terraform remote state. The AWS account ID is appended to guarantee global uniqueness."
  type        = string
  default     = "terraform-state-backend"
}

variable "environment" {
  description = "Logical environment name used for tagging."
  type        = string
  default     = "shared"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project   = "terraform-remote-state"
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  state_bucket_name = "${var.bucket_name}-${data.aws_caller_identity.current.account_id}"
  key_alias_name    = "alias/terraform-state"
  lock_table_name   = "terraform-lock"

  availability_zones = data.aws_availability_zones.available.names

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

###############################################################################
# Customer managed KMS key dedicated to Terraform remote state
###############################################################################

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed KMS key used to encrypt the Terraform remote state stored in S3 and the DynamoDB state locking table."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "terraform_state" {
  name          = local.key_alias_name
  target_key_id = aws_kms_key.terraform_state.id
}

data "aws_iam_policy_document" "terraform_state_kms" {
  statement {
    sid    = "AllowAccountRootKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = [aws_kms_key.terraform_state.arn]
  }

  statement {
    sid    = "AllowS3AndDynamoDBStateEncryptionUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.terraform_state.arn]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values = [
        "s3.${local.region}.amazonaws.com",
        "dynamodb.${local.region}.amazonaws.com",
      ]
    }
  }
}

resource "aws_kms_key_policy" "terraform_state" {
  key_id = aws_kms_key.terraform_state.id
  policy = data.aws_iam_policy_document.terraform_state_kms.json
}

###############################################################################
# S3 bucket holding the Terraform remote state
###############################################################################

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.state_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "terraform_state_bucket" {
  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyUnencryptedObjectUploads"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = ["${aws_s3_bucket.terraform_state.arn}/*"]

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }
}

resource "aws_s3_bucket_policy" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id
  policy = data.aws_iam_policy_document.terraform_state_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.terraform_state,
  ]
}

###############################################################################
# DynamoDB table used for Terraform state locking
###############################################################################

resource "aws_dynamodb_table" "terraform_lock" {
  name         = local.lock_table_name
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.terraform_state.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "state_bucket_name" {
  description = "Name of the S3 bucket that stores the Terraform remote state."
  value       = aws_s3_bucket.terraform_state.bucket
}

output "state_bucket_arn" {
  description = "ARN of the S3 bucket that stores the Terraform remote state."
  value       = aws_s3_bucket.terraform_state.arn
}

output "lock_table_name" {
  description = "Name of the DynamoDB table used for Terraform state locking."
  value       = aws_dynamodb_table.terraform_lock.name
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used to encrypt the Terraform state."
  value       = aws_kms_key.terraform_state.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key used to encrypt the Terraform state."
  value       = aws_kms_alias.terraform_state.name
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "powerscale_regions" {
  description = "AWS regions where PowerScale node runtime operations may assign private IP addresses to network interfaces."
  type        = list(string)
  default     = ["*"]
}

resource "aws_iam_policy" "powerscale_node_runtime_policy" {
  name        = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-policy"
  description = "Allows PowerScale node runtime operations to assign private IP addresses to EC2 network interfaces."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AssignPrivateIpAddressesForPowerScaleNodes"
        Effect = "Allow"
        Action = [
          "ec2:AssignPrivateIpAddresses"
        ]
        Resource = [
          for region in var.powerscale_regions :
          "arn:aws:ec2:${region}:${data.aws_caller_identity.current.account_id}:network-interface/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "powerscale_node_runtime_role" {
  name = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEC2ServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "powerscale_node_runtime_policy_attachment" {
  role       = aws_iam_role.powerscale_node_runtime_role.name
  policy_arn = aws_iam_policy.powerscale_node_runtime_policy.arn
}

resource "aws_iam_instance_profile" "powerscale_node_runtime_instance_profile" {
  name = "${data.aws_caller_identity.current.account_id}-powerscale-node-runtime-instance-profile"
  role = aws_iam_role.powerscale_node_runtime_role.name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (user-controlled inputs only)
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the custom VPC."
  type        = string
  default     = "192.168.0.0/16"
}

variable "subnet_newbits" {
  description = "Number of bits added to the VPC prefix when carving subnets (/16 + 8 = /24). Sole authoritative subnet-sizing input."
  type        = number
  default     = 8
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to every resource."
  type        = map(string)
  default = {
    Project   = "tiered-app"
    ManagedBy = "terraform"
  }
}

variable "app_port" {
  description = "TCP port the application tier listens on."
  type        = number
  default     = 8080
}

variable "admin_cidr" {
  description = "Restricted CIDR permitted to SSH into the management tier (replace with the real admin range)."
  type        = string
  default     = "203.0.113.0/24"
}

###############################################################################
# Availability zones (static provider metadata lookup)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  # web = index 0 -> 192.168.0.0/24
  # app = index 1 -> 192.168.1.0/24
  # db  = index 2 -> 192.168.2.0/24
  # mgmt = index 3 -> 192.168.3.0/24
  web_subnet_cidr  = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 0)
  app_subnet_cidr  = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 1)
  db_subnet_cidr   = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 2)
  mgmt_subnet_cidr = cidrsubnet(var.vpc_cidr, var.subnet_newbits, 3)
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = "${var.environment}-vpc"
  })
}

###############################################################################
# Subnets
#
# AZ placement: web and mgmt intentionally SHARE the first zone
# (data.aws_availability_zones.available.names[0]) so the public entry point and
# the management/jump tier sit in the same failure domain. app uses names[1] and
# db uses names[2], spreading the private tiers across two additional zones.
#
# Public-IP auto-assignment is intentionally NOT enabled on any subnet
# (map_public_ip_on_launch defaults to false). The web tier remains publicly
# reachable through the internet gateway and the public route table association;
# explicit public addressing is delegated to instance/ALB-level constructs.
###############################################################################

resource "aws_subnet" "web" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.web_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.tags, {
    Name = "${var.environment}-web-subnet"
    Tier = "web"
  })
}

resource "aws_subnet" "app" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.app_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(var.tags, {
    Name = "${var.environment}-app-subnet"
    Tier = "app"
  })
}

resource "aws_subnet" "db" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.db_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(var.tags, {
    Name = "${var.environment}-db-subnet"
    Tier = "db"
  })
}

resource "aws_subnet" "mgmt" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.mgmt_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(var.tags, {
    Name = "${var.environment}-mgmt-subnet"
    Tier = "mgmt"
  })
}

###############################################################################
# Internet gateway (public entry path for the web tier)
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.environment}-igw"
  })
}

###############################################################################
# NAT gateway (outbound-only egress for the app tier, hosted in the web subnet)
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${var.environment}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.web.id

  tags = merge(var.tags, {
    Name = "${var.environment}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Route tables
###############################################################################

# Public route table: default route to the internet gateway (web tier).
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-public-rt"
    Tier = "web"
  })
}

# Private route table: default route through the NAT gateway (app tier).
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-private-rt"
    Tier = "app"
  })
}

# Isolated route table for the database tier: local routes only, no default route.
resource "aws_route_table" "db" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.environment}-db-rt"
    Tier = "db"
  })
}

# Isolated route table for the management tier: local routes only, no default route.
resource "aws_route_table" "mgmt" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = "${var.environment}-mgmt-rt"
    Tier = "mgmt"
  })
}

###############################################################################
# Route table associations
###############################################################################

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "app" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "db" {
  subnet_id      = aws_subnet.db.id
  route_table_id = aws_route_table.db.id
}

resource "aws_route_table_association" "mgmt" {
  subnet_id      = aws_subnet.mgmt.id
  route_table_id = aws_route_table.mgmt.id
}

###############################################################################
# Security groups (tier scoped)
#
# Cycle avoidance: only ONE direction of every cross-tier relationship may be
# expressed as an inline rule on an aws_security_group resource. The reverse
# direction is expressed as a standalone aws_security_group_rule resource, which
# depends on the SGs but introduces no edges between the SG resources.
#
# Resulting dependency order (acyclic):
#   web  (no SG-reference deps)
#   mgmt (no SG-reference deps)
#   app  -> depends on web (ingress from web)
#   db   -> depends on app (ingress from app)
#   rules -> depend only on the SGs they name
#
# Egress policy: no security group egresses to 0.0.0.0/0. Outbound reachability
# is scoped per tier (peer SG via source_security_group_id, or the VPC CIDR for
# the management tier). Security groups are stateful, so return traffic for
# accepted ingress is automatically permitted.
###############################################################################

resource "aws_security_group" "web" {
  name        = "${var.environment}-web-sg"
  description = "Public web tier: HTTP/HTTPS from the internet. Egress to the app tier is declared as a standalone rule."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from the internet"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-web-sg"
    Tier = "web"
  })
}

resource "aws_security_group" "app" {
  name        = "${var.environment}-app-sg"
  description = "Private app tier: application traffic from the web tier. Egress to the db tier is declared as standalone rules."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Application port from the web tier"
    from_port       = var.app_port
    to_port         = var.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.web.id]
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-app-sg"
    Tier = "app"
  })
}

resource "aws_security_group" "db" {
  name        = "${var.environment}-db-sg"
  description = "Database tier: MySQL/PostgreSQL from the app tier only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from the app tier"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  ingress {
    description     = "PostgreSQL from the app tier"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.app.id]
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-db-sg"
    Tier = "db"
  })
}

resource "aws_security_group" "mgmt" {
  name        = "${var.environment}-mgmt-sg"
  description = "Management tier: SSH from the restricted admin CIDR; egress scoped to the VPC CIDR only."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the restricted admin CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Intra-VPC reachability only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(var.tags, {
    Name = "${var.environment}-mgmt-sg"
    Tier = "mgmt"
  })
}

###############################################################################
# Standalone cross-tier egress rules
#
# Declared as separate resources so the aws_security_group resources never
# reference each other. This keeps SG-to-SG referencing on both directions
# without creating the web<->app and app<->db cycles.
###############################################################################

resource "aws_security_group_rule" "web_to_app" {
  description              = "Application traffic from the web tier to the app tier"
  type                     = "egress"
  from_port                = var.app_port
  to_port                  = var.app_port
  protocol                 = "tcp"
  security_group_id        = aws_security_group.web.id
  source_security_group_id = aws_security_group.app.id
}

resource "aws_security_group_rule" "app_to_db_mysql" {
  description              = "MySQL from the app tier to the db tier"
  type                     = "egress"
  from_port                = 3306
  to_port                  = 3306
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app.id
  source_security_group_id = aws_security_group.db.id
}

resource "aws_security_group_rule" "app_to_db_postgres" {
  description              = "PostgreSQL from the app tier to the db tier"
  type                     = "egress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app.id
  source_security_group_id = aws_security_group.db.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the custom VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr" {
  description = "CIDR block of the custom VPC."
  value       = aws_vpc.main.cidr_block
}

output "web_subnet_id" {
  description = "ID of the web tier subnet."
  value       = aws_subnet.web.id
}

output "app_subnet_id" {
  description = "ID of the app tier subnet."
  value       = aws_subnet.app.id
}

output "db_subnet_id" {
  description = "ID of the db tier subnet."
  value       = aws_subnet.db.id
}

output "mgmt_subnet_id" {
  description = "ID of the mgmt tier subnet."
  value       = aws_subnet.mgmt.id
}

output "availability_zone_tier_map" {
  description = "Mapping of each tier to the availability zone its subnet lives in."
  value = {
    web  = aws_subnet.web.availability_zone
    app  = aws_subnet.app.availability_zone
    db   = aws_subnet.db.availability_zone
    mgmt = aws_subnet.mgmt.availability_zone
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# State adoption of objects already created by this configuration
# (one-time adoption handles for greenfield re-applies with no remote backend)
###############################################################################

import {
  to = aws_iam_user.tj
  id = "TJ"
}

import {
  to = aws_efs_file_system.main
  id = "fs-0863ce0759f1dfa96"
}

###############################################################################
# Variables (user-controlled values only)
###############################################################################

variable "environment" {
  description = "Environment name used for tagging (for example: dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "owner" {
  description = "Owner tag value applied to every resource created by this configuration."
  type        = string
  default     = "TJ"
}

variable "iam_user_path" {
  description = "IAM path for the TJ user."
  type        = string
  default     = "/"
}

variable "iam_policy_path" {
  description = "IAM path for the GlacierEFSEC2 managed policy."
  type        = string
  default     = "/"
}

variable "glacier_archive_bucket_prefix" {
  description = "Prefix used to generate a globally unique S3 bucket name for Glacier-class archival storage."
  type        = string
  default     = "tj-glacier-archive"
}

variable "glacier_transition_days" {
  description = "Number of days after which current objects transition to an archive storage class."
  type        = number
  default     = 90
}

variable "efs_creation_token" {
  description = "Unique creation token for the encrypted EFS file system."
  type        = string
  default     = "tj-efs"
}

variable "tags" {
  description = "Additional tags merged into the default tag set for all taggable resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure is queried)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name

  common_tags = merge(
    {
      Environment = var.environment
      Owner       = var.owner
      Application = "GlacierEFSEC2"
      ManagedBy   = "Terraform"
    },
    var.tags
  )

  # Account/region scoped ARN prefixes so that no statement pairs Action "*" with Resource "*"
  ec2_arn_prefix = "arn:${local.partition}:ec2:${local.region}:${local.account_id}"

  efs_mount_target_arn = "arn:${local.partition}:elasticfilesystem:${local.region}:${local.account_id}:mount-target/*"

  # S3 Glacier storage-class archival ARNs (the AWS-recommended replacement for a Glacier vault)
  glacier_archive_bucket_arn = aws_s3_bucket.glacier_archive.arn
  glacier_archive_object_arn = "${aws_s3_bucket.glacier_archive.arn}/*"

  # Longer archive tier interval derived from the user-controlled transition interval
  glacier_deep_archive_days = var.glacier_transition_days * 2
}

###############################################################################
# IAM user and encrypted EFS file system
###############################################################################

resource "aws_iam_user" "tj" {
  name = "TJ"
  path = var.iam_user_path

  tags = merge(local.common_tags, { Name = "TJ" })
}

resource "aws_efs_file_system" "main" {
  creation_token   = var.efs_creation_token
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = merge(local.common_tags, { Name = "tj-efs" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# KMS customer-managed key for the Glacier-class archive bucket
###############################################################################

resource "aws_kms_key" "glacier_archive" {
  description             = "Customer-managed KMS key for the ${var.glacier_archive_bucket_prefix} S3 Glacier-class archival bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, { Name = "${var.glacier_archive_bucket_prefix}-kms" })
}

resource "aws_kms_alias" "glacier_archive" {
  # Alias name derives from the generated bucket identity so repeated applies stay unique
  name          = "alias/${aws_s3_bucket.glacier_archive.bucket}"
  target_key_id = aws_kms_key.glacier_archive.key_id
}

###############################################################################
# S3 bucket replacing the deprecated Glacier vault (Glacier/Deep Archive classes)
###############################################################################

resource "aws_s3_bucket" "glacier_archive" {
  bucket_prefix = var.glacier_archive_bucket_prefix

  tags = merge(local.common_tags, { Name = "${var.glacier_archive_bucket_prefix}-archive" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.glacier_archive.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "glacier_archive" {
  bucket = aws_s3_bucket.glacier_archive.id

  rule {
    id     = "archive-transition"
    status = "Enabled"

    filter {}

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER_IR"
    }

    transition {
      days          = local.glacier_deep_archive_days
      storage_class = "DEEP_ARCHIVE"
    }

    noncurrent_version_expiration {
      noncurrent_days = var.glacier_transition_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.glacier_archive]
}

###############################################################################
# Custom policy document - split per service so no statement uses Action "*" + Resource "*"
###############################################################################

data "aws_iam_policy_document" "glacier_efs_ec2" {
  # ---------------------------------------------------------------------------
  # EC2 read-only discovery - these APIs do not support resource-level permissions
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2ReadOnlyDiscovery"
    effect = "Allow"

    actions = [
      "ec2:DescribeAccountAttributes",
      "ec2:DescribeAddresses",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeImages",
      "ec2:DescribeInstanceAttribute",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeInstances",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeLaunchTemplates",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeRegions",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSubnets",
      "ec2:DescribeTags",
      "ec2:DescribeVolumes",
      "ec2:DescribeVolumesModifications",
      "ec2:DescribeVpcs",
    ]

    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # EC2 instance / volume / snapshot lifecycle - scoped to this account and region
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2InstanceVolumeAndSnapshotLifecycle"
    effect = "Allow"

    actions = [
      "ec2:RunInstances",
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:RebootInstances",
      "ec2:TerminateInstances",
      "ec2:ModifyInstanceAttribute",
      "ec2:CreateVolume",
      "ec2:AttachVolume",
      "ec2:DetachVolume",
      "ec2:ModifyVolume",
      "ec2:DeleteVolume",
      "ec2:CreateSnapshot",
      "ec2:DeleteSnapshot",
      "ec2:CreateTags",
      "ec2:DeleteTags",
    ]

    resources = [
      "${local.ec2_arn_prefix}:instance/*",
      "${local.ec2_arn_prefix}:volume/*",
      "${local.ec2_arn_prefix}:snapshot/*",
      "${local.ec2_arn_prefix}:network-interface/*",
      "${local.ec2_arn_prefix}:image/*",
      "${local.ec2_arn_prefix}:subnet/*",
      "${local.ec2_arn_prefix}:security-group/*",
      "${local.ec2_arn_prefix}:key-pair/*",
    ]
  }

  # ---------------------------------------------------------------------------
  # EC2 security group management - scoped to this account and region
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2SecurityGroupManagement"
    effect = "Allow"

    actions = [
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:UpdateSecurityGroupRuleDescriptionsIngress",
      "ec2:UpdateSecurityGroupRuleDescriptionsEgress",
      "ec2:CreateTags",
      "ec2:DeleteTags",
    ]

    resources = [
      "${local.ec2_arn_prefix}:security-group/*",
      "${local.ec2_arn_prefix}:vpc/*",
    ]
  }

  # ---------------------------------------------------------------------------
  # EC2 key pair management - scoped to this account and region
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EC2KeyPairManagement"
    effect = "Allow"

    actions = [
      "ec2:CreateKeyPair",
      "ec2:DeleteKeyPair",
      "ec2:ImportKeyPair",
    ]

    resources = [
      "${local.ec2_arn_prefix}:key-pair/*",
    ]
  }

  # ---------------------------------------------------------------------------
  # EFS client mount access - scoped strictly to the file system created here
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EFSClientAccess"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess",
    ]

    resources = [
      aws_efs_file_system.main.arn,
    ]
  }

  # ---------------------------------------------------------------------------
  # EFS describe operations - file system and mount target scope
  # ---------------------------------------------------------------------------
  statement {
    sid    = "EFSDescribe"
    effect = "Allow"

    actions = [
      "elasticfilesystem:DescribeFileSystems",
      "elasticfilesystem:DescribeMountTargets",
    ]

    resources = [
      aws_efs_file_system.main.arn,
      local.efs_mount_target_arn,
    ]
  }

  # ---------------------------------------------------------------------------
  # S3 archive bucket-level operations - scoped to the archive bucket created here
  # ---------------------------------------------------------------------------
  statement {
    sid    = "GlacierArchiveBucketAccess"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:ListBucketMultipartUploads",
    ]

    resources = [
      local.glacier_archive_bucket_arn,
    ]
  }

  # ---------------------------------------------------------------------------
  # S3 archive object-level operations - scoped to objects in the archive bucket
  # ---------------------------------------------------------------------------
  statement {
    sid    = "GlacierArchiveObjectAccess"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:DeleteObject",
      "s3:RestoreObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = [
      local.glacier_archive_object_arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-storage-class"
      values   = ["GLACIER", "GLACIER_IR", "DEEP_ARCHIVE"]
    }
  }

  # ---------------------------------------------------------------------------
  # KMS access to the archive bucket key - scoped to the key created here
  # ---------------------------------------------------------------------------
  statement {
    sid    = "GlacierArchiveKMSAccess"
    effect = "Allow"

    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.glacier_archive.arn,
    ]
  }
}

###############################################################################
# Managed policy and attachment
###############################################################################

resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = "GlacierEFSEC2"
  description = "EC2 management permissions plus scoped EFS client-mount access and S3 Glacier storage-class archival permissions."
  path        = var.iam_policy_path
  policy      = data.aws_iam_policy_document.glacier_efs_ec2.json

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "tj_glacier_efs_ec2" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

###############################################################################
# Outputs
###############################################################################

output "iam_user_arn" {
  description = "ARN of the TJ IAM user."
  value       = aws_iam_user.tj.arn
}

output "iam_policy_arn" {
  description = "ARN of the GlacierEFSEC2 IAM policy."
  value       = aws_iam_policy.glacier_efs_ec2.arn
}

output "efs_file_system_arn" {
  description = "ARN of the encrypted EFS file system used for scoped client-mount permissions."
  value       = aws_efs_file_system.main.arn
}

output "glacier_archive_bucket_arn" {
  description = "ARN of the S3 bucket providing Glacier/Deep Archive storage-class archival."
  value       = aws_s3_bucket.glacier_archive.arn
}

output "glacier_archive_kms_key_arn" {
  description = "ARN of the customer-managed KMS key protecting the archive bucket."
  value       = aws_kms_key.glacier_archive.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Partition / account / region metadata (static provider lookups only)
# ---------------------------------------------------------------------------
data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------
variable "name" {
  description = "Name of the IAM role created for EC2 instances."
  type        = string
  default     = "ec2-instance-role"

  validation {
    condition     = can(regex("^[a-zA-Z0-9+=,.@_-]{1,64}$", var.name))
    error_message = "The role name must be 1-64 characters and may only contain alphanumerics and +=,.@_- characters."
  }
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile. Defaults to '<name>-instance-profile'."
  type        = string
  default     = null

  validation {
    condition     = var.instance_profile_name == null || can(regex("^[a-zA-Z0-9+=,.@_-]{1,128}$", var.instance_profile_name))
    error_message = "The instance profile name must be 1-128 characters and may only contain alphanumerics and +=,.@_- characters."
  }
}

variable "description" {
  description = "Description applied to the IAM role."
  type        = string
  default     = "IAM role assumed by EC2 instances to obtain temporary credentials via IMDS."
}

variable "path" {
  description = "IAM path for the role and instance profile."
  type        = string
  default     = "/"

  validation {
    condition     = can(regex("^/(.*/)?$", var.path))
    error_message = "The IAM path must begin and end with a forward slash, for example \"/\" or \"/service/\"."
  }
}

variable "max_session_duration" {
  description = "Maximum session duration (in seconds) for the role, between 3600 and 43200."
  type        = number
  default     = 3600

  validation {
    condition     = var.max_session_duration >= 3600 && var.max_session_duration <= 43200
    error_message = "max_session_duration must be between 3600 and 43200 seconds."
  }
}

variable "permissions_boundary" {
  description = "Optional ARN of a managed policy to use as the permissions boundary for the role."
  type        = string
  default     = null

  validation {
    condition     = var.permissions_boundary == null || can(regex("^arn:[a-z0-9-]+:iam::[0-9]{12}:policy/.+$", var.permissions_boundary))
    error_message = "permissions_boundary must be a valid IAM policy ARN (or null)."
  }
}

variable "managed_policy_arns" {
  description = "List of AWS managed or customer managed IAM policy ARNs to attach to the role."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for arn in var.managed_policy_arns : can(regex("^arn:[a-z0-9-]+:iam::[0-9]{12}:policy/.+$", arn))
    ])
    error_message = "Every entry in managed_policy_arns must be a valid IAM policy ARN."
  }

  validation {
    condition     = length(var.managed_policy_arns) == length(distinct(var.managed_policy_arns))
    error_message = "managed_policy_arns must not contain duplicate ARNs."
  }
}

variable "inline_policies" {
  description = "Map of inline policy name to IAM policy JSON document."
  type        = map(string)
  default     = {}

  validation {
    condition     = alltrue([for k, v in var.inline_policies : can(regex("^[a-zA-Z0-9+=,.@_-]{1,128}$", k))])
    error_message = "Inline policy names must be 1-128 characters and may only contain alphanumerics and +=,.@_- characters."
  }

  validation {
    condition     = alltrue([for k, v in var.inline_policies : can(jsondecode(v))])
    error_message = "Every inline policy value must be a valid JSON IAM policy document."
  }
}

variable "tags" {
  description = "Additional tags applied to the role and instance profile."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Locals
# ---------------------------------------------------------------------------
locals {
  instance_profile_name = coalesce(var.instance_profile_name, "${var.name}-instance-profile")

  tags = merge(
    var.tags,
    {
      Name        = var.name
      ManagedBy   = "Terraform"
      Partition   = data.aws_partition.current.partition
      AwsRegion   = data.aws_region.current.name
      AwsAccount  = data.aws_caller_identity.current.account_id
      Description = var.description
    },
  )
}

# ---------------------------------------------------------------------------
# Trust policy — partition aware EC2 service principal
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.${data.aws_partition.current.dns_suffix}"]
    }
  }
}

# ---------------------------------------------------------------------------
# IAM role and instance profile
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ec2" {
  name                 = var.name
  description          = var.description
  path                 = var.path
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = var.max_session_duration
  permissions_boundary = var.permissions_boundary
  tags                 = local.tags
}

resource "aws_iam_instance_profile" "ec2" {
  name = local.instance_profile_name
  path = var.path
  role = aws_iam_role.ec2.name
  tags = local.tags
}

# ---------------------------------------------------------------------------
# Managed policy attachments
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.ec2.name
  policy_arn = each.value
}

# ---------------------------------------------------------------------------
# Inline policies
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "inline" {
  for_each = var.inline_policies

  name   = each.key
  role   = aws_iam_role.ec2.name
  policy = each.value
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "role_name" {
  description = "Name of the IAM role for EC2 instances."
  value       = aws_iam_role.ec2.name
}

output "role_arn" {
  description = "ARN of the IAM role for EC2 instances."
  value       = aws_iam_role.ec2.arn
}

output "instance_profile_name" {
  description = "Name of the IAM instance profile for EC2 instances."
  value       = aws_iam_instance_profile.ec2.name
}

output "instance_profile_arn" {
  description = "ARN of the IAM instance profile for EC2 instances."
  value       = aws_iam_instance_profile.ec2.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  cluster_name = "Fast-App"

  common_tags = {
    Cluster   = local.cluster_name
    ManagedBy = "terraform"
  }

  anywhere_cidr = "0.0.0.0/0"

  availability_zones = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  public_subnet_cidrs = [
    "10.0.0.0/24",
    "10.0.1.0/24",
  ]

  private_subnet_cidrs = [
    "10.0.10.0/24",
    "10.0.11.0/24",
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = length(local.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-${local.availability_zones[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count = length(local.private_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-${local.availability_zones[count.index]}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.anywhere_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.anywhere_cidr
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

output "vpc_id" {
  description = "ID of the Fast-App VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = aws_subnet.private[*].id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (user-controlled, non-infrastructure values only)
###############################################################################

variable "monitoring_account_ids" {
  description = "List of AWS account IDs allowed to assume the Grafana monitoring query role. When empty, the account running this deployment is used as the trusted principal."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for account_id in var.monitoring_account_ids : can(regex("^[0-9]{12}$", account_id))])
    error_message = "Each monitoring account ID must be a 12 digit AWS account ID, e.g. 123456789012."
  }
}

variable "grafana_external_id_secret_name" {
  description = "Base name for the AWS Secrets Manager secret that stores the Grafana external ID used in the role trust policy. A unique suffix is appended by AWS."
  type        = string
  default     = "grafana/monitoring/external-id"
}

variable "grafana_saml_idp_metadata_url" {
  description = "HTTPS URL of the SAML 2.0 identity provider metadata document used to authenticate users into the Grafana workspace."
  type        = string
  default     = "https://idp.example.com/saml/metadata"

  validation {
    condition     = can(regex("^https://", var.grafana_saml_idp_metadata_url))
    error_message = "The SAML IdP metadata URL must be an HTTPS URL."
  }
}

variable "grafana_saml_login_validity_duration" {
  description = "Maximum session duration in minutes for users authenticated via SAML to the Grafana workspace (1-720)."
  type        = number
  default     = 720

  validation {
    condition     = var.grafana_saml_login_validity_duration >= 1 && var.grafana_saml_login_validity_duration <= 720
    error_message = "The SAML login validity duration must be between 1 and 720 minutes."
  }
}

variable "grafana_saml_editor_role_values" {
  description = "List of SAML assertion role/group values that map to the Grafana Editor role."
  type        = list(string)
  default     = ["editor"]
}

variable "grafana_saml_admin_role_values" {
  description = "List of SAML assertion role/group values that map to the Grafana Admin role."
  type        = list(string)
  default     = ["admin"]
}

variable "grafana_saml_role_assertion" {
  description = "Name of the SAML assertion that carries the Grafana role value."
  type        = string
  default     = "role"
}

variable "grafana_saml_groups_assertion" {
  description = "Name of the SAML assertion that carries the Grafana group values."
  type        = string
  default     = "groups"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration. Overrides the built-in defaults for Environment / Project / ManagedBy."
  type        = map(string)
  default     = {}
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "grafana-monitoring"

  common_tags = merge(
    {
      Environment = "production"
      Project     = "grafana-monitoring"
      ManagedBy   = "Terraform"
    },
    var.tags
  )

  # Effective list of account IDs allowed to assume the role. Falls back to the
  # account running this deployment so the trust policy always has at least one
  # valid, real AWS principal.
  effective_monitoring_account_ids = length(var.monitoring_account_ids) > 0 ? var.monitoring_account_ids : [data.aws_caller_identity.current.account_id]
}

###############################################################################
# Generated external ID stored in AWS Secrets Manager (never plaintext)
###############################################################################

data "aws_secretsmanager_random_password" "grafana_external_id" {
  password_length     = 32
  exclude_punctuation = true
}

resource "aws_secretsmanager_secret" "grafana_external_id" {
  name_prefix             = "${var.grafana_external_id_secret_name}-"
  description             = "External ID required when assuming the Grafana monitoring query role."
  recovery_window_in_days = 7

  tags = merge(local.common_tags, { Name = var.grafana_external_id_secret_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "grafana_external_id" {
  secret_id     = aws_secretsmanager_secret.grafana_external_id.id
  secret_string = data.aws_secretsmanager_random_password.grafana_external_id.random_password
}

data "aws_secretsmanager_secret_version" "grafana_external_id" {
  secret_id  = aws_secretsmanager_secret.grafana_external_id.id
  depends_on = [aws_secretsmanager_secret_version.grafana_external_id]
}

###############################################################################
# Role trust policy: Grafana service principal + restricted monitoring accounts
###############################################################################

data "aws_iam_policy_document" "grafana_query_assume_role" {
  statement {
    sid     = "AllowGrafanaAndMonitoringAccountsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    principals {
      type        = "AWS"
      identifiers = [for account_id in local.effective_monitoring_account_ids : "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = local.effective_monitoring_account_ids
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [data.aws_secretsmanager_secret_version.grafana_external_id.secret_string]
    }
  }
}

###############################################################################
# IAM role assumed by the Grafana workspace
###############################################################################

resource "aws_iam_role" "grafana_query" {
  name_prefix          = "${local.name_prefix}-query-role-"
  description          = "Role assumed by the Grafana workspace to query Amazon Managed Service for Prometheus and CloudWatch."
  assume_role_policy   = data.aws_iam_policy_document.grafana_query_assume_role.json
  max_session_duration = 3600

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-query-role" })
}

###############################################################################
# Amazon Managed Service for Prometheus workspace (greenfield, created here)
###############################################################################

resource "aws_prometheus_workspace" "monitoring" {
  alias = "${local.name_prefix}-amp"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-amp" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Least-privilege query policy (Prometheus + CloudWatch read only)
###############################################################################

data "aws_iam_policy_document" "grafana_query" {
  statement {
    sid    = "PrometheusReadOnlyQueryAccess"
    effect = "Allow"
    actions = [
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:GetLabels",
      "aps:GetSeries",
      "aps:GetMetricData",
      "aps:GetMetricMetadata",
      "aps:QueryMetrics",
    ]
    resources = [aws_prometheus_workspace.monitoring.arn]
  }

  statement {
    sid    = "CloudWatchReadOnlyMetricsAccess"
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:ListTagsForResource",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_query" {
  name_prefix = "${local.name_prefix}-query-policy-"
  description = "Least-privilege policy allowing the Grafana workspace to read Prometheus and CloudWatch metrics."
  policy      = data.aws_iam_policy_document.grafana_query.json

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-query-policy" })
}

resource "aws_iam_role_policy_attachment" "grafana_query" {
  role       = aws_iam_role.grafana_query.name
  policy_arn = aws_iam_policy.grafana_query.arn
}

###############################################################################
# AWS Managed Grafana workspace
###############################################################################

resource "aws_grafana_workspace" "grafana" {
  name                     = "Grafana"
  account_access_type      = "CURRENT_ACCOUNT"
  authentication_providers = ["SAML"]
  permission_type          = "CUSTOMER_MANAGED"
  role_arn                 = aws_iam_role.grafana_query.arn
  data_sources             = ["PROMETHEUS", "CLOUDWATCH"]

  tags = merge(local.common_tags, { Name = "Grafana" })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# SAML configuration attached to the Grafana workspace
###############################################################################

resource "aws_grafana_workspace_saml_configuration" "grafana" {
  workspace_id            = aws_grafana_workspace.grafana.id
  idp_metadata_url        = var.grafana_saml_idp_metadata_url
  login_validity_duration = var.grafana_saml_login_validity_duration
  editor_role_values      = var.grafana_saml_editor_role_values
  admin_role_values       = var.grafana_saml_admin_role_values
  role_assertion          = var.grafana_saml_role_assertion
  groups_assertion        = var.grafana_saml_groups_assertion
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"

  # Map each private subnet CIDR to one of the first two available AZs in the
  # region. AZ names are resolved dynamically — never hardcoded.
  private_subnet_cidrs = {
    "10.0.1.0/24" = data.aws_availability_zones.available.names[0]
    "10.0.2.0/24" = data.aws_availability_zones.available.names[1]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "test-vpc"
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnet_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.key
  availability_zone       = each.value
  map_public_ip_on_launch = false

  tags = {
    Name = "test-private-subnet-${each.value}"
    Tier = "private"
  }
}

output "vpc_id" {
  description = "The ID of the VPC created for this test network foundation."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC created for this test network foundation."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "List of the individual private subnet IDs created in the VPC."
  value       = [for s in aws_subnet.private : s.id]
}

output "subnet_cidrs" {
  description = "List of the individual private subnet CIDR blocks created in the VPC."
  value       = [for s in aws_subnet.private : s.cidr_block]
}

output "private_subnet_ids" {
  description = "Aggregated list of the private subnet IDs in the VPC."
  value       = [for s in aws_subnet.private : s.id]
}

output "private_subnet_cidrs" {
  description = "Aggregated list of the private subnet CIDR blocks in the VPC."
  value       = [for s in aws_subnet.private : s.cidr_block]
}

# NOTE: The outputs below intentionally mirror the private subnet IDs and CIDRs.
# This mirroring exists only for testing/parity with templates that expect public
# subnet outputs. It does NOT imply that these subnets are public, routed to an
# internet gateway, or associated with any NAT/route table resources.
output "public_subnet_ids" {
  description = "Testing only: mirrors the private subnet IDs; these subnets are not internet-routable."
  value       = [for s in aws_subnet.private : s.id]
}

output "public_subnet_cidrs" {
  description = "Testing only: mirrors the private subnet CIDR blocks; these subnets are not internet-routable."
  value       = [for s in aws_subnet.private : s.cidr_block]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  project     = "trade-tariff"
  environment = "development"

  vpc_cidr = "10.0.0.0/16"

  az_a = data.aws_availability_zones.available.names[0]
  az_b = data.aws_availability_zones.available.names[1]

  public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]

  name_prefix = "${local.project}-${local.environment}"

  common_tags = {
    Project     = local.project
    Environment = local.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[0]
  availability_zone       = local.az_a
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-a"
    Tier = "public"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[1]
  availability_zone       = local.az_b
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-b"
    Tier = "public"
  })
}

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[0]
  availability_zone       = local.az_a
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-a"
    Tier = "private"
  })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[1]
  availability_zone       = local.az_b
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-b"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

resource "aws_nat_gateway" "main" {
  allocation_id     = aws_eip.nat.id
  subnet_id         = aws_subnet.public_a.id
  connectivity_type = "public"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat"
  })

  timeouts {
    create = "10m"
    delete = "10m"
  }

  depends_on = [
    aws_internet_gateway.main,
    aws_route_table.public,
    aws_route_table_association.public_a,
  ]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "allow_ssh" {
  name        = "allow-ssh"
  description = "Allow SSH inbound from the VPC CIDR only and restrict all outbound traffic to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "allow-ssh"
  })

  lifecycle {
    create_before_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "repository_name" {
  description = "Name of the ECR repository that will store container images."
  type        = string
  default     = "app-images"

  validation {
    condition     = can(regex("^[a-z0-9]+([-._/][a-z0-9]+)*$", var.repository_name))
    error_message = "The repository name must be lowercase and may only contain alphanumerics, hyphens, underscores, periods and forward slashes."
  }
}

variable "create_kms_key" {
  description = "When true, a customer-managed KMS key is created and used for ECR image encryption. When false, AES256 (SSE-S3 style) encryption is used unless kms_key_arn is supplied."
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "Optional ARN of an existing customer-managed KMS key to use when create_kms_key is false. Leave empty to fall back to AES256 encryption."
  type        = string
  default     = ""
}

variable "create_repository_policy" {
  description = "When true, an ECR repository access policy is attached to the repository."
  type        = bool
  default     = false
}

variable "allowed_pull_principals" {
  description = "List of AWS principal ARNs (accounts, roles or users) that are granted pull-only access to the repository."
  type        = list(string)
  default     = []
}

variable "create_lifecycle_policy" {
  description = "When true, a lifecycle policy is attached to the repository to expire stale images."
  type        = bool
  default     = true
}

variable "max_image_count" {
  description = "Maximum number of tagged images to retain before older images are expired."
  type        = number
  default     = 10
}

variable "lifecycle_tag_prefixes" {
  description = "Tag prefixes the tagged-image retention rule applies to."
  type        = list(string)
  default     = ["v"]
}

variable "untagged_image_expiry_days" {
  description = "Number of days after which untagged images are expired."
  type        = number
  default     = 14
}

variable "tags" {
  description = "Common tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "terraform"
    Project     = "container-registry"
  }
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  # Root principal of the account that owns the repository (used to allow the
  # owner to push/pull images). Derived from provider metadata, never hardcoded.
  repository_owner_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  # Customer-managed encryption is used when a key is created or supplied.
  custom_kms_enabled = var.create_kms_key || var.kms_key_arn != ""

  ecr_encryption_type = local.custom_kms_enabled ? "KMS" : "AES256"

  ecr_kms_key_arn = var.create_kms_key ? aws_kms_key.ecr[0].arn : (var.kms_key_arn != "" ? var.kms_key_arn : null)

  common_tags = merge(var.tags, {
    Name        = var.repository_name
    Environment = lookup(var.tags, "Environment", "dev")
    ManagedBy   = "terraform"
  })

  ecr_lifecycle_policy = {
    rules = [
      {
        rulePriority = 1
        description  = "Retain only the most recent ${var.max_image_count} tagged images"
        selection = {
          tagStatus     = "tagged"
          tagPrefixList = var.lifecycle_tag_prefixes
          countType     = "imageCountMoreThan"
          countNumber   = var.max_image_count
        }
        action = {
          type = "expire"
        }
      },
      {
        rulePriority = 2
        description  = "Expire untagged images older than ${var.untagged_image_expiry_days} days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = var.untagged_image_expiry_days
        }
        action = {
          type = "expire"
        }
      },
    ]
  }
}

###############################################################################
# KMS key (customer-managed encryption, optional)
###############################################################################

resource "aws_kms_key" "ecr" {
  count = var.create_kms_key ? 1 : 0

  description             = "Customer-managed KMS key for ECR repository ${var.repository_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${var.repository_name}-ecr"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "ecr" {
  count = var.create_kms_key ? 1 : 0

  name          = "alias/${var.repository_name}-ecr"
  target_key_id = aws_kms_key.ecr[0].key_id
}

###############################################################################
# ECR repository
###############################################################################

resource "aws_ecr_repository" "main" {
  name = var.repository_name

  # Tags are immutable so a published image tag can never be overwritten. CI/CD
  # must push unique, non-reused tags (git SHA, build number, or semver) rather
  # than mutating a floating tag such as "latest".
  image_tag_mutability = "IMMUTABLE"

  dynamic "encryption_configuration" {
    for_each = local.custom_kms_enabled ? [local.ecr_encryption_type] : ["AES256"]

    content {
      encryption_type = encryption_configuration.value
      kms_key         = local.custom_kms_enabled ? local.ecr_kms_key_arn : null
    }
  }

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Repository access policy (optional)
###############################################################################

data "aws_iam_policy_document" "repository" {
  count = var.create_repository_policy ? 1 : 0

  dynamic "statement" {
    for_each = length(var.allowed_pull_principals) > 0 ? [1] : []

    content {
      sid    = "AllowPullFromTrustedPrincipals"
      effect = "Allow"

      actions = [
        "ecr:GetDownloadUrlForLayer",
        "ecr:BatchGetImage",
        "ecr:BatchCheckLayerAvailability",
      ]

      resources = [aws_ecr_repository.main.arn]

      principals {
        type        = "AWS"
        identifiers = var.allowed_pull_principals
      }
    }
  }

  statement {
    sid    = "AllowRepositoryOwnerFullAccess"
    effect = "Allow"

    actions = [
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
      "ecr:DescribeRepositories",
      "ecr:DescribeImages",
      "ecr:ListImages",
      "ecr:BatchDeleteImage",
      "ecr:GetRepositoryPolicy",
      "ecr:SetRepositoryPolicy",
      "ecr:DeleteRepositoryPolicy",
    ]

    resources = [aws_ecr_repository.main.arn]

    principals {
      type        = "AWS"
      identifiers = [local.repository_owner_arn]
    }
  }
}

resource "aws_ecr_repository_policy" "main" {
  count = var.create_repository_policy ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = data.aws_iam_policy_document.repository[0].json
}

###############################################################################
# Lifecycle policy (optional, enabled by default)
###############################################################################

resource "aws_ecr_lifecycle_policy" "main" {
  count = var.create_lifecycle_policy ? 1 : 0

  repository = aws_ecr_repository.main.name
  policy     = jsonencode(local.ecr_lifecycle_policy)
}

###############################################################################
# Outputs
###############################################################################

output "repository_name" {
  description = "Name of the created ECR repository."
  value       = aws_ecr_repository.main.name
}

output "repository_url" {
  description = "URL of the ECR repository used to push and pull images. Tags are immutable: CI/CD must publish unique, non-reused tags (git SHA, build number, or semver) instead of mutating a floating tag such as 'latest'."
  value       = aws_ecr_repository.main.repository_url
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.main.arn
}

output "image_tag_mutability" {
  description = "Tag mutability setting of the repository. IMMUTABLE prevents image tags from being overwritten after they are pushed."
  value       = aws_ecr_repository.main.image_tag_mutability
}

output "registry_id" {
  description = "Registry ID (AWS account ID) that owns the repository."
  value       = aws_ecr_repository.main.registry_id
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for image encryption, when one is configured."
  value       = local.custom_kms_enabled ? local.ecr_kms_key_arn : null
  sensitive   = true
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key used for image encryption, when one is created."
  value       = var.create_kms_key ? aws_kms_alias.ecr[0].name : null
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

variable "project" {
  type        = string
  default     = "example"
  description = "Project name used as part of the resource naming prefix."
}

variable "environment" {
  type        = string
  default     = "dev"
  description = "Deployment environment used as part of the resource naming prefix."
}

variable "queue_name_suffix" {
  type        = string
  default     = "main"
  description = "Queue name suffix. Must end with '.fifo' when enable_fifo is true."

  validation {
    condition     = (var.enable_fifo && endswith(var.queue_name_suffix, ".fifo")) || (!var.enable_fifo && !endswith(var.queue_name_suffix, ".fifo"))
    error_message = "When enable_fifo is true, queue_name_suffix must end with '.fifo'. When enable_fifo is false, it must not end with '.fifo'."
  }
}

variable "enable_fifo" {
  type        = bool
  default     = false
  description = "Whether to create a FIFO SQS queue."
}

variable "fifo_content_based_deduplication" {
  type        = bool
  default     = false
  description = "Whether to enable content-based deduplication for a FIFO queue."

  validation {
    condition     = var.enable_fifo || !var.fifo_content_based_deduplication
    error_message = "fifo_content_based_deduplication can only be true when enable_fifo is true."
  }
}

variable "enable_queue_policy" {
  type        = bool
  default     = false
  description = "Whether to create an SQS queue access policy."
}

variable "queue_policy_principal_arn" {
  type        = string
  default     = ""
  description = "AWS principal ARN allowed to send messages when enable_queue_policy is true."

  validation {
    condition     = !var.enable_queue_policy || length(trimspace(var.queue_policy_principal_arn)) > 0
    error_message = "queue_policy_principal_arn must be set when enable_queue_policy is true."
  }
}

variable "message_retention_seconds" {
  type        = number
  default     = 345600
  description = "The number of seconds SQS retains a message."
}

variable "visibility_timeout_seconds" {
  type        = number
  default     = 30
  description = "The visibility timeout for the queue in seconds."
}

variable "receive_wait_time_seconds" {
  type        = number
  default     = 20
  description = "The long polling wait time for ReceiveMessage calls in seconds."
}

variable "max_message_size" {
  type        = number
  default     = 262144
  description = "The limit of how many bytes a message can contain."
}

variable "delay_seconds" {
  type        = number
  default     = 0
  description = "The delay for each message in seconds."
}

variable "extra_tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to all resources."
}

variable "owner" {
  type        = string
  default     = "platform-team"
  description = "Owner tag value."
}

variable "cost_center" {
  type        = string
  default     = "shared-services"
  description = "CostCenter tag value."
}

variable "enable_kms" {
  type        = bool
  default     = true
  description = "Whether to create and use a customer-managed KMS key for SQS encryption."
}

variable "enable_dlq" {
  type        = bool
  default     = true
  description = "Whether to create a dead-letter queue and redrive policy."
}

variable "max_receive_count" {
  type        = number
  default     = 5
  description = "The number of times a message is received before being moved to the DLQ."
}

locals {
  name_prefix = "${var.project}-${var.environment}"
  queue_name  = "${local.name_prefix}-${var.queue_name_suffix}"
  dlq_name    = var.enable_fifo ? "${trimsuffix(local.queue_name, ".fifo")}-dlq.fifo" : "${local.queue_name}-dlq"

  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "Terraform"
      Owner       = var.owner
      CostCenter  = var.cost_center
    },
    var.extra_tags
  )
}

data "aws_iam_policy_document" "sqs_kms" {
  statement {
    sid    = "EnableRootAccountPermissions"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CreateGrant",
      "kms:DescribeKey",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:EnableKeyRotation",
      "kms:DisableKeyRotation",
      "kms:UpdateKeyDescription",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSQSPrincipal"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "sqs" {
  count = var.enable_kms ? 1 : 0

  description             = "KMS key for SQS queue ${local.queue_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.sqs_kms.json
  tags                    = local.common_tags
}

resource "aws_sqs_queue" "dlq" {
  count = var.enable_dlq ? 1 : 0

  name                        = local.dlq_name
  fifo_queue                  = var.enable_fifo
  content_based_deduplication = var.enable_fifo ? var.fifo_content_based_deduplication : null
  message_retention_seconds   = var.message_retention_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  max_message_size            = var.max_message_size
  delay_seconds               = var.delay_seconds
  kms_master_key_id           = var.enable_kms ? aws_kms_key.sqs[0].arn : null
  sqs_managed_sse_enabled     = var.enable_kms ? null : true
  tags                        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue" "this" {
  name                        = local.queue_name
  fifo_queue                  = var.enable_fifo
  content_based_deduplication = var.enable_fifo ? var.fifo_content_based_deduplication : null
  message_retention_seconds   = var.message_retention_seconds
  visibility_timeout_seconds  = var.visibility_timeout_seconds
  receive_wait_time_seconds   = var.receive_wait_time_seconds
  max_message_size            = var.max_message_size
  delay_seconds               = var.delay_seconds
  kms_master_key_id           = var.enable_kms ? aws_kms_key.sqs[0].arn : null
  sqs_managed_sse_enabled     = var.enable_kms ? null : true
  tags                        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_policy" "this" {
  count = var.enable_dlq ? 1 : 0

  queue_url = aws_sqs_queue.this.id

  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  })
}

data "aws_iam_policy_document" "queue_policy" {
  count = var.enable_queue_policy ? 1 : 0

  statement {
    sid    = "AllowSendMessage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [var.queue_policy_principal_arn]
    }

    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.this.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = ["arn:${data.aws_partition.current.partition}:sqs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:*"]
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = var.enable_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this.id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

output "queue_url" {
  value = aws_sqs_queue.this.url
}

output "queue_arn" {
  value = aws_sqs_queue.this.arn
}

output "queue_name" {
  value = aws_sqs_queue.this.name
}

output "fifo_queue" {
  value = aws_sqs_queue.this.fifo_queue
}

output "dlq_url" {
  value = try(aws_sqs_queue.dlq[0].url, null)
}

output "dlq_arn" {
  value = try(aws_sqs_queue.dlq[0].arn, null)
}

output "kms_key_arn" {
  value = try(aws_kms_key.sqs[0].arn, null)
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "dsql_cluster_enabled" {
  description = "Controls whether the primary Aurora DSQL cluster is created."
  type        = bool
  default     = true
}

variable "deletion_protection_enabled" {
  description = "Enables deletion protection on the Aurora DSQL clusters."
  type        = bool
  default     = true
}

variable "force_destroy" {
  description = "Destruction intent for the Aurora DSQL clusters. This provider version does not expose a force_destroy argument on aws_dsql_cluster, so destructive behavior is governed by deletion_protection_enabled and the lifecycle prevent_destroy guard; this value is surfaced as an output for the effective destruction policy."
  type        = bool
  default     = false
}

variable "enable_kms_encryption" {
  description = "Creates and uses a customer managed KMS key for Aurora DSQL encryption at rest."
  type        = bool
  default     = true
}

variable "enable_multi_region" {
  description = "Creates a secondary Aurora DSQL cluster for multi-region deployments."
  type        = bool
  default     = false
}

variable "secondary_region" {
  description = "AWS region intended for the secondary Aurora DSQL cluster."
  type        = string
  default     = "us-west-2"
}

variable "enable_cluster_peering" {
  description = "Creates the Aurora DSQL cluster peering when enabled and at least one peer cluster is supplied."
  type        = bool
  default     = false
}

variable "witness_region" {
  description = "Witness region for the Aurora DSQL cluster peering. Must be a non-empty region."
  type        = string
  default     = "us-east-1"

  validation {
    condition     = length(trimspace(var.witness_region)) > 0
    error_message = "witness_region must be a non-empty AWS region name when cluster peering is enabled."
  }
}

variable "peer_cluster_regions" {
  description = "List of regions that contain peer Aurora DSQL clusters."
  type        = list(string)
  default     = []
}

variable "cluster_peering_create_timeout" {
  description = "Timeout applied to the Aurora DSQL cluster and cluster peering create operations."
  type        = string
  default     = "30m"
}

variable "tags" {
  description = "Tags applied to every taggable resource."
  type        = map(string)
  default = {
    Environment = "dev"
    ManagedBy   = "Terraform"
    Project     = "aurora-dsql"
  }
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

locals {
  name_prefix = "${var.environment}-dsql"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })

  create_cluster_peering = var.enable_cluster_peering && length(var.peer_cluster_regions) > 0

  dsql_service_principals = [
    "dsql.amazonaws.com",
    "dsql.${data.aws_region.current.name}.amazonaws.com",
  ]
}

data "aws_iam_policy_document" "dsql_kms" {
  count = var.enable_kms_encryption ? 1 : 0

  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAuroraDSQLServiceAccess"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = local.dsql_service_principals
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "dsql" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "Customer managed KMS key used to encrypt Aurora DSQL clusters in ${var.environment}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = var.enable_multi_region

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "dsql" {
  count = var.enable_kms_encryption ? 1 : 0

  key_id = aws_kms_key.dsql[0].id
  policy = data.aws_iam_policy_document.dsql_kms[0].json
}

resource "aws_kms_alias" "dsql" {
  count = var.enable_kms_encryption ? 1 : 0

  name_prefix   = "alias/${local.name_prefix}-"
  target_key_id = aws_kms_key.dsql[0].key_id
}

resource "aws_dsql_cluster" "primary" {
  count = var.dsql_cluster_enabled ? 1 : 0

  deletion_protection_enabled = var.deletion_protection_enabled
  kms_encryption_key          = var.enable_kms_encryption ? aws_kms_key.dsql[0].arn : "AWS_OWNED_KMS_KEY"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-primary"
    Role = "primary"
  })

  timeouts {
    create = var.cluster_peering_create_timeout
    delete = var.cluster_peering_create_timeout
  }

  depends_on = [
    aws_kms_key_policy.dsql,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dsql_cluster" "secondary" {
  count = var.enable_multi_region ? 1 : 0

  deletion_protection_enabled = var.deletion_protection_enabled
  kms_encryption_key          = var.enable_kms_encryption ? aws_kms_key.dsql[0].arn : "AWS_OWNED_KMS_KEY"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-secondary"
    Role = "secondary"
  })

  timeouts {
    create = var.cluster_peering_create_timeout
    delete = var.cluster_peering_create_timeout
  }

  depends_on = [
    aws_kms_key_policy.dsql,
  ]

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dsql_cluster_peering" "this" {
  count = local.create_cluster_peering ? 1 : 0

  identifier = aws_dsql_cluster.primary[0].identifier

  clusters = toset(concat(
    [aws_dsql_cluster.primary[0].arn],
    aws_dsql_cluster.secondary[*].arn,
  ))

  witness_region = var.witness_region

  timeouts {
    create = var.cluster_peering_create_timeout
  }

  depends_on = [
    aws_dsql_cluster.primary,
    aws_dsql_cluster.secondary,
  ]
}

output "cluster_identifier" {
  description = "Identifier of the primary Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.primary[0].identifier, null)
}

output "cluster_arn" {
  description = "ARN of the primary Aurora DSQL cluster."
  value       = try(aws_dsql_cluster.primary[0].arn, null)
}

output "cluster_endpoint" {
  description = "Connection endpoint (hostname) of the primary Aurora DSQL cluster."
  value       = try("${aws_dsql_cluster.primary[0].identifier}.dsql.${data.aws_region.current.name}.on.aws", null)
}

output "secondary_cluster_identifier" {
  description = "Identifier of the secondary Aurora DSQL cluster, when multi-region is enabled."
  value       = try(aws_dsql_cluster.secondary[0].identifier, null)
}

output "secondary_cluster_arn" {
  description = "ARN of the secondary Aurora DSQL cluster, when multi-region is enabled."
  value       = try(aws_dsql_cluster.secondary[0].arn, null)
}

output "secondary_region" {
  description = "Region intended for the secondary Aurora DSQL cluster when multi-region is enabled."
  value       = var.enable_multi_region ? var.secondary_region : null
}

output "cluster_peering_identifier" {
  description = "Identifier of the Aurora DSQL cluster peering, when cluster peering is enabled."
  value       = try(aws_dsql_cluster_peering.this[0].identifier, null)
}

output "effective_destruction_policy" {
  description = "Effective destruction controls applied to the Aurora DSQL clusters. The provider version in use does not expose a force_destroy argument on aws_dsql_cluster, so destruction is governed by deletion_protection_enabled and the lifecycle prevent_destroy guard."
  value = {
    force_destroy               = var.force_destroy
    deletion_protection_enabled = var.deletion_protection_enabled
    lifecycle_prevent_destroy   = true
  }
}

output "kms_encryption_key" {
  description = "Effective KMS encryption key used by the Aurora DSQL clusters: the customer managed key ARN when KMS encryption is enabled, otherwise the AWS-owned key sentinel."
  value       = var.enable_kms_encryption ? try(aws_kms_key.dsql[0].arn, null) : "AWS_OWNED_KMS_KEY"
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key used for Aurora DSQL encryption, when KMS encryption is enabled."
  value       = try(aws_kms_alias.dsql[0].name, null)
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key used for Aurora DSQL encryption, when KMS encryption is enabled."
  value       = try(aws_kms_key.dsql[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "bucket_name" {
  description = "Globally unique name of the S3 bucket to create."
  type        = string
  default     = "example-customizable-s3-bucket"
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock on the bucket (bucket versioning is always enabled to support it)."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow deletion of the bucket even when it still contains objects. Defaults to false to prevent accidental data loss."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

variable "bucket_policies" {
  description = "Map of custom bucket policy definitions, keyed by a unique identifier. Each policy declares an id, an optional document version, and one or more statements with sid, actions, effect (defaults to Allow), resources, and principals."
  type = map(object({
    id      = string
    version = optional(string, "2012-10-17")
    statements = list(object({
      sid       = string
      actions   = list(string)
      effect    = optional(string, "Allow")
      resources = list(string)
      principals = list(object({
        type        = string
        identifiers = list(string)
      }))
    }))
  }))
  default = {}
}

locals {
  kms_alias_name = "alias/${replace(var.bucket_name, ".", "-")}-s3-encryption"

  tags = merge(
    {
      Name      = var.bucket_name
      ManagedBy = "Terraform"
    },
    var.tags,
  )
}

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  object_lock_enabled = var.object_lock_enabled
  force_destroy       = var.force_destroy

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_kms_key" "s3" {
  description             = "Customer managed KMS key used for default encryption of the ${var.bucket_name} S3 bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "s3" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }

  depends_on = [aws_kms_alias.s3]
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 1
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

data "aws_iam_policy_document" "bucket" {
  for_each = var.bucket_policies

  version = each.value.version

  dynamic "statement" {
    for_each = each.value.statements

    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  for_each = var.bucket_policies

  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket[each.key].json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this,
  ]
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -------------------------------------------------------------------
# Static provider metadata (pure lookups, no pre-existing infra)
# -------------------------------------------------------------------
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -------------------------------------------------------------------
# Locals
# -------------------------------------------------------------------
locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  create_resources = var.create_resources
  create_topic     = var.create_resources
  create_policy    = var.create_resources && var.create_topic_policy

  kms_alias_name = "alias/sns-${replace(coalesce(var.name, var.name_prefix, "topic"), ".", "-")}"

  topic_kms_master_key_id = var.kms_master_key_id != null ? var.kms_master_key_id : try(aws_kms_key.sns[0].arn, null)

  subscriptions = var.create_resources ? var.subscriptions : {}

  # ---- all user supplied topic policy statements flattened ----
  all_topic_policy_statements = concat(
    var.source_policy_statements,
    var.custom_policy_statements,
    var.override_policy_statements,
  )

  # ---- endpoint discovery from subscription definitions (used to scope IAM) ----
  sqs_endpoints = distinct([
    for s in values(local.subscriptions) : s.endpoint
    if try(s.protocol, "") == "sqs" && try(s.endpoint, null) != null
  ])

  lambda_endpoints = distinct([
    for s in values(local.subscriptions) : s.endpoint
    if try(s.protocol, "") == "lambda" && try(s.endpoint, null) != null
  ])

  firehose_endpoints = distinct([
    for s in values(local.subscriptions) : s.endpoint
    if try(s.protocol, "") == "firehose" && try(s.endpoint, null) != null
  ])

  application_endpoints = distinct([
    for s in values(local.subscriptions) : s.endpoint
    if try(s.protocol, "") == "application" && try(s.endpoint, null) != null
  ])

  # ---- least-privilege resource scopes (fallback scoped to account/region/service) ----
  sqs_policy_resources = length(local.sqs_endpoints) > 0 ? local.sqs_endpoints : [
    "arn:${local.partition}:sqs:${local.region}:${local.account_id}:*"
  ]

  lambda_policy_resources = length(local.lambda_endpoints) > 0 ? local.lambda_endpoints : [
    "arn:${local.partition}:lambda:${local.region}:${local.account_id}:function:*"
  ]

  firehose_policy_resources = length(local.firehose_endpoints) > 0 ? local.firehose_endpoints : [
    "arn:${local.partition}:firehose:${local.region}:${local.account_id}:deliverystream/*"
  ]

  application_policy_resources = length(local.application_endpoints) > 0 ? local.application_endpoints : [
    "arn:${local.partition}:sns:${local.region}:${local.account_id}:endpoint/*"
  ]

  logs_policy_resources = [
    "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
  ]

  # ---- delivery feedback role resolution (user supplied wins, else managed role) ----
  sqs_feedback_role_arn = (
    var.sqs_feedback_role_arn != null
    ? var.sqs_feedback_role_arn
    : try(aws_iam_role.sns_delivery_feedback_sqs[0].arn, null)
  )

  lambda_feedback_role_arn = (
    var.lambda_feedback_role_arn != null
    ? var.lambda_feedback_role_arn
    : try(aws_iam_role.sns_delivery_feedback_lambda[0].arn, null)
  )

  http_feedback_role_arn = (
    var.http_feedback_role_arn != null
    ? var.http_feedback_role_arn
    : try(aws_iam_role.sns_delivery_feedback_http[0].arn, null)
  )

  firehose_feedback_role_arn = (
    var.firehose_feedback_role_arn != null
    ? var.firehose_feedback_role_arn
    : try(aws_iam_role.sns_delivery_feedback_firehose[0].arn, null)
  )

  application_feedback_role_arn = (
    var.application_feedback_role_arn != null
    ? var.application_feedback_role_arn
    : try(aws_iam_role.sns_delivery_feedback_application[0].arn, null)
  )

  # ---- creation toggles for managed delivery feedback roles ----
  create_sqs_feedback         = var.create_resources && var.sqs_feedback_role_arn == null
  create_lambda_feedback      = var.create_resources && var.lambda_feedback_role_arn == null
  create_http_feedback        = var.create_resources && var.http_feedback_role_arn == null
  create_firehose_feedback    = var.create_resources && var.firehose_feedback_role_arn == null
  create_application_feedback = var.create_resources && var.application_feedback_role_arn == null
}

# -------------------------------------------------------------------
# Plan/apply-time invariant: content based deduplication requires FIFO.
# Expressed as a check block so it does not form a variable-validation cycle.
# -------------------------------------------------------------------
check "fifo_content_based_deduplication" {
  assert {
    condition     = !var.content_based_deduplication || var.fifo_topic
    error_message = "content_based_deduplication may only be enabled when fifo_topic is true."
  }
}

# -------------------------------------------------------------------
# Plan/apply-time invariant: user supplied topic policy statements must
# only use explicit SNS-namespaced actions (SNS rejects wildcard / foreign
# service actions in SetTopicAttributes).
# -------------------------------------------------------------------
check "topic_policy_actions_in_sns_scope" {
  assert {
    condition = alltrue(flatten([
      for stmt in local.all_topic_policy_statements : [
        for action in try(stmt.actions, []) :
        can(regex("^sns:", lower(action)))
      ]
    ]))
    error_message = "Every action in source/custom/override SNS topic policy statements must be an explicit 'SNS:' namespaced action (no bare '*' and no foreign-service actions)."
  }
}

# -------------------------------------------------------------------
# KMS key + alias for SNS encryption
# -------------------------------------------------------------------
data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "AllowRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateAlias",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DeleteAlias",
      "kms:DescribeKey",
      "kms:DisableKeyRotation",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateAlias",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  count = local.create_resources ? 1 : 0

  description             = "KMS customer managed key used to encrypt Amazon SNS topic data"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms.json
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  count = local.create_resources ? 1 : 0

  name          = local.kms_alias_name
  target_key_id = aws_kms_key.sns[0].key_id
}

# -------------------------------------------------------------------
# SNS topic
# -------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  count = local.create_topic ? 1 : 0

  name                        = var.name
  name_prefix                 = var.name_prefix
  display_name                = var.display_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.content_based_deduplication
  kms_master_key_id           = local.topic_kms_master_key_id

  application_failure_feedback_role_arn    = local.application_feedback_role_arn
  application_success_feedback_role_arn    = local.application_feedback_role_arn
  application_success_feedback_sample_rate = var.application_success_feedback_sample_rate

  firehose_failure_feedback_role_arn    = local.firehose_feedback_role_arn
  firehose_success_feedback_role_arn    = local.firehose_feedback_role_arn
  firehose_success_feedback_sample_rate = var.firehose_success_feedback_sample_rate

  http_failure_feedback_role_arn    = local.http_feedback_role_arn
  http_success_feedback_role_arn    = local.http_feedback_role_arn
  http_success_feedback_sample_rate = var.http_success_feedback_sample_rate

  lambda_failure_feedback_role_arn    = local.lambda_feedback_role_arn
  lambda_success_feedback_role_arn    = local.lambda_feedback_role_arn
  lambda_success_feedback_sample_rate = var.lambda_success_feedback_sample_rate

  sqs_failure_feedback_role_arn    = local.sqs_feedback_role_arn
  sqs_success_feedback_role_arn    = local.sqs_feedback_role_arn
  sqs_success_feedback_sample_rate = var.sqs_success_feedback_sample_rate

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# -------------------------------------------------------------------
# SNS topic policy
# -------------------------------------------------------------------
data "aws_iam_policy_document" "sns_topic" {
  count = local.create_policy ? 1 : 0

  statement {
    sid    = "DefaultOwnerAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "SNS:AddPermission",
      "SNS:DeleteTopic",
      "SNS:GetTopicAttributes",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
      "SNS:Receive",
      "SNS:RemovePermission",
      "SNS:SetTopicAttributes",
      "SNS:Subscribe",
    ]

    resources = [aws_sns_topic.this[0].arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceOwner"
      values   = [local.account_id]
    }
  }

  dynamic "statement" {
    for_each = var.source_policy_statements

    content {
      sid       = try(statement.value.sid, null)
      effect    = try(statement.value.effect, "Allow")
      actions   = try(statement.value.actions, [])
      resources = try(statement.value.resources, [aws_sns_topic.this[0].arn])

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.custom_policy_statements

    content {
      sid       = try(statement.value.sid, null)
      effect    = try(statement.value.effect, "Allow")
      actions   = try(statement.value.actions, [])
      resources = try(statement.value.resources, [aws_sns_topic.this[0].arn])

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.override_policy_statements

    content {
      sid       = try(statement.value.sid, null)
      effect    = try(statement.value.effect, "Allow")
      actions   = try(statement.value.actions, [])
      resources = try(statement.value.resources, [aws_sns_topic.this[0].arn])

      dynamic "principals" {
        for_each = try(statement.value.principals, [])

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sns_topic_policy" "this" {
  count = local.create_policy ? 1 : 0

  arn    = aws_sns_topic.this[0].arn
  policy = data.aws_iam_policy_document.sns_topic[0].json
}

# -------------------------------------------------------------------
# Delivery feedback: assume role policy shared by SNS managed roles
# -------------------------------------------------------------------
data "aws_iam_policy_document" "sns_assume_role" {
  statement {
    sid     = "AllowSnsServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
  }
}

# ----------------------------- SQS --------------------------------
data "aws_iam_policy_document" "sns_delivery_feedback_sqs" {
  count = local.create_sqs_feedback ? 1 : 0

  statement {
    sid       = "AllowSnsDeliveryFeedbackToSqs"
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = local.sqs_policy_resources
  }
}

resource "aws_iam_role" "sns_delivery_feedback_sqs" {
  count = local.create_sqs_feedback ? 1 : 0

  name_prefix        = "sns-feedback-sqs-"
  description        = "Delivery status feedback role for Amazon SNS to SQS endpoints"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "sns_delivery_feedback_sqs" {
  count = local.create_sqs_feedback ? 1 : 0

  name_prefix = "sns-feedback-sqs-"
  description = "Least privilege policy allowing SNS delivery feedback to SQS endpoints"
  policy      = data.aws_iam_policy_document.sns_delivery_feedback_sqs[0].json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_delivery_feedback_sqs" {
  count = local.create_sqs_feedback ? 1 : 0

  role       = aws_iam_role.sns_delivery_feedback_sqs[0].name
  policy_arn = aws_iam_policy.sns_delivery_feedback_sqs[0].arn
}

# ---------------------------- Lambda ------------------------------
data "aws_iam_policy_document" "sns_delivery_feedback_lambda" {
  count = local.create_lambda_feedback ? 1 : 0

  statement {
    sid       = "AllowSnsDeliveryFeedbackToLambda"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.lambda_policy_resources
  }
}

resource "aws_iam_role" "sns_delivery_feedback_lambda" {
  count = local.create_lambda_feedback ? 1 : 0

  name_prefix        = "sns-feedback-lambda-"
  description        = "Delivery status feedback role for Amazon SNS to Lambda endpoints"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "sns_delivery_feedback_lambda" {
  count = local.create_lambda_feedback ? 1 : 0

  name_prefix = "sns-feedback-lambda-"
  description = "Least privilege policy allowing SNS delivery feedback to Lambda endpoints"
  policy      = data.aws_iam_policy_document.sns_delivery_feedback_lambda[0].json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_delivery_feedback_lambda" {
  count = local.create_lambda_feedback ? 1 : 0

  role       = aws_iam_role.sns_delivery_feedback_lambda[0].name
  policy_arn = aws_iam_policy.sns_delivery_feedback_lambda[0].arn
}

# ----------------------------- HTTP -------------------------------
data "aws_iam_policy_document" "sns_delivery_feedback_http" {
  count = local.create_http_feedback ? 1 : 0

  statement {
    sid    = "AllowSnsDeliveryFeedbackToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = local.logs_policy_resources
  }
}

resource "aws_iam_role" "sns_delivery_feedback_http" {
  count = local.create_http_feedback ? 1 : 0

  name_prefix        = "sns-feedback-http-"
  description        = "Delivery status feedback role for Amazon SNS to HTTP/S endpoints"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "sns_delivery_feedback_http" {
  count = local.create_http_feedback ? 1 : 0

  name_prefix = "sns-feedback-http-"
  description = "Least privilege policy allowing SNS delivery feedback to CloudWatch Logs"
  policy      = data.aws_iam_policy_document.sns_delivery_feedback_http[0].json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_delivery_feedback_http" {
  count = local.create_http_feedback ? 1 : 0

  role       = aws_iam_role.sns_delivery_feedback_http[0].name
  policy_arn = aws_iam_policy.sns_delivery_feedback_http[0].arn
}

# --------------------------- Firehose -----------------------------
data "aws_iam_policy_document" "sns_delivery_feedback_firehose" {
  count = local.create_firehose_feedback ? 1 : 0

  statement {
    sid    = "AllowSnsDeliveryFeedbackToFirehose"
    effect = "Allow"

    actions = [
      "firehose:PutRecord",
      "firehose:PutRecordBatch",
    ]

    resources = local.firehose_policy_resources
  }
}

resource "aws_iam_role" "sns_delivery_feedback_firehose" {
  count = local.create_firehose_feedback ? 1 : 0

  name_prefix        = "sns-feedback-firehose-"
  description        = "Delivery status feedback role for Amazon SNS to Kinesis Data Firehose endpoints"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "sns_delivery_feedback_firehose" {
  count = local.create_firehose_feedback ? 1 : 0

  name_prefix = "sns-feedback-firehose-"
  description = "Least privilege policy allowing SNS delivery feedback to Firehose endpoints"
  policy      = data.aws_iam_policy_document.sns_delivery_feedback_firehose[0].json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_delivery_feedback_firehose" {
  count = local.create_firehose_feedback ? 1 : 0

  role       = aws_iam_role.sns_delivery_feedback_firehose[0].name
  policy_arn = aws_iam_policy.sns_delivery_feedback_firehose[0].arn
}

# -------------------------- Application ---------------------------
data "aws_iam_policy_document" "sns_delivery_feedback_application" {
  count = local.create_application_feedback ? 1 : 0

  statement {
    sid    = "AllowSnsDeliveryFeedbackToApplicationEndpoints"
    effect = "Allow"

    actions = [
      "sns:Publish",
    ]

    resources = local.application_policy_resources
  }

  statement {
    sid    = "AllowSnsDeliveryFeedbackToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = local.logs_policy_resources
  }
}

resource "aws_iam_role" "sns_delivery_feedback_application" {
  count = local.create_application_feedback ? 1 : 0

  name_prefix        = "sns-feedback-application-"
  description        = "Delivery status feedback role for Amazon SNS to application endpoints"
  assume_role_policy = data.aws_iam_policy_document.sns_assume_role.json
  tags               = var.tags
}

resource "aws_iam_policy" "sns_delivery_feedback_application" {
  count = local.create_application_feedback ? 1 : 0

  name_prefix = "sns-feedback-application-"
  description = "Least privilege policy allowing SNS delivery feedback for application endpoints"
  policy      = data.aws_iam_policy_document.sns_delivery_feedback_application[0].json
  tags        = var.tags
}

resource "aws_iam_role_policy_attachment" "sns_delivery_feedback_application" {
  count = local.create_application_feedback ? 1 : 0

  role       = aws_iam_role.sns_delivery_feedback_application[0].name
  policy_arn = aws_iam_policy.sns_delivery_feedback_application[0].arn
}

# -------------------------------------------------------------------
# Subscriptions
# -------------------------------------------------------------------
resource "aws_sns_topic_subscription" "this" {
  for_each = local.subscriptions

  topic_arn = aws_sns_topic.this[0].arn
  protocol  = each.value.protocol
  endpoint  = each.value.endpoint

  filter_policy                   = try(each.value.filter_policy, null)
  filter_policy_scope             = try(each.value.filter_policy_scope, null)
  confirmation_timeout_in_minutes = try(each.value.confirmation_timeout_in_minutes, null)
  raw_message_delivery            = try(each.value.raw_message_delivery, false)
  redrive_policy                  = try(each.value.redrive_policy, null)
  delivery_policy                 = try(each.value.delivery_policy, null)
  endpoint_auto_confirms          = try(each.value.endpoint_auto_confirms, false)
}

# -------------------------------------------------------------------
# Variables
# -------------------------------------------------------------------
variable "create_resources" {
  description = "Master toggle that controls whether all SNS resources in this configuration are created."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Mutually exclusive with name_prefix. Must end with '.fifo' for FIFO topics."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || !var.fifo_topic || endswith(var.name, ".fifo")
    error_message = "When fifo_topic is true the topic name must end with '.fifo'."
  }
}

variable "name_prefix" {
  description = "Name prefix for the SNS topic. Mutually exclusive with name."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Human readable display name for the SNS topic."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether the SNS topic is a FIFO topic."
  type        = bool
  default     = false

  validation {
    condition     = !var.fifo_topic || var.content_based_deduplication
    error_message = "content_based_deduplication must be true when fifo_topic is true."
  }
}

variable "content_based_deduplication" {
  description = "Whether content based deduplication is enabled for the FIFO topic."
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "Optional external KMS key ID or ARN used for SNS topic encryption. Defaults to the managed key created by this configuration."
  type        = string
  default     = null
}

variable "sqs_feedback_role_arn" {
  description = "Optional existing IAM role ARN used for SQS delivery feedback. A least-privilege role is created when null."
  type        = string
  default     = null
}

variable "lambda_feedback_role_arn" {
  description = "Optional existing IAM role ARN used for Lambda delivery feedback. A least-privilege role is created when null."
  type        = string
  default     = null
}

variable "http_feedback_role_arn" {
  description = "Optional existing IAM role ARN used for HTTP/S delivery feedback. A least-privilege role is created when null."
  type        = string
  default     = null
}

variable "firehose_feedback_role_arn" {
  description = "Optional existing IAM role ARN used for Firehose delivery feedback. A least-privilege role is created when null."
  type        = string
  default     = null
}

variable "application_feedback_role_arn" {
  description = "Optional existing IAM role ARN used for application endpoint delivery feedback. A least-privilege role is created when null."
  type        = string
  default     = null
}

variable "sqs_success_feedback_sample_rate" {
  description = "Percentage of successful SQS deliveries to log (0-100)."
  type        = number
  default     = null
}

variable "lambda_success_feedback_sample_rate" {
  description = "Percentage of successful Lambda deliveries to log (0-100)."
  type        = number
  default     = null
}

variable "http_success_feedback_sample_rate" {
  description = "Percentage of successful HTTP/S deliveries to log (0-100)."
  type        = number
  default     = null
}

variable "firehose_success_feedback_sample_rate" {
  description = "Percentage of successful Firehose deliveries to log (0-100)."
  type        = number
  default     = null
}

variable "application_success_feedback_sample_rate" {
  description = "Percentage of successful application endpoint deliveries to log (0-100)."
  type        = number
  default     = null
}

variable "subscriptions" {
  description = "Map of SNS topic subscriptions keyed by a unique name. Each entry supports protocol, endpoint, filter_policy, filter_policy_scope, confirmation_timeout_in_minutes, raw_message_delivery, redrive_policy, delivery_policy and endpoint_auto_confirms."
  type        = map(any)
  default     = {}
}

variable "create_topic_policy" {
  description = "Whether to create an IAM topic policy for the SNS topic."
  type        = bool
  default     = true
}

variable "custom_policy_statements" {
  description = "Additional policy statements appended to the SNS topic policy. Actions must be explicit SNS-namespaced actions."
  type        = list(any)
  default     = []
}

variable "override_policy_statements" {
  description = "Policy statements used to override or extend the default SNS topic policy. Actions must be explicit SNS-namespaced actions."
  type        = list(any)
  default     = []
}

variable "source_policy_statements" {
  description = "Policy statements restricting which sources may publish to the SNS topic. Actions must be explicit SNS-namespaced actions."
  type        = list(any)
  default     = []
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default     = {}
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for tagging Ansible test infrastructure."
  type        = string
  default     = "test"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix = "ansible-vpc"

  common_tags = {
    Project     = "ansible"
    Environment = var.environment
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "ansible_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "ansible-vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.ansible_vpc.id
  cidr_block        = "10.0.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "ansible-vpc-private-subnet-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.ansible_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "ansible-vpc-public-subnet-1"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "ansible_igw" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = merge(local.common_tags, {
    Name = "ansible-vpc-igw"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = merge(local.common_tags, {
    Name = "ansible-vpc-public-rt"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route" "public_default_route" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.ansible_igw.id
}

resource "aws_route_table_association" "public_rt_assoc" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_rt.id
}

resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.ansible_vpc.id

  tags = merge(local.common_tags, {
    Name = "ansible-vpc-private-rt"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route_table_association" "private_rt_assoc" {
  subnet_id      = aws_subnet.private_subnet_1.id
  route_table_id = aws_route_table.private_rt.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

variable "name_prefix" {
  description = "Prefix applied to the name of every resource created by this configuration."
  type        = string
  default     = "tgw-hub"
}

variable "environment" {
  description = "Environment name used for tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

locals {
  tags = {
    Project     = "transit-gateway-centralized-routing"
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  # One or more non-overlapping VPCs, each with two public and two private
  # subnets. The map key is the VPC name and is used with for_each so that
  # VPCs/attachments can be added or removed without changing other blocks.
  vpc_config = {
    app = {
      cidr_block           = "10.0.0.0/16"
      public_subnet_cidrs  = ["10.0.0.0/24", "10.0.1.0/24"]
      private_subnet_cidrs = ["10.0.10.0/24", "10.0.11.0/24"]
    }
    data = {
      cidr_block           = "10.1.0.0/16"
      public_subnet_cidrs  = ["10.1.0.0/24", "10.1.1.0/24"]
      private_subnet_cidrs = ["10.1.10.0/24", "10.1.11.0/24"]
    }
  }

  # Flattened subnet maps keyed by "<vpc>-<tier>-<index>".
  public_subnets = merge([
    for vpc_key, vpc in local.vpc_config : {
      for idx, cidr_block in vpc.public_subnet_cidrs :
      "${vpc_key}-public-${idx + 1}" => {
        vpc_key           = vpc_key
        cidr_block        = cidr_block
        availability_zone = data.aws_availability_zones.available.names[idx]
      }
    }
  ]...)

  private_subnets = merge([
    for vpc_key, vpc in local.vpc_config : {
      for idx, cidr_block in vpc.private_subnet_cidrs :
      "${vpc_key}-private-${idx + 1}" => {
        vpc_key           = vpc_key
        cidr_block        = cidr_block
        availability_zone = data.aws_availability_zones.available.names[idx]
      }
    }
  ]...)

  # Every "source VPC -> peer VPC CIDR block" pair used for the TGW routes.
  vpc_peers = {
    for pair in setproduct(keys(local.vpc_config), keys(local.vpc_config)) :
    "${pair[0]}-to-${pair[1]}" => {
      source_vpc_key  = pair[0]
      peer_vpc_key    = pair[1]
      peer_cidr_block = local.vpc_config[pair[1]].cidr_block
    }
    if pair[0] != pair[1]
  }
}

resource "aws_vpc" "this" {
  for_each = local.vpc_config

  cidr_block           = each.value.cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-vpc"
  })
}

resource "aws_internet_gateway" "this" {
  for_each = local.vpc_config

  vpc_id = aws_vpc.this[each.key].id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-igw"
  })
}

resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id                  = aws_vpc.this[each.value.vpc_key].id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = true

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.this[each.value.vpc_key].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.availability_zone

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  for_each = local.vpc_config

  vpc_id = aws_vpc.this[each.key].id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table" "private" {
  for_each = local.vpc_config

  vpc_id = aws_vpc.this[each.key].id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "public_internet" {
  for_each = local.vpc_config

  route_table_id         = aws_route_table.public[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[each.key].id
}

resource "aws_route" "public_to_peer" {
  for_each = local.vpc_peers

  route_table_id         = aws_route_table.public[each.value.source_vpc_key].id
  destination_cidr_block = each.value.peer_cidr_block
  gateway_id             = aws_ec2_transit_gateway.main.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_route" "private_to_peer" {
  for_each = local.vpc_peers

  route_table_id         = aws_route_table.private[each.value.source_vpc_key].id
  destination_cidr_block = each.value.peer_cidr_block
  gateway_id             = aws_ec2_transit_gateway.main.id

  depends_on = [aws_ec2_transit_gateway_vpc_attachment.this]
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[each.value.vpc_key].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.value.vpc_key].id
}

resource "aws_ec2_transit_gateway" "main" {
  description = "Centralized transit gateway for ${var.name_prefix} inter-VPC routing"

  dns_support                     = "enable"
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw"
  })
}

resource "aws_ec2_transit_gateway_vpc_attachment" "this" {
  for_each = local.vpc_config

  transit_gateway_id = aws_ec2_transit_gateway.main.id
  vpc_id             = aws_vpc.this[each.key].id

  subnet_ids = [
    for key, subnet in local.private_subnets :
    aws_subnet.private[key].id
    if subnet.vpc_key == each.key
  ]

  dns_support                                     = "enable"
  transit_gateway_default_route_table_association = false
  transit_gateway_default_route_table_propagation = false

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-tgw-attachment"
  })
}

resource "aws_ec2_transit_gateway_route_table" "main" {
  transit_gateway_id = aws_ec2_transit_gateway.main.id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw-route-table"
  })
}

resource "aws_ec2_transit_gateway_route_table_association" "this" {
  for_each = aws_ec2_transit_gateway_vpc_attachment.this

  transit_gateway_attachment_id  = each.value.id
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.main.id
}

resource "aws_ec2_transit_gateway_route_table_propagation" "this" {
  for_each = aws_ec2_transit_gateway_vpc_attachment.this

  transit_gateway_attachment_id  = each.value.id
  transit_gateway_route_table_id = aws_ec2_transit_gateway_route_table.main.id
}

resource "aws_security_group" "vpc" {
  for_each = local.vpc_config

  name        = "${var.name_prefix}-${each.key}-app-sg"
  description = "Application security group for the ${each.key} VPC: intra-VPC and inter-VPC traffic only"
  vpc_id      = aws_vpc.this[each.key].id

  ingress {
    description = "HTTPS from within the ${each.key} VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [each.value.cidr_block]
  }

  ingress {
    description = "HTTP from within the ${each.key} VPC"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [each.value.cidr_block]
  }

  ingress {
    description = "Inter-VPC traffic from peer VPC CIDR blocks over the transit gateway"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [for key, vpc in local.vpc_config : vpc.cidr_block if key != each.key]
  }

  egress {
    description = "Intra-VPC and inter-VPC traffic only, no unrestricted internet egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = concat(
      [each.value.cidr_block],
      [for key, vpc in local.vpc_config : vpc.cidr_block if key != each.key]
    )
  }

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-${each.key}-app-sg"
  })
}

data "aws_iam_policy_document" "kms_logs" {
  statement {
    sid    = "AllowAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:Describe*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "logs" {
  description             = "KMS key used to encrypt ${var.name_prefix} Transit Gateway flow logs"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_logs.json

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-flow-logs-key"
  })
}

resource "aws_kms_alias" "logs" {
  name          = "alias/${var.name_prefix}-flow-logs"
  target_key_id = aws_kms_key.logs.key_id
}

resource "aws_cloudwatch_log_group" "tgw_flow" {
  name              = "/aws/transit-gateway/${var.name_prefix}/flow-logs"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.logs.arn

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw-flow-logs"
  })
}

data "aws_iam_policy_document" "flow_logs_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "flow_logs" {
  statement {
    sid    = "WriteTransitGatewayFlowLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      aws_cloudwatch_log_group.tgw_flow.arn,
      "${aws_cloudwatch_log_group.tgw_flow.arn}:*",
    ]
  }
}

resource "aws_iam_role" "flow_logs" {
  name               = "${var.name_prefix}-tgw-flow-logs-role"
  assume_role_policy = data.aws_iam_policy_document.flow_logs_assume_role.json

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw-flow-logs-role"
  })
}

resource "aws_iam_policy" "flow_logs" {
  name        = "${var.name_prefix}-tgw-flow-logs-policy"
  description = "Least privilege policy allowing the flow logs service to write Transit Gateway flow logs"
  policy      = data.aws_iam_policy_document.flow_logs.json

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw-flow-logs-policy"
  })
}

resource "aws_iam_role_policy_attachment" "flow_logs" {
  role       = aws_iam_role.flow_logs.name
  policy_arn = aws_iam_policy.flow_logs.arn
}

resource "aws_flow_log" "tgw" {
  traffic_type       = "ALL"
  transit_gateway_id = aws_ec2_transit_gateway.main.id

  log_destination_type     = "cloud-watch-logs"
  log_destination          = aws_cloudwatch_log_group.tgw_flow.arn
  iam_role_arn             = aws_iam_role.flow_logs.arn
  max_aggregation_interval = 60

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-tgw-flow-logs"
  })
}

resource "aws_s3_bucket" "logs" {
  bucket = "${var.name_prefix}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}-flow-logs"

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-log-archive"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.logs.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "logs_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.logs.arn,
      "${aws_s3_bucket.logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = data.aws_iam_policy_document.logs_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.logs]
}

output "transit_gateway_id" {
  description = "ID of the centralized Transit Gateway."
  value       = aws_ec2_transit_gateway.main.id
}

output "transit_gateway_arn" {
  description = "ARN of the centralized Transit Gateway."
  value       = aws_ec2_transit_gateway.main.arn
}

output "transit_gateway_route_table_id" {
  description = "ID of the Transit Gateway route table every VPC attachment associates with and propagates into."
  value       = aws_ec2_transit_gateway_route_table.main.id
}

output "vpc_attachment_ids" {
  description = "Map of VPC name to Transit Gateway VPC attachment ID."
  value       = { for key, attachment in aws_ec2_transit_gateway_vpc_attachment.this : key => attachment.id }
}

output "vpc_ids" {
  description = "Map of VPC name to VPC ID."
  value       = { for key, vpc in aws_vpc.this : key => vpc.id }
}

output "transit_gateway_flow_log_id" {
  description = "ID of the Transit Gateway flow log."
  value       = aws_flow_log.tgw.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project" {
  description = "Project name used to build resource names and tags."
  type        = string
  default     = "dragondrop"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.0.0/24"
  sg_name     = "dragondrop-compute-ecs-fargate-sg"
  name_prefix = "${var.project}-compute"

  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "Terraform"
      Component   = "ecs-fargate"
    },
    var.tags
  )
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_subnet" "fargate" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-subnet"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-rt"
    }
  )
}

resource "aws_route_table_association" "fargate" {
  subnet_id      = aws_subnet.fargate.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "ecs_fargate" {
  name        = local.sg_name
  description = "Outbound-only security group for DragonDrop ECS Fargate tasks, scoped to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = local.sg_name
    }
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.ecs_fargate.id
  description       = "Allow all outbound traffic within the VPC CIDR only."
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.sg_name}-egress-vpc"
    }
  )
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  table_names = {
    raw       = "raw_metrics"
    aggregate = "aggregate_metrics"
  }
}

resource "aws_dynamodb_table" "raw_metrics" {
  name         = local.table_names.raw
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "uuid"

  attribute {
    name = "uuid"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  stream_enabled   = true
  stream_view_type = "NEW_IMAGE"

  ttl {
    enabled        = true
    attribute_name = "expdate"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "aggregate_metrics" {
  name         = local.table_names.aggregate
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "pk"
  range_key    = "sk"

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  attribute {
    name = "identifier"
    type = "S"
  }

  server_side_encryption {
    enabled = true
  }

  point_in_time_recovery {
    enabled = true
  }

  global_secondary_index {
    name            = "IdentifierIndex"
    hash_key        = "identifier"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "instance_type" {
  description = "EC2 instance type used for the Apache web server."
  type        = string
  default     = "t3.micro"
}

variable "server_name" {
  description = "Logical server name used for resource naming and for the served index page."
  type        = string
  default     = "demo"
}

variable "tags" {
  description = "Additional tags merged into every resource created by this configuration."
  type        = map(string)
  default     = {}
}

locals {
  vpc_cidr    = "10.0.0.0/16"
  subnet_cidr = "10.0.1.0/24"

  common_tags = merge(
    {
      Project     = var.server_name
      Environment = "test"
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-public-subnet"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web" {
  name        = "${var.server_name}-web-sg"
  description = "Inbound HTTP from anywhere; egress restricted to the VPC CIDR."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from the internet"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "VPC-internal egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-web-sg"
  })
}

resource "aws_instance" "web" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.instance_type
  subnet_id              = aws_subnet.public.id
  vpc_security_group_ids = [aws_security_group.web.id]

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    encrypted             = true
    volume_type           = "gp3"
    volume_size           = 8
    delete_on_termination = true
  }

  user_data_replace_on_change = true

  user_data = <<-EOT
    #!/bin/bash
    set -euo pipefail

    yum install -y httpd
    systemctl enable --now httpd

    cat > /var/www/html/index.html <<'HTML'
    <!DOCTYPE html>
    <html lang="en">
      <head>
        <meta charset="utf-8" />
        <title>${var.server_name}</title>
      </head>
      <body>
        <h1>Hello from ${var.server_name}</h1>
      </body>
    </html>
    HTML
  EOT

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-web"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_eip" "web" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.server_name}-web-eip"
  })
}

resource "aws_eip_association" "web" {
  allocation_id = aws_eip.web.id
  instance_id   = aws_instance.web.id
}

###############################################################################
# Terraform & Provider Configuration
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables (all have defaults so `terraform apply` runs non-interactively)
###############################################################################

variable "environment" {
  description = "Deployment environment name used for resource tagging."
  type        = string
  default     = "test"
}

variable "project" {
  description = "Project name used for resource tagging."
  type        = string
  default     = "sns-messaging-integration"
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

variable "kms_deletion_window_in_days" {
  description = "Waiting period (in days) before the customer-managed KMS key is permanently deleted."
  type        = number
  default     = 30
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "Terraform"
    },
    var.tags,
  )

  # Map of the two policy-managed SNS topic ARNs, keyed by a stable label.
  # Drives the per-topic policy document so that every policy statement
  # applies to exactly one resource (an SNS requirement).
  policy_topic_arns = {
    topic_with_policy  = aws_sns_topic.topic_with_policy.arn
    topic_with_policy2 = aws_sns_topic.topic_with_policy2.arn
  }

  # Topic-scoped SNS action set that SNS accepts on a topic resource policy.
  # `sns:*` is rejected ("action out of service scope") because it expands to
  # control-plane actions that cannot be granted on a single topic.
  topic_policy_actions = [
    "SNS:Subscribe",
    "SNS:Publish",
    "SNS:Receive",
    "SNS:GetTopicAttributes",
    "SNS:SetTopicAttributes",
    "SNS:AddPermission",
    "SNS:RemovePermission",
    "SNS:DeleteTopic",
    "SNS:ListSubscriptionsByTopic",
  ]
}

###############################################################################
# Data Sources (static provider metadata only — no pre-existing infra lookups)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# KMS Customer-Managed Key (encryption for all three SNS topics)
###############################################################################

# Key policy: the account root retains full key administration, and the SNS
# service principal is granted only the cryptographic actions required to
# deliver messages to KMS-encrypted topics.
data "aws_iam_policy_document" "sns_kms_policy" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowSNSEncryptionActions"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "sns_encryption" {
  description             = "Customer-managed KMS key used to encrypt SNS topics for messaging integration testing"
  enable_key_rotation     = true
  deletion_window_in_days = var.kms_deletion_window_in_days
  policy                  = data.aws_iam_policy_document.sns_kms_policy.json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

# Friendly alias whose name is made per-account unique so repeated applies
# cannot collide with an orphaned alias of the same fixed name.
resource "aws_kms_alias" "sns_encryption" {
  name          = "alias/sns-messaging-integration-${data.aws_caller_identity.current.account_id}"
  target_key_id = aws_kms_key.sns_encryption.key_id
}

###############################################################################
# SNS Topics (all encrypted with the customer-managed KMS key)
###############################################################################

resource "aws_sns_topic" "topic_with_policy" {
  name              = "my-topic-with-policy"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
  tags              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "topic_with_policy2" {
  name              = "my-topic-with-policy2"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
  tags              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic" "user_updates_topic" {
  name              = "user-updates-topic"
  kms_master_key_id = aws_kms_key.sns_encryption.arn
  tags              = local.tags

  # Custom delivery policy controlling retry and throttling behavior.
  # SNS delivery policies are protocol-scoped documents; the retry/throttle
  # configuration must be nested under the endpoint protocol key (e.g. "http").
  delivery_policy = jsonencode({
    http = {
      defaultHealthyRetryPolicy = {
        minDelayTarget     = 20
        maxDelayTarget     = 120
        numRetries         = 6
        numMaxDelayRetries = 3
        numNoDelayRetries  = 0
        numMinDelayRetries = 3
        backoffFunction    = "exponential"
      }
      defaultThrottlePolicy = {
        maxReceivesPerSecond = 1000
      }
      disableSubscriptionOverrides = false
    }
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Shared Topic Policy (one reusable document, per-topic instance)
###############################################################################

# NOTE: The permissive `Principal = "*"` grant below exists SOLELY for messaging
# integration testing and is intentionally bounded to a single named topic ARN
# per statement (SNS requires each statement to apply to exactly one resource).
# All AWS principals are granted the topic-scoped SNS action set — a wildcard
# action is never paired with a wildcard resource, and the actions are limited
# to those SNS accepts within a topic resource policy. The `user-updates-topic`
# topic deliberately does NOT receive this policy.
data "aws_iam_policy_document" "topic_policy" {
  for_each = local.policy_topic_arns

  statement {
    sid    = "AllowAllPrincipalsFullSNSAccessOnIntegrationTestTopics"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = local.topic_policy_actions

    resources = [each.value]
  }
}

# The same reusable policy document is attached to each policy-managed topic
# via its own per-topic instance, scoped to that topic's ARN only.
resource "aws_sns_topic_policy" "topic_with_policy" {
  arn    = aws_sns_topic.topic_with_policy.arn
  policy = data.aws_iam_policy_document.topic_policy["topic_with_policy"].json
}

resource "aws_sns_topic_policy" "topic_with_policy2" {
  arn    = aws_sns_topic.topic_with_policy2.arn
  policy = data.aws_iam_policy_document.topic_policy["topic_with_policy2"].json
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  name_prefix = "test-vpc"
  common_tags = {
    Project     = "test-vpc"
    Environment = "test"
    ManagedBy   = "terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-main"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_eip" "standalone" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-standalone-eip"
  })
}

output "vpc_id" {
  description = "ID of the created VPC"
  value       = aws_vpc.main.id
}

output "public_subnet_id" {
  description = "ID of the public subnet"
  value       = aws_subnet.public.id
}

output "private_subnet_id" {
  description = "ID of the private subnet"
  value       = aws_subnet.private.id
}

output "eip_public_ip" {
  description = "Public IP address of the standalone Elastic IP"
  value       = aws_eip.standalone.public_ip
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (all with defaults so `terraform apply` runs unattended)
###############################################################################

variable "project" {
  description = "Project name used as a prefix for resource names and tags."
  type        = string
  default     = "container-platform"
}

variable "environment" {
  description = "Deployment environment (dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "RFC1918 CIDR block for the VPC. Must not overlap existing networks."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "The vpc_cidr value must be a valid CIDR block (e.g. 10.0.0.0/16)."
  }
}

variable "tags" {
  description = "Additional tags applied to every taggable resource in this stack."
  type        = map(string)
  default = {
    Owner = "platform-team"
  }
}

###############################################################################
# Data sources (static provider metadata only - greenfield account)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  # Only the first two AZs of the region are used; never hardcode us-east-1a/b.
  azs = [
    data.aws_availability_zones.available.names[0],
    data.aws_availability_zones.available.names[1],
  ]

  name_prefix = "${var.project}-${var.environment}"

  common_tags = merge(
    var.tags,
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
      Region      = data.aws_region.current.name
    }
  )

  # ---------------------------------------------------------------------------
  # Security group ingress rules (discrete aws_vpc_security_group_ingress_rule
  # resources are used exclusively - no inline ingress/egress blocks exist on
  # aws_security_group.app, so there is no rule drift between the two styles).
  #
  # NOTE / DEVIATION FROM LEAST PRIVILEGE:
  #   * Ports 3000 (application) and 5432 (PostgreSQL) are opened to 0.0.0.0/0
  #     ONLY because that is an explicit requirement of this request. Exposing
  #     them to the internet is NOT least privilege and should be narrowed to
  #     known CIDR ranges, a VPN/bastion range, or referenced VPC-internal
  #     security groups before production use.
  #   * SSH (22) is intentionally restricted to the VPC CIDR - never 0.0.0.0/0.
  # ---------------------------------------------------------------------------
  ingress_rules = {
    ssh_from_vpc = {
      description = "SSH from within the VPC CIDR only (bastion / app instances)"
      from_port   = 22
      to_port     = 22
      ip_protocol = "tcp"
      cidr_ipv4   = var.vpc_cidr
    }
    http_public = {
      description = "HTTP from anywhere"
      from_port   = 80
      to_port     = 80
      ip_protocol = "tcp"
      cidr_ipv4   = "0.0.0.0/0"
    }
    https_public = {
      description = "HTTPS from anywhere"
      from_port   = 443
      to_port     = 443
      ip_protocol = "tcp"
      cidr_ipv4   = "0.0.0.0/0"
    }
    app_3000_public = {
      description = "Application port 3000 from anywhere - explicit requirement, restrict before production"
      from_port   = 3000
      to_port     = 3000
      ip_protocol = "tcp"
      cidr_ipv4   = "0.0.0.0/0"
    }
    postgres_5432_public = {
      description = "PostgreSQL 5432 from anywhere - explicit requirement, NOT least privilege, restrict to VPN/known CIDRs before production"
      from_port   = 5432
      to_port     = 5432
      ip_protocol = "tcp"
      cidr_ipv4   = "0.0.0.0/0"
    }
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr

  # enable_dns_hostnames is mandatory for resolving the Service Discovery
  # private DNS namespace below.
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

# Public subnets are public because their route table has a 0.0.0.0/0 route to
# the internet gateway - not because of map_public_ip_on_launch. The flag is set
# to false so instances/ENIs do not receive a public IPv4 by default; a workload
# that genuinely needs one can be given an explicit, auditable EIP association.
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 0)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-a"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 1)
  availability_zone       = local.azs[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-b"
      Tier = "public"
    }
  )
}

# Private subnets never map public IPs on launch.
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 2)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-a"
      Tier = "private"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, 3)
  availability_zone       = local.azs[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-b"
      Tier = "private"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

###############################################################################
# NAT (exactly ONE gateway - deliberate cost decision)
#
# A single NAT gateway lives in public_a (the first AZ). All private subnets
# route through it, which makes it a cross-AZ single point of failure for
# private egress. The NAT gateway's public address comes from the explicitly
# associated aws_eip.nat, so it is unaffected by map_public_ip_on_launch.
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat-eip"
    }
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public_a.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-nat"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Route tables
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-public-rt"
    }
  )
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  for_each = {
    public_a = aws_subnet.public_a.id
    public_b = aws_subnet.public_b.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.public.id
}

# One private route table serves both private subnets (single NAT).
resource "aws_route_table_association" "private" {
  for_each = {
    private_a = aws_subnet.private_a.id
    private_b = aws_subnet.private_b.id
  }

  subnet_id      = each.value
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Application security group
#
# Only discrete aws_vpc_security_group_ingress_rule / _egress_rule resources are
# used - the security group itself declares no inline ingress/egress blocks.
###############################################################################

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app-sg"
  description = "Fronts the containerized workloads; SSH restricted to the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-app-sg"
    }
  )
}

resource "aws_vpc_security_group_ingress_rule" "app" {
  for_each = local.ingress_rules

  security_group_id = aws_security_group.app.id
  description       = each.value.description
  cidr_ipv4         = each.value.cidr_ipv4
  ip_protocol       = each.value.ip_protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port
}

# -----------------------------------------------------------------------------
# Egress is restricted to the VPC CIDR only (all protocols) - no 0.0.0.0/0.
#
# NOTE: this intentionally blocks container image pulls (ECR/Docker Hub) and OS
# package installs that would otherwise traverse the NAT gateway. If internet
# egress is genuinely required, add aws_vpc_security_group_egress_rule resources
# for the S3 and ECR interface endpoints / prefix lists (e.g. via
# data "aws_ec2_managed_prefix_list") scoped to the minimum ports needed.
# -----------------------------------------------------------------------------
resource "aws_vpc_security_group_egress_rule" "vpc_only" {
  security_group_id = aws_security_group.app.id
  description       = "All outbound traffic restricted to the VPC CIDR"
  cidr_ipv4         = aws_vpc.main.cidr_block
  ip_protocol       = "-1"
}

###############################################################################
# Service Discovery private DNS namespace
###############################################################################

resource "aws_service_discovery_private_dns_namespace" "service" {
  name        = "service.local"
  description = "Private DNS namespace for container task registration and service-to-service discovery within the VPC"
  vpc         = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "service.local"
    }
  )
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  # No backend block: remote state is managed by the deployment harness.
  # No provider block: the provider (region = "us-east-1") is injected
  # by the deployment harness.
}

##############################################################################
# Static provider metadata
# (pure provider lookups only - no pre-existing infrastructure is discovered)
##############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

##############################################################################
# Common naming and tagging
##############################################################################

locals {
  project     = "benchmark-backup"
  environment = "prod"

  vault_name = "benchmark-backup-vault"
  kms_alias  = "alias/benchmark-backup-vault"

  # Retention for recovery points. This value MUST fall strictly inside the
  # vault-lock retention window configured below (min 7 / max 90 days),
  # otherwise AWS Backup rejects recovery point creation.
  backup_retention_days = 30

  tags = {
    Project     = local.project
    Environment = local.environment
    ManagedBy   = "Terraform"
  }
}

##############################################################################
# Customer managed KMS key dedicated to AWS Backup
##############################################################################

resource "aws_kms_key" "backup" {
  description = "CMK used by AWS Backup to encrypt recovery points in ${local.vault_name}"
  key_usage   = "ENCRYPT_DECRYPT"

  enable_key_rotation     = true
  deletion_window_in_days = 30

  # Key administration for the account root (no wildcard action alongside a
  # wildcard resource: actions are enumerated explicitly).
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:CreateAlias",
          "kms:DeleteAlias",
          "kms:DescribeKey",
          "kms:GetKeyPolicy",
          "kms:PutKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:EnableKeyRotation",
          "kms:DisableKeyRotation",
          "kms:RotateKeyOnDemand",
          "kms:EnableKey",
          "kms:DisableKey",
          "kms:UpdateKeyDescription",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ListResourceTags",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:CreateGrant",
          "kms:ListGrants",
          "kms:RevokeGrant",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupToUseTheKey"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowAwsBackupToCreateGrantsForAwsResources"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action   = "kms:CreateGrant"
        Resource = "*"
        Condition = {
          Bool = {
            "kms:GrantIsForAWSResource" = "true"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "backup" {
  name          = local.kms_alias
  target_key_id = aws_kms_key.backup.key_id
}

##############################################################################
# Backup vault - encrypted with the CMK
##############################################################################

resource "aws_backup_vault" "backup" {
  name        = local.vault_name
  kms_key_arn = aws_kms_key.backup.arn

  tags = local.tags

  # The vault holds immutable recovery points: never allow it to be destroyed
  # by a plan/apply cycle.
  lifecycle {
    prevent_destroy = true
  }
}

##############################################################################
# Backup vault lock - enforces the 7-90 day retention window
##############################################################################

# WARNING: the vault lock is IRREVERSIBLE once the grace period
# (changeable_for_days) has elapsed and the vault enters compliance mode.
# Recovery points can never be deleted before min_retention_days, and are
# always deleted by max_retention_days. Verify min/max retention and the
# grace period BEFORE applying - they cannot be relaxed afterwards.
resource "aws_backup_vault_lock_configuration" "backup" {
  backup_vault_name = aws_backup_vault.backup.name

  min_retention_days  = 7
  max_retention_days  = 90
  changeable_for_days = 3

  # The vault must exist before the lock is applied.
  depends_on = [aws_backup_vault.backup]
}

##############################################################################
# IAM role assumed by the AWS Backup service
##############################################################################

resource "aws_iam_role" "backup" {
  name        = "${local.project}-backup-role"
  description = "Service role assumed by AWS Backup to create and restore recovery points"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAwsBackupServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "restore" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

##############################################################################
# Backup plan - daily scheduled rule targeting the locked vault
##############################################################################

resource "aws_backup_plan" "backup" {
  name = "${local.project}-plan"

  rule {
    rule_name         = "${local.project}-daily-rule"
    target_vault_name = aws_backup_vault.backup.name
    schedule          = "cron(0 5 * * ? *)"

    start_window      = 60
    completion_window = 180

    lifecycle {
      # delete_after must be inside the vault lock window (7 - 90 days).
      delete_after = local.backup_retention_days
    }

    recovery_point_tags = local.tags
  }

  tags = local.tags

  depends_on = [aws_backup_vault.backup]
}

##############################################################################
# Backup selection - tag based (tag:benchmark-backup = true)
##############################################################################

resource "aws_backup_selection" "backup" {
  name         = "${local.project}-selection"
  plan_id      = aws_backup_plan.backup.id
  iam_role_arn = aws_iam_role.backup.arn

  # No explicit `resources` list: membership is driven entirely by tags so any
  # resource tagged benchmark-backup = true is picked up automatically.
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "benchmark-backup"
    value = "true"
  }

  depends_on = [aws_iam_role_policy_attachment.backup]
}

# ---------------------------------------------------------------------------
# Terraform / provider requirements
# NOTE: No `terraform { backend { ... } }` block is declared — backend
# configuration is managed externally by the deployment harness. The AWS
# provider configuration (region) is injected by the harness as well.
# ---------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Static provider metadata (account id / region) used to build Cognito ARNs.
# These are pure provider metadata lookups — NOT discovery of pre-existing
# infrastructure (this is a greenfield account).
# ---------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# Variables
# ---------------------------------------------------------------------------
variable "project" {
  description = "Project name used as a prefix for all resource names."
  type        = string
  default     = "cognito-mobile"
}

variable "environment" {
  description = "Deployment environment (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------
# Locals
#
# NOTE: `aws_cognito_user_pool_client` does not expose a `tags` argument in the
# hashicorp/aws ~> 5.0 provider schema, so it is intentionally excluded from
# the set of taggable resources. Tags are applied to the user pool, identity
# pool, and IAM role.
#
# NOTE: Amazon Cognito Sync is on a deprecation path. Keep the `cognito-sync`
# IAM grants only for as long as the legacy API is required. For new offline
# user-data sync workloads prefer AWS AppSync / Amplify DataStore.
# ---------------------------------------------------------------------------
locals {
  name_prefix = "${var.project}-${var.environment}"

  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )

  cognito_sync_arn = "arn:aws:cognito-sync:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/*"
}

# ---------------------------------------------------------------------------
# Cognito User Pool
# Advanced security (threat protection) is configured via the nested
# `user_pool_add_ons` block at the AUDIT tier — this does not force the paid
# ENFORCED tier.
#
# MFA is OPTIONAL and backed by a concrete software-token (TOTP) factor.
# Cognito rejects OPTIONAL/ON without at least one enabled factor, so the
# `software_token_mfa_configuration` block is required. TOTP needs no SMS/SNS
# setup and no validated phone numbers, keeping the deployment self-contained.
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  user_pool_add_ons {
    advanced_security_mode = "AUDIT"
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_CODE"
    email_subject        = "Verify your ${var.project} account"
    email_message        = "Your verification code is {####}. Please enter it to confirm your ${var.project} account."
  }

  deletion_protection = "ACTIVE"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-pool"
  })
}

# ---------------------------------------------------------------------------
# App client (public mobile / SPA client — no client secret generated).
# No OAuth/hosted-UI flows are enabled, so no user pool domain is required.
# This resource does not support tags in the current provider schema.
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"

  read_attributes = [
    "email",
    "email_verified",
    "name",
  ]

  write_attributes = [
    "email",
    "name",
  ]

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  enable_token_revocation = true
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool linked to the User Pool app client.
# `allow_unauthenticated_identities = false` means NO guest access is possible;
# see the comment below regarding the unauthenticated role.
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "${local.name_prefix}-identity-pool"
  allow_unauthenticated_identities = false
  allow_classic_flow               = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = "cognito-idp.${data.aws_region.current.name}.amazonaws.com/${aws_cognito_user_pool.main.id}"
    server_side_token_check = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-identity-pool"
  })
}

# ---------------------------------------------------------------------------
# IAM role for AUTHENTICATED identities only.
# Because allow_unauthenticated_identities = false, there is intentionally no
# unauthenticated role created here — guest/unauthenticated access cannot be
# granted accidentally.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name               = "${local.name_prefix}-authenticated"
  description        = "Role assumed by authenticated Cognito identities for Cognito Sync and Mobile Analytics."
  assume_role_policy = data.aws_iam_policy_document.authenticated_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-authenticated"
  })
}

# ---------------------------------------------------------------------------
# Least-privilege inline policy for the authenticated role.
#   - cognito-sync:* scoped to the identity pool ARN (never "*")
#   - mobileanalytics:PutEvents on "*" (the API has no resource-level scoping)
# Actions and Resources are never both "*" within a single statement.
# ---------------------------------------------------------------------------
data "aws_iam_policy_document" "authenticated" {
  statement {
    sid     = "CognitoSyncAccess"
    effect  = "Allow"
    actions = ["cognito-sync:*"]

    resources = [local.cognito_sync_arn]
  }

  statement {
    sid     = "MobileAnalyticsPutEvents"
    effect  = "Allow"
    actions = ["mobileanalytics:PutEvents"]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${local.name_prefix}-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated.json
}

# ---------------------------------------------------------------------------
# Wire the identity pool to the authenticated role via Terraform references.
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name used for tagging all resources."
  type        = string
  default     = "test"
}

variable "project_name" {
  description = "Project name used for tagging and resource naming."
  type        = string
  default     = "custom-vpc"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-vpc"
  })
}

resource "aws_subnet" "main" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-igw"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-rt"
  })
}

resource "aws_route" "default" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

resource "aws_eip" "main" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-eip"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = "us-east-1.compute.internal"
  domain_name_servers = ["8.8.8.8", "8.8.4.4"]

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-dhcp-options"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from within the VPC CIDR only"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTPS from within the VPC CIDR only"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Egress restricted to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project_name}-default-sg"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  project     = "event-pipeline"
  environment = "prod"

  common_tags = {
    Project     = local.project
    Environment = local.environment
    ManagedBy   = "Terraform"
  }

  sns_topic_name = "event-topic"
  api_name       = "event-api"
  stage_name     = "prod"

  # SNS Publish integration endpoint for API Gateway in this partition/region.
  sns_publish_uri = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.name}:sns:path//"

  # Velocity template that converts the incoming POST body into SNS Publish params.
  sns_publish_template = <<-EOT
    Action=Publish&TopicArn=$util.urlEncode("${aws_sns_topic.event_topic.arn}")&Message=$util.urlEncode($input.body)
  EOT

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

###############################################################################
# KMS key dedicated to the event-topic SNS topic
###############################################################################

resource "aws_kms_key" "event_topic" {
  description             = "Customer managed key for the ${local.sns_topic_name} SNS topic"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "event_topic" {
  name          = "alias/${local.sns_topic_name}"
  target_key_id = aws_kms_key.event_topic.key_id
}

data "aws_iam_policy_document" "event_topic_kms" {
  statement {
    sid    = "KeyAdministrationByAccount"
    effect = "Allow"

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:DescribeKey",
      "kms:DisableKeyRotation",
      "kms:EnableKeyRotation",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    resources = [aws_kms_key.event_topic.arn]
  }

  statement {
    sid    = "AllowSnsServiceUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    resources = [aws_kms_key.event_topic.arn]
  }

  statement {
    sid    = "AllowApiGatewayRoleUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.api_gateway_sns.arn]
    }

    resources = [aws_kms_key.event_topic.arn]
  }
}

resource "aws_kms_key_policy" "event_topic" {
  key_id = aws_kms_key.event_topic.id
  policy = data.aws_iam_policy_document.event_topic_kms.json
}

###############################################################################
# SNS topic
###############################################################################

resource "aws_sns_topic" "event_topic" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.event_topic.arn

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "event_topic" {
  statement {
    sid    = "AllowApiGatewayRolePublish"
    effect = "Allow"

    actions = ["sns:Publish"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.api_gateway_sns.arn]
    }

    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    actions = [
      "sns:Publish",
      "sns:Subscribe",
    ]

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    resources = [aws_sns_topic.event_topic.arn]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_sns_topic_policy" "event_topic" {
  arn    = aws_sns_topic.event_topic.arn
  policy = data.aws_iam_policy_document.event_topic.json
}

###############################################################################
# IAM role assumed by API Gateway to publish to SNS
###############################################################################

data "aws_iam_policy_document" "api_gateway_assume_role" {
  statement {
    sid     = "AllowApiGatewayServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_iam_role" "api_gateway_sns" {
  name                 = "api-gateway-sns-publish-role"
  description          = "Allows API Gateway to publish messages to the ${local.sns_topic_name} SNS topic"
  assume_role_policy   = data.aws_iam_policy_document.api_gateway_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "api_gateway_sns_publish" {
  statement {
    sid       = "PublishToEventTopic"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.event_topic.arn]
  }

  statement {
    sid    = "UseEventTopicKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.event_topic.arn]
  }
}

resource "aws_iam_role_policy" "api_gateway_sns_publish" {
  name   = "api-gateway-sns-publish"
  role   = aws_iam_role.api_gateway_sns.id
  policy = data.aws_iam_policy_document.api_gateway_sns_publish.json
}

###############################################################################
# API Gateway REST API
###############################################################################

resource "aws_api_gateway_rest_api" "event_api" {
  name        = local.api_name
  description = "REST API that publishes incoming POST requests to the ${local.sns_topic_name} SNS topic"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_resource" "events" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  parent_id   = aws_api_gateway_rest_api.event_api.root_resource_id
  path_part   = "events"
}

resource "aws_api_gateway_method" "events_post" {
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  resource_id   = aws_api_gateway_resource.events.id
  http_method   = "POST"
  authorization = "AWS_IAM"

  request_validator_id = null
}

resource "aws_api_gateway_integration" "events_sns" {
  rest_api_id             = aws_api_gateway_rest_api.event_api.id
  resource_id             = aws_api_gateway_resource.events.id
  http_method             = aws_api_gateway_method.events_post.http_method
  type                    = "AWS"
  integration_http_method = "POST"
  uri                     = local.sns_publish_uri
  credentials             = aws_iam_role.api_gateway_sns.arn

  request_parameters = {
    "integration.request.header.Content-Type" = "'application/x-www-form-urlencoded'"
  }

  request_templates = {
    "application/json" = local.sns_publish_template
  }

  passthrough_behavior = "NEVER"
}

###############################################################################
# Method / integration responses
###############################################################################

resource "aws_api_gateway_method_response" "events_post_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = "200"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "events_sns_200" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = aws_api_gateway_method_response.events_post_200.status_code

  response_templates = {
    "application/json" = jsonencode({ message = "event accepted" })
  }

  depends_on = [aws_api_gateway_integration.events_sns]
}

resource "aws_api_gateway_method_response" "events_post_400" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = "400"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "events_sns_400" {
  rest_api_id       = aws_api_gateway_rest_api.event_api.id
  resource_id       = aws_api_gateway_resource.events.id
  http_method       = aws_api_gateway_method.events_post.http_method
  status_code       = aws_api_gateway_method_response.events_post_400.status_code
  selection_pattern = "4\\d{2}"

  response_templates = {
    "application/json" = jsonencode({ message = "request rejected" })
  }

  depends_on = [aws_api_gateway_integration.events_sns]
}

resource "aws_api_gateway_method_response" "events_post_500" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  resource_id = aws_api_gateway_resource.events.id
  http_method = aws_api_gateway_method.events_post.http_method
  status_code = "500"

  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration_response" "events_sns_500" {
  rest_api_id       = aws_api_gateway_rest_api.event_api.id
  resource_id       = aws_api_gateway_resource.events.id
  http_method       = aws_api_gateway_method.events_post.http_method
  status_code       = aws_api_gateway_method_response.events_post_500.status_code
  selection_pattern = "5\\d{2}"

  response_templates = {
    "application/json" = jsonencode({ message = "unable to process event" })
  }

  depends_on = [aws_api_gateway_integration.events_sns]
}

resource "aws_api_gateway_gateway_response" "default_4xx" {
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  response_type = "DEFAULT_4XX"

  response_parameters = {
    "gatewayresponse.header.Content-Type" = "'application/json'"
  }

  response_templates = {
    "application/json" = jsonencode({ message = "request rejected" })
  }
}

resource "aws_api_gateway_gateway_response" "default_5xx" {
  rest_api_id   = aws_api_gateway_rest_api.event_api.id
  response_type = "DEFAULT_5XX"

  response_parameters = {
    "gatewayresponse.header.Content-Type" = "'application/json'"
  }

  response_templates = {
    "application/json" = jsonencode({ message = "unable to process event" })
  }
}

###############################################################################
# Deployment and stage
###############################################################################

resource "aws_api_gateway_deployment" "event_api" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.events.id,
      aws_api_gateway_method.events_post.id,
      aws_api_gateway_integration.events_sns.id,
      aws_api_gateway_method_response.events_post_200.id,
      aws_api_gateway_integration_response.events_sns_200.id,
      aws_api_gateway_method_response.events_post_400.id,
      aws_api_gateway_integration_response.events_sns_400.id,
      aws_api_gateway_method_response.events_post_500.id,
      aws_api_gateway_integration_response.events_sns_500.id,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    aws_api_gateway_integration.events_sns,
    aws_api_gateway_integration_response.events_sns_200,
    aws_api_gateway_integration_response.events_sns_400,
    aws_api_gateway_integration_response.events_sns_500,
  ]
}

resource "aws_api_gateway_stage" "prod" {
  rest_api_id          = aws_api_gateway_rest_api.event_api.id
  deployment_id        = aws_api_gateway_deployment.event_api.id
  stage_name           = local.stage_name
  description          = "Production stage for ${local.api_name}"
  xray_tracing_enabled = true

  tags = local.common_tags
}

resource "aws_api_gateway_method_settings" "prod" {
  rest_api_id = aws_api_gateway_rest_api.event_api.id
  stage_name  = aws_api_gateway_stage.prod.stage_name
  method_path = "*/*"

  settings {
    metrics_enabled        = true
    logging_level          = "OFF"
    data_trace_enabled     = false
    throttling_rate_limit  = 100
    throttling_burst_limit = 200
  }
}

###############################################################################
# Outputs
###############################################################################

output "api_invoke_url" {
  description = "Invoke URL for the POST /events endpoint"
  value       = "${aws_api_gateway_stage.prod.invoke_url}/events"
}

output "event_topic_arn" {
  description = "ARN of the SNS event topic"
  value       = aws_sns_topic.event_topic.arn
}

output "event_topic_kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the SNS topic"
  value       = aws_kms_key.event_topic.arn
}

output "api_gateway_sns_role_arn" {
  description = "ARN of the IAM role API Gateway assumes to publish to SNS"
  value       = aws_iam_role.api_gateway_sns.arn
}

output "api_gateway_rest_api_id" {
  description = "ID of the REST API"
  value       = aws_api_gateway_rest_api.event_api.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region into which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the custom VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets."
  type        = list(string)
  default     = ["10.0.3.0/24", "10.0.4.0/24"]
}

locals {
  any_ipv4_cidr = "0.0.0.0/0"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "terraform-aws-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "terraform-aws-vpc-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = local.any_ipv4_cidr
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "terraform-aws-vpc-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "terraform-aws-vpc-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "terraform-aws-vpc-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = local.any_ipv4_cidr
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "terraform-aws-vpc-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the ntier primary VPC."
  type        = string
  default     = "10.10.0.0/16"
}

variable "environment" {
  description = "Deployment environment name applied to every resource tag."
  type        = string
  default     = "production"
}

variable "common_tags" {
  description = "Additional tags merged into every resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_name = "ntier primary"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.common_tags,
  )
}

###############################################################################
# Availability Zones
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = local.vpc_name
      Tier = "network"
    },
  )
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-igw"
      Tier = "network"
    },
  )
}

###############################################################################
# Subnets - first tier
#
# Public-tier membership is conveyed by aws_route_table_association, NOT by
# subnet-level public IP auto-assignment. map_public_ip_on_launch is left
# false on every subnet so instances never receive a public IP implicitly;
# outbound/inbound addressing must be granted explicitly at the instance or
# launch-template layer.
###############################################################################

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-web"
      Tier = "web"
    },
  )
}

resource "aws_subnet" "app" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-app"
      Tier = "app"
    },
  )
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-database"
      Tier = "database"
    },
  )
}

resource "aws_subnet" "management" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.4.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-management"
      Tier = "management"
    },
  )
}

###############################################################################
# Subnets - duplicate second tier
###############################################################################

resource "aws_subnet" "web2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-web2"
      Tier = "web"
    },
  )
}

resource "aws_subnet" "app2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.12.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-app2"
      Tier = "app"
    },
  )
}

resource "aws_subnet" "database2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.10.13.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-database2"
      Tier = "database"
    },
  )
}

###############################################################################
# Route tables
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-public-rt"
      Tier = "public"
    },
  )
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.vpc_name}-private-rt"
      Tier = "private"
    },
  )
}

###############################################################################
# Routes
###############################################################################

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# NOTE: This route targets the internet gateway per the request. A truly
# isolated private tier should instead route 0.0.0.0/0 to a NAT gateway
# (aws_nat_gateway) placed in a public subnet, with an Elastic IP and the
# associated private route table entries.
resource "aws_route" "private_internet" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

###############################################################################
# Route table associations - public tier
###############################################################################

resource "aws_route_table_association" "web_public" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "management_public" {
  subnet_id      = aws_subnet.management.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "web2_public" {
  subnet_id      = aws_subnet.web2.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Route table associations - private tier
###############################################################################

resource "aws_route_table_association" "app_private" {
  subnet_id      = aws_subnet.app.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database_private" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "app2_private" {
  subnet_id      = aws_subnet.app2.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "database2_private" {
  subnet_id      = aws_subnet.database2.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the ntier primary VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

output "subnet_ids" {
  description = "Map of subnet names to subnet IDs."
  value = {
    web        = aws_subnet.web.id
    app        = aws_subnet.app.id
    database   = aws_subnet.database.id
    management = aws_subnet.management.id
    web2       = aws_subnet.web2.id
    app2       = aws_subnet.app2.id
    database2  = aws_subnet.database2.id
  }
}

output "public_subnet_ids" {
  description = "Subnet IDs associated with the public route table."
  value = [
    aws_subnet.web.id,
    aws_subnet.management.id,
    aws_subnet.web2.id,
  ]
}

output "private_subnet_ids" {
  description = "Subnet IDs associated with the private route table."
  value = [
    aws_subnet.app.id,
    aws_subnet.database.id,
    aws_subnet.app2.id,
    aws_subnet.database2.id,
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------

variable "create_standard" {
  description = "Create a standard customer-managed KMS key with AWS-provided key material"
  type        = bool
  default     = true
}

variable "create_external" {
  description = "Create an external KMS key with imported key material"
  type        = bool
  default     = false
}

variable "create_replica" {
  description = "Create a standard multi-region replica key"
  type        = bool
  default     = false
}

variable "create_replica_external" {
  description = "Create a replica external key (replica of an external primary multi-region key)"
  type        = bool
  default     = false
}

variable "description" {
  description = "Description of the KMS key"
  type        = string
  default     = "Managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Waiting period for scheduled key deletion"
  type        = number
  default     = 30
}

variable "external_key_material_base64" {
  description = "Base64-encoded key material for external keys (sensitive)"
  type        = string
  sensitive   = true
  default     = null
}

variable "primary_key_arn" {
  description = "ARN of the primary key for standard replica"
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary external key for replica external"
  type        = string
  default     = null
}

variable "aws_account_id" {
  description = "AWS account ID for the root principal in the key policy. Required when no override_policy_document is provided."
  type        = string
  default     = ""
}

variable "key_owners" {
  description = "List of IAM ARNs that are key owners (full access)"
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "List of IAM ARNs that are key administrators"
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM ARNs that are standard key users"
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "List of IAM ARNs that are service users"
  type        = list(string)
  default     = []
}

variable "autoscaling_role_arns" {
  description = "List of IAM ARNs for EC2 Auto Scaling roles"
  type        = list(string)
  default     = []
}

variable "hmac_users" {
  description = "List of IAM ARNs for HMAC users"
  type        = list(string)
  default     = []
}

variable "asymmetric_encrypt_users" {
  description = "List of IAM ARNs for asymmetric public encryption users"
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "List of IAM ARNs for asymmetric sign/verify users"
  type        = list(string)
  default     = []
}

variable "route53_dnssec_principals" {
  description = "List of IAM ARNs for Route 53 DNSSEC signing"
  type        = list(string)
  default     = []
}

variable "custom_policy_statements" {
  description = "List of custom policy statements (each object with sid, effect, principals, actions, resources, conditions)"
  type = list(object({
    sid    = string
    effect = string
    principals = object({
      type        = string
      identifiers = list(string)
    })
    actions   = list(string)
    resources = list(string)
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "override_policy_document" {
  description = "JSON policy document to override the generated policy"
  type        = string
  default     = null
}

variable "alias_name" {
  description = "Exact alias name (e.g., alias/my-key)"
  type        = string
  default     = null
}

variable "alias_name_prefix" {
  description = "Alias name prefix (e.g., alias/my-app-)"
  type        = string
  default     = null
}

variable "grants" {
  description = "List of KMS grants to create"
  type = list(object({
    grantee_principal = string
    operations        = list(string)
    retiring_principal = optional(string)
    constraints       = optional(list(object({
      key   = string
      value = string
    })))
  }))
  default = []
}

# ----------------------------------------------------------------------
# Validation: exactly one creation flag must be true
# ----------------------------------------------------------------------

check "mutual_exclusion" {
  assert {
    condition = (
      (var.create_standard ? 1 : 0) +
      (var.create_external ? 1 : 0) +
      (var.create_replica ? 1 : 0) +
      (var.create_replica_external ? 1 : 0)
    ) == 1
    error_message = "Exactly one of create_standard, create_external, create_replica, create_replica_external must be true."
  }
}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------

locals {
  # Map of role types to their actions and variable references
  role_statements = {
    key_owners = {
      principals = var.key_owners
      actions    = ["kms:*"]
    }
    key_administrators = {
      principals = var.key_administrators
      actions    = [
        "kms:Describe*", "kms:Put*", "kms:Update*", "kms:Revoke*",
        "kms:Disable*", "kms:Get*", "kms:TagResource", "kms:UntagResource",
        "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion"
      ]
    }
    key_users = {
      principals = var.key_users
      actions    = [
        "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*",
        "kms:GenerateDataKey*", "kms:DescribeKey", "kms:GetPublicKey"
      ]
    }
    service_users = {
      principals = var.service_users
      actions    = [
        "kms:Encrypt", "kms:Decrypt", "kms:ReEncrypt*",
        "kms:GenerateDataKey*", "kms:DescribeKey"
      ]
    }
    autoscaling_roles = {
      principals = var.autoscaling_role_arns
      actions    = [
        "kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*",
        "kms:DescribeKey", "kms:CreateGrant", "kms:ListGrants", "kms:RevokeGrant"
      ]
    }
    hmac_users = {
      principals = var.hmac_users
      actions    = ["kms:GenerateMac", "kms:VerifyMac"]
    }
    asymmetric_encrypt_users = {
      principals = var.asymmetric_encrypt_users
      actions    = ["kms:Encrypt", "kms:Decrypt", "kms:GetPublicKey", "kms:DescribeKey"]
    }
    asymmetric_sign_verify_users = {
      principals = var.asymmetric_sign_verify_users
      actions    = ["kms:Sign", "kms:Verify", "kms:GetPublicKey", "kms:DescribeKey"]
    }
    route53_dnssec_principals = {
      principals = var.route53_dnssec_principals
      actions    = ["kms:Sign", "kms:GetPublicKey", "kms:DescribeKey"]
    }
  }

  # Determine if any custom policy content exists
  has_custom_policy = var.override_policy_document != null || var.aws_account_id != "" || length(flatten([
    for k, v in local.role_statements : v.principals
  ])) > 0 || length(var.custom_policy_statements) > 0

  # Compute the active key ID and ARN based on the mutually exclusive flag
  key_id = var.create_standard ? aws_kms_key.standard[0].key_id : (
    var.create_external ? aws_kms_external_key.external[0].id : (
      var.create_replica ? aws_kms_replica_key.standard[0].key_id : (
        var.create_replica_external ? aws_kms_replica_key.external[0].key_id : null
      )
    )
  )

  key_arn = var.create_standard ? aws_kms_key.standard[0].arn : (
    var.create_external ? aws_kms_external_key.external[0].arn : (
      var.create_replica ? aws_kms_replica_key.standard[0].arn : (
        var.create_replica_external ? aws_kms_replica_key.external[0].arn : null
      )
    )
  )
}

# ----------------------------------------------------------------------
# KMS Key Resources (mutually exclusive via count)
# ----------------------------------------------------------------------

resource "aws_kms_key" "standard" {
  count                    = var.create_standard ? 1 : 0
  description             = var.description
  key_usage               = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation     = true
  deletion_window_in_days = var.deletion_window_in_days
  multi_region            = false
  policy                  = local.has_custom_policy ? (
    var.override_policy_document != null ? var.override_policy_document : data.aws_iam_policy_document.key_policy[0].json
  ) : null

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_external_key" "external" {
  count                    = var.create_external ? 1 : 0
  description             = var.description
  multi_region            = false
  deletion_window_in_days = var.deletion_window_in_days
  key_material_base64     = var.external_key_material_base64

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "standard" {
  count                    = var.create_replica ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_key_arn
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.has_custom_policy ? (
    var.override_policy_document != null ? var.override_policy_document : data.aws_iam_policy_document.key_policy[0].json
  ) : null

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_replica_key" "external" {
  count                    = var.create_replica_external ? 1 : 0
  description             = var.description
  primary_key_arn         = var.primary_external_key_arn
  deletion_window_in_days = var.deletion_window_in_days
  policy                  = local.has_custom_policy ? (
    var.override_policy_document != null ? var.override_policy_document : data.aws_iam_policy_document.key_policy[0].json
  ) : null

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Dynamic Key Policy Document (always created, used only when has_custom_policy)
# ----------------------------------------------------------------------

data "aws_iam_policy_document" "key_policy" {
  count = 1

  # Root account full access (only if aws_account_id is provided)
  dynamic "statement" {
    for_each = var.aws_account_id != "" ? [1] : []
    content {
      sid    = "EnableRootAccess"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = ["arn:aws:iam::${var.aws_account_id}:root"]
      }
      actions   = ["kms:*"]
      resources = ["*"]
    }
  }

  # Role-based statements
  dynamic "statement" {
    for_each = { for k, v in local.role_statements : k => v if length(v.principals) > 0 }
    content {
      sid    = statement.key
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = statement.value.principals
      }
      actions   = statement.value.actions
      resources = ["*"]
    }
  }

  # Custom policy statements
  dynamic "statement" {
    for_each = var.custom_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      principals {
        type        = statement.value.principals.type
        identifiers = statement.value.principals.identifiers
      }
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# ----------------------------------------------------------------------
# KMS Alias
# ----------------------------------------------------------------------

resource "aws_kms_alias" "this" {
  count = var.alias_name != null ? 1 : (var.alias_name_prefix != null ? 1 : 0)

  name          = var.alias_name != null ? var.alias_name : null
  name_prefix   = var.alias_name_prefix != null ? var.alias_name_prefix : null
  target_key_id = local.key_id
}

# ----------------------------------------------------------------------
# KMS Grants
# ----------------------------------------------------------------------

resource "aws_kms_grant" "this" {
  for_each = { for idx, g in var.grants : idx => g }

  key_id            = local.key_arn
  grantee_principal = each.value.grantee_principal
  operations        = each.value.operations
  retiring_principal = each.value.retiring_principal != null ? each.value.retiring_principal : null

  dynamic "constraints" {
    for_each = each.value.constraints != null ? each.value.constraints : []
    content {
      encryption_context_subset = {
        constraints.value.key = constraints.value.value
      }
    }
  }
}

# ----------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------

output "kms_key_id" {
  description = "The ID of the created KMS key"
  value       = local.key_id
}

output "kms_key_arn" {
  description = "The ARN of the created KMS key"
  value       = local.key_arn
}

output "alias_arn" {
  description = "The ARN of the created alias (if any)"
  value       = try(aws_kms_alias.this[0].arn, null)
}

output "grant_ids" {
  description = "List of grant IDs created"
  value       = { for k, g in aws_kms_grant.this : k => g.grant_id }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Static metadata lookups
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Variables
variable "topic_name" {
  description = "Name of the SNS topic"
  type        = string
  default     = "my-sns-topic"
}

variable "create_kms_key" {
  description = "Whether to create a dedicated KMS key for SNS encryption"
  type        = bool
  default     = true
}

variable "provided_kms_key_arn" {
  description = "ARN of an existing KMS key to use; ignored if create_kms_key is true"
  type        = string
  default     = ""
}

variable "topic_policy_json" {
  description = "Optional custom SNS topic policy (JSON string); if non-empty, an aws_sns_topic_policy resource is created"
  type        = string
  default     = ""
}

variable "fifo_topic" {
  description = "Whether to create a FIFO topic"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topic"
  type        = bool
  default     = false
}

variable "application_feedback_role_arn" {
  description = "IAM role ARN for application delivery status feedback"
  type        = string
  default     = ""
}

variable "application_success_feedback_sample_rate" {
  description = "Sample rate for application success feedback (0-100)"
  type        = number
  default     = 100
}

variable "http_feedback_role_arn" {
  description = "IAM role ARN for HTTP delivery status feedback"
  type        = string
  default     = ""
}

variable "http_success_feedback_sample_rate" {
  description = "Sample rate for HTTP success feedback (0-100)"
  type        = number
  default     = 100
}

variable "lambda_feedback_role_arn" {
  description = "IAM role ARN for Lambda delivery status feedback"
  type        = string
  default     = ""
}

variable "lambda_success_feedback_sample_rate" {
  description = "Sample rate for Lambda success feedback (0-100)"
  type        = number
  default     = 100
}

variable "sqs_feedback_role_arn" {
  description = "IAM role ARN for SQS delivery status feedback"
  type        = string
  default     = ""
}

variable "sqs_success_feedback_sample_rate" {
  description = "Sample rate for SQS success feedback (0-100)"
  type        = number
  default     = 100
}

variable "firehose_feedback_role_arn" {
  description = "IAM role ARN for Firehose delivery status feedback"
  type        = string
  default     = ""
}

variable "firehose_success_feedback_sample_rate" {
  description = "Sample rate for Firehose success feedback (0-100)"
  type        = number
  default     = 100
}

variable "subscriptions" {
  description = "Map of subscriptions with flexible endpoint, protocol, and optional settings"
  type = map(object({
    endpoint                        = string
    protocol                        = string
    auto_confirmation               = optional(bool, false)
    raw_message_delivery            = optional(bool, false)
    filter_policy                   = optional(string, null)
    redrive_policy                  = optional(string, null)
    confirmation_timeout_in_minutes = optional(number, null)
  }))
  default = {}
}

# Locals
locals {
  topic_name = var.fifo_topic ? "${var.topic_name}.fifo" : var.topic_name
  kms_key_arn = var.create_kms_key ? (
    aws_kms_key.sns[0].arn
  ) : (
    var.provided_kms_key_arn != "" ? var.provided_kms_key_arn : "alias/aws/sns"
  )
}

# KMS Key (optional)
resource "aws_kms_key" "sns" {
  count = var.create_kms_key ? 1 : 0
  description             = "KMS key for SNS topic ${var.topic_name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = data.aws_iam_policy_document.sns_kms.json
}

data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "Enable CloudWatch Logs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${data.aws_region.current.name}.amazonaws.com"]
    }
    actions   = ["kms:Encrypt", "kms:Decrypt"]
    resources = ["*"]
  }

  statement {
    sid    = "Allow root account administration"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
}

resource "aws_kms_alias" "sns" {
  count         = var.create_kms_key ? 1 : 0
  name          = "alias/sns/${var.topic_name}"
  target_key_id = aws_kms_key.sns[0].key_id
}

# SNS Topic
resource "aws_sns_topic" "main" {
  name                        = local.topic_name
  fifo_topic                  = var.fifo_topic
  content_based_deduplication = var.fifo_topic ? var.content_based_deduplication : null
  kms_master_key_id           = local.kms_key_arn

  # Application feedback
  application_success_feedback_role_arn  = var.application_feedback_role_arn != "" ? var.application_feedback_role_arn : null
  application_success_feedback_sample_rate = var.application_feedback_role_arn != "" ? var.application_success_feedback_sample_rate : null
  application_failure_feedback_role_arn  = var.application_feedback_role_arn != "" ? var.application_feedback_role_arn : null

  # HTTP feedback
  http_success_feedback_role_arn  = var.http_feedback_role_arn != "" ? var.http_feedback_role_arn : null
  http_success_feedback_sample_rate = var.http_feedback_role_arn != "" ? var.http_success_feedback_sample_rate : null
  http_failure_feedback_role_arn  = var.http_feedback_role_arn != "" ? var.http_feedback_role_arn : null

  # Lambda feedback
  lambda_success_feedback_role_arn  = var.lambda_feedback_role_arn != "" ? var.lambda_feedback_role_arn : null
  lambda_success_feedback_sample_rate = var.lambda_feedback_role_arn != "" ? var.lambda_success_feedback_sample_rate : null
  lambda_failure_feedback_role_arn  = var.lambda_feedback_role_arn != "" ? var.lambda_feedback_role_arn : null

  # SQS feedback
  sqs_success_feedback_role_arn  = var.sqs_feedback_role_arn != "" ? var.sqs_feedback_role_arn : null
  sqs_success_feedback_sample_rate = var.sqs_feedback_role_arn != "" ? var.sqs_success_feedback_sample_rate : null
  sqs_failure_feedback_role_arn  = var.sqs_feedback_role_arn != "" ? var.sqs_feedback_role_arn : null

  # Firehose feedback
  firehose_success_feedback_role_arn  = var.firehose_feedback_role_arn != "" ? var.firehose_feedback_role_arn : null
  firehose_success_feedback_sample_rate = var.firehose_feedback_role_arn != "" ? var.firehose_success_feedback_sample_rate : null
  firehose_failure_feedback_role_arn  = var.firehose_feedback_role_arn != "" ? var.firehose_feedback_role_arn : null

  tags = {
    Name = var.topic_name
  }
}

# Optional SNS Topic Policy
resource "aws_sns_topic_policy" "main" {
  count  = var.topic_policy_json != "" ? 1 : 0
  arn    = aws_sns_topic.main.arn
  policy = var.topic_policy_json
}

# Subscriptions
resource "aws_sns_topic_subscription" "sub" {
  for_each = var.subscriptions

  topic_arn = aws_sns_topic.main.arn
  endpoint  = each.value.endpoint
  protocol  = each.value.protocol

  confirmation_timeout_in_minutes = each.value.auto_confirmation ? 1 : try(each.value.confirmation_timeout_in_minutes, null)
  raw_message_delivery            = each.value.raw_message_delivery
  filter_policy                   = try(each.value.filter_policy, null)
  redrive_policy                  = try(each.value.redrive_policy, null)
}

variable "create_iam_group" {
  type    = bool
  default = true
}

variable "create_iam_read_only_and_s3_full_access_policy" {
  type    = bool
  default = true
}

variable "create_group_policy_attachment" {
  type    = bool
  default = true
}

variable "create_iam_users" {
  type    = bool
  default = true
}

variable "create_ec2_console_screenshot_policy" {
  type    = bool
  default = true
}

variable "create_user_policy_attachments" {
  type    = bool
  default = true
}

variable "create_group_membership" {
  type    = bool
  default = true
}

variable "create_ec2_instance_role" {
  type    = bool
  default = true
}

variable "iam_group_name" {
  type    = string
  default = "developers"
}

variable "iam_users" {
  type    = list(string)
  default = ["jack", "jones"]
}

variable "iam_read_only_and_s3_full_access_policy_name" {
  type    = string
  default = "iam_read_only_and_s3_full_access"
}

variable "ec2_get_console_screenshot_policy_name" {
  type    = string
  default = "ec2_get_console_screenshot"
}

variable "ec2_instance_role_name" {
  type    = string
  default = "instance_role"
}

# Data source for policy documents
data "aws_iam_policy_document" "iam_read_only_and_s3_full_access" {
  statement {
    sid    = "IAMReadAccess"
    effect = "Allow"
    actions = [
      "iam:Get*",
      "iam:List*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ReadWriteAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      "arn:aws:s3:::*",
      "arn:aws:s3:::*/*"
    ]
  }
}

data "aws_iam_policy_document" "ec2_get_console_screenshot" {
  statement {
    sid    = "EC2ConsoleScreenshot"
    effect = "Allow"
    actions = [
      "ec2:GetConsoleScreenshot"
    ]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "instance_assume_role" {
  statement {
    sid    = "EC2AssumeRole"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# IAM Group
resource "aws_iam_group" "developers" {
  count = var.create_iam_group ? 1 : 0
  name  = var.iam_group_name
}

# IAM Policy: IAM Read Only + S3 Full Access
resource "aws_iam_policy" "iam_read_only_and_s3_full_access" {
  count  = var.create_iam_read_only_and_s3_full_access_policy ? 1 : 0
  name   = var.iam_read_only_and_s3_full_access_policy_name
  policy = data.aws_iam_policy_document.iam_read_only_and_s3_full_access.json
}

# Group Policy Attachment
resource "aws_iam_group_policy_attachment" "group_policy_attach" {
  count = var.create_group_policy_attachment && var.create_iam_group && var.create_iam_read_only_and_s3_full_access_policy ? 1 : 0
  group = aws_iam_group.developers[0].name
  policy_arn = aws_iam_policy.iam_read_only_and_s3_full_access[0].arn
}

# IAM Users
resource "aws_iam_user" "this" {
  for_each = var.create_iam_users ? toset(var.iam_users) : toset([])
  name     = each.key
  tags = {
    user_created_by = "terraform"
  }
}

# IAM Policy: EC2 Console Screenshot
resource "aws_iam_policy" "ec2_get_console_screenshot" {
  count  = var.create_ec2_console_screenshot_policy ? 1 : 0
  name   = var.ec2_get_console_screenshot_policy_name
  policy = data.aws_iam_policy_document.ec2_get_console_screenshot.json
}

# User Policy Attachments
resource "aws_iam_user_policy_attachment" "this" {
  for_each = var.create_user_policy_attachments && var.create_ec2_console_screenshot_policy && var.create_iam_users ? toset(var.iam_users) : toset([])
  user       = aws_iam_user.this[each.key].name
  policy_arn = aws_iam_policy.ec2_get_console_screenshot[0].arn
}

# Group Membership
resource "aws_iam_group_membership" "developers_membership" {
  count = var.create_group_membership && var.create_iam_group && var.create_iam_users ? 1 : 0
  name  = "developers-membership"
  group = aws_iam_group.developers[0].name
  users = [for u in var.iam_users : aws_iam_user.this[u].name]
}

# IAM Role for EC2 Instance
resource "aws_iam_role" "instance_role" {
  count              = var.create_ec2_instance_role ? 1 : 0
  name               = var.ec2_instance_role_name
  assume_role_policy = data.aws_iam_policy_document.instance_assume_role.json
  tags = {
    Name = var.ec2_instance_role_name
  }
}

# Attach AWS Managed IAMReadOnlyAccess Policy to the Role
resource "aws_iam_role_policy_attachment" "instance_role_attach" {
  count      = var.create_ec2_instance_role ? 1 : 0
  role       = aws_iam_role.instance_role[0].name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "multi-cluster-vpc"
}

locals {
  common_tags = {
    Blueprint  = var.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = var.vpc_name
  cidr = "10.0.0.0/16"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnets = [
    cidrsubnet("10.0.0.0/16", 4, 0),
    cidrsubnet("10.0.0.0/16", 4, 1),
    cidrsubnet("10.0.0.0/16", 4, 2),
  ]

  public_subnets = [
    cidrsubnet("10.0.0.0/16", 8, 48),
    cidrsubnet("10.0.0.0/16", 8, 49),
    cidrsubnet("10.0.0.0/16", 8, 50),
  ]

  enable_nat_gateway  = true
  single_nat_gateway  = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.common_tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Security group for cluster1, allowing communication with cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.common_tags, { Name = "cluster1_additional_sg" })
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Security group for cluster2, allowing communication with cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.common_tags, { Name = "cluster2_additional_sg" })
}

# Ingress and egress rules for cluster1 SG
resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
  security_group_id        = aws_security_group.cluster1_additional_sg.id
}

# Ingress and egress rules for cluster2 SG
resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  from_port                = 0
  to_port                  = 0
  protocol                 = "-1"
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
  security_group_id        = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

