  type    = string
  default = ""
}

variable "create_route53_record" {
  type    = bool
  default = false
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

# Locals
locals {
  enable_sms_config     = length(var.sms_configuration.external_id) > 0 && length(var.sms_configuration.sns_caller_arn) > 0
  enable_device_config  = length(keys(var.device_configuration)) > 0
  enable_lambda_config  = length(keys(var.lambda_trigger_config_map)) > 0
  triggers              = var.lambda_trigger_config_map
}

# IAM role for Lambda triggers (one per trigger type)
resource "aws_iam_role" "lambda_trigger" {
  for_each = local.triggers

  name = "${var.pool_name}-lambda-${each.key}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  for_each = local.triggers

  role       = aws_iam_role.lambda_trigger[each.key].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Local file to create a placeholder zip for Lambda functions
resource "null_resource" "placeholder_zip" {
  triggers = {
    always = timestamp()
  }

  provisioner "local-exec" {
    command = "echo 'exports.handler = async () => ({ statusCode: 200, body: \"ok\" });' > index.js && zip -j placeholder.zip index.js && rm index.js"
  }
}

# Placeholder Lambda function for each trigger
resource "aws_lambda_function" "trigger" {
  for_each = local.triggers

  filename      = "placeholder.zip"
  function_name = "${var.pool_name}-trigger-${each.key}"
  role          = aws_iam_role.lambda_trigger[each.key].arn
  handler       = "index.handler"
  runtime       = "nodejs18.x"
  publish       = false

  depends_on = [
    null_resource.placeholder_zip
  ]

  lifecycle {
    ignore_changes = [
      filename,
    ]
  }
}

# Main Cognito User Pool
resource "aws_cognito_user_pool" "main" {
  name = var.pool_name

  alias_attributes           = var.alias_attributes
  auto_verified_attributes   = var.auto_verified_attributes
  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  mfa_configuration          = var.mfa_configuration
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  dynamic "sms_configuration" {
    for_each = local.enable_sms_config ? [1] : []
    content {
      external_id    = var.sms_configuration.external_id
      sns_caller_arn = var.sms_configuration.sns_caller_arn
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled ? [1] : []
    content {
      enabled = true
    }
  }

  dynamic "username_configuration" {
    for_each = var.case_sensitive_username != null ? [1] : []
    content {
      case_sensitive = var.case_sensitive_username
    }
  }

  dynamic "device_configuration" {
    for_each = local.enable_device_config ? [1] : []
    content {
      challenge_required_on_new_device      = lookup(var.device_configuration, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(var.device_configuration, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "lambda_config" {
    for_each = local.enable_lambda_config ? [1] : []
    content {
      create_auth_challenge          = lookup(local.triggers, "create_auth_challenge", null)
      custom_message                 = lookup(local.triggers, "custom_message", null)
      define_auth_challenge          = lookup(local.triggers, "define_auth_challenge", null)
      post_authentication            = lookup(local.triggers, "post_authentication", null)
      post_confirmation              = lookup(local.triggers, "post_confirmation", null)
      pre_authentication             = lookup(local.triggers, "pre_authentication", null)
      pre_sign_up                    = lookup(local.triggers, "pre_sign_up", null)
      pre_token_generation           = lookup(local.triggers, "pre_token_generation", null)
      user_migration                 = lookup(local.triggers, "user_migration", null)
      verify_auth_challenge_response = lookup(local.triggers, "verify_auth_challenge_response", null)

      custom_email_sender {
        lambda_arn     = lookup(local.triggers, "custom_email_sender", null)
        lambda_version = "$LATEST"
      }

      custom_sms_sender {
        lambda_arn     = lookup(local.triggers, "custom_sms_sender", null)
        lambda_version = "$LATEST"
      }
    }
  }

  verification_message_template {
    default_email_option = lookup(var.verification_message_template_by_link, "default_email_option", null)
    email_message        = lookup(var.verification_message_template_by_link, "email_message", null)
    email_subject        = lookup(var.verification_message_template_by_link, "email_subject", null)
    sms_message          = lookup(var.verification_message_template_by_link, "sms_message", null)
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = var.recovery_mechanisms[0].name
      priority = var.recovery_mechanisms[0].priority
    }
    recovery_mechanism {
      name     = var.recovery_mechanisms[1].name
      priority = var.recovery_mechanisms[1].priority
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only
    dynamic "invite_message_template" {
      for_each = length(keys(var.invite_message_template)) > 0 ? [1] : []
      content {
        email_message = lookup(var.invite_message_template, "email_message", null)
        email_subject = lookup(var.invite_message_template, "email_subject", null)
        sms_message   = lookup(var.invite_message_template, "sms_message", null)
      }
    }
  }

  dynamic "schema" {
    for_each = var.custom_schema_attributes
    content {
      name                = schema.value.name
      required            = lookup(schema.value, "required", null)
      mutable             = lookup(schema.value, "mutable", null)
      attribute_data_type = schema.value.attribute_data_type

      dynamic "string_attribute_constraints" {
        for_each = schema.value.attribute_data_type == "String" && contains(keys(schema.value), "min_length") ? [1] : []
        content {
          min_length = lookup(schema.value, "min_length", null)
          max_length = lookup(schema.value, "max_length", null)
        }
      }
    }
  }

  lifecycle {
    ignore_changes = []
  }
}

# User Pool Clients
resource "aws_cognito_user_pool_client" "client" {
  for_each = toset(var.client_app_names)

  user_pool_id = aws_cognito_user_pool.main.id
  name         = each.key

  generate_secret = var.client_generate_secret

  access_token_validity  = var.token_validities.access_token
  id_token_validity      = var.token_validities.id_token
  refresh_token_validity = var.token_validities.refresh_token

  token_validity_units {
    access_token  = var.token_validity_units.access_token
    id_token      = var.token_validity_units.id_token
    refresh_token = var.token_validity_units.refresh_token
  }

  allowed_oauth_flows_user_pool_client = var.allowed_oauth_flows_user_pool_client
  enable_token_revocation              = var.enable_token_revocation
  explicit_auth_flows                  = var.explicit_auth_flows
  prevent_user_existence_errors        = var.prevent_user_existence_errors

  read_attributes  = var.read_attributes
  write_attributes = var.write_attributes

  callback_urls           = var.callback_urls
  logout_urls             = var.logout_urls
  allowed_oauth_flows     = var.allowed_oauth_flows
  allowed_oauth_scopes    = var.allowed_oauth_scopes
  supported_identity_providers = var.supported_identity_providers
}

# User Group (conditional)
resource "aws_cognito_user_group" "group" {
  count = var.group_name != "" ? 1 : 0

  user_pool_id = aws_cognito_user_pool.main.id
  name         = var.group_name
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : null
}

# User Pool Domain (conditional)
resource "aws_cognito_user_pool_domain" "domain" {
  count = var.domain_string != "" ? 1 : 0

  domain           = var.domain_string
  user_pool_id     = aws_cognito_user_pool.main.id
  certificate_arn  = var.acm_certificate_arn != "" ? var.acm_certificate_arn : null
}

# Route53 A-record (conditional)
resource "aws_route53_record" "alias" {
  count = var.create_route53_record && var.route53_zone_id != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = aws_cognito_user_pool_domain.domain[0].domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

variable "subnet_map_public_ip" {
  description = "Whether to assign public IP on launch for all subnets"
  type        = bool
  default     = false
}

variable "subnet_a_az" {
  description = "Availability zone for Subnet A (if null, uses first AZ)"
  type        = string
  default     = null
}

variable "subnet_b_az" {
  description = "Availability zone for Subnet B (if null, uses second AZ)"
  type        = string
  default     = null
}

variable "subnet_c_az" {
  description = "Availability zone for Subnet C (if null, uses third AZ)"
  type        = string
  default     = null
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool for the Elastic IP"
  type        = string
  default     = "amazon"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

# Data source for availability zones
data "aws_availability_zones" "available" {}

# Locals to resolve AZs
locals {
  subnet_a_az = var.subnet_a_az != null ? var.subnet_a_az : data.aws_availability_zones.available.names[0]
  subnet_b_az = var.subnet_b_az != null ? var.subnet_b_az : data.aws_availability_zones.available.names[1]
  subnet_c_az = var.subnet_c_az != null ? var.subnet_c_az : data.aws_availability_zones.available.names[2]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

# Subnets
resource "aws_subnet" "a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_map_public_ip

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_map_public_ip

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_map_public_ip

  tags = {
    Name = var.subnet_c_name
  }
}

# Route Table
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

# Default route to Internet Gateway
resource "aws_route" "default" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

# Associate route table with Subnet A only
resource "aws_route_table_association" "a" {
  subnet_id      = aws_subnet.a.id
  route_table_id = aws_route_table.main.id
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = "NAT-EIP"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.b.id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = var.nat_gateway_name
  }
}

# Security Group
resource "aws_security_group" "default" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "DefaultSecurityGroup"
  }
}

# Egress rule: allow all traffic within VPC CIDR
resource "aws_security_group_rule" "egress_vpc" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.default.id
}

# Output
output "nat_gateway_public_ip" {
  description = "Public IP of the NAT Gateway"
  value       = aws_nat_gateway.main.public_ip
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "vault_name" {
  description = "Name of the backup vault"
  type        = string
  default     = "my-backup-vault"
}

variable "tags" {
  description = "Optional resource tags"
  type        = map(string)
  default     = {}
}

variable "backup_tag_key" {
  description = "Tag key used for backup selection"
  type        = string
  default     = "backup"
}

variable "daily_schedule" {
  description = "Cron schedule for daily backup rule"
  type        = string
  default     = "cron(0 12 ? * * *)"
}

variable "weekly_schedule" {
  description = "Cron schedule for weekly backup rule"
  type        = string
  default     = "cron(0 12 ? * 1 *)"
}

variable "monthly_schedule" {
  description = "Cron schedule for monthly backup rule"
  type        = string
  default     = "cron(0 12 1 * ? *)"
}

variable "daily_deletion_days" {
  description = "Number of days after which daily backups are deleted"
  type        = number
  default     = 7
}

variable "weekly_deletion_days" {
  description = "Number of days after which weekly backups are deleted"
  type        = number
  default     = 31
}

variable "monthly_deletion_days" {
  description = "Number of days after which monthly backups are deleted"
  type        = number
  default     = 366
}

variable "daily_continuous_backup" {
  description = "Enable continuous backup for daily rule"
  type        = bool
  default     = false
}

variable "notification_enabled" {
  description = "Enable backup vault notifications"
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of SNS topic for backup notifications (required if notification_enabled is true)"
  type        = string
  default     = ""
}

variable "notification_events" {
  description = "List of backup events to notify on"
  type        = list(string)
  default = [
    "BACKUP_JOB_FAILED",
    "RESTORE_JOB_FAILED",
    "COPY_JOB_FAILED",
    "S3_BACKUP_OBJECT_FAILED",
    "S3_RESTORE_OBJECT_FAILED"
  ]
}

# Locals
locals {
  vault_name = var.vault_name
}

# KMS Key
resource "aws_kms_key" "this" {
  description             = "KMS key for encrypting AWS Backup vault ${local.vault_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  name          = "alias/backup-vault-key"
  target_key_id = aws_kms_key.this.key_id
}

# Backup Vault
resource "aws_backup_vault" "this" {
  name        = local.vault_name
  kms_key_arn = aws_kms_key.this.arn
  tags        = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for Backup
resource "aws_iam_role" "backup_role" {
  name               = "AWSBackupServiceRoleFor${replace(local.vault_name, "-", "")}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

data "aws_iam_policy" "backup_service_role_policy" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = data.aws_iam_policy.backup_service_role_policy.arn
}

# Backup Plans
resource "aws_backup_plan" "daily" {
  name = "${local.vault_name}-daily"

  rule {
    rule_name                = "daily_backup_rule"
    target_vault_name        = aws_backup_vault.this.name
    schedule                 = var.daily_schedule
    enable_continuous_backup = var.daily_continuous_backup

    lifecycle {
      delete_after = var.daily_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_plan" "weekly" {
  name = "${local.vault_name}-weekly"

  rule {
    rule_name         = "weekly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.weekly_schedule

    lifecycle {
      delete_after = var.weekly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

resource "aws_backup_plan" "monthly" {
  name = "${local.vault_name}-monthly"

  rule {
    rule_name         = "monthly_backup_rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.monthly_schedule

    lifecycle {
      delete_after = var.monthly_deletion_days
    }
  }

  advanced_backup_setting {
    backup_options = {
      WindowsVSS = "enabled"
    }
    resource_type = "EC2"
  }

  tags = var.tags
}

# Backup Selections
resource "aws_backup_selection" "daily" {
  name         = "daily_backup_selection"
  plan_id      = aws_backup_plan.daily.id
  iam_role_arn = aws_iam_role.backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "daily"
  }
}

resource "aws_backup_selection" "weekly" {
  name         = "weekly_backup_selection"
  plan_id      = aws_backup_plan.weekly.id
  iam_role_arn = aws_iam_role.backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "weekly"
  }
}

resource "aws_backup_selection" "monthly" {
  name         = "monthly_backup_selection"
  plan_id      = aws_backup_plan.monthly.id
  iam_role_arn = aws_iam_role.backup_role.arn
  resources    = ["*"]

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.backup_tag_key
    value = "monthly"
  }
}

# Backup Vault Notifications (conditional)
resource "aws_backup_vault_notifications" "this" {
  count = var.notification_enabled ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.notification_events
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "env" {
  description = "Environment tag value"
  type        = string
  default     = "test"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.20.0/24", "10.0.21.0/24"]
}

variable "common_tags" {
  description = "Common tags to apply to all resources"
  type        = map(string)
  default = {
    Owner   = "Valerii Vasianovych"
    Project = "Terraform AWS"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  merged_tags = merge(var.common_tags, { Region = var.region })
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    { Name = "${var.env}-vpc" },
    local.merged_tags
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "${var.env}-igw" },
    local.merged_tags
  )
}

resource "aws_subnet" "public" {
  count = length(var.public_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    { Name = "${var.env}-public-subnet-${count.index}" },
    local.merged_tags
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnet_cidrs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    { Name = "${var.env}-private-subnet-${count.index}" },
    local.merged_tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "${var.env}-route-public-subnets" },
    local.merged_tags
  )
}

resource "aws_route" "public" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  count = length(var.public_subnet_cidrs)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  count  = length(var.private_subnet_cidrs)
  domain = "vpc"

  tags = merge(
    { Name = "${var.env}-nat-eip-${count.index}" },
    local.merged_tags
  )
}

resource "aws_nat_gateway" "main" {
  count = length(var.private_subnet_cidrs)

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(
    { Name = "${var.env}-nat-gw-${count.index}" },
    local.merged_tags
  )
}

resource "aws_route_table" "private" {
  count  = length(var.private_subnet_cidrs)
  vpc_id = aws_vpc.main.id

  tags = merge(
    { Name = "${var.env}-route-private-subnets-${count.index}" },
    local.merged_tags
  )
}

resource "aws_route" "private" {
  count = length(var.private_subnet_cidrs)

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnet_cidrs)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "create_eks" {
  description = "Boolean flag to control creation of the EKS cluster"
  type        = bool
  default     = false
}

variable "cluster_name" {
  description = "Name of the EKS cluster"
  type        = string
  default     = ""
}

variable "cluster_version" {
  description = "Kubernetes version for the EKS cluster"
  type        = string
  default     = null
}

variable "authentication_mode" {
  description = "Authentication mode for the EKS cluster's access config"
  type        = string
  default     = "API_AND_CONFIG_MAP"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the cluster VPC configuration"
  type        = list(string)
  default     = []
}

variable "control_plane_subnet_ids" {
  description = "List of control plane subnet IDs (takes precedence over subnet_ids)"
  type        = list(string)
  default     = []
}

locals {
  # Use control_plane_subnet_ids if provided, otherwise fall back to subnet_ids
  subnet_ids = length(var.control_plane_subnet_ids) > 0 ? var.control_plane_subnet_ids : var.subnet_ids
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks-cluster" {
  name               = "eks-cluster"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks-cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks-cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_eks_cluster" "this" {
  count = var.create_eks ? 1 : 0

  name       = var.cluster_name
  role_arn   = aws_iam_role.eks-cluster.arn
  version    = var.cluster_version

  vpc_config {
    subnet_ids = local.subnet_ids
  }

  access_config {
    authentication_mode                         = var.authentication_mode
    bootstrap_cluster_creator_admin_permissions = true
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller
  ]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

locals {
  common_tags = {
    Name       = "rwwise.dev Infrastructure Setup"
    Repository = "https://github.com/zangrum/setup.inf.rwwise.dev"
    AccountID  = data.aws_caller_identity.current.account_id
    UserID     = data.aws_caller_identity.current.user_id
  }

  cicd_policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codebuild:ListProjects",
          "codebuild:BatchGetProjects",
          "codebuild:ListBuilds",
          "codebuild:BatchGetBuilds",
          "codebuild:ListBuildsForProject",
          "codebuild:DescribeTestCases",
          "codecommit:ListRepositories",
          "codecommit:GetRepository",
          "codecommit:GetBranch",
          "codecommit:ListBranches",
          "codecommit:GetCommit",
          "codecommit:ListPullRequests",
          "codecommit:GetPullRequest",
          "cloudwatch:ListMetrics",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "events:ListRules",
          "events:ListTargetsByRule",
          "events:DescribeRule",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:ListLogDeliveries",
          "logs:FilterLogEvents"
        ]
        Resource = "*"
      },
      {
        Sid    = "CodeStarConnectionsUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-connections:GetConnection",
          "codestar-connections:ListConnections"
        ]
        Resource = "arn:aws:codestar-connections:*:*:connection/*"
      },
      {
        Sid    = "CodeStarNotificationsPowerUserAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:DescribeNotificationRule",
          "codestar-notifications:ListNotificationRules"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "codestar-notifications:NotificationsForResource" = "arn:aws:codebuild:*"
          }
        }
      },
      {
        Sid    = "CodeStarNotificationsListAccess"
        Effect = "Allow"
        Action = [
          "codestar-notifications:ListNotificationRules",
          "codestar-notifications:ListEventTypes",
          "codestar-notifications:ListTargets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user" "dev" {
  name = "DevUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

resource "aws_iam_user" "test" {
  name = "TestUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

resource "aws_iam_user" "prod" {
  name = "ProdUser-rwwise.dev"
  path = "/system/"
  tags = local.common_tags
}

resource "aws_iam_access_key" "dev" {
  user = aws_iam_user.dev.name
}

resource "aws_iam_access_key" "test" {
  user = aws_iam_user.test.name
}

resource "aws_iam_access_key" "prod" {
  user = aws_iam_user.prod.name
}

resource "aws_iam_user_policy" "dev" {
  name   = "dev_cicd_user_policy"
  user   = aws_iam_user.dev.name
  policy = local.cicd_policy_document
}

resource "aws_iam_user_policy" "test" {
  name   = "test_cicd_user_policy"
  user   = aws_iam_user.test.name
  policy = local.cicd_policy_document
}

resource "aws_iam_user_policy" "prod" {
  name   = "prod_cicd_user_policy"
  user   = aws_iam_user.prod.name
  policy = local.cicd_policy_document
}

terraform {
  required_version = ">= 1.1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "bus_config" {
  type    = any
  default = {}

  validation {
    condition     = var.bus_config != null
    error_message = "bus_config must not be null."
  }
}

variable "rules" {
  type    = any
  default = []

  validation {
    condition     = var.rules != null
    error_message = "rules must not be null."
  }
}

variable "targets" {
  type    = any
  default = []

  validation {
    condition     = var.targets != null
    error_message = "targets must not be null."
  }
}

locals {
  module_name = var.name != null && var.name != "" ? trim(var.name) : "default"
}

data "aws_partition" "current" {}

# EventBridge Bus – only created when module_name != "default"
resource "aws_cloudwatch_event_bus" "main" {
  count = local.module_name != "default" ? 1 : 0

  name              = local.module_name
  event_source_name = try(var.bus_config.event_source_name, null)
  tags              = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# EventBridge Rules – always created, attached to custom bus if it exists
resource "aws_cloudwatch_event_rule" "rules" {
  for_each = { for r in var.rules : r.name => r }

  name                = each.key
  description         = each.value.description != null ? each.value.description : null
  event_pattern       = each.value.event_pattern != null ? each.value.event_pattern : null
  schedule_expression = each.value.schedule_expression != null ? each.value.schedule_expression : null
  event_bus_name      = try(aws_cloudwatch_event_bus.main[0].name, null)
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for EventBridge to invoke targets
resource "aws_iam_role" "invoke" {
  name = "${local.module_name}-invoke"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.${data.aws_partition.current.dns_suffix}"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = var.tags
}

# Inline policy for the IAM role
resource "aws_iam_role_policy" "invoke_targets" {
  name = "${local.module_name}-invoke-targets"
  role = aws_iam_role.invoke.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction",
          "states:StartExecution"
        ]
        Resource = "*"
      }
    ]
  })
}

# EventBridge Targets – always created, attached to custom bus if it exists
resource "aws_cloudwatch_event_target" "targets" {
  for_each = { for t in var.targets : "${t.rule}-${t.arn}" => t }

  rule           = aws_cloudwatch_event_rule.rules[each.value.rule].name
  arn            = each.value.arn
  event_bus_name = try(aws_cloudwatch_event_bus.main[0].name, null)
  role_arn       = strcontains(each.value.arn, "stateMachine") ? aws_iam_role.invoke.arn : null

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  type        = string
  default     = "default"
  description = "Base name used for resource naming and tagging."
}

variable "kms_key_arn" {
  type        = string
  default     = ""
  description = "Optional KMS key ARN for vault encryption. If empty, AWS default KMS key is used."
}

variable "vault_policy" {
  type        = string
  default     = ""
  description = "Optional JSON policy document for the backup vault. Attached only when non-empty."
}

variable "schedule" {
  type        = string
  default     = "cron(0 5 * * ? *)"
  description = "Cron expression for the backup schedule."
}

variable "start_window" {
  type        = number
  default     = 60
  description = "Start window for the backup rule in minutes."
}

variable "completion_window" {
  type        = number
  default     = 120
  description = "Completion window for the backup rule in minutes."
}

variable "destination_vault_map" {
  type        = map(string)
  default     = {}
  description = "Map of destination region to vault ARN for copy actions. Key is region, value is vault ARN."
}

variable "sns_topic_arn" {
  type        = string
  default     = ""
  description = "Optional SNS topic ARN for vault event notifications. Configured only when non-empty."
}

variable "tag_key" {
  type        = string
  default     = "Backup"
  description = "Tag key used for backup selection filtering."
}

variable "tag_value" {
  type        = string
  default     = "true"
  description = "Tag value used for backup selection filtering."
}

locals {
  job_tag = "${var.name}-backup"
}

# IAM Role for AWS Backup
resource "aws_iam_role" "backup" {
  name               = "aws-backup-${var.name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = {
    Job = local.job_tag
  }
}

resource "aws_iam_role_policy_attachment" "backup" {
  role       = aws_iam_role.backup.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup Vault
resource "aws_backup_vault" "this" {
  name        = "vault-${var.name}-backup"
  kms_key_arn = var.kms_key_arn != "" ? var.kms_key_arn : null
  tags = {
    Job = local.job_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Backup Vault Policy (conditional)
resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != "" ? 1 : 0
  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

# Backup Plan
resource "aws_backup_plan" "this" {
  name = "plan-${var.name}-backup"
  tags = {
    Job = local.job_tag
  }

  rule {
    rule_name         = "rule-${var.name}-backup"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.schedule
    start_window      = var.start_window
    completion_window = var.completion_window
    recovery_point_tags = {
      Job = local.job_tag
    }

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.destination_vault_map
      content {
        destination_vault_arn = copy_action.value
      }
    }
  }
}

# Backup Selection
resource "aws_backup_selection" "this" {
  name         = "selection-${var.name}-backup"
  iam_role_arn = aws_iam_role.backup.arn
  plan_id      = aws_backup_plan.this.id
  resources    = []  # Can be empty; tag-based selection is used

  condition {
    # Empty condition block - no additional conditions
  }

  selection_tag {
    type  = "STRINGEQUALS"
    key   = var.tag_key
    value = var.tag_value
  }
}

# Backup Vault Notifications (conditional)
resource "aws_backup_vault_notifications" "this" {
  count = var.sns_topic_arn != "" ? 1 : 0
  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

# Variables
variable "create" {
  description = "Toggle to provision a new Transit Gateway (true) or look up an existing one (false)"
  type        = bool
  default     = true
}

variable "id" {
  description = "Existing Transit Gateway ID when create is false"
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag to filter an existing Transit Gateway when create is false and id is null"
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Transit Gateway"
  type        = number
  default     = 65200
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account attachment requests"
  type        = string
  default     = "disable"
}

variable "dns_support" {
  description = "DNS support for the Transit Gateway"
  type        = string
  default     = "enable"
}

variable "vpn_ecmp_support" {
  description = "VPN ECMP support for the Transit Gateway"
  type        = string
  default     = "enable"
}

variable "transit_gateway_cidr_blocks" {
  description = "IPv4 or IPv6 CIDR blocks for the Transit Gateway"
  type        = list(string)
  default     = []
  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Each value in transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables to create or look up"
  type = map(object({
    create = bool
    id     = optional(string)
    tags   = optional(map(string))
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of external AWS account IDs or organization ARNs for RAM sharing"
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Override name for the RAM resource share"
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags applied to all resources"
  type        = map(string)
  default     = {}
}

# Locals
locals {
  # Transit Gateway ID (from created resource or data source)
  tgw_id = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  tgw_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  # Route table IDs map (keyed by route table name)
  route_table_ids = merge(
    { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id },
    { for k, v in data.aws_ec2_transit_gateway_route_table.this : k => v.id }
  )
}

# Transit Gateway resource (when create = true)
resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, var.name != null ? { Name = var.name } : {})

  lifecycle {
    prevent_destroy = true
  }
}

# Data source for existing Transit Gateway (when create = false)
data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null ? ["dummy"] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }
}

# Route tables (create)
resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.tgw_id

  tags = merge(
    var.tags,
    each.value.tags,
    { Name = lookup(each.value.tags, "Name", each.key) }
  )

  lifecycle {
    prevent_destroy = true
  }
}

# Data source for existing route tables (lookup)
data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.tgw_id]
  }

  filter {
    name   = "tag:Name"
    values = [each.key]
  }
}

# RAM Resource Share (only if shared_principals is not empty)
resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, var.name, "tgw-share")
  allow_external_principals = true

  tags = merge(var.tags, { Name = coalesce(var.ram_resource_share_name, var.name, "tgw-share") })

  lifecycle {
    prevent_destroy = true
  }
}

# RAM Resource Association (Transit Gateway)
resource "aws_ram_resource_association" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  resource_arn       = local.tgw_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# RAM Principal Associations
resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

# Outputs
output "transit_gateway_id" {
  description = "The ID of the Transit Gateway"
  value       = local.tgw_id
}

output "route_table_ids" {
  description = "Map of route table names to their IDs"
  value       = local.route_table_ids
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# KMS Key for Backup Vaults
resource "aws_kms_key" "backup_key" {
  description             = "Shared KMS key for AWS Backup vaults"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  tags = {
    Name = "BackupKey"
  }
}

# IAM Role for Bronze Backup
resource "aws_iam_role" "bronze_backup_role" {
  name = "Bronze_Backup_Role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "bronze_backup_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role_policy_attachment" "bronze_restore_policy" {
  role       = aws_iam_role.bronze_backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForRestores"
}

# Backup Vaults
resource "aws_backup_vault" "bronze_backup_vault" {
  name        = "Bronze_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "silver_backup_vault" {
  name        = "Silver_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "gold_backup_vault" {
  name        = "Gold_Backup_Vault"
  kms_key_arn = aws_kms_key.backup_key.arn
}

resource "aws_backup_vault" "premium" {
  name        = "Premium"
  kms_key_arn = aws_kms_key.backup_key.arn
}

# Backup Plans
resource "aws_backup_plan" "bronze_backup" {
  name = "Bronze_Backup"
  rule {
    rule_name         = "Bronze_Backup_Weekly"
    target_vault_name = aws_backup_vault.bronze_backup_vault.name
    schedule          = "cron(0 0 ? * FRI *)"
    lifecycle {
      delete_after = 10
    }
  }
}

resource "aws_backup_plan" "silver_backup_plan" {
  name = "Silver_Backup_Plan"
  rule {
    rule_name         = "Silver_Backup_Daily"
    target_vault_name = aws_backup_vault.silver_backup_vault.name
    schedule          = "cron(0 5 ? * * *)"
    lifecycle {
      delete_after = 7
    }
  }
}

resource "aws_backup_plan" "gold_backup" {
  name = "Gold_Backup"
  rule {
    rule_name         = "Gold_Daily_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Gold_Monthly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      delete_after = 365
    }
  }
  rule {
    rule_name         = "Gold_Yearly_Backup_Rule"
    target_vault_name = aws_backup_vault.gold_backup_vault.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      delete_after = 2555
    }
  }
}

resource "aws_backup_plan" "premium" {
  name = "Premium"
  rule {
    rule_name         = "Premium_Daily_4Hour_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0/4 ? * * *)"
    lifecycle {
      delete_after = 1
    }
  }
  rule {
    rule_name         = "Premium_Daily_Backup"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 * * ? *)"
    lifecycle {
      delete_after = 31
    }
  }
  rule {
    rule_name         = "Premium_Monthly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 1 1/1 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 365
    }
  }
  rule {
    rule_name         = "Premium_Yearly"
    target_vault_name = aws_backup_vault.premium.name
    schedule          = "cron(0 0 31 12 ? *)"
    lifecycle {
      cold_storage_after = 15
      delete_after       = 2555
    }
  }
}

# Backup Selections (Resource Assignments)
resource "aws_backup_selection" "bronze_resource_assignment" {
  name         = "Bronze_Resource_Assignment"
  plan_id      = aws_backup_plan.bronze_backup.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Bronze"
  }
}

resource "aws_backup_selection" "silver_backup_resource" {
  name         = "Silver_Backup_resource"
  plan_id      = aws_backup_plan.silver_backup_plan.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Silver"
  }
}

resource "aws_backup_selection" "gold_backup_select" {
  name         = "Gold_Backup_Select"
  plan_id      = aws_backup_plan.gold_backup.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Gold"
  }
}

resource "aws_backup_selection" "premium" {
  name         = "Premium"
  plan_id      = aws_backup_plan.premium.id
  iam_role_arn = aws_iam_role.bronze_backup_role.arn
  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "Premium"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region for the provider"
  type        = string
  default     = "us-east-1"
}

variable "role_name" {
  description = "Name of the IAM role for Prisma Cloud"
  type        = string
  default     = "PrismaCloudReadWriteRole"
}

variable "read_write" {
  description = "Boolean flag to enable creation of remediation policy"
  type        = bool
  default     = false
}

resource "random_string" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true
}

resource "aws_iam_role" "prisma_cloud" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::188619942792:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "security_audit" {
  role       = aws_iam_role.prisma_cloud.name
  policy_arn = "arn:aws:iam::aws:policy/SecurityAudit"
}

resource "aws_iam_role_policy" "read_only" {
  name = "PrismaCloud-IAM-ReadOnly-Policy"
  role = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cognito-identity:ListTagsForResource",
          "cognito-idp:ListTagsForResource",
          "ecr:DescribeImages",
          "ecr:GetLifecyclePolicy",
          "elasticbeanstalk:ListTagsForResource",
          "elasticfilesystem:DescribeTags",
          "glacier:GetVaultLock",
          "glacier:ListTagsForVault",
          "glue:GetSecurityConfigurations",
          "logs:GetLogEvents",
          "mq:listBrokers",
          "mq:describeBroker",
          "ram:GetResourceShares",
          "secretsmanager:DescribeSecret",
          "ssm:GetParameters",
          "ssm:ListTagsForResource",
          "sqs:SendMessage",
          "elasticmapreduce:ListSecurityConfigurations",
          "sns:listSubscriptions",
          "wafv2:ListResourcesForWebACL",
          "wafv2:ListWebACLs"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "remediation" {
  count = var.read_write ? 1 : 0
  name   = "PrismaCloud-IAM-Remediation-Policy"
  role   = aws_iam_role.prisma_cloud.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:UpdateAccountPasswordPolicy",
          "ec2:ModifyImageAttribute",
          "rds:ModifyDBSnapshotAttribute",
          "s3:PutBucketAcl",
          "ec2:RevokeSecurityGroupIngress"
        ]
        Resource = "*"
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "10.0.2.0/24"
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "development-be-vpc" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = "development-be-vpc"
  }
}

# ------------------------------------------------------------------------------
# SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "development-be-public-subnet" {
  vpc_id                  = aws_vpc.development-be-vpc.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "development-be-public-subnet"
  }
}

resource "aws_subnet" "development-be-private-subnet" {
  vpc_id            = aws_vpc.development-be-vpc.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "development-be-private-subnet"
  }
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "development-be-ig" {
  vpc_id = aws_vpc.development-be-vpc.id

  tags = {
    Name = "development-be-ig"
  }
}

# ------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE AND ASSOCIATION
# ------------------------------------------------------------------------------
resource "aws_route_table" "development-be-public-rt" {
  vpc_id = aws_vpc.development-be-vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.development-be-ig.id
  }

  tags = {
    Name = "development-be-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.development-be-public-subnet.id
  route_table_id = aws_route_table.development-be-public-rt.id
}

# ------------------------------------------------------------------------------
# SECURITY GROUP
# ------------------------------------------------------------------------------
resource "aws_security_group" "http_access" {
  name        = "http_access"
  description = "Security group for HTTP access (development-be)"
  vpc_id      = aws_vpc.development-be-vpc.id

  tags = {
    Name = "development-be-sg"
  }
}

resource "aws_security_group_rule" "ssh_from_vpc_cidr" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.development-be-vpc.cidr_block]
  security_group_id = aws_security_group.http_access.id
}

resource "aws_security_group_rule" "http_from_all" {
  type              = "ingress"
  from_port         = 80
  to_port           = 80
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.http_access.id
}

resource "aws_security_group_rule" "egress_to_vpc_cidr" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [aws_vpc.development-be-vpc.cidr_block]
  security_group_id = aws_security_group.http_access.id
}

# ------------------------------------------------------------------------------
# OUTPUTS
# ------------------------------------------------------------------------------
output "vpc_id" {
  description = "ID of the development-be-vpc"
  value       = aws_vpc.development-be-vpc.id
}

output "public_subnet_id" {
  description = "ID of the development-be-public-subnet"
  value       = aws_subnet.development-be-public-subnet.id
}

output "private_subnet_id" {
  description = "ID of the development-be-private-subnet"
  value       = aws_subnet.development-be-private-subnet.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create all SNS resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the SNS topic. Used when use_name_prefix is false."
  type        = string
  default     = null
}

variable "use_name_prefix" {
  description = "If true, use name as a prefix for the SNS topic."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication for FIFO topics."
  type        = bool
  default     = false
}

variable "delivery_policy" {
  description = "JSON delivery policy for the SNS topic."
  type        = string
  default     = null
}

variable "display_name" {
  description = "Display name for the SNS topic."
  type        = string
  default     = null
}

variable "kms_master_key_id" {
  description = "ARN of the KMS key used for encryption."
  type        = string
  default     = null
}

variable "signature_version" {
  description = "Signature version for the topic. Ignored if fifo_topic is true."
  type        = string
  default     = null
}

variable "tracing_config" {
  description = "Tracing configuration for the topic. Valid values are Active or PassThrough."
  type        = string
  default     = null
}

variable "fifo_topic" {
  description = "Whether the topic is FIFO."
  type        = bool
  default     = false
}

# Feedback configuration maps
variable "application_feedback_config" {
  description = "Feedback configuration for application protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "firehose_feedback_config" {
  description = "Feedback configuration for Firehose protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "http_feedback_config" {
  description = "Feedback configuration for HTTP protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "lambda_feedback_config" {
  description = "Feedback configuration for Lambda protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

variable "sqs_feedback_config" {
  description = "Feedback configuration for SQS protocol."
  type = object({
    failure_role_arn    = string
    success_role_arn    = string
    success_sample_rate = string
  })
  default = null
}

# Data protection policy
variable "data_protection_policy" {
  description = "JSON data protection policy for the topic. Not applied to FIFO topics."
  type        = string
  default     = null
}

# Topic policy variables
variable "create_topic_policy" {
  description = "Whether to create a topic policy using the constructed document. If false, use topic_policy directly."
  type        = bool
  default     = true
}

variable "topic_policy" {
  description = "External JSON topic policy to attach when create_topic_policy is false."
  type        = string
  default     = null
}

variable "enable_default_topic_policy" {
  description = "Whether to include a default policy statement granting standard SNS actions to all AWS principals conditioned on owning account."
  type        = bool
  default     = true
}

variable "source_policy_document" {
  description = "JSON source policy document to merge into the topic policy."
  type        = string
  default     = null
}

variable "override_policy_documents" {
  description = "List of JSON policy documents to override in the topic policy."
  type        = list(string)
  default     = []
}

variable "statements" {
  description = "List of additional statement objects to include in the topic policy."
  type = list(object({
    sid       = optional(string)
    effect    = string
    actions   = list(string)
    resources = list(string)
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

# Subscription variables
variable "create_subscription" {
  description = "Whether to create topic subscriptions."
  type        = bool
  default     = true
}

variable "subscriptions" {
  description = "Map of subscriptions to create. Each key is a subscription identifier."
  type = map(object({
    confirmation_timeout_in_minutes = optional(number, 1)
    delivery_policy                 = optional(string)
    endpoint                        = string
    filter_policy                   = optional(string)
    filter_policy_scope             = optional(string)
    protocol                        = string
    raw_message_delivery            = optional(bool, false)
    redrive_policy                  = optional(string)
    subscription_role_arn           = optional(string)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "combined" {
  count = var.create && var.create_topic_policy ? 1 : 0

  source_policy_documents = compact(concat(
    var.source_policy_document != null ? [var.source_policy_document] : [],
    var.override_policy_documents
  ))

  dynamic "statement" {
    for_each = var.statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources
      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }
      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_default_topic_policy ? [1] : []
    content {
      sid       = "DefaultTopicPolicy"
      effect    = "Allow"
      actions   = ["sns:Publish", "sns:Subscribe", "sns:Receive"]
      resources = [aws_sns_topic.this[0].arn]
      principals {
        type        = "AWS"
        identifiers = ["*"]
      }
      condition {
        test     = "StringEquals"
        variable = "aws:SourceOwner"
        values   = [data.aws_caller_identity.current.account_id]
      }
    }
  }
}

# ------------------------------------------------------------------------------
# SNS Topic
# ------------------------------------------------------------------------------

resource "aws_sns_topic" "this" {
  count = var.create ? 1 : 0

  name = var.use_name_prefix ? null : (var.name != null ? var.name : "sns-topic")
  name_prefix = var.use_name_prefix ? (var.name != null ? "${var.name}-" : "sns-topic-") : null

  content_based_deduplication = var.content_based_deduplication
  delivery_policy             = var.delivery_policy
  display_name                = var.display_name
  kms_master_key_id           = var.kms_master_key_id
  signature_version           = var.fifo_topic ? null : var.signature_version
  tracing_config              = var.tracing_config
  fifo_topic                  = var.fifo_topic

  # Application feedback
  application_failure_feedback_role_arn    = var.application_feedback_config != null ? var.application_feedback_config.failure_role_arn : null
  application_success_feedback_role_arn    = var.application_feedback_config != null ? var.application_feedback_config.success_role_arn : null
  application_success_feedback_sample_rate = var.application_feedback_config != null ? var.application_feedback_config.success_sample_rate : null

  # Firehose feedback
  firehose_failure_feedback_role_arn    = var.firehose_feedback_config != null ? var.firehose_feedback_config.failure_role_arn : null
  firehose_success_feedback_role_arn    = var.firehose_feedback_config != null ? var.firehose_feedback_config.success_role_arn : null
  firehose_success_feedback_sample_rate = var.firehose_feedback_config != null ? var.firehose_feedback_config.success_sample_rate : null

  # HTTP feedback
  http_failure_feedback_role_arn    = var.http_feedback_config != null ? var.http_feedback_config.failure_role_arn : null
  http_success_feedback_role_arn    = var.http_feedback_config != null ? var.http_feedback_config.success_role_arn : null
  http_success_feedback_sample_rate = var.http_feedback_config != null ? var.http_feedback_config.success_sample_rate : null

  # Lambda feedback
  lambda_failure_feedback_role_arn    = var.lambda_feedback_config != null ? var.lambda_feedback_config.failure_role_arn : null
  lambda_success_feedback_role_arn    = var.lambda_feedback_config != null ? var.lambda_feedback_config.success_role_arn : null
  lambda_success_feedback_sample_rate = var.lambda_feedback_config != null ? var.lambda_feedback_config.success_sample_rate : null

  # SQS feedback
  sqs_failure_feedback_role_arn    = var.sqs_feedback_config != null ? var.sqs_feedback_config.failure_role_arn : null
  sqs_success_feedback_role_arn    = var.sqs_feedback_config != null ? var.sqs_feedback_config.success_role_arn : null
  sqs_success_feedback_sample_rate = var.sqs_feedback_config != null ? var.sqs_feedback_config.success_sample_rate : null
}

# ------------------------------------------------------------------------------
# Topic Policy
# ------------------------------------------------------------------------------

resource "aws_sns_topic_policy" "this" {
  count = var.create ? 1 : 0
  arn   = aws_sns_topic.this[0].arn
  policy = var.create_topic_policy ? data.aws_iam_policy_document.combined[0].json : var.topic_policy
}

# ------------------------------------------------------------------------------
# Data Protection Policy
# ------------------------------------------------------------------------------

resource "aws_sns_topic_data_protection_policy" "this" {
  count  = var.create && var.data_protection_policy != null && !var.fifo_topic ? 1 : 0
  arn    = aws_sns_topic.this[0].arn
  policy = var.data_protection_policy
}

# ------------------------------------------------------------------------------
# Topic Subscriptions
# ------------------------------------------------------------------------------

resource "aws_sns_topic_subscription" "this" {
  for_each = var.create && var.create_subscription ? var.subscriptions : {}

  topic_arn = aws_sns_topic.this[0].arn

  confirmation_timeout_in_minutes = each.value.confirmation_timeout_in_minutes
  delivery_policy                 = each.value.delivery_policy
  endpoint                        = each.value.endpoint
  filter_policy                   = each.value.filter_policy
  filter_policy_scope             = each.value.filter_policy_scope
  protocol                        = each.value.protocol
  raw_message_delivery            = each.value.raw_message_delivery
  redrive_policy                  = each.value.redrive_policy
  subscription_role_arn           = each.value.subscription_role_arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables
variable "bucket_name" {
  type    = string
  default = null
}

variable "prefix" {
  type    = bool
  default = false
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "request_payer" {
  type    = string
  default = "BucketOwner"
}

variable "encryption" {
  type    = bool
  default = true
}

variable "kms_key" {
  type    = string
  default = ""
}

variable "versioning" {
  type    = bool
  default = false
}

variable "mfa_delete" {
  type    = bool
  default = false
}

variable "acl" {
  type    = string
  default = null
}

variable "policy" {
  type    = string
  default = null
}

variable "grants" {
  type = list(object({
    id         = string
    type       = string
    permission = string
    uri        = optional(string)
  }))
  default = []
}

variable "owner_id" {
  type    = string
  default = null
}

variable "tags" {
  type    = map(string)
  default = {}
}

variable "acceleration_status" {
  type    = string
  default = null
}

variable "logging_target_bucket" {
  type    = string
  default = null
}

variable "logging_target_prefix" {
  type    = string
  default = null
}

variable "website_index_document" {
  type    = string
  default = null
}

variable "website_error_document" {
  type    = string
  default = null
}

variable "website_redirect_all_requests_to" {
  type    = string
  default = null
}

variable "cors_rules" {
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  type = list(object({
    id      = string
    status  = string
    filter  = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
      and    = optional(object({
        prefix = optional(string)
        tags   = optional(map(string))
      }))
    }))
    transitions = optional(list(object({
      days          = optional(number)
      storage_class = string
      date          = optional(string)
    })))
    noncurrent_version_transitions = optional(list(object({
      days          = number
      storage_class = string
    })))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "object_lock_enabled" {
  type    = bool
  default = false
}

variable "object_lock_default_retention_mode" {
  type    = string
  default = null
}

variable "object_lock_default_retention_days" {
  type    = number
  default = null
}

variable "object_lock_default_retention_years" {
  type    = number
  default = null
}

variable "replication_rules" {
  type = list(object({
    id       = string
    status   = string
    priority = optional(number)
    filter   = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
      and    = optional(object({
        prefix = optional(string)
        tags   = optional(map(string))
      }))
    }))
    destination = object({
      bucket        = string
      storage_class = optional(string)
      replica_kms_key_id = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      account_id = optional(string)
      metrics    = optional(object({
        status  = string
        minutes = optional(number)
      }))
      replication_time = optional(object({
        status  = string
        minutes = optional(number)
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        enabled = bool
      }))
    }))
    delete_marker_replication = optional(string)
    existing_object_replication = optional(string)
  }))
  default = []
}

variable "replication_role_arn" {
  type    = string
  default = null
}

variable "replication_destination_bucket_arn" {
  type    = string
  default = null
}

# Data source for canonical user ID (used when owner_id is not provided)
data "aws_canonical_user_id" "current" {
  count = var.owner_id == null ? 1 : 0
}

# Random suffixes
resource "random_id" "suffix" {
  byte_length = 4
}

resource "random_string" "extra_suffix" {
  length  = 8
  special = false
  upper   = false
}

# Local bucket name
locals {
  base_name   = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.suffix.hex}"
  bucket_name = var.prefix ? "${local.base_name}${random_string.extra_suffix.result}" : local.base_name
}

# S3 bucket (no lifecycle block)
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  request_payer = var.request_payer
  tags          = var.tags

  object_lock_enabled = var.object_lock_enabled
}

# Public access block
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key (if encryption enabled and no key supplied)
resource "aws_kms_key" "this" {
  count = var.encryption && var.kms_key == "" ? 1 : 0

  description             = "KMS key for S3 bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count = var.encryption && var.kms_key == "" ? 1 : 0

  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

# Server-side encryption configuration
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.encryption ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = var.kms_key != "" ? var.kms_key : aws_kms_key.this[0].arn
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status    = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

# ACL (optional)
resource "aws_s3_bucket_acl" "this" {
  count = var.acl != null || length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl != null ? var.acl : null

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []
    content {
      owner {
        id = var.owner_id != null ? var.owner_id : data.aws_canonical_user_id.current[0].id
      }
      dynamic "grant" {
        for_each = var.grants
        content {
          grantee {
            id   = grant.value.id
            type = grant.value.type
            uri  = grant.value.uri
          }
          permission = grant.value.permission
        }
      }
    }
  }
}

# Bucket policy (optional)
resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

# CORS configuration (optional)
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle configuration (optional)
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
          dynamic "and" {
            for_each = filter.value.and != null ? [filter.value.and] : []
            content {
              prefix = and.value.prefix
              tags   = and.value.tags
            }
          }
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions != null ? rule.value.transitions : []
        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
          date          = transition.value.date
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions != null ? rule.value.noncurrent_version_transitions : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# Logging (optional)
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_target_bucket != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix
}

# Website configuration (optional)
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website_index_document != null || var.website_error_document != null || var.website_redirect_all_requests_to != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = var.website_index_document != null ? [var.website_index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = var.website_error_document != null ? [var.website_error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = var.website_redirect_all_requests_to != null ? [var.website_redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
      protocol  = "http"
    }
  }
}

# Accelerate configuration (optional)
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

# Object lock configuration (optional)
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.object_lock_default_retention_mode != null ? [1] : []
    content {
      default_retention {
        mode  = var.object_lock_default_retention_mode
        days  = var.object_lock_default_retention_days
        years = var.object_lock_default_retention_years
      }
    }
  }
}

# Replication IAM role (only if replication rules exist and no external role ARN)
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0

  name = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# Replication IAM policy
resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0

  name = "CoreS3ReplicationPolicy_${local.bucket_name}"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetReplicationConfiguration",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:GetObjectRetention",
          "s3:GetObjectLegalHold"
        ]
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:PutObject",
          "s3:PutObjectAcl",
          "s3:PutObjectVersionAcl",
          "s3:PutObjectTagging",
          "s3:PutObjectVersionTagging",
          "s3:PutObjectRetention",
          "s3:PutObjectLegalHold"
        ]
        Resource = [
          var.replication_destination_bucket_arn,
          "${var.replication_destination_bucket_arn}/*"
        ]
      }
    ]
  })
}

# Attach replication policy to role
resource "aws_iam_role_policy_attachment" "replication" {
  count = length(var.replication_rules) > 0 && var.replication_role_arn == null ? 1 : 0

  role       = aws_iam_role.replication[count.index].name
  policy_arn = aws_iam_policy.replication[count.index].arn
}

# Replication configuration (if rules provided)
resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = var.replication_role_arn != null ? var.replication_role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = filter.value.prefix
          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
          dynamic "and" {
            for_each = filter.value.and != null ? [filter.value.and] : []
            content {
              prefix = and.value.prefix
              tags   = and.value.tags
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = rule.value.destination.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [1] : []
          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }

        dynamic "access_control_translation" {
          for_each = rule.value.destination.access_control_translation != null ? [rule.value.destination.access_control_translation] : []
          content {
            owner = access_control_translation.value.owner
          }
        }

        account = rule.value.destination.account_id

        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []
          content {
            status = metrics.value.status
            dynamic "event_threshold" {
              for_each = metrics.value.minutes != null ? [1] : []
              content {
                minutes = metrics.value.minutes
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []
          content {
            status = replication_time.value.status
            time {
              minutes = replication_time.value.minutes
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []
        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []
            content {
              status = sse_kms_encrypted_objects.value.enabled ? "Enabled" : "Disabled"
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication != null ? [1] : []
        content {
          status = rule.value.delete_marker_replication
        }
      }

      dynamic "existing_object_replication" {
        for_each = rule.value.existing_object_replication != null ? [1] : []
        content {
          status = rule.value.existing_object_replication
        }
      }
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "random_suffix" {
  description = "Whether to append a random suffix to resource names"
  type        = bool
  default     = true
}

variable "suffix_length" {
  description = "Length of random suffix"
  type        = number
  default     = 4
}

variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "zedcloud"
}

variable "iam_user_name" {
  description = "Base name for the IAM user"
  type        = string
  default     = "zedcloud-s3-user"
}

variable "iam_policy_name" {
  description = "Name for the IAM policy"
  type        = string
  default     = "zedcloud-s3-policy"
}

variable "upload_image" {
  description = "Whether to upload an image file to the S3 bucket"
  type        = bool
  default     = false
}

variable "image_filename" {
  description = "Local image file to upload (relative to execution directory)"
  type        = string
  default     = "my-file.qcow2"
}

variable "s3_folder" {
  description = "Optional folder prefix for the uploaded image"
  type        = string
  default     = "my-folder"
}

variable "create_folder" {
  description = "If true, prefix the S3 key with s3_folder"
  type        = bool
  default     = true
}

variable "create_iam_user" {
  description = "Whether to create the IAM user and access key"
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

locals {
  bucket_name     = var.random_suffix ? "${var.bucket_name}-${random_string.suffix[0].result}" : var.bucket_name
  iam_user_name   = var.random_suffix ? "${var.iam_user_name}-${random_string.suffix[0].result}" : var.iam_user_name
  iam_policy_name = var.random_suffix ? "${var.iam_policy_name}-${random_string.suffix[0].result}" : var.iam_policy_name
}

resource "random_string" "suffix" {
  count   = var.random_suffix ? 1 : 0
  length  = var.suffix_length
  lower   = true
  upper   = false
  number  = true
  special = false
}

resource "aws_kms_key" "s3" {
  description             = "KMS key for S3 bucket SSE-KMS encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-policy"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 use of key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })
  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = true
  tags = {
    Name = local.bucket_name
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  ignore_public_acls      = true
  block_public_policy     = true
  restrict_public_buckets = true
}

resource "aws_iam_user" "s3_reader" {
  count = var.create_iam_user ? 1 : 0
  name  = local.iam_user_name
  path  = "/"
  force_destroy = true
}

resource "aws_iam_access_key" "s3_reader" {
  count = var.create_iam_user ? 1 : 0
  user  = aws_iam_user.s3_reader[0].name
}

data "aws_iam_policy_document" "s3_read_only" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject"
    ]
    resources = [
      "arn:aws:s3:::${local.bucket_name}/*"
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = [
      "arn:aws:s3:::${local.bucket_name}"
    ]
  }
}

resource "aws_iam_policy" "s3_read_only" {
  name   = local.iam_policy_name
  policy = data.aws_iam_policy_document.s3_read_only.json
}

resource "aws_iam_user_policy_attachment" "s3_reader" {
  count      = var.create_iam_user ? 1 : 0
  user       = aws_iam_user.s3_reader[0].name
  policy_arn = aws_iam_policy.s3_read_only.arn
}

resource "aws_s3_object" "image" {
  count  = var.upload_image ? 1 : 0
  bucket = aws_s3_bucket.main.id
  key    = var.create_folder ? "${var.s3_folder}/${var.image_filename}" : var.image_filename
  source = var.image_filename
  etag   = filemd5(var.image_filename)
}

variable "default_tags" {
  type        = map(string)
  default     = {
    Project     = "tf-eks-jofo"
    Owner       = "Jovan Zelincevic"
    Compliance  = "Nothing"
    Environment = "dev"
    Provider    = "Terraform"
  }
}

locals {
  common_tags = var.default_tags
  name_prefix = "${var.default_tags["Project"]}-${var.default_tags["Environment"]}"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.14.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name       = "${local.name_prefix}-public-subnet-${count.index + 1}"
    SubnetType = "public"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-nat-gw"
  })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 4, count.index + 3)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.common_tags, {
    Name       = "${local.name_prefix}-private-subnet-${count.index + 1}"
    SubnetType = "private"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replication"
  region = var.replication_region
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_bucket" {
  description = "Controls whether to create the S3 bucket"
  type        = bool
  default     = true

  validation {
    condition     = !var.create_bucket || (var.bucket != null || var.bucket_prefix != null)
    error_message = "When create_bucket is true, you must specify either bucket or bucket_prefix."
  }
}

variable "bucket" {
  description = "Name of the S3 bucket (mutually exclusive with bucket_prefix)"
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for the S3 bucket name (mutually exclusive with bucket)"
  type        = string
  default     = "s3-bucket-"
}

variable "acl" {
  description = "Canned ACL to apply to the bucket"
  type        = string
  default     = "private"
}

variable "force_destroy" {
  description = "Allow destruction of non-empty bucket"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to resources"
  type        = map(string)
  default     = {}
}

variable "acceleration_status" {
  description = "S3 transfer acceleration status (Enabled or Suspended)"
  type        = string
  default     = null
}

variable "request_payer" {
  description = "Request payer configuration (BucketOwner or Requester)"
  type        = string
  default     = null
}

variable "control_object_ownership" {
  description = "Whether to control object ownership"
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership rule when control_object_ownership is true"
  type        = string
  default     = "ObjectWriter"
}

variable "website" {
  description = "Static website hosting configuration"
  type        = any
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type        = any
  default     = []
}

variable "versioning" {
  description = "Versioning configuration (object with status and mfa_delete)"
  type = object({
    status     = optional(string, "Disabled")
    mfa_delete = optional(bool, false)
  })
  default = {}
}

variable "logging" {
  description = "Logging configuration (target_bucket and target_prefix)"
  type = object({
    target_bucket = string
    target_prefix = string
  })
  default = null
}

variable "grants" {
  description = "List of ACL grants (only when control_object_ownership is false)"
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type        = any
  default     = []
}

variable "replication_configuration" {
  description = "Cross-region replication configuration"
  type        = any
  default     = null
}

variable "server_side_encryption_configuration" {
  description = "Server-side encryption configuration"
  type = object({
    rule = object({
      apply_server_side_encryption_by_default = object({
        sse_algorithm     = string
        kms_master_key_id = optional(string)
      })
    })
  })
  default = null
}

variable "object_lock_configuration" {
  description = "Object lock configuration"
  type = object({
    object_lock_enabled = optional(bool, true)
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

variable "attach_elb_log_delivery_policy" {
  description = "Attach policy for ELB log delivery"
  type        = bool
  default     = false
}

variable "attach_lb_log_delivery_policy" {
  description = "Attach policy for ALB/NLB log delivery"
  type        = bool
  default     = false
}

variable "attach_deny_insecure_transport_policy" {
  description = "Attach policy to deny insecure transport"
  type        = bool
  default     = false
}

variable "attach_policy" {
  description = "Attach custom bucket policy"
  type        = bool
  default     = false
}

variable "policy" {
  description = "Custom bucket policy JSON"
  type        = string
  default     = null
}

variable "attach_public_policy" {
  description = "Attach public access block settings"
  type        = bool
  default     = true
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "replication_region" {
  description = "Region for cross-region replication destination"
  type        = string
  default     = "us-west-2"
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {
  count = var.create_bucket ? 1 : 0
}

data "aws_elb_service_account" "main" {
  count = var.create_bucket && (var.attach_elb_log_delivery_policy || var.attach_lb_log_delivery_policy) ? 1 : 0
}

# ------------------------------------------------------------------------------
# KMS Key (when no server_side_encryption_configuration provided)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "this" {
  count = var.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0

  description             = "S3 bucket SSE-KMS key"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
}

resource "aws_kms_alias" "this" {
  count = var.create_bucket && var.server_side_encryption_configuration == null ? 1 : 0

  name_prefix   = "alias/s3-${var.bucket != null ? var.bucket : "tf-"}"
  target_key_id = aws_kms_key.this[0].key_id
}

# ------------------------------------------------------------------------------
# Main S3 Bucket (inline acceleration_status, boolean object_lock_enabled)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "this" {
  count = var.create_bucket ? 1 : 0

  bucket              = var.bucket
  bucket_prefix       = var.bucket_prefix
  force_destroy       = var.force_destroy
  acceleration_status = var.acceleration_status
  object_lock_enabled = var.object_lock_configuration != null ? var.object_lock_configuration.object_lock_enabled : null
  tags                = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Ownership Controls
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_ownership_controls" "this" {
  count = var.create_bucket && var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }
}

# ------------------------------------------------------------------------------
# Bucket ACL — canned (only when no grants and control_object_ownership false)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "this" {
  count = var.create_bucket && var.control_object_ownership == false && length(var.grants) == 0 && var.acl != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  acl    = var.acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ------------------------------------------------------------------------------
# Bucket ACL — grants-based (only when grants provided and control_object_ownership false)
# ------------------------------------------------------------------------------
locals {
  grants_flat = flatten([
    for g in var.grants : [
      for perm in g.permissions : {
        type       = g.type
        id         = g.id
        uri        = g.uri
        permission = perm
      }
    ]
  ])
}

resource "aws_s3_bucket_acl" "grants" {
  count = var.create_bucket && var.control_object_ownership == false && length(var.grants) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  access_control_policy {
    dynamic "grant" {
      for_each = local.grants_flat
      content {
        grantee {
          type = grant.value.type
          id   = grant.value.id
          uri  = grant.value.uri
        }
        permission = grant.value.permission
      }
    }

    owner {
      id = data.aws_caller_identity.current[0].account_id
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# ------------------------------------------------------------------------------
# Request Payment Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = var.create_bucket && var.request_payer != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  payer  = var.request_payer
}

# ------------------------------------------------------------------------------
# Website Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "this" {
  count = var.create_bucket && var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "index_document" {
    for_each = lookup(var.website, "index_document", null) != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value.suffix
    }
  }

  dynamic "error_document" {
    for_each = lookup(var.website, "error_document", null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value.key
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = lookup(var.website, "redirect_all_requests_to", null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value.host_name
      protocol  = lookup(redirect_all_requests_to.value, "protocol", null)
    }
  }

  dynamic "routing_rule" {
    for_each = lookup(var.website, "routing_rules", [])
    content {
      dynamic "condition" {
        for_each = lookup(routing_rule.value, "condition", null) != null ? [routing_rule.value.condition] : []
        content {
          key_prefix_equals              = coalesce(lookup(condition.value, "key_prefix_equals", null), lookup(condition.value, "key", null), lookup(condition.value, "prefix", null))
          http_error_code_returned_equals = lookup(condition.value, "http_error_code_returned_equals", null)
        }
      }

      dynamic "redirect" {
        for_each = lookup(routing_rule.value, "redirect", null) != null ? [routing_rule.value.redirect] : []
        content {
          host_name             = lookup(redirect.value, "host_name", null)
          http_redirect_code    = lookup(redirect.value, "http_redirect_code", null)
          protocol              = lookup(redirect.value, "protocol", null)
          replace_key_prefix_with = lookup(redirect.value, "replace_key_prefix_with", null)
          replace_key_with      = lookup(redirect.value, "replace_key_with", null)
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CORS Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "this" {
  count = var.create_bucket && length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = lookup(cors_rule.value, "allowed_headers", [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = lookup(cors_rule.value, "expose_headers", [])
      max_age_seconds = lookup(cors_rule.value, "max_age_seconds", null)
    }
  }
}

# ------------------------------------------------------------------------------
# Versioning
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "this" {
  count = var.create_bucket && (
    (var.versioning != {} && var.versioning.status != "Disabled") ||
    var.object_lock_configuration != null ||
    var.replication_configuration != null
  ) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status    = var.versioning != {} ? var.versioning.status : "Enabled"
    mfa_delete = var.versioning != {} ? var.versioning.mfa_delete : false
  }
}

# ------------------------------------------------------------------------------
# Logging
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket        = var.logging.target_bucket
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_delivery[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_delivery[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  statement {
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_delivery[0].arn}/${var.logging.target_prefix}*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
  }
}

resource "aws_s3_bucket_policy" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_delivery[0].id
  policy = data.aws_iam_policy_document.log_delivery[0].json
}

# ------------------------------------------------------------------------------
# Log Delivery Lifecycle Rule (with required filter)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "log_delivery" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.log_delivery[0].id

  rule {
    id     = "log-expiration"
    status = "Enabled"

    filter {
      prefix = var.logging.target_prefix
    }

    expiration {
      days = 90
    }
  }
}

resource "aws_s3_bucket_logging" "this" {
  count = var.create_bucket && var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  target_bucket = aws_s3_bucket.log_delivery[0].id
  target_prefix = var.logging.target_prefix
}

# ------------------------------------------------------------------------------
# Lifecycle Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = var.create_bucket && length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = lookup(rule.value, "filter", null) != null ? [rule.value.filter] : []
        content {
          dynamic "and" {
            for_each = (lookup(filter.value, "prefix", null) != null && lookup(filter.value, "tags", null) != null) ? [{
              prefix = filter.value.prefix
              tags   = filter.value.tags
            }] : []
            content {
              prefix = and.value.prefix
              tags   = and.value.tags
            }
          }

          prefix = (lookup(filter.value, "tags", null) == null && lookup(filter.value, "prefix", null) != null) ? filter.value.prefix : null

          dynamic "tag" {
            for_each = (lookup(filter.value, "prefix", null) == null && lookup(filter.value, "tags", null) != null) ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = lookup(rule.value, "expiration", null) != null ? [rule.value.expiration] : []
        content {
          date                         = lookup(expiration.value, "date", null)
          days                         = lookup(expiration.value, "days", null)
          expired_object_delete_marker = lookup(expiration.value, "expired_object_delete_marker", null)
        }
      }

      dynamic "transition" {
        for_each = lookup(rule.value, "transitions", [])
        content {
          date          = lookup(transition.value, "date", null)
          days          = lookup(transition.value, "days", null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = lookup(rule.value, "noncurrent_version_expiration", null) != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = noncurrent_version_expiration.value.noncurrent_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = lookup(rule.value, "noncurrent_version_transitions", [])
        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = lookup(rule.value, "abort_incomplete_multipart_upload", null) != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Server-Side Encryption Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.create_bucket ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.server_side_encryption_configuration != null ? var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default.sse_algorithm : "aws:kms"
      kms_master_key_id = var.server_side_encryption_configuration != null ? lookup(var.server_side_encryption_configuration.rule.apply_server_side_encryption_by_default, "kms_master_key_id", null) : aws_kms_key.this[0].arn
    }
  }
}

# ------------------------------------------------------------------------------
# Object Lock Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.create_bucket && var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = lookup(rule.value.default_retention, "days", null)
        years = lookup(rule.value.default_retention, "years", null)
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Cross-Region Replication
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "replication_destination" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  provider = aws.replication

  bucket        = var.replication_configuration.destination_bucket
  force_destroy = false
  tags          = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replication_destination" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  provider = aws.replication

  bucket = aws_s3_bucket.replication_destination[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replication_destination" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  provider = aws.replication

  bucket = aws_s3_bucket.replication_destination[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Role for replication
resource "aws_iam_role" "replication" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  name = "s3-replication-role-${var.bucket != null ? var.bucket : var.bucket_prefix}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  statement {
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetBucketVersioning",
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags"
    ]
    resources = [
      aws_s3_bucket.this[0].arn,
      "${aws_s3_bucket.this[0].arn}/*",
      aws_s3_bucket.replication_destination[0].arn,
      "${aws_s3_bucket.replication_destination[0].arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = var.server_side_encryption_configuration == null ? [1] : []
    content {
      actions = [
        "kms:Decrypt",
        "kms:Encrypt"
      ]
      resources = [aws_kms_key.this[0].arn]
    }
  }
}

resource "aws_iam_policy" "replication" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  name   = "s3-replication-policy-${var.bucket != null ? var.bucket : var.bucket_prefix}"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = var.create_bucket && var.replication_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = lookup(var.replication_configuration, "rules", [])
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = lookup(rule.value, "priority", null)

      dynamic "filter" {
        for_each = lookup(rule.value, "filter", null) != null ? [rule.value.filter] : []
        content {
          dynamic "and" {
            for_each = (lookup(filter.value, "prefix", null) != null && lookup(filter.value, "tags", null) != null) ? [{
              prefix = filter.value.prefix
              tags   = filter.value.tags
            }] : []
            content {
              prefix = and.value.prefix
              tags   = and.value.tags
            }
          }

          prefix = (lookup(filter.value, "tags", null) == null && lookup(filter.value, "prefix", null) != null) ? filter.value.prefix : null

          dynamic "tag" {
            for_each = (lookup(filter.value, "prefix", null) == null && lookup(filter.value, "tags", null) != null) ? filter.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket = aws_s3_bucket.replication_destination[0].arn
        storage_class = lookup(rule.value.destination, "storage_class", null)

        dynamic "replication_time" {
          for_each = lookup(rule.value.destination, "replication_time", null) != null ? [rule.value.destination.replication_time] : []
          content {
            status = replication_time.value.status
            time {
              minutes = replication_time.value.minutes
            }
          }
        }

        dynamic "metrics" {
          for_each = lookup(rule.value.destination, "metrics", null) != null ? [rule.value.destination.metrics] : []
          content {
            status = metrics.value.status
            event_threshold {
              minutes = metrics.value.minutes
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = lookup(rule.value, "delete_marker_replication", null) != null ? [1] : []
        content {
          status = rule.value.delete_marker_replication
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Public Access Block (main bucket)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.create_bucket && var.attach_public_policy ? 1 : 0

  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# ------------------------------------------------------------------------------
# Combined Bucket Policy
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "combined" {
  count = var.create_bucket ? 1 : 0

  source_policy_documents = var.attach_policy && var.policy != null ? [var.policy] : []

  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/logs/elb/*"]

      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main[0].arn]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/logs/lb/*"]

      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main[0].arn]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_lb_log_delivery_policy ? [1] : []
    content {
      actions   = ["s3:GetBucketAcl"]
      resources = [aws_s3_bucket.this[0].arn]

      principals {
        type        = "AWS"
        identifiers = [data.aws_elb_service_account.main[0].arn]
      }
    }
  }

  dynamic "statement" {
    for_each = var.attach_deny_insecure_transport_policy ? [1] : []
    content {
      effect = "Deny"
      actions = [
        "s3:GetObject",
        "s3:PutObject",
        "s3:DeleteObject",
        "s3:ListBucket"
      ]
      resources = [
        aws_s3_bucket.this[0].arn,
        "${aws_s3_bucket.this[0].arn}/*"
      ]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.create_bucket && (
    var.attach_elb_log_delivery_policy ||
    var.attach_lb_log_delivery_policy ||
    var.attach_deny_insecure_transport_policy ||
    var.attach_policy
  ) ? 1 : 0

  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "projectPrefix" {
  type    = string
  default = "f5-dcec"
}

variable "resourceOwner" {
  type    = string
  default = "f5-user"
}

variable "buildSuffix" {
  type    = string
  default = "YY"
}

variable "map_public_ip_on_launch" {
  type    = bool
  default = false
}

variable "awsRegion" {
  type    = string
  default = "us-east-1"
}

variable "vpcMainCidr" {
  type    = string
  default = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  type    = string
  default = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  type    = string
  default = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  type    = string
  default = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  type    = string
  default = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  type    = string
  default = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  type    = string
  default = "10.1.120.0/24"
}

variable "awsAz1" {
  type    = string
  default = null
}

variable "awsAz2" {
  type    = string
  default = null
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]
  az2 = var.awsAz2 != null ? var.awsAz2 : (var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[1])

  common_tags = {
    projectPrefix = var.projectPrefix
    resourceOwner = var.resourceOwner
    buildSuffix   = var.buildSuffix
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-pub-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "mgmt_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-mgmt-b-${var.buildSuffix}"
  })
}

resource "aws_subnet" "priv_a" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.az1

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-a-${var.buildSuffix}"
  })
}

resource "aws_subnet" "priv_b" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.az2

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-sub-priv-b-${var.buildSuffix}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
  })
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Input variables
variable "region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "resource_name" {
  description = "Base name used to tag and name all resources"
  type        = string
  default     = "benchmark"
}

variable "listener_rule_count" {
  description = "Number of listener rules to create for path-based routing"
  type        = number
  default     = 1
}

# Data source for available availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Local values for AZ selection
locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)
}

# VPC with CIDR 10.0.0.0/16
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name   = var.resource_name
    Region = var.region
  }
}

# Two subnets using calculated /24 CIDR blocks
resource "aws_subnet" "main" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = {
    Name = var.resource_name
  }
}

# Security group allowing all ingress and egress within the VPC
resource "aws_security_group" "main" {
  name        = var.resource_name
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = var.resource_name
  }
}

# HTTP target group on port 8080 with health check on port 8081
resource "aws_lb_target_group" "main" {
  name        = var.resource_name
  port        = 8080
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    port                = 8081
    protocol            = "HTTP"
    path                = "/health"
    interval            = 60
    timeout             = 3
    healthy_threshold   = 3
    unhealthy_threshold = 3
    matcher             = "200-299"
  }

  tags = {
    Name = var.resource_name
  }
}

# Internal Application Load Balancer
resource "aws_lb" "main" {
  name                       = var.resource_name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.main.id]
  subnets                    = aws_subnet.main[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = var.resource_name
  }
}

# Self-signed certificate for HTTPS listener
resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name = "${var.resource_name}.example.com"
  }

  validity_period_hours = 12

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  private_key       = tls_private_key.self_signed.private_key_pem
  certificate_body = tls_self_signed_cert.self_signed.cert_pem

  tags = {
    Name = var.resource_name
  }
}

# HTTPS listener on port 80 forwarding to target group
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = {
    Name = var.resource_name
  }
}

# Listener rules for path-based routing
resource "aws_lb_listener_rule" "main" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-/*"]
    }
  }

  tags = {
    Name = var.resource_name
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "management_trail"
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail"
  type        = bool
  default     = false
}

variable "log_group_name" {
  description = "Name of the CloudWatch Log Group for CloudTrail logs"
  type        = string
  default     = "cloudtrail_logs"
}

variable "enable_kms_encryption" {
  description = "Enable KMS encryption for CloudTrail and S3 bucket"
  type        = bool
  default     = true
}

variable "kms_key_alias" {
  description = "Alias for the KMS key used by CloudTrail"
  type        = string
  default     = "alias/cloudtrail_key"
}

# Data sources
data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_organizations_organization" "org" {
  count = var.is_organization_trail ? 1 : 0
}

# Random suffix for S3 bucket
resource "random_string" "bucket_suffix" {
  length  = 12
  numeric = true
  special = false
  lower   = false
  upper   = false
}

# S3 bucket for CloudTrail logs
resource "aws_s3_bucket" "cloudtrail_bucket" {
  bucket        = "cloudtrail-bucket-${random_string.bucket_suffix.result}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_bucket" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "cloudtrail_bucket" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

locals {
  sse_algorithm = var.enable_kms_encryption ? "aws:kms" : "AES256"
  kms_key_id    = var.enable_kms_encryption ? aws_kms_key.cloudtrail_key[0].arn : null
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_bucket" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.kms_key_id
    }
  }
}

locals {
  bucket_arn = aws_s3_bucket.cloudtrail_bucket.arn
  org_id     = var.is_organization_trail ? data.aws_organizations_organization.org[0].id : ""
  log_prefix = var.is_organization_trail ? "AWSLogs/${local.org_id}/*" : "AWSLogs/${data.aws_caller_identity.current.account_id}/*"
}

data "aws_iam_policy_document" "cloudtrail_bucket_policy" {
  statement {
    sid    = "AllowCloudTrailGetBucketAcl"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [local.bucket_arn]
  }

  statement {
    sid    = "AllowCloudTrailPutObject"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${local.bucket_arn}/${local.log_prefix}"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    dynamic "condition" {
      for_each = var.is_organization_trail ? [1] : []
      content {
        test     = "StringEquals"
        variable = "aws:SourceOrgID"
        values   = [local.org_id]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_bucket" {
  bucket = aws_s3_bucket.cloudtrail_bucket.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket_policy.json
}

# KMS key and alias (conditional)
data "aws_iam_policy_document" "kms_key_policy" {
  count = var.enable_kms_encryption ? 1 : 0

  statement {
    sid    = "EnableRootAdminPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [
        "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root",
        data.aws_caller_identity.current.arn
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["kms:GenerateDataKey", "kms:DescribeKey"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions   = ["kms:GenerateDataKey", "kms:Decrypt"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowAccountToDecryptLogs"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:Decrypt"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "cloudtrail_key" {
  count = var.enable_kms_encryption ? 1 : 0

  description             = "CloudTrail encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms_key_policy[0].json
}

resource "aws_kms_alias" "cloudtrail_key" {
  count = var.enable_kms_encryption ? 1 : 0

  name          = var.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail_key[0].key_id
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "cloudtrail_logs" {
  name              = var.log_group_name
  retention_in_days = 0
  skip_destroy      = true
  lifecycle {
    prevent_destroy = true
  }
}

# IAM role for CloudTrail to write to CloudWatch Logs
data "aws_iam_policy_document" "cloudtrail_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "cloudtrail_cw_role" {
  name               = "CloudTrailRoleForCloudWatchLogs"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_assume_role.json
}

data "aws_iam_policy_document" "cloudtrail_cw_policy" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cw_policy" {
  name   = "allow-access-to-cw-logs"
  role   = aws_iam_role.cloudtrail_cw_role.id
  policy = data.aws_iam_policy_document.cloudtrail_cw_policy.json
}

# CloudTrail trail
resource "aws_cloudtrail" "management_trail" {
  name                       = var.trail_name
  s3_bucket_name             = aws_s3_bucket.cloudtrail_bucket.id
  is_multi_region_trail      = true
  enable_log_file_validation = true
  include_global_service_events = true
  is_organization_trail      = var.is_organization_trail
  cloud_watch_logs_group_arn = "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*"
  cloud_watch_logs_role_arn  = aws_iam_role.cloudtrail_cw_role.arn
  kms_key_id                 = var.enable_kms_encryption ? aws_kms_key.cloudtrail_key[0].arn : null

  event_selector {
    read_write_type           = "All"
    include_management_events = true
  }
}

# Import existing resources to avoid AlreadyExists errors
import {
  to = aws_kms_alias.cloudtrail_key[0]
  id = var.kms_key_alias
}

import {
  to = aws_cloudwatch_log_group.cloudtrail_logs
  id = var.log_group_name
}

import {
  to = aws_iam_role.cloudtrail_cw_role
  id = "CloudTrailRoleForCloudWatchLogs"
}

import {
  to = aws_iam_role_policy.cloudtrail_cw_policy
  id = "CloudTrailRoleForCloudWatchLogs:allow-access-to-cw-logs"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "namespace" {
  type    = string
  default = ""
}

variable "repository_name" {
  type    = string
  default = null
}

variable "lifecycle_policy" {
  type    = string
  default = null
}

variable "trusted_accounts" {
  type    = list(string)
  default = []
}

variable "image_tag_mutability" {
  type    = string
  default = "IMMUTABLE"
}

variable "scan_on_push" {
  type    = bool
  default = true
}

data "aws_caller_identity" "current" {}

resource "random_pet" "this" {
  length = 1
}

locals {
  effective_name   = var.repository_name != null && var.repository_name != "" ? var.repository_name : random_pet.this.id
  repository_name  = var.namespace != "" ? "${var.namespace}/${local.effective_name}" : local.effective_name
  allowed_accounts = concat([data.aws_caller_identity.current.account_id], var.trusted_accounts)
}

resource "aws_ecr_repository" "this" {
  name                 = local.repository_name
  image_tag_mutability = var.image_tag_mutability
  image_scanning_configuration {
    scan_on_push = var.scan_on_push
  }
  tags = {
    "terraform.io" = "managed"
    "Name"         = local.repository_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "this" {
  count      = var.lifecycle_policy != null ? 1 : 0
  repository = aws_ecr_repository.this.name
  policy     = var.lifecycle_policy
}

data "aws_iam_policy_document" "ecr_read" {
  statement {
    sid    = "ECRRead"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages"
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "ecr_read" {
  name   = "${local.repository_name}-ecr-read"
  policy = data.aws_iam_policy_document.ecr_read.json
}

data "aws_iam_policy_document" "ecr_write" {
  statement {
    sid    = "ECRWrite"
    effect = "Allow"
    actions = [
      "ecr:PutImage",
      "ecr:UploadLayerPart",
      "ecr:InitiateLayerUpload",
      "ecr:CompleteLayerUpload"
    ]
    resources = [aws_ecr_repository.this.arn]
  }
}

resource "aws_iam_policy" "ecr_write" {
  name   = "${local.repository_name}-ecr-write"
  policy = data.aws_iam_policy_document.ecr_write.json
}

data "aws_iam_policy_document" "repository_policy" {
  statement {
    sid    = "AllowCrossAccountAccess"
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:DescribeImages",
      "ecr:DescribeRepositories",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:ListImages"
    ]
    principals {
      type        = "AWS"
      identifiers = local.allowed_accounts
    }
  }
}

resource "aws_ecr_repository_policy" "this" {
  repository = aws_ecr_repository.this.name
  policy     = data.aws_iam_policy_document.repository_policy.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  default = "10.0.0.0/16"
}

variable "number_of_azs" {
  default = 2
}

variable "enable_public_subnets" {
  default = false
}

variable "enable_nat_subnets" {
  default = false
}

variable "enable_private_subnets" {
  default = false
}

locals {
  default_tags = {
    Environment = "dev"
    Project     = "myproject"
  }

  enabled_tiers_count = sum([
    var.enable_public_subnets ? 1 : 0,
    var.enable_nat_subnets ? 1 : 0,
    var.enable_private_subnets ? 1 : 0
  ])

  total_subnets = var.number_of_azs * local.enabled_tiers_count

  newbits = local.total_subnets > 0 ? ceil(log(local.total_subnets) / log(2)) : 0

  vpc_id = aws_vpc.main.id

  public_subnet_cidrs = var.enable_public_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 0 * var.number_of_azs + az_idx)
  ] : []

  nat_subnet_cidrs = var.enable_nat_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 1 * var.number_of_azs + az_idx)
  ] : []

  private_subnet_cidrs = var.enable_private_subnets ? [
    for az_idx in range(var.number_of_azs) :
    cidrsubnet(local.vpc_id, local.newbits, 2 * var.number_of_azs + az_idx)
  ] : []
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.default_tags, {
    Name = "main-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "main-igw"
  })
}

resource "aws_security_group" "public" {
  count = var.enable_public_subnets ? 1 : 0

  name        = "public-sg"
  description = "Security group for public tier"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.default_tags, {
    Name = "public-sg"
  })
}

resource "aws_route_table" "public" {
  count = var.enable_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.default_tags, {
    Name = "public-rt"
  })
}

resource "aws_route" "public_internet" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route" "public_local" {
  count = var.enable_public_subnets ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = aws_vpc.main.cidr_block
  gateway_id             = "local"
}

resource "aws_subnet" "public" {
  count = var.enable_public_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.default_tags, {
    Name = "public-subnet-${count.index + 1}"
  })
}

resource "aws_route_table_association" "public" {
  count = var.enable_public_subnets ? var.number_of_azs : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_subnet" "nat" {
  count = var.enable_nat_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.nat_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "nat-subnet-${count.index + 1}"
  })
}

resource "aws_subnet" "private" {
  count = var.enable_private_subnets ? var.number_of_azs : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.default_tags, {
    Name = "private-subnet-${count.index + 1}"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# Variables with defaults as per objectives
variable "project" {
  description = "Project name for tagging"
  type        = string
  default     = "demo"
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "poc"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "demo-dataflow"
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.3.0/24"]
}

variable "key_name" {
  description = "Name for the EC2 key pair"
  type        = string
  default     = "kplinuxdemo"
}

variable "bastion_instance_type" {
  description = "Instance type for bastion host"
  type        = string
  default     = "t3.nano"
}

variable "ebs_optimized" {
  description = "Enable EBS optimization on bastion"
  type        = bool
  default     = false
}

variable "bastion_ssh_cidr" {
  description = "CIDR block allowed for SSH access to bastion"
  type        = string
  default     = "10.0.0.0/16" # Restricted to VPC CIDR by default
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Provider block explicitly configured
provider "aws" {
  region = var.region
}

# Local values for consistent tagging
locals {
  common_tags = merge(
    var.tags,
    {
      Project     = var.project
      Environment = var.environment
    }
  )
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Generate TLS private key for bastion key pair
resource "tls_private_key" "bastion" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# Create key pair using generated public key
resource "aws_key_pair" "bastion" {
  key_name   = var.key_name
  public_key = tls_private_key.bastion.public_key_openssh
  tags       = local.common_tags
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

# Internet Gateway
resource "aws_internet_gateway" "demo_gw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demogwInternet"
  })
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demoPublicRouteTable"
  })
}

# Default route to Internet Gateway
resource "aws_route" "public_default" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.demo_gw.id
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.0.0/24" : "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "public-subnet-${count.index}"
  })
}

# Private subnets
resource "aws_subnet" "private" {
  count                   = length(var.private_subnet_cidrs)
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "private-subnet-${count.index}"
  })
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "demo-private-rt"
  })
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count          = length(var.private_subnet_cidrs)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security group for bastion host
resource "aws_security_group" "bastion" {
  name        = "bastion-sg"
  description = "Allow SSH from VPC CIDR and outbound to VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from allowed CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.bastion_ssh_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"] # Restricted to VPC CIDR
  }

  tags = merge(local.common_tags, {
    Name = "bastion-sg"
  })
}

# Bastion EC2 instance
resource "aws_instance" "bastion" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = var.bastion_instance_type
  key_name               = aws_key_pair.bastion.key_name
  subnet_id              = aws_subnet.public[0].id
  vpc_security_group_ids = [aws_security_group.bastion.id]
  associate_public_ip_address = true
  ebs_optimized          = var.ebs_optimized

  # Require IMDSv2
  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  # Encrypt root block device
  root_block_device {
    encrypted = true
  }

  tags = merge(local.common_tags, {
    Name = "bastion-host"
  })

  lifecycle {
    # Prevent accidental destruction of bastion
    prevent_destroy = true
  }
}

# Data source for Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.99.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "destination"
  region = var.destination_region
}

# ----------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------------------------------------------------------

variable "destination_region" {
  description = "Region for the cross-region backup vault"
  type        = string
  default     = "us-west-1"
}

variable "create_daily_backup" {
  description = "Whether to include the daily backup rule in the plan"
  type        = bool
  default     = true
}

variable "excluded_rds_arns" {
  description = "List of RDS instance ARNs to exclude from backups"
  type        = list(string)
  default     = []
}

variable "enable_cross_account_copy" {
  description = "Enable copy of backups to a cross-account vault"
  type        = bool
  default     = false
}

variable "cross_account_destination_vault_arn" {
  description = "ARN of the cross-account backup vault"
  type        = string
  default     = ""
}

locals {
  cross_account_vault_arn = var.cross_account_destination_vault_arn
}

# ----------------------------------------------------------------------------------------------------------------------
# KMS KEYS
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_kms_key" "primary_vault_key" {
  description             = "KMS key for AWS Backup vaults in primary region"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key" "cross_region_vault_key" {
  provider = aws.destination

  description             = "KMS key for AWS Backup vault in cross-region"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# BACKUP VAULTS
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_backup_vault" "daily" {
  name        = "DailyBackupVault-v2"
  kms_key_arn = aws_kms_key.primary_vault_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "weekly" {
  name        = "WeeklyBackupVault-v2"
  kms_key_arn = aws_kms_key.primary_vault_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "monthly" {
  name        = "MonthlyBackupVault-v2"
  kms_key_arn = aws_kms_key.primary_vault_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "yearly" {
  name        = "YearlyBackupVault-v2"
  kms_key_arn = aws_kms_key.primary_vault_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault" "cross_region" {
  provider = aws.destination

  name        = "CrossRegionBackupVault-v2"
  kms_key_arn = aws_kms_key.cross_region_vault_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# IAM ROLE FOR AWS BACKUP
# ----------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "backup_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["backup.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "backup_service_role" {
  name               = "AWSBackupServiceRole-v2"
  assume_role_policy = data.aws_iam_policy_document.backup_trust.json
}

resource "aws_iam_role_policy_attachment" "backup_policy" {
  role       = aws_iam_role.backup_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# ----------------------------------------------------------------------------------------------------------------------
# BACKUP PLAN
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_backup_plan" "rds_backup" {
  name = "RDS-Backup-Plan"

  dynamic "rule" {
    for_each = var.create_daily_backup ? ["daily"] : []
    content {
      rule_name         = "DailyBackupRule"
      target_vault_name = aws_backup_vault.daily.name
      schedule          = "cron(0 2 * * ? *)"

      lifecycle {
        delete_after = 7
      }

      copy_action {
        destination_vault_arn = aws_backup_vault.cross_region.arn
      }

      dynamic "copy_action" {
        for_each = var.enable_cross_account_copy && local.cross_account_vault_arn != "" ? ["cross_account"] : []
        content {
          destination_vault_arn = local.cross_account_vault_arn
        }
      }
    }
  }

  rule {
    rule_name         = "WeeklyBackupRule"
    target_vault_name = aws_backup_vault.weekly.name
    schedule          = "cron(0 2 ? * SUN *)"

    lifecycle {
      delete_after = 30
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy && local.cross_account_vault_arn != "" ? ["cross_account"] : []
      content {
        destination_vault_arn = local.cross_account_vault_arn
      }
    }
  }

  rule {
    rule_name         = "MonthlyBackupRule"
    target_vault_name = aws_backup_vault.monthly.name
    schedule          = "cron(0 3 1 * ? *)"

    lifecycle {
      delete_after = 365
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy && local.cross_account_vault_arn != "" ? ["cross_account"] : []
      content {
        destination_vault_arn = local.cross_account_vault_arn
      }
    }
  }

  rule {
    rule_name         = "YearlyBackupRule"
    target_vault_name = aws_backup_vault.yearly.name
    schedule          = "cron(0 4 1 1 ? *)"

    lifecycle {
      delete_after = 2555
    }

    copy_action {
      destination_vault_arn = aws_backup_vault.cross_region.arn
    }

    dynamic "copy_action" {
      for_each = var.enable_cross_account_copy && local.cross_account_vault_arn != "" ? ["cross_account"] : []
      content {
        destination_vault_arn = local.cross_account_vault_arn
      }
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# BACKUP SELECTION – ALL RDS EXCEPT EXCLUDED
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_backup_selection" "all_rds" {
  iam_role_arn = aws_iam_role.backup_service_role.arn
  plan_id      = aws_backup_plan.rds_backup.id
  name         = "AllRDSInstances"

  resources = ["arn:aws:rds:*:*:db:*"]

  not_resources = var.excluded_rds_arns
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables for IAM account password policy
# ----------------------------------------------------------------------
variable "allow_users_to_change_password" {
  type    = bool
  default = true
}

variable "hard_expiry" {
  type    = bool
  default = false
}

variable "max_password_age" {
  type    = number
  default = 90
}

variable "minimum_password_length" {
  type    = number
  default = 14
}

variable "password_reuse_prevention" {
  type    = number
  default = 24
}

variable "require_lowercase_characters" {
  type    = bool
  default = true
}

variable "require_uppercase_characters" {
  type    = bool
  default = true
}

variable "require_numbers" {
  type    = bool
  default = true
}

variable "require_symbols" {
  type    = bool
  default = true
}

# ----------------------------------------------------------------------
# Account password policy
# ----------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  allow_users_to_change_password = var.allow_users_to_change_password
  hard_expiry                    = var.hard_expiry
  max_password_age               = var.max_password_age
  minimum_password_length        = var.minimum_password_length
  password_reuse_prevention      = var.password_reuse_prevention
  require_lowercase_characters   = var.require_lowercase_characters
  require_uppercase_characters   = var.require_uppercase_characters
  require_numbers                = var.require_numbers
  require_symbols                = var.require_symbols
}

# ----------------------------------------------------------------------
# IAM Groups
# ----------------------------------------------------------------------
resource "aws_iam_group" "administrators" {
  name = "administrators"
}

resource "aws_iam_group" "developpers" {
  name = "developpers"
}

resource "aws_iam_group" "prod_users" {
  name = "prod_users"
}

# ----------------------------------------------------------------------
# IAM Policy Documents
# ----------------------------------------------------------------------
data "aws_iam_policy_document" "developpers_policy_doc" {
  statement {
    actions   = ["ec2:*", "rds:*"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["dev"]
    }
  }
}

data "aws_iam_policy_document" "prod_users_policy_doc" {
  statement {
    actions   = ["ec2:*", "rds:*"]
    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/env"
      values   = ["preprod", "prod"]
    }
  }
}

data "aws_iam_policy_document" "administrators_policy_doc" {
  statement {
    effect      = "Allow"
    not_actions = ["iam:*", "organizations:*", "account:*"]
    resources   = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:ResourceTag/security"
      values   = ["high"]
    }
  }

  statement {
    effect    = "Allow"
    actions   = [
      "iam:CreateServiceLinkedRole",
      "iam:DeleteServiceLinkedRole",
      "iam:ListRoles",
      "organizations:DescribeOrganization",
      "account:ListRegions"
    ]
    resources = ["*"]
  }
}

# ----------------------------------------------------------------------
# IAM Policies
# ----------------------------------------------------------------------
resource "aws_iam_policy" "developpers_policy" {
  name        = "developpers_policy"
  description = "Policy for developers group"
  policy      = data.aws_iam_policy_document.developpers_policy_doc.json
}

resource "aws_iam_policy" "prod_users_policy" {
  name        = "prod_users_policy"
  description = "Policy for prod users group"
  policy      = data.aws_iam_policy_document.prod_users_policy_doc.json
}

resource "aws_iam_policy" "administrators_policy" {
  name        = "administrators_policy"
  description = "Policy for administrators group"
  policy      = data.aws_iam_policy_document.administrators_policy_doc.json
}

# ----------------------------------------------------------------------
# Attach policies to groups
# ----------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "developpers_attach" {
  group      = aws_iam_group.developpers.name
  policy_arn = aws_iam_policy.developpers_policy.arn
}

resource "aws_iam_group_policy_attachment" "prod_users_attach" {
  group      = aws_iam_group.prod_users.name
  policy_arn = aws_iam_policy.prod_users_policy.arn
}

resource "aws_iam_group_policy_attachment" "administrators_attach" {
  group      = aws_iam_group.administrators.name
  policy_arn = aws_iam_policy.administrators_policy.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "resource_name_prefix" {
  description = "Prefix for naming resources"
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "VPC instance tenancy"
  type        = string
  default     = "default"
}

variable "vpc_cidr" {
  description = "Main VPC CIDR block"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound NACL rules for private subnets"
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      protocol    = "tcp"
      from_port   = "1024"
      to_port     = "65535"
      action      = "allow"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound NACL rules for private subnets"
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      protocol    = "tcp"
      from_port   = "443"
      to_port     = "443"
      action      = "allow"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name        = "${var.resource_name_prefix}-vpc"
    Environment = var.resource_name_prefix
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name        = "${var.resource_name_prefix}-private-subnet-${count.index}"
    Environment = var.resource_name_prefix
  }
}

resource "aws_route_table" "private" {
  count = 2

  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${var.resource_name_prefix}-private-rt-${count.index}"
    Environment = var.resource_name_prefix
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${var.region}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  tags = {
    Name        = "${var.resource_name_prefix}-s3-gateway-endpoint"
    Environment = var.resource_name_prefix
  }
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules
    content {
      rule_no    = tonumber(ingress.value.rule_number)
      protocol   = ingress.value.protocol
      from_port  = tonumber(ingress.value.from_port)
      to_port    = tonumber(ingress.value.to_port)
      action     = ingress.value.action
      cidr_block = ingress.value.cidr_block
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules
    content {
      rule_no    = tonumber(egress.value.rule_number)
      protocol   = egress.value.protocol
      from_port  = tonumber(egress.value.from_port)
      to_port    = tonumber(egress.value.to_port)
      action     = egress.value.action
      cidr_block = egress.value.cidr_block
    }
  }

  tags = {
    Name        = "${var.resource_name_prefix}-private-acl"
    Environment = var.resource_name_prefix
  }
}

resource "aws_network_acl_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private.id
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

variable "namespace" {
  type        = string
  default     = ""
  description = "Namespace for the null-label context"
}

variable "environment" {
  type        = string
  default     = ""
  description = "Environment for the null-label context"
}

variable "stage" {
  type        = string
  default     = ""
  description = "Stage for the null-label context"
}

variable "name" {
  type        = string
  default     = "vpc"
  description = "Name for the null-label context"
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter for the null-label context"
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional attributes for the null-label context"
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags to apply to all resources"
}

variable "vpc_cidr_block" {
  type        = string
  default     = "11.0.0.0/16"
  description = "Primary IPv4 CIDR block for the VPC. Ignored when `vpc_ipv4_ipam_pool_id` is set."
}

variable "vpc_instance_tenancy" {
  type        = string
  default     = "default"
  description = "Instance tenancy for the VPC"
}

variable "enable_dns_hostnames" {
  type        = bool
  default     = true
  description = "Enable DNS hostnames in the VPC"
}

variable "enable_dns_support" {
  type        = bool
  default     = true
  description = "Enable DNS support in the VPC"
}

variable "assign_generated_ipv6_cidr_block" {
  type        = bool
  default     = true
  description = "Assign an Amazon-provided IPv6 /56 CIDR block to the VPC. Ignored when `vpc_ipv6_ipam_pool_id` is set."
}

variable "vpc_ipv4_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID for the primary IPv4 CIDR allocation"
}

variable "vpc_ipv4_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length for the primary IPv4 CIDR allocation when using IPAM"
}

variable "vpc_ipv6_ipam_pool_id" {
  type        = string
  default     = null
  description = "IPAM pool ID for the primary IPv6 CIDR allocation"
}

variable "vpc_ipv6_netmask_length" {
  type        = number
  default     = null
  description = "Netmask length for the primary IPv6 CIDR allocation when using IPAM"
}

variable "additional_ipv4_cidr_block_associations" {
  type = map(object({
    cidr_block          = optional(string)
    ipv4_ipam_pool_id   = optional(string)
    ipv4_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default     = {}
  description = "Map of additional IPv4 CIDR block associations for the VPC"
}

variable "additional_ipv6_cidr_block_associations" {
  type = map(object({
    ipv6_cidr_block     = optional(string)
    ipv6_ipam_pool_id   = optional(string)
    ipv6_netmask_length = optional(number)
    create_timeout      = optional(string)
    delete_timeout      = optional(string)
  }))
  default     = {}
  description = "Map of additional IPv6 CIDR block associations for the VPC"
}

variable "default_security_group_deny_all" {
  type        = bool
  default     = true
  description = "Manage the default security group and remove all ingress/egress rules"
}

variable "manage_default_route_table" {
  type        = bool
  default     = false
  description = "Manage the default route table for the VPC"
}

variable "manage_default_network_acl" {
  type        = bool
  default     = false
  description = "Manage the default network ACL for the VPC"
}

variable "internet_gateway_enabled" {
  type        = bool
  default     = true
  description = "Create an internet gateway for the VPC"
}

variable "ipv6_egress_only_internet_gateway_enabled" {
  type        = bool
  default     = false
  description = "Create an IPv6 egress-only internet gateway for the VPC"
}

locals {
  label = join(
    var.delimiter,
    compact([
      var.namespace,
      var.environment,
      var.stage,
      var.name,
      join(var.delimiter, var.attributes)
    ])
  )

  label_tags = {
    Name = local.label
  }

  namespace_tags = var.namespace != "" ? { Namespace = var.namespace } : {}
  environment_tags = var.environment != "" ? { Environment = var.environment } : {}
  stage_tags = var.stage != "" ? { Stage = var.stage } : {}

  tags = merge(
    var.tags,
    local.label_tags,
    local.namespace_tags,
    local.environment_tags,
    local.stage_tags
  )
}

resource "aws_vpc" "this" {
  cidr_block                       = var.vpc_ipv4_ipam_pool_id == null ? var.vpc_cidr_block : null
  instance_tenancy                 = var.vpc_instance_tenancy
  enable_dns_hostnames             = var.enable_dns_hostnames
  enable_dns_support               = var.enable_dns_support
  assign_generated_ipv6_cidr_block = var.vpc_ipv6_ipam_pool_id == null ? var.assign_generated_ipv6_cidr_block : null
  ipv4_ipam_pool_id                = var.vpc_ipv4_ipam_pool_id
  ipv4_netmask_length              = var.vpc_ipv4_netmask_length
  ipv6_ipam_pool_id                = var.vpc_ipv6_ipam_pool_id
  ipv6_netmask_length              = var.vpc_ipv6_netmask_length

  tags = local.tags
}

resource "aws_vpc_ipv4_cidr_block_association" "this" {
  for_each = var.additional_ipv4_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  cidr_block          = each.value.ipv4_ipam_pool_id == null ? each.value.cidr_block : null
  ipv4_ipam_pool_id   = each.value.ipv4_ipam_pool_id
  ipv4_netmask_length = each.value.cidr_block != null ? null : each.value.ipv4_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

resource "aws_vpc_ipv6_cidr_block_association" "this" {
  for_each = var.additional_ipv6_cidr_block_associations

  vpc_id              = aws_vpc.this.id
  ipv6_cidr_block     = each.value.ipv6_ipam_pool_id == null ? each.value.ipv6_cidr_block : null
  ipv6_ipam_pool_id   = each.value.ipv6_ipam_pool_id
  ipv6_netmask_length = each.value.ipv6_cidr_block != null ? null : each.value.ipv6_netmask_length

  timeouts {
    create = each.value.create_timeout
    delete = each.value.delete_timeout
  }
}

resource "aws_default_security_group" "this" {
  count = var.default_security_group_deny_all ? 1 : 0

  vpc_id  = aws_vpc.this.id
  ingress = []
  egress  = []

  tags = local.tags
}

resource "aws_default_route_table" "this" {
  count = var.manage_default_route_table ? 1 : 0

  default_route_table_id = aws_vpc.this.default_route_table_id

  tags = local.tags
}

resource "aws_default_network_acl" "this" {
  count = var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = aws_vpc.this.default_network_acl_id

  tags = local.tags
}

resource "aws_internet_gateway" "this" {
  count = var.internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = local.tags
}

resource "aws_egress_only_internet_gateway" "this" {
  count = var.ipv6_egress_only_internet_gateway_enabled ? 1 : 0

  vpc_id = aws_vpc.this.id

  tags = local.tags
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment_prefix" {
  type    = string
  default = "DEV"
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "create_private_subnet" {
  type    = bool
  default = false
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = "${var.environment_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.1.0/24" : "10.0.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-public-subnet-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.environment_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.environment_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_subnet" "private" {
  count = var.create_private_subnet ? 2 : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = count.index == 0 ? "10.0.10.0/24" : "10.0.11.0/24"
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.environment_prefix}-private-subnet-${count.index}"
  }
}

resource "aws_eip" "nat" {
  count = var.create_private_subnet ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${var.environment_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  count = var.create_private_subnet ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${var.environment_prefix}-nat-gw"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = var.create_private_subnet ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[0].id
  }

  tags = {
    Name = "${var.environment_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnet ? 2 : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# ---------------------------------------------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ---------------------------------------------------------------------------------------------------------------------

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DATA SOURCES (static provider metadata only)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

# ---------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ---------------------------------------------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the primary SQS queue and all dependent resources."
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the queue. If not provided, name_prefix will be used. For FIFO queues, '.fifo' is automatically appended."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the queue name. Used when name is not provided. For FIFO queues, '.fifo' is automatically appended."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the primary queue is a FIFO queue."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication for FIFO queues."
  type        = bool
  default     = true
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values: 'messageGroup' and 'queue'."
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values: 'perQueue' and 'perMessageGroupId'."
  type        = string
  default     = "perQueue"
}

variable "sqs_managed_sse_enabled" {
  description = "Whether to use SQS-managed server-side encryption. If true, no KMS key is used."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of a custom KMS master key to use for encryption. If provided, sqs_managed_sse_enabled is automatically set to false."
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Whether to create an IAM policy attached to the queue."
  type        = bool
  default     = false
}

variable "queue_policy_source" {
  description = "Optional JSON string of an IAM policy document to use as the source (base) policy."
  type        = string
  default     = null
}

variable "queue_policy_override" {
  description = "Optional JSON string of an IAM policy document to override the source policy."
  type        = string
  default     = null
}

variable "create_dlq" {
  description = "Whether to create a dead-letter queue for the primary queue."
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to restrict the dead-letter queue's redrive permission to the primary queue."
  type        = bool
  default     = true
}

variable "max_receive_count" {
  description = "The maximum number of times a message can be received before being sent to the dead-letter queue."
  type        = number
  default     = 5
}

variable "tags" {
  description = "A map of tags to assign to all resources."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------------------------------------------------------------
# LOCALS
# ---------------------------------------------------------------------------------------------------------------------

locals {
  # Ensure that at least one of name or name_prefix is provided
  # (We do not validate here, but provider will enforce if both null)
  queue_name = var.name != null ? var.name : var.name_prefix != null ? var.name_prefix : "default-queue"

  # For FIFO queues, append .fifo suffix if not already present
  primary_queue_name = var.fifo_queue ? (
    endswith(local.queue_name, ".fifo") ? local.queue_name : "${local.queue_name}.fifo"
  ) : local.queue_name

  dlq_name = var.fifo_queue ? (
    endswith("${local.queue_name}-dlq", ".fifo") ? "${local.queue_name}-dlq" : "${local.queue_name}-dlq.fifo"
  ) : "${local.queue_name}-dlq"

  # Determine encryption settings for primary queue
  use_sqs_managed_sse = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false
  use_kms_key         = var.kms_master_key_id != null

  # Construct the primary queue ARN using data sources (no resource dependency)
  primary_queue_arn = "arn:aws:sqs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:${local.primary_queue_name}"

  # Redrive allow policy JSON for DLQ (only when create_dlq_redrive_allow_policy is true)
  dlq_redrive_allow_policy = var.create_dlq_redrive_allow_policy ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = "*"
        Action    = "sqs:SendMessage"
        Resource  = local.primary_queue_arn
        Condition = {
          ArnEquals = {
            "aws:SourceArn" = local.primary_queue_arn
          }
        }
      }
    ]
  }) : null
}

# ---------------------------------------------------------------------------------------------------------------------
# PRIMARY QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "primary" {
  count = var.create ? 1 : 0

  name   = var.name != null ? local.primary_queue_name : null
  name_prefix = var.name == null ? local.primary_queue_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope        = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit      = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms_key ? var.kms_master_key_id : null

  # Redrive policy: point to DLQ if created
  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = try(aws_sqs_queue.dead_letter[0].arn, "")
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# DEAD-LETTER QUEUE
# ---------------------------------------------------------------------------------------------------------------------

resource "aws_sqs_queue" "dead_letter" {
  count = var.create && var.create_dlq ? 1 : 0

  name   = var.name != null ? local.dlq_name : null
  name_prefix = var.name == null ? local.dlq_name : null

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope        = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit      = var.fifo_queue ? var.fifo_throughput_limit : null

  sqs_managed_sse_enabled = local.use_sqs_managed_sse ? true : null
  kms_master_key_id       = local.use_kms_key ? var.kms_master_key_id : null

  # Redrive allow policy to restrict redrive to primary queue
  redrive_allow_policy = local.dlq_redrive_allow_policy

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------------------------------------------------
# QUEUE POLICY (attached to primary queue)
# ---------------------------------------------------------------------------------------------------------------------

data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = var.queue_policy_source != null ? [var.queue_policy_source] : []
  override_policy_documents = var.queue_policy_override != null ? [var.queue_policy_override] : []

  # Default policy when no source or override is provided
  dynamic "statement" {
    for_each = var.queue_policy_source == null && var.queue_policy_override == null ? [1] : []
    content {
      effect    = "Allow"
      actions   = ["sqs:*"]
      resources = [aws_sqs_queue.primary[0].arn]
    }
  }
}

resource "aws_sqs_queue_policy" "primary" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.primary[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

