terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "backup_name" {
  type        = string
  default     = "my-backup"
  description = "Name for the backup vault, plan, and IAM role."
  validation {
    condition     = length(var.backup_name) > 0
    error_message = "backup_name must not be empty."
  }
}

variable "account_type" {
  type        = string
  default     = "workload"
  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  type        = string
  default     = null
}

variable "vault_policy" {
  type        = string
  default     = null
}

variable "min_retention_days" {
  type        = number
  default     = null
}

variable "max_retention_days" {
  type        = number
  default     = null
}

variable "changeable_for_days" {
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  type        = string
  default     = null
}

variable "selection_resources" {
  type        = list(string)
  default     = []
}

variable "rule_schedule" {
  type        = string
  default     = "cron(0 5 ? * * *)"
}

variable "copy_destinations" {
  type = list(object({
    destination_region    = string
    destination_vault_arn = optional(string)
    lifecycle = optional(object({
      cold_storage_after = optional(number)
      delete_after       = optional(number)
    }))
  }))
  default = []
}

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = var.min_retention_days != null ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications && var.sns_topic_arn != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  sns_topic_arn     = var.sns_topic_arn
  backup_vault_events = [
    "BACKUP_JOB_FAILED",
    "COPY_JOB_FAILED",
  ]
}

data "aws_iam_policy" "aws_backup_service_role" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

resource "aws_iam_role" "aws_backup" {
  count = var.account_type == "workload" ? 1 : 0

  name = "aws-backup-${var.backup_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "aws_backup" {
  count = var.account_type == "workload" ? 1 : 0

  role       = aws_iam_role.aws_backup[0].name
  policy_arn = data.aws_iam_policy.aws_backup_service_role.arn
}

resource "aws_backup_plan" "backup_plan" {
  count = var.account_type == "workload" ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = var.backup_name
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120
    recovery_point_tags = {
      Backup = "true"
    }

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    dynamic "copy_action" {
      for_each = var.copy_destinations
      content {
        destination_vault_arn = try(
          copy_action.value.destination_vault_arn,
          "arn:aws:backup:${copy_action.value.destination_region}:${data.aws_caller_identity.current.account_id}:backup-vault:Default"
        )
        dynamic "lifecycle" {
          for_each = copy_action.value.lifecycle != null ? [copy_action.value.lifecycle] : []
          content {
            cold_storage_after = lifecycle.value.cold_storage_after
            delete_after       = lifecycle.value.delete_after
          }
        }
      }
    }
  }
}

resource "aws_backup_selection" "backup_selection" {
  count = var.account_type == "workload" ? 1 : 0

  iam_role_arn = aws_iam_role.aws_backup[0].arn
  plan_id      = aws_backup_plan.backup_plan[0].id
  name         = "${var.backup_name}-selection"

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }

  resources = length(var.selection_resources) > 0 ? var.selection_resources : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

resource "random_pet" "suffix" {
  length    = 2
  separator = "-"
}

locals {
  name_prefix = "config-${random_pet.suffix.id}"
}

# IAM Role for AWS Config
resource "aws_iam_role" "config" {
  name = local.name_prefix
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "config.amazonaws.com"
        },
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name = "${local.name_prefix}-sns-publish"
  role = aws_iam_role.config.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect   = "Allow",
        Action   = "sns:Publish",
        Resource = aws_sns_topic.config.arn
      }
    ]
  })
}

# S3 Snapshot Bucket
resource "aws_s3_bucket" "snapshot" {
  bucket        = "${local.name_prefix}-snapshots"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket                  = aws_s3_bucket.snapshot.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }
  }
}

resource "aws_s3_bucket_policy" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Sid    = "AllowConfigServiceAndRole"
        Effect = "Allow"
        Principal = {
          Service = "config.amazonaws.com"
        }
        Action   = ["s3:PutObject"]
        Resource = "${aws_s3_bucket.snapshot.arn}/*"
      }
    ]
  })
}

# KMS Key for SNS Topic and S3 SSE
data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms_key" {
  statement {
    sid    = "Enable IAM User Permissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "Allow SNS service to encrypt/decrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:Encrypt"    ]
    resources = ["*"]
  }
  statement {
    sid    = "Allow Config service to use key for delivery"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "Allow S3 service to ue key for SSE-KMS"
    effect = "Allow"
    principals {
      typ        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "config" {
  description         = "KMS key for AWS Config SNS notificatons and S3 encryption"
  enable_key_rotation = true
  policy              = data.aws_iam_policy_document.kms_key.json
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.name_prefix}-snss3"
  target_key_id = aws_km_key.config.key_id
}

# SNS Topic
resource "aws_sns_topic" "config" {
  name              = local.name_prefix
  kms_master_key_id = aws_kms_key.config.arn
}

# AWS Config Recorder
resource "aws_config_configuration_recorder" "main" {
  name     = "${local.ame_prefix}-recorder"
  rei_arn = aws_iam_role.config.arn
  reording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

# Aws Config Delivery Channel
resource "aws_config_delivery_channel" "main" {
  name           = "${local.name_prefix}-delivery-channel"
  s3_bcket_name = aws_s3_bucket.snapsht.bucket
  s3_key_prefix  = "awsconfig/records"
  s3_kms_key_arn = aw_kms_key.config.arn
  sns_topic_arn = aws_sns_topic.config.arn
  depens_on     = [
    aws_config_configuration_recorder.main,
    aws_s3_bcket_policy.snapshot
  ]
}

# Eleven Managed Config Rules
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                       = "${local.name_prefix}-cloudtrail-enaled"
  description                = "Cecks tah CloudTrail is enabled"
  maximum_execution_frequecy = "TwentyFour_Hurs"
  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }
  depnds_on = [aws_config_configuration_recorder.main]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                       = "${local.name_prefix}-iam_pw-policy"
  desription                = "Cecks IA password policy"
  maximum_execution_frequency = "TwentyFour_Hours"
  source {
    owner             = "AWS"
    source_identifer = "IAM_PASSWORD_POLICY"
  }
  depnds_on = ["aws_config_cofiguration_recorder.main"]
}

# Terraform and provider constraints
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Data source for current region
data "aws_region" "current" {}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name    = "bjit-vpc"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(["10.0.4.0/24", "10.0.6.0/24", "10.0.8.0/24"], count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name    = "bjit-public-subnet-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(["10.0.10.0/24", "10.0.12.0/24", "10.0.14.0/24"], count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name    = "bjit-private-subnet-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-igw"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name    = "bjit-public-rt"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  tags = {
    Name    = "bjit-private-rt-${count.index + 1}"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 VPC Gateway Endpoint
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name    = "bjit-s3-endpoint"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

# Security Groups
resource "aws_security_group" "alb" {
  name        = "bjit-api-server-ALB-SG"
  description = "Security group for ALB allowing HTTP/HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name    = "bjit-api-server-ALB-SG"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

resource "aws_security_group" "mariadb" {
  name        = "bjit-mariaDB-RDS-SG"
  description = "Security group for MariaDB RDS allowing MySQL from VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name    = "bjit-mariaDB-RDS-SG"
    Project = "BJIT DevOps Task"
    Author  = "Ariful Islam"
  }
}

