resource "aws_security_group" "allow_tls" {
  name        = "allow_tls"
  description = "Public security group for web tier"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Outbound to VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.project_vpc.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "allow_tls"
  })
}

resource "aws_security_group" "pvt_seg" {
  name        = "pvt-seg"
  description = "Private security group for database tier"
  vpc_id      = aws_vpc.project_vpc.id

  ingress {
    description     = "HTTP from public SG"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "HTTPS from public SG"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "SSH from public SG"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  ingress {
    description     = "PostgreSQL from public SG"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.allow_tls.id]
  }

  egress {
    description     = "Outbound to public SG only"
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.allow_tls.id]
  }

  tags = merge(local.common_tags, {
    Name = "pvt-seg"
  })
}

# ------------------------------------------------------------------------------
# Terraform and provider configuration
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Data sources for dynamic region and account
# ------------------------------------------------------------------------------
data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Import existing resources into Terraform state
# ------------------------------------------------------------------------------
import {
  to = aws_dynamodb_table.pets
  id = "Pets"
}

import {
  to = aws_iam_role.apigw_dynamodb_role
  id = "apigw-dynamodb-role"
}

import {
  to = aws_iam_role.cloudwatch_role
  id = "apigw-cloudwatch-role"
}

import {
  to = aws_cloudwatch_log_group.apigw
  id = "/aws/APIGW/terraform"
}

# ------------------------------------------------------------------------------
# DynamoDB: Pets table with PetType-index GSI
# ------------------------------------------------------------------------------
resource "aws_dynamodb_table" "pets" {
  name           = "Pets"
  billing_mode   = "PROVISIONED"
  hash_key       = "id"
  read_capacity  = 5
  write_capacity = 5

  attribute {
    name = "id"
    type = "S"
  }

  attribute {
    name = "PetType"
    type = "S"
  }

  global_secondary_index {
    name            = "PetType-index"
    hash_key        = "PetType"
    projection_type = "INCLUDE"
    non_key_attributes = ["PetName", "PetPrice"]
    read_capacity   = 5
    write_capacity  = 5
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM role for API Gateway → DynamoDB integration
# ------------------------------------------------------------------------------
resource "aws_iam_role" "apigw_dynamodb_role" {
  name = "apigw-dynamodb-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "apigateway.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "apigw_dynamodb_policy" {
  name = "apigw-dynamodb-policy"
  role = aws_iam_role.apigw_dynamodb_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "dynamodb:PutItem"
        Resource = aws_dynamodb_table.pets.arn
      },
      {
        Effect   = "Allow"
        Action   = "dynamodb:Query"
        Resource = [
          aws_dynamodb_table.pets.arn,
          "${aws_dynamodb_table.pets.arn}/index/PetType-index"
        ]
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# API Gateway REST API
# ------------------------------------------------------------------------------
resource "aws_api_gateway_rest_api" "main" {
  name = "APIGW DynamoDB Serverless Pattern Demo"
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  api_key_source = "HEADER"
}

# ------------------------------------------------------------------------------
# API Gateway Resources: /pets and /pets/{PetType}
# ------------------------------------------------------------------------------
resource "aws_api_gateway_resource" "pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_rest_api.main.root_resource_id
  path_part   = "pets"
}

resource "aws_api_gateway_resource" "pet_type" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  parent_id   = aws_api_gateway_resource.pets.id
  path_part   = "{PetType}"
}

# ------------------------------------------------------------------------------
# POST /pets – Method, Integration, Method Response, Integration Response
# ------------------------------------------------------------------------------
resource "aws_api_gateway_method" "post_pets" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.pets.id
  http_method   = "POST"
  authorization = "NONE"
  api_key_required = true
}

resource "aws_api_gateway_method_response" "post_pets" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = "200"
  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration" "post_pets" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.pets.id
  http_method             = aws_api_gateway_method.post_pets.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.region}:dynamodb:action/PutItem"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<VTL
#set($inputRoot = $input.path('$'))
{
  "TableName": "Pets",
  "Item": {
    "id": {"S": "$context.requestId"},
    "PetBoolean": {"BOOL": true},
    #foreach($key in $inputRoot.keySet())
      #if($key != "id" && $key != "PetBoolean")
        "$key": {"S": "$inputRoot.get($key)"}
        #if($foreach.hasNext),#end
      #end
    #end
  }
}
VTL
  }
}

resource "aws_api_gateway_integration_response" "post_pets" {
  depends_on = [aws_api_gateway_integration.post_pets]

  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pets.id
  http_method = aws_api_gateway_method.post_pets.http_method
  status_code = aws_api_gateway_method_response.post_pets.status_code
  selection_pattern = ""
}

# ------------------------------------------------------------------------------
# GET /pets/{PetType} – Method, Integration, Method Response, Integration Response
# ------------------------------------------------------------------------------
resource "aws_api_gateway_method" "get_pets_by_type" {
  rest_api_id   = aws_api_gateway_rest_api.main.id
  resource_id   = aws_api_gateway_resource.pet_type.id
  http_method   = "GET"
  authorization = "NONE"
  api_key_required = true
  request_parameters = {
    "method.request.path.PetType" = true
  }
}

resource "aws_api_gateway_method_response" "get_pets_by_type" {
  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = "200"
  response_models = {
    "application/json" = "Empty"
  }
}

resource "aws_api_gateway_integration" "get_pets_by_type" {
  rest_api_id             = aws_api_gateway_rest_api.main.id
  resource_id             = aws_api_gateway_resource.pet_type.id
  http_method             = aws_api_gateway_method.get_pets_by_type.http_method
  integration_http_method = "POST"
  type                    = "AWS"
  uri                     = "arn:aws:apigateway:${data.aws_region.current.region}:dynamodb:action/Query"
  credentials             = aws_iam_role.apigw_dynamodb_role.arn

  request_templates = {
    "application/json" = <<VTL
{
  "TableName": "Pets",
  "IndexName": "PetType-index",
  "KeyConditionExpression": "#pt = :pt",
  "ExpressionAttributeNames": {
    "#pt": "PetType"
  },
  "ExpressionAttributeValues": {
    ":pt": {"S": "$util.urlDecode($input.params('PetType'))"}
  }
}
VTL
  }
}

resource "aws_api_gateway_integration_response" "get_pets_by_type" {
  depends_on = [aws_api_gateway_integration.get_pets_by_type]

  rest_api_id = aws_api_gateway_rest_api.main.id
  resource_id = aws_api_gateway_resource.pet_type.id
  http_method = aws_api_gateway_method.get_pets_by_type.http_method
  status_code = aws_api_gateway_method_response.get_pets_by_type.status_code
  selection_pattern = ""

  response_templates = {
    "application/json" = <<VTL
#set($items = $input.path('$.Items'))
[
  #foreach($item in $items)
    #set($itemJson = $util.dynamodb.fromDynamoDbJson($item))
    #if($foreach.hasNext)
    $itemJson,
    #else
    $itemJson
    #end
  #end
]
VTL
  }
}

# ------------------------------------------------------------------------------
# Deployment & Stage
# ------------------------------------------------------------------------------
resource "aws_api_gateway_deployment" "main" {
  depends_on = [
    aws_api_gateway_integration.post_pets,
    aws_api_gateway_integration.get_pets_by_type,
    aws_api_gateway_integration_response.post_pets,
    aws_api_gateway_integration_response.get_pets_by_type,
    aws_api_gateway_method.post_pets,
    aws_api_gateway_method.get_pets_by_type,
    aws_api_gateway_method_response.post_pets,
    aws_api_gateway_method_response.get_pets_by_type,
    aws_api_gateway_resource.pets,
    aws_api_gateway_resource.pet_type
  ]

  rest_api_id = aws_api_gateway_rest_api.main.id
}

resource "aws_api_gateway_stage" "main" {
  deployment_id = aws_api_gateway_deployment.main.id
  rest_api_id   = aws_api_gateway_rest_api.main.id
  stage_name    = "v1"

  access_log_settings {
    destination_arn = "arn:aws:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.apigw.name}"
    format = jsonencode({
      requestId        = "$context.requestId"
      extendedRequestId = "$context.extendedRequestId"
      ip               = "$context.identity.sourceIp"
      caller           = "$context.identity.caller"
      user             = "$context.identity.user"
      requestTime      = "$context.requestTime"
      httpMethod       = "$context.httpMethod"
      resourcePath     = "$context.resourcePath"
      status           = "$context.status"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
    })
  }
}

# ------------------------------------------------------------------------------
# API Gateway Account – CloudWatch Role
# ------------------------------------------------------------------------------
resource "aws_iam_role" "cloudwatch_role" {
  name = "apigw-cloudwatch-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "apigateway.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "cloudwatch_policy" {
  name = "apigw-cloudwatch-policy"
  role = aws_iam_role.cloudwatch_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:DescribeLogGroups",
        "logs:DescribeLogStreams",
        "logs:PutLogEvents"
      ]
      Resource = "*"
    }]
  })
}

resource "aws_api_gateway_account" "main" {
  cloudwatch_role_arn = aws_iam_role.cloudwatch_role.arn
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group and Resource Policy
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "apigw" {
  name              = "/aws/APIGW/terraform"
  retention_in_days = 7
}

resource "aws_cloudwatch_log_resource_policy" "apigw" {
  policy_name = "apigw-log-policy"

  policy_document = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "apigateway.amazonaws.com"
      }
      Action = [
        "logs:PutLogEvents",
        "logs:CreateLogStream"
      ]
      Resource = "arn:aws:logs:${data.aws_region.current.region}:${data.aws_caller_identity.current.account_id}:log-group:${aws_cloudwatch_log_group.apigw.name}:*"
      Condition = {
        ArnLike = {
          "aws:SourceArn" = aws_api_gateway_rest_api.main.execution_arn
        }
      }
    }]
  })
}

# ------------------------------------------------------------------------------
# API Key, Usage Plan, and Usage Plan Key
# ------------------------------------------------------------------------------
resource "aws_api_gateway_api_key" "main" {
  name    = "apigw-dynamodb-terraform-api-key"
  enabled = true
}

resource "aws_api_gateway_usage_plan" "main" {
  name = "apigw-dynamodb-terraform-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.main.id
    stage  = aws_api_gateway_stage.main.stage_name
  }

  throttle_settings {
    burst_limit = 20
    rate_limit  = 100
  }

  quota_settings {
    limit  = 1000
    period = "MONTH"
  }
}

resource "aws_api_gateway_usage_plan_key" "main" {
  key_id        = aws_api_gateway_api_key.main.id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.main.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "name" {
  description = "Prefix for bucket names"
  type        = string
  default     = "sadcloud"
}

variable "no_versioning" {
  description = "Disable versioning on main bucket"
  type        = bool
  default     = false
}

variable "no_default_encryption" {
  description = "Disable default encryption on main bucket"
  type        = bool
  default     = false
}

variable "website_enabled" {
  description = "Enable static website hosting on main bucket"
  type        = bool
  default     = false
}

variable "no_logging" {
  description = "Disable access logging for main bucket"
  type        = bool
  default     = false
}

variable "allow_cleartext" {
  description = "Attach policy to deny non-SSL requests"
  type        = bool
  default     = false
}

variable "s3_getobject_only" {
  description = "Create secondary bucket with public read-only access"
  type        = bool
  default     = false
}

variable "s3_public" {
  description = "Create secondary bucket with full public access"
  type        = bool
  default     = false
}

variable "bucket_acl" {
  description = "Canned ACL for logging bucket"
  type        = string
  default     = "log-delivery-write"
}

resource "random_id" "suffix" {
  byte_length = 4
}

resource "aws_kms_key" "main" {
  count                = var.no_default_encryption ? 0 : 1
  description          = "KMS key for main S3 bucket encryption"
  enable_key_rotation  = true
}

resource "aws_kms_alias" "main" {
  count         = var.no_default_encryption ? 0 : 1
  name          = "alias/${var.name}-main-key"
  target_key_id = aws_kms_key.main[0].key_id
}

resource "aws_kms_key" "logging" {
  count                = var.no_logging ? 0 : 1
  description          = "KMS key for logging S3 bucket encryption"
  enable_key_rotation  = true
}

resource "aws_kms_alias" "logging" {
  count         = var.no_logging ? 0 : 1
  name          = "alias/${var.name}-logging-key"
  target_key_id = aws_kms_key.logging[0].key_id
}

resource "aws_s3_bucket" "main" {
  bucket        = "${var.name}-${random_id.suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "main" {
  bucket = aws_s3_bucket.main.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "main" {
  bucket = aws_s3_bucket.main.id
  acl    = "private"
  depends_on = [aws_s3_bucket_ownership_controls.main]
}

resource "aws_s3_bucket_versioning" "main" {
  count  = var.no_versioning ? 0 : 1
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count  = var.no_default_encryption ? 0 : 1
  bucket = aws_s3_bucket.main.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.main[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "main" {
  count  = var.website_enabled ? 1 : 0
  bucket = aws_s3_bucket.main.id
  index_document {
    suffix = "index.html"
  }
}

resource "aws_s3_bucket" "logging" {
  count         = var.no_logging ? 0 : 1
  bucket        = "${var.name}-logging-${random_id.suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_ownership_controls" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id
  acl    = var.bucket_acl
  depends_on = [aws_s3_bucket_ownership_controls.logging]
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count                   = var.no_logging ? 0 : 1
  bucket                  = aws_s3_bucket.logging[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count  = var.no_logging ? 0 : 1
  bucket = aws_s3_bucket.logging[0].id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.logging[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_logging" "main" {
  count         = var.no_logging ? 0 : 1
  bucket        = aws_s3_bucket.main.id
  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "log/"
}

resource "aws_s3_bucket_policy" "deny_cleartext" {
  count  = var.allow_cleartext ? 1 : 0
  bucket = aws_s3_bucket.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLTransport"
        Effect    = "Deny"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.main.arn,
          "${aws_s3_bucket.main.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
        Principal = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "getonly" {
  count         = var.s3_getobject_only ? 1 : 0
  bucket        = "${var.name}-getonly-${random_id.suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "getonly" {
  count                   = var.s3_getobject_only ? 1 : 0
  bucket                  = aws_s3_bucket.getonly[0].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "getonly" {
  count  = var.s3_getobject_only ? 1 : 0
  bucket = aws_s3_bucket.getonly[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadGetObject"
        Effect    = "Allow"
        Action    = "s3:GetObject"
        Resource = [
          aws_s3_bucket.getonly[0].arn,
          "${aws_s3_bucket.getonly[0].arn}/*"
        ]
        Principal = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "public" {
  count         = var.s3_public ? 1 : 0
  bucket        = "${var.name}-public-${random_id.suffix.hex}"
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "public" {
  count                   = var.s3_public ? 1 : 0
  bucket                  = aws_s3_bucket.public[0].id
  block_public_acls       = false
  block_public_policy     = false
  ignore_public_acls      = false
  restrict_public_buckets = false
}

resource "aws_s3_bucket_policy" "public" {
  count  = var.s3_public ? 1 : 0
  bucket = aws_s3_bucket.public[0].id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "PublicReadWrite"
        Effect    = "Allow"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.public[0].arn,
          "${aws_s3_bucket.public[0].arn}/*"
        ]
        Principal = "*"
      }
    ]
  })
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "agent_policy" {
  name = "AWSElasticDisasterRecoveryAgentPolicy"
}

data "aws_iam_policy" "failback_policy" {
  name = "AWSElasticDisasterRecoveryFailbackPolicy"
}

data "aws_iam_policy" "conversion_server_policy" {
  name = "AWSElasticDisasterRecoveryConversionServerPolicy"
}

data "aws_iam_policy" "recovery_instance_policy" {
  name = "AWSElasticDisasterRecoveryRecoveryInstancePolicy"
}

data "aws_iam_policy" "replication_server_policy" {
  name = "AWSElasticDisasterRecoveryReplicationServerPolicy"
}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

locals {
  drs_service_role_names = [
    "AWSElasticDisasterRecoveryAgentRole",
    "AWSElasticDisasterRecoveryFailbackRole",
    "AWSElasticDisasterRecoveryConversionServerRole",
    "AWSElasticDisasterRecoveryRecoveryInstanceRole",
    "AWSElasticDisasterRecoveryReplicationServerRole",
    "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole",
  ]
  drs_service_role_arns = [
    aws_iam_role.drs_agent.arn,
    aws_iam_role.drs_failback.arn,
    aws_iam_role.drs_conversion.arn,
    aws_iam_role.drs_recovery_instance.arn,
    aws_iam_role.drs_replication_server.arn,
    aws_iam_role.drs_recovery_instance_launch.arn,
  ]
  drs_managed_policy_arns = [
    data.aws_iam_policy.agent_policy.arn,
    data.aws_iam_policy.failback_policy.arn,
    data.aws_iam_policy.conversion_server_policy.arn,
    data.aws_iam_policy.recovery_instance_policy.arn,
    data.aws_iam_policy.replication_server_policy.arn,
  ]
}

resource "aws_iam_role" "drs_agent" {
  name = "AWSElasticDisasterRecoveryAgentRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_failback" {
  name = "AWSElasticDisasterRecoveryFailbackRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          StringLike = {
            "aws:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role" "drs_conversion" {
  name = "AWSElasticDisasterRecoveryConversionServerRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "drs_recovery_instance" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "drs_replication_server" {
  name = "AWSElasticDisasterRecoveryReplicationServerRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "drs_recovery_instance_launch" {
  name = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path = "/service-role/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "agent_policy_attachment" {
  role       = aws_iam_role.drs_agent.name
  policy_arn = data.aws_iam_policy.agent_policy.arn
}

resource "aws_iam_role_policy_attachment" "failback_policy_attachment" {
  role       = aws_iam_role.drs_failback.name
  policy_arn = data.aws_iam_policy.failback_policy.arn
}

resource "aws_iam_role_policy_attachment" "conversion_policy_attachment" {
  role       = aws_iam_role.drs_conversion.name
  policy_arn = data.aws_iam_policy.conversion_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance.name
  policy_arn = data.aws_iam_policy.recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "replication_server_policy_attachment" {
  role       = aws_iam_role.drs_replication_server.name
  policy_arn = data.aws_iam_policy.replication_server_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_launch_policy_attachment" {
  role       = aws_iam_role.drs_recovery_instance_launch.name
  policy_arn = data.aws_iam_policy.recovery_instance_policy.arn
}

resource "aws_iam_role_policy_attachment" "recovery_instance_launch_ssm_attachment" {
  role       = aws_iam_role.drs_recovery_instance_launch.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

resource "aws_iam_role" "drs_initializer" {
  name = "AWSElasticDisasterRecoveryInitializerRole"
  path = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = data.aws_caller_identity.current.arn
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "initialize_policy" {
  name        = "InitializePolicy"
  description = "Policy for DRS initializer role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "drs:InitializeService"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:CreateInstanceProfile"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:PassRole"
        Resource = local.drs_service_role_arns
      },
      {
        Effect = "Allow"
        Action = "iam:CreateServiceLinkedRole"
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "elasticdisasterrecovery.amazonaws.com"
          }
        }
      },
      {
        Effect = "Allow"
        Action = "ec2:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "iam:AttachRolePolicy"
        Resource = local.drs_service_role_arns
        Condition = {
          ArnEquals = {
            "iam:PolicyARN" = local.drs_managed_policy_arns
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "initialize_policy_attachment" {
  role       = aws_iam_role.drs_initializer.name
  policy_arn = aws_iam_policy.initialize_policy.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name      = "VPC_from_Terraform"
    Terraform = "true"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"][count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Security group
resource "aws_security_group" "allow_ssh_http_https" {
  name        = "allow_ssh_http_https"
  description = "Allow SSH from VPC, HTTP and HTTPS from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Terraform_SG_HTTP_HTTPS_SSH = "true"
  }
}

# EC2 instances
resource "aws_instance" "private_instance" {
  count         = 3
  ami           = data.aws_ami.amazon_linux2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.allow_ssh_http_https.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    volume_size           = 20
    volume_type           = "gp2"
    delete_on_termination = true
    encrypted             = true

    tags = {
      Name = "Terraform_EBS_Volume1"
    }
  }

  tags = {
    Name = "Terraform_Instance"
  }
}

terraform {
  required_version = "~> 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# IAM Role: ecsServiceRole
data "aws_iam_policy_document" "ecs_service_role_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_service_role" {
  name               = "ecsServiceRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_service_role_trust.json
}

data "aws_iam_policy_document" "ecs_task_role_policy" {
  statement {
    effect = "Allow"
    actions = [
      "elasticloadbalancing:Describe*",
      "elasticloadbalancing:RegisterInstancesWithLoadBalancer",
      "elasticloadbalancing:DeregisterInstancesFromLoadBalancer",
      "elasticloadbalancing:RegisterTargets",
      "elasticloadbalancing:DeregisterTargets",
      "ec2:DescribeInstances",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ssm:GetParameter",
      "ssm:DescribeParameters",
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
      "kms:Decrypt",
      "kms:DescribeKey",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:CreateDeployment",
      "codedeploy:GetDeployment",
      "codedeploy:ListDeployments",
      "sns:Publish",
      "cloudwatch:PutMetricData",
      "cloudwatch:DescribeAlarms",
      "lambda:InvokeFunction",
      "lambda:GetFunctionConfiguration"
    ]
    resources = ["*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "ecs:ListClusters",
      "ecs:DescribeClusters",
      "ecs:ListServices",
      "ecs:DescribeServices",
      "ecs:ListTasks",
      "ecs:DescribeTasks",
      "ecs:ListTaskDefinitions",
      "ecs:DescribeTaskDefinition"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_task_role_policy" {
  name   = "ecsTaskRolePolicy"
  role   = aws_iam_role.ecs_service_role.id
  policy = data.aws_iam_policy_document.ecs_task_role_policy.json
}

# IAM Role: ecsExecTaskRole
data "aws_iam_policy_document" "ecs_exec_task_role_trust" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com", "s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_exec_task_role" {
  name               = "ecsExecTaskRole"
  assume_role_policy = data.aws_iam_policy_document.ecs_exec_task_role_trust.json
}

data "aws_iam_policy_document" "ecs_exec_role_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:DescribeRepositories",
      "ecs:DescribeServices",
      "ecs:ListServices",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogStreams",
      "secretsmanager:GetSecretValue",
      "secretsmanager:DescribeSecret",
      "kms:Decrypt",
      "kms:DescribeKey",
      "ssm:GetParameter",
      "ssm:DescribeParameters"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ecs_exec_role_policy" {
  name   = "ecsExecRolePolicy"
  role   = aws_iam_role.ecs_exec_task_role.id
  policy = data.aws_iam_policy_document.ecs_exec_role_policy.json
}

data "aws_iam_policy_document" "ecs_execution_additional" {
  statement {
    effect = "Allow"
