terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# External VPC
resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = "prod"
  }
}

# External default security group (no rules)
resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  ingress = []
  egress  = []
}

# External subnets
resource "aws_subnet" "ext_subnet_0" {
  vpc_id                  = aws_vpc.external.id
  cidr_block              = "10.41.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name        = "Subnet0-1a"
    purpose     = "Production External Subnet"
    environment = "prod"
  }
}

resource "aws_subnet" "ext_subnet_1" {
  vpc_id                  = aws_vpc.external.id
  cidr_block              = "10.41.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name        = "Subnet1-1b"
    purpose     = "Production External Subnet"
    environment = "prod"
  }
}

resource "aws_subnet" "ext_subnet_2" {
  vpc_id                  = aws_vpc.external.id
  cidr_block              = "10.41.2.0/24"
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = {
    Name        = "Subnet2-1c"
    purpose     = "Production External Subnet"
    environment = "prod"
  }
}

resource "aws_subnet" "ext_subnet_3" {
  vpc_id                  = aws_vpc.external.id
  cidr_block              = "10.41.3.0/24"
  availability_zone       = data.aws_availability_zones.available.names[3]
  map_public_ip_on_launch = false

  tags = {
    Name        = "Subnet3-1d"
    purpose     = "Production External Subnet"
    environment = "prod"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "external_gw" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    purpose     = "Production External Internet Gateway"
    environment = "prod"
  }
}

# External route table
resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.external_gw.id
  }

  tags = {
    Name        = "External RT"
    purpose     = "Production External Route Table"
    environment = "prod"
  }
}

# Main route table association for external VPC
resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

# Route table associations for each external subnet
resource "aws_route_table_association" "ext_rta_0" {
  subnet_id      = aws_subnet.ext_subnet_0.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "ext_rta_1" {
  subnet_id      = aws_subnet.ext_subnet_1.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "ext_rta_2" {
  subnet_id      = aws_subnet.ext_subnet_2.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "ext_rta_3" {
  subnet_id      = aws_subnet.ext_subnet_3.id
  route_table_id = aws_route_table.external.id
}

# External default network ACL
resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  egress {
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
