terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables
variable "prefix" {
  description = "Resource name prefix"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "ARN of an existing ACM certificate for HTTPS listener (if null, a self-signed certificate will be generated)"
  type        = string
  default     = null
}

variable "url" {
  description = "Override WEBHOOK_URL (if null, defaults to HTTPS ALB DNS name)"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for n8n"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type (FARGATE or FARGATE_SPOT)"
  type        = string
  default     = "FARGATE_SPOT"
}

# Locals
locals {
  prefix         = var.prefix
  vpc_cidr       = "10.0.0.0/16"
  public_cidrs   = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]
  private_cidrs  = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  azs            = slice(data.aws_availability_zones.available.names, 0, 3)
  webhook_url    = var.url != null ? var.url : "https://${aws_lb.internal_alb.dns_name}"
  suffix         = random_id.suffix.hex
}

# Random suffix for resource name uniqueness
resource "random_id" "suffix" {
  byte_length = 4
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "${local.prefix}-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.prefix}-public-${count.index}"
    Tier = "public"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.private_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = {
    Name = "${local.prefix}-private-${count.index}"
    Tier = "private"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.prefix}-igw"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }
  tags = {
    Name = "${local.prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private route table (no default route)
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Groups
# ALB Security Group
resource "aws_security_group" "alb_sg" {
  name        = "${local.prefix}-alb-sg"
  description = "Security group for internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-alb-sg"
  }
}

# ECS Task Security Group
resource "aws_security_group" "ecs_sg" {
  name        = "${local.prefix}-ecs-sg"
  description = "Security group for ECS Fargate tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n port from ALB"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb_sg.id]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-ecs-sg"
  }
}

# EFS Security Group
resource "aws_security_group" "efs_sg" {
  name        = "${local.prefix}-efs-sg"
  description = "Security group for EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.prefix}-efs-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "internal_alb" {
  name                       = "${local.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb_sg.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = {
    Name = "${local.prefix}-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "ecs_tg" {
  name        = "${local.prefix}-tg-${local.suffix}"
  port        = 80
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = {
    Name = "${local.prefix}-tg-${local.suffix}"
  }
}

# HTTP Listener (redirect to HTTPS)
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.internal_alb.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"
    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

# Self-signed certificate resources (only if certificate_arn is null)
resource "tls_private_key" "self_signed" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  count           = var.certificate_arn == null ? 1 : 0
  private_key_pem = tls_private_key.self_signed[0].private_key_pem

  subject {
    common_name = "${local.prefix}.internal"
  }

  validity_period_hours = 87600 # 10 years

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  count            = var.certificate_arn == null ? 1 : 0
  private_key      = tls_private_key.self_signed[0].private_key_pem
  certificate_body = tls_self_signed_cert.self_signed[0].cert_pem
}

# HTTPS Listener
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.internal_alb.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.self_signed[0].arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.ecs_tg.arn
  }
}

# EFS File System
resource "aws_efs_file_system" "n8n" {
  creation_token   = "${local.prefix}-efs-${local.suffix}"
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${local.prefix}-efs-${local.suffix}"
  }
}

# EFS Access Point
resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"
    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "0777"
    }
  }

  tags = {
    Name = "${local.prefix}-efs-ap"
  }
}

# EFS Mount Targets
resource "aws_efs_mount_target" "n8n" {
  count          = 3
  file_system_id = aws_efs_file_system.n8n.id
  subnet_id      = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs_sg.id]
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${local.prefix}-logs-${local.suffix}"
  retention_in_days = 1
}

# ECS Cluster
resource "aws_ecs_cluster" "n8n" {
  name = "${local.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }
}

# Associate capacity provider with cluster (using built-in Fargate types)
resource "aws_ecs_cluster_capacity_providers" "n8n" {
  cluster_name = aws_ecs_cluster.n8n.name

  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

# IAM Roles
# Execution Role
resource "aws_iam_role" "ecs_exec" {
  name = "${local.prefix}-ecs-exec-role-${local.suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "exec_logs" {
  name = "${local.prefix}-exec-logs-policy-${local.suffix}"
  role = aws_iam_role.ecs_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.n8n.arn}:*"
      }
    ]
  })
}

# Task Role
resource "aws_iam_role" "ecs_task" {
  name = "${local.prefix}-ecs-task-role-${local.suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs_and_efs" {
  name = "${local.prefix}-task-logs-efs-policy-${local.suffix}"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.n8n.arn}:*"
      },
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.n8n.arn
      }
    ]
  })
}

# Task Definition
resource "aws_ecs_task_definition" "n8n" {
  family                   = "${local.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_exec.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  volume {
    name = "n8n_data"
    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      transit_encryption = "ENABLED"
      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true
      portMappings = [
        {
          containerPort = 5678
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "n8n"
        }
      }
      mountPoints = [
        {
          sourceVolume  = "n8n_data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]
    }
  ])
}

# Data source for current region (needed for logs)
data "aws_region" "current" {}

# ECS Service
resource "aws_ecs_service" "n8n" {
  name            = "${local.prefix}-service"
  cluster         = aws_ecs_cluster.n8n.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = true
  }

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.ecs_tg.arn
    container_name   = "n8n"
    container_port   = 5678
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  primary_az   = data.aws_availability_zones.available.names[0]
  secondary_az = data.aws_availability_zones.available.names[1]
}

resource "aws_vpc" "main" {
  cidr_block           = "10.32.0.0/20"
  enable_dns_hostnames = true

  tags = {
    Name = "lambda-rds-dev"
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []
}

resource "aws_default_network_acl" "default" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = {
    Name = "lambda-rds-dev-default-nacl"
  }
}

resource "aws_subnet" "db_1" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.0/28"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-1"
  }
}

resource "aws_subnet" "lambda" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.1.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-dev-lambda-subnet"
  }
}

resource "aws_subnet" "db_2" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.0.16/28"
  availability_zone       = local.secondary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-db-subnet-2"
  }
}

resource "aws_subnet" "bastion" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.32.15.0/24"
  availability_zone       = local.primary_az
  map_public_ip_on_launch = false

  tags = {
    Name = "lambda-rds-bastion-host-subnet"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "lambda-rds-public-subnet"
  }
}

resource "aws_route_table_association" "bastion" {
  subnet_id      = aws_subnet.bastion.id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "postgres_db" {
  name        = "lambda-rds-dev-postgres-db"
  description = "Security group for PostgreSQL database"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-postgres-db"
  }
}

resource "aws_security_group" "lambda_functions" {
  name        = "lambda-rds-dev-lambda-functions"
  description = "Security group for Lambda functions"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-lambda-functions"
  }
}

resource "aws_security_group" "bastion_host" {
  name        = "lambda-rds-dev-bastion-host"
  description = "Security group for bastion host"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "lambda-rds-dev-bastion-host"
  }
}

# Ingress rules for PostgreSQL database security group
resource "aws_security_group_rule" "postgres_ingress_bastion" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.bastion_host.id
  security_group_id        = aws_security_group.postgres_db.id
}

resource "aws_security_group_rule" "postgres_ingress_lambda" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.lambda_functions.id
  security_group_id        = aws_security_group.postgres_db.id
}

# Egress rule for PostgreSQL database security group
resource "aws_security_group_rule" "postgres_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["10.32.0.0/20"]
  security_group_id = aws_security_group.postgres_db.id
}

# Egress rule for Lambda functions security group
resource "aws_security_group_rule" "lambda_egress" {
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["10.32.0.0/20"]
  security_group_id = aws_security_group.lambda_functions.id
}

# Ingress rule for bastion host security group
resource "aws_security_group_rule" "bastion_ingress_ssh" {
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
  security_group_id = aws_security_group.bastion_host.id
}

# Egress rule for bastion host security group
resource "aws_security_group_rule" "bastion_egress_postgres" {
  type                     = "egress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.postgres_db.id
  security_group_id        = aws_security_group.bastion_host.id
}

locals {
  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "quasar" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "Quasar" })
}

resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, { Name = "Quasar RDS - 1A" })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, { Name = "Quasar RDS - 1E" })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host security group"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, { Name = "Quasar-Bastion" })

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA Proxy security group"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, { Name = "Quasar-HA-Proxy" })

  ingress {
    description = "HTTP from everywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from everywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from Bastion"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD security group"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, { Name = "Quasar-Jenkins" })

  ingress {
    description = "SSH from Bastion"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description = "Jenkins UI from HA Proxy"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes security group"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, { Name = "Quasar-ETL" })

  ingress {
    description = "SSH from Bastion and Jenkins"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    security_groups = [
      aws_security_group.bastion.id,
      aws_security_group.jenkins.id,
    ]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database security group"
  vpc_id      = aws_vpc.quasar.id

  tags = merge(local.common_tags, { Name = "Quasar-PostgreSQL" })

  ingress {
    description = "PostgreSQL from everywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "PostgreSQL from ETL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.quasar.cidr_block]
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------

variable "create" {
  description = "Whether to create the SQS queue resources"
  type        = bool
  default     = true
}

variable "name" {
  description = "Human-readable queue name (without .fifo suffix)"
  type        = string
  default     = "my-queue"
}

variable "use_name_prefix" {
  description = "Use the queue name as a prefix for auto-generated names (standard queues only)"
  type        = bool
  default     = false
}

# Main queue FIFO settings
variable "fifo_queue" {
  description = "Whether the main queue is FIFO"
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enable content-based deduplication (FIFO queues only)"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Deduplication scope for FIFO queues (queue or messageGroup)"
  type        = string
  default     = "queue"
}

variable "fifo_throughput_limit" {
  description = "FIFO throughput limit (perQueue or perMessageGroupId)"
  type        = string
  default     = "perQueue"
}

# Main queue standard settings
variable "delay_seconds" {
  description = "Delay in seconds for message delivery"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Maximum message size in bytes"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Message retention period in seconds"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Receive message wait time (long polling) in seconds"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout in seconds"
  type        = number
  default     = 30
}

# Main queue encryption
variable "sqs_managed_sse_enabled" {
  description = "Enable SQS-managed SSE (ignored if kms_master_key_id is set)"
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "KMS master key ID for encryption (overrides sqs_managed_sse_enabled)"
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "KMS data key reuse period in seconds (used when kms_master_key_id is set)"
  type        = number
  default     = 300
}

# Main queue policy
variable "create_queue_policy" {
  description = "Whether to attach an IAM policy to the main queue"
  type        = bool
  default     = false
}

variable "queue_policy_statements" {
  description = "List of IAM policy statements for the main queue"
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    actions   = list(string)
    resources = list(string)
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "queue_policy_source_policy_documents" {
  description = "List of source policy documents to merge for the main queue policy"
  type        = list(string)
  default     = []
}

variable "queue_policy_override_policy_documents" {
  description = "List of override policy documents for the main queue policy"
  type        = list(string)
  default     = []
}

# DLQ settings
variable "create_dlq" {
  description = "Whether to create a dead-letter queue"
  type        = bool
  default     = false
}

variable "create_dlq_redrive_allow_policy" {
  description = "Whether to attach a redrive allow policy to the DLQ"
  type        = bool
  default     = true
}

variable "create_dlq_queue_policy" {
  description = "Whether to attach an IAM policy to the DLQ"
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the DLQ name"
  type        = string
  default     = "-dlq"
}

# DLQ override variables (if null, inherit from main queue)
variable "dlq_fifo_queue" {
  description = "Override: whether the DLQ is FIFO (null inherits from main)"
  type        = bool
  default     = null
}

variable "dlq_content_based_deduplication" {
  description = "Override: content-based deduplication for DLQ"
  type        = bool
  default     = null
}

variable "dlq_deduplication_scope" {
  description = "Override: deduplication scope for DLQ"
  type        = string
  default     = null
}

variable "dlq_fifo_throughput_limit" {
  description = "Override: FIFO throughput limit for DLQ"
  type        = string
  default     = null
}

variable "dlq_delay_seconds" {
  description = "Override: delay seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_max_message_size" {
  description = "Override: max message size for DLQ"
  type        = number
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "Override: message retention seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_receive_wait_time_seconds" {
  description = "Override: receive wait time seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_visibility_timeout_seconds" {
  description = "Override: visibility timeout seconds for DLQ"
  type        = number
  default     = null
}

variable "dlq_sqs_managed_sse_enabled" {
  description = "Override: SQS-managed SSE for DLQ"
  type        = bool
  default     = null
}

variable "dlq_kms_master_key_id" {
  description = "Override: KMS master key ID for DLQ"
  type        = string
  default     = null
}

variable "dlq_kms_data_key_reuse_period_seconds" {
  description = "Override: KMS data key reuse period for DLQ"
  type        = number
  default     = null
}

# DLQ policy variables
variable "dlq_queue_policy_statements" {
  description = "List of IAM policy statements for the DLQ"
  type = list(object({
    sid       = optional(string)
    effect    = optional(string, "Allow")
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })))
    actions   = list(string)
    resources = list(string)
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })))
  }))
  default = []
}

variable "dlq_policy_source_policy_documents" {
  description = "List of source policy documents to merge for the DLQ policy"
  type        = list(string)
  default     = []
}

variable "dlq_policy_override_policy_documents" {
  description = "List of override policy documents for the DLQ policy"
  type        = list(string)
  default     = []
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------

locals {
  # Main queue name construction
  main_queue_name                = var.fifo_queue ? "${var.name}.fifo" : var.name
  main_queue_use_name_prefix     = !var.fifo_queue && var.use_name_prefix
  main_queue_name_arg            = local.main_queue_use_name_prefix ? null : local.main_queue_name
  main_queue_name_prefix_arg     = local.main_queue_use_name_prefix ? var.name : null

  # DLQ name construction
  dlq_base_name                  = var.create_dlq ? "${var.name}${var.dlq_name_suffix}" : null
  dlq_fifo_queue                 = var.dlq_fifo_queue != null ? var.dlq_fifo_queue : var.fifo_queue
  dlq_use_name_prefix            = !local.dlq_fifo_queue && var.use_name_prefix
  dlq_queue_name                 = local.dlq_fifo_queue ? "${local.dlq_base_name}.fifo" : local.dlq_base_name
  dlq_queue_name_arg             = local.dlq_use_name_prefix ? null : local.dlq_queue_name
  dlq_queue_name_prefix_arg      = local.dlq_use_name_prefix ? local.dlq_base_name : null

  # DLQ attribute inheritance (override if set, otherwise inherit from main)
  dlq_content_based_deduplication      = var.dlq_content_based_deduplication != null ? var.dlq_content_based_deduplication : var.content_based_deduplication
  dlq_deduplication_scope              = var.dlq_deduplication_scope != null ? var.dlq_deduplication_scope : var.deduplication_scope
  dlq_fifo_throughput_limit            = var.dlq_fifo_throughput_limit != null ? var.dlq_fifo_throughput_limit : var.fifo_throughput_limit
  dlq_delay_seconds                    = var.dlq_delay_seconds != null ? var.dlq_delay_seconds : var.delay_seconds
  dlq_max_message_size                 = var.dlq_max_message_size != null ? var.dlq_max_message_size : var.max_message_size
  dlq_message_retention_seconds        = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds
  dlq_receive_wait_time_seconds        = var.dlq_receive_wait_time_seconds != null ? var.dlq_receive_wait_time_seconds : var.receive_wait_time_seconds
  dlq_visibility_timeout_seconds       = var.dlq_visibility_timeout_seconds != null ? var.dlq_visibility_timeout_seconds : var.visibility_timeout_seconds
  dlq_sqs_managed_sse_enabled          = var.dlq_sqs_managed_sse_enabled != null ? var.dlq_sqs_managed_sse_enabled : var.sqs_managed_sse_enabled
  dlq_kms_master_key_id                = var.dlq_kms_master_key_id != null ? var.dlq_kms_master_key_id : var.kms_master_key_id
  dlq_kms_data_key_reuse_period_seconds = var.dlq_kms_data_key_reuse_period_seconds != null ? var.dlq_kms_data_key_reuse_period_seconds : var.kms_data_key_reuse_period_seconds
}

# ------------------------------------------------------------------------------
# RESOURCES
# ------------------------------------------------------------------------------

# Main queue
resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name       = local.main_queue_name_arg
  name_prefix = local.main_queue_name_prefix_arg

  # FIFO attributes (only sent when fifo_queue is true)
  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  # Standard attributes
  delay_seconds                = var.delay_seconds
  max_message_size             = var.max_message_size
  message_retention_seconds    = var.message_retention_seconds
  receive_wait_time_seconds    = var.receive_wait_time_seconds
  visibility_timeout_seconds   = var.visibility_timeout_seconds

  # Encryption (conditional)
  sqs_managed_sse_enabled          = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : null
  kms_master_key_id                = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null

  # Redrive policy (only when DLQ exists)
  redrive_policy = var.create && var.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount    = 5
  }) : null

  lifecycle {
    prevent_destroy = true
  }
}

# DLQ queue
resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name       = local.dlq_queue_name_arg
  name_prefix = local.dlq_queue_name_prefix_arg

  # FIFO attributes (only sent when dlq_fifo_queue is true)
  fifo_queue                  = local.dlq_fifo_queue
  content_based_deduplication = local.dlq_fifo_queue ? local.dlq_content_based_deduplication : null
  deduplication_scope         = local.dlq_fifo_queue ? local.dlq_deduplication_scope : null
  fifo_throughput_limit       = local.dlq_fifo_queue ? local.dlq_fifo_throughput_limit : null

  # Standard attributes
  delay_seconds                = local.dlq_delay_seconds
  max_message_size             = local.dlq_max_message_size
  message_retention_seconds    = local.dlq_message_retention_seconds
  receive_wait_time_seconds    = local.dlq_receive_wait_time_seconds
  visibility_timeout_seconds   = local.dlq_visibility_timeout_seconds

  # Encryption (inherited from local)
  sqs_managed_sse_enabled          = local.dlq_kms_master_key_id == null ? local.dlq_sqs_managed_sse_enabled : null
  kms_master_key_id                = local.dlq_kms_master_key_id
  kms_data_key_reuse_period_seconds = local.dlq_kms_master_key_id != null ? local.dlq_kms_data_key_reuse_period_seconds : null

  lifecycle {
    prevent_destroy = true
  }
}

# Redrive allow policy (attached to DLQ)
resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [aws_sqs_queue.main[0].arn]
  })
}

# ------------------------------------------------------------------------------
# IAM POLICY DOCUMENTS (data sources)
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "queue_policy" {
  count = var.create && var.create_queue_policy ? 1 : 0

  source_policy_documents   = var.queue_policy_source_policy_documents
  override_policy_documents = var.queue_policy_override_policy_documents

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

data "aws_iam_policy_document" "dlq_queue_policy" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  source_policy_documents   = var.dlq_policy_source_policy_documents
  override_policy_documents = var.dlq_policy_override_policy_documents

  dynamic "statement" {
    for_each = var.dlq_queue_policy_statements
    content {
      sid       = statement.value.sid
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals != null ? statement.value.principals : []
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions != null ? statement.value.conditions : []
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# QUEUE POLICIES (attached to SQS queues)
# ------------------------------------------------------------------------------
resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.main[0].id
  policy    = data.aws_iam_policy_document.queue_policy[0].json
}

resource "aws_sqs_queue_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.dlq[0].id
  policy    = data.aws_iam_policy_document.dlq_queue_policy[0].json
}

# ------------------------------------------------------------------------------
# Terraform Provider Requirements
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create" {
  description = "Master switch to enable creation of all resources"
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the Lambda function"
  type        = string
  default     = "my-function"
}

variable "alias_name" {
  description = "Alias name for the Lambda function"
  type        = string
  default     = "my-alias"
}

variable "current_version" {
  description = "Current version of the Lambda function"
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Target version for the deployment"
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "ARN of the before allow traffic lifecycle hook"
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "ARN of the after allow traffic lifecycle hook"
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create a new CodeDeploy application"
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an existing CodeDeploy application"
  type        = bool
  default     = false
}

variable "app_name" {
  description = "Name of the CodeDeploy application"
  type        = string
  default     = "my-app"
}

variable "create_deployment_group" {
  description = "Whether to create a new deployment group"
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an existing deployment group"
  type        = bool
  default     = false
}

variable "deployment_config_name" {
  description = "Name of the deployment configuration"
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "cloudwatch_alarm_names" {
  description = "List of CloudWatch alarm names for monitoring"
  type        = list(string)
  default     = []
}

variable "trigger_configs" {
  description = "List of trigger configurations; each object must have trigger_name and trigger_events"
  type = list(object({
    trigger_name   = string
    trigger_events = list(string)
  }))
  default = []
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role for CodeDeploy"
  type        = bool
  default     = true
}

variable "codedeploy_service_principals" {
  description = "List of service principals allowed to assume the CodeDeploy role"
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach the inline policy for Lambda invoke permissions"
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach the inline policy for SNS publish permissions"
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to create a CodeDeploy deployment"
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI command to use"
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Sleep interval in seconds between deployment status checks"
  type        = number
  default     = 5
}

variable "save_deploy_script" {
  description = "Whether to save the deployment script to a local file"
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to execute the deployment provisioner via null_resource"
  type        = bool
  default     = false
}

# ------------------------------------------------------------------------------
# Locals
# ------------------------------------------------------------------------------
locals {
  create_app_condition               = var.create && var.create_app && !var.use_existing_app
  create_deployment_group_condition  = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_codedeploy_role_condition   = var.create && var.create_codedeploy_role
  create_deployment_condition        = var.create && var.create_deployment

  # Hook ARNs filtered to non-empty
  hook_arns = compact([var.before_allow_traffic_hook_arn, var.after_allow_traffic_hook_arn])

  # SNS topic names for triggers
  trigger_sns_topics = { for idx, t in var.trigger_configs : t.trigger_name => "${var.app_name}-${t.trigger_name}" }

  # AppSpec content
  appspec_content = jsonencode({
    version = 1
    Resources = [
      {
        Type = "AWS::Lambda::Function"
        Properties = {
          Name           = var.function_name
          Alias          = var.alias_name
          CurrentVersion = var.current_version
          TargetVersion  = var.target_version
        }
      }
    ]
    Hooks = [
      for arn in local.hook_arns : {
        name              = arn == var.before_allow_traffic_hook_arn ? "BeforeAllowTraffic" : "AfterAllowTraffic"
        LambdaFunctionArn = arn
      }
    ]
  })

  # Deployment monitoring script – only evaluated when deployment is enabled
  deploy_script = local.create_deployment_condition ? (<<-EOF
    #!/usr/bin/env bash
    set -e
    APP_SPEC='${local.appspec_content}'
    DEPLOYMENT_GROUP="${aws_codedeploy_deployment_group.this[0].deployment_group_name}"
    AWS_CLI="${var.aws_cli_command}"
    SLEEP_TIMER=${var.get_deployment_sleep_timer}

    # Create the deployment
    DEPLOYMENT_ID=$($AWS_CLI deploy create-deployment \
      --deployment-group-name "$DEPLOYMENT_GROUP" \
      --revision revisionType=String,stringValue="$APP_SPEC" \
      --query "deploymentId" --output text)
    echo "Created deployment: $DEPLOYMENT_ID"

    # Monitor until completion
    while true; do
      STATUS=$($AWS_CLI deploy get-deployment --deployment-id $DEPLOYMENT_ID --query "deploymentInfo.status" --output text)
      echo "Deployment status: $STATUS"
      if [[ "$STATUS" == "Succeeded" ]]; then
        exit 0
      elif [[ "$STATUS" == "Failed" || "$STATUS" == "Stopped" ]]; then
        exit 1
      fi
      sleep $SLEEP_TIMER
    done
  EOF
  ) : ""
}

# ------------------------------------------------------------------------------
# Data Sources
# ------------------------------------------------------------------------------
data "aws_iam_policy_document" "codedeploy_assume_role" {
  count = local.create_codedeploy_role_condition ? 1 : 0
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

# ------------------------------------------------------------------------------
# SNS Topics for Triggers
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "trigger" {
  for_each = local.create_app_condition ? local.trigger_sns_topics : {}
  name     = each.value
}

# ------------------------------------------------------------------------------
# CodeDeploy Application
# ------------------------------------------------------------------------------
resource "aws_codedeploy_app" "this" {
  count            = local.create_app_condition ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# CodeDeploy Deployment Group
# ------------------------------------------------------------------------------
resource "aws_codedeploy_deployment_group" "this" {
  count                  = local.create_deployment_group_condition ? 1 : 0
  app_name               = aws_codedeploy_app.this[0].name
  deployment_group_name  = "${var.app_name}-deployment-group"
  service_role_arn       = local.create_codedeploy_role_condition ? aws_iam_role.codedeploy[0].arn : null
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = true
    events  = ["DEPLOYMENT_STOP_ON_ALARM"]
  }

  dynamic "alarm_configuration" {
    for_each = length(var.cloudwatch_alarm_names) > 0 ? [true] : []
    content {
      alarms  = var.cloudwatch_alarm_names
      enabled = true
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configs
    content {
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_target_arn = aws_sns_topic.trigger[trigger_configuration.value.trigger_name].arn
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# IAM Role for CodeDeploy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "codedeploy" {
  count              = local.create_codedeploy_role_condition ? 1 : 0
  name               = "${var.app_name}-codedeploy-role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role[0].json
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda" {
  count      = local.create_codedeploy_role_condition ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

# Inline policy for Lambda hooks
resource "aws_iam_role_policy" "hooks" {
  count  = local.create_codedeploy_role_condition && var.attach_hooks_policy && length(local.hook_arns) > 0 ? 1 : 0
  name   = "${var.app_name}-hooks-policy"
  role   = aws_iam_role.codedeploy[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "lambda:InvokeFunction"
        Effect   = "Allow"
        Resource = local.hook_arns
      }
    ]
  })
}

# Inline policy for SNS triggers
resource "aws_iam_role_policy" "triggers" {
  count  = local.create_codedeploy_role_condition && var.attach_triggers_policy && length(var.trigger_configs) > 0 ? 1 : 0
  name   = "${var.app_name}-triggers-policy"
  role   = aws_iam_role.codedeploy[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "sns:Publish"
        Effect   = "Allow"
        Resource = [for t in aws_sns_topic.trigger : t.arn]
      }
    ]
  })
}

# Random UUID for force redeployment
resource "random_uuid" "force_deploy" {
  count = local.create_deployment_condition && var.run_deployment ? 1 : 0
}

# Local file for deployment script
resource "local_file" "deploy_script" {
  count    = local.create_deployment_condition && var.save_deploy_script ? 1 : 0
  content  = local.deploy_script
  filename = "${path.module}/deploy_monitor.sh"
}

# Null resource to execute deployment
resource "null_resource" "run_deployment" {
  count = local.create_deployment_condition && var.run_deployment ? 1 : 0
  triggers = {
    force_uuid = random_uuid.force_deploy[0].result
  }
  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "tf-project"
}

variable "az_count" {
  description = "Number of Availability Zones to use (max 5)"
  type        = number
  default     = 3
  validation {
    condition     = var.az_count >= 1 && var.az_count <= 5
    error_message = "az_count must be between 1 and 5."
  }
}

variable "web_subnet_cidrs" {
  description = "List of CIDR blocks for web subnets"
  type        = list(string)
  default     = []
}

variable "app_subnet_cidrs" {
  description = "List of CIDR blocks for app subnets"
  type        = list(string)
  default     = []
}

variable "db_subnet_cidrs" {
  description = "List of CIDR blocks for database subnets"
  type        = list(string)
  default     = []
}

variable "reserved_subnet_cidrs" {
  description = "List of CIDR blocks for reserved subnets"
  type        = list(string)
  default     = []
}

variable "interface_vpc_endpoints" {
  description = "Map of interface VPC endpoints to create"
  type = map(object({
    service_name = string
    subnet_ids   = optional(list(string))
  }))
  default = {}
}

variable "gateway_vpc_endpoint_service" {
  description = "Service name for a gateway VPC endpoint (e.g., s3). If empty, no gateway endpoint is created."
  type        = string
  default     = ""
}

# Random resources
resource "random_integer" "vpc_suffix" {
  min = 1
  max = 100
}

# AZ data
data "aws_availability_zones" "available" {
  state = "available"
}

resource "random_shuffle" "az" {
  input        = data.aws_availability_zones.available.names
  result_count = var.az_count
}

# Local values
locals {
  name_tag = "${var.name_prefix}-${random_integer.vpc_suffix.result}"
  private_subnet_ids = concat(
    aws_subnet.app[*].id,
    aws_subnet.db[*].id,
    aws_subnet.reserved[*].id
  )
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = local.name_tag
  }
}

# Subnets
resource "aws_subnet" "web" {
  count = length(var.web_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.web_subnet_cidrs[count.index]
  availability_zone       = element(random_shuffle.az.result, count.index % length(random_shuffle.az.result))
  map_public_ip_on_launch = true

  tags = {
    Name = "${local.name_tag}-web-${count.index + 1}"
    Tier = "web"
  }
}

resource "aws_subnet" "app" {
  count = length(var.app_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.app_subnet_cidrs[count.index]
  availability_zone       = element(random_shuffle.az.result, count.index % length(random_shuffle.az.result))
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_tag}-app-${count.index + 1}"
    Tier = "app"
  }
}

resource "aws_subnet" "db" {
  count = length(var.db_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.db_subnet_cidrs[count.index]
  availability_zone       = element(random_shuffle.az.result, count.index % length(random_shuffle.az.result))
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_tag}-db-${count.index + 1}"
    Tier = "db"
  }
}

resource "aws_subnet" "reserved" {
  count = length(var.reserved_subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.reserved_subnet_cidrs[count.index]
  availability_zone       = element(random_shuffle.az.result, count.index % length(random_shuffle.az.result))
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_tag}-reserved-${count.index + 1}"
    Tier = "reserved"
  }
}

# Internet Gateway (conditional on web subnets)
resource "aws_internet_gateway" "igw" {
  count = length(var.web_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_tag}-igw"
  }
}

# Public Route Table (conditional on web subnets)
resource "aws_route_table" "public" {
  count = length(var.web_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw[0].id
  }

  tags = {
    Name = "${local.name_tag}-public-rt"
  }
}

# Private Route Table (conditional on any private subnets)
resource "aws_route_table" "private" {
  count = length(concat(var.app_subnet_cidrs, var.db_subnet_cidrs, var.reserved_subnet_cidrs)) > 0 ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_tag}-private-rt"
  }
}

# Route Table Associations
resource "aws_route_table_association" "web" {
  count = length(var.web_subnet_cidrs)

  subnet_id      = aws_subnet.web[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table_association" "app" {
  count = length(var.app_subnet_cidrs)

  subnet_id      = aws_subnet.app[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "db" {
  count = length(var.db_subnet_cidrs)

  subnet_id      = aws_subnet.db[count.index].id
  route_table_id = aws_route_table.private[0].id
}

resource "aws_route_table_association" "reserved" {
  count = length(var.reserved_subnet_cidrs)

  subnet_id      = aws_subnet.reserved[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# VPC Endpoint Security Group (only if interface endpoints exist)
resource "aws_security_group" "vpc_endpoint" {
  count = length(var.interface_vpc_endpoints) > 0 ? 1 : 0

  name        = "${local.name_tag}-vpc-endpoint-sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound to VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "${local.name_tag}-vpc-endpoint-sg"
  }
}

# Interface VPC Endpoints
resource "aws_vpc_endpoint" "interface" {
  for_each = var.interface_vpc_endpoints

  vpc_id              = aws_vpc.main.id
  vpc_endpoint_type   = "Interface"
  service_name        = each.value.service_name
  subnet_ids          = each.value.subnet_ids != null ? each.value.subnet_ids : local.private_subnet_ids
  security_group_ids  = [aws_security_group.vpc_endpoint[0].id]
  private_dns_enabled = true

  tags = {
    Name = "${local.name_tag}-${each.key}"
  }
}

# Gateway VPC Endpoint (conditional)
resource "aws_vpc_endpoint" "gateway" {
  count = var.gateway_vpc_endpoint_service != "" ? 1 : 0

  vpc_id            = aws_vpc.main.id
  vpc_endpoint_type = "Gateway"
  service_name      = var.gateway_vpc_endpoint_service
  route_table_ids   = [aws_route_table.private[0].id]

  tags = {
    Name = "${local.name_tag}-gateway-${var.gateway_vpc_endpoint_service}"
  }
}

terraform {
  required_version = ">= 1.0"
