resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from admin CIDRs and self, outbound to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from admin CIDRs"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.admin_cidrs
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Home SSH"
  }
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from VPC CIDR and self, outbound to VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "All traffic to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "Packer SSH"
  }
}

variable "env" {
  description = "Environment name prefix for resource tags"
  type        = string
  default     = ""
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24"]
}

variable "private_app_subnet_cidrs" {
  description = "CIDR blocks for private application subnets"
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.20.0/24", "10.0.30.0/24"]
}

variable "private_db_subnet_cidrs" {
  description = "CIDR blocks for private database subnets"
  type        = list(string)
  default     = ["10.0.100.0/24", "10.0.110.0/24", "10.0.120.0/24"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = true

  tags = {
    Name = var.env != "" ? "${var.env}-vpc" : "vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.env != "" ? "${var.env}-igw" : "igw"
  }
}

resource "aws_eip" "nat" {
  count      = 3
  domain     = "vpc"
  depends_on = [aws_internet_gateway.igw]

  tags = {
    Name = var.env != "" ? "${var.env}-nat-eip-${count.index}" : "nat-eip-${count.index}"
  }
}

resource "aws_subnet" "public" {
  count                   = 3
  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.public_subnet_cidrs, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = var.env != "" ? "${var.env}-public-subnet-${count.index}" : "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private_app" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_app_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = var.env != "" ? "${var.env}-private-app-subnet-${count.index}" : "private-app-subnet-${count.index}"
  }
}

resource "aws_subnet" "private_db" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = element(var.private_db_subnet_cidrs, count.index)
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = var.env != "" ? "${var.env}-private-db-subnet-${count.index}" : "private-db-subnet-${count.index}"
  }
}

resource "aws_nat_gateway" "nat" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = var.env != "" ? "${var.env}-nat-gw-${count.index}" : "nat-gw-${count.index}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = var.env != "" ? "${var.env}-public-rt" : "public-rt"
  }
}

resource "aws_route_table" "private_app" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = var.env != "" ? "${var.env}-private-app-rt-${count.index}" : "private-app-rt-${count.index}"
  }
}

resource "aws_route_table" "private_db" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = aws_vpc.main.cidr_block
    gateway_id = "local"
  }

  tags = {
    Name = var.env != "" ? "${var.env}-private-db-rt" : "private-db-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private_app" {
  count          = 3
  subnet_id      = aws_subnet.private_app[count.index].id
  route_table_id = aws_route_table.private_app[count.index].id
}

resource "aws_route_table_association" "private_db" {
  count          = 3
  subnet_id      = aws_subnet.private_db[count.index].id
  route_table_id = aws_route_table.private_db.id
}

# Terraform configuration for production-grade S3 bucket

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Data sources
data "aws_caller_identity" "current" {}

# Random suffix
resource "random_id" "suffix" {
  count = var.use_random_suffix ? 1 : 0
  byte_length = 4
  prefix      = ""
}

# Locals
locals {
  account_alias_prefix = var.use_account_alias_prefix ? "${data.aws_caller_identity.current.account_id}-" : ""
  random_suffix        = var.use_random_suffix ? "-${random_id.suffix[0].hex}" : ""
  bucket_name          = "${local.account_alias_prefix}${var.bucket_name}${local.random_suffix}"

  # Default encryption algorithm
  sse_algorithm = var.kms_master_key_id != "" ? "aws:kms" : "AES256"
}

# S3 bucket
resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  lifecycle {
    prevent_destroy = true
  }
}

# Optional public access block
resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id != "" ? var.kms_master_key_id : null
    }
    bucket_key_enabled = var.bucket_key_enabled
  }
}

# Ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

# Lifecycle configuration
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = "all_storage_classes_128K"

  # Rule: abort incomplete multipart uploads after 14 days
  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  # Rule: transition noncurrent versions to STANDARD_IA after 30 days, expire after 365 days
  rule {
    id     = "noncurrent-version-lifecycle"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  # Rule: expire analytics data after 30 days
  rule {
    id     = "analytics-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  # Rule: expire inventory data after 14 days
  rule {
    id     = "inventory-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }
}

# Analytics configuration
resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "AnalyticsExport"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          prefix     = "_AWSBucketAnalytics/"
          format     = "CSV"
        }
      }
    }
  }
}

# Optional inventory configuration
resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "Inventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  filter {
    prefix = "_AWSBucketInventory/"
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectLockRetainUntilDate",
    "ObjectLockMode",
    "ObjectLockLegalHoldStatus",
    "IntelligentTieringAccessTier",
    "BucketKeyStatus"
  ]

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = "_AWSBucketInventory/"
      encryption {
        sse_s3 {}
      }
    }
  }
}

# Bucket policy
data "aws_iam_policy_document" "bucket_policy" {
  # Deny non-TLS requests
  statement {
    sid       = "DenyNonTLS"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }

  # Allow S3 service principal to write analytics data
  statement {
    sid       = "AllowS3AnalyticsWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  # Allow S3 service principal to write inventory data
  statement {
    sid       = "AllowS3InventoryWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.this.arn}/_AWSBucketInventory/*"]
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }

  # Merge custom policy if provided
  source_policy_documents = var.custom_bucket_policy != "" ? [var.custom_bucket_policy] : []
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json
}

# Optional logging
resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

# Optional transfer acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

# Optional ACL
resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != "" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

# CORS configuration (only created when CORS rules are provided)
resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Base name for the S3 bucket"
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Whether to prepend the AWS account ID to the bucket name (uses account ID as prefix since IAM account alias may not exist in greenfield accounts)"
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Whether to append a random suffix to the bucket name"
  type        = bool
  default     = false
}

variable "enable_s3_public_access_block" {
  description = "Enable S3 public access block settings"
  type        = bool
  default     = true
}

variable "enable_analytics" {
  description = "Enable storage class analytics"
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Enable bucket inventory"
  type        = bool
  default     = false
}

variable "kms_master_key_id" {
  description = "KMS master key ID for SSE-KMS encryption. If empty, AES256 is used."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for SSE-KMS"
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if non-empty"
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "Target bucket for server access logs. Leave empty to disable logging."
  type        = string
  default     = ""
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status ('Enabled' or 'Suspended'). Set to null to disable."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL to apply to the bucket. Leave empty to skip ACL (ownership controls enforced)."
  type        = string
  default     = ""
}

variable "cors_rules" {
  description = "List of CORS rules. Each rule must have allowed_headers, allowed_methods, allowed_origins."
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "custom_bucket_policy" {
  description = "JSON string of a custom bucket policy to merge with the default policy."
  type        = string
  default     = ""
}

# Outputs
output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  value = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  value = aws_s3_bucket.this.bucket_regional_domain_name
}

# Terraform required providers
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources
data "aws_canonical_user_id" "current" {}

data "aws_caller_identity" "current" {}

# Variables
variable "bucket_name" {
  description = "Prefix for the main S3 bucket name (a unique suffix will be appended)"
  type        = string
  default     = "benchmark-access-logs-bkt"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "Development"
}

variable "tags" {
  description = "Additional tags for resources"
  type        = map(string)
  default = {
    ServiceProvider = "Rackspace"
  }
}

variable "public_access_block_enabled" {
  description = "Enable public access block settings on the main bucket"
  type        = bool
  default     = true
}

variable "encryption_algorithm" {
  description = "Server-side encryption algorithm: 'AES256', 'aws:kms', or 'none'"
  type        = string
  default     = "AES256"
  validation {
    condition     = contains(["AES256", "aws:kms", "none"], var.encryption_algorithm)
    error_message = "Valid values: AES256, aws:kms, none."
  }
}

variable "kms_key_id" {
  description = "Existing KMS key ID for encryption. If empty, a new key is created."
  type        = string
  default     = ""
}

variable "bucket_key_enabled" {
  description = "Enable S3 bucket key for KMS encryption"
  type        = bool
  default     = false
}

variable "control_object_ownership" {
  description = "Enable object ownership controls"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting when control_object_ownership is true"
  type        = string
  default     = "ObjectWriter"
}

variable "canned_acl" {
  description = "Canned ACL to apply to the bucket (e.g., 'private', 'public-read')"
  type        = string
  default     = ""
}

variable "grants_json" {
  description = "JSON-encoded list of grant objects (e.g., [{\"type\":\"Group\",\"uri\":\"http://acs.amazonaws.com/groups/global/AllUsers\",\"permissions\":[\"READ\"]}])"
  type        = string
  default     = ""
}

variable "versioning_status" {
  description = "Versioning status: 'Enabled' or 'Suspended'"
  type        = string
  default     = "Suspended"
}

variable "mfa_delete" {
  description = "MFA delete status: 'Enabled' or 'Disabled'"
  type        = string
  default     = "Disabled"
}

variable "bucket_logging" {
  description = "Enable bucket logging"
  type        = bool
  default     = false
}

variable "log_bucket_name" {
  description = "Name of the logging bucket (created if bucket_logging is true)"
  type        = string
  default     = "benchmark-access-logs-bkt-logs"
}

variable "log_prefix" {
  description = "Prefix for log objects in the logging bucket"
  type        = string
  default     = ""
}

variable "object_lock_enabled" {
  description = "Enable S3 Object Lock (forces bucket creation with object lock enabled)"
  type        = bool
  default     = false
}

variable "website_config" {
  description = "Map of website configuration settings: index_document, error_document, redirect_all_requests_to, routing_rules"
  type        = any
  default     = {}
}

variable "intelligent_tiering" {
  description = "Map of intelligent tiering configuration"
  type        = any
  default     = {}
}

variable "cloudwatch_metrics" {
  description = "Map of CloudWatch metrics configurations"
  type        = any
  default     = {}
}

variable "cors_rules" {
  description = "List of CORS rule maps"
  type        = any
  default     = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule maps"
  type        = any
  default     = []
}

# Locals
locals {
  merged_tags = merge(
    { Environment = var.environment },
    var.tags
  )

  # Parse grants JSON if provided
  grants_list = var.grants_json != "" ? jsondecode(var.grants_json) : []

  # Determine if we need to create a KMS key
  create_kms_key = var.encryption_algorithm == "aws:kms" && var.kms_key_id == ""

  # KMS key ID to use
  kms_key_id_final = local.create_kms_key ? aws_kms_key.main[0].arn : var.kms_key_id
}

# Main S3 bucket (uses bucket_prefix for uniqueness)
resource "aws_s3_bucket" "main" {
  bucket_prefix = var.bucket_name

  # Object Lock requires bucket creation with object_lock_enabled = true
  object_lock_enabled = var.object_lock_enabled

  tags = local.merged_tags

  lifecycle {
    prevent_destroy = true
  }
}

# Public access block (conditional)
resource "aws_s3_bucket_public_access_block" "main" {
  count = var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# KMS key (created only if encryption is aws:kms and no existing key ID provided)
data "aws_iam_policy_document" "kms_key" {
  count = local.create_kms_key ? 1 : 0

  statement {
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
}

resource "aws_kms_key" "main" {
  count = local.create_kms_key ? 1 : 0

  description             = "S3 bucket encryption key for ${var.bucket_name}"
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms_key[0].json

  lifecycle {
    prevent_destroy = true
  }
}

# Encryption configuration (conditional)
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  count = var.encryption_algorithm != "none" ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption_algorithm == "aws:kms" ? "aws:kms" : "AES256"
      kms_master_key_id = var.encryption_algorithm == "aws:kms" ? local.kms_key_id_final : null
    }
    bucket_key_enabled = var.encryption_algorithm == "aws:kms" ? var.bucket_key_enabled : null
  }
}

# Ownership controls (conditional)
resource "aws_s3_bucket_ownership_controls" "main" {
  count = var.control_object_ownership ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    object_ownership = var.object_ownership
  }
}

# Bucket ACL with canned ACL or grants (skipped when public access block is enabled)
resource "aws_s3_bucket_acl" "main" {
  count = (var.canned_acl != "" || length(local.grants_list) > 0) && !var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  # Use canned ACL if provided (mutually exclusive with access_control_policy)
  acl = var.canned_acl != "" ? var.canned_acl : null

  # Use access_control_policy if grants are provided
  dynamic "access_control_policy" {
    for_each = length(local.grants_list) > 0 ? [1] : []

    content {
      dynamic "grant" {
        for_each = local.grants_list

        content {
          grantee {
            type = grant.value.type
            uri  = try(grant.value.uri, null)
            id   = try(grant.value.id, null)
          }
          permission = grant.value.permissions[0]
        }
      }
      owner {
        id = data.aws_canonical_user_id.current.id
      }
    }
  }
}

# Fallback ACL granting full control to canonical user (skipped when public access block is enabled)
resource "aws_s3_bucket_acl" "fallback" {
  count = (var.canned_acl == "" && length(local.grants_list) == 0) && !var.public_access_block_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  depends_on = [aws_s3_bucket_ownership_controls.main]

  access_control_policy {
    grant {
      grantee {
        type = "CanonicalUser"
        id   = data.aws_canonical_user_id.current.id
      }
      permission = "FULL_CONTROL"
    }
    owner {
      id = data.aws_canonical_user_id.current.id
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.bucket

  versioning_configuration {
    status    = var.versioning_status
    mfa_delete = var.mfa_delete
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Logging bucket (conditional)
resource "aws_s3_bucket" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = var.log_bucket_name

  tags = merge(local.merged_tags, { Name = var.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Bucket logging (conditional)
resource "aws_s3_bucket_logging" "main" {
  count = var.bucket_logging ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = var.log_prefix
}

# Object Lock configuration (conditional)
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  rule {
    default_retention {
      mode = "GOVERNANCE"
      days = 365
    }
  }
}

# Website configuration (conditional)
resource "aws_s3_bucket_website_configuration" "main" {
  count = length(var.website_config) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  index_document {
    suffix = try(var.website_config.index_document, "index.html")
  }

  error_document {
    key = try(var.website_config.error_document, "error.html")
  }

  dynamic "redirect_all_requests_to" {
    for_each = can(var.website_config.redirect_all_requests_to) ? [var.website_config.redirect_all_requests_to] : []

    content {
      host_name = redirect_all_requests_to.value
    }
  }

  dynamic "routing_rule" {
    for_each = can(var.website_config.routing_rules) ? var.website_config.routing_rules : []

    content {
      redirect {
        host_name = routing_rule.value.redirect.host_name
        protocol  = routing_rule.value.redirect.protocol
      }
    }
  }
}

# Intelligent Tiering (conditional)
resource "aws_s3_bucket_intelligent_tiering_configuration" "main" {
  count = length(var.intelligent_tiering) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket
  name   = try(var.intelligent_tiering.name, "Default")

  dynamic "tiering" {
    for_each = try(var.intelligent_tiering.tiering, [])

    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# CloudWatch Metrics (conditional)
resource "aws_s3_bucket_metric" "main" {
  count = length(var.cloudwatch_metrics) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket
  name   = try(var.cloudwatch_metrics.name, "Default")

  filter {
    prefix = try(var.cloudwatch_metrics.filter.prefix, null)
    tags   = try(var.cloudwatch_metrics.filter.tags, null)
  }
}

# CORS configuration (conditional)
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, [])
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, [])
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

# Lifecycle configuration (conditional)
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.bucket

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = try(rule.value.status, "Enabled")

      dynamic "abort_incomplete_multipart_upload" {
        for_each = can(rule.value.abort_incomplete_multipart_upload) ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }

      dynamic "expiration" {
        for_each = can(rule.value.expiration) ? [rule.value.expiration] : []

        content {
          date = try(expiration.value.date, null)
          days = try(expiration.value.days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = can(rule.value.noncurrent_version_transition) ? rule.value.noncurrent_version_transition : []

        content {
          noncurrent_days = noncurrent_version_transition.value.noncurrent_days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# Terraform settings
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.80, != 5.100.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "bucket_name" {
  description = "Name of the S3 bucket (max 63 characters)"
  type        = string
  default     = null
  validation {
    condition     = var.bucket_name == null || length(var.bucket_name) <= 63
    error_message = "Bucket name must be at most 63 characters."
  }
}

variable "bucket_name_prefix" {
  description = "Prefix for bucket name (max 37 characters)"
  type        = string
  default     = null
  validation {
    condition     = var.bucket_name_prefix == null || length(var.bucket_name_prefix) <= 37
    error_message = "Bucket name prefix must be at most 37 characters."
  }
}

variable "force_destroy" {
  description = "Allow force destruction of the bucket even if non-empty"
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object Ownership setting: BucketOwnerEnforced or ObjectWriter"
  type        = string
  default     = "BucketOwnerEnforced"
  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter"], var.object_ownership)
    error_message = "object_ownership must be either 'BucketOwnerEnforced' or 'ObjectWriter'."
  }
}

variable "block_public_acls" {
  description = "Block public ACLs"
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Block public bucket policies"
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Ignore public ACLs"
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Restrict public buckets"
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Enable bucket versioning"
  type        = bool
  default     = false
}

variable "kms_key_arn" {
  description = "ARN of KMS key for server-side encryption (if not provided, uses AES256)"
  type        = string
  default     = null
}

variable "enable_eventbridge" {
  description = "Enable EventBridge notifications"
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Target bucket for server access logs"
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix for log objects"
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "ARNs of source buckets for logging permissions policy"
  type        = list(string)
  default     = []
}

variable "custom_bucket_policy" {
  description = "Custom JSON bucket policy to combine with default policies"
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Enable object lock configuration"
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Object lock mode (GOVERNANCE or COMPLIANCE)"
  type        = string
  default     = "GOVERNANCE"
  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "Object lock mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Number of days for object lock retention"
  type        = number
  default     = null
}

variable "object_lock_years" {
  description = "Number of years for object lock retention"
  type        = number
  default     = null
}

variable "replication_rules" {
  description = "List of replication rules (each with id, priority, destination_bucket_arn, destination_region, and optional filters)"
  type = list(object({
    id                              = string
    priority                        = number
    destination_bucket_arn          = string
    destination_region              = string
    filter_and_prefix               = optional(string)
    filter_and_tags                 = optional(map(string))
    delete_marker_replication_status = optional(string)
  }))
  default = []
}

variable "inventory_configurations" {
  description = "List of inventory configurations"
  type = list(object({
    name                      = string
    enabled                   = optional(bool, true)
    included_object_versions  = optional(string, "All")
    optional_fields           = optional(list(string))
    destination_bucket_arn    = string
    destination_format        = string
    destination_prefix        = optional(string)
    schedule_frequency        = string
    filter_prefix             = optional(string)
  }))
  default = []
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules"
  type = list(object({
    id                                       = string
    status                                   = optional(string, "Enabled")
    prefix                                   = optional(string)
    tags                                     = optional(map(string))
    expiration_days                          = optional(number)
    expiration_date                          = optional(string)
    expiration_expired_object_delete_marker  = optional(bool)
    transition_days                          = optional(number)
    transition_date                          = optional(string)
    transition_storage_class                 = optional(string)
    noncurrent_version_expiration_days       = optional(number)
    noncurrent_version_transition_days       = optional(number)
    noncurrent_version_transition_storage_class = optional(string)
    abort_incomplete_multipart_upload_days   = optional(number)
  }))
  default = []
}

# Locals
locals {
  bucket_name = coalesce(
    var.bucket_name,
    var.bucket_name_prefix != null ? "${var.bucket_name_prefix}${random_string.suffix.result}" : "s3-bucket-${random_string.suffix.result}"
  )

  logging_configured = var.logging_target_bucket != null && var.logging_target_prefix != null

  ssl_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureConnections"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.this.arn,
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })

  logging_policy = length(var.logging_source_bucket_arns) > 0 ? jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogsPolicy"
        Effect    = "Allow"
        Principal = { Service = "logging.s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource = [
          "${aws_s3_bucket.this.arn}/*"
        ]
        Condition = {
          ArnLike = {
            "aws:SourceArn" = var.logging_source_bucket_arns
          }
        }
      }
    ]
  }) : null
}

resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
}

# Main bucket
resource "aws_s3_bucket" "this" {
  bucket       = local.bucket_name
  force_destroy = var.force_destroy
}

# Object ownership controls
resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id
  rule {
    object_ownership = var.object_ownership
  }
}

# Conditional ACL for ObjectWriter ownership
resource "aws_s3_bucket_acl" "this" {
  count      = var.object_ownership == "ObjectWriter" ? 1 : 0
  bucket     = aws_s3_bucket.this.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.this]
}

# Public access block
resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

# Server-side encryption
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.kms_key_arn != null ? "aws:kms" : "AES256"
      kms_master_key_id = var.kms_key_arn != null ? var.kms_key_arn : null
    }
    bucket_key_enabled = var.kms_key_arn != null ? true : null
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# Combined bucket policy
data "aws_iam_policy_document" "combined" {
  source_policy_documents = compact([
    local.ssl_policy,
    var.custom_bucket_policy,
    local.logging_policy
  ])
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined.json
}

# EventBridge notification
resource "aws_s3_bucket_notification" "this" {
  count       = var.enable_eventbridge ? 1 : 0
  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

# Server access logging
resource "aws_s3_bucket_logging" "this" {
  count  = local.logging_configured ? 1 : 0
  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Cannot enable server access logging when object lock is enabled."
    }
  }
}

# Object lock configuration
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count  = var.object_lock_enabled ? 1 : 0
  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = var.object_lock_days
      years = var.object_lock_years
    }
  }

  lifecycle {
    precondition {
      condition     = !local.logging_configured
      error_message = "Cannot enable object lock when server access logging is configured."
    }
  }
}

# Replication configuration
resource "aws_s3_bucket_replication_configuration" "this" {
  count  = length(var.replication_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = "Enabled"

      delete_marker_replication {
        status = rule.value.delete_marker_replication_status != null ? rule.value.delete_marker_replication_status : "Disabled"
      }

      destination {
        bucket = rule.value.destination_bucket_arn
      }

      filter {
        dynamic "and" {
          for_each = rule.value.filter_and_prefix != null && length(rule.value.filter_and_tags) > 0 ? [1] : []
          content {
            prefix = rule.value.filter_and_prefix
            tags   = rule.value.filter_and_tags
          }
        }
        prefix = rule.value.filter_and_prefix
      }
    }
  }
}

# Replication IAM role
resource "aws_iam_role" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "${aws_s3_bucket.this.id}-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

data "aws_caller_identity" "current" {}

resource "aws_iam_policy" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0
  name  = "${aws_s3_bucket.this.id}-replication-policy"
  policy = data.aws_iam_policy_document.replication[0].json
}

data "aws_iam_policy_document" "replication" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket"
    ]
    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging"
    ]
    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  dynamic "statement" {
    for_each = var.replication_rules
    content {
      effect = "Allow"
      actions = [
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags"
      ]
      resources = ["${statement.value.destination_bucket_arn}/*"]
    }
  }
}

resource "aws_iam_role_policy_attachment" "replication" {
  count      = length(var.replication_rules) > 0 ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

# Inventory configurations
resource "aws_s3_bucket_inventory" "this" {
  for_each = { for idx, inv in var.inventory_configurations : idx => inv }

  bucket = aws_s3_bucket.this.id
  name   = each.value.name
  enabled = each.value.enabled
  included_object_versions = each.value.included_object_versions
  optional_fields = each.value.optional_fields

  destination {
    bucket {
      format     = each.value.destination_format
      bucket_arn = each.value.destination_bucket_arn
      prefix     = each.value.destination_prefix

      encryption {
        sse_s3 {}
      }
    }
  }

  schedule {
    frequency = each.value.schedule_frequency
  }

  filter {
    prefix = each.value.filter_prefix
  }
}

# CORS configuration (conditional on at least one rule)
resource "aws_s3_bucket_cors_configuration" "this" {
  count  = length(var.cors_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Lifecycle configuration (conditional on at least one rule)
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count  = length(var.lifecycle_rules) > 0 ? 1 : 0
  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.prefix != null || length(rule.value.tags) > 0 ? [1] : []
        content {
          prefix = rule.value.prefix
          dynamic "tag" {
            for_each = rule.value.tags != null ? rule.value.tags : {}
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration_days != null || rule.value.expiration_date != null || rule.value.expiration_expired_object_delete_marker != null ? [1] : []
        content {
          days                         = rule.value.expiration_days
          date                         = rule.value.expiration_date
          expired_object_delete_marker = rule.value.expiration_expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition_days != null || rule.value.transition_date != null ? [1] : []
        content {
          days          = rule.value.transition_days
          date          = rule.value.transition_date
          storage_class = rule.value.transition_storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration_days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition_days != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_transition_days
          storage_class   = rule.value.noncurrent_version_transition_storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }
    }
  }
}

# Outputs
output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "group_name_prefix" {
  description = "Prefix for IAM group names"
  type        = string
  default     = "app"
}

variable "designated_region" {
  description = "AWS region allowed for s3:CreateBucket"
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket" {
  description = "Name of the remote state S3 bucket to deny access to"
  type        = string
  default     = "remote-state-bucket"
}

data "aws_caller_identity" "current" {}

# IAM Account Password Policy
resource "aws_iam_account_password_policy" "strict" {
  minimum_password_length      = 12
  require_uppercase_characters = true
  require_lowercase_characters = true
  require_numbers              = true
  require_symbols              = true
  allow_users_to_change_password = true
  hard_expiry                  = false
  max_password_age             = 0
  password_reuse_prevention    = 0
}

# S3 Account Public Access Block
resource "aws_s3_account_public_access_block" "global" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# IAM Groups
resource "aws_iam_group" "developer" {
  name = "${var.group_name_prefix}_developer"
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = "${var.group_name_prefix}_admin"
  path = "/"
}

# Attach AWS-managed policies to developer group
resource "aws_iam_group_policy_attachment" "developer_readonly" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:aws:iam::aws:policy/IAMUserSSHKeys"
}

# Custom policy: Developer personal access key management
resource "aws_iam_policy" "developer_access_keys" {
  name        = "${var.group_name_prefix}_developer_access_keys"
  description = "Manage personal access keys"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:CreateAccessKey",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_access_keys_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_access_keys.arn
}

# Custom policy: Virtual MFA device management
resource "aws_iam_policy" "developer_mfa_devices" {
  name        = "${var.group_name_prefix}_developer_mfa_devices"
  description = "Manage virtual MFA devices"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Effect   = "Allow"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_mfa_devices_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_mfa_devices.arn
}

# Custom policy: MFA-gated S3 access
resource "aws_iam_policy" "developer_s3_mfa" {
  name        = "${var.group_name_prefix}_developer_s3_mfa"
  description = "MFA-gated S3 access"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Deny"
        Action   = "s3:CreateBucket"
        Resource = "arn:aws:s3:::*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.designated_region
          }
        }
      },
      {
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = [
          "arn:aws:s3:::${var.remote_state_bucket}",
          "arn:aws:s3:::${var.remote_state_bucket}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

# Custom policy: MFA-gated EC2, ELB, CloudWatch, AutoScaling, service-linked roles
resource "aws_iam_policy" "developer_ec2_mfa" {
  name        = "${var.group_name_prefix}_developer_ec2_mfa"
  description = "MFA-gated access to EC2, ELB, CloudWatch, AutoScaling, and service-linked roles"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Effect   = "Allow"
        Action   = "iam:PassRole"
        Resource = [
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/aws-service-role/ec2.amazonaws.com/AWSServiceRoleForEC2"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_ec2_mfa_attach" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_ec2_mfa.arn
}

# Admin role
resource "aws_iam_role" "admin" {
  name = "admin"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action    = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# Admin role policy: full admin with MFA
resource "aws_iam_policy" "admin_role_policy" {
  name        = "admin_role_full_admin_mfa"
  description = "Full admin access with MFA requirement"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_role_attach" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_role_policy.arn
}

# Admin group policy: allow sts:AssumeRole to admin role with MFA
resource "aws_iam_policy" "admin_group_assume_role" {
  name        = "${var.group_name_prefix}_admin_assume_admin_role"
  description = "Allow assuming admin role with MFA"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_role_attach" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_role.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_cidr" {
  type    = string
  default = "10.0.0.0/16"
}

variable "subnets" {
  type = list(object({
    cidr_block        = string
    availability_zone = string
    name              = string
  }))
  default = [
    { cidr_block = "10.0.0.0/24",  availability_zone = "us-east-1a", name = "subnet-0" },
    { cidr_block = "10.0.1.0/24",  availability_zone = "us-east-1b", name = "subnet-1" },
    { cidr_block = "10.0.2.0/24",  availability_zone = "us-east-1c", name = "subnet-2" },
    { cidr_block = "10.0.3.0/24",  availability_zone = "us-east-1a", name = "subnet-3" },
    { cidr_block = "10.0.4.0/24",  availability_zone = "us-east-1b", name = "subnet-4" },
    { cidr_block = "10.0.5.0/24",  availability_zone = "us-east-1c", name = "subnet-5" },
    { cidr_block = "10.0.6.0/24",  availability_zone = "us-east-1a", name = "subnet-6" },
    { cidr_block = "10.0.7.0/24",  availability_zone = "us-east-1b", name = "subnet-7" },
    { cidr_block = "10.0.8.0/24",  availability_zone = "us-east-1c", name = "subnet-8" },
    { cidr_block = "10.0.9.0/24",  availability_zone = "us-east-1a", name = "subnet-9" },
    { cidr_block = "10.0.10.0/24", availability_zone = "us-east-1b", name = "subnet-10" },
    { cidr_block = "10.0.11.0/24", availability_zone = "us-east-1c", name = "subnet-11" },
    { cidr_block = "10.0.12.0/24", availability_zone = "us-east-1a", name = "subnet-12" },
    { cidr_block = "10.0.13.0/24", availability_zone = "us-east-1b", name = "subnet-13" },
    { cidr_block = "10.0.14.0/24", availability_zone = "us-east-1c", name = "subnet-14" },
    { cidr_block = "10.0.15.0/24", availability_zone = "us-east-1a", name = "subnet-15" },
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  assign_generated_ipv6_cidr_block = true
  tags = {
    Name = "my-deploy-me-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "igw-deploy-me"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.main[0].id
  depends_on    = [aws_internet_gateway.main]
  tags = {
    Name = "deployme-natgw"
  }
}

resource "aws_subnet" "main" {
  for_each = { for idx, subnet in var.subnets : idx => subnet }

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value.cidr_block
  availability_zone       = each.value.availability_zone
  map_public_ip_on_launch = false
  tags = {
    Name = each.value.name
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = {
    Name = "rt-private-deploy-me"
  }
}

resource "aws_main_route_table_association" "private" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  for_each = { for idx in range(0, 8) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }
  tags = {
    Name = "rt-public-deploy-me"
  }
}

resource "aws_route_table_association" "public" {
  for_each = { for idx in range(8, 12) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "spare" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }
  tags = {
    Name = "rt-spare-deploy-me"
  }
}

resource "aws_route_table_association" "spare" {
  for_each = { for idx in range(12, 16) : idx => idx }

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.spare.id
}

resource "aws_security_group" "allow_web_traffic" {
  name        = "allow_web_traffic"
  description = "Allow inbound HTTP, HTTPS, and SSH traffic from VPC and web from anywhere"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = {
    Name = "allow_web_traffic"
  }
}

output "server_public_ip" {
  value = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name" {
  description = "Name component of the standard label"
  type        = string
  default     = "my-security-group"
}

variable "environment" {
  description = "Environment component of the standard label"
  type        = string
  default     = "dev"
}

variable "managedby" {
  description = "ManagedBy tag value"
  type        = string
  default     = "opsstation"
}

variable "label_order" {
  description = "Order of label components"
  type        = list(string)
  default     = ["name", "environment"]
}

variable "repository" {
  description = "Repository URL for the source code"
  type        = string
  default     = "https://github.com/opsstation/terraform-aws-security_group"
}

variable "enabled" {
  description = "Master switch to enable or disable all module resources"
  type        = bool
  default     = true
}

variable "new_sg" {
  description = "When true, create a new security group; when false, use existing_sg_id"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID in which to create the security group. If null and new_sg is true, a VPC will be created automatically."
  type        = string
  default     = null
}

variable "existing_sg_id" {
  description = "Existing security group ID to apply rules to (required when new_sg = false)"
  type        = string
  default     = null
}

variable "prefix_list_enabled" {
  description = "Flag to enable creation or use of managed prefix lists"
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list IDs; when empty and prefix_list_enabled is true, a new prefix list is created"
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list"
  type        = string
  default     = "IPv4"
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries in the managed prefix list"
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Entries for the managed prefix list"
  type = list(object({
    cidr        = string
    description = string
  }))
  default = []
}

variable "ingress_rules" {
  description = "List of ingress security group rules"
  type = list(object({
    description              = string
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress security group rules"
  type = list(object({
    description              = string
    protocol                 = string
    from_port                = number
    to_port                  = number
    cidr_blocks              = optional(list(string), [])
    ipv6_cidr_blocks         = optional(list(string), [])
    self                     = optional(bool, false)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []
}

locals {
  label_id         = try(module.labels[0].id, "")
  label_tags       = try(module.labels[0].tags, {})
  sg_name          = format("%s-sg", local.label_id)
  prefix_name      = format("%s-prefix-list", local.label_id)
  effective_vpc_id = var.vpc_id != null ? var.vpc_id : (var.enabled && var.new_sg ? aws_vpc.this[0].id : null)
  sg_id            = var.enabled ? (var.new_sg ? aws_security_group.this[0].id : var.existing_sg_id) : null
  prefix_list_id   = var.enabled && (var.prefix_list_enabled || length(var.prefix_list_ids) > 0) ? (
    length(var.prefix_list_ids) > 0 ? var.prefix_list_ids[0] : aws_ec2_managed_prefix_list.this[0].id
  ) : null
}

module "labels" {
  source      = "git::git@github.com:opsstation/terraform-aws-labels.git?ref=v1.0.0"
  count       = var.enabled ? 1 : 0
  name        = var.name
  environment = var.environment
  managedby   = var.managedby
  label_order = var.label_order
  repository  = var.repository
}

resource "aws_vpc" "this" {
  count                = var.enabled && var.new_sg && var.vpc_id == null ? 1 : 0
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.label_tags, { Name = format("%s-vpc", local.label_id) })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group" "this" {
  count       = var.enabled && var.new_sg ? 1 : 0
  name        = local.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.effective_vpc_id

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.label_tags, { Name = local.sg_name })
}

resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.prefix_list_enabled && length(var.prefix_list_ids) == 0 ? 1 : 0
  name           = local.prefix_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = merge(local.label_tags, { Name = local.prefix_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_security_group_rule" "ingress" {
  for_each = var.enabled ? { for idx, rule in var.ingress_rules : idx => rule } : {}

  type              = "ingress"
  security_group_id = local.sg_id
  description       = each.value.description
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self                     = each.value.self ? true : null
  source_security_group_id = try(each.value.source_security_group_id, null) != null && try(each.value.source_security_group_id, "") != "" ? each.value.source_security_group_id : null
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null && try(each.value.prefix_list_id, "") != "" ? [each.value.prefix_list_id] : (local.prefix_list_id != null ? [local.prefix_list_id] : [])
}

resource "aws_security_group_rule" "egress" {
  for_each = var.enabled ? { for idx, rule in var.egress_rules : idx => rule } : {}

  type              = "egress"
  security_group_id = local.sg_id
  description       = each.value.description
  protocol          = each.value.protocol
  from_port         = each.value.from_port
  to_port           = each.value.to_port

  cidr_blocks              = length(each.value.cidr_blocks) > 0 ? each.value.cidr_blocks : null
  ipv6_cidr_blocks         = length(each.value.ipv6_cidr_blocks) > 0 ? each.value.ipv6_cidr_blocks : null
  self                     = each.value.self ? true : null
  source_security_group_id = try(each.value.source_security_group_id, null) != null && try(each.value.source_security_group_id, "") != "" ? each.value.source_security_group_id : null
  prefix_list_ids          = try(each.value.prefix_list_id, null) != null && try(each.value.prefix_list_id, "") != "" ? [each.value.prefix_list_id] : (local.prefix_list_id != null ? [local.prefix_list_id] : [])
}

output "security_group_id" {
  description = "The ID of the security group (new or existing)"
  value       = local.sg_id
}

output "prefix_list_id" {
  description = "The ID of the managed prefix list (if created or provided)"
  value       = local.prefix_list_id
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_name" {
  type        = string
  default     = "dev"
  description = "Environment name used to construct IAM role names"
}

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ---------------------------------------------------------------------------
# 1. Account Password Policy
# ---------------------------------------------------------------------------
resource "aws_iam_account_password_policy" "this" {
  minimum_password_length      = 14
  require_lowercase_characters = true
  require_uppercase_characters = true
  require_numbers              = true
  require_symbols              = false
  allow_users_to_change_password = true
  max_password_age             = 90
  password_reuse_prevention    = 3
}

# ---------------------------------------------------------------------------
# 2. ECS Task Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_task_secretsmanager" {
  role       = aws_iam_role.ecs_task.name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}

resource "aws_iam_role_policy" "ecs_task_s3_custom" {
  name = "ecs-task-s3-custom"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObjectVersion",
          "s3:PutObjectAcl",
          "s3:GetBucketAcl",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_ssm_messages" {
  name = "ecs-task-ssm-messages"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ssmmessages:CreateControlChannel",
          "ssmmessages:CreateDataChannel",
          "ssmmessages:OpenControlChannel",
          "ssmmessages:OpenDataChannel"
        ]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 3. ECS Execution Role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role-for-${var.environment_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ecs_execution_ecstask" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_iam_role_policy_attachment" "ecs_execution_ec2container" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

resource "aws_iam_role_policy" "ecs_execution_inline" {
  name = "ecs-execution-secrets-kms"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:secret:*"
      },
      {
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = "arn:aws:kms:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:key/*"
      }
    ]
  })
}

