resource "aws_iam_role_policy" "eventbridge_stepfunctions_inline" {
  name = "eventbridge-stepfunctions-policy"
  role = aws_iam_role.eventbridge_stepfunctions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "states:StartExecution"
        Resource = "arn:aws:states:${data.aws_region.current.id}:${data.aws_caller_identity.current.account_id}:stateMachine:*"
        Condition = {
          StringEquals = {
            "aws:ResourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 9. Developer Policy (MFA-limited)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "developers_policy_limited_mfa" {
  name        = "developers-policy-limited-mfa"
  description = "Developer access with MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:GetObjectVersion",
          "s3:PutObjectAcl",
          "s3:GetBucketAcl",
          "s3:ListAllMyBuckets"
        ]
        Resource = "*"
      },
      {
        Sid    = "SecretsManagerReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:ListSecrets"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "CloudWatchAndECSReadOnlyWithMFA"
        Effect = "Allow"
        Action = [
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "ecs:Describe*",
          "ecs:List*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
          "iam:UpdateAccessKey",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "ExplicitDenyWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice",
          "iam:UpdateAccessKey",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# 10. Billing Policy (MFA-limited)
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "billing_policy_limited_mfa" {
  name        = "billing-policy-limited-mfa"
  description = "Billing access with MFA enforcement"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "BillingAccessWithMFA"
        Effect = "Allow"
        Action = [
          "aws-portal:*",
          "budgets:*",
          "ce:*",
          "payments:*",
          "tax:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "SelfServiceIAM"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
      },
      {
        Sid    = "ExplicitDenyWithoutMFA"
        Effect = "Deny"
        NotAction = [
          "iam:ChangePassword",
          "iam:CreateLoginProfile",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ListVirtualMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

variable "config" {
  type        = string
  description = "YAML configuration for pipelines"
  default     = <<YAML
pipelines:
  - name: pipeline-one
    source:
      provider: CodeCommit
      repository_name: my-repo
      branch: main
    role_arn: null
    stages:
      - name: Source
        actions:
          - name: Source
            category: Source
            owner: AWS
            provider: CodeCommit
            version: 1
            configuration:
              RepositoryName: my-repo
              BranchName: main
      - name: Build
        actions:
          - name: Build
            category: Build
            owner: AWS
            provider: CodeBuild
            version: 1
            configuration:
              ProjectName: pipeline-one-build
              EnvironmentType: LINUX_CONTAINER
              ComputeType: BUILD_GENERAL1_SMALL
              Image: aws/codebuild/standard:6.0
      - name: Approval
        actions:
          - name: Approve
            category: Approval
            owner: AWS
            provider: Manual
            version: 1
            configuration: {}
      - name: Deploy
        actions:
          - name: InvokeLambda
            category: Invoke
            owner: AWS
            provider: Lambda
            version: 1
            configuration:
              FunctionName: pipeline-one-function
              UserParameters: "{}"
    triggers:
      - type: branch
        branch: main
      - type: cron
        expression: "cron(0 0 * * ? *)"
  - name: pipeline-two
    source:
      provider: GitHub
      repository_owner: myorg
      repository_name: my-repo
      branch: develop
    role_arn: null
    stages:
      - name: Source
        actions:
          - name: Source
            category: Source
            owner: AWS
            provider: CodeStarSourceConnection
            version: 1
            configuration:
              ConnectionArn: placeholder
              FullRepositoryId: myorg/my-repo
              BranchName: develop
      - name: Build
        actions:
          - name: Build
            category: Build
            owner: AWS
            provider: CodeBuild
            version: 1
            configuration:
              ProjectName: pipeline-two-build
              EnvironmentType: LINUX_CONTAINER
              ComputeType: BUILD_GENERAL1_SMALL
              Image: aws/codebuild/standard:6.0
    triggers:
      - type: cron
        expression: "cron(0 12 * * ? *)"
      - type: custom
        pattern: '{"source": ["aws.codecommit"], "detail-type": ["CodeCommit Repository State Change"]}'
YAML
}

locals {
  parsed_config = yamldecode(var.config)
  pipelines     = { for p in local.parsed_config.pipelines : p.name => p }

  # Extract CodeBuild configuration for pipelines that have a CodeBuild stage
  codebuild_projects = {
    for pname, pipeline in local.pipelines :
    pname => {
      name       = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.ProjectName, null)
      env_type   = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.EnvironmentType, "LINUX_CONTAINER")
      compute    = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.ComputeType, "BUILD_GENERAL1_SMALL")
      image      = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0].configuration.Image, "aws/codebuild/standard:6.0")
    }
    if try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "CodeBuild"][0], null) != null
  }

  # Extract Lambda configuration for pipelines that have a Lambda action
  lambda_functions = {
    for pname, pipeline in local.pipelines :
    pname => {
      name = try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "Lambda"][0].configuration.FunctionName, null)
    }
    if try([for a in flatten([for s in pipeline.stages : s.actions]) : a if a.provider == "Lambda"][0], null) != null
  }

  # Determine if a default CodePipeline IAM role is needed
  default_role_needed = length([for p in local.pipelines : p if p.role_arn == null]) > 0

  # Map from trigger key to pipeline name
  trigger_to_pipeline = {
    for pair in flatten([
      for pname, pipeline in local.pipelines : [
        for idx, trigger in pipeline.triggers : {
          key   = "${pname}-${idx}"
          pname = pname
        }
      ]
    ]) : pair.key => pair.pname
  }
}

# KMS customer managed key for S3 bucket encryption
resource "aws_kms_key" "s3" {
  description             = "CMK for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# KMS alias uses name_prefix to avoid collisions with previously created aliases
resource "aws_kms_alias" "s3" {
  name_prefix   = "alias/s3-bucket-cmk-"
  target_key_id = aws_kms_key.s3.key_id
}

# Random suffix for bucket names
resource "random_id" "bucket_suffix" {
  for_each    = local.pipelines
  byte_length = 4
}

# S3 artifact buckets
resource "aws_s3_bucket" "artifact" {
  for_each      = local.pipelines
  bucket        = "artifacts-${each.key}-${random_id.bucket_suffix[each.key].hex}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact" {
  for_each                = local.pipelines
  bucket                  = aws_s3_bucket.artifact[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.artifact[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.artifact[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

# S3 build cache buckets
resource "aws_s3_bucket" "cache" {
  for_each      = local.pipelines
  bucket        = "cache-${each.key}-${random_id.bucket_suffix[each.key].hex}"
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cache" {
  for_each                = local.pipelines
  bucket                  = aws_s3_bucket.cache[each.key].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cache" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.cache[each.key].id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "cache" {
  for_each = local.pipelines
  bucket   = aws_s3_bucket.cache[each.key].id
  versioning_configuration {
    status = "Enabled"
  }
}

# CodeStar connections for GitHub, Bitbucket, or GitHub Enterprise Server sources
resource "aws_codestarconnections_connection" "github" {
  for_each = {
    for name, pipeline in local.pipelines :
    name => pipeline
    if pipeline.source.provider == "GitHub" || pipeline.source.provider == "Bitbucket" || pipeline.source.provider == "GitHubEnterpriseServer"
  }
  name          = "${each.key}-connection"
  provider_type = each.value.source.provider == "GitHubEnterpriseServer" ? "GitHubEnterpriseServer" : each.value.source.provider
  lifecycle {
    prevent_destroy = true
  }
}

# CodeStar host for GitHub Enterprise Server
resource "aws_codestarconnections_host" "ghes" {
  for_each = {
    for name, pipeline in local.pipelines :
    name => pipeline
    if pipeline.source.provider == "GitHubEnterpriseServer"
  }
  name              = "${each.key}-host"
  provider_endpoint = try(each.value.source.endpoint, "https://github.example.com")
  provider_type     = "GitHubEnterpriseServer"
  lifecycle {
    prevent_destroy = true
  }
}

# Default CodePipeline IAM role (if any pipeline does not specify a role_arn)
# name_prefix is used to avoid EntityAlreadyExists in shared/provisioned environments
resource "aws_iam_role" "codepipeline_default" {
  count = local.default_role_needed ? 1 : 0
  name_prefix = "codepipeline-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# IAM policy for default CodePipeline role
resource "aws_iam_policy" "codepipeline_default" {
  count = local.default_role_needed ? 1 : 0
  name_prefix = "codepipeline-default-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "codepipeline:*",
          "codecommit:*",
          "codebuild:*",
          "ecr:*"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = concat(
          [for b in aws_s3_bucket.artifact : b.arn],
          [for b in aws_s3_bucket.cache : b.arn],
          flatten([for b in aws_s3_bucket.artifact : ["${b.arn}/*"]]),
          flatten([for b in aws_s3_bucket.cache : ["${b.arn}/*"]])
        )
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "codepipeline_default" {
  count      = local.default_role_needed ? 1 : 0
  role       = aws_iam_role.codepipeline_default[0].name
  policy_arn = aws_iam_policy.codepipeline_default[0].arn
}

# Dedicated IAM role for CodeBuild
resource "aws_iam_role" "codebuild_default" {
  count = length(local.codebuild_projects) > 0 ? 1 : 0
  name_prefix = "codebuild-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "codebuild_default" {
  count = length(local.codebuild_projects) > 0 ? 1 : 0
  name_prefix = "codebuild-default-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = concat(
          [for b in aws_s3_bucket.artifact : b.arn],
          [for b in aws_s3_bucket.cache : b.arn],
          flatten([for b in aws_s3_bucket.artifact : ["${b.arn}/*"]]),
          flatten([for b in aws_s3_bucket.cache : ["${b.arn}/*"]])
        )
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "codebuild_default" {
  count      = length(local.codebuild_projects) > 0 ? 1 : 0
  role       = aws_iam_role.codebuild_default[0].name
  policy_arn = aws_iam_policy.codebuild_default[0].arn
}

# Dedicated IAM role for Lambda
resource "aws_iam_role" "lambda_default" {
  count = length(local.lambda_functions) > 0 ? 1 : 0
  name_prefix = "lambda-default-role-"
  path        = "/terraforest/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "lambda_default" {
  count      = length(local.lambda_functions) > 0 ? 1 : 0
  role       = aws_iam_role.lambda_default[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

# Inline CodeBuild projects
resource "aws_codebuild_project" "pipeline" {
  for_each     = local.codebuild_projects
  name         = each.value.name
  service_role = aws_iam_role.codebuild_default[0].arn

  source {
    type     = "CODEPIPELINE"
    buildspec = ""
  }

  artifacts {
    type = "CODEPIPELINE"
  }

  environment {
    compute_type               = each.value.compute
    image                      = each.value.image
    type                       = each.value.env_type
    image_pull_credentials_type = "CODEBUILD"
  }

  lifecycle {
    ignore_changes = [
      source[0].buildspec,
    ]
  }
}

# Import existing CodeBuild projects to prevent ResourceAlreadyExistsException
import {
  for_each = local.codebuild_projects
  to       = aws_codebuild_project.pipeline[each.key]
  id       = each.value.name
}

# Archive file for Lambda placeholder code
data "archive_file" "lambda" {
  for_each    = local.lambda_functions
  type        = "zip"
  output_path = "${path.module}/lambda-${each.key}.zip"
  source {
    content  = "def handler(event, context):\n    return {'statusCode': 200}"
    filename = "index.py"
  }
}

# Inline Lambda functions
resource "aws_lambda_function" "pipeline" {
  for_each         = local.lambda_functions
  function_name    = each.value.name
  handler          = "index.handler"
  runtime          = "python3.9"
  role             = aws_iam_role.lambda_default[0].arn
  filename         = data.archive_file.lambda[each.key].output_path
  source_code_hash = data.archive_file.lambda[each.key].output_base64sha256
  lifecycle {
    prevent_destroy = true
    ignore_changes = [
      source_code_hash,
      filename,
    ]
  }
}

# Import existing Lambda function to prevent ResourceConflictException
import {
  for_each = local.lambda_functions
  to       = aws_lambda_function.pipeline[each.key]
  id       = each.value.name
}

# CodePipeline resources
resource "aws_codepipeline" "pipeline" {
  for_each = local.pipelines
  name     = each.key
  role_arn = coalesce(each.value.role_arn, try(aws_iam_role.codepipeline_default[0].arn, null))

  artifact_store {
    location = aws_s3_bucket.artifact[each.key].id
    type     = "S3"
  }

  dynamic "stage" {
    for_each = each.value.stages
    content {
      name = stage.value.name
      dynamic "action" {
        for_each = stage.value.actions
        content {
          name     = action.value.name
          category = action.value.category
          owner    = action.value.owner
          provider = action.value.provider
          version  = action.value.version
          configuration = merge(
            action.value.provider == "CodeBuild" ? {} : action.value.configuration,
            action.value.provider == "CodeStarSourceConnection" ? {
              ConnectionArn = aws_codestarconnections_connection.github[each.key].arn
            } : {},
            action.value.provider == "CodeBuild" ? {
              ProjectName = aws_codebuild_project.pipeline[each.key].name
            } : {},
            action.value.provider == "Lambda" ? {
              FunctionName = aws_lambda_function.pipeline[each.key].function_name
            } : {}
          )
          output_artifacts = action.value.category == "Source" ? ["source_output"] : null
          input_artifacts  = action.value.provider == "CodeBuild" ? ["source_output"] : null
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# EventBridge IAM roles for each pipeline
resource "aws_iam_role" "eventbridge_pipeline" {
  for_each = local.pipelines
  name_prefix = "terrabits-${each.key}-"
  path        = "/"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_policy" "eventbridge_pipeline" {
  for_each = local.pipelines
  name_prefix = "terrabits-${each.key}-policy-"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.pipeline[each.key].arn
      }
    ]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "eventbridge_pipeline" {
  for_each = local.pipelines
  role       = aws_iam_role.eventbridge_pipeline[each.key].name
  policy_arn = aws_iam_policy.eventbridge_pipeline[each.key].arn
}

# EventBridge rules – one per trigger
resource "aws_cloudwatch_event_rule" "pipeline" {
  for_each = {
    for pair in flatten([
      for pname, pipeline in local.pipelines : [
        for idx, trigger in pipeline.triggers : {
          key      = "${pname}-${idx}"
          pname    = pname
          trigger  = trigger
        }
      ]
    ]) : pair.key => pair
  }
  name        = "${each.value.pname}-trigger-${index([for t in local.pipelines[each.value.pname].triggers : t], each.value.trigger)}"
  description = "EventBridge rule for pipeline ${each.value.pname} trigger"

  event_pattern = each.value.trigger.type == "branch" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    detail = {
      referenceType = ["branch"]
      referenceName = [each.value.trigger.branch]
    }
  }) : each.value.trigger.type == "tag" ? jsonencode({
    source      = ["aws.codecommit"]
    detail-type = ["CodeCommit Repository State Change"]
    detail = {
      referenceType = ["tag"]
      referenceName = [each.value.trigger.tag]
    }
  }) : each.value.trigger.type == "custom" ? each.value.trigger.pattern : null

  schedule_expression = each.value.trigger.type == "cron" ? each.value.trigger.expression : null
}

# EventBridge targets – one per rule
resource "aws_cloudwatch_event_target" "pipeline" {
  for_each = aws_cloudwatch_event_rule.pipeline
  rule     = each.value.name
  target_id = "target-${each.key}"
  arn       = aws_codepipeline.pipeline[local.trigger_to_pipeline[each.key]].arn
  role_arn  = aws_iam_role.eventbridge_pipeline[local.trigger_to_pipeline[each.key]].arn
}

# Data sources for KMS key policy and account root
data "aws_partition" "current" {}
data "aws_caller_identity" "current" {}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "server_name" {
  type        = string
  default     = "sftp-server"
  description = "Name for the SFTP server and associated resources"
}

variable "vpc_id" {
  type        = string
  default     = ""
  description = "VPC ID for VPC endpoint (empty for PUBLIC endpoint)"
}

variable "subnet_ids" {
  type        = list(string)
  default     = []
  description = "List of subnet IDs for mount targets and endpoint (if VPC)"
}

variable "allowed_cidr_blocks" {
  type        = list(string)
  default     = []
  description = "CIDR blocks allowed to connect to SFTP server over SSH (port 22)"
}

variable "is_public" {
  type        = bool
  default     = false
  description = "Whether to assign Elastic IPs to the SFTP server when using VPC endpoint"
}

variable "kms_key_id" {
  type        = string
  default     = ""
  description = "KMS key ID for EFS encryption (default AWS managed key if empty)"
}

variable "sftp_users" {
  type = map(object({
    username       = string
    uid            = number
    gid            = number
    ssh_public_key = optional(string, "")
    home_directory = optional(string, "")
    restricted     = optional(bool, false)
    iam_role_arn   = optional(string, "")
  }))
  default     = {}
  description = "Map of SFTP users with POSIX profile, SSH key, home directory, restricted flag, and optional IAM role ARN"
}

variable "additional_access_points" {
  type = map(object({
    path        = string
    uid         = number
    gid         = number
    permissions = optional(string, "0755")
  }))
  default     = {}
  description = "Additional EFS access points beyond user homes"
}

variable "logging_enabled" {
  type        = bool
  default     = false
  description = "Whether to enable CloudWatch logging for the SFTP server"
}

variable "efs_performance_mode" {
  type        = string
  default     = "generalPurpose"
  description = "EFS performance mode (generalPurpose or maxIO)"
}

data "aws_region" "current" {}
data "aws_caller_identity" "current" {}

locals {
  user_config = {
    for k, v in var.sftp_users : k => {
      username       = v.username
      uid            = v.uid
      gid            = v.gid
      ssh_public_key = v.ssh_public_key
      home_directory = v.home_directory != "" ? v.home_directory : "/${v.username}"
      restricted     = v.restricted
      iam_role_arn   = v.iam_role_arn
    }
  }
}

# EFS File System
resource "aws_efs_file_system" "this" {
  creation_token   = "${var.server_name}-efs"
  performance_mode = var.efs_performance_mode
  throughput_mode  = "bursting"
  encrypted        = true
  kms_key_id       = var.kms_key_id != "" ? var.kms_key_id : null

  tags = {
    Name = "${var.server_name}-efs"
  }
}

# EFS Mount Targets (only when VPC ID provided)
resource "aws_efs_mount_target" "this" {
  for_each = var.vpc_id != "" ? toset(var.subnet_ids) : toset([])

  file_system_id  = aws_efs_file_system.this.id
  subnet_id       = each.key
  security_groups = [aws_security_group.efs[0].id]
}

# Security Groups (only when VPC ID provided)
resource "aws_security_group" "sftp" {
  count = var.vpc_id != "" ? 1 : 0
  name   = "${var.server_name}-sftp-sg"
  vpc_id = var.vpc_id
  tags = {
    Name = "${var.server_name}-sftp-sg"
  }
}

resource "aws_security_group" "efs" {
  count = var.vpc_id != "" ? 1 : 0
  name   = "${var.server_name}-efs-sg"
  vpc_id = var.vpc_id
  tags = {
    Name = "${var.server_name}-efs-sg"
  }
}

# Security Group Rules
resource "aws_security_group_rule" "sftp_ingress" {
  count             = var.vpc_id != "" && length(var.allowed_cidr_blocks) > 0 ? 1 : 0
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = var.allowed_cidr_blocks
  security_group_id = aws_security_group.sftp[0].id
}

resource "aws_security_group_rule" "sftp_egress_to_efs" {
  count                    = var.vpc_id != "" ? 1 : 0
  type                     = "egress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.efs[0].id
  security_group_id        = aws_security_group.sftp[0].id
}

resource "aws_security_group_rule" "efs_ingress_from_sftp" {
  count                    = var.vpc_id != "" ? 1 : 0
  type                     = "ingress"
  from_port                = 2049
  to_port                  = 2049
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.sftp[0].id
  security_group_id        = aws_security_group.efs[0].id
}

resource "aws_security_group_rule" "efs_egress_all" {
  count = var.vpc_id != "" ? 1 : 0
  type              = "egress"
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.efs[0].id
}

# Elastic IPs (only when public and VPC)
resource "aws_eip" "sftp" {
  count = var.vpc_id != "" && var.is_public ? length(var.subnet_ids) : 0
  domain = "vpc"
  tags = {
    Name = "${var.server_name}-eip-${count.index}"
  }
}

# Transfer Server
resource "aws_transfer_server" "this" {
  domain                = "EFS"
  identity_provider_type = "SERVICE_MANAGED"
  security_policy_name  = "TransferSecurityPolicy-2023-05"
  endpoint_type         = var.vpc_id != "" ? "VPC" : "PUBLIC"

  dynamic "endpoint_details" {
    for_each = var.vpc_id != "" ? [1] : []
    content {
      vpc_id     = var.vpc_id
      subnet_ids = var.subnet_ids
      address_allocation_ids = var.is_public ? aws_eip.sftp[*].id : null
    }
  }

  logging_role = var.logging_enabled ? aws_iam_role.logging[0].arn : null

  tags = {
    Name = var.server_name
  }
}

# IAM Role for SFTP Users (single role for all users without custom ARN)
resource "aws_iam_role" "sftp_user" {
  name = "${var.server_name}-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sftp_user" {
  name        = "${var.server_name}-policy"
  description = "Policy for SFTP user to access EFS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Effect   = "Allow"
        Resource = aws_efs_file_system.this.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "sftp_user" {
  role       = aws_iam_role.sftp_user.name
  policy_arn = aws_iam_policy.sftp_user.arn
}

# SFTP Users
resource "aws_transfer_user" "this" {
  for_each = local.user_config

  server_id      = aws_transfer_server.this.id
  user_name      = each.value.username
  role           = each.value.iam_role_arn != "" ? each.value.iam_role_arn : aws_iam_role.sftp_user.arn
  home_directory_type = each.value.restricted ? "PATH" : "LOGICAL"
  home_directory  = each.value.home_directory
  posix_profile {
    uid = each.value.uid
    gid = each.value.gid
  }
}

# SSH Keys for Users with keys
resource "aws_transfer_ssh_key" "this" {
  for_each = {
    for k, v in local.user_config : k => v if v.ssh_public_key != ""
  }

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.key].user_name
  body      = each.value.ssh_public_key
}

# User-specific EFS Access Points
resource "aws_efs_access_point" "user" {
  for_each = local.user_config

  file_system_id = aws_efs_file_system.this.id
  root_directory {
    path = each.value.home_directory
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = "0755"
    }
  }
  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
}

# Additional EFS Access Points
resource "aws_efs_access_point" "additional" {
  for_each = var.additional_access_points

  file_system_id = aws_efs_file_system.this.id
  root_directory {
    path = each.value.path
    creation_info {
      owner_uid   = each.value.uid
      owner_gid   = each.value.gid
      permissions = each.value.permissions
    }
  }
  posix_user {
    uid = each.value.uid
    gid = each.value.gid
  }
}

# CloudWatch Logging Role and Policy
resource "aws_iam_role" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-logging-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "logging" {
  count = var.logging_enabled ? 1 : 0
  name  = "${var.server_name}-logging-policy"
  description = "Policy for SFTP server to write CloudWatch logs"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/transfer/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "logging" {
  count = var.logging_enabled ? 1 : 0
  role       = aws_iam_role.logging[0].name
  policy_arn = aws_iam_policy.logging[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Variables
variable "create_bucket" {
  description = "Whether to create the S3 bucket"
  type        = bool
  default     = true
}

variable "create_kms_key" {
  description = "Whether to create the default KMS key for SSE-KMS"
  type        = bool
  default     = true
}

variable "bucket" {
  description = "Explicit bucket name (overrides auto-generated name)"
  type        = string
  default     = null
}

variable "bucket_prefix" {
  description = "Prefix for auto-generated bucket name"
  type        = string
  default     = null
}

variable "force_destroy" {
  description = "Allow bucket to be destroyed even if non-empty"
  type        = bool
  default     = null
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "canned_acl" {
  description = "Canned ACL to apply to the bucket (e.g., private, public-read)"
  type        = string
  default     = null
}

variable "acl_grants" {
  description = "List of ACL grant blocks (each with id, type, permission)"
  type = list(object({
    id         = string
    type       = string
    permission = string
  }))
  default = []
}

variable "website" {
  description = "Static website hosting configuration"
  type = object({
    index_document = optional(string)
    error_document = optional(string)
    routing_rules  = optional(list(any))
  })
  default = null
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = null
}

variable "versioning" {
  description = "Versioning configuration (enabled or disabled)"
  type = object({
    enabled    = optional(bool)
    mfa_delete = optional(bool)
  })
  default = null
}

variable "logging" {
  description = "Access logging configuration (target bucket and prefix)"
  type = object({
    target_bucket = string
    target_prefix = optional(string)
  })
  default = null
}

variable "acceleration" {
  description = "Transfer acceleration status (true/false)"
  type        = bool
  default     = null
}

variable "requester_pays" {
  description = "Requester pays configuration (true/false)"
  type        = bool
  default     = null
}

variable "lifecycle_rules" {
  description = "List of lifecycle rule configurations"
  type = list(object({
    id                                     = optional(string)
    status                                 = optional(string)
    prefix                                 = optional(string)
    expiration                             = optional(map(string))
    transition                             = optional(list(map(string)))
    noncurrent_version_expiration          = optional(map(string))
    noncurrent_version_transition          = optional(list(map(string)))
    abort_incomplete_multipart_upload_days = optional(number)
    filter                                 = optional(map(string))
  }))
  default = null
}

variable "replication" {
  description = "Cross-region replication configuration"
  type = object({
    role_arn              = optional(string)
    rules                 = list(any)
    destination_bucket_arn = string
  })
  default = null
}

variable "intelligent_tiering" {
  description = "Map of intelligent tiering configurations"
  type = map(object({
    status = optional(string)
    filter = optional(map(string))
    tiering = list(object({
      access_tier = string
      days        = number
    }))
  }))
  default = {}
}

variable "object_ownership" {
  description = "Object ownership control (e.g., ObjectWriter, BucketOwnerPreferred)"
  type        = string
  default     = "ObjectWriter"
}

variable "encryption" {
  description = "Custom encryption configuration (overrides default KMS)"
  type = object({
    sse_algorithm     = string
    kms_master_key_id = optional(string)
  })
  default = null
}

variable "object_lock_configuration" {
  description = "Object lock configuration with default retention"
  type = object({
    object_lock_enabled = string
    rule = optional(object({
      default_retention = object({
        mode  = string
        days  = optional(number)
        years = optional(number)
      })
    }))
  })
  default = null
}

# Policy toggles
variable "attach_elb_log_delivery_policy" {
  description = "Attach policy granting ELB log delivery"
  type        = bool
  default     = false
}

variable "elb_log_delivery_source_arns" {
  description = "List of ELB ARNs allowed to deliver logs"
  type        = list(string)
  default     = []
}

variable "attach_alb_log_delivery_policy" {
  description = "Attach policy granting ALB/NLB log delivery"
  type        = bool
  default     = false
}

variable "alb_log_delivery_source_arns" {
  description = "List of ALB/NLB ARNs allowed to deliver logs"
  type        = list(string)
  default     = []
}

variable "deny_insecure_transport" {
  description = "Deny requests without secure transport"
  type        = bool
  default     = false
}

variable "deny_old_tls" {
  description = "Deny requests using TLS versions older than 1.2"
  type        = bool
  default     = false
}

variable "attach_policy_json" {
  description = "Attach a user-supplied JSON policy"
  type        = bool
  default     = false
}

variable "policy_json" {
  description = "User-supplied JSON policy document"
  type        = string
  default     = null
}

# Locals
locals {
  create_bucket = var.create_bucket
  create_kms    = var.create_kms_key && var.create_bucket

  # Bucket name logic
  bucket_name = var.bucket != null ? var.bucket : (
    var.bucket_prefix != null ? "${var.bucket_prefix}${random_pet.this[0].id}" : random_pet.this[0].id
  )

  force_destroy = coalesce(var.force_destroy, false)

  # Determine if any policy toggle is enabled
  enable_policy = var.attach_elb_log_delivery_policy || var.attach_alb_log_delivery_policy || var.deny_insecure_transport || var.deny_old_tls || var.attach_policy_json

  # Replication role creation
  create_replication_role = var.replication != null && var.replication.role_arn == null
}

# Random pet for bucket name
resource "random_pet" "this" {
  count = var.create_bucket && var.bucket == null && var.bucket_prefix == null ? 1 : 0
  length = 2
}

# KMS Key
resource "aws_kms_key" "this" {
  count                    = local.create_kms ? 1 : 0
  description             = "S3 bucket encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  tags                    = var.tags
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  count         = local.create_kms ? 1 : 0
  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

# S3 Bucket
resource "aws_s3_bucket" "this" {
  count         = local.create_bucket ? 1 : 0
  bucket        = local.bucket_name
  force_destroy = local.force_destroy
  tags          = var.tags
}

# Public Access Block
resource "aws_s3_bucket_public_access_block" "this" {
  count = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_bucket_policy.this]
}

# Ownership Controls
resource "aws_s3_bucket_ownership_controls" "this" {
  count = local.create_bucket && var.object_ownership != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    object_ownership = var.object_ownership
  }

  depends_on = [aws_s3_bucket_policy.this]
}

# Default Encryption (SSE-KMS or custom)
resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = local.create_bucket ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = var.encryption != null ? var.encryption.sse_algorithm : "aws:kms"
      kms_master_key_id = var.encryption != null ? var.encryption.kms_master_key_id : (local.create_kms ? aws_kms_key.this[0].arn : null)
    }
  }
}

# ACL
resource "aws_s3_bucket_acl" "this" {
  count = local.create_bucket && (var.canned_acl != null || length(var.acl_grants) > 0) ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  acl    = var.canned_acl

  dynamic "access_control_policy" {
    for_each = length(var.acl_grants) > 0 ? [1] : []
    content {
      dynamic "grant" {
        for_each = var.acl_grants
        content {
          grantee {
            id   = grant.value.id
            type = grant.value.type
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.this.account_id
      }
    }
  }
}

# Website
resource "aws_s3_bucket_website_configuration" "this" {
  count = local.create_bucket && var.website != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  index_document {
    suffix = var.website.index_document
  }
  error_document {
    key = var.website.error_document
  }
  dynamic "routing_rule" {
    for_each = var.website.routing_rules != null ? var.website.routing_rules : []
    content {
      condition {
        key_prefix_equals = routing_rule.value.condition.key_prefix_equals
        http_error_code_returned_equals = routing_rule.value.condition.http_error_code_returned_equals
      }
      redirect {
        protocol         = routing_rule.value.redirect.protocol
        host_name        = routing_rule.value.redirect.host_name
        http_redirect_code = routing_rule.value.redirect.http_redirect_code
        replace_key_prefix_with = routing_rule.value.redirect.replace_key_prefix_with
        replace_key_with = routing_rule.value.redirect.replace_key_with
      }
    }
  }
}

# CORS
resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.create_bucket && var.cors_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# Versioning
resource "aws_s3_bucket_versioning" "this" {
  count = local.create_bucket && var.versioning != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  versioning_configuration {
    status     = var.versioning.enabled ? "Enabled" : "Suspended"
    mfa_delete = var.versioning.mfa_delete ? "Enabled" : "Disabled"
  }
}

# Logging
resource "aws_s3_bucket_logging" "this" {
  count = local.create_bucket && var.logging != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

# Acceleration
resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = local.create_bucket && var.acceleration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  status = var.acceleration ? "Enabled" : "Suspended"
}

# Requester Pays
resource "aws_s3_bucket_request_payment_configuration" "this" {
  count = local.create_bucket && var.requester_pays != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  payer = var.requester_pays ? "Requester" : "BucketOwner"
}

# Lifecycle
resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.create_bucket && var.lifecycle_rules != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status
      prefix = rule.value.prefix

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days = try(noncurrent_version_expiration.value.noncurrent_days, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = try(noncurrent_version_transition.value.noncurrent_days, null)
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)
        }
      }
    }
  }
}

# Replication
resource "aws_iam_role" "replication" {
  count = local.create_bucket && var.replication != null && local.create_replication_role ? 1 : 0
  name  = "s3-replication-${local.bucket_name}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  count = local.create_bucket && var.replication != null && local.create_replication_role ? 1 : 0
  name  = "s3-replication-${local.bucket_name}"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.this[0].arn,
          "${aws_s3_bucket.this[0].arn}/*"
        ]
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.this[0].arn}/*"
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = "${var.replication.destination_bucket_arn}/*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = local.create_bucket && var.replication != null && local.create_replication_role ? 1 : 0
  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.create_bucket && var.replication != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  role   = var.replication.role_arn != null ? var.replication.role_arn : aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication.rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = rule.value.priority

      filter {
        prefix = rule.value.filter.prefix
      }

      destination {
        bucket        = var.replication.destination_bucket_arn
        storage_class = rule.value.destination.storage_class
        encryption_configuration {
          replica_kms_key_id = rule.value.destination.replica_kms_key_id
        }
        access_control_translation {
          owner = rule.value.destination.access_control_translation.owner
        }
      }

      delete_marker_replication {
        status = rule.value.delete_marker_replication.status
      }

      source_selection_criteria {
        sse_kms_encrypted_objects {
          status = rule.value.source_selection_criteria.sse_kms_encrypted_objects.status
        }
      }

      existing_object_replication {
        status = rule.value.existing_object_replication.status
      }
    }
  }
}

# Intelligent Tiering
resource "aws_s3_bucket_intelligent_tiering_configuration" "this" {
  for_each = local.create_bucket ? var.intelligent_tiering : {}
  bucket = aws_s3_bucket.this[0].id
  name   = each.key

  dynamic "filter" {
    for_each = each.value.filter != null ? [each.value.filter] : []
    content {
      prefix = try(filter.value.prefix, null)
    }
  }

  dynamic "tiering" {
    for_each = each.value.tiering
    content {
      access_tier = tiering.value.access_tier
      days        = tiering.value.days
    }
  }
}

# Object Lock
resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = local.create_bucket && var.object_lock_configuration != null ? 1 : 0
  bucket = aws_s3_bucket.this[0].id

  object_lock_enabled = var.object_lock_configuration.object_lock_enabled

  dynamic "rule" {
    for_each = var.object_lock_configuration.rule != null ? [var.object_lock_configuration.rule] : []
    content {
      default_retention {
        mode  = rule.value.default_retention.mode
        days  = rule.value.default_retention.days
        years = rule.value.default_retention.years
      }
    }
  }
}

# Bucket Policy
data "aws_iam_policy_document" "combined" {
  count = local.create_bucket && local.enable_policy ? 1 : 0

  # ELB log delivery
  dynamic "statement" {
    for_each = var.attach_elb_log_delivery_policy ? [1] : []
    content {
      sid    = "ELBLogDelivery"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["elasticloadbalancing.amazonaws.com"]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "StringEquals"
        variable = "aws:SourceArn"
        values   = var.elb_log_delivery_source_arns
      }
    }
  }

  # ALB/NLB log delivery
  dynamic "statement" {
    for_each = var.attach_alb_log_delivery_policy ? [1] : []
    content {
      sid    = "ALBLogDelivery"
      effect = "Allow"
      principals {
        type        = "Service"
        identifiers = ["delivery.logs.amazonaws.com"]
      }
      actions   = ["s3:PutObject"]
      resources = ["${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "StringEquals"
        variable = "aws:SourceArn"
        values   = var.alb_log_delivery_source_arns
      }
    }
  }

  # Deny insecure transport
  dynamic "statement" {
    for_each = var.deny_insecure_transport ? [1] : []
    content {
      sid    = "DenyInsecureTransport"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["false"]
      }
    }
  }

  # Deny old TLS
  dynamic "statement" {
    for_each = var.deny_old_tls ? [1] : []
    content {
      sid    = "DenyOldTLS"
      effect = "Deny"
      principals {
        type        = "*"
        identifiers = ["*"]
      }
      actions   = ["s3:*"]
      resources = [aws_s3_bucket.this[0].arn, "${aws_s3_bucket.this[0].arn}/*"]
      condition {
        test     = "NumericLessThan"
        variable = "s3:TlsVersion"
        values   = ["1.2"]
      }
      condition {
        test     = "Bool"
        variable = "aws:SecureTransport"
        values   = ["true"]
      }
    }
  }

  # User-supplied JSON policy
  source_policy_documents = var.attach_policy_json && var.policy_json != null ? [var.policy_json] : []
}

resource "aws_s3_bucket_policy" "this" {
  count = local.create_bucket && local.enable_policy ? 1 : 0
  bucket = aws_s3_bucket.this[0].id
  policy = data.aws_iam_policy_document.combined[0].json
}

# Data sources
data "aws_caller_identity" "this" {}

# Outputs
output "bucket_id" {
  description = "The name of the S3 bucket"
  value       = local.create_bucket ? aws_s3_bucket.this[0].id : null
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = local.create_bucket ? aws_s3_bucket.this[0].arn : null
}

output "bucket_domain_name" {
  description = "The bucket domain name"
  value       = local.create_bucket ? aws_s3_bucket.this[0].bucket_domain_name : null
}

output "kms_key_arn" {
  description = "The ARN of the KMS key (if created)"
  value       = local.create_kms ? aws_kms_key.this[0].arn : null
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "target_stack" {
  type    = string
  default = "benchmark"
}

variable "stack_githash" {
  type    = string
  default = "benchmark0000"
}

variable "stack_githash_long" {
  type    = string
  default = "benchmark0000000000000000000000000000000000000000"
}

variable "stack_s3_bucket" {
  type    = string
  default = "benchmark-stack-bucket"
}

variable "dataset_s3_object_key" {
  type    = string
  default = "dataset.csv"
}

variable "destigmatized_dataset_s3_object_key" {
  type    = string
  default = "destigmatized_dataset.csv"
}

variable "genomic_dataset_s3_object_key" {
  type    = string
  default = "genomic_dataset.csv"
}

locals {
  role_prefixes = [
    "wildfly-deployment-s3",
    "httpd-deployment-s3",
    "auth-hpds-deployment-s3",
    "open-hpds-deployment-s3",
    "dictionary-deployment-s3"
  ]
}

data "aws_iam_policy_document" "assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "inline" {
  for_each = toset(local.role_prefixes)

  statement {
    sid       = "EC2CreateTags"
    effect    = "Allow"
    actions   = ["ec2:CreateTags"]
    resources = ["arn:aws:ec2:*:*:instance/*"]
  }

  statement {
    sid       = "CloudWatchPutMetricData"
    effect    = "Allow"
    actions   = ["cloudwatch:PutMetricData"]
    resources = ["*"]
  }

  statement {
    sid       = "S3ListBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = ["arn:aws:s3:::${var.stack_s3_bucket}"]
  }

  statement {
    sid       = "S3GetObjectTier"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = [
      "arn:aws:s3:::${var.stack_s3_bucket}/${each.key}/*",
      "arn:aws:s3:::${var.stack_s3_bucket}/common-security-tools/*"
    ]
  }

  statement {
    sid       = "S3GetObjectDatasets"
    effect    = "Allow"
    actions   = ["s3:GetObject"]
    resources = [
      "arn:aws:s3:::${var.stack_s3_bucket}/${var.dataset_s3_object_key}",
      "arn:aws:s3:::${var.stack_s3_bucket}/${var.destigmatized_dataset_s3_object_key}",
      "arn:aws:s3:::${var.stack_s3_bucket}/${var.genomic_dataset_s3_object_key}"
    ]
  }
}

resource "aws_iam_role" "this" {
  for_each          = toset(local.role_prefixes)
  name              = "${each.key}-${var.target_stack}-${var.stack_githash}"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json
}

resource "aws_iam_instance_profile" "this" {
  for_each = aws_iam_role.this
  name     = each.value.name
  role     = each.value.name
}

resource "aws_iam_role_policy_attachment" "cloudwatch" {
  for_each   = aws_iam_role.this
  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "ssm" {
  for_each   = aws_iam_role.this
  role       = each.value.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy" "inline" {
  for_each = aws_iam_role.this
  name     = "${each.value.name}-inline"
  role     = each.value.name
  policy   = data.aws_iam_policy_document.inline[each.key].json
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region
}

# Variables
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "create_module" {
  description = "Toggle to create all resources in this module"
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "Whether to create a new security group (true) or use an existing one (false)"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID where the security group will reside. If null and a new security group is created, a VPC will be auto-created."
  type        = string
  default     = null
}

variable "vpc_cidr_block" {
  description = "CIDR block for the auto-created VPC (only used when vpc_id is null and a new security group is created)"
  type        = string
  default     = "10.0.0.0/16"
}

variable "existing_sg_id" {
  description = "Existing security group ID when create_new_sg is false"
  type        = string
  default     = ""

  validation {
    condition     = var.create_new_sg || (var.create_module && length(var.existing_sg_id) > 0)
    error_message = "existing_sg_id must be provided when create_new_sg is false and create_module is true."
  }
}

variable "sg_name" {
  description = "Name of the security group"
  type        = string
  default     = "terraform-sg"
}

variable "revoke_rules_on_delete" {
  description = "Whether to revoke rules on security group delete"
  type        = bool
  default     = true
}

variable "create_before_destroy" {
  description = "Whether to use create_before_destroy lifecycle on the security group"
  type        = bool
  default     = true
}

variable "ingress_rules_new" {
  description = "Ingress rules for the newly created security group"
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules_new : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_new" {
  description = <<-EOT
    Egress rules for the newly created security group.
    IMPORTANT: No default egress rule is created. If this list is empty, outbound traffic
    will be blocked by default. You must provide at least one egress rule to allow
    outbound traffic (e.g., [{ protocol = "-1", from_port = 0, to_port = 0, cidr_ipv4 = "0.0.0.0/0" }]).
  EOT
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules_new : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "ingress_rules_existing" {
  description = "Ingress rules for the existing security group"
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules_existing : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each ingress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "egress_rules_existing" {
  description = <<-EOT
    Egress rules for the existing security group.
    IMPORTANT: No default egress rule is created. If this list is empty, outbound traffic
    will be blocked by default. You must provide at least one egress rule to allow
    outbound traffic (e.g., [{ protocol = "-1", from_port = 0, to_port = 0, cidr_ipv4 = "0.0.0.0/0" }]).
  EOT
  type = list(object({
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
    description              = optional(string)
    protocol                 = string
    from_port                = number
    to_port                  = number
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.egress_rules_existing : (
        (rule.cidr_ipv4 != null ? 1 : 0) +
        (rule.cidr_ipv6 != null ? 1 : 0) +
        (rule.source_security_group_id != null ? 1 : 0) +
        (rule.prefix_list_id != null ? 1 : 0) == 1
      )
    ])
    error_message = "Each egress rule must specify exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id, or prefix_list_id."
  }
}

variable "create_prefix_list" {
  description = "Whether to create an AWS-managed prefix list"
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the managed prefix list"
  type        = string
  default     = ""
}

variable "address_family" {
  description = "Address family for the prefix list (IPv4 or IPv6)"
  type        = string
  default     = "IPv4"
}

variable "max_entries" {
  description = "Maximum number of entries for the prefix list"
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "List of entries for the prefix list"
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

variable "existing_prefix_list_ids" {
  description = "List of existing prefix list IDs to use instead of creating a new one"
  type        = list(string)
  default     = []
}

# Locals
locals {
  # Auto-create a VPC only when: module is enabled, a new SG is created, and no vpc_id is supplied
  create_vpc = var.create_module && var.create_new_sg && var.vpc_id == null

  # Select the VPC ID: use user-supplied value, or the auto-created VPC, or null (for existing-group-only paths)
  vpc_id = var.create_module && var.create_new_sg ? (
    var.vpc_id != null ? var.vpc_id : aws_vpc.this[0].id
  ) : null

  # SG ID for the new security group
  sg_id = var.create_module && var.create_new_sg ? (
    var.create_before_destroy ? aws_security_group.this_cbd_true[0].id : aws_security_group.this_cbd_false[0].id
  ) : null
}

# Auto-created VPC for greenfield deployments
resource "aws_vpc" "this" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.sg_name != "" ? "${var.sg_name}-vpc" : "terraform-vpc"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Security Group (new) - with create_before_destroy = true
resource "aws_security_group" "this_cbd_true" {
  count = var.create_module && var.create_new_sg && var.create_before_destroy ? 1 : 0

  name        = var.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id

  tags = {
    Name = var.sg_name
  }

  lifecycle {
    create_before_destroy = true
    ignore_changes        = [description, name]
  }

  revoke_rules_on_delete = var.revoke_rules_on_delete
}

# Security Group (new) - with create_before_destroy = false
resource "aws_security_group" "this_cbd_false" {
  count = var.create_module && var.create_new_sg && !var.create_before_destroy ? 1 : 0

  name        = var.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id

  tags = {
    Name = var.sg_name
  }

  lifecycle {
    create_before_destroy = false
    ignore_changes        = [description, name]
  }

  revoke_rules_on_delete = var.revoke_rules_on_delete
}

# Ingress rules for new SG
resource "aws_security_group_rule" "ingress_new" {
  count = var.create_module && var.create_new_sg ? length(var.ingress_rules_new) : 0

  security_group_id = local.sg_id
  type              = "ingress"
  protocol          = var.ingress_rules_new[count.index].protocol
  from_port         = var.ingress_rules_new[count.index].from_port
  to_port           = var.ingress_rules_new[count.index].to_port
  description       = var.ingress_rules_new[count.index].description

  cidr_blocks              = var.ingress_rules_new[count.index].cidr_ipv4 != null ? [var.ingress_rules_new[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.ingress_rules_new[count.index].cidr_ipv6 != null ? [var.ingress_rules_new[count.index].cidr_ipv6] : null
  source_security_group_id = var.ingress_rules_new[count.index].source_security_group_id
  prefix_list_ids          = var.ingress_rules_new[count.index].prefix_list_id != null ? [var.ingress_rules_new[count.index].prefix_list_id] : null
}

# Egress rules for new SG
resource "aws_security_group_rule" "egress_new" {
  count = var.create_module && var.create_new_sg ? length(var.egress_rules_new) : 0

  security_group_id = local.sg_id
  type              = "egress"
  protocol          = var.egress_rules_new[count.index].protocol
  from_port         = var.egress_rules_new[count.index].from_port
  to_port           = var.egress_rules_new[count.index].to_port
  description       = var.egress_rules_new[count.index].description

  cidr_blocks              = var.egress_rules_new[count.index].cidr_ipv4 != null ? [var.egress_rules_new[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.egress_rules_new[count.index].cidr_ipv6 != null ? [var.egress_rules_new[count.index].cidr_ipv6] : null
  source_security_group_id = var.egress_rules_new[count.index].source_security_group_id
  prefix_list_ids          = var.egress_rules_new[count.index].prefix_list_id != null ? [var.egress_rules_new[count.index].prefix_list_id] : null
}

# Ingress rules for existing SG
resource "aws_security_group_rule" "ingress_existing" {
  count = var.create_module && !var.create_new_sg ? length(var.ingress_rules_existing) : 0

  security_group_id = var.existing_sg_id
  type              = "ingress"
  protocol          = var.ingress_rules_existing[count.index].protocol
  from_port         = var.ingress_rules_existing[count.index].from_port
  to_port           = var.ingress_rules_existing[count.index].to_port
  description       = var.ingress_rules_existing[count.index].description

  cidr_blocks              = var.ingress_rules_existing[count.index].cidr_ipv4 != null ? [var.ingress_rules_existing[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.ingress_rules_existing[count.index].cidr_ipv6 != null ? [var.ingress_rules_existing[count.index].cidr_ipv6] : null
  source_security_group_id = var.ingress_rules_existing[count.index].source_security_group_id
  prefix_list_ids          = var.ingress_rules_existing[count.index].prefix_list_id != null ? [var.ingress_rules_existing[count.index].prefix_list_id] : null
}

# Egress rules for existing SG
resource "aws_security_group_rule" "egress_existing" {
  count = var.create_module && !var.create_new_sg ? length(var.egress_rules_existing) : 0

  security_group_id = var.existing_sg_id
  type              = "egress"
  protocol          = var.egress_rules_existing[count.index].protocol
  from_port         = var.egress_rules_existing[count.index].from_port
  to_port           = var.egress_rules_existing[count.index].to_port
  description       = var.egress_rules_existing[count.index].description

  cidr_blocks              = var.egress_rules_existing[count.index].cidr_ipv4 != null ? [var.egress_rules_existing[count.index].cidr_ipv4] : null
  ipv6_cidr_blocks         = var.egress_rules_existing[count.index].cidr_ipv6 != null ? [var.egress_rules_existing[count.index].cidr_ipv6] : null
  source_security_group_id = var.egress_rules_existing[count.index].source_security_group_id
  prefix_list_ids          = var.egress_rules_existing[count.index].prefix_list_id != null ? [var.egress_rules_existing[count.index].prefix_list_id] : null
}

# Managed Prefix List
resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = var.prefix_list_name
  address_family = var.address_family
  max_entries    = var.max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }
}

# Outputs
output "sg_id" {
  description = "ID of the security group (created or existing)"
  value = var.create_module ? (
    var.create_new_sg ? local.sg_id : var.existing_sg_id
  ) : null
}

output "vpc_id" {
  description = "VPC ID (auto-created or user-supplied) used by the security group"
  value = var.create_module && var.create_new_sg ? local.vpc_id : null
}

output "prefix_list_id" {
  description = "ID of the created prefix list, if any"
  value = var.create_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? (
    aws_ec2_managed_prefix_list.this[0].id
  ) : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "project" {
  type    = string
  default = "Cv-React-App"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "ec2_codedeploy" {
  name = "AmazonEC2RoleforAWSCodeDeploy"
}

data "aws_iam_policy" "ec2_full" {
  name = "AmazonEC2FullAccess"
}

data "aws_iam_policy" "codedeploy_service" {
  name = "AWSCodeDeployRole"
}

data "aws_iam_policy" "cloudwatch_agent" {
  name = "CloudWatchAgentServerPolicy"
}

# Customer managed key for S3 encryption
resource "aws_kms_key" "artifacts_key" {
  description             = "KMS key for ${var.project} artifacts bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# S3 Artifact Bucket
resource "aws_s3_bucket" "artifacts" {
  bucket        = lower("${var.project}-codepipeline-artifacts")
  force_destroy = false
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts_key.arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket                  = aws_s3_bucket.artifacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Custom S3 artifact access policy (replaces AmazonS3FullAccess for all roles)
data "aws_iam_policy_document" "artifact_s3_access" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:DeleteObject"
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*"
    ]
  }
}

resource "aws_iam_policy" "artifact_s3_access" {
  name        = "${var.project}-artifact-s3-access"
  description = "Grant specific S3 actions on the artifact bucket"
  policy      = data.aws_iam_policy_document.artifact_s3_access.json
}

# EC2 CodeDeploy Role
resource "aws_iam_role" "ec2_codedeploy_role" {
  name               = "${var.project}_ec2_codedeploy_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json
}

data "aws_iam_policy_document" "ec2_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_attach_ec2codedeploy" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = data.aws_iam_policy.ec2_codedeploy.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_attach_ec2full" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = data.aws_iam_policy.ec2_full.arn
}

resource "aws_iam_role_policy_attachment" "ec2_codedeploy_attach_artifact_s3" {
  role       = aws_iam_role.ec2_codedeploy_role.name
  policy_arn = aws_iam_policy.artifact_s3_access.arn
}

resource "aws_iam_instance_profile" "ec2_codedeploy_instance_profile" {
  name = "${var.project}_ec2_codedeploy_instance_profile"
  role = aws_iam_role.ec2_codedeploy_role.name
}

# CodeDeploy Service Role
resource "aws_iam_role" "codedeploy_service_role" {
  name               = "${var.project}_codedeploy_service_role"
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume.json
}

data "aws_iam_policy_document" "codedeploy_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["codedeploy.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_attach_codedeployrole" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = data.aws_iam_policy.codedeploy_service.arn
}

resource "aws_iam_role_policy_attachment" "codedeploy_service_attach_artifact_s3" {
  role       = aws_iam_role.codedeploy_service_role.name
  policy_arn = aws_iam_policy.artifact_s3_access.arn
}

# EC2 CloudWatch Agent Role
resource "aws_iam_role" "ec2_cloudwatch_agent_role" {
  name               = "${var.project}_ec2_cloudwatch_agent_role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume.json
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_attach_cloudwatchagent" {
  role       = aws_iam_role.ec2_cloudwatch_agent_role.name
  policy_arn = data.aws_iam_policy.cloudwatch_agent.arn
}

resource "aws_iam_role_policy_attachment" "cloudwatch_agent_attach_artifact_s3" {
  role       = aws_iam_role.ec2_cloudwatch_agent_role.name
  policy_arn = aws_iam_policy.artifact_s3_access.arn
}

resource "aws_iam_instance_profile" "ec2_cloudwatch_agent_instance_profile" {
  name = "${var.project}_ec2_cloudwatch_agent_instance_profile"
  role = aws_iam_role.ec2_cloudwatch_agent_role.name
}

# CodeBuild Role
resource "aws_iam_role" "codebuild_role" {
  name               = "CodeBuildRole"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json
}

data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# CodeBuild inline policy includes S3, logs, and report actions
data "aws_iam_policy_document" "codebuild_inline" {
  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*"
    ]
  }
  statement {
    effect = "Allow"
    actions = [
      "codebuild:CreateReport",
      "codebuild:UpdateReport",
      "codebuild:BatchPutTestCases",
      "codebuild:CreateReportGroup",
      "codebuild:UpdateReportGroup"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild_inline_policy" {
  name   = "CodeBuildInlinePolicy"
  role   = aws_iam_role.codebuild_role.name
  policy = data.aws_iam_policy_document.codebuild_inline.json
}

# CodePipeline Role
resource "aws_iam_role" "codepipeline_role" {
  name               = "CodePipelineRole"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json
}

data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = [
        "codepipeline.amazonaws.com",
        "codebuild.amazonaws.com",
        "codedeploy.amazonaws.com",
        "s3.amazonaws.com"
      ]
    }
    actions = ["sts:AssumeRole"]
  }
  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "codepipeline_inline" {
  statement {
    effect = "Allow"
    actions = [
      "codestar-connections:*",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetBucketVersioning",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "codecommit:*",
      "codedeploy:*",
      "lambda:*",
      "codebuild:*",
      "cloudformation:*"
    ]
    resources = ["*"]
  }
  # Restrict S3 actions to the artifact bucket only
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:PutObjectAcl",
      "s3:GetBucketLocation",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.artifacts.arn,
      "${aws_s3_bucket.artifacts.arn}/*"
    ]
  }
  # Allow pass role for pipeline execution roles
  statement {
    effect = "Allow"
    actions = ["iam:PassRole"]
    resources = [
      aws_iam_role.ec2_codedeploy_role.arn,
      aws_iam_role.codedeploy_service_role.arn,
      aws_iam_role.ec2_cloudwatch_agent_role.arn,
      aws_iam_role.codebuild_role.arn
    ]
  }
}

resource "aws_iam_role_policy" "codepipeline_inline_policy" {
  name   = "CodePipelineInlinePolicy"
  role   = aws_iam_role.codepipeline_role.name
  policy = data.aws_iam_policy_document.codepipeline_inline.json
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "dev"
}

locals {
  common_tags = {
    Environment = var.environment
  }
}

# DynamoDB Tables

resource "aws_dynamodb_table" "near_app_actions_mapping" {
  name         = "near-app-actions-mapping"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-app-actions-mapping" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-app-actions-master" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_categories" {
  name         = "near-app-categories"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "categoryId"

  attribute {
    name = "categoryId"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-app-categories" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_apps" {
  name         = "near-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "appId"

  attribute {
    name = "appId"
    type = "S"
  }

  attribute {
    name = "categoryId"
    type = "S"
  }

  global_secondary_index {
    name            = "categoryId-Index"
    hash_key        = "categoryId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, { Name = "near-apps" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_connected_apps" {
  name         = "near-connected-apps"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "connectionId"

  attribute {
    name = "connectionId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "appId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "appId-Index"
    hash_key        = "appId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, { Name = "near-connected-apps" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_contacts" {
  name         = "near-contacts"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "contactId"

  attribute {
    name = "contactId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-contactId-index"
    hash_key        = "userId"
    range_key       = "contactId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, { Name = "near-contacts" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_fiat_tokens" {
  name         = "near-fiat-tokens"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "symbol"

  attribute {
    name = "symbol"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-fiat-tokens" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_files_invitations" {
  name             = "near-files-invitations"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "pk"
  range_key        = "sk"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"
  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  attribute {
    name = "pk"
    type = "S"
  }

  attribute {
    name = "sk"
    type = "S"
  }

  tags = merge(local.common_tags, { Name = "near-files-invitations" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_files" {
  name             = "near-files"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "walletId"
  range_key        = "fileId"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"
  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "fileId"
    type = "S"
  }

  attribute {
    name = "ownerId"
    type = "S"
  }

  attribute {
    name = "hash"
    type = "S"
  }

  global_secondary_index {
    name            = "ownerId-walletId-index"
    hash_key        = "ownerId"
    range_key       = "walletId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "hash-index"
    hash_key        = "hash"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "ownerId-fileId-index"
    hash_key        = "ownerId"
    range_key       = "fileId"
    projection_type = "ALL"
  }

  tags = merge(local.common_tags, { Name = "near-files" })

  lifecycle {
    prevent_destroy = true
