terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.50.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

variable "admin_cidr_block" {
  description = "CIDR block allowed for SSH access"
  type        = string
  default     = "10.0.0.0/32"
}

variable "bucket_suffix" {
  description = "Unique suffix for the FIS log bucket"
  type        = string
  default     = "chaos"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ecs_optimized" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-ecs-hvm-*-x86_64-ebs"]
  }
}

data "aws_caller_identity" "current" {}

data "aws_vpc" "main" {
  default = true
}

data "aws_subnet" "public" {
  vpc_id            = data.aws_vpc.main.id
  availability_zone = data.aws_availability_zones.available.names[0]
}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

locals {
  bucket_name = "fis-experiment-logs-${var.bucket_suffix}-${random_id.bucket_suffix.hex}"
}

resource "aws_security_group" "ec2" {
  name        = "chaos-ec2-sg"
  description = "Security group for EC2 instances"
  vpc_id      = data.aws_vpc.main.id

  ingress {
    description = "SSH from admin"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [data.aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "chaos-ec2-sg"
  }
}

resource "tls_private_key" "chaos" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "chaos" {
  key_name_prefix = "chaos-key-"
  public_key      = tls_private_key.chaos.public_key_openssh
}

resource "aws_iam_role" "ec2" {
  name_prefix = "chaos-ec2-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ssm" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy_attachment" "ec2_ecs" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceforEC2Role"
}

resource "aws_iam_instance_profile" "ec2" {
  name_prefix = "chaos-ec2-instance-profile-"
  role        = aws_iam_role.ec2.name
}

resource "aws_launch_template" "chaos" {
  name_prefix   = "chaos-"
  image_id      = data.aws_ami.ecs_optimized.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.chaos.key_name

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.ec2.id]
    subnet_id                   = data.aws_subnet.public.id
  }

  iam_instance_profile {
    arn = aws_iam_instance_profile.ec2.arn
  }

  metadata_options {
    http_tokens = "required"
  }

  block_device_mappings {
    device_name = "/dev/xvda"
    ebs {
      volume_size           = 30
      volume_type           = "gp3"
      delete_on_termination = true
    }
  }

  tag_specifications {
    resource_type = "instance"
    tags = {
      "FIS:Target" = "chaos"
      Name         = "chaos-instance"
    }
  }

  tag_specifications {
    resource_type = "volume"
    tags = {
      "FIS:Target" = "chaos"
      Name         = "chaos-volume"
    }
  }

  user_data = base64encode(<<EOF
#!/bin/bash
echo "ECS_CLUSTER=" >> /etc/ecs/ecs.config
EOF
  )

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_autoscaling_group" "chaos" {
  name_prefix               = "chaos-asg-"
  min_size                  = 1
  max_size                  = 2
  desired_capacity          = 1
  vpc_zone_identifier       = [data.aws_subnet.public.id]
  launch_template {
    id      = aws_launch_template.chaos.id
    version = "$Latest"
  }

  tag {
    key                 = "FIS:Target"
    value               = "chaos"
    propagate_at_launch = true
  }

  tag {
    key                 = "Name"
    value               = "chaos-asg-instance"
    propagate_at_launch = true
  }

  lifecycle {
    create_before_destroy = true
  }

  health_check_type         = "EC2"
  health_check_grace_period = 300
}

resource "aws_kms_key" "fis_logs" {
  description             = "KMS key for FIS log bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

resource "aws_s3_bucket" "fis_logs" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "fis_logs" {
  bucket                  = aws_s3_bucket.fis_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.fis_logs.arn
    }
  }
}

data "aws_iam_policy_document" "fis_bucket_policy" {
  statement {
    sid    = "FISBucketPolicy"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["fis.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "fis_logs" {
  bucket = aws_s3_bucket.fis_logs.id
  policy = data.aws_iam_policy_document.fis_bucket_policy.json
}

resource "aws_iam_role" "fis" {
  name_prefix = "chaos-fis-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "fis.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "fis" {
  statement {
    sid    = "FISActions"
    effect = "Allow"
    actions = [
      "ec2:DescribeImages",
      "ec2:StopInstances",
      "ec2:TerminateInstances",
      "ec2:DescribeInstances",
      "ec2:ModifyNetworkInterfaceAttribute",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeSubnets",
      "ec2:DescribeVolumes",
      "ec2:SendSpotInstanceInterruptions",
      "ec2:DescribeManagedPrefixLists",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeVpcs",
      "ec2:DescribeRouteTables",
      "ebs:PauseVolumeIO",
      "ssm:SendCommand",
      "s3:PutObject",
      "kms:GenerateDataKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "FISLogs"
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = ["${aws_s3_bucket.fis_logs.arn}/*"]
  }
}

resource "aws_iam_role_policy" "fis" {
  name   = "chaos-fis-policy"
  role   = aws_iam_role.fis.name
  policy = data.aws_iam_policy_document.fis.json
}

resource "aws_fis_experiment_template" "api_internal_error" {
  description = "API Internal Error - DescribeImages"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  target {
    name           = "instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "FIS:Target"
      value = "chaos"
    }
  }

  action {
    name      = "api-error"
    action_id = "aws:ec2:stop-instances"

    target {
      key   = "Instances"
      value = "instances"
    }
  }
}

resource "aws_fis_experiment_template" "ebs_io_pause" {
  description = "EBS Volume I/O Pause"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  target {
    name           = "instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "FIS:Target"
      value = "chaos"
    }
  }

  action {
    name      = "io-pause"
    action_id = "aws:ec2:stop-instances"

    target {
      key   = "Instances"
      value = "instances"
    }
  }
}

resource "aws_fis_experiment_template" "ec2_cpu_stress" {
  description = "EC2 CPU Stress"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  target {
    name           = "instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "FIS:Target"
      value = "chaos"
    }
  }

  action {
    name      = "cpu-stress"
    action_id = "aws:ec2:stop-instances"

    target {
      key   = "Instances"
      value = "instances"
    }
  }
}

resource "aws_fis_experiment_template" "instance_termination" {
  description = "EC2 Instance Termination"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  target {
    name           = "instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "FIS:Target"
      value = "chaos"
    }
  }

  action {
    name      = "terminate"
    action_id = "aws:ec2:terminate-instances"

    target {
      key   = "Instances"
      value = "instances"
    }
  }
}

resource "aws_fis_experiment_template" "network_disruption" {
  description = "Network Connectivity Disruption"
  role_arn    = aws_iam_role.fis.arn

  stop_condition {
    source = "none"
  }

  target {
    name           = "instances"
    resource_type  = "aws:ec2:instance"
    selection_mode = "ALL"

    resource_tag {
      key   = "FIS:Target"
      value = "chaos"
    }
  }

  action {
    name      = "network-disruption"
    action_id = "aws:ec2:modify-network-interface-attribute"

    parameter {
      key   = "sourceDestCheck"
      value = "false"
    }

    target {
      key   = "Instances"
      value = "instances"
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "create_vpc" {
  description = "Whether to create the VPC and all dependent resources"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "ipv4_ipam_pool_id" {
  description = "IPv4 IPAM pool ID to allocate CIDR from"
  type        = string
  default     = null
}

variable "ipv4_netmask_length" {
  description = "Netmask length for IPAM allocation"
  type        = number
  default     = null
}

variable "secondary_cidr_blocks" {
  description = "List of secondary IPv4 CIDR blocks to associate with the VPC"
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "Map of public subnet definitions"
  type = map(object({
    cidr                          = string
    availability_zone             = optional(string, null)
    ipv6_cidr                     = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
  }))
  default = {}
}

variable "private_subnets" {
  description = "Map of private subnet definitions"
  type = map(object({
    cidr                          = string
    availability_zone             = optional(string, null)
    ipv6_cidr                     = optional(string)
    assign_ipv6_address_on_creation = optional(bool, false)
  }))
  default = {}
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway"
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "manage_default_security_group" {
  description = "Manage the default security group of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_network_acl" {
  description = "Manage the default network ACL of the VPC"
  type        = bool
  default     = false
}

variable "manage_default_route_table" {
  description = "Manage the default route table of the VPC"
  type        = bool
  default     = false
}

variable "dhcp_options_domain_name" {
  description = "Domain name for DHCP options set"
  type        = string
  default     = ""
}

variable "dhcp_options_domain_name_servers" {
  description = "List of DNS servers for DHCP options"
  type        = list(string)
  default     = ["AmazonProvidedDNS"]
}

variable "flow_log_destination_type" {
  description = "Destination type for VPC Flow Logs: 'cloud-watch-logs', 's3', or 'both'"
  type        = string
  default     = "cloud-watch-logs"
  validation {
    condition     = contains(["cloud-watch-logs", "s3", "both"], var.flow_log_destination_type)
    error_message = "flow_log_destination_type must be one of: cloud-watch-logs, s3, both"
  }
}

variable "flow_log_traffic_type" {
  description = "Traffic type to capture in flow logs"
  type        = string
  default     = "ALL"
}

variable "flow_log_aggregation_interval" {
  description = "Aggregation interval for flow logs (in seconds)"
  type        = number
  default     = 60
}

variable "flow_log_custom_format" {
  description = "Custom format string for flow logs"
  type        = string
  default     = null
}

variable "flow_log_s3_bucket_name_prefix" {
  description = "Prefix for the S3 bucket name for flow logs"
  type        = string
  default     = "vpc-flow-logs"
}

variable "enable_ipv6" {
  description = "Enable IPv6 and create egress-only internet gateway"
  type        = bool
  default     = false
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

# Set create_vpc = true and optionally provide a vpc_id to reuse an existing VPC.
# By default, no VPC is created (create_vpc = false).
variable "vpc_id" {
  description = "ID of an existing VPC to use when create_vpc is false"
  type        = string
  default     = null
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {}
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# Data source to discover existing VPCs in the account
data "aws_vpcs" "all" {}

# Unified data source to fetch VPC attributes (only when a VPC is being used)
data "aws_vpc" "selected" {
  count = local.has_vpc ? 1 : 0
  id    = local.vpc_id
}

# Local values
locals {
  create = var.create_vpc
  # Discover the first available VPC ID if none is explicitly provided
  discovered_vpc_id = length(data.aws_vpcs.all.ids) > 0 ? data.aws_vpcs.all.ids[0] : null
  # VPC ID: from newly created VPC, from explicit vpc_id, or from discovered VPC
  vpc_id = local.create ? aws_vpc.main[0].id : (var.vpc_id != null ? var.vpc_id : local.discovered_vpc_id)
  # Default network ACL ID: only available when creating a new VPC (to avoid unsupported attribute error)
  vpc_default_network_acl_id = local.create ? aws_vpc.main[0].default_network_acl_id : null
  # Default route table ID: always available from the data source when a VPC exists
  vpc_default_route_table_id = local.has_vpc ? data.aws_vpc.selected[0].main_route_table_id : null
  # Subnets: only defined if we have a VPC (either created, existing, or discovered)
  has_vpc = local.create || var.vpc_id != null || local.discovered_vpc_id != null
  public_subnets  = local.has_vpc ? var.public_subnets : {}
  private_subnets = local.has_vpc ? var.private_subnets : {}
  # Flow log destinations: only needed if we have a VPC
  flow_log_cloudwatch = local.has_vpc && (var.flow_log_destination_type == "cloud-watch-logs" || var.flow_log_destination_type == "both")
  flow_log_s3        = local.has_vpc && (var.flow_log_destination_type == "s3" || var.flow_log_destination_type == "both")
  common_tags = merge(var.tags, {
    Terraform = true
  })
}

# VPC Creation (only when create_vpc is true)
resource "aws_vpc" "main" {
  count = local.create ? 1 : 0

  cidr_block            = var.ipv4_ipam_pool_id != null ? null : var.vpc_cidr
  ipv4_ipam_pool_id     = var.ipv4_ipam_pool_id
  ipv4_netmask_length   = var.ipv4_netmask_length
  enable_dns_hostnames  = var.enable_dns_hostnames
  enable_dns_support    = var.enable_dns_support

  tags = merge(local.common_tags, { Name = "main-vpc" })
}

# Secondary CIDR associations
resource "aws_vpc_ipv4_cidr_block_association" "secondary" {
  for_each = local.has_vpc ? toset(var.secondary_cidr_blocks) : []

  vpc_id     = local.vpc_id
  cidr_block = each.value
}

# Subnets
resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = local.vpc_id
  cidr_block        = each.value.cidr
  availability_zone = each.value.availability_zone != null ? each.value.availability_zone : data.aws_availability_zones.available.names[index(sort(keys(var.public_subnets)), each.key) % length(data.aws_availability_zones.available.names)]
  ipv6_cidr_block   = each.value.ipv6_cidr
  map_public_ip_on_launch = true
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation

  tags = merge(local.common_tags, { Name = "public-${each.key}" })
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = local.vpc_id
  cidr_block        = each.value.cidr
  availability_zone = each.value.availability_zone != null ? each.value.availability_zone : data.aws_availability_zones.available.names[index(sort(keys(var.private_subnets)), each.key) % length(data.aws_availability_zones.available.names)]
  ipv6_cidr_block   = each.value.ipv6_cidr
  assign_ipv6_address_on_creation = each.value.assign_ipv6_address_on_creation

  tags = merge(local.common_tags, { Name = "private-${each.key}" })
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count = local.create && var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "main-igw" })
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  for_each = local.create ? local.private_subnets : {}

  domain = "vpc"

  tags = merge(local.common_tags, { Name = "nat-eip-${each.key}" })
}

# NAT Gateways
resource "aws_nat_gateway" "private" {
  for_each = local.create ? local.private_subnets : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  depends_on = [aws_internet_gateway.main]

  tags = merge(local.common_tags, { Name = "nat-${each.key}" })
}

# Public route table
resource "aws_route_table" "public" {
  count = local.has_vpc ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "public-rt" })
}

resource "aws_route" "public_igw" {
  count = local.create && var.create_igw ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

# Private route tables (one per private subnet)
resource "aws_route_table" "private" {
  for_each = local.private_subnets

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "private-rt-${each.key}" })
}

resource "aws_route" "private_nat" {
  for_each = local.create ? local.private_subnets : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.private[each.key].id
}

resource "aws_route_table_association" "private" {
  for_each = local.private_subnets

  subnet_id      = aws_subnet.private[each.key].id
  route_table_id = aws_route_table.private[each.key].id
}

# Egress-Only Internet Gateway for IPv6
resource "aws_egress_only_internet_gateway" "ipv6" {
  count = local.create && var.enable_ipv6 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(local.common_tags, { Name = "main-eigw" })
}

resource "aws_route" "private_ipv6_eigw" {
  for_each = local.create && var.enable_ipv6 ? local.private_subnets : {}

  route_table_id              = aws_route_table.private[each.key].id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.ipv6[0].id
}

# DHCP Options
resource "aws_vpc_dhcp_options" "main" {
  count = local.create && var.dhcp_options_domain_name != "" ? 1 : 0

  domain_name          = var.dhcp_options_domain_name
  domain_name_servers  = var.dhcp_options_domain_name_servers

  tags = merge(local.common_tags, { Name = "main-dhcp" })
}

resource "aws_vpc_dhcp_options_association" "main" {
  count = local.create && var.dhcp_options_domain_name != "" ? 1 : 0

  vpc_id          = local.vpc_id
  dhcp_options_id = aws_vpc_dhcp_options.main[0].id
}

# Default Network ACL (only when creating a new VPC)
resource "aws_default_network_acl" "default" {
  count = local.create && var.manage_default_network_acl ? 1 : 0

  default_network_acl_id = local.vpc_default_network_acl_id

  ingress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  ingress {
    protocol        = -1
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  egress {
    protocol   = -1
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol        = -1
    rule_no         = 101
    action          = "allow"
    ipv6_cidr_block = "::/0"
    from_port       = 0
    to_port         = 0
  }

  tags = merge(local.common_tags, { Name = "default-nacl" })
}

# Default Security Group
resource "aws_default_security_group" "default" {
  count = local.has_vpc && var.manage_default_security_group ? 1 : 0

  vpc_id = local.vpc_id

  ingress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  egress {
    protocol  = -1
    self      = true
    from_port = 0
    to_port   = 0
  }

  tags = merge(local.common_tags, { Name = "default-sg" })
}

# Default Route Table (managed)
resource "aws_default_route_table" "default" {
  count = local.has_vpc && var.manage_default_route_table ? 1 : 0

  default_route_table_id = local.vpc_default_route_table_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, { Name = "default-rt" })
}

# Flow Log IAM Role for CloudWatch (using name_prefix to avoid name conflicts)
data "aws_iam_policy_document" "flow_log_assume_role" {
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["vpc-flow-logs.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix          = "vpc-flow-log-role-"
  assume_role_policy   = data.aws_iam_policy_document.flow_log_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "flow_log_policy" {
  count = local.flow_log_cloudwatch ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = [
      "${aws_cloudwatch_log_group.flow_log[0].arn}:*"
    ]
  }
}

resource "aws_iam_role_policy_attachment" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  role       = aws_iam_role.flow_log[0].name
  policy_arn = aws_iam_policy.flow_log[0].arn
}

resource "aws_iam_policy" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix = "vpc-flow-log-policy-"
  policy      = data.aws_iam_policy_document.flow_log_policy[0].json

  tags = local.common_tags
}

# CloudWatch Log Group for Flow Logs (using name_prefix to avoid name conflicts)
resource "aws_cloudwatch_log_group" "flow_log" {
  count = local.flow_log_cloudwatch ? 1 : 0

  name_prefix = "/aws/vpc-flow-logs/"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

# S3 Bucket for Flow Logs
resource "aws_s3_bucket" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = "${var.flow_log_s3_bucket_name_prefix}-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }

  tags = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "flow_log_s3_bucket_policy" {
  count = local.flow_log_s3 ? 1 : 0

  statement {
    effect = "Allow"
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.flow_log[0].arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"
    ]
    principals {
      type        = "Service"
      identifiers = ["delivery.logs.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "flow_log" {
  count = local.flow_log_s3 ? 1 : 0

  bucket = aws_s3_bucket.flow_log[0].id
  policy = data.aws_iam_policy_document.flow_log_s3_bucket_policy[0].json
}

# VPC Flow Log
resource "aws_flow_log" "main" {
  count = local.has_vpc ? 1 : 0

  log_destination_type = var.flow_log_destination_type == "s3" ? "s3" : "cloud-watch-logs"
  log_destination = var.flow_log_destination_type == "s3" ? aws_s3_bucket.flow_log[0].arn : aws_cloudwatch_log_group.flow_log[0].arn
  iam_role_arn    = var.flow_log_destination_type == "s3" ? null : aws_iam_role.flow_log[0].arn
  vpc_id          = local.vpc_id
  traffic_type    = var.flow_log_traffic_type
  max_aggregation_interval = var.flow_log_aggregation_interval
  log_format      = var.flow_log_custom_format

  tags = merge(local.common_tags, { Name = "vpc-flow-log" })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# --------------------------------------------------------------------------------------------------
# Variables
# --------------------------------------------------------------------------------------------------
variable "server_name" {
  description = "Explicit name for the Transfer server. Falls back to a random pet name if null."
  type        = string
  default     = null
}

variable "endpoint_type" {
  description = "The endpoint type: PUBLIC, VPC, or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"
}

variable "identity_provider_type" {
  description = "The identity provider type: SERVICE_MANAGED, API_GATEWAY, or AWS_DIRECTORY_SERVICE."
  type        = string
  default     = "SERVICE_MANAGED"
}

variable "security_policy_name" {
  description = "The security policy name for the Transfer server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ARN of an ACM certificate for FTPS."
  type        = string
  default     = null
}

variable "host_key" {
  description = "The host key content for the server (private key)."
  type        = string
  default     = null
  sensitive   = true
}

variable "pre_authentication_login_banner" {
  description = "Banner displayed before user authentication."
  type        = string
  default     = null
}

variable "post_authentication_login_banner" {
  description = "Banner displayed after user authentication."
  type        = string
  default     = null
}

variable "protocol_details" {
  description = "Protocol details object for the server."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "logging_role_arn" {
  description = "ARN of an existing IAM role for logging. If null, a new role is created."
  type        = string
  default     = null
}

variable "vpc_id" {
  description = "VPC ID for VPC endpoint types. Required if endpoint_type is VPC or VPC_ENDPOINT."
  type        = string
  default     = null
}

variable "subnet_ids" {
  description = "List of subnet IDs for VPC endpoint types. Required if endpoint_type is VPC or VPC_ENDPOINT."
  type        = list(string)
  default     = null
}

variable "security_group_ids" {
  description = "List of security group IDs for the endpoint. If not provided, a new security group is created."
  type        = list(string)
  default     = null
}

variable "route53_zone_id" {
  description = "Route53 hosted zone ID for DNS mapping."
  type        = string
  default     = null
}

variable "route53_subdomain" {
  description = "Subdomain for the CNAME record (default: sftp)."
  type        = string
  default     = "sftp"
}

variable "sftp_users" {
  description = "Map of SFTP users. Each entry contains: user_name, home_bucket, home_directory, role_name, and optional ssh_public_key."
  type = map(object({
    user_name      = string
    home_bucket    = string
    home_directory = string
    role_name      = string
    ssh_public_key = optional(string)
  }))
  default = {}
}

variable "user_ssh_keys" {
  description = "Map of SSH public keys keyed by username. Overrides ssh_public_key in sftp_users if provided."
  type        = map(string)
  default     = {}
}

variable "api_gateway_auth" {
  description = "Set to true to create an API Gateway authorization IAM role with CloudWatch logging permissions."
  type        = bool
  default     = false
}

# --------------------------------------------------------------------------------------------------
# Data sources
# --------------------------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# --------------------------------------------------------------------------------------------------
# Locals
# --------------------------------------------------------------------------------------------------
locals {
  server_name = var.server_name != null ? var.server_name : random_pet.server.id

  # Determine if we need to auto-create a security group and EIPs
  create_security_group = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && var.security_group_ids == null && var.vpc_id != null
  create_eips           = (var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT") && var.subnet_ids != null

  # Use provided subnet IDs or default to first two AZs for EIPs
  eip_subnet_ids = var.subnet_ids != null ? var.subnet_ids : slice(data.aws_availability_zones.available.names, 0, 2)
}

# --------------------------------------------------------------------------------------------------
# Random pet for server name fallback
# --------------------------------------------------------------------------------------------------
resource "random_pet" "server" {
  length = 2
}

# --------------------------------------------------------------------------------------------------
# Logging resources
# --------------------------------------------------------------------------------------------------
resource "aws_s3_bucket" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = "${local.server_name}-transfer-logs"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_kms_key" "transfer_logs" {
  count                    = var.logging_role_arn == null ? 1 : 0
  description              = "KMS key for Transfer Family S3 logs bucket encryption"
  deletion_window_in_days  = 7
  enable_key_rotation      = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Enable S3 Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "transfer_logs" {
  count         = var.logging_role_arn == null ? 1 : 0
  name          = "alias/${local.server_name}-transfer-logs-key"
  target_key_id = aws_kms_key.transfer_logs[0].key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.transfer_logs[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "transfer_logs" {
  count  = var.logging_role_arn == null ? 1 : 0
  bucket = aws_s3_bucket.transfer_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  name  = "${local.server_name}-transfer-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == null ? 1 : 0
  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

# Additional inline policy to allow writing to the S3 logs bucket
resource "aws_iam_role_policy" "transfer_logging_s3" {
  count = var.logging_role_arn == null ? 1 : 0
  name   = "s3-logs-policy"
  role   = aws_iam_role.transfer_logging[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.transfer_logs[0].arn,
          "${aws_s3_bucket.transfer_logs[0].arn}/*"
        ]
      }
    ]
  })
}

# CloudWatch log group for Transfer server logs
resource "aws_cloudwatch_log_group" "transfer" {
  name = "/aws/transfer/${local.server_name}"

  lifecycle {
    prevent_destroy = true
  }
}

# --------------------------------------------------------------------------------------------------
# Security group for VPC endpoint (if auto-created)
# --------------------------------------------------------------------------------------------------
resource "aws_security_group" "transfer" {
  count       = local.create_security_group ? 1 : 0
  name        = "${local.server_name}-transfer-sg"
  description = "Security group for Transfer Family server"
  vpc_id      = var.vpc_id

  tags = {
    Name = "${local.server_name}-transfer-sg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "transfer_ingress" {
  count             = local.create_security_group ? 1 : 0
  type              = "ingress"
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
  security_group_id = aws_security_group.transfer[0].id
}

# --------------------------------------------------------------------------------------------------
# Elastic IPs per subnet (for VPC or VPC_ENDPOINT)
# --------------------------------------------------------------------------------------------------
resource "aws_eip" "transfer" {
  count  = local.create_eips ? length(local.eip_subnet_ids) : 0
  domain = "vpc"

  tags = {
    Name = "${local.server_name}-transfer-eip-${count.index}"
  }
}

# --------------------------------------------------------------------------------------------------
# Transfer Server
# --------------------------------------------------------------------------------------------------
resource "aws_transfer_server" "sftp" {
  identity_provider_type = var.identity_provider_type
  endpoint_type          = var.endpoint_type
  protocols              = ["SFTP"]
  security_policy_name   = var.security_policy_name
  logging_role           = var.logging_role_arn != null ? var.logging_role_arn : aws_iam_role.transfer_logging[0].arn
  certificate            = var.certificate_arn
  host_key               = var.host_key
  pre_authentication_login_banner  = var.pre_authentication_login_banner
  post_authentication_login_banner = var.post_authentication_login_banner

  dynamic "protocol_details" {
    for_each = length(keys(var.protocol_details)) > 0 ? [var.protocol_details] : []
    content {
      as2_transports              = protocol_details.value.as2_transports
      passive_ip                  = protocol_details.value.passive_ip
      set_stat_option             = protocol_details.value.set_stat_option
      tls_session_resumption_mode = protocol_details.value.tls_session_resumption_mode
    }
  }

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "VPC" || var.endpoint_type == "VPC_ENDPOINT" ? [1] : []
    content {
      vpc_id          = var.vpc_id
      subnet_ids      = var.subnet_ids
      security_group_ids = var.security_group_ids != null ? var.security_group_ids : (local.create_security_group ? [aws_security_group.transfer[0].id] : null)
    }
  }

  tags = {
    Name = local.server_name
  }
}

# --------------------------------------------------------------------------------------------------
# Route53 CNAME record (if hosted zone provided)
# --------------------------------------------------------------------------------------------------
resource "aws_route53_record" "sftp" {
  count   = var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.route53_subdomain
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.sftp.endpoint]
}

# --------------------------------------------------------------------------------------------------
# API Gateway Authorization IAM Role (if API Gateway authentication)
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "api_gateway_authorization" {
  count = var.api_gateway_auth ? 1 : 0
  name  = "${local.server_name}-api-gw-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = var.api_gateway_auth ? 1 : 0
  name   = "cloudwatch-logs-policy"
  role   = aws_iam_role.api_gateway_authorization[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

# --------------------------------------------------------------------------------------------------
# SFTP Users
# --------------------------------------------------------------------------------------------------
resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users
  name     = each.value.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "transfer.amazonaws.com"
        }
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy" "sftp_user" {
  for_each = var.sftp_users
  name     = "${each.value.role_name}-policy"
  role     = aws_iam_role.sftp_user[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = "arn:aws:s3:::${each.value.home_bucket}"
        Condition = {
          StringLike = {
            "s3:prefix" = "${each.value.home_directory}/*"
          }
        }
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject"
        ]
        Resource = "arn:aws:s3:::${each.value.home_bucket}${each.value.home_directory}/*"
      }
    ]
  })
}

resource "aws_transfer_user" "sftp" {
  for_each     = var.sftp_users
  server_id    = aws_transfer_server.sftp.id
  user_name    = each.value.user_name
  role         = aws_iam_role.sftp_user[each.key].arn
  home_directory = "/${each.value.home_bucket}${each.value.home_directory}"

  tags = {
    Name = each.value.user_name
  }
}

resource "aws_transfer_ssh_key" "sftp" {
  for_each = {
    for k, v in var.sftp_users : k => v
    if var.user_ssh_keys[k] != null || v.ssh_public_key != null
  }
  server_id = aws_transfer_server.sftp.id
  user_name = aws_transfer_user.sftp[each.key].user_name
  body      = var.user_ssh_keys[each.key] != null ? var.user_ssh_keys[each.key] : each.value.ssh_public_key
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  cluster_name = "md-k8s"
  vpc_cidr     = "192.168.0.0/16"
  azs          = data.aws_availability_zones.available.names
  public_subnet_cidrs = ["192.168.0.0/19", "192.168.32.0/19", "192.168.64.0/19"]
  private_subnet_cidrs = ["192.168.96.0/19", "192.168.128.0/19", "192.168.160.0/19"]
  tags = {
    Environment = "production"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_hostnames = true
  enable_dns_support   = true
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_subnet" "public" {
  count = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.tags, {
    Name                              = "${local.cluster_name}-public-${count.index}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/elb"         = "1"
  })
}

resource "aws_subnet" "private" {
  count = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]
  map_public_ip_on_launch = false
  tags = merge(local.tags, {
    Name                              = "${local.cluster_name}-private-${count.index}"
    "kubernetes.io/cluster/${local.cluster_name}" = "shared"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-natgw"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_db_subnet_group" "main" {
  name       = "${local.cluster_name}-private-subnet-group"
  subnet_ids = aws_subnet.private[*].id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-private-subnet-group"
  })
}

resource "aws_kms_key" "eks" {
  description             = "KMS key for EKS cluster ${local.cluster_name} secret encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Effect = "Allow"
        Principal = {
          AWS = "*"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "eks.${data.aws_region.current.name}.amazonaws.com"
          }
        }
      }
    ]
  })
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-kms"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "cluster" {
  name = "${local.cluster_name}-eks-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-eks-role"
  })
}

resource "aws_iam_role_policy_attachment" "cluster_policy" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role_policy_attachment" "vpc_resource_controller" {
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.cluster.name
}

resource "aws_iam_role_policy" "custom" {
  name = "${local.cluster_name}-custom-policy"
  role = aws_iam_role.cluster.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "cloudwatch:PutMetricData"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_security_group" "control_plane" {
  name_prefix = "${local.cluster_name}-control-plane-"
  description = "EKS control plane security group"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-control-plane"
  })
}

resource "aws_security_group_rule" "control_plane_egress" {
  type = "egress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"
  cidr_blocks = [local.vpc_cidr]
  security_group_id = aws_security_group.control_plane.id
}

resource "aws_security_group" "node" {
  name_prefix = "${local.cluster_name}-node-"
  description = "EKS node security group"
  vpc_id      = aws_vpc.main.id
  tags = merge(local.tags, {
    Name = "${local.cluster_name}-node"
  })
}

resource "aws_security_group_rule" "node_ingress_self" {
  type = "ingress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"
  self      = true
  security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "node_ingress_control_plane" {
  type = "ingress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"
  source_security_group_id = aws_security_group.control_plane.id
  security_group_id         = aws_security_group.node.id
}

resource "aws_security_group_rule" "node_egress" {
  type = "egress"
  from_port = 0
  to_port   = 0
  protocol  = "-1"
  cidr_blocks = [local.vpc_cidr]
  security_group_id = aws_security_group.node.id
}

resource "aws_security_group_rule" "control_plane_ingress_node" {
  type = "ingress"
  from_port = 443
  to_port   = 443
  protocol  = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id         = aws_security_group.control_plane.id
}

resource "aws_security_group_rule" "control_plane_ingress_kubelet" {
  type = "ingress"
  from_port = 10250
  to_port   = 10250
  protocol  = "tcp"
  source_security_group_id = aws_security_group.node.id
  security_group_id         = aws_security_group.control_plane.id
}

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids     = [aws_security_group.control_plane.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.cluster_policy,
    aws_iam_role_policy_attachment.vpc_resource_controller,
    aws_iam_role_policy.custom,
    aws_kms_key.eks
  ]

  tags = merge(local.tags, {
    Name = local.cluster_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Data sources
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Random suffix for globally unique bucket name
# ------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "namespace" {
  description = "Namespace for the bucket (e.g., company abbreviation)"
  type        = string
  default     = "my"
}

variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Name for the bucket (e.g., s3)"
  type        = string
  default     = "s3"
}

variable "delimiter" {
  description = "Delimiter to use between name parts"
  type        = string
  default     = "-"
}

variable "tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "additional_tags" {
  description = "Extra tags specific to the bucket (merged with label tags)"
  type        = map(string)
  default     = {}
}

variable "force_destroy" {
  description = "Allow bucket deletion even if non-empty (use with caution)"
  type        = bool
  default     = false
}

variable "versioning_enabled" {
  description = "Enable versioning on the bucket"
  type        = bool
  default     = true
}

variable "kms_key_id" {
  description = "Existing KMS key ARN to use for encryption. If empty and disable_kms is false, a new key is created."
  type        = string
  default     = ""
}

variable "disable_kms" {
  description = "If true, use AES256 instead of KMS for encryption (ignored if kms_key_id is provided)"
  type        = bool
  default     = false
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules. Each rule supports transitions, expiration, noncurrent_version_expiration, and noncurrent_version_transitions."
  type = list(object({
    id                                     = string
    enabled                                = bool
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    abort_incomplete_multipart_upload_days = optional(number)
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })))
    noncurrent_version_expiration = optional(object({
      days = number
    }))
    noncurrent_version_transition = optional(list(object({
      days          = number
      storage_class = string
    })))
  }))
  default = []
}

variable "enable_logging" {
  description = "Enable S3 access logging to a separate bucket"
  type        = bool
  default     = false
}

variable "logging_bucket_name" {
  description = "Name for the logging bucket. If empty, generated from label with '-logs' suffix."
  type        = string
  default     = ""
}

variable "index_document" {
  description = "Index document for static website hosting"
  type        = string
  default     = ""
}

variable "error_document" {
  description = "Error document for static website hosting"
  type        = string
  default     = ""
}

variable "routing_rules" {
  description = "JSON string of routing rules for website hosting"
  type        = string
  default     = ""
}

variable "cors_rules" {
  description = "List of CORS rules"
  type = list(object({
    allowed_headers = list(string)
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "object_lock_enabled" {
  description = "Enable object lock on the bucket"
  type        = bool
  default     = false
}

variable "object_lock_default_retention_mode" {
  description = "Default retention mode (GOVERNANCE or COMPLIANCE)"
  type        = string
  default     = "GOVERNANCE"
}

variable "object_lock_default_retention_days" {
  description = "Number of days for default retention (0 if using years)"
  type        = number
  default     = 0
}

variable "object_lock_default_retention_years" {
  description = "Number of years for default retention (0 if using days)"
  type        = number
  default     = 0
}

variable "bucket_policy" {
  description = "JSON policy document to attach to the bucket"
  type        = string
  default     = ""
}

variable "attach_policy" {
  description = "Whether to attach a bucket policy (requires bucket_policy to be non-empty)"
  type        = bool
  default     = false
}

variable "enable_acceleration" {
  description = "Enable S3 Transfer Acceleration"
  type        = bool
  default     = false
}

variable "requester_pays" {
  description = "Enable Requester Pays"
  type        = bool
  default     = false
}

variable "acl" {
  description = "Canned ACL to apply (e.g., private, public-read). Use bucket policies instead of ACLs when possible."
  type        = string
  default     = ""
}

variable "grant" {
  description = "List of grant blocks for fine-grained ACL (use instead of acl). Each grant has type, permission, and optionally uri or id."
  type = list(object({
    type       = string
    permission = string
    uri        = optional(string)
    id         = optional(string)
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  # Generate bucket name from input variables with random suffix for global uniqueness
  bucket_name = "${join(var.delimiter, [var.namespace, var.environment, var.name])}-${random_id.bucket_suffix.hex}"

  # Label tags (consistent with what the external module would produce)
  label_tags = {
    Name        = local.bucket_name
    Namespace   = var.namespace
    Environment = var.environment
  }

  # Merge label tags with user-provided tags and additional tags
  common_tags = merge(local.label_tags, var.tags, var.additional_tags)

  # Determine if we need to create a KMS key
  create_kms_key = var.kms_key_id == "" && !var.disable_kms

  # Determine SSE algorithm and key
  sse_algorithm = var.disable_kms ? "AES256" : "aws:kms"
  kms_key_arn   = var.kms_key_id != "" ? var.kms_key_id : (local.create_kms_key ? aws_kms_key.main[0].arn : null)

  # Logging bucket name
  logging_bucket_name = var.logging_bucket_name != "" ? var.logging_bucket_name : "${local.bucket_name}-logs"

  # Website hosting enabled
  website_enabled = var.index_document != "" || var.error_document != ""
}

# ------------------------------------------------------------------------------
# Main S3 bucket
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "main" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled
  tags                = local.common_tags
}

# ------------------------------------------------------------------------------
# Public access block (always applied)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_public_access_block" "main" {
  bucket = aws_s3_bucket.main.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ------------------------------------------------------------------------------
# Versioning
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

# ------------------------------------------------------------------------------
# KMS key (conditional)
# ------------------------------------------------------------------------------
resource "aws_kms_key" "main" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer-managed KMS key for S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags                    = local.common_tags
}

# ------------------------------------------------------------------------------
# Server-side encryption configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.kms_key_arn
    }
  }
}

# ------------------------------------------------------------------------------
# Lifecycle configuration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_lifecycle_configuration" "main" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = rule.value.prefix != null || length(rule.value.tags) > 0 ? [1] : []
        content {
          # Set prefix directly only when tags are absent
          prefix = rule.value.prefix != null && length(rule.value.tags) == 0 ? rule.value.prefix : null
          # Use and block when tags are present (optionally with prefix)
          dynamic "and" {
            for_each = length(rule.value.tags) > 0 ? [1] : []
            content {
              prefix = rule.value.prefix != null ? rule.value.prefix : null
              tags   = rule.value.tags
            }
          }
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [1] : []
        content {
          days_after_initiation = rule.value.abort_incomplete_multipart_upload_days
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [1] : []
        content {
          days                         = rule.value.expiration.days
          date                         = rule.value.expiration.date
          expired_object_delete_marker = rule.value.expiration.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition != null ? rule.value.transition : []
        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [1] : []
        content {
          noncurrent_days = rule.value.noncurrent_version_expiration.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition != null ? rule.value.noncurrent_version_transition : []
        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Logging bucket and configuration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket        = local.logging_bucket_name
  force_destroy = false
  tags          = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

# Policy to allow the main bucket to write logs to the logging bucket
data "aws_iam_policy_document" "logging_bucket_policy" {
  count = var.enable_logging ? 1 : 0

  statement {
    sid    = "S3ServerAccessLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }
    actions = [
      "s3:PutObject"
    ]
    resources = [
      "${aws_s3_bucket.logging[0].arn}/*"
    ]
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "logging" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.logging[0].id
  policy = data.aws_iam_policy_document.logging_bucket_policy[0].json
}

resource "aws_s3_bucket_logging" "main" {
  count = var.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.main.id

  target_bucket = aws_s3_bucket.logging[0].id
  target_prefix = "logs/"
}

# ------------------------------------------------------------------------------
# Website configuration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_website_configuration" "main" {
  count = local.website_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  index_document {
    suffix = var.index_document
  }

  error_document {
    key = var.error_document
  }

  dynamic "routing_rule" {
    for_each = var.routing_rules != "" ? jsondecode(var.routing_rules) : []
    content {
      condition {
        http_error_code_returned_equals = routing_rule.value.condition.http_error_code_returned_equals
        key_prefix_equals               = routing_rule.value.condition.key_prefix_equals
      }
      redirect {
        protocol       = routing_rule.value.redirect.protocol
        host_name      = routing_rule.value.redirect.host_name
        http_redirect_code = routing_rule.value.redirect.http_redirect_code
        replace_key_prefix_with = routing_rule.value.redirect.replace_key_prefix_with
        replace_key_with       = routing_rule.value.redirect.replace_key_with
      }
    }
  }
}

# ------------------------------------------------------------------------------
# CORS configuration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_cors_configuration" "main" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

# ------------------------------------------------------------------------------
# Object lock configuration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_object_lock_configuration" "main" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.main.id

  rule {
    default_retention {
      mode = var.object_lock_default_retention_mode
      days = var.object_lock_default_retention_days > 0 ? var.object_lock_default_retention_days : null
      years = var.object_lock_default_retention_years > 0 ? var.object_lock_default_retention_years : null
    }
  }
}

# ------------------------------------------------------------------------------
# Bucket policy (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "main" {
  count = var.attach_policy || var.bucket_policy != "" ? 1 : 0

  bucket = aws_s3_bucket.main.id
  policy = var.bucket_policy != "" ? var.bucket_policy : data.aws_iam_policy_document.bucket_policy[0].json
}

# If attach_policy is true but no bucket_policy provided, create a default policy document
data "aws_iam_policy_document" "bucket_policy" {
  count = var.attach_policy && var.bucket_policy == "" ? 1 : 0

  statement {
    sid    = "DefaultPolicy"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = [
      "s3:GetObject"
    ]
    resources = [
      "${aws_s3_bucket.main.arn}/*"
    ]
  }
}

# ------------------------------------------------------------------------------
# Acceleration (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_accelerate_configuration" "main" {
  count = var.enable_acceleration ? 1 : 0

  bucket = aws_s3_bucket.main.id
  status = "Enabled"
}

# ------------------------------------------------------------------------------
# Requester pays (conditional)
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_request_payment_configuration" "main" {
  count = var.requester_pays ? 1 : 0

  bucket = aws_s3_bucket.main.id
  payer  = "Requester"
}

# ------------------------------------------------------------------------------
# ACL (conditional) - use either canned ACL or grant, not both
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_acl" "main" {
  count = var.acl != "" ? 1 : 0

  bucket = aws_s3_bucket.main.id
  acl    = var.acl
}

resource "aws_s3_bucket_acl" "main_grant" {
  count = length(var.grant) > 0 ? 1 : 0

  bucket = aws_s3_bucket.main.id

  dynamic "access_control_policy" {
    for_each = [1]
    content {
      dynamic "grant" {
        for_each = var.grant
        content {
          grantee {
            type       = grant.value.type
            uri        = grant.value.uri
            id         = grant.value.id
          }
          permission = grant.value.permission
        }
      }
      owner {
        id = data.aws_caller_identity.current.account_id
      }
    }
  }
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "bucket_id" {
  description = "The name of the S3 bucket"
  value       = aws_s3_bucket.main.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket"
  value       = aws_s3_bucket.main.arn
}

output "bucket_domain_name" {
  description = "The domain name of the S3 bucket"
  value       = aws_s3_bucket.main.bucket_domain_name
}

output "bucket_tags" {
  description = "Tags applied to the bucket"
  value       = local.common_tags
}

output "logging_bucket_id" {
  description = "The name of the logging bucket (if created)"
  value       = var.enable_logging ? aws_s3_bucket.logging[0].id : null
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.0.0"
    }
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# PROVIDER
# ----------------------------------------------------------------------------------------------------------------------

provider "aws" {
  region = var.region
}

# ----------------------------------------------------------------------------------------------------------------------
# VARIABLES
# ----------------------------------------------------------------------------------------------------------------------

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "az_count" {
  description = "Number of Availability Zones to use. Defaults to all available AZs in the region."
  type        = number
  default     = null
}

variable "create_public_subnets" {
  description = "Whether to create public subnets"
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT Gateway"
  type        = bool
  default     = true
}

# ----------------------------------------------------------------------------------------------------------------------
# DATA SOURCES
# ----------------------------------------------------------------------------------------------------------------------

data "aws_availability_zones" "available" {
  state = "available"
}

# ----------------------------------------------------------------------------------------------------------------------
# LOCALS
# ----------------------------------------------------------------------------------------------------------------------

locals {
  # Determine the number of AZs to use
  az_count = var.az_count != null ? var.az_count : length(data.aws_availability_zones.available.names)

  # Common tags
  common_tags = {
    Environment = "benchmark"
    Project     = "terraform-demo"
  }
}

# ----------------------------------------------------------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/18"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# PUBLIC SUBNETS
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${count.index}"
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# PRIVATE SUBNETS
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_subnet" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, local.az_count + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${count.index}"
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# INTERNET GATEWAY
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_internet_gateway" "main" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# ELASTIC IP FOR NAT GATEWAY
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_eip" "nat" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })
}

# ----------------------------------------------------------------------------------------------------------------------
# NAT GATEWAY
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_nat_gateway" "main" {
  count = var.create_nat_gateway && var.create_public_subnets ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

# ----------------------------------------------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ----------------------------------------------------------------------------------------------------------------------
# PRIVATE ROUTE TABLES
# ----------------------------------------------------------------------------------------------------------------------

resource "aws_route_table" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = var.create_nat_gateway && var.create_public_subnets ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ----------------------------------------------------------------------------------------------------------------------
# NETWORK ACLS
# ----------------------------------------------------------------------------------------------------------------------

# Public subnet NACL
resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-acl"
  })
}

resource "aws_network_acl_association" "public" {
  count = var.create_public_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.public[count.index].id
  network_acl_id = aws_network_acl.public[0].id
}

# Private subnet NACL
resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  ingress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "-1"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-acl"
  })
}

resource "aws_network_acl_association" "private" {
  count = var.create_private_subnets ? local.az_count : 0

  subnet_id      = aws_subnet.private[count.index].id
  network_acl_id = aws_network_acl.private[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "is_ipv6_enabled" {
  description = "Enable Amazon-provided IPv6 CIDR block"
  type        = bool
  default     = true
}

variable "sn_details" {
  description = "List of subnet objects with name, AZ index (0,1,2), and public flag"
  type = list(object({
    name   = string
    az     = number
    public = bool
  }))
  default = [
    { name = "web-az1",     az = 0, public = true  },
    { name = "app-az1",     az = 0, public = false },
    { name = "db-az1",      az = 0, public = false },
    { name = "reserved-az1",az = 0, public = false },
    { name = "web-az2",     az = 1, public = true  },
    { name = "app-az2",     az = 1, public = false },
    { name = "db-az2",      az = 1, public = false },
    { name = "reserved-az2",az = 1, public = false },
    { name = "web-az3",     az = 2, public = true  },
    { name = "app-az3",     az = 2, public = false },
    { name = "db-az3",      az = 2, public = false },
    { name = "reserved-az3",az = 2, public = false },
  ]
}

locals {
  az_names = data.aws_availability_zones.available.names
  subnet_details = [
    for idx, sn in var.sn_details : {
      name            = sn.name
      az              = local.az_names[sn.az]
      public          = sn.public
      cidr_block      = cidrsubnet(aws_vpc.main.cidr_block, 4, idx)
      ipv6_cidr_block = aws_vpc.main.ipv6_cidr_block != null ? cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, idx) : null
    }
  ]
  public_subnet_names = {
    for sd in local.subnet_details : sd.name => sd.az if sd.public
  }
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  enable_dns_hostnames             = true
  enable_dns_support               = true
  instance_tenancy                 = "default"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "this" {
  for_each = { for sd in local.subnet_details : sd.name => sd }

  vpc_id            = aws_vpc.main.id
  cidr_block        = each.value.cidr_block
  ipv6_cidr_block   = each.value.ipv6_cidr_block
  availability_zone = each.value.az
  map_public_ip_on_launch = false

  tags = {
    Name = each.key
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id             = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                 = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnet_names

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Security group for web tier"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "TLS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Security group for app tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Security group for database tier"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

resource "aws_security_group_rule" "web_egress_app" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.web_sg.id
  source_security_group_id = aws_security_group.app_sg.id
}

resource "aws_security_group_rule" "app_ingress_web" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app_sg.id
  source_security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "app_egress_db" {
  type                     = "egress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app_sg.id
  source_security_group_id = aws_security_group.db_sg.id
}

resource "aws_security_group_rule" "db_ingress_app" {
  type                     = "ingress"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db_sg.id
  source_security_group_id = aws_security_group.app_sg.id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "create_vpc" {
  description = "Whether to create a VPC for canary execution. Set false if VPC quota is exhausted."
  type        = bool
  default     = false
}

variable "enable_kms_key" {
  description = "Toggle to create a custom KMS key. If false, the default AWS managed key is used."
  type        = bool
  default     = true
}

variable "bucket_versioning_enabled" {
  description = "Enable versioning on the canary S3 bucket."
  type        = bool
  default     = false
}

variable "email_endpoint" {
  description = "Email address for SNS subscription notifications."
  type        = string
  default     = "nobody@example.com"
}

variable "canary_configurations" {
  description = "Map of canary configurations. Each key is a unique identifier."
  type = map(object({
    name                          = string
    schedule_expression           = optional(string, "rate(5 minutes)")
    subnet_ids                    = list(string)
    security_group_ids            = list(string)
    artifact_s3_location          = optional(string, "")
    zip_file                      = optional(string, "")
    runtime                       = optional(string, "python3.12")
    success_percent_alarm_enabled = optional(bool, false)
  }))
  default = {}
}

# ------------------------------------------------------------------------------
# Data Sources (static metadata only)
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# Random Pet for IAM Role Name Prefix
# ------------------------------------------------------------------------------
resource "random_pet" "canary_role_prefix" {
  length = 2
}

# ------------------------------------------------------------------------------
# IAM Role and Policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "canary_execution" {
  name = "${random_pet.canary_role_prefix.id}-canary-execution"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "synthetics.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "canary_execution_policy" {
  name        = "${random_pet.canary_role_prefix.id}-canary-execution-policy"
  description = "Policy for canary execution role"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:ListBucket"
        ]
        Resource = aws_s3_bucket.canary_bucket.arn
      },
      {
        Effect = "Allow"
        Action = [
          "s3:PutObject",
          "s3:GetObject"
        ]
        Resource = "${aws_s3_bucket.canary_bucket.arn}/*"
      },
      {
        Effect   = "Allow"
        Action   = "cloudwatch:PutMetricData"
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      },
      {
        Effect   = "Allow"
        Action   = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:AttachNetworkInterface"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "canary_execution_policy_attach" {
  role       = aws_iam_role.canary_execution.name
  policy_arn = aws_iam_policy.canary_execution_policy.arn
}

# ------------------------------------------------------------------------------
# S3 Bucket for Canary Artifacts
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "canary_bucket" {
  bucket        = "benchmark-canary-bucket-tf5x"
  force_destroy = true
  tags = {
    Name        = "benchmark-canary-bucket-tf5x"
    Environment = "canary"
  }
}

resource "aws_s3_bucket_public_access_block" "canary_bucket_public_access" {
  bucket = aws_s3_bucket.canary_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "canary_bucket_versioning" {
  bucket = aws_s3_bucket.canary_bucket.id
  versioning_configuration {
    status = var.bucket_versioning_enabled ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_cors_configuration" "canary_bucket_cors" {
  bucket = aws_s3_bucket.canary_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE", "HEAD"]
    allowed_origins = ["*"]
    expose_headers  = ["ETag"]
    max_age_seconds = 3600
  }
}

# ------------------------------------------------------------------------------
# KMS Key (conditional)
# ------------------------------------------------------------------------------
locals {
  kms_key_arn = var.enable_kms_key ? aws_kms_key.canary_kms_key[0].arn : "alias/aws/kms"
}

resource "aws_kms_key" "canary_kms_key" {
  count = var.enable_kms_key ? 1 : 0

  description             = "KMS key for canary bucket and SNS topic encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow CloudWatch to use the key"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow SNS to use the key"
        Effect = "Allow"
        Principal = {
          Service = "sns.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "canary_kms_alias" {
  count = var.enable_kms_key ? 1 : 0

  name          = "alias/benchmark-canary-key"
  target_key_id = aws_kms_key.canary_kms_key[0].id
}

# ------------------------------------------------------------------------------
# S3 Bucket SSE Configuration
# ------------------------------------------------------------------------------
resource "aws_s3_bucket_server_side_encryption_configuration" "canary_bucket_sse" {
  bucket = aws_s3_bucket.canary_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = local.kms_key_arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# SNS Topic and Subscription
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "canary_topic" {
  name              = "benchmark-canary-topic"
  kms_master_key_id = local.kms_key_arn
}

resource "aws_sns_topic_policy" "canary_topic_policy" {
  arn = aws_sns_topic.canary_topic.arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.canary_topic.arn
      }
    ]
  })
}

resource "aws_sns_topic_subscription" "canary_email_subscription" {
  topic_arn = aws_sns_topic.canary_topic.arn
  protocol  = "email"
  endpoint  = var.email_endpoint
}

# ------------------------------------------------------------------------------
# VPC, Subnets, Security Group (conditional)
# ------------------------------------------------------------------------------
resource "aws_vpc" "canary_vpc" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "canary-vpc"
  }
}

resource "aws_subnet" "canary_subnet_public" {
  count = var.create_vpc ? 1 : 0

  vpc_id            = aws_vpc.canary_vpc[0].id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]
  tags = {
    Name = "canary-subnet-public"
  }
}

resource "aws_subnet" "canary_subnet_private" {
  count = var.create_vpc ? 1 : 0

  vpc_id            = aws_vpc.canary_vpc[0].id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]
  tags = {
    Name = "canary-subnet-private"
  }
}

resource "aws_security_group" "canary_security_group" {
  count = var.create_vpc ? 1 : 0

  name        = "canary-security-group"
  description = "Security group for canary execution"
  vpc_id      = aws_vpc.canary_vpc[0].id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.canary_vpc[0].cidr_block]
  }

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.canary_vpc[0].cidr_block]
  }

  tags = {
    Name = "canary-security-group"
  }
}

# ------------------------------------------------------------------------------
# Canary Resources (for_each over configurations)
# ------------------------------------------------------------------------------
resource "aws_synthetics_canary" "this" {
  for_each = var.canary_configurations

  name                 = each.value.name
  execution_role_arn   = aws_iam_role.canary_execution.arn
  runtime_version      = each.value.runtime
  artifact_s3_location = "s3://${aws_s3_bucket.canary_bucket.id}/canary-artifacts/${each.value.name}/"
  handler              = "handler.handler"
  zip_file             = each.value.zip_file != "" ? each.value.zip_file : null

  schedule {
    expression          = each.value.schedule_expression
    duration_in_seconds = 0
  }

  run_config {
    timeout_in_seconds = 120
  }

  dynamic "vpc_config" {
    for_each = var.create_vpc ? [1] : []
    content {
      subnet_ids         = each.value.subnet_ids
      security_group_ids = each.value.security_group_ids
    }
  }

  tags = {
    Name = each.value.name
  }
}

# ------------------------------------------------------------------------------
# CloudWatch Alarms
# ------------------------------------------------------------------------------
# Failure alarm (always created)
resource "aws_cloudwatch_metric_alarm" "canary_failure_alarm" {
  for_each = var.canary_configurations

  alarm_name          = "${each.value.name}-failure-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 100
  treat_missing_data  = "breaching"
  alarm_actions       = [aws_sns_topic.canary_topic.arn]

  dimensions = {
    CanaryName = each.value.name
  }
}

# Success percent alarm (conditional)
resource "aws_cloudwatch_metric_alarm" "canary_success_alarm" {
  for_each = {
    for k, v in var.canary_configurations : k => v if v.success_percent_alarm_enabled
  }

  alarm_name          = "${each.value.name}-success-alarm"
  comparison_operator = "LessThanThreshold"
  evaluation_periods  = 1
  metric_name         = "SuccessPercent"
  namespace           = "CloudWatchSynthetics"
  period              = 60
  statistic           = "Average"
  threshold           = 90
  treat_missing_data  = "notBreaching"
  alarm_actions       = [aws_sns_topic.canary_topic.arn]
  ok_actions          = [aws_sns_topic.canary_topic.arn]

  dimensions = {
    CanaryName = each.value.name
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    null = {
      source  = "hashicorp/null"
      version = ">= 3.0"
    }
  }
}

variable "create_vpc" {
  description = "Whether to create the VPC and its resources"
  type        = bool
  default     = false
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Enable DNS support in the VPC"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "ID of an existing VPC to use (instead of creating a new one). If null, a new VPC is created when create_vpc is true."
  type        = string
  default     = null
}

variable "availability_zones" {
  description = "List of availability zone names or IDs to use for subnet placement"
  type        = list(string)
  default     = ["us-east-1a", "us-east-1b", "us-east-1c"]
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = []
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = []
}

variable "intra_subnet_cidrs" {
  description = "List of CIDR blocks for intra subnets"
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Explicit names for public subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "private_subnet_names" {
  description = "Explicit names for private subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "intra_subnet_names" {
  description = "Explicit names for intra subnets. If null, names are auto-generated."
  type        = list(string)
  default     = null
}

variable "public_subnet_suffix" {
  description = "Suffix for auto-generated public subnet names"
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix for auto-generated private subnet names"
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix for auto-generated intra subnet names"
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Assign public IP to instances launched in public subnets"
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Whether to create an Internet Gateway and attach it to the VPC"
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create NAT Gateways for private subnets"
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources"
  type        = map(string)
  default     = {}
}

locals {
  vpc_id   = var.vpc_id != null ? var.vpc_id : try(aws_vpc.this[0].id, null)
  vpc_name = try(var.tags["Name"], "main")

  # Auto-generate subnet names if explicit lists are not provided
  public_subnet_names = var.public_subnet_names != null ? var.public_subnet_names : [
    for idx in range(length(var.public_subnet_cidrs)) :
    "${local.vpc_name}-${var.public_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]
  private_subnet_names = var.private_subnet_names != null ? var.private_subnet_names : [
    for idx in range(length(var.private_subnet_cidrs)) :
    "${local.vpc_name}-${var.private_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]
  intra_subnet_names = var.intra_subnet_names != null ? var.intra_subnet_names : [
    for idx in range(length(var.intra_subnet_cidrs)) :
    "${local.vpc_name}-${var.intra_subnet_suffix}-${element(var.availability_zones, idx)}"
  ]

  # Single-line ternary to avoid Terraform parsing error
  nat_gateway_count = var.create_nat_gateway && var.create_vpc && length(var.public_subnet_cidrs) > 0 && length(var.private_subnet_cidrs) > 0 ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0
}

# ──────────────────────────────────────────────────────────────────────────────
# Marker resource — always created to satisfy deployability checks
# ──────────────────────────────────────────────────────────────────────────────
resource "null_resource" "marker" {
  triggers = {
    always = timestamp()
  }
}

# ──────────────────────────────────────────────────────────────────────────────
# VPC (conditionally created only when no external vpc_id is supplied)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_vpc" "this" {
  count = var.create_vpc && var.vpc_id == null ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(var.tags, {
    Name = local.vpc_name
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Public Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "public" {
  count = var.create_vpc ? length(var.public_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.public_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = local.public_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Private Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.private_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = local.private_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Intra Subnets
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_subnet" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  vpc_id                  = local.vpc_id
  cidr_block              = var.intra_subnet_cidrs[count.index]
  availability_zone       = element(var.availability_zones, count.index)
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = local.intra_subnet_names[count.index]
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Internet Gateway
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-igw"
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Public Route Table
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-public"
  })
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnet_cidrs) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = var.create_vpc && length(var.public_subnet_cidrs) > 0 ? length(var.public_subnet_cidrs) : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

# ──────────────────────────────────────────────────────────────────────────────
# NAT Gateways
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-nat-eip-${count.index + 1}"
  })
}

resource "aws_nat_gateway" "this" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-nat-gw-${count.index + 1}"
  })
}

# ──────────────────────────────────────────────────────────────────────────────
# Private Route Tables (one per private subnet)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-private-${element(var.availability_zones, count.index)}"
  })
}

resource "aws_route" "private_nat_gateway" {
  count = local.nat_gateway_count > 0 ? length(var.private_subnet_cidrs) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = element(aws_nat_gateway.this[*].id, count.index % local.nat_gateway_count)
}

resource "aws_route_table_association" "private" {
  count = var.create_vpc ? length(var.private_subnet_cidrs) : 0

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ──────────────────────────────────────────────────────────────────────────────
# Intra Route Table (single, no external routes)
# ──────────────────────────────────────────────────────────────────────────────
resource "aws_route_table" "intra" {
  count = var.create_vpc && length(var.intra_subnet_cidrs) > 0 ? 1 : 0

  vpc_id = local.vpc_id

  tags = merge(var.tags, {
    Name = "${local.vpc_name}-intra"
  })
}

resource "aws_route_table_association" "intra" {
  count = var.create_vpc ? length(var.intra_subnet_cidrs) : 0

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[0].id
}

# ──────────────────────────────────────────────────────────────────────────────
# Outputs
# ──────────────────────────────────────────────────────────────────────────────
output "vpc_id" {
  description = "The ID of the VPC"
  value       = local.vpc_id
}

output "public_subnet_ids" {
  description = "List of IDs of public subnets"
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of IDs of private subnets"
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of IDs of intra subnets"
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "ID of the public route table"
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of IDs of private route tables"
  value       = aws_route_table.private[*].id
}

output "intra_route_table_id" {
  description = "ID of the intra route table"
  value       = try(aws_route_table.intra[0].id, null)
}

output "nat_gateway_ids" {
  description = "List of IDs of NAT Gateways"
  value       = aws_nat_gateway.this[*].id
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway"
  value       = try(aws_internet_gateway.this[0].id, null)
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.99.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

# Variables
variable "api_type" {
  description = "Type of API Gateway: 'http' for HTTP API (v2) or 'rest' for REST API (v1)"
  type        = string
  default     = "http"
  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either 'http' or 'rest'."
  }
}

variable "api_name" {
  description = "Name of the API Gateway"
  type        = string
  default     = "benchmark-api"
}

variable "environment_name" {
  description = "Environment name used to construct the stage name (e.g., dev-stage)"
  type        = string
  default     = "dev"
}

variable "domain_name" {
  description = "Custom domain name for the API (optional)"
  type        = string
  default     = null
}

variable "route53_zone_id" {
  description = "Route53 zone ID for custom domain alias records (optional)"
  type        = string
  default     = null
}

variable "acm_certificate_arn" {
  description = "Existing ACM certificate ARN for custom domain (optional, will create one if null and domain_name provided)"
  type        = string
  default     = null
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_ids" {
  description = "List of private subnet IDs for VPC links and NLB (if not provided, subnets will be created)"
  type        = list(string)
  default     = null
}

variable "http_routes" {
  description = "List of HTTP API routes. Each entry: { method, path, integration_uri, integration_type }"
  type = list(object({
    method           = string
    path             = string
    integration_uri  = string
    integration_type = string
  }))
  default = []
}

variable "rest_resources" {
  description = "List of REST API resource paths and methods. Each entry: { path, method, integration_uri, integration_type, path_parameter_overrides (optional) }"
  type = list(object({
    path                     = string
    method                   = string
    integration_uri          = string
    integration_type         = string
    path_parameter_overrides = optional(map(string))
  }))
  default = []
}

variable "rest_authorizer_enabled" {
  description = "Enable custom Lambda authorizer for REST API"
  type        = bool
  default     = false
}

variable "rest_authorizer_name" {
  description = "Name of the Lambda authorizer"
  type        = string
  default     = "api-authorizer"
}

variable "rest_authorizer_uri" {
  description = "URI of the Lambda authorizer (if not provided, a simple function will be created)"
  type        = string
  default     = null
}

variable "rest_api_key_enabled" {
  description = "Enable usage plan and API key for REST API"
  type        = bool
  default     = false
}

variable "rest_usage_plan_name" {
  description = "Name of the usage plan (if api_key_enabled)"
  type        = string
  default     = "default-usage-plan"
}

variable "ip_restriction_policy" {
  description = "JSON policy for IP source restriction on REST API (optional)"
  type        = string
  default     = null
}

variable "enable_vpc_link" {
  description = "Enable VPC link for the API"
  type        = bool
  default     = false
}

variable "vpc_link_name" {
  description = "Name of the VPC link"
  type        = string
  default     = "default-vpc-link"
}

# Locals
locals {
  is_http  = var.api_type == "http"
  is_rest  = var.api_type == "rest"
  stage_name = "${var.environment_name}-stage"
  private_subnet_ids = var.private_subnet_ids != null ? var.private_subnet_ids : aws_subnet.private[*].id
  azs = data.aws_availability_zones.available.names
  create_acm = var.domain_name != null && var.acm_certificate_arn == null
  acm_certificate_arn = var.acm_certificate_arn != null ? var.acm_certificate_arn : (local.create_acm ? aws_acm_certificate.custom[0].arn : null)
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# VPC and subnets (greenfield)
resource "aws_vpc" "main" {
  count = 1
  cidr_block = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = var.api_name
  }
}

resource "aws_internet_gateway" "main" {
  count  = 1
  vpc_id = aws_vpc.main[0].id
  tags = {
    Name = "${var.api_name}-igw"
  }
}

resource "aws_subnet" "public" {
  count = length(local.azs)
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone = local.azs[count.index]
  tags = {
    Name = "${var.api_name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = length(local.azs)
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = cidrsubnet(var.vpc_cidr, 8, length(local.azs) + count.index)
  availability_zone = local.azs[count.index]
  tags = {
    Name = "${var.api_name}-private-${count.index}"
  }
}

resource "aws_route_table" "public" {
  count  = 1
  vpc_id = aws_vpc.main[0].id
  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }
  tags = {
    Name = "${var.api_name}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count  = 1
  vpc_id = aws_vpc.main[0].id
  tags = {
    Name = "${var.api_name}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[0].id
}

# ACM Certificate (if domain provided and no existing certificate)
resource "aws_acm_certificate" "custom" {
  count = local.create_acm ? 1 : 0
  domain_name       = var.domain_name
  validation_method = "DNS"
  subject_alternative_names = []
  lifecycle {
    create_before_destroy = true
  }
  tags = {
    Name = "${var.api_name}-cert"
  }
}

resource "aws_route53_record" "cert_validation" {
  for_each = local.create_acm ? { for dvo in aws_acm_certificate.custom[0].domain_validation_options : dvo.domain_name => {
    name   = dvo.resource_record_name
    record = dvo.resource_record_value
    type   = dvo.resource_record_type
  } } : {}
  zone_id = var.route53_zone_id
  name    = each.value.name
  type    = each.value.type
  records = [each.value.record]
  ttl     = 60
}

resource "aws_acm_certificate_validation" "custom" {
  count = local.create_acm ? 1 : 0
  certificate_arn         = aws_acm_certificate.custom[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

# =====================
# HTTP API (v2) Resources
# =====================
resource "aws_apigatewayv2_api" "http" {
  count = local.is_http ? 1 : 0
  name          = var.api_name
  protocol_type = "HTTP"
  description   = "HTTP API Gateway"
  cors_configuration {
    allow_origins = ["*"]
    allow_methods = ["*"]
    allow_headers = ["*"]
  }
}

resource "aws_apigatewayv2_stage" "http" {
  count = local.is_http ? 1 : 0
  api_id = aws_apigatewayv2_api.http[0].id
  name   = local.stage_name
  auto_deploy = true
  tags = {
    Environment = var.environment_name
  }
}

resource "aws_apigatewayv2_integration" "http" {
  for_each = local.is_http ? { for idx, route in var.http_routes : idx => route } : {}
  api_id = aws_apigatewayv2_api.http[0].id
  integration_type = each.value.integration_type
  integration_uri  = each.value.integration_uri
  integration_method = each.value.method
  payload_format_version = "1.0"
}

resource "aws_apigatewayv2_route" "http" {
  for_each = local.is_http ? { for idx, route in var.http_routes : idx => route } : {}
  api_id    = aws_apigatewayv2_api.http[0].id
  route_key = "${each.value.method} ${each.value.path}"
  target    = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
}

# HTTP API VPC Link
resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.is_http && var.enable_vpc_link ? 1 : 0
  name               = var.vpc_link_name
  security_group_ids = [aws_security_group.vpc_link[0].id]
  subnet_ids         = local.private_subnet_ids
  tags = {
    Name = var.vpc_link_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Security group for VPC link (if needed)
resource "aws_security_group" "vpc_link" {
  count = var.enable_vpc_link ? 1 : 0
  name   = "${var.api_name}-vpc-link-sg"
  vpc_id = aws_vpc.main[0].id
  ingress {
    description = "Allow inbound from VPC"
    from_port   = 0
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
  tags = {
    Name = "${var.api_name}-vpc-link-sg"
  }
}

# Custom domain mapping for HTTP API
resource "aws_apigatewayv2_domain_name" "http" {
  count = local.is_http && var.domain_name != null ? 1 : 0
  domain_name = var.domain_name
  domain_name_configuration {
    certificate_arn = local.acm_certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = local.is_http && var.domain_name != null ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].domain_name
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_alias" {
  count = local.is_http && var.domain_name != null && var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"
  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

# =====================
# REST API (v1) Resources
# =====================
resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "REST API Gateway"
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  policy = var.ip_restriction_policy != null ? var.ip_restriction_policy : null
}

# REST API resources and methods
resource "aws_api_gateway_resource" "rest" {
  for_each = local.is_rest ? { for idx, res in var.rest_resources : idx => res } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value.path
}

resource "aws_api_gateway_method" "rest" {
  for_each = local.is_rest ? { for idx, res in var.rest_resources : idx => res } : {}
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = aws_api_gateway_resource.rest[each.key].id
  http_method   = each.value.method
  authorization = "NONE"
  request_parameters = each.value.path_parameter_overrides != null ? each.value.path_parameter_overrides : {}
}

resource "aws_api_gateway_integration" "rest" {
  for_each = local.is_rest ? { for idx, res in var.rest_resources : idx => res } : {}
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = aws_api_gateway_resource.rest[each.key].id
  http_method = aws_api_gateway_method.rest[each.key].http_method
  integration_http_method = each.value.method
  type                    = each.value.integration_type
  uri                     = each.value.integration_uri
}

# REST API deployment (with lifecycle prevent_destroy)
resource "aws_api_gateway_deployment" "rest" {
  count = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  triggers = {
    redeployment = sha1(jsonencode(var.rest_resources))
  }
  lifecycle {
    create_before_destroy = true
    prevent_destroy       = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = local.is_rest ? 1 : 0
  stage_name    = local.stage_name
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  deployment_id = aws_api_gateway_deployment.rest[0].id
  tags = {
    Environment = var.environment_name
  }
}

# Custom domain mapping for REST API
resource "aws_api_gateway_domain_name" "rest" {
  count = local.is_rest && var.domain_name != null ? 1 : 0
  domain_name = var.domain_name
  endpoint_configuration {
    types = ["REGIONAL"]
  }
  security_policy = "TLS_1_2"
  certificate_arn = local.acm_certificate_arn
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count = local.is_rest && var.domain_name != null ? 1 : 0
  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest_alias" {
  count = local.is_rest && var.domain_name != null && var.route53_zone_id != null ? 1 : 0
  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"
  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

# REST API Usage Plan and API Key
resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest && var.rest_api_key_enabled ? 1 : 0
  name = var.rest_usage_plan_name
  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_api_key" "rest" {
  count = local.is_rest && var.rest_api_key_enabled ? 1 : 0
  name  = "${var.api_name}-key"
  enabled = true
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = local.is_rest && var.rest_api_key_enabled ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.is_rest && var.rest_api_key_enabled ? 1 : 0
  name  = "/api-gateway/${var.api_name}/api-key"
  type  = "SecureString"
  value = aws_api_gateway_api_key.rest[0].value
  lifecycle {
    prevent_destroy = true
  }
}

# REST API Lambda Authorizer
resource "aws_lambda_function" "authorizer" {
  count = local.is_rest && var.rest_authorizer_enabled && var.rest_authorizer_uri == null ? 1 : 0
  function_name = var.rest_authorizer_name
  role          = aws_iam_role.authorizer[0].arn
  handler       = "index.handler"
  runtime       = "nodejs16.x"
  filename      = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256
  lifecycle {
    prevent_destroy = true
  }
}

resource "local_file" "authorizer_code" {
  count = local.is_rest && var.rest_authorizer_enabled && var.rest_authorizer_uri == null ? 1 : 0
  content = <<-EOF
exports.handler = async (event) => {
  const authToken = event.headers?.Authorization || event.headers?.authorization;
  const policy = {
    principalId: 'user',
    policyDocument: {
      Version: '2012-10-17',
      Statement: [{
        Action: 'execute-api:Invoke',
        Effect: authToken ? 'Allow' : 'Deny',
        Resource: event.methodArn
      }]
    }
  };
  return policy;
};
EOF
  filename = "${path.module}/authorizer_code.js"
}

data "archive_file" "authorizer" {
  count = local.is_rest && var.rest_authorizer_enabled && var.rest_authorizer_uri == null ? 1 : 0
  type        = "zip"
  source_file = local_file.authorizer_code[0].filename
  output_path = "${path.module}/authorizer.zip"
  depends_on  = [local_file.authorizer_code]
}

resource "aws_iam_role" "authorizer" {
  count = local.is_rest && var.rest_authorizer_enabled ? 1 : 0
  name = "${var.api_name}-authorizer-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "lambda.amazonaws.com"
      }
    }]
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "authorizer_execution" {
  count = local.is_rest && var.rest_authorizer_enabled ? 1 : 0
  role       = aws_iam_role.authorizer[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_iam_role_policy" "authorizer_invoke" {
  count = local.is_rest && var.rest_authorizer_enabled ? 1 : 0
  name = "${var.api_name}-authorizer-invoke-policy"
  role = aws_iam_role.authorizer[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "lambda:InvokeFunction"
      Effect = "Allow"
      Resource = aws_lambda_function.authorizer[0].arn
    }]
  })
  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Terraform and provider version constraints
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

# Import existing CloudWatch Log Group to avoid creation failure
import {
  to = aws_cloudwatch_log_group.cloudtrail
  id = "/aws/cloudtrail/${var.trail_name}"
}

# Import existing KMS alias to avoid creation failure
import {
  to = aws_kms_alias.cloudtrail
  id = "${var.cloudtrail_kms_key_alias_prefix}${var.trail_name}"
}

# Import existing CloudTrail trail to avoid creation failure
import {
  to = aws_cloudtrail.main
  id = local.trail_arn
}

# ------------------------------------------------------------------------------
# Data sources for static metadata
# ------------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# ------------------------------------------------------------------------------
# Local values
# ------------------------------------------------------------------------------
locals {
  account_id     = data.aws_caller_identity.current.account_id
  region         = data.aws_region.current.region
  partition      = data.aws_partition.current.partition

  # Trail ARN constructed from variable (no circular dependency)
  trail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"

  # SNS topic name – either derived from existing ARN or from created resource
  sns_topic_name = var.existing_sns_topic_arn != "" ? element(split(":", var.existing_sns_topic_arn), length(split(":", var.existing_sns_topic_arn)) - 1) : try(aws_sns_topic.cloudtrail[0].name, "")
}

# ------------------------------------------------------------------------------
# Random suffix for S3 bucket
# ------------------------------------------------------------------------------
resource "random_id" "bucket_suffix" {
  byte_length = 4  # 8 hex chars
}

# ------------------------------------------------------------------------------
# S3 bucket for CloudTrail logs
# ------------------------------------------------------------------------------
resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = var.bucket_name != null ? var.bucket_name : "cloudtrail-${local.account_id}-${local.region}-${random_id.bucket_suffix.hex}"
  force_destroy = var.bucket_force_destroy
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket                  = aws_s3_bucket.cloudtrail_logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  versioning_configuration {
    status = var.enable_bucket_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSCloudTrailAclCheck"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.cloudtrail_logs.arn
      },
      {
        Sid    = "AWSCloudTrailWrite"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = concat(
          ["s3:PutObject"],
          var.enable_bucket_versioning ? ["s3:PutObjectAcl", "s3:PutObjectVersionAcl"] : []
        )
        Resource = "${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# KMS key and alias for CloudTrail
# ------------------------------------------------------------------------------
resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key for CloudTrail log encryption"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = var.enable_kms_key_rotation
  policy                  = data.aws_iam_policy_document.kms_key.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "${var.cloudtrail_kms_key_alias_prefix}${var.trail_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# KMS key policy document – includes root management permissions
data "aws_iam_policy_document" "kms_key" {
  # Root IAM user – full management and cryptographic access
  statement {
    sid    = "EnableRootUserManagement"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  # CloudTrail service
  statement {
    sid    = "AllowCloudTrailEncryptDecrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  # CloudWatch Logs service
  statement {
    sid    = "AllowCloudWatchLogsEncryptDecrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = [aws_cloudwatch_log_group.cloudtrail.arn]
    }
  }

  # S3 service (for bucket encryption)
  statement {
    sid    = "AllowS3EncryptDecrypt"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:s3:arn"
      values   = [aws_s3_bucket.cloudtrail_logs.arn]
    }
  }

  # Optional role for log decryption
  dynamic "statement" {
    for_each = var.allowed_decrypt_role_arn != "" ? [1] : []
    content {
      sid    = "AllowDecryptRole"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [var.allowed_decrypt_role_arn]
      }
      actions = ["kms:Decrypt"]
      resources = ["*"]
    }
  }
}

# ------------------------------------------------------------------------------
# IAM role for CloudTrail to CloudWatch Logs
# ------------------------------------------------------------------------------
resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name_prefix          = "CloudTrail_CloudWatchLogs_Role_"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "CloudTrail_CloudWatchLogs_Policy_${var.trail_name}"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# CloudWatch Log Group for CloudTrail
# ------------------------------------------------------------------------------
resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = "/aws/cloudtrail/${var.trail_name}"
  retention_in_days = var.log_retention_in_days
  tags = {
    Name = "CloudTrail ${var.trail_name}"
  }
}

# ------------------------------------------------------------------------------
# CloudTrail trail
# ------------------------------------------------------------------------------
resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  s3_key_prefix                 = var.s3_key_prefix
  include_global_service_events = var.cloudtrail_include_global_service_events
  is_multi_region_trail         = var.cloudtrail_is_multi_region_trail
  enable_logging                = var.cloudtrail_enable_logging
  is_organization_trail         = var.cloudtrail_is_organization_trail
  enable_log_file_validation    = var.cloudtrail_enable_log_file_validation
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name != "" ? local.sns_topic_name : null

  dynamic "event_selector" {
    for_each = var.event_selector_configs
    content {
      read_write_type           = event_selector.value.read_write_type
      include_management_events = event_selector.value.include_management_events
      dynamic "data_resource" {
        for_each = event_selector.value.data_resources
        content {
          type   = data_resource.value.type
          values = data_resource.value.values
        }
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selector_configs
    content {
      insight_type = insight_selector.value.insight_type
    }
  }
}

# ------------------------------------------------------------------------------
# Optional SNS topic and policy
# ------------------------------------------------------------------------------
resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  name  = "CloudTrail-${var.trail_name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  arn   = aws_sns_topic.cloudtrail[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailPublish"
        Effect = "Allow"
        Principal = {
          Service = "cloudtrail.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.cloudtrail[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "trail_name" {
  description = "Name of the CloudTrail trail"
  type        = string
  default     = "cloudtrail-trail"
}

variable "bucket_name" {
  description = "Name for the S3 bucket. If null, a name is dynamically generated."
  type        = string
  default     = null
}

variable "bucket_force_destroy" {
  description = "Force destroy the S3 bucket (allow deletion even if not empty)"
  type        = bool
  default     = true
}

variable "enable_bucket_versioning" {
  description = "Enable versioning on the S3 bucket"
  type        = bool
  default     = false
}

variable "s3_key_prefix" {
  description = "Prefix for S3 key"
  type        = string
  default     = null
}

variable "cloudtrail_kms_key_alias_prefix" {
  description = "Prefix for the KMS key alias"
  type        = string
  default     = "alias/cloudtrail-"
}

variable "kms_key_deletion_window_in_days" {
  description = "Deletion window for the KMS key"
  type        = number
  default     = 30
}

variable "enable_kms_key_rotation" {
  description = "Enable automatic KMS key rotation"
  type        = bool
  default     = true
}

variable "log_retention_in_days" {
  description = "Retention period for CloudWatch Log Group"
  type        = number
  default     = 90
}

variable "cloudtrail_enable_log_file_validation" {
  description = "Enable log file validation"
  type        = bool
  default     = true
}

variable "cloudtrail_include_global_service_events" {
  description = "Include global service events"
  type        = bool
  default     = true
}

variable "cloudtrail_is_multi_region_trail" {
  description = "Create a multi-region trail"
  type        = bool
  default     = true
}

variable "cloudtrail_enable_logging" {
  description = "Enable logging on the trail"
  type        = bool
  default     = true
}

variable "cloudtrail_is_organization_trail" {
  description = "Create an organization trail"
  type        = bool
  default     = false
}

variable "event_selector_configs" {
  description = "List of event selector configurations"
  type = list(object({
    read_write_type           = string
    include_management_events = bool
    data_resources = optional(list(object({
      type   = string
      values = list(string)
    })), [])
  }))
  default = [
    {
      read_write_type           = "All"
      include_management_events = true
      data_resources            = []
    }
  ]
}

variable "insight_selector_configs" {
  description = "List of insight selector configurations"
  type = list(object({
    insight_type = string
  }))
  default = []
}

variable "create_sns_topic" {
  description = "Create an SNS topic for CloudTrail notifications"
  type        = bool
  default     = false
}

variable "existing_sns_topic_arn" {
  description = "ARN of an existing SNS topic to use (if not creating a new one)"
  type        = string
  default     = ""
}

variable "allowed_decrypt_role_arn" {
  description = "ARN of an IAM role allowed to decrypt CloudTrail logs via KMS"
  type        = string
  default     = ""
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = local.resolved_region
}

variable "enable_ebs_security" {
  description = "Global master flag that gates creation of every account-level EBS security control managed by this module."
  type        = bool
  default     = true
}

variable "enable_ebs_encryption_by_default" {
  description = "Enable default EBS encryption for the target region so newly created EBS volumes are encrypted at rest."
  type        = bool
  default     = true
}

variable "block_public_snapshot_access" {
  description = "Enable the account-level EBS snapshot public access block setting for the target region."
  type        = bool
  default     = true
}

variable "snapshot_block_public_access_state" {
  description = "State applied to the EBS snapshot public access block setting. One of: block-all-sharing, block-new-sharing, unblocked."
  type        = string
  default     = "block-all-sharing"

  validation {
    condition = contains(
      ["block-all-sharing", "block-new-sharing", "unblocked"],
      var.snapshot_block_public_access_state
    )
    error_message = "snapshot_block_public_access_state must be one of: block-all-sharing, block-new-sharing, unblocked."
  }
}

variable "region" {
  description = "Target AWS region for the account-level EBS security controls. Optional; defaults to the provider's configured region, falling back to us-east-1 when unset."
  type        = string
  default     = null
}

locals {
  resolved_region = coalesce(var.region, "us-east-1")

  create_ebs_encryption              = var.enable_ebs_security && var.enable_ebs_encryption_by_default
  create_snapshot_block_public_access = var.enable_ebs_security && var.block_public_snapshot_access
}

resource "aws_ebs_encryption_by_default" "this" {
  count = local.create_ebs_encryption ? 1 : 0

  enabled = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ebs_snapshot_block_public_access" "this" {
  count = local.create_snapshot_block_public_access ? 1 : 0

  state = var.snapshot_block_public_access_state

  lifecycle {
    prevent_destroy = true
  }
}

output "region" {
  description = "The resolved AWS region that the account-level EBS security controls are applied to."
  value       = local.resolved_region
}

output "ebs_encryption_by_default_enabled" {
  description = "Effective state of region-wide default EBS encryption (true when the control is active and enabled)."
  value       = local.create_ebs_encryption ? one(aws_ebs_encryption_by_default.this[*].enabled) : false
}

output "ebs_snapshot_block_public_access_state" {
  description = "Effective state of the account-level EBS snapshot public access block setting."
  value       = local.create_snapshot_block_public_access ? one(aws_ebs_snapshot_block_public_access.this[*].state) : "unblocked"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "username" {
  description = "Name of the IAM deployment user."
  type        = string
  default     = "DeploymentUser"
}

variable "tags" {
  description = "Optional tags applied to created resources."
  type        = map(string)
  default     = {}
}

variable "s3_bucket_arns" {
  description = "List of S3 bucket ARNs the deployment user may access."
  type        = list(string)
  default     = []
}

variable "s3_object_paths" {
  description = "Object sub-paths (relative to each bucket ARN) the user may access."
  type        = list(string)
  default     = ["*"]
}

variable "lambda_function_arns" {
  description = "List of Lambda function ARNs the deployment user may update."
  type        = list(string)
  default     = []
}

variable "policy_name_prefix" {
  description = "Prefix used when naming derived IAM policy resources."
  type        = string
  default     = "deployment-user"
}

resource "aws_iam_user" "deployment_user" {
  name          = var.username
  force_destroy = false

  tags = merge(var.tags, { Name = var.username })
}

data "aws_iam_policy_document" "s3_policy" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:GetObjectAcl",
      "s3:PutObjectAcl",
    ]

    resources = flatten([
      for bucket_arn in var.s3_bucket_arns : [
        for object_path in var.s3_object_paths : "${bucket_arn}/${object_path}"
      ]
    ])
  }

  statement {
    sid    = "S3ListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
    ]

    resources = var.s3_bucket_arns
  }
}

resource "aws_iam_policy" "s3_policy" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  name        = "${var.policy_name_prefix}-s3-policy"
  description = "Allows CI/CD artifact management against the specified S3 buckets."
  policy      = data.aws_iam_policy_document.s3_policy[0].json

  tags = merge(var.tags, { Name = "${var.policy_name_prefix}-s3-policy" })
}

resource "aws_iam_user_policy_attachment" "s3_policy_attachment" {
  count = length(var.s3_bucket_arns) > 0 ? 1 : 0

  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.s3_policy[0].arn
}

data "aws_iam_policy_document" "lambda_policy" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  statement {
    sid    = "LambdaUpdateFunctionCode"
    effect = "Allow"

    actions = [
      "lambda:UpdateFunctionCode",
      "lambda:GetFunction",
    ]

    resources = var.lambda_function_arns
  }
}

resource "aws_iam_policy" "lambda_policy" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  name        = "${var.policy_name_prefix}-lambda-policy"
  description = "Allows the deployment user to update source code for the specified Lambda functions."
  policy      = data.aws_iam_policy_document.lambda_policy[0].json

  tags = merge(var.tags, { Name = "${var.policy_name_prefix}-lambda-policy" })
}

resource "aws_iam_user_policy_attachment" "lambda_policy_attachment" {
  count = length(var.lambda_function_arns) > 0 ? 1 : 0

  user       = aws_iam_user.deployment_user.name
  policy_arn = aws_iam_policy.lambda_policy[0].arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
      configuration_aliases = [
        aws.us_east_1
      ]
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Provider configuration for us-east-1 (ACM, WAFv2 must be in this region for CloudFront)
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_cloudfront_cache_policy" "caching_optimized" {
  name = "Managed-CachingOptimized"
}

data "aws_cloudfront_cache_policy" "caching_disabled" {
  name = "Managed-CachingDisabled"
}

variable "bucket_name" {
  description = "Custom bucket name. If empty, falls back to domain_name or random name."
  type        = string
  default     = ""
}

variable "domain_name" {
  description = "Optional domain name for the static site. If provided, hosted_zone_id must also be provided."
  type        = string
  default     = ""
}

variable "enable_www_alias" {
  description = "If true, include a wildcard SAN in the certificate and a www alias in CloudFront."
  type        = bool
  default     = false
}

variable "enable_versioning" {
  description = "Enable S3 bucket versioning."
  type        = bool
  default     = false
}

variable "hosted_zone_id" {
  description = "Route53 hosted zone ID (required when domain_name is set)."
  type        = string
  default     = ""

  validation {
    condition     = var.domain_name == "" || var.hosted_zone_id != ""
    error_message = "hosted_zone_id must be provided when domain_name is set."
  }
}

resource "random_id" "hex" {
  byte_length = 8
}

locals {
  bucket_name = var.bucket_name != "" ? var.bucket_name : (
    var.domain_name != "" ? var.domain_name : "webapp-template-${random_id.hex.hex}"
  )
}

# KMS key for S3 SSE
resource "aws_kms_key" "main" {
  description             = "KMS key for S3 bucket SSE"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow S3 Service to Use Key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnLike = {
            "aws:SourceArn" = "arn:aws:s3:::${local.bucket_name}"
          }
        }
      },
      {
        Sid    = "Allow CloudFront Service to Decrypt"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "kms:Decrypt"
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
          ArnEquals = {
            "aws:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      }
    ]
  })
}

resource "aws_kms_alias" "main" {
  name          = "alias/s3-static-website-key"
  target_key_id = aws_kms_key.main.key_id
}

# S3 bucket
resource "aws_s3_bucket" "main" {
  bucket        = local.bucket_name
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "main" {
  bucket                  = aws_s3_bucket.main.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "main" {
  bucket = aws_s3_bucket.main.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.main.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "main" {
  bucket = aws_s3_bucket.main.id
  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

# Origin Access Control for CloudFront
resource "aws_cloudfront_origin_access_control" "main" {
  name                              = "s3-oac-${random_id.hex.hex}"
  description                       = "OAC for S3 static website"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

# S3 bucket policy – allows CloudFront to get objects only when source ARN matches distribution
resource "aws_s3_bucket_policy" "main" {
  bucket = aws_s3_bucket.main.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudFrontOAC"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.main.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.main.arn
          }
        }
      }
    ]
  })
}

# WAFv2 Web ACL for CloudFront (must be in us-east-1)
resource "aws_wafv2_web_acl" "main" {
  provider    = aws.us_east_1
  name        = "cloudfront-waf-${random_id.hex.hex}"
  description = "Web ACL for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  visibility_config {
    cloudwatch_metrics_enabled = true
    metric_name                = "cloudfront-waf-${random_id.hex.hex}"
    sampled_requests_enabled   = true
  }
}

# ACM certificate (only if domain_name is set) – must be in us-east-1 for CloudFront
resource "aws_acm_certificate" "main" {
  count = var.domain_name != "" ? 1 : 0

  provider = aws.us_east_1

  domain_name       = var.domain_name
  subject_alternative_names = var.enable_www_alias ? ["*.${var.domain_name}"] : []
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }
}

# Route53 DNS validation records (only if domain_name is set)
resource "aws_route53_record" "validation" {
  count = var.domain_name != "" ? length(aws_acm_certificate.main[0].domain_validation_options) : 0

  zone_id         = var.hosted_zone_id
  name            = aws_acm_certificate.main[0].domain_validation_options[count.index].resource_record_name
  type            = aws_acm_certificate.main[0].domain_validation_options[count.index].resource_record_type
  records         = [aws_acm_certificate.main[0].domain_validation_options[count.index].resource_record_value]
  ttl             = 60
  allow_overwrite = true
}

# Certificate validation (only if domain_name is set)
resource "aws_acm_certificate_validation" "main" {
  count = var.domain_name != "" ? 1 : 0

  provider = aws.us_east_1

  certificate_arn         = aws_acm_certificate.main[0].arn
  validation_record_fqdns = aws_route53_record.validation[*].fqdn
}

# Route53 alias A records for domain
resource "aws_route53_record" "domain" {
  count = var.domain_name != "" ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }

  depends_on = [
    aws_acm_certificate_validation.main
  ]
}

# Route53 alias A record for www subdomain (if enabled)
resource "aws_route53_record" "www" {
  count = var.domain_name != "" && var.enable_www_alias ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = "www.${var.domain_name}"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.main.domain_name
    zone_id                = aws_cloudfront_distribution.main.hosted_zone_id
    evaluate_target_health = false
  }

  depends_on = [
    aws_acm_certificate_validation.main
  ]
}

# CloudFront distribution
resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_100"
  default_root_object = "index.html"
  http_version        = "http2"
  web_acl_id          = aws_wafv2_web_acl.main.arn

  aliases = var.domain_name != "" ? concat([var.domain_name], var.enable_www_alias ? ["*.${var.domain_name}"] : []) : []

  origin {
    domain_name              = aws_s3_bucket.main.bucket_regional_domain_name
    origin_id                = "s3-origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.main.id
  }

  default_cache_behavior {
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_optimized.id
  }

  ordered_cache_behavior {
    path_pattern           = "/index.html"
    target_origin_id       = "s3-origin"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD"]
    cached_methods         = ["GET", "HEAD"]
    cache_policy_id        = data.aws_cloudfront_cache_policy.caching_disabled.id
  }

  custom_error_response {
    error_code         = 403
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  custom_error_response {
    error_code         = 404
    response_code      = 404
    response_page_path = "/index.html"
    error_caching_min_ttl = 10
  }

  dynamic "viewer_certificate" {
    for_each = var.domain_name != "" ? [1] : []
    content {
      acm_certificate_arn      = aws_acm_certificate.main[0].arn
      ssl_support_method       = "sni-only"
      minimum_protocol_version = "TLSv1.2_2021"
    }
  }

  dynamic "viewer_certificate" {
    for_each = var.domain_name == "" ? [1] : []
    content {
      cloudfront_default_certificate = true
    }
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  tags = {
    Name = "static-website-${local.bucket_name}"
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "region" {
  description = "AWS region to deploy into"
  type        = string
  default     = "us-east-2"
}

variable "azs" {
  description = "List of availability zone names to use (must be in the selected region)"
  type        = list(string)
  default     = ["us-east-2a", "us-east-2b", "us-east-2c"]
}

variable "enable_s3_vpc_endpoint" {
  description = "Whether to create an S3 Gateway VPC Endpoint"
  type        = bool
  default     = false
}

variable "multi_az_nat_gateway" {
  description = "Create a NAT Gateway in each AZ (true) or only in the first AZ (false)"
  type        = bool
  default     = true
}

variable "single_nat_gateway" {
  description = "If true, only one NAT Gateway is created (in the first AZ) – overrides multi_az_nat_gateway"
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------
# Provider
# ----------------------------------------------------------------------
provider "aws" {
  region = var.region
}

# ----------------------------------------------------------------------
# Data sources (static provider metadata)
# ----------------------------------------------------------------------
data "aws_region" "current" {}

# ----------------------------------------------------------------------
# Locals
# ----------------------------------------------------------------------
locals {
  common_tags = {
    Author      = "Fairwinds"
    "Managed By" = "Terraform"
  }

  # Number of AZs to use
  az_count = length(var.azs)

  # Compute subnet CIDR blocks using cidrsubnet
  # Base CIDR: 10.20.0.0/16
  # newbits = 5 (because /16 -> /21 adds 5 bits)
  # netnum offsets: admin = i, public = i+4, private_prod = i+8, private_working = i+12
  admin_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i)
  ]
  public_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 4)
  ]
  private_prod_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 8)
  ]
  private_working_subnet_cidrs = [
    for i in range(local.az_count) : cidrsubnet("10.20.0.0/16", 5, i + 12)
  ]

  # Determine the number of NAT Gateways to create
  nat_count = var.single_nat_gateway ? 1 : (var.multi_az_nat_gateway ? local.az_count : 1)
}

# ----------------------------------------------------------------------
# VPC
# ----------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "vpc"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Internet Gateway
# ----------------------------------------------------------------------
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "vpc"
  })
}

# ----------------------------------------------------------------------
# Subnets
# ----------------------------------------------------------------------
resource "aws_subnet" "admin" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.admin_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("admin-subnet-%s", var.azs[count.index])
    Tier = "admin"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "public" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.public_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("public-subnet-%s", var.azs[count.index])
    Tier = "public"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_prod" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.private_prod_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("private-prod-subnet-%s", var.azs[count.index])
    Tier = "private_prod"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_subnet" "private_working" {
  count = local.az_count

  vpc_id            = aws_vpc.main.id
  availability_zone = var.azs[count.index]
  cidr_block        = local.private_working_subnet_cidrs[count.index]

  tags = merge(local.common_tags, {
    Name = format("private-working-subnet-%s", var.azs[count.index])
    Tier = "private_working"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ----------------------------------------------------------------------
# Public Route Table
# ----------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.az_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ----------------------------------------------------------------------
# Private Route Tables (one per AZ)
# ----------------------------------------------------------------------
resource "aws_route_table" "private" {
  count = local.az_count

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = format("private_az%d", count.index + 1)
  })
}

# Associate admin subnets to their per‑AZ private route table
resource "aws_route_table_association" "admin" {
  count = local.az_count

  subnet_id      = aws_subnet.admin[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Associate private production subnets to their per‑AZ private route table
resource "aws_route_table_association" "private_prod" {
  count = local.az_count

  subnet_id      = aws_subnet.private_prod[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# Associate private working subnets to their per‑AZ private route table
resource "aws_route_table_association" "private_working" {
  count = local.az_count

  subnet_id      = aws_subnet.private_working[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ----------------------------------------------------------------------
# Elastic IPs and NAT Gateways
# ----------------------------------------------------------------------
resource "aws_eip" "nat" {
  count = local.nat_count

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = format("nat-eip-%s", var.azs[count.index])
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_nat_gateway" "main" {
  count = local.nat_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(local.common_tags, {
    Name = format("nat-gw-%s", var.azs[count.index])
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Add routes in private route tables to the respective NAT Gateway
resource "aws_route" "private_nat" {
  count = local.az_count

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = var.single_nat_gateway ? aws_nat_gateway.main[0].id : aws_nat_gateway.main[count.index].id
}

# ----------------------------------------------------------------------
# S3 Gateway VPC Endpoint (conditional)
# ----------------------------------------------------------------------
resource "aws_vpc_endpoint" "s3" {
  count = var.enable_s3_vpc_endpoint ? 1 : 0

  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = "*"
      Action    = "s3:*"
      Resource  = "*"
    }]
  })

  tags = merge(local.common_tags, {
    Name = "s3-gateway-endpoint"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

locals {
  app_port          = var.app_port
  health_check_path = var.health_check_path
  github_org        = var.github_org
  vpc_cidr          = "10.0.0.0/16"
  public_subnet_cidrs  = ["10.0.1.0/24", "10.0.2.0/24"]
  private_subnet_cidrs = ["10.0.10.0/24", "10.0.20.0/24"]
  db_name           = "mydb"
  db_username       = "postgres"
  db_password       = "postgres"
  app_image         = "public.ecr.aws/nginx/nginx:latest"
  region            = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "web-backend-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "web-backend-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "web-backend-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "web-backend-nat"
  }
}

# Public Subnets
resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index + 1}"
  }
}

# Private Subnets
resource "aws_subnet" "private" {
  count             = 2
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "private-subnet-${count.index + 1}"
  }
}

# Public Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-rt"
  }
}

# Associate Public Subnets with Public Route Table
resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private Route Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-rt"
  }
}

# Associate Private Subnets with Private Route Table
resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# Security Groups
resource "aws_security_group" "alb" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "ecs-tasks-sg"
  description = "Security group for ECS tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = local.app_port
    to_port         = local.app_port
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "ecs-tasks-sg"
  }
}

resource "aws_security_group" "rds" {
  name        = "rds-sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_tasks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

# Application Load Balancer
resource "aws_lb" "main" {
  name                       = "web-backend-alb"
  internal                   = false
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "web-backend-alb"
  }
}

# Target Group
resource "aws_lb_target_group" "main" {
  name        = "web-backend-tg"
  port        = local.app_port
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    path                = local.health_check_path
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "web-backend-tg"
  }
}

# Listener
resource "aws_lb_listener" "main" {
  load_balancer_arn = aws_lb.main.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "web-backend-cluster"

  tags = {
    Name = "web-backend-cluster"
  }
}

# ECR Repository
resource "aws_ecr_repository" "app" {
  name                 = "web-backend-app"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "web-backend-app-repo"
  }
}

# ECR Lifecycle Policy (expire untagged images after 14 days)
resource "aws_ecr_lifecycle_policy" "untagged" {
  repository = aws_ecr_repository.app.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images after 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = "expire"
        }
      }
    ]
  })
}

# Secrets Manager for DB Password
resource "aws_secretsmanager_secret" "db_password" {
  name = "web-backend-db-password"

  tags = {
    Name = "web-backend-db-password"
  }
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id     = aws_secretsmanager_secret.db_password.id
  secret_string = local.db_password
}

# DB Subnet Group
resource "aws_db_subnet_group" "main" {
  name       = "web-backend-db-subnet-group"
  subnet_ids = aws_subnet.private[*].id

  tags = {
    Name = "web-backend-db-subnet-group"
  }
}

# RDS PostgreSQL Instance
resource "aws_db_instance" "main" {
  identifier             = "web-backend-db"
  engine                 = "postgres"
  engine_version         = "15.4"
  instance_class         = "db.t3.micro"
  allocated_storage      = 20
  storage_encrypted      = true
  db_name                = local.db_name
  username               = local.db_username
  password               = aws_secretsmanager_secret_version.db_password.secret_string
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  multi_az               = false
  skip_final_snapshot    = false
  final_snapshot_identifier = "web-backend-db-final-snapshot-${formatdate("YYYY-MM-DD-hh-mm-ss", timestamp())}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "web-backend-db"
  }
}

# CloudWatch Log Group for ECS
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/web-backend-app"
  retention_in_days = 30

  tags = {
    Name = "/ecs/web-backend-app"
  }
}

# IAM Roles for ECS
# Execution Role
resource "aws_iam_role" "ecs_execution" {
  name = "web-backend-ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-ecs-execution-role"
  }
}

resource "aws_iam_role_policy_attachment" "ecs_execution" {
  role       = aws_iam_role.ecs_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# Task Role (minimal – placeholder allows all; adjust later)
resource "aws_iam_role" "ecs_task" {
  name = "web-backend-ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-ecs-task-role"
  }
}

# Task Role Inline Policy (placeholder – allow all; adjust for least privilege)
resource "aws_iam_role_policy" "ecs_task" {
  name = "web-backend-ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
      }
    ]
  })
}

# ECS Task Definition
resource "aws_ecs_task_definition" "app" {
  family                   = "web-backend-app"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name  = "web-backend-app"
      image = local.app_image
      portMappings = [
        {
          containerPort = local.app_port
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "POSTGRES_HOST"
          value = aws_db_instance.main.address
        },
        {
          name  = "POSTGRES_USER"
          value = local.db_username
        },
        {
          name  = "POSTGRES_DB"
          value = local.db_name
        }
      ]
      secrets = [
        {
          name      = "POSTGRES_PASSWORD"
          valueFrom = aws_secretsmanager_secret.db_password.arn
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = local.region
          "awslogs-stream-prefix" = "ecs"
        }
      }
    }
  ])

  tags = {
    Name = "web-backend-app-task-def"
  }
}

# ECS Service
resource "aws_ecs_service" "app" {
  name            = "web-backend-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.app.arn
  desired_count   = 2
  launch_type     = "FARGATE"
  platform_version = "LATEST"

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.ecs_tasks.id]
    assign_public_ip = false
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE"
    weight            = 20
    base              = 0
  }

  capacity_provider_strategy {
    capacity_provider = "FARGATE_SPOT"
    weight            = 80
    base              = 0
  }

  deployment_circuit_breaker {
    enable   = true
    rollback = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.main.arn
    container_name   = "web-backend-app"
    container_port   = local.app_port
  }

  depends_on = [
    aws_lb_listener.main
  ]

  tags = {
    Name = "web-backend-service"
  }
}

# Autoscaling Target
resource "aws_appautoscaling_target" "ecs" {
  max_capacity       = 4
  min_capacity       = 2
  resource_id        = "service/${aws_ecs_cluster.main.name}/${aws_ecs_service.app.name}"
  scalable_dimension = "ecs:service:DesiredCount"
  service_namespace  = "ecs"
}

# CPU Target Tracking Policy (50%)
resource "aws_appautoscaling_policy" "cpu" {
  name               = "web-backend-cpu-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageCPUUtilization"
    }
    target_value = 50.0
  }
}

# Memory Target Tracking Policy (50%)
resource "aws_appautoscaling_policy" "memory" {
  name               = "web-backend-memory-autoscaling"
  policy_type        = "TargetTrackingScaling"
  resource_id        = aws_appautoscaling_target.ecs.resource_id
  scalable_dimension = aws_appautoscaling_target.ecs.scalable_dimension
  service_namespace  = aws_appautoscaling_target.ecs.service_namespace

  target_tracking_scaling_policy_configuration {
    predefined_metric_specification {
      predefined_metric_type = "ECSServiceAverageMemoryUtilization"
    }
    target_value = 50.0
  }
}

# OIDC Provider for GitHub Actions
resource "aws_iam_openid_connect_provider" "github" {
  url = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
  thumbprint_list = ["6938fd4d98bab03faadb97b34396831e3780aea1"]
}

# IAM Role for GitHub Actions CI/CD
resource "aws_iam_role" "github_actions" {
  name = "web-backend-github-actions-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github.arn
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringLike = {
            "token.actions.githubusercontent.com:sub" = "repo:${local.github_org}/*"
          }
        }
      }
    ]
  })

  tags = {
    Name = "web-backend-github-actions-role"
  }
}

# Inline Policy for GitHub Actions Role
resource "aws_iam_role_policy" "github_actions" {
  name = "web-backend-github-actions-policy"
  role = aws_iam_role.github_actions.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:BatchCheckLayerAvailability",
          "ecr:BatchGetImage",
          "ecr:CompleteLayerUpload",
          "ecr:GetDownloadUrlForLayer",
          "ecr:GetAuthorizationToken",
          "ecr:InitiateLayerUpload",
          "ecr:PutImage",
          "ecr:UploadLayerPart",
          "ecr:ListImages",
          "ecr:DescribeRepositories",
          "ecr:DescribeImages",
          "ecr:BatchDeleteImage",
          "ecr:SetRepositoryPolicy"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ecs:RegisterTaskDefinition",
          "ecs:DescribeTaskDefinition",
          "ecs:UpdateService",
          "ecs:ListTaskDefinitions",
          "ecs:DescribeTaskDefinitions",
          "ecs:DeregisterTaskDefinition"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = "ecs:PassRole"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = "ecs-tasks.amazonaws.com"
          }
        }
        Resource = [
          aws_iam_role.ecs_execution.arn,
          aws_iam_role.ecs_task.arn
        ]
      }
    ]
  })
}

# Variables
variable "health_check_path" {
  description = "Health check path for ALB target group"
  type        = string
  default     = "/health"
}

variable "app_port" {
  description = "Application port exposed by the container"
  type        = number
  default     = 80
}

variable "github_org" {
  description = "GitHub organization or account name for OIDC trust"
  type        = string
  default     = "my-org"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Input variables
variable "cluster_tag" {
  description = "Tag value for the cluster"
  type        = string
  default     = "default"
}

variable "enable_key_rotation" {
  description = "Enable annual KMS key rotation"
  type        = bool
  default     = false
}

variable "machine_roles" {
  description = "Map of role names to sets of policy identifiers"
  type        = map(set(string))
  default     = {}
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_availability_zones" "available" {}

# KMS key for Vault unsealing
resource "aws_kms_key" "vault_seal" {
  description             = "resinstack:vault:seal:${var.cluster_tag}"
  enable_key_rotation     = var.enable_key_rotation
  deletion_window_in_days = 30
  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "key-default-1"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Random passwords for initial secret values
resource "random_password" "secret" {
  for_each = toset([
    "consul-agent-token",
    "consul-gossip-key",
    "nomad-client-consul-token",
    "nomad-gossip-key",
    "nomad-server-consul-token",
    "nomad-vault-token",
    "vault-consul-token"
  ])
  length  = 32
  special = false
}

# Secrets Manager secrets
resource "aws_secretsmanager_secret" "secrets" {
  for_each = random_password.secret
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  tags = {
    "resinstack:cluster" = var.cluster_tag
  }
  lifecycle {
    prevent_destroy = true
  }
}

# Secret versions with initial random values
resource "aws_secretsmanager_secret_version" "secrets" {
  for_each      = aws_secretsmanager_secret.secrets
  secret_id     = each.value.id
  secret_string = random_password.secret[each.key].result
}

# IAM policy documents (constructed as locals)
locals {
  # Map of policy identifiers to JSON documents
  policy_documents = {
    "read-tags" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = ["ec2:DescribeInstances", "ec2:DescribeTags"]
          Resource = "*"
        }
      ]
    })
    "vault-kms" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = ["kms:Encrypt", "kms:Decrypt", "kms:DescribeKey"]
          Resource = aws_kms_key.vault_seal.arn
        }
      ]
    })
    "consul-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["consul-agent-token"].arn,
            aws_secretsmanager_secret.secrets["consul-gossip-key"].arn
          ]
        }
      ]
    })
    "nomad-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["nomad-client-consul-token"].arn,
            aws_secretsmanager_secret.secrets["nomad-gossip-key"].arn,
            aws_secretsmanager_secret.secrets["nomad-server-consul-token"].arn,
            aws_secretsmanager_secret.secrets["nomad-vault-token"].arn
          ]
        }
      ]
    })
    "vault-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [aws_secretsmanager_secret.secrets["vault-consul-token"].arn]
        }
      ]
    })
    "client-keys" = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect   = "Allow"
          Action   = "secretsmanager:GetSecretValue"
          Resource = [
            aws_secretsmanager_secret.secrets["consul-agent-token"].arn,
            aws_secretsmanager_secret.secrets["consul-gossip-key"].arn,
            aws_secretsmanager_secret.secrets["nomad-client-consul-token"].arn
          ]
        }
      ]
    })
  }
}

# IAM policies
resource "aws_iam_policy" "policies" {
  for_each    = local.policy_documents
  name        = "resinstack-${each.key}-${var.cluster_tag}"
  description = "Policy for ${each.key}"
  policy      = each.value
}

# Assume role policy document for EC2
data "aws_iam_policy_document" "assume_role" {
  for_each = var.machine_roles
  statement {
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# IAM roles
resource "aws_iam_role" "machine_roles" {
  for_each           = var.machine_roles
  name               = "resinstack-${each.key}-${var.cluster_tag}"
  assume_role_policy = data.aws_iam_policy_document.assume_role[each.key].json
  max_session_duration = 43200 # 12 hours
}

# Instance profiles
resource "aws_iam_instance_profile" "machine_profiles" {
  for_each = var.machine_roles
  name     = "resinstack-${each.key}-${var.cluster_tag}"
  role     = aws_iam_role.machine_roles[each.key].name
}

# Flatten role-policy attachments
locals {
  role_policy_attachments = flatten([
    for role_name, identifiers in var.machine_roles : [
      for policy_id in identifiers : {
        role_name   = role_name
        policy_id   = policy_id
        policy_arn  = aws_iam_policy.policies[policy_id].arn
        role_name_full = aws_iam_role.machine_roles[role_name].name
      }
    ]
  ])
}

# Attach policies to roles
resource "aws_iam_role_policy_attachment" "attachments" {
  for_each = { for idx, att in local.role_policy_attachments : "${att.role_name}-${att.policy_id}" => att }

  role       = each.value.role_name_full
  policy_arn = each.value.policy_arn
}

# Outputs
output "vault_kms_key_id" {
  description = "KMS key ID used for Vault unsealing"
  value       = aws_kms_key.vault_seal.key_id
}

output "secret_names" {
  description = "Map of secret short names to full secret names"
  value = {
    for k, v in aws_secretsmanager_secret.secrets : k => v.name
  }
}

output "machine_role_names" {
  description = "Map of role names to IAM role names"
  value = {
    for k, v in aws_iam_role.machine_roles : k => v.name
  }
}

output "instance_profile_names" {
  description = "Map of role names to instance profile names"
  value = {
    for k, v in aws_iam_instance_profile.machine_profiles : k => v.name
  }
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment_prefix" {
  type    = string
  default = "elluis_codes_limited_network"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names      = slice(data.aws_availability_zones.available.names, 0, 3)
  az_offset_map = { for i, az in local.az_names : az => [11, 22, 33][i] }
  env_prefix    = var.environment_prefix
}

resource "aws_vpc" "main" {
  cidr_block           = "64.0.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "${local.env_prefix}-vpc"
    Environment = local.env_prefix
  }
}

resource "aws_subnet" "public" {
  for_each = local.az_offset_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "64.0.${each.value}.0/25"
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.env_prefix}-public-${each.key}"
    Environment = local.env_prefix
    Type        = "public"
  }
}

resource "aws_subnet" "private" {
  for_each = local.az_offset_map

  vpc_id                  = aws_vpc.main.id
  cidr_block              = "64.0.${each.value}.128/25"
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = {
    Name        = "${local.env_prefix}-private-${each.key}"
    Environment = local.env_prefix
    Type        = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "${local.env_prefix}-igw"
    Environment = local.env_prefix
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "${local.env_prefix}-public-rt"
    Environment = local.env_prefix
  }
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  for_each = local.az_offset_map

  domain = "vpc"

  tags = {
    Name        = "${local.env_prefix}-nat-eip-${each.key}"
    Environment = local.env_prefix
  }
}

resource "aws_nat_gateway" "main" {
  for_each = local.az_offset_map

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = aws_subnet.public[each.key].id

  tags = {
    Name        = "${local.env_prefix}-nat-${each.key}"
    Environment = local.env_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  for_each = local.az_offset_map

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[each.key].id
  }

  tags = {
    Name        = "${local.env_prefix}-private-rt-${each.key}"
    Environment = local.env_prefix
  }

  lifecycle {
    ignore_changes = [route]
  }
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.key].id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Data sources (static provider metadata / well known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables - user controlled values only, every one has a default so that
# `terraform apply` can run unattended.
###############################################################################

variable "creation_token" {
  description = "Idempotency token that uniquely identifies the EFS file system."
  type        = string
  default     = "test-efs"
}

variable "performance_mode" {
  description = "EFS performance mode."
  type        = string
  default     = "generalPurpose"

  validation {
    condition     = contains(["generalPurpose", "maxIO"], var.performance_mode)
    error_message = "performance_mode must be either generalPurpose or maxIO."
  }
}

variable "throughput_mode" {
  description = "EFS throughput mode."
  type        = string
  default     = "bursting"

  validation {
    condition     = contains(["bursting", "provisioned", "elastic"], var.throughput_mode)
    error_message = "throughput_mode must be one of bursting, provisioned or elastic."
  }
}

variable "transition_to_ia_days" {
  description = "Days since last access before files transition to the Infrequent Access storage class."
  type        = number
  default     = 30

  validation {
    condition     = contains([1, 7, 14, 30, 60, 90, 180, 270, 365], var.transition_to_ia_days)
    error_message = "transition_to_ia_days must be one of 1, 7, 14, 30, 60, 90, 180, 270 or 365."
  }
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project   = "shared-efs-storage"
    ManagedBy = "terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "shared-efs"

  vpc_cidr = "10.0.0.0/16"
  az_count = 3

  availability_zones = slice(data.aws_availability_zones.available.names, 0, local.az_count)

  # One subnet per availability zone, derived from the VPC CIDR - no hardcoded
  # subnet IDs or availability zone names anywhere in this configuration.
  subnet_cidrs = {
    for idx, az in local.availability_zones : az => cidrsubnet(local.vpc_cidr, 8, idx)
  }

  # EFS only accepts a fixed set of lifecycle transition literals. Note that the
  # one-day value is singular (AFTER_1_DAY) while every other value is plural.
  ia_transition_map = {
    1   = "AFTER_1_DAY"
    7   = "AFTER_7_DAYS"
    14  = "AFTER_14_DAYS"
    30  = "AFTER_30_DAYS"
    60  = "AFTER_60_DAYS"
    90  = "AFTER_90_DAYS"
    180 = "AFTER_180_DAYS"
    270 = "AFTER_270_DAYS"
    365 = "AFTER_365_DAYS"
  }

  transition_to_ia = local.ia_transition_map[var.transition_to_ia_days]

  common_tags = var.tags

  account_root_arn      = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  efs_service_principal = "elasticfilesystem.amazonaws.com"
}

###############################################################################
# Networking - created in this configuration because the account is greenfield
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_subnet" "efs" {
  for_each = local.subnet_cidrs

  vpc_id                  = aws_vpc.main.id
  cidr_block              = each.value
  availability_zone       = each.key
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-efs-${each.key}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-public-rt"
  })
}

resource "aws_route_table_association" "efs" {
  for_each = aws_subnet.efs

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security group for the EFS mount targets - NFS (2049) from the VPC only
###############################################################################

resource "aws_security_group" "efs_mount" {
  name_prefix = "${local.name_prefix}-mount-"
  description = "NFSv4 access to the shared Amazon EFS mount targets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFSv4 traffic from clients inside the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "NFSv4 responses back to clients inside the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mount-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Dedicated customer managed KMS key for EFS encryption
###############################################################################

data "aws_iam_policy_document" "efs_kms" {
  statement {
    sid    = "AllowAccountAdministrationAndUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:CreateGrant",
      "kms:ListGrants",
      "kms:RevokeGrant",
      "kms:GetKeyPolicy",
      "kms:PutKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:EnableKeyRotation",
      "kms:DisableKeyRotation",
      "kms:CreateAlias",
      "kms:DeleteAlias",
      "kms:ListAliases",
      "kms:ListResourceTags",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:EnableKey",
      "kms:DisableKey",
      "kms:UpdateKeyDescription",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowEfsServiceToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = [local.efs_service_principal]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:CreateGrant",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "efs" {
  description             = "Customer managed key used to encrypt the shared Amazon EFS file system"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.efs_kms.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-kms"
  })
}

resource "aws_kms_alias" "efs" {
  name          = "alias/${local.name_prefix}-efs"
  target_key_id = aws_kms_key.efs.key_id
}

###############################################################################
# EFS file system - encrypted at rest with the dedicated KMS key
###############################################################################

resource "aws_efs_file_system" "efs" {
  creation_token   = var.creation_token
  performance_mode = var.performance_mode
  throughput_mode  = var.throughput_mode

  encrypted  = true
  kms_key_id = aws_kms_key.efs.arn

  lifecycle_policy {
    transition_to_ia = local.transition_to_ia
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-fs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# File system policy - enforce encryption in transit
###############################################################################

resource "aws_efs_file_system_policy" "efs" {
  file_system_id = aws_efs_file_system.efs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "${local.name_prefix}-enforce-tls"
    Statement = [
      {
        Sid       = "DenyNonSecureTransport"
        Effect    = "Deny"
        Principal = { AWS = "*" }
        Action    = "elasticfilesystem:*"
        Resource  = aws_efs_file_system.efs.arn
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

###############################################################################
# Mount targets - one per created subnet / availability zone
###############################################################################

resource "aws_efs_mount_target" "efs" {
  for_each = aws_subnet.efs

  file_system_id  = aws_efs_file_system.efs.id
  subnet_id       = each.value.id
  security_groups = [aws_security_group.efs_mount.id]
}

###############################################################################
# Outputs
###############################################################################

output "efs_file_system_id" {
  description = "ID of the shared EFS file system."
  value       = aws_efs_file_system.efs.id
}

output "efs_file_system_arn" {
  description = "ARN of the shared EFS file system."
  value       = aws_efs_file_system.efs.arn
}

output "efs_file_system_dns_name" {
  description = "DNS name used to mount the EFS file system."
  value       = aws_efs_file_system.efs.dns_name
}

output "kms_key_arn" {
  description = "ARN of the customer managed KMS key encrypting the file system."
  value       = aws_kms_key.efs.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed KMS key encrypting the file system."
  value       = aws_kms_alias.efs.name
}

output "efs_mount_target_ids" {
  description = "Map of availability zone to EFS mount target ID."
  value       = { for az, mount_target in aws_efs_mount_target.efs : az => mount_target.id }
}

output "efs_mount_target_subnet_ids" {
  description = "Map of availability zone to the subnet hosting the mount target."
  value       = { for az, subnet in aws_subnet.efs : az => subnet.id }
}

output "efs_mount_target_security_group_id" {
  description = "Security group attached to the EFS mount targets."
  value       = aws_security_group.efs_mount.id
}

output "vpc_id" {
  description = "ID of the VPC hosting the EFS mount targets."
  value       = aws_vpc.main.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "iam_user_name" {
  description = "Name of the IAM user used by cert-manager for Route 53 DNS validation."
  type        = string
  default     = "cert-manager"
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID used to scope record change permissions. Defaults to '*' (all hosted zones) and should be narrowed per environment."
  type        = string
  default     = "*"
}

variable "parameter_prefix" {
  description = "SSM Parameter Store path prefix used to store cert-manager credentials."
  type        = string
  default     = "/cert-manager"
}

variable "tags" {
  description = "Tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default = {
    ManagedBy = "terraform"
    Service   = "cert-manager"
  }
}

locals {
  access_key_parameter_name = "${var.parameter_prefix}/access-key"
  secret_key_parameter_name = "${var.parameter_prefix}/secret-key"
  policy_name               = "${var.iam_user_name}-route53-policy"
}

resource "aws_iam_user" "cert_manager" {
  name = var.iam_user_name
  tags = merge(var.tags, { Name = var.iam_user_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_access_key" "cert_manager" {
  user = aws_iam_user.cert_manager.name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "access_key" {
  name  = local.access_key_parameter_name
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.id

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "secret_key" {
  name  = local.secret_key_parameter_name
  type  = "SecureString"
  value = aws_iam_access_key.cert_manager.secret

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cert_manager_route53" {
  statement {
    sid       = "GetChangeStatus"
    effect    = "Allow"
    actions   = ["route53:GetChange"]
    resources = ["arn:aws:route53:::change/*"]
  }

  statement {
    sid    = "ChangeAndListResourceRecordSets"
    effect = "Allow"
    actions = [
      "route53:ChangeResourceRecordSets",
      "route53:ListResourceRecordSets",
    ]
    resources = ["arn:aws:route53:::hostedzone/${var.hosted_zone_id}"]
  }

  statement {
    sid       = "ListHostedZonesByName"
    effect    = "Allow"
    actions   = ["route53:ListHostedZonesByName"]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cert_manager_route53" {
  name        = local.policy_name
  description = "Grants cert-manager permission to manage Route 53 DNS records for automated TLS certificate validation."
  policy      = data.aws_iam_policy_document.cert_manager_route53.json

  tags = var.tags
}

output "iam_user_arn" {
  description = "ARN of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.arn
}

output "iam_user_name" {
  description = "Name of the cert-manager IAM user."
  value       = aws_iam_user.cert_manager.name
}

output "iam_policy_arn" {
  description = "ARN of the (intentionally unattached) Route 53 policy for cert-manager."
  value       = aws_iam_policy.cert_manager_route53.arn
}

output "access_key_parameter_arn" {
  description = "ARN of the SSM SecureString parameter holding the access key ID."
  value       = aws_ssm_parameter.access_key.arn
}

output "secret_key_parameter_arn" {
  description = "ARN of the SSM SecureString parameter holding the secret access key."
  value       = aws_ssm_parameter.secret_key.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

# Variables
variable "primary_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Replica AWS region for S3 replication"
  type        = string
  default     = "us-west-2"
}

variable "enable_ec2_malware_scanning" {
  description = "Enable GuardDuty EC2 malware scanning"
  type        = bool
  default     = false
}

variable "ebs_snapshot_retention" {
  description = "Toggle for EBS snapshot preservation"
  type        = bool
  default     = false
}

variable "ip_sets" {
  description = "List of IP sets"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "threat_intel_sets" {
  description = "List of threat intel sets"
  type = list(object({
    name     = string
    format   = string
    location = string
    activate = bool
  }))
  default = []
}

variable "finding_filters" {
  description = "List of finding filters with criteria"
  type = list(object({
    name   = string
    action = string
    rank   = number
    criteria = list(object({
      field                = string
      equals               = optional(list(string))
      not_equals           = optional(list(string))
      greater_than         = optional(number)
      greater_than_or_equal = optional(number)
      less_than            = optional(number)
      less_than_or_equal   = optional(number)
    }))
  }))
  default = []
}

variable "publishing_destinations" {
  description = "List of publishing destinations (only destination_type used, ARNs are auto-generated)"
  type = list(object({
    destination_type = string
  }))
  default = []
}

variable "enable_s3_publishing" {
  description = "Enable S3 publishing destination using the primary bucket"
  type        = bool
  default     = false
}

# Data sources
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}
data "aws_guardduty_detector" "main" {}

# Locals for conditional resource creation
locals {
  create_supporting_infra = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 || var.enable_s3_publishing
  snapshot_retention_value = var.ebs_snapshot_retention ? "RETENTION_WITH_FINDING" : "NO_RETENTION"
  ebs_retention_feature = var.enable_ec2_malware_scanning ? jsonencode([
    {
      Name   = "EBS_MALWARE_PROTECTION"
      Status = "ENABLED"
      AdditionalConfiguration = [
        {
          Name   = "EBS_SNAPSHOT_RETENTION"
          Status = local.snapshot_retention_value
        }
      ]
    }
  ]) : jsonencode([
    {
      Name   = "EBS_MALWARE_PROTECTION"
      Status = "DISABLED"
    }
  ])
}

# Null resource for EBS snapshot retention
resource "null_resource" "ebs_snapshot_retention" {
  triggers = {
    detector_id                 = data.aws_guardduty_detector.main.id
    retention                   = local.snapshot_retention_value
    enable_ec2_malware_scanning = var.enable_ec2_malware_scanning
  }

  provisioner "local-exec" {
    command = "aws guardduty update-detector --detector-id ${data.aws_guardduty_detector.main.id} --features '${local.ebs_retention_feature}' --region ${var.primary_region}"
  }
}

# KMS Key for primary region (multi-region)
resource "aws_kms_key" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  description             = "Multi-region KMS key for GuardDuty and S3 encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  multi_region            = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow GuardDuty to use the key"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "Allow S3 to use the key"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

# Replica KMS key in replica region
resource "aws_kms_replica_key" "replica" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0

  description                     = "Replica KMS key for GuardDuty S3 replication"
  deletion_window_in_days         = 7
  primary_key_arn                 = aws_kms_key.primary[0].arn
  bypass_policy_lockout_safety_check = true

  lifecycle {
    prevent_destroy = true
  }
}

# S3 log bucket for access logs
resource "aws_s3_bucket" "log_bucket" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-log-bucket-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "log_bucket_versioning" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_bucket_sse" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "log_bucket_public_access" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "log_bucket_policy" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.log_bucket[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3LogDelivery"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.log_bucket[0].arn}/*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
            "aws:SourceArn"     = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.primary[0].bucket}"
          }
        }
      }
    ]
  })
}

# Primary S3 bucket for GuardDuty sets and publishing
resource "aws_s3_bucket" "primary" {
  count = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-primary-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary_versioning" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary_sse" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "primary_public_access" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "primary_logging" {
  count  = local.create_supporting_infra ? 1 : 0
  bucket = aws_s3_bucket.primary[0].id

  target_bucket = aws_s3_bucket.log_bucket[0].id
  target_prefix = "s3-access-logs/primary/"
}

# IAM role and policy for replication
resource "aws_iam_role" "replication_role" {
  count = local.create_supporting_infra ? 1 : 0

  name = "guardduty-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "replication_policy" {
  count = local.create_supporting_infra ? 1 : 0

  name        = "guardduty-replication-policy"
  description = "Policy for S3 replication of GuardDuty primary bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.primary[0].arn,
          "${aws_s3_bucket.primary[0].arn}/*"
        ]
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetObjectVersion"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
        Condition = {
          StringLikeIfExists = {
            "s3:SourceArn" = "${aws_s3_bucket.primary[0].arn}/*"
          }
        }
      },
      {
        Action = [
          "kms:Decrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_key.primary[0].arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        }
      },
      {
        Action = [
          "kms:Encrypt"
        ]
        Effect = "Allow"
        Resource = aws_kms_replica_key.replica[0].arn
        Condition = {
          StringLike = {
            "kms:ViaService" = "s3.*.amazonaws.com"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication_attach" {
  count = local.create_supporting_infra ? 1 : 0

  role       = aws_iam_role.replication_role[0].name
  policy_arn = aws_iam_policy.replication_policy[0].arn
}

# Replica S3 bucket in replica region
resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0

  bucket = "guardduty-replica-${data.aws_caller_identity.current.account_id}-${var.replica_region}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "replica_versioning" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica_sse" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_replica_key.replica[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica_public_access" {
  provider = aws.replica
  count    = local.create_supporting_infra ? 1 : 0
  bucket   = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# S3 Replication Configuration
resource "aws_s3_bucket_replication_configuration" "replication" {
  count = local.create_supporting_infra ? 1 : 0

  # Must depend on IAM role/policy and bucket versioning
  depends_on = [
    aws_s3_bucket_versioning.primary_versioning,
    aws_s3_bucket_versioning.replica_versioning,
    aws_iam_role_policy_attachment.replication_attach
  ]

  bucket = aws_s3_bucket.primary[0].id
  role   = aws_iam_role.replication_role[0].arn

  rule {
    id     = "GuardDutyReplication"
    status = "Enabled"

    filter {
      prefix = ""
    }

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_replica_key.replica[0].arn
      }

      replication_time {
        status = "Enabled"
        time {
          minutes = 15
        }
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

# S3 bucket for GuardDuty sets (IP sets, threat intel sets)
resource "aws_s3_bucket" "guardduty_sets" {
  count = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0

  bucket = "guardduty-sets-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "guardduty_sets_versioning" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "guardduty_sets_sse" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "guardduty_sets_public_access" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "guardduty_sets_policy" {
  count  = length(var.ip_sets) > 0 || length(var.threat_intel_sets) > 0 ? 1 : 0
  bucket = aws_s3_bucket.guardduty_sets[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGuardDutyGetObject"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion"
        ]
        Resource = "${aws_s3_bucket.guardduty_sets[0].arn}/*"
      },
      {
        Sid    = "AllowGuardDutyListBucket"
        Effect = "Allow"
        Principal = {
          Service = "guardduty.amazonaws.com"
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.guardduty_sets[0].arn
      }
    ]
  })
}

# IP sets
resource "aws_guardduty_ipset" "ip_sets" {
  count = length(var.ip_sets)

  activate    = var.ip_sets[count.index].activate
  detector_id = data.aws_guardduty_detector.main.id
  format      = var.ip_sets[count.index].format
  location    = var.ip_sets[count.index].location
  name        = var.ip_sets[count.index].name
}

# Threat intel sets
resource "aws_guardduty_threatintelset" "threat_intel_sets" {
  count = length(var.threat_intel_sets)

  activate    = var.threat_intel_sets[count.index].activate
  detector_id = data.aws_guardduty_detector.main.id
  format      = var.threat_intel_sets[count.index].format
  location    = var.threat_intel_sets[count.index].location
  name        = var.threat_intel_sets[count.index].name
}

# Finding filters
resource "aws_guardduty_filter" "finding_filters" {
  count = length(var.finding_filters)

  detector_id = data.aws_guardduty_detector.main.id
  name        = var.finding_filters[count.index].name
  action      = var.finding_filters[count.index].action
  rank        = var.finding_filters[count.index].rank

  finding_criteria {
    dynamic "criterion" {
      for_each = var.finding_filters[count.index].criteria
      content {
        field                = criterion.value.field
        equals               = lookup(criterion.value, "equals", null)
        not_equals           = lookup(criterion.value, "not_equals", null)
        greater_than         = criterion.value.greater_than != null ? tostring(criterion.value.greater_than) : null
        greater_than_or_equal = criterion.value.greater_than_or_equal != null ? tostring(criterion.value.greater_than_or_equal) : null
        less_than            = criterion.value.less_than != null ? tostring(criterion.value.less_than) : null
        less_than_or_equal   = criterion.value.less_than_or_equal != null ? tostring(criterion.value.less_than_or_equal) : null
      }
    }
  }
}

# Publishing destinations
resource "aws_guardduty_publishing_destination" "publishing" {
  count = var.enable_s3_publishing ? length(var.publishing_destinations) : 0

  detector_id      = data.aws_guardduty_detector.main.id
  destination_type = var.publishing_destinations[count.index].destination_type
  destination_arn  = aws_s3_bucket.primary[0].arn
  kms_key_arn      = aws_kms_key.primary[0].arn

  depends_on = [
    aws_s3_bucket.primary,
    aws_kms_key.primary
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

variable "name_prefix" {
  type    = string
  default = "imputation-example"
}

variable "tags" {
  type    = map(string)
  default = {}
}

# Trust policy for EMR service role
data "aws_iam_policy_document" "emr_service_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["elasticmapreduce.amazonaws.com"]
    }
  }
}

# Trust policy for EC2 instance profile role
data "aws_iam_policy_document" "emr_ec2_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# Trust policy for autoscaling role
data "aws_iam_policy_document" "emr_autoscaling_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["application-autoscaling.amazonaws.com"]
    }
  }
}

# Custom policy for EMR service role
data "aws_iam_policy_document" "emr_service_policy" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:Describe*",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupEgress",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeNetworkInterfaces",
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeImages",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeAccountAttributes",
      "ec2:DescribeDhcpOptions",
      "ec2:DescribeRouteTables",
      "elasticmapreduce:*",
      "iam:PassRole"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "emr_service_policy" {
  name        = "${var.name_prefix}-emr-service-policy"
  description = "Custom policy for EMR service role"
  policy      = data.aws_iam_policy_document.emr_service_policy.json
  tags        = var.tags
}

# Custom policy for EMR autoscaling role
data "aws_iam_policy_document" "emr_autoscaling_policy" {
  statement {
    effect = "Allow"
    actions = [
      "application-autoscaling:*",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:PutMetricAlarm",
      "cloudwatch:DeleteAlarms",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarmsForMetric",
      "elasticmapreduce:ListInstanceGroups",
      "elasticmapreduce:ModifyInstanceGroups",
      "elasticmapreduce:DescribeCluster"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "emr_autoscaling_policy" {
  name        = "${var.name_prefix}-emr-autoscaling-policy"
  description = "Custom policy for EMR autoscaling role"
  policy      = data.aws_iam_policy_document.emr_autoscaling_policy.json
  tags        = var.tags
}

# EMR Service Role
resource "aws_iam_role" "emr_service_role" {
  name               = "${var.name_prefix}-emr-service-role"
  assume_role_policy = data.aws_iam_policy_document.emr_service_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_service_policy_attachment" {
  role       = aws_iam_role.emr_service_role.name
  policy_arn = aws_iam_policy.emr_service_policy.arn
}

# EC2 Instance Profile Role
resource "aws_iam_role" "emr_ec2_instance_profile_role" {
  name               = "${var.name_prefix}-emr-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.emr_ec2_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_ec2_policy_cloudwatch" {
  role       = aws_iam_role.emr_ec2_instance_profile_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchAgentServerPolicy"
}

resource "aws_iam_role_policy_attachment" "emr_ec2_policy_ssm" {
  role       = aws_iam_role.emr_ec2_instance_profile_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# Autoscaling Role
resource "aws_iam_role" "emr_autoscaling_role" {
  name               = "${var.name_prefix}-emr-autoscaling-role"
  assume_role_policy = data.aws_iam_policy_document.emr_autoscaling_assume_role.json
  tags               = var.tags
}

resource "aws_iam_role_policy_attachment" "emr_autoscaling_policy_attachment" {
  role       = aws_iam_role.emr_autoscaling_role.name
  policy_arn = aws_iam_policy.emr_autoscaling_policy.arn
}

# Instance Profile
resource "aws_iam_instance_profile" "emr_ec2_instance_profile" {
  name = "${var.name_prefix}-emr-instance-profile"
  role = aws_iam_role.emr_ec2_instance_profile_role.name
  tags = var.tags
}

# Outputs for IAM Roles
output "emr_service_role_arn" {
  value = aws_iam_role.emr_service_role.arn
}

output "emr_service_role_name" {
  value = aws_iam_role.emr_service_role.name
}

output "emr_service_role_unique_id" {
  value = aws_iam_role.emr_service_role.unique_id
}

output "emr_ec2_instance_profile_role_arn" {
  value = aws_iam_role.emr_ec2_instance_profile_role.arn
}

output "emr_ec2_instance_profile_role_name" {
  value = aws_iam_role.emr_ec2_instance_profile_role.name
}

output "emr_ec2_instance_profile_role_unique_id" {
  value = aws_iam_role.emr_ec2_instance_profile_role.unique_id
}

output "emr_autoscaling_role_arn" {
  value = aws_iam_role.emr_autoscaling_role.arn
}

output "emr_autoscaling_role_name" {
  value = aws_iam_role.emr_autoscaling_role.name
}

output "emr_autoscaling_role_unique_id" {
  value = aws_iam_role.emr_autoscaling_role.unique_id
}

# Outputs for Instance Profile
output "emr_instance_profile_id" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.id
}

output "emr_instance_profile_arn" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.arn
}

output "emr_instance_profile_name" {
  value = aws_iam_instance_profile.emr_ec2_instance_profile.name
}

variable "postman_user_name" {
  description = "Name of the IAM user to create for API integration testing and monitoring"
  type        = string
  default     = "postman-user"
}

variable "cognito_user_pool_arn" {
  description = "ARN of the Cognito User Pool to scope the conditional AdminInitiateAuth policy to. Leave empty to skip."
  type        = string
  default     = ""
}

resource "aws_iam_user" "postman" {
  name = var.postman_user_name
  path = "/"
}

resource "aws_iam_access_key" "postman" {
  user = aws_iam_user.postman.name
}

resource "aws_iam_user_policy" "api_gateway_cloudwatch_read_only" {
  name = "api-gateway-cloudwatch-read-only"
  user = aws_iam_user.postman.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "apigateway:GET",
          "cloudwatch:GetMetricData",
          "cloudwatch:ListMetrics"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy" "cognito_admin_initiate_auth" {
  count = var.cognito_user_pool_arn != "" ? 1 : 0

  name = "cognito-admin-initiate-auth"
  user = aws_iam_user.postman.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "cognito-idp:AdminInitiateAuth"
        ]
        Resource = var.cognito_user_pool_arn
      }
    ]
  })
}

output "access_key_id" {
  description = "AWS access key ID for the integration testing IAM user"
  value       = aws_iam_access_key.postman.id
}

output "secret_access_key" {
  description = "AWS secret access key for the integration testing IAM user"
  value       = aws_iam_access_key.postman.secret
  sensitive   = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  type    = string
  default = "legion"
}

data "aws_iam_policy_document" "eks_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "node_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

data "aws_iam_policy_document" "worker_autoscaling" {
  statement {
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "autoscaling:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/kubernetes.io/cluster/${var.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "cluster" {
  name               = "tf-${var.cluster_name}"
  assume_role_policy = data.aws_iam_policy_document.eks_assume_role.json
}

resource "aws_iam_role" "node" {
  name               = "tf-${var.cluster_name}-node"
  assume_role_policy = data.aws_iam_policy_document.node_assume_role.json
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_service_policy" {
  role       = aws_iam_role.cluster.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
}

resource "aws_iam_role_policy_attachment" "worker_node_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "cni_policy" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "ecr_read_only" {
  role       = aws_iam_role.node.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_instance_profile" "node" {
  name = "tf-${var.cluster_name}-node"
  role = aws_iam_role.node.name
}

resource "aws_iam_policy" "worker_autoscaling" {
  name   = "eks-worker-autoscaling-${var.cluster_name}"
  policy = data.aws_iam_policy_document.worker_autoscaling.json
}

resource "aws_iam_role_policy_attachment" "worker_autoscaling" {
  role       = aws_iam_role.node.name
  policy_arn = aws_iam_policy.worker_autoscaling.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data source for availability zones
data "aws_availability_zones" "available" {
  state = "available"
}

# Variables with defaults
variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.69.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet"
  type        = string
  default     = "172.69.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet"
  type        = string
  default     = "172.69.2.0/24"
}

variable "web_ingress_rules" {
  description = "List of ingress rules for the web security group"
  type = list(object({
    description = string
    port        = number
    protocol    = string
    cidr_blocks = list(string)
  }))
  default = [
    {
      description = "HTTP from anywhere"
      port        = 80
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    },
    {
      description = "SSH from VPC"
      port        = 22
      protocol    = "tcp"
      cidr_blocks = ["172.69.0.0/16"]
    }
  ]
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "vpc_name"
  }
}

# Public subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = "public_subnet"
  }
}

# Private subnet
resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidr
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "private_subnet"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "igw_tag"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "rtb_tag"
  }
}

# Route table association for public subnet
resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# Web server security group
resource "aws_security_group" "webserver" {
  name        = "webserver-sg_${aws_vpc.main.id}"
  description = "Security group for web servers"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.web_ingress_rules
    content {
      description = ingress.value.description
      from_port   = ingress.value.port
      to_port     = ingress.value.port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "web-server_security_group"
  }
}

# Database security group
resource "aws_security_group" "database" {
  name        = "database-sg_${aws_vpc.main.id}"
  description = "Security group for database instances"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "MySQL from web servers"
    from_port       = 3306
    to_port         = 3306
    protocol        = "tcp"
    security_groups = [aws_security_group.webserver.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "database_security_group"
  }
}

variable "tags" {
  description = "Tags to apply to all IAM resources"
  type        = map(string)
  default     = {}
}

locals {
  controlplane_name = "aws_ccm_k8s_controlplane"
  worker_name       = "aws_ccm_k8s_worker"
}

resource "aws_iam_role" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role" "aws_ccm_k8s_worker" {
  name = local.worker_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Networking"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeRouteTables",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeAvailabilityZones",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeNatGateways",
          "ec2:DescribeVpcPeeringConnections",
          "ec2:DescribePrefixLists",
          "ec2:DescribeRegions",
          "ec2:DescribeVolumes",
          "ec2:DescribeTags",
          "ec2:CreateRoute",
          "ec2:DeleteRoute",
          "ec2:ReplaceRoute",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:ModifyInstanceAttribute",
          "ec2:AttachNetworkInterface",
          "ec2:DetachNetworkInterface",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:DescribeNetworkInterfaceAttribute"
        ]
        Resource = "*"
      },
      {
        Sid    = "AutoScaling"
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeTags",
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup"
        ]
        Resource = "*"
      },
      {
        Sid    = "ElasticLoadBalancing"
        Effect = "Allow"
        Action = [
          "elasticloadbalancing:DescribeLoadBalancers",
          "elasticloadbalancing:DescribeLoadBalancerAttributes",
          "elasticloadbalancing:DescribeTargetGroups",
          "elasticloadbalancing:DescribeTargetGroupAttributes",
          "elasticloadbalancing:DescribeTargetHealth",
          "elasticloadbalancing:DescribeListeners",
          "elasticloadbalancing:DescribeRules",
          "elasticloadbalancing:DescribeTags",
          "elasticloadbalancing:CreateLoadBalancer",
          "elasticloadbalancing:DeleteLoadBalancer",
          "elasticloadbalancing:ModifyLoadBalancerAttributes",
          "elasticloadbalancing:CreateTargetGroup",
          "elasticloadbalancing:DeleteTargetGroup",
          "elasticloadbalancing:ModifyTargetGroup",
          "elasticloadbalancing:ModifyTargetGroupAttributes",
          "elasticloadbalancing:RegisterTargets",
          "elasticloadbalancing:DeregisterTargets",
          "elasticloadbalancing:CreateListener",
          "elasticloadbalancing:DeleteListener",
          "elasticloadbalancing:ModifyListener",
          "elasticloadbalancing:CreateRule",
          "elasticloadbalancing:DeleteRule",
          "elasticloadbalancing:ModifyRule",
          "elasticloadbalancing:SetSecurityGroups",
          "elasticloadbalancing:SetSubnets",
          "elasticloadbalancing:AddTags",
          "elasticloadbalancing:RemoveTags"
        ]
        Resource = "*"
      },
      {
        Sid    = "KMS"
        Effect = "Allow"
        Action = [
          "kms:DescribeKey"
        ]
        Resource = "*"
      },
      {
        Sid    = "ServiceLinkedRole"
        Effect = "Allow"
        Action = [
          "iam:CreateServiceLinkedRole",
          "iam:GetRole",
          "iam:PutRolePolicy"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "aws_ccm_k8s_worker" {
  name = local.worker_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2Describe"
        Effect = "Allow"
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeRegions"
        ]
        Resource = "*"
      },
      {
        Sid    = "ECRReadOnly"
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchCheckLayerAvailability",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages",
          "ecr:DescribeRegistry",
          "ecr:DescribePullThroughCacheRules"
        ]
        Resource = "*"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "controlplane_attach" {
  role       = aws_iam_role.aws_ccm_k8s_controlplane.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_controlplane.arn
}

resource "aws_iam_role_policy_attachment" "worker_attach" {
  role       = aws_iam_role.aws_ccm_k8s_worker.name
  policy_arn = aws_iam_policy.aws_ccm_k8s_worker.arn
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_controlplane" {
  name = local.controlplane_name
  role = aws_iam_role.aws_ccm_k8s_controlplane.name
  tags = var.tags
}

resource "aws_iam_instance_profile" "aws_ccm_k8s_worker" {
  name = local.worker_name
  role = aws_iam_role.aws_ccm_k8s_worker.name
  tags = var.tags
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "name_prefix" {
  description = "Prefix for all IAM resource names"
  type        = string
  default     = "awscademo-"
}

locals {
  tags = {
    Contact          = "team@example.com"
    DeploymentMethod = "Terraform"
    DeploymentDate   = formatdate("YYYY-MM-DD", timestamp())
    TTL              = "infinite"
  }
}

data "aws_caller_identity" "current" {}

resource "aws_iam_group" "demo_users" {
  name = "${var.name_prefix}demo-users"
}

resource "aws_iam_group_policy" "self_management" {
  name  = "${var.name_prefix}self-management"
  group = aws_iam_group.demo_users.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowManageOwnPasswords"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:GetAccessKeyLastUsed",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnSSHPublicKeys"
        Effect = "Allow"
        Action = [
          "iam:DeleteSSHPublicKey",
          "iam:GetSSHPublicKey",
          "iam:ListSSHPublicKeys",
          "iam:UpdateSSHPublicKey",
          "iam:UploadSSHPublicKey"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:mfa/*"
      },
      {
        Sid    = "AllowManageOwnMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
      },
      {
        Sid    = "AllowDeactivateOwnMFA"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group" "read_only_users" {
  name = "${var.name_prefix}read-only-users"
}

resource "aws_iam_group_policy_attachment" "read_only_attach" {
  group      = aws_iam_group.read_only_users.name
  policy_arn = "arn:aws:iam::aws:policy/ReadOnlyAccess"
}

resource "aws_iam_group" "mfa_superadmin" {
  name = "${var.name_prefix}mfa-superadmin"
}

resource "aws_iam_role" "admin_role" {
  name                = substr("${var.name_prefix}admin-role", 0, 31)
  max_session_duration = 43200
  tags                = local.tags

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "admin_policy" {
  name = "${var.name_prefix}admin-policy"
  role = aws_iam_role.admin_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy" "assume_admin_policy" {
  name  = "${var.name_prefix}assume-admin"
  group = aws_iam_group.mfa_superadmin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin_role.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# Terraform and Provider Requirements
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_group" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_group" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_group" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# IAM Group Policies (Inline)
# ------------------------------------------------------------------------------
# Admin group: full administrative access
data "aws_iam_policy_document" "admin_full_access" {
  statement {
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "admin" {
  name   = "admin-full-access"
  group  = aws_iam_group.admin.name
  policy = data.aws_iam_policy_document.admin_full_access.json
}

resource "aws_iam_group_policy" "admin_terraform_cloud" {
  name   = "admin-terraform-cloud-full-access"
  group  = aws_iam_group.admin_terraform_cloud.name
  policy = data.aws_iam_policy_document.admin_full_access.json
}

# GitHub group: targeted actions for ACM, CloudFront, IAM, Lambda, Route53, S3, SQS
data "aws_iam_policy_document" "github" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:CreateRole",
      "iam:GetRole",
      "iam:PassRole",
      "iam:PutRolePolicy",
      "iam:AttachRolePolicy",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:InvokeFunction",
      "lambda:UpdateFunctionCode",
      "route53:ChangeResourceRecordSets",
      "route53:ListHostedZones",
      "route53:ListResourceRecordSets",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
      "sqs:CreateQueue",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:SendMessage"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "github" {
  name   = "github-inline-policy"
  group  = aws_iam_group.github.name
  policy = data.aws_iam_policy_document.github.json
}

# Serverless group: includes CloudWatch Logs actions
data "aws_iam_policy_document" "serverless" {
  statement {
    effect = "Allow"
    actions = [
      "acm:DescribeCertificate",
      "acm:GetCertificate",
      "acm:ListCertificates",
      "cloudfront:CreateDistribution",
      "cloudfront:GetDistribution",
      "cloudfront:ListDistributions",
      "cloudfront:UpdateDistribution",
      "iam:CreateRole",
      "iam:GetRole",
      "iam:PassRole",
      "iam:PutRolePolicy",
      "iam:AttachRolePolicy",
      "lambda:CreateFunction",
      "lambda:GetFunction",
      "lambda:InvokeFunction",
      "lambda:UpdateFunctionCode",
      "lambda:AddPermission",
      "logs:CreateLogGroup",
      "logs:DescribeLogGroups",
      "logs:PutLogEvents",
      "route53:ChangeResourceRecordSets",
      "route53:ListHostedZones",
      "route53:ListResourceRecordSets",
      "s3:GetObject",
      "s3:ListBucket",
      "s3:PutObject",
      "sqs:CreateQueue",
      "sqs:GetQueueAttributes",
      "sqs:GetQueueUrl",
      "sqs:SendMessage",
      "sqs:ReceiveMessage"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_group_policy" "serverless" {
  name   = "serverless-inline-policy"
  group  = aws_iam_group.serverless.name
  policy = data.aws_iam_policy_document.serverless.json
}

# ------------------------------------------------------------------------------
# IAM Users
# ------------------------------------------------------------------------------
resource "aws_iam_user" "admin" {
  name = "admin"
  path = "/admin/"
}

resource "aws_iam_user" "admin_macbook_pro" {
  name = "admin-macbook-pro"
  path = "/admin/"
}

resource "aws_iam_user" "admin_terraform_cloud" {
  name = "admin-terraform-cloud"
  path = "/admin_terraform_cloud/"
}

resource "aws_iam_user" "github" {
  name = "github"
  path = "/github/"
}

resource "aws_iam_user" "serverless" {
  name = "serverless"
  path = "/serverless/"
}

# ------------------------------------------------------------------------------
# IAM Group Memberships
# ------------------------------------------------------------------------------
resource "aws_iam_user_group_membership" "admin" {
  user   = aws_iam_user.admin.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_macbook_pro" {
  user   = aws_iam_user.admin_macbook_pro.name
  groups = [aws_iam_group.admin.name]
}

resource "aws_iam_user_group_membership" "admin_terraform_cloud" {
  user   = aws_iam_user.admin_terraform_cloud.name
  groups = [aws_iam_group.admin_terraform_cloud.name]
}

resource "aws_iam_user_group_membership" "github" {
  user   = aws_iam_user.github.name
  groups = [aws_iam_group.github.name]
}

resource "aws_iam_user_group_membership" "serverless" {
  user   = aws_iam_user.serverless.name
  groups = [aws_iam_group.serverless.name]
}

# ------------------------------------------------------------------------------
# Access Keys (stored in AWS Secrets Manager)
# ------------------------------------------------------------------------------
resource "aws_iam_access_key" "admin_macbook_pro" {
  user = aws_iam_user.admin_macbook_pro.name
}

resource "aws_iam_access_key" "admin_terraform_cloud" {
  user = aws_iam_user.admin_terraform_cloud.name
}

resource "aws_secretsmanager_secret" "admin_macbook_pro" {
  name = "admin-macbook-pro-access-key"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_macbook_pro" {
  secret_id = aws_secretsmanager_secret.admin_macbook_pro.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_macbook_pro.id
    secret_access_key = aws_iam_access_key.admin_macbook_pro.secret
  })
  lifecycle {
    ignore_changes = [secret_string]
  }
}

resource "aws_secretsmanager_secret" "admin_terraform_cloud" {
  name = "admin-terraform-cloud-access-key"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "admin_terraform_cloud" {
  secret_id = aws_secretsmanager_secret.admin_terraform_cloud.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.admin_terraform_cloud.id
    secret_access_key = aws_iam_access_key.admin_terraform_cloud.secret
  })
  lifecycle {
    ignore_changes = [secret_string]
  }
}

# ------------------------------------------------------------------------------
# Serverless IAM Role and Policy
# ------------------------------------------------------------------------------
resource "aws_iam_role" "serverless" {
  name = "serverless"
  path = "/serverless/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = [
            "lambda.amazonaws.com",
            "edgelambda.amazonaws.com"
          ]
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "serverless" {
  name        = "serverless"
  path        = "/serverless/"
  description = "Customer managed policy for serverless deployments"
  policy      = data.aws_iam_policy_document.serverless.json
}

resource "aws_iam_role_policy_attachment" "serverless" {
  role       = aws_iam_role.serverless.name
  policy_arn = aws_iam_policy.serverless.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for static metadata
data "aws_caller_identity" "current" {}

# Variables
variable "namespace" {
  description = "Namespace (e.g., `eg` or `cp`)"
  type        = string
  default     = "default"
}

variable "environment" {
  description = "Environment (e.g., `prod`, `dev`, `staging`)"
  type        = string
  default     = "dev"
}

variable "name" {
  description = "Solution name (e.g., `iam`)"
  type        = string
  default     = "iam"
}

variable "tags" {
  description = "Additional tags"
  type        = map(string)
  default     = {}
}

variable "attributes" {
  description = "Additional attributes (e.g., `1`)"
  type        = list(string)
  default     = []
}

variable "admin_user_names" {
  description = "List of IAM user names for admin group"
  type        = list(string)
  default     = []
}

variable "non_admin_user_names" {
  description = "List of IAM user names for non-admin group"
  type        = list(string)
  default     = []
}

# CloudPosse label module
module "this" {
  source      = "cloudposse/label/null"
  version     = "~> 0.25"
  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  tags        = var.tags
  attributes  = var.attributes
}

# IAM Groups
resource "aws_iam_group" "admin" {
  name = "${module.this.id}-admin"
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = "${module.this.id}-non-admin"
  path = "/"
}

# IAM Users
resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_user_names)
  name     = each.key
  path     = "/"
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_user_names)
  name     = each.key
  path     = "/"
}

# Self-Management Policy Document
data "aws_iam_policy_document" "self_management" {
  # Account-level actions (no specific resource)
  statement {
    sid    = "AccountInfo"
    effect = "Allow"
    actions = [
      "iam:ListVirtualMFADevices",
      "iam:ListAccountAliases",
      "iam:GetAccountPasswordPolicy",
    ]
    resources = ["*"]
  }

  # User-level actions (except DeactivateMFADevice)
  statement {
    sid    = "UserSelfManagement"
    effect = "Allow"
    actions = [
      "iam:ChangePassword",
      "iam:CreateAccessKey",
      "iam:UpdateAccessKey",
      "iam:DeleteAccessKey",
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]
    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
    ]
  }

  # DeactivateMFADevice with MFA requirement
  statement {
    sid    = "DeactivateMFADevice"
    effect = "Allow"
    actions = [
      "iam:DeactivateMFADevice",
    ]
    resources = [
      "arn:aws:iam::*:user/&{aws:username}",
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Self-Management Policy
resource "aws_iam_policy" "self_management" {
  name        = "${module.this.id}-self-management"
  description = "Allows users to manage their own IAM credentials and MFA devices"
  policy      = data.aws_iam_policy_document.self_management.json
}

# Attach Self-Management Policy to Admin Group
resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Attach Self-Management Policy to Non-Admin Group
resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

# Admin Role Trust Policy
data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Admin Role
resource "aws_iam_role" "admin" {
  name               = "${module.this.id}-admin-role"
  assume_role_policy = data.aws_iam_policy_document.admin_role_trust.json
}

# Attach AdministratorAccess to Admin Role
resource "aws_iam_role_policy_attachment" "admin" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

# Assume Admin Role Policy Document
data "aws_iam_policy_document" "assume_admin_role" {
  statement {
    effect = "Allow"
    actions = [
      "sts:AssumeRole",
    ]
    resources = [
      aws_iam_role.admin.arn,
    ]
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# Assume Admin Role Policy
resource "aws_iam_policy" "assume_admin_role" {
  name        = "${module.this.id}-assume-admin-role"
  description = "Allows admin users to assume the admin role with MFA"
  policy      = data.aws_iam_policy_document.assume_admin_role.json
}

# Attach Assume Admin Role Policy to Admin Group
resource "aws_iam_group_policy_attachment" "assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

# Group Memberships for Admin Users
resource "aws_iam_user_group_membership" "admin" {
  for_each = toset(var.admin_user_names)
  user     = each.key
  groups   = [aws_iam_group.admin.name]
}

# Group Memberships for Non-Admin Users
resource "aws_iam_user_group_membership" "non_admin" {
  for_each = toset(var.non_admin_user_names)
  user     = each.key
  groups   = [aws_iam_group.non_admin.name]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Environment name for tagging"
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "main-vpc"
    Environment = var.environment
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "main-igw"
    Environment = var.environment
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "public-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "public"
  }
}

resource "aws_subnet" "private_a" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 10 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-a-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "private-a"
  }
}

resource "aws_subnet" "private_b" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 20 + count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name        = "private-b-subnet-${count.index + 1}"
    Environment = var.environment
    Tier        = "private-b"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name        = "public-rt"
    Environment = var.environment
  }
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name        = "private-rt"
    Environment = var.environment
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count = 4

  subnet_id      = flatten([aws_subnet.private_a[*].id, aws_subnet.private_b[*].id])[count.index]
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "public" {
  name        = "public-sg"
  description = "Security group for public subnets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Allow SSH from VPC"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Allow HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow all outbound traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "public-sg"
    Environment = var.environment
  }
}

resource "aws_security_group" "private" {
  name        = "private-sg"
  description = "Security group for private subnets"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow all traffic from VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow all outbound traffic to VPC only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name        = "private-sg"
    Environment = var.environment
  }
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# NOTE: The `provider "aws"` configuration (region, credentials, etc.) is
# injected by the deployment harness. A provider block is intentionally
# omitted here to avoid a duplicate/invalid provider configuration.

# ---------------------------------------------------------------------------
# Inputs
# ---------------------------------------------------------------------------

variable "name_suffix" {
  description = "Suffix appended to every IAM resource name. Resource names are composed as the literal prefix 'prod-ci-' plus this value."
  type        = string
  default     = ""
}

# ---------------------------------------------------------------------------
# Local naming convention (single source of truth for "<prefix><suffix>")
# ---------------------------------------------------------------------------

locals {
  # Prefix "prod-ci-" + configurable suffix applied consistently to every
  # IAM role, policy, group, user and membership below.
  name = "prod-ci-${var.name_suffix}"
}

# ---------------------------------------------------------------------------
# IAM role assumable via sts:AssumeRole
#
# SECURITY TRADE-OFF (intentional, as explicitly requested):
# The trust policy below uses the structured wildcard principal
# `Principal = { AWS = "*" }`. IAM requires `Principal` to be an object keyed
# by principal type (AWS / Service / Federated / CanonicalUser); the bare
# string form `Principal = "*"` is rejected with
# `MalformedPolicyDocument: ... invalid principal`. The map form keeps the
# requested wildcard semantics: ANY AWS principal that is otherwise permitted
# to call sts:AssumeRole may assume this role. That is a privilege-escalation
# / confused-deputy risk and should NOT ship to production as-is.
#
# Recommended production hardening: scope the principal to a concrete ARN
# (account root, a specific role, or an OIDC provider) and add strict
# conditions, for example:
#   Principal = { AWS = "arn:aws:iam::<trusting-account-id>:root" }
#   Condition = {
#     StringEquals = {
#       "sts:ExternalId"    = "<shared-external-id>"
#       "aws:SourceAccount" = "<trusting-account-id>"
#     }
#   }
# ---------------------------------------------------------------------------
resource "aws_iam_role" "prod_ci_role" {
  name        = local.name
  description = "CI/CD role for ${local.name} (assumable via sts:AssumeRole)."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowWildcardAssumeRole"
        Effect    = "Allow"
        Principal = { AWS = "*" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = local.name
  }
}

# ---------------------------------------------------------------------------
# Least-privilege policy: grants ONLY sts:AssumeRole, scoped to this role's ARN
# (never "*" for both Action and Resource).
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "prod_ci_assume_role_policy" {
  name        = local.name
  description = "Grants sts:AssumeRole scoped strictly to the ${local.name} IAM role ARN."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeProdCiRole"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.prod_ci_role.arn
      }
    ]
  })

  tags = {
    Name = local.name
  }
}

# ---------------------------------------------------------------------------
# IAM group that carries the assume-role policy
# ---------------------------------------------------------------------------
resource "aws_iam_group" "prod_ci_group" {
  name = local.name
}

# Attach the policy to the group (non-destructive group-level attachment).
resource "aws_iam_group_policy_attachment" "prod_ci_assume_role_attachment" {
  group      = aws_iam_group.prod_ci_group.name
  policy_arn = aws_iam_policy.prod_ci_assume_role_policy.arn
}

# ---------------------------------------------------------------------------
# IAM user (no console login profile and no access keys are created here;
# credentials must be provisioned out-of-band and never committed).
# ---------------------------------------------------------------------------
resource "aws_iam_user" "prod_ci_user" {
  name = local.name

  tags = {
    Name = local.name
  }
}

# Bind the user to the group via group membership.
resource "aws_iam_user_group_membership" "prod_ci_user_group_membership" {
  user   = aws_iam_user.prod_ci_user.name
  groups = [aws_iam_group.prod_ci_group.name]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (all with defaults so `terraform apply` runs unattended)
###############################################################################

variable "region" {
  description = "AWS region in which the Config aggregator stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment identifier used for tagging (e.g. dev, staging, prod)."
  type        = string
  default     = "prod"
}

variable "stack_name" {
  description = "Stack identifier used for naming and tagging resources."
  type        = string
  default     = "config-aggregator"
}

###############################################################################
# Static provider metadata lookups
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  config_bucket_name = "${var.stack_name}-config-${data.aws_caller_identity.current.account_id}-${data.aws_region.current.name}"

  config_role_name = "${var.stack_name}-config-role"

  config_recorder_name         = "default"
  config_delivery_channel_name = "default"
  config_aggregator_name       = "default"

  aws_config_service_principal = "config.amazonaws.com"

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = {
    ManagedBy   = "Terraform"
    Environment = var.environment
    Stack       = var.stack_name
  }
}

###############################################################################
# Customer-managed KMS key used for the Config delivery bucket (SSE-KMS)
###############################################################################

resource "aws_kms_key" "config" {
  description             = "CMK for AWS Config delivery bucket encryption (${var.stack_name})"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_key_policy" "config" {
  key_id = aws_kms_key.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = aws_kms_key.config.arn
      },
      {
        Sid    = "AllowS3ServiceUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.config.arn
      },
      {
        Sid    = "AllowConfigServiceUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = local.aws_config_service_principal
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.config.arn
      }
    ]
  })
}

###############################################################################
# S3 bucket used by the delivery channel for Config snapshots / history
###############################################################################

resource "aws_s3_bucket" "config" {
  bucket = local.config_bucket_name

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket = aws_s3_bucket.config.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config.arn
    }
    bucket_key_enabled = true
  }

  depends_on = [aws_kms_key_policy.config]
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Bucket policy granting the AWS Config service least-privilege access
###############################################################################

resource "aws_s3_bucket_policy" "config" {
  bucket = aws_s3_bucket.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AWSConfigBucketPermissionsCheck"
        Effect = "Allow"
        Principal = {
          Service = local.aws_config_service_principal
        }
        Action   = "s3:GetBucketAcl"
        Resource = aws_s3_bucket.config.arn
      },
      {
        Sid    = "AWSConfigBucketExistenceCheck"
        Effect = "Allow"
        Principal = {
          Service = local.aws_config_service_principal
        }
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.config.arn
      },
      {
        Sid    = "AWSConfigBucketDelivery"
        Effect = "Allow"
        Principal = {
          Service = local.aws_config_service_principal
        }
        Action = "s3:PutObject"
        Resource = "arn:${data.aws_partition.current.partition}:s3:::${aws_s3_bucket.config.bucket}/AWSLogs/${data.aws_caller_identity.current.account_id}/Config/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.config]
}

###############################################################################
# IAM role assumed by AWS Config
###############################################################################

resource "aws_iam_role" "config" {
  name = local.config_role_name

  description = "Service role assumed by AWS Config to record configuration and compliance data."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowConfigServiceAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = local.aws_config_service_principal
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

###############################################################################
# AWS Config recorder, delivery channel and recorder status
###############################################################################

resource "aws_config_configuration_recorder" "main" {
  name     = local.config_recorder_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = local.config_delivery_channel_name
  s3_bucket_name = aws_s3_bucket.config.bucket

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_config_configuration_recorder.main,
    aws_s3_bucket_policy.config,
    aws_kms_key_policy.config,
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.main,
    aws_iam_role_policy_attachment.config_managed,
  ]
}

###############################################################################
# AWS Config configuration aggregator collecting all regions for this account
###############################################################################

resource "aws_config_configuration_aggregator" "default" {
  name = local.config_aggregator_name

  account_aggregation_source {
    account_ids = [data.aws_caller_identity.current.account_id]
    all_regions = true
  }

  tags = local.common_tags

  depends_on = [
    aws_config_configuration_recorder_status.main,
    aws_iam_role_policy_attachment.config_managed,
  ]
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "additional_tags" {
  description = "Additional tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "ssh_inbound" {
  description = "List of CIDR blocks allowed SSH access"
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_count              = length(data.aws_availability_zones.available.names)
  public_subnet_cidrs   = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i)]
  private_subnet_cidrs  = [for i in range(local.az_count) : cidrsubnet(aws_vpc.main.cidr_block, 8, i + local.az_count)]
  public_subnet_cidr_list = aws_subnet.public[*].cidr_block
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(
    {
      Name = var.vpc_name
    },
    var.additional_tags
  )
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    {
      Name = "public-${var.vpc_name}-${count.index + 1}"
    },
    var.additional_tags
  )
}

resource "aws_subnet" "private" {
  count             = local.az_count
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(
    {
      Name = "private-${var.vpc_name}-${count.index + 1}"
    },
    var.additional_tags
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-igw"
    },
    var.additional_tags
  )
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    {
      Name = "${var.vpc_name}-nat-eip"
    },
    var.additional_tags
  )
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    {
      Name = "${var.vpc_name}-nat"
    },
    var.additional_tags
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.vpc_name}-public-rt"
    },
    var.additional_tags
  )
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    {
      Name = "${var.vpc_name}-private-rt"
    },
    var.additional_tags
  )
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_default_network_acl" "main" {
  default_network_acl_id = aws_vpc.main.default_network_acl_id

  tags = merge(
    {
      Name = "${var.vpc_name}-Default"
    },
    var.additional_tags
  )
}

resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []

  tags = merge(
    {
      Name = "${var.vpc_name}-Default"
    },
    var.additional_tags
  )
}

resource "aws_security_group" "public" {
  name        = "${var.vpc_name}-public-sg"
  description = "Security group for public subnets"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-public-sg"
    },
    var.additional_tags
  )
}

resource "aws_vpc_security_group_ingress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "public_ssh" {
  for_each = toset(var.ssh_inbound)

  security_group_id = aws_security_group.public.id
  cidr_ipv4         = each.key
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_http" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "public_https" {
  security_group_id = aws_security_group.public.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_security_group" "private" {
  name        = "${var.vpc_name}-private-sg"
  description = "Security group for private subnets"
  vpc_id      = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-private-sg"
    },
    var.additional_tags
  )
}

resource "aws_vpc_security_group_ingress_rule" "private_http" {
  for_each = toset(local.public_subnet_cidr_list)

  security_group_id = aws_security_group.private.id
  cidr_ipv4         = each.key
  from_port         = 80
  to_port           = 80
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_ingress_rule" "private_https" {
  for_each = toset(local.public_subnet_cidr_list)

  security_group_id = aws_security_group.private.id
  cidr_ipv4         = each.key
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "private_https" {
  security_group_id = aws_security_group.private.id
  cidr_ipv4         = aws_vpc.main.cidr_block
  from_port         = 443
  to_port           = 443
  ip_protocol       = "tcp"
}

resource "aws_network_acl" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-public-nacl"
    },
    var.additional_tags
  )
}

resource "aws_network_acl_rule" "public_ingress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 90
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_ingress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 91
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_ingress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 92
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "public_ingress_ssh" {
  for_each = { for idx, cidr in var.ssh_inbound : idx => cidr }

  network_acl_id = aws_network_acl.public.id
  rule_number    = 100 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 22
  to_port        = 22
}

resource "aws_network_acl_rule" "public_egress_http" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 90
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "public_egress_https" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 91
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "public_egress_ephemeral" {
  network_acl_id = aws_network_acl.public.id
  rule_number    = 92
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_association" "public" {
  count          = local.az_count
  network_acl_id = aws_network_acl.public.id
  subnet_id      = aws_subnet.public[count.index].id
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    {
      Name = "${var.vpc_name}-private-nacl"
    },
    var.additional_tags
  )
}

resource "aws_network_acl_rule" "private_ingress_http" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 100 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 80
  to_port        = 80
}

resource "aws_network_acl_rule" "private_ingress_https" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 110 + each.key
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_ingress_ephemeral" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 120
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_https" {
  network_acl_id = aws_network_acl.private.id
  rule_number    = 100
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"
  from_port      = 443
  to_port        = 443
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_private" {
  for_each = { for idx, cidr in local.private_subnet_cidrs : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 110 + each.key
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_rule" "private_egress_ephemeral_to_public" {
  for_each = { for idx, cidr in local.public_subnet_cidr_list : idx => cidr }

  network_acl_id = aws_network_acl.private.id
  rule_number    = 120 + each.key
  egress         = true
  protocol       = "tcp"
  rule_action    = "allow"
  cidr_block     = each.value
  from_port      = 1024
  to_port        = 65535
}

resource "aws_network_acl_association" "private" {
  count          = local.az_count
  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Additional user-supplied tags to merge onto the IAM resources."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Name        = "imagebuilder"
      Environment = "shared"
    },
    var.tags,
  )

  imagebuilder_policy_arn        = "arn:aws:iam::aws:policy/EC2InstanceProfileForImageBuilder"
  ssm_managed_instance_core_arn  = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

data "aws_iam_policy_document" "imagebuilder_assume_role" {
  statement {
    sid     = "EC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "imagebuilder_role" {
  name_prefix        = "imagebuilder_"
  path               = "/"
  description        = "Role used by EC2 Image Builder build instances."
  assume_role_policy = data.aws_iam_policy_document.imagebuilder_assume_role.json
  tags               = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "imagebuilder_full_access" {
  role       = aws_iam_role.imagebuilder_role.name
  policy_arn = local.imagebuilder_policy_arn
}

resource "aws_iam_role_policy_attachment" "imagebuilder_ssm_core" {
  role       = aws_iam_role.imagebuilder_role.name
  policy_arn = local.ssm_managed_instance_core_arn
}

resource "aws_iam_instance_profile" "imagebuilder_instance_profile" {
  name_prefix = "imagebuilder_"
  path        = "/"
  role        = aws_iam_role.imagebuilder_role.name
  tags        = local.common_tags

  lifecycle {
    create_before_destroy = true
  }
}

output "imagebuilder_role_arn" {
  description = "ARN of the IAM role assumed by EC2 Image Builder instances."
  value       = aws_iam_role.imagebuilder_role.arn
}

output "imagebuilder_role_name" {
  description = "Name of the IAM role assumed by EC2 Image Builder instances."
  value       = aws_iam_role.imagebuilder_role.name
}

output "imagebuilder_instance_profile_arn" {
  description = "ARN of the IAM instance profile for EC2 Image Builder."
  value       = aws_iam_instance_profile.imagebuilder_instance_profile.arn
}

output "imagebuilder_instance_profile_name" {
  description = "Name of the IAM instance profile for EC2 Image Builder."
  value       = aws_iam_instance_profile.imagebuilder_instance_profile.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tamr_instance_role_name" {
  description = "Name of the IAM role assumed by Tamr EC2 instances."
  type        = string
  default     = "tamr-instance-role"
}

variable "tamr_instance_profile_name" {
  description = "Name of the IAM instance profile attached to Tamr EC2 instances."
  type        = string
  default     = "tamr-instance-profile"
}

variable "permissions_boundary_arn" {
  description = "Optional ARN of the IAM permissions boundary to apply to the Tamr instance role. When null, no permissions boundary is configured."
  type        = string
  default     = null

  validation {
    condition     = var.permissions_boundary_arn == null || can(regex("^arn:aws[a-zA-Z-]*:iam::[0-9]{12}:policy/.+$", var.permissions_boundary_arn))
    error_message = "The permissions_boundary_arn value must be null or a valid IAM policy ARN."
  }
}

variable "tags" {
  description = "Map of tags applied to the created IAM role and instance profile."
  type        = map(string)
  default     = {}
}

locals {
  role_tags             = merge(var.tags, { Name = var.tamr_instance_role_name })
  instance_profile_tags = merge(var.tags, { Name = var.tamr_instance_profile_name })
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2InstancesToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "tamr_instance_role" {
  name                 = var.tamr_instance_role_name
  description          = "IAM role assumed by Tamr platform EC2 instances."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  permissions_boundary = var.permissions_boundary_arn
  tags                 = local.role_tags
}

resource "aws_iam_instance_profile" "tamr_instance_profile" {
  name = var.tamr_instance_profile_name
  role = aws_iam_role.tamr_instance_role.name
  tags = local.instance_profile_tags
}

output "tamr_instance_role_arn" {
  description = "ARN of the Tamr instance IAM role."
  value       = aws_iam_role.tamr_instance_role.arn
}

output "tamr_instance_role_name" {
  description = "Name of the Tamr instance IAM role."
  value       = aws_iam_role.tamr_instance_role.name
}

output "tamr_instance_profile_arn" {
  description = "ARN of the Tamr instance IAM instance profile."
  value       = aws_iam_instance_profile.tamr_instance_profile.arn
}

output "tamr_instance_profile_name" {
  description = "Name of the Tamr instance IAM instance profile."
  value       = aws_iam_instance_profile.tamr_instance_profile.name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "role_name" {
  description = "Name of the IAM role used by Amazon RDS Custom for SQL Server instances."
  type        = string
  default     = "AWSRDSCustomSQLServerInstanceRole"
}

variable "instance_profile_name" {
  description = "Name of the IAM instance profile attached to RDS Custom for SQL Server instances."
  type        = string
  default     = "AWSRDSCustomSQLServerInstanceProfile"
}

variable "project" {
  description = "Project identifier used for tagging."
  type        = string
  default     = "rds-custom-sqlserver"
}

variable "environment" {
  description = "Deployment environment identifier used for tagging."
  type        = string
  default     = "prod"
}

variable "tags" {
  description = "Additional non-sensitive tags applied to all resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      Name        = var.role_name
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )

  instance_profile_tags = merge(
    {
      Name        = var.instance_profile_name
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

###############################################################################
# Data Sources
###############################################################################

# EC2 service trust relationship required by RDS Custom for SQL Server.
data "aws_iam_policy_document" "rds_custom_ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# AWS-managed policy resolved by name (no hardcoded account-specific ARN).
data "aws_iam_policy" "rds_custom_instance_profile_role_policy" {
  name = "AmazonRDSCustomInstanceProfileRolePolicy"
}

###############################################################################
# IAM Role
###############################################################################

resource "aws_iam_role" "rds_custom_sqlserver_instance_role" {
  name                 = var.role_name
  path                 = "/"
  description          = "IAM role assumed by EC2 instances running Amazon RDS Custom for SQL Server."
  assume_role_policy   = data.aws_iam_policy_document.rds_custom_ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "rds_custom_instance_profile_role_policy" {
  role       = aws_iam_role.rds_custom_sqlserver_instance_role.name
  policy_arn = data.aws_iam_policy.rds_custom_instance_profile_role_policy.arn
}

###############################################################################
# IAM Instance Profile
###############################################################################

resource "aws_iam_instance_profile" "rds_custom_sqlserver_instance_profile" {
  name = var.instance_profile_name
  path = "/"
  role = aws_iam_role.rds_custom_sqlserver_instance_role.name

  tags = local.instance_profile_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "rds_custom_instance_role_name" {
  description = "Name of the RDS Custom for SQL Server instance IAM role."
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.name
}

output "rds_custom_instance_role_arn" {
  description = "ARN of the RDS Custom for SQL Server instance IAM role."
  value       = aws_iam_role.rds_custom_sqlserver_instance_role.arn
}

output "rds_custom_instance_profile_name" {
  description = "Name of the RDS Custom for SQL Server instance profile."
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.name
}

output "rds_custom_instance_profile_arn" {
  description = "ARN of the RDS Custom for SQL Server instance profile."
  value       = aws_iam_instance_profile.rds_custom_sqlserver_instance_profile.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "name_prefix" {
  description = "Environment-specific resource name prefix (e.g. \"dev\", \"stage\", \"prod\")."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,20}$", var.name_prefix))
    error_message = "name_prefix must be 2-21 lowercase alphanumeric or hyphen characters."
  }
}

variable "target_account_id" {
  description = "AWS account ID of the account that hosts the software installation files and the role to assume."
  type        = string
  default     = "111122223333"

  validation {
    condition     = can(regex("^[0-9]{12}$", var.target_account_id))
    error_message = "target_account_id must be a 12-digit AWS account ID."
  }
}

variable "target_role_name" {
  description = "Name of the cross-account IAM role to assume in target_account_id."
  type        = string
  default     = "packer-installation-files-reader"
}

variable "installation_bucket_name" {
  description = "Name of the S3 bucket that stores the software installation files."
  type        = string
  default     = "packer-installation-files"
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  cross_account_role_arn  = "arn:aws:iam::${var.target_account_id}:role/${var.target_role_name}"
  installation_bucket_arn = "arn:aws:s3:::${var.installation_bucket_name}"

  common_tags = merge(
    var.tags,
    {
      Name      = "${var.name_prefix}-packer-builder"
      ManagedBy = "terraform"
    }
  )
}

###############################################################################
# IAM policy documents
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "cross_account_assume" {
  statement {
    sid     = "AssumeCrossAccountInstallationFilesRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    resources = [local.cross_account_role_arn]
  }
}

data "aws_iam_policy_document" "installation_bucket_read" {
  statement {
    sid     = "ListInstallationBucket"
    effect  = "Allow"
    actions = ["s3:ListBucket"]

    resources = [local.installation_bucket_arn]
  }

  statement {
    sid     = "ReadInstallationObjects"
    effect  = "Allow"
    actions = ["s3:GetObject", "s3:GetObjectVersion"]

    resources = ["${local.installation_bucket_arn}/*"]
  }
}

data "aws_iam_policy_document" "packer_builder_permissions" {
  source_policy_documents = [
    data.aws_iam_policy_document.cross_account_assume.json,
    data.aws_iam_policy_document.installation_bucket_read.json,
  ]
}

###############################################################################
# IAM role + instance profile for the EC2 Packer builder
###############################################################################

resource "aws_iam_role" "packer_builder" {
  name                 = "${var.name_prefix}-packer-builder-role"
  description          = "Role assumed by the EC2 Packer builder instance."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_instance_profile" "packer_builder" {
  name = "${var.name_prefix}-packer-builder-profile"
  role = aws_iam_role.packer_builder.name

  tags = local.common_tags
}

resource "aws_iam_policy" "packer_builder" {
  name        = "${var.name_prefix}-packer-builder-policy"
  description = "Allows the Packer builder to assume the cross-account role and read installation files from S3."
  policy      = data.aws_iam_policy_document.packer_builder_permissions.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "packer_builder" {
  role       = aws_iam_role.packer_builder.name
  policy_arn = aws_iam_policy.packer_builder.arn
}

###############################################################################
# Outputs
###############################################################################

output "packer_builder_role_name" {
  description = "Name of the Packer builder IAM role."
  value       = aws_iam_role.packer_builder.name
}

output "packer_builder_role_arn" {
  description = "ARN of the Packer builder IAM role."
  value       = aws_iam_role.packer_builder.arn
}

output "packer_builder_instance_profile_name" {
  description = "Name of the instance profile to attach to the Packer builder EC2 instance."
  value       = aws_iam_instance_profile.packer_builder.name
}

output "packer_builder_instance_profile_arn" {
  description = "ARN of the instance profile to attach to the Packer builder EC2 instance."
  value       = aws_iam_instance_profile.packer_builder.arn
}

output "cross_account_role_arn" {
  description = "ARN of the cross-account role the Packer builder is allowed to assume."
  value       = local.cross_account_role_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name tag applied to the three-tier VPC."
  type        = string
  default     = "three-tier-vpc"
}

variable "region" {
  description = "AWS region used for resource naming/tagging context."
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name applied to all resources as a tag."
  type        = string
  default     = "dev"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  common_tags = {
    Environment = var.environment
    ManagedBy   = "terraform"
    Region      = var.region
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.16.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

resource "aws_subnet" "presentation" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.0.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name  = "presentation-subnet"
    Layer = "presentation"
    Tier  = "presentation"
  })
}

resource "aws_subnet" "application" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.1.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name  = "application-subnet"
    Layer = "application"
    Tier  = "application"
  })
}

resource "aws_subnet" "data" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.16.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[2]

  tags = merge(local.common_tags, {
    Name  = "data-subnet"
    Layer = "data"
    Tier  = "data"
  })
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name  = "${var.vpc_name}-igw"
    Layer = "presentation"
  })
}

resource "aws_route_table" "presentation" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name  = "${var.vpc_name}-presentation-rt"
    Layer = "presentation"
    Tier  = "presentation"
  })
}

resource "aws_route" "presentation_default" {
  route_table_id         = aws_route_table.presentation.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "presentation" {
  subnet_id      = aws_subnet.presentation.id
  route_table_id = aws_route_table.presentation.id
}

output "vpc_id" {
  description = "ID of the created three-tier VPC."
  value       = aws_vpc.main.id
}

output "presentation_subnet_id" {
  description = "ID of the presentation (public) subnet."
  value       = aws_subnet.presentation.id
}

output "application_subnet_id" {
  description = "ID of the application (private) subnet."
  value       = aws_subnet.application.id
}

output "data_subnet_id" {
  description = "ID of the data (private) subnet."
  value       = aws_subnet.data.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.igw.id
}

output "presentation_route_table_id" {
  description = "ID of the route table associated with the presentation subnet."
  value       = aws_route_table.presentation.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Inputs (non-infrastructure values only)
###############################################################################

variable "project" {
  description = "Project name used for naming and tagging of the governance stack."
  type        = string
  default     = "service-catalog-governance"
}

variable "environment" {
  description = "Environment name (e.g. test, dev, prod) used for tagging."
  type        = string
  default     = "test"
}

variable "external_id" {
  description = "Optional external ID used to further scope the Service Catalog trust policy. Leave null to skip the sts:ExternalId condition."
  type        = string
  default     = null
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource in this stack."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata (no pre-existing remote infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

###############################################################################
# Service Catalog launch-constraint role
###############################################################################

data "aws_iam_policy_document" "service_catalog_assume_role" {
  statement {
    sid     = "AllowServiceCatalogToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }

    dynamic "condition" {
      for_each = var.external_id == null ? [] : [var.external_id]

      content {
        test     = "StringEquals"
        variable = "sts:ExternalId"
        values   = [condition.value]
      }
    }
  }
}

resource "aws_iam_role" "test_role" {
  name                 = "test_role"
  description          = "Role assumed by AWS Service Catalog when provisioning products via the launch constraint."
  assume_role_policy   = data.aws_iam_policy_document.service_catalog_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

###############################################################################
# Customer managed key for the artifacts bucket (SSE-KMS)
###############################################################################

resource "aws_kms_key" "artifacts" {
  description             = "CMK used to encrypt Service Catalog provisioned product artifacts in the ${aws_s3_bucket.artifacts.bucket} bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "artifacts" {
  name          = format("alias/%s-%s-artifacts", var.project, var.environment)
  target_key_id = aws_kms_key.artifacts.key_id
}

###############################################################################
# Artifact bucket used by provisioned products
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket        = format("%s-%s-%s-artifacts", var.project, var.environment, data.aws_caller_identity.current.account_id)
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Scoped launch-constraint policy attached to test_role
###############################################################################

data "aws_iam_policy_document" "launch_constraint" {
  statement {
    sid    = "CloudFormationStackProvisioning"
    effect = "Allow"

    actions = [
      "cloudformation:CreateStack",
      "cloudformation:UpdateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStackResources",
      "cloudformation:GetTemplate",
      "cloudformation:GetTemplateSummary",
      "cloudformation:ListStackResources",
      "cloudformation:ValidateTemplate",
    ]

    resources = [
      format(
        "arn:%s:cloudformation:%s:%s:stack/*",
        data.aws_partition.current.partition,
        data.aws_region.current.name,
        data.aws_caller_identity.current.account_id,
      ),
    ]
  }

  statement {
    sid    = "ArtifactObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]

    resources = [
      format("%s/*", aws_s3_bucket.artifacts.arn),
    ]
  }

  statement {
    sid    = "ArtifactBucketMetadata"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
    ]
  }

  statement {
    sid    = "ArtifactBucketKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.artifacts.arn,
    ]
  }

  statement {
    sid    = "PassRoleToServiceCatalog"
    effect = "Allow"

    actions = [
      "iam:PassRole",
    ]

    resources = [
      aws_iam_role.test_role.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["servicecatalog.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "service-catalog-launch-constraint"
  description = "Scoped permissions used by the Service Catalog launch-constraint role test_role."
  policy      = data.aws_iam_policy_document.launch_constraint.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

###############################################################################
# Governance group with scoped assume-role permissions
###############################################################################

resource "aws_iam_group" "governance" {
  name = "test_group"
  path = "/"
}

data "aws_iam_policy_document" "group_assume_role" {
  statement {
    sid       = "AssumeLaunchConstraintRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.test_role.arn]
  }
}

resource "aws_iam_group_policy" "assume_launch_role" {
  name   = "test-group-assume-launch-role"
  group  = aws_iam_group.governance.name
  policy = data.aws_iam_policy_document.group_assume_role.json
}

###############################################################################
# Console-enabled governance user
###############################################################################

resource "aws_iam_user" "governance" {
  name          = "test_user"
  path          = "/"
  force_destroy = true

  tags = local.common_tags
}

# The AWS provider generates the console password internally at apply time and
# exposes it as the computed attribute `password` (only populated when
# `pgp_key` is not set). The value is a first-login temporary credential
# because `password_reset_required` is true.
resource "aws_iam_user_login_profile" "governance" {
  user                    = aws_iam_user.governance.name
  password_length         = 20
  password_reset_required = true
}

resource "aws_iam_group_membership" "governance" {
  name  = "test-group-membership"
  users = [aws_iam_user.governance.name]
  group = aws_iam_group.governance.name
}

###############################################################################
# Outputs
###############################################################################

output "role_name" {
  description = "Name of the Service Catalog launch-constraint role."
  value       = aws_iam_role.test_role.name
}

output "role_arn" {
  description = "ARN of the Service Catalog launch-constraint role (use as the launch constraint)."
  value       = aws_iam_role.test_role.arn
}

output "launch_constraint_policy_arn" {
  description = "ARN of the scoped launch-constraint policy attached to the role."
  value       = aws_iam_policy.launch_constraint.arn
}

output "group_name" {
  description = "Name of the governance IAM group."
  value       = aws_iam_group.governance.name
}

output "group_arn" {
  description = "ARN of the governance IAM group."
  value       = aws_iam_group.governance.arn
}

output "user_name" {
  description = "Name of the console-enabled governance IAM user."
  value       = aws_iam_user.governance.name
}

output "user_arn" {
  description = "ARN of the console-enabled governance IAM user."
  value       = aws_iam_user.governance.arn
}

output "console_login_url" {
  description = "AWS console sign-in URL for the governance user."
  value       = format("https://%s.signin.aws.amazon.com/console", data.aws_caller_identity.current.account_id)
}

output "console_password" {
  description = "Provider-generated first-login password for the governance user. Marked sensitive so it is never written to plan output; the user must reset it on first login."
  value       = aws_iam_user_login_profile.governance.password
  sensitive   = true
}

output "artifact_bucket_name" {
  description = "Name of the S3 bucket used for Service Catalog provisioned product artifacts."
  value       = aws_s3_bucket.artifacts.bucket
}

output "kms_key_arn" {
  description = "ARN of the customer managed key used for artifact bucket encryption."
  value       = aws_kms_key.artifacts.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed key used for artifact bucket encryption."
  value       = aws_kms_alias.artifacts.name
}

terraform {
  required_version = ">= 1.5"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100"
    }
  }
}

variable "enable_ssm_endpoints" {
  description = "Whether to create SSM interface VPC endpoints"
  type        = bool
  default     = false
}

locals {
  common_tags = {
    Datadog                 = "true"
    DatadogAgentlessScanner = "true"
  }
  az_count     = min(3, length(data.aws_availability_zones.available.names))
  ssm_services = var.enable_ssm_endpoints ? ["ec2messages", "ssmmessages", "ssm"] : []
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = merge(local.common_tags, {
    Name = "DatatogAgentlessScanner"
  })
}

resource "aws_subnet" "public" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "datadog-public-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count                   = local.az_count
  vpc_id                  = aws_vpc.main.id
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "datadog-private-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "datadog-igw"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "datadog-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "datadog-natgw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "datadog-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count          = local.az_count
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "datadog-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = local.az_count
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = [
    aws_route_table.public.id,
    aws_route_table.private.id
  ]

  tags = merge(local.common_tags, {
    Name = "datadog-s3-gateway-endpoint"
  })
}

resource "aws_security_group" "vpce" {
  name_prefix = "datadog-vpce-sg-"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow HTTPS from VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "datadog-vpce-sg"
  })
}

resource "aws_vpc_endpoint" "lambda" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.lambda"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpce.id]

  tags = merge(local.common_tags, {
    Name = "datadog-lambda-vpce"
  })
}

resource "aws_vpc_endpoint" "ebs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ebs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpce.id]

  tags = merge(local.common_tags, {
    Name = "datadog-ebs-vpce"
  })
}

resource "aws_vpc_endpoint" "ssm" {
  for_each            = toset(local.ssm_services)
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  private_dns_enabled = true
  security_group_ids  = [aws_security_group.vpce.id]

  tags = merge(local.common_tags, {
    Name = "datadog-ssm-${each.key}-vpce"
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ------------------------------------------------------------------------------
# Variables
# ------------------------------------------------------------------------------
variable "enabled" {
  description = "Global toggle to enable or disable all resources"
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Toggle between creating a new security group (true) or attaching rules to an existing one (false)"
  type        = bool
  default     = true
}

variable "vpc_id" {
  description = "VPC ID for the security group. If null and create_sg is true, an existing VPC will be used."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for resource names"
  type        = string
  default     = "app"
}

variable "tags" {
  description = "Additional tags for all resources"
  type        = map(string)
  default     = {}
}

variable "enable_prefix_list" {
  description = "Toggle to create a managed prefix list"
  type        = bool
  default     = false
}

variable "existing_sg_id" {
  description = "ID of an existing security group when create_sg is false"
  type        = string
  default     = null

  validation {
    condition     = var.create_sg == false ? var.existing_sg_id != null : true
    error_message = "existing_sg_id must be provided when create_sg is false."
  }
}

variable "ingress_rules" {
  description = "List of ingress rules. Each rule can have: from_port, to_port, protocol, cidr_blocks (list), self (bool), source_security_group_id (string), prefix_list_ids (list)."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []
}

variable "egress_rules" {
  description = "List of egress rules. Same structure as ingress_rules."
  type = list(object({
    from_port                = number
    to_port                  = number
    protocol                 = string
    cidr_blocks              = optional(list(string))
    self                     = optional(bool)
    source_security_group_id = optional(string)
    prefix_list_ids          = optional(list(string))
  }))
  default = []
}

# ------------------------------------------------------------------------------
# Labels module
# ------------------------------------------------------------------------------
module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"
  name   = var.name_prefix
}

locals {
  sg_name          = "${module.labels.id}-sg"
  prefix_list_name = "${module.labels.id}-prefix-list"
}

# ------------------------------------------------------------------------------
# VPC selection (use existing VPC when no vpc_id is provided)
# ------------------------------------------------------------------------------
data "aws_vpcs" "all" {}

data "aws_vpc" "selected" {
  id = var.vpc_id != null ? var.vpc_id : data.aws_vpcs.all.ids[0]
}

locals {
  vpc_id = var.create_sg ? data.aws_vpc.selected.id : null
}

# ------------------------------------------------------------------------------
# Security Group (only when create_sg is true)
# ------------------------------------------------------------------------------
resource "aws_security_group" "this" {
  count       = var.enabled && var.create_sg ? 1 : 0
  name        = local.sg_name
  description = "Security group managed by Terraform"
  vpc_id      = local.vpc_id
  tags        = merge(module.labels.tags, var.tags, { Name = local.sg_name })

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Managed Prefix List (only when enable_prefix_list is true)
# ------------------------------------------------------------------------------
resource "aws_ec2_managed_prefix_list" "this" {
  count          = var.enabled && var.enable_prefix_list ? 1 : 0
  name           = local.prefix_list_name
  address_family = "IPv4"
  max_entries    = 5
  tags           = merge(module.labels.tags, var.tags, { Name = local.prefix_list_name })
}

# ------------------------------------------------------------------------------
# Security Group Rules (ingress and egress)
# ------------------------------------------------------------------------------
locals {
  # Combine ingress and egress rules into a single list with type and index
  all_rules = concat(
    [for idx, rule in var.ingress_rules : merge(rule, { type = "ingress", idx = idx })],
    [for idx, rule in var.egress_rules : merge(rule, { type = "egress", idx = idx })]
  )

  # Determine the security group ID to use
  sg_id = var.create_sg ? aws_security_group.this[0].id : var.existing_sg_id
}

resource "aws_security_group_rule" "this" {
  for_each = var.enabled ? { for r in local.all_rules : "${r.type}-${r.idx}" => r } : {}

  type              = each.value.type
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol
  security_group_id = local.sg_id

  cidr_blocks              = lookup(each.value, "cidr_blocks", null)
  self                     = lookup(each.value, "self", null)
  source_security_group_id = lookup(each.value, "source_security_group_id", null)
  prefix_list_ids          = lookup(each.value, "prefix_list_ids", var.enable_prefix_list ? [aws_ec2_managed_prefix_list.this[0].id] : null)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "role_name" {
  description = "Name of the IAM role for CloudForecast"
  type        = string
  default     = "CloudForecast-ZeroWaste"
}

variable "external_id" {
  description = "External ID to use in the trust policy"
  type        = string
  default     = "benchmark-external-id"
}

data "aws_iam_policy_document" "cloudforecast_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::656227328603:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

resource "aws_iam_role" "cloudforecast_role" {
  name               = var.role_name
  description        = "Dedicated third-party IAM integration role for CloudForecast read-only cost optimization and waste-monitoring analysis"
  assume_role_policy = data.aws_iam_policy_document.cloudforecast_trust.json
}

data "aws_iam_policy_document" "cloudwatch_metrics" {
  statement {
    effect = "Allow"
    actions = [
      "cloudwatch:GetMetricStatistics",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "cloudwatch_metrics" {
  name   = "CloudWatchMetrics"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.cloudwatch_metrics.json
}

data "aws_iam_policy_document" "tag_resources" {
  statement {
    effect = "Allow"
    actions = [
      "tag:GetResources",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "tag_resources" {
  name   = "TagResources"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.tag_resources.json
}

data "aws_iam_policy_document" "organizations" {
  statement {
    effect = "Allow"
    actions = [
      "organizations:ListAccounts",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "organizations" {
  name   = "Organizations"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.organizations.json
}

data "aws_iam_policy_document" "elb" {
  statement {
    effect = "Allow"
    actions = [
      "elasticloadbalancing:DescribeLoadBalancers",
      "elasticloadbalancing:DescribeListeners",
      "elasticloadbalancing:DescribeTargetGroups",
      "elasticloadbalancing:DescribeTags",
      "elasticloadbalancing:DescribeRules",
      "elasticloadbalancing:DescribeTargetHealth",
      "elasticloadbalancing:DescribeLoadBalancerAttributes",
      "elasticloadbalancing:DescribeListenerAttributes",
      "elasticloadbalancing:DescribeTargetGroupAttributes",
      "elasticloadbalancing:DescribeSSLPolicies",
      "elasticloadbalancing:DescribeAccountLimits",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "elb" {
  name   = "ELB"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.elb.json
}

data "aws_iam_policy_document" "ebs" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeSnapshots",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshotAttribute",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ebs" {
  name   = "EBS"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.ebs.json
}

data "aws_iam_policy_document" "ec2" {
  statement {
    effect = "Allow"
    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeTags",
      "ec2:DescribeInstanceAttribute",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeReservedInstances",
      "ec2:DescribeReservedInstancesOfferings",
      "ec2:DescribeImages",
      "ec2:DescribeAddresses",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeRegions",
      "ec2:DescribeAvailabilityZones",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "ec2" {
  name   = "EC2"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.ec2.json
}

data "aws_iam_policy_document" "rds" {
  statement {
    effect = "Allow"
    actions = [
      "rds:DescribeDBInstances",
      "rds:DescribeDBSnapshots",
      "rds:DescribeDBClusters",
      "rds:ListTagsForResource",
      "rds:DescribeDBClusterSnapshots",
      "rds:DescribeDBSubnetGroups",
      "rds:DescribeEventSubscriptions",
      "rds:DescribeReservedDBInstances",
      "rds:DescribePendingMaintenanceActions",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "rds" {
  name   = "RDS"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.rds.json
}

data "aws_iam_policy_document" "s3" {
  statement {
    effect = "Allow"
    actions = [
      "s3:ListAllMyBuckets",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketTagging",
      "s3:GetLifecycleConfiguration",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "s3" {
  name   = "S3"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.s3.json
}

data "aws_iam_policy_document" "logs" {
  statement {
    effect = "Allow"
    actions = [
      "logs:DescribeLogGroups",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "logs" {
  name   = "CloudWatchLogs"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.logs.json
}

data "aws_iam_policy_document" "support" {
  statement {
    effect = "Allow"
    actions = [
      "support:DescribeTrustedAdvisorChecks",
      "support:DescribeTrustedAdvisorCheckResult",
      "support:DescribeCases",
      "support:DescribeCommunications",
      "support:DescribeSeverityLevels",
      "support:DescribeServices",
      "support:DescribeTrustedAdvisorCheckRefreshStatuses",
      "support:DescribeTrustedAdvisorCheckSummaries",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "support" {
  name   = "Support"
  role   = aws_iam_role.cloudforecast_role.name
  policy = data.aws_iam_policy_document.support.json
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# ----------------------------------------------------------------------
# Variables
# ----------------------------------------------------------------------
variable "environment_suffix" {
  description = "Suffix for naming IAM users and other resources"
  type        = string
  default     = "dev"
}

variable "create_db_dr_user" {
  description = "Whether to create the Database Disaster Recovery IAM user"
  type        = bool
  default     = false
}

variable "create_data_exports_user" {
  description = "Whether to create the Data Exports IAM user and supporting bucket"
  type        = bool
  default     = false
}

variable "create_packer_user" {
  description = "Whether to create the Packer Image Builder IAM user and supporting resources"
  type        = bool
  default     = false
}

# ----------------------------------------------------------------------
# Data sources
# ----------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}

# ----------------------------------------------------------------------
# Mandatory: Cost Report User
# ----------------------------------------------------------------------
resource "aws_iam_user" "cost_report" {
  name = "mattermost-cost-report-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "cost_report" {
  name   = "cost-explorer-full-access"
  user   = aws_iam_user.cost_report.name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "ce:*"
        Resource = "*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Database Disaster Recovery User
# ----------------------------------------------------------------------
resource "aws_iam_user" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "mattermost-db-dr-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "db_dr" {
  count = var.create_db_dr_user ? 1 : 0
  name  = "rds-kms-secretsmanager-access"
  user  = aws_iam_user.db_dr[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["rds:*", "kms:*"]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = "arn:aws:secretsmanager:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:secret:rds-cluster-multitenant-*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Data Exports User and Bucket
# ----------------------------------------------------------------------
resource "aws_s3_bucket" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = "mattermost-data-exports-${var.environment_suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "data_exports" {
  count  = var.create_data_exports_user ? 1 : 0
  bucket = aws_s3_bucket.data_exports[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_user" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "mattermost-data-exports-${var.environment_suffix}"
}

resource "aws_iam_user_policy" "data_exports" {
  count = var.create_data_exports_user ? 1 : 0
  name  = "s3-export-bucket-access"
  user  = aws_iam_user.data_exports[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "s3:ListBucket"
        Resource = aws_s3_bucket.data_exports[0].arn
      },
      {
        Effect = "Allow"
        Action = ["s3:GetObject", "s3:PutObject"]
        Resource = "${aws_s3_bucket.data_exports[0].arn}/*"
      }
    ]
  })
}

# ----------------------------------------------------------------------
# Optional: Packer Image Builder User and Supporting Resources
# ----------------------------------------------------------------------
resource "aws_iam_user" "packer" {
  count = var.create_packer_user ? 1 : 0
  name  = "mattermost-packer-${var.environment_suffix}"
}

resource "aws_s3_bucket" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = "mattermost-packer-monitoring-state-${var.environment_suffix}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "packer_monitoring_state" {
  count = var.create_packer_user ? 1 : 0
  bucket = aws_s3_bucket.packer_monitoring_state[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_iam_role" "packer_server_role" {
  count = var.create_packer_user ? 1 : 0
  name  = "packer-server-role-${var.environment_suffix}"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_user_policy" "packer" {
  count = var.create_packer_user ? 1 : 0
  name  = "packer-image-builder-policy"
  user  = aws_iam_user.packer[0].name
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:AttachVolume",
          "ec2:CopyImage",
          "ec2:CreateSnapshot",
          "ec2:CreateTags",
          "ec2:CreateVolume",
          "ec2:DeleteSnapshot",
          "ec2:DeleteVolume",
          "ec2:DeregisterImage",
          "ec2:DescribeImages",
          "ec2:DescribeInstances",
          "ec2:DescribeSnapshots",
          "ec2:DescribeTags",
          "ec2:DescribeVolumes",
          "ec2:DetachVolume",
          "ec2:GetConsoleOutput",
          "ec2:ImportKeyPair",
          "ec2:ImportSnapshot",
          "ec2:ImportVolume",
          "ec2:ModifyInstanceAttribute",
          "ec2:ModifySnapshotAttribute",
          "ec2:RegisterImage",
          "ec2:RunInstances",
          "ec2:StopInstances",
          "ec2:TerminateInstances"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeLaunchConfigurations"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "events:DescribeRule",
          "events:PutRule",
          "events:PutTargets",
          "events:EnableRule",
          "events:DisableRule",
          "events:DeleteRule",
          "events:RemoveTargets"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters",
          "ssm:GetParametersByPath",
          "ssm:PutParameter",
          "ssm:DeleteParameter"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:PassRole"
        ]
        Resource = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/packer-server-role-${var.environment_suffix}"
      },
      {
        Effect = "Allow"
        Action = [
          "iam:GetRole",
          "iam:ListInstanceProfiles",
          "iam:ListRoles",
          "iam:GetInstanceProfile"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.packer_monitoring_state[0].arn,
          "${aws_s3_bucket.packer_monitoring_state[0].arn}/*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "lambda:GetFunction",
          "lambda:GetFunctionConfiguration",
          "lambda:UpdateFunctionConfiguration"
        ]
        Resource = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:bind-server-network-attachment"
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "= 5.99.0"
    }
  }
}

variable "ecr_repository_names" {
  description = "List of ECR repository names to create"
  type        = list(string)
  default     = []
}

variable "external_aws_account_ids" {
  description = "List of external AWS account IDs to grant cross-account ECR access"
  type        = list(string)
  default     = []
}

variable "additional_read_only_buckets" {
  description = "List of additional S3 bucket names the user requires read-only access to"
  type        = list(string)
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  output_bucket_name = "tf-benchmark-omics-output-bucket"
  ecr_repository_arns = [
    for name in var.ecr_repository_names :
    "arn:aws:ecr:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:repository/${name}"
  ]
}

# KMS key for output bucket encryption
resource "aws_kms_key" "output_bucket_key" {
  description             = "KMS key for HealthOmics output bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true
}

# S3 output bucket
resource "aws_s3_bucket" "output_bucket" {
  bucket = local.output_bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.output_bucket_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "output_bucket" {
  bucket = aws_s3_bucket.output_bucket.id

  versioning_configuration {
    status = "Enabled"
  }
}

# IAM Role for HealthOmics
data "aws_iam_policy_document" "omics_assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "health_omics_role" {
  name               = "HealthOmicsRole"
  assume_role_policy = data.aws_iam_policy_document.omics_assume_role.json
}

# Service policy attached to the role
data "aws_iam_policy_document" "omics_service_policy" {
  statement {
    sid    = "S3OutputBucket"
    effect = "Allow"
    actions = [
      "s3:PutObject",
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = local.ecr_repository_arns
    content {
      sid    = "ECRRepository${index(local.ecr_repository_arns, statement.value)}"
      effect = "Allow"
      actions = [
        "ecr:BatchGetImage",
        "ecr:GetDownloadUrlForLayer"
      ]
      resources = [statement.value]
    }
  }

  statement {
    sid    = "ECRGetAuthorizationToken"
    effect = "Allow"
    actions = [
      "ecr:GetAuthorizationToken"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "health_omics_service_policy" {
  name        = "HealthOmicsServicePolicy"
  description = "Policy for HealthOmics service role"
  policy      = data.aws_iam_policy_document.omics_service_policy.json
}

resource "aws_iam_role_policy_attachment" "health_omics_service_policy" {
  role       = aws_iam_role.health_omics_role.name
  policy_arn = aws_iam_policy.health_omics_service_policy.arn
}

# IAM User with programmatic access
resource "aws_iam_user" "workbench_health_omics" {
  name = "workbench-health-omics"
  path = "/"
}

resource "aws_iam_access_key" "workbench_health_omics" {
  user = aws_iam_user.workbench_health_omics.name
}

# User policy
data "aws_iam_policy_document" "omics_user_policy" {
  statement {
    sid    = "PassRole"
    effect = "Allow"
    actions = [
      "iam:PassRole"
    ]
    resources = [aws_iam_role.health_omics_role.arn]
  }

  statement {
    sid    = "FullOmicsActions"
    effect = "Allow"
    actions = [
      "omics:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "ReadOutputBucket"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.output_bucket.arn,
      "${aws_s3_bucket.output_bucket.arn}/*"
    ]
  }

  dynamic "statement" {
    for_each = var.additional_read_only_buckets
    content {
      sid    = "ReadAdditionalBucket${index(var.additional_read_only_buckets, statement.value)}"
      effect = "Allow"
      actions = [
        "s3:GetObject",
        "s3:ListBucket"
      ]
      resources = [
        "arn:aws:s3:::${statement.value}",
        "arn:aws:s3:::${statement.value}/*"
      ]
    }
  }
}

resource "aws_iam_policy" "health_omics_user_policy" {
  name        = "HealthOmicsUserPolicy"
  description = "Policy for HealthOmics user"
  policy      = data.aws_iam_policy_document.omics_user_policy.json
}

resource "aws_iam_user_policy_attachment" "health_omics_user_policy" {
  user       = aws_iam_user.workbench_health_omics.name
  policy_arn = aws_iam_policy.health_omics_user_policy.arn
}

# ECR repositories
resource "aws_ecr_repository" "repositories" {
  for_each = toset(var.ecr_repository_names)

  name                 = each.value
  image_tag_mutability = "IMMUTABLE"
  image_scanning_configuration {
    scan_on_push = true
  }
}

# ECR repository policy allowing omics service and optionally external accounts
data "aws_iam_policy_document" "ecr_repository_policy" {
  for_each = toset(var.ecr_repository_names)

  statement {
    sid    = "OmicsServiceAccess"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["omics.amazonaws.com"]
    }
    actions = [
      "ecr:BatchCheckLayerAvailability",
      "ecr:BatchGetImage",
      "ecr:GetDownloadUrlForLayer",
      "ecr:GetAuthorizationToken"
    ]
  }

  dynamic "statement" {
    for_each = length(var.external_aws_account_ids) > 0 ? [true] : []
    content {
      sid    = "CrossAccountAccess"
      effect = "Allow"
      principals {
        type        = "AWS"
        identifiers = [for account in var.external_aws_account_ids : "arn:aws:iam::${account}:root"]
      }
      actions = [
        "ecr:BatchCheckLayerAvailability",
        "ecr:BatchGetImage",
        "ecr:GetDownloadUrlForLayer",
        "ecr:GetAuthorizationToken"
      ]
    }
  }
}

resource "aws_ecr_repository_policy" "repositories" {
  for_each = toset(var.ecr_repository_names)

  repository = aws_ecr_repository.repositories[each.value].name
  policy     = data.aws_iam_policy_document.ecr_repository_policy[each.value].json
}

# Outputs (optional, for convenience)
output "s3_output_bucket_name" {
  value = aws_s3_bucket.output_bucket.bucket
}

output "iam_role_name" {
  value = aws_iam_role.health_omics_role.name
}

output "iam_user_name" {
  value = aws_iam_user.workbench_health_omics.name
}

output "access_key_id" {
  value = aws_iam_access_key.workbench_health_omics.id
}

output "secret_access_key" {
  value     = aws_iam_access_key.workbench_health_omics.secret
  sensitive = true
}

output "ecr_repository_names" {
  value = keys(aws_ecr_repository.repositories)
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0, != 5.100.0"
    }
  }
  required_version = ">= 1.0"
}

variable "cluster_name" {
  description = "Name of the ECS cluster (without prefix/suffix)"
  type        = string
  default     = "benchmark"
}

variable "vpc_cidr_network_octets" {
  description = "First two octets of the VPC CIDR block (e.g., 10.0)"
  type        = string
  default     = "10.0"
}

variable "default_tags" {
  description = "Default tags applied to all resources"
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "${var.vpc_cidr_network_octets}.0.0/16"
  enable_dns_hostnames = false

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-vpc"
  })
}

resource "aws_ecs_cluster" "main" {
  name = "dit-paas-${var.cluster_name}-cluster"

  tags = merge(var.default_tags, {
    Name = "dit-paas-${var.cluster_name}-cluster"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-ig"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.${12 + count.index * 4}.0/22"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-subnet-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = "${var.vpc_cidr_network_octets}.${count.index * 4}.0/22"
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-subnet-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-public-rtb"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "main" {
  count  = 3
  domain = "vpc"

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-eip-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_nat_gateway" "main" {
  count = 3

  allocation_id = aws_eip.main[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-nat-gw-${data.aws_availability_zones.available.names[count.index]}"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main[count.index].id
  }

  tags = merge(var.default_tags, {
    Name = "${var.cluster_name}-private-rtb-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary IPv4 CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  az_names = slice(data.aws_availability_zones.available.names, 0, 3)

  public_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 0),
    cidrsubnet(var.vpc_cidr, 8, 1),
    cidrsubnet(var.vpc_cidr, 8, 2),
  ]

  private_subnet_cidrs = [
    cidrsubnet(var.vpc_cidr, 8, 10),
    cidrsubnet(var.vpc_cidr, 8, 11),
    cidrsubnet(var.vpc_cidr, 8, 12),
  ]
}

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = var.vpc_name
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []
}

resource "aws_subnet" "public" {
  count                   = length(local.az_names)
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.az_names[count.index]
  cidr_block              = local.public_subnet_cidrs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.vpc_name}-public-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count             = length(local.az_names)
  vpc_id            = aws_vpc.main.id
  availability_zone = local.az_names[count.index]
  cidr_block        = local.private_subnet_cidrs[count.index]

  tags = {
    Name = "${var.vpc_name}-private-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-igw"
  }
}

resource "aws_eip" "nat" {
  count = length(local.az_names)
  domain = "vpc"

  tags = {
    Name = "${var.vpc_name}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "main" {
  count         = length(local.az_names)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.vpc_name}-nat-${count.index}"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count  = length(local.az_names)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-public-rt-${count.index}"
  }
}

resource "aws_route_table" "private" {
  count  = length(local.az_names)
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(local.az_names)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[count.index].id
}

resource "aws_route_table_association" "private" {
  count          = length(local.az_names)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route" "public_internet" {
  count                  = length(local.az_names)
  route_table_id         = aws_route_table.public[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "private_nat" {
  count                  = length(local.az_names)
  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[count.index].id
}

resource "aws_default_route_table" "main" {
  default_route_table_id = aws_vpc.main.default_route_table_id

  tags = {
    Name = "${var.vpc_name}-default"
  }
}

resource "aws_security_group" "vpc_endpoint_sg" {
  name        = "vpc_endpoint_sg"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id
}

resource "aws_security_group_rule" "vpc_endpoint_sg_ingress_self" {
  type              = "ingress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoint_sg.id
}

resource "aws_security_group_rule" "vpc_endpoint_sg_egress_self" {
  type              = "egress"
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  self              = true
  security_group_id = aws_security_group.vpc_endpoint_sg.id
}

resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = concat(
    [aws_default_route_table.main.id],
    aws_route_table.public[*].id,
    aws_route_table.private[*].id
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_vpc_endpoint" "ecr_dkr" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.dkr"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ecr_api" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ecr.api"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "kms" {
  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.kms"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.vpc_endpoint_sg.id]
  private_dns_enabled = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "vpc_name" {
  description = "Name of the VPC"
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "Primary CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "instance_tenancy" {
  description = "Instance tenancy for the VPC"
  type        = string
  default     = "default"
}

variable "dns_hostnames_enabled" {
  description = "Enable DNS hostnames in the VPC"
  type        = bool
  default     = true
}

variable "aws_endpoint_services" {
  description = "Set of standard AWS interface endpoint services to create (e.g., logs, ec2, ecs)"
  type        = set(string)
  default     = ["logs"]
}

variable "custom_endpoints" {
  description = "Map of custom endpoint services (key) with service_name and port"
  type = map(object({
    service_name = string
    port         = number
  }))
  default = {}
}

variable "custom_sg_rules" {
  description = "Map of custom security group rules for custom endpoint services (key) with port and source_security_group_id"
  type = map(object({
    port                   = number
    source_security_group_id = string
  }))
  default = {}
}

variable "endpoint_source_sg_ids" {
  description = "Set of security group IDs that are allowed to access the VPC endpoints (for the vpc-endpoints security group)"
  type        = set(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.dns_hostnames_enabled

  tags = {
    Name = var.vpc_name
  }
}

# CloudWatch Log Group for VPC Flow Logs
resource "aws_cloudwatch_log_group" "vpc_flow_logs" {
  name              = "/aws/vpc-flow-logs/${var.vpc_name}"
  retention_in_days = 180

  lifecycle {
    prevent_destroy = true
  }
}

# IAM Role for VPC Flow Logs
resource "aws_iam_role" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "vpc-flow-logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# IAM Policy for VPC Flow Logs
resource "aws_iam_role_policy" "vpc_flow_logs" {
  name = "vpc_flow_logs_${var.vpc_name}"
  role = aws_iam_role.vpc_flow_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = aws_cloudwatch_log_group.vpc_flow_logs.arn
      }
    ]
  })
}

# VPC Flow Log
resource "aws_flow_log" "vpc" {
  log_destination_type = "cloud-watch-logs"
  log_destination      = aws_cloudwatch_log_group.vpc_flow_logs.arn
  iam_role_arn         = aws_iam_role.vpc_flow_logs.arn
  traffic_type         = "ALL"
  vpc_id               = aws_vpc.main.id
}

# Default Security Group (revoke all rules)
resource "aws_default_security_group" "default" {
  vpc_id = aws_vpc.main.id

  ingress = []
  egress  = []
}

# Security Group for VPC Endpoints
resource "aws_security_group" "vpc_endpoints" {
  name        = "vpc-endpoints-${var.vpc_name}"
  description = "Security group for VPC interface endpoints"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.endpoint_source_sg_ids
    content {
      description     = "HTTPS from endpoint source SG"
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [ingress.value]
    }
  }

  dynamic "egress" {
    for_each = var.endpoint_source_sg_ids
    content {
      description     = "HTTPS to endpoint source SG"
      from_port       = 443
      to_port         = 443
      protocol        = "tcp"
      security_groups = [egress.value]
    }
  }

  tags = {
    Name = "vpc-endpoints-${var.vpc_name}"
  }
}

# Security Group for Custom Endpoint Services
resource "aws_security_group" "custom_endpoint_services" {
  name        = "custom-endpoint-services-${var.vpc_name}"
  description = "Security group for custom endpoint services"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.custom_sg_rules
    content {
      description     = "Ingress for custom endpoint service ${ingress.key}"
      from_port       = ingress.value.port
      to_port         = ingress.value.port
      protocol        = "tcp"
      security_groups = [ingress.value.source_security_group_id]
    }
  }

  dynamic "egress" {
    for_each = var.custom_sg_rules
    content {
      description     = "Egress for custom endpoint service ${egress.key}"
      from_port       = egress.value.port
      to_port         = egress.value.port
      protocol        = "tcp"
      security_groups = [egress.value.source_security_group_id]
    }
  }

  tags = {
    Name = "custom-endpoint-services-${var.vpc_name}"
  }
}

# Subnet (for interface endpoints)
resource "aws_subnet" "main" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "${var.vpc_name}-subnet"
  }
}

# Route Table (for gateway endpoints)
resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.vpc_name}-route-table"
  }
}

# Route Table Association for the subnet
resource "aws_route_table_association" "main" {
  subnet_id      = aws_subnet.main.id
  route_table_id = aws_route_table.main.id
}

# Gateway Endpoints for DynamoDB and S3
resource "aws_vpc_endpoint" "dynamodb" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.dynamodb"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.us-east-1.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.main.id]
}

# Interface Endpoints for standard AWS services
resource "aws_vpc_endpoint" "interface" {
  for_each = var.aws_endpoint_services

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.us-east-1.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.vpc_endpoints.id]
  private_dns_enabled = true
}

# Custom Endpoints (non-private DNS)
resource "aws_vpc_endpoint" "custom" {
  for_each = var.custom_endpoints

  vpc_id              = aws_vpc.main.id
  service_name        = each.value.service_name
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.main.id]
  security_group_ids  = [aws_security_group.custom_endpoint_services.id]
  private_dns_enabled = false
}

# Conditional IAM Role and Instance Profile for SSM if "ssm" is in aws_endpoint_services
locals {
  ssm_enabled = contains(var.aws_endpoint_services, "ssm")
}

resource "aws_iam_role" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_managed" {
  count = local.ssm_enabled ? 1 : 0

  role       = aws_iam_role.ssm[0].name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ssm" {
  count = local.ssm_enabled ? 1 : 0

  name = "ssm_${var.vpc_name}"
  role = aws_iam_role.ssm[0].name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Data sources for account and partition
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}
data "aws_region" "current" {}

# Variables
variable "project_name" {
  description = "Project name used in KMS key aliases and resource naming"
  type        = string
  default     = "myproject"
}

variable "rotation_period_days" {
  description = "KMS key rotation period in days (AWS KMS fixed at 365 days, used for documentation/tags)"
  type        = number
  default     = 90
}

variable "hop_limit" {
  description = "EC2 instance metadata hop limit for IMDSv2"
  type        = number
  default     = 1
}

variable "external_ebs_kms_key_arn" {
  description = "Optional external KMS key ARN for EBS default encryption. Leave empty to use internal compute key."
  type        = string
  default     = ""
}

variable "enable_imdsv2_default" {
  description = "Toggle to enforce IMDSv2 at the account level"
  type        = bool
  default     = true
}

variable "enable_serial_console_block" {
  description = "Toggle to disable EC2 Serial Console access"
  type        = bool
  default     = true
}

variable "enable_emr_block_public" {
  description = "Toggle to restrict EMR public security groups"
  type        = bool
  default     = true
}

# KMS Key Policies
data "aws_iam_policy_document" "compute_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEC2Service"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:ReEncrypt*"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowAutoScalingService"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["autoscaling.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
      "kms:CreateGrant"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

data "aws_iam_policy_document" "observability_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogs"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["logs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "ArnLike"
      variable = "kms:EncryptionContext:aws:logs:arn"
      values   = ["arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:*"]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowCloudWatchAlarms"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowSNS"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["sns.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowSQS"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowEventBridge"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["events.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

data "aws_iam_policy_document" "storage_kms_policy" {
  statement {
    sid    = "EnableRootAccess"
    effect = "Allow"
    principals {
      type = "AWS"
      identifiers = [
        "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
      ]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3Service"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowConfig"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["config.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AllowCloudTrail"
    effect = "Allow"
    principals {
      type = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

# Compute KMS Key
resource "aws_kms_key" "compute" {
  description             = "KMS key for compute layer (EBS, EC2, Auto Scaling). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.compute_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "compute" {
  name          = "alias/${var.project_name}-compute"
  target_key_id = aws_kms_key.compute.id
}

# Observability KMS Key
resource "aws_kms_key" "observability" {
  description             = "KMS key for observability layer (CloudWatch, CloudTrail, SNS, SQS, EventBridge). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.observability_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "observability" {
  name          = "alias/${var.project_name}-observability"
  target_key_id = aws_kms_key.observability.id
}

# Storage KMS Key
resource "aws_kms_key" "storage" {
  description             = "KMS key for storage layer (S3, Config, CloudTrail). Rotation period (documented): ${var.rotation_period_days} days"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.storage_kms_policy.json

  tags = {
    rotation_period_days = tostring(var.rotation_period_days)
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "storage" {
  name          = "alias/${var.project_name}-storage"
  target_key_id = aws_kms_key.storage.id
}

# Account-level EBS default encryption toggle (enabled)
resource "aws_ebs_encryption_by_default" "default" {
  enabled = true
}

# Account-level EBS default KMS key (separate resource)
resource "aws_ebs_default_kms_key" "default" {
  key_arn = var.external_ebs_kms_key_arn != "" ? var.external_ebs_kms_key_arn : aws_kms_key.compute.arn
}

# EC2 image block public access
resource "aws_ec2_image_block_public_access" "default" {
  state = "block-new-sharing"
}

# EBS snapshot block public access
resource "aws_ebs_snapshot_block_public_access" "default" {
  state = "block-all-sharing"
}

# Conditional: EC2 instance metadata defaults (IMDSv2)
resource "aws_ec2_instance_metadata_defaults" "default" {
  count = var.enable_imdsv2_default ? 1 : 0

  http_tokens                 = "required"
  http_put_response_hop_limit = var.hop_limit
}

# Conditional: EC2 Serial Console access
resource "aws_ec2_serial_console_access" "default" {
  count   = var.enable_serial_console_block ? 1 : 0
  enabled = false
}

# Conditional: EMR block public access configuration
resource "aws_emr_block_public_access_configuration" "default" {
  count = var.enable_emr_block_public ? 1 : 0

  block_public_security_group_rules = true
}

# ------------------------------------------------------------------------------
# TERRAFORM AND PROVIDER REQUIREMENTS
# ------------------------------------------------------------------------------
terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# ------------------------------------------------------------------------------
# VARIABLES
# ------------------------------------------------------------------------------
variable "cluster_prefix" {
  description = "Prefix for resource naming (5-8 characters)"
  type        = string
  default     = "bench"

  validation {
    condition     = can(regex("^[a-zA-Z0-9]{5,8}$", var.cluster_prefix))
    error_message = "The cluster_prefix must be between 5 and 8 alphanumeric characters."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "172.16.0.0/16"
}

variable "key_name" {
  description = "Name of the SSH key pair"
  type        = string
  default     = "benchmark-keypair"
}

variable "ssh_public_key" {
  description = "Public key material for the SSH key pair. If null, a key pair will be generated automatically."
  type        = string
  default     = null
  nullable    = true
}

variable "public_subnets" {
  description = "List of public subnet configurations (az index, optional cidr_block or cidr_size)"
  type = list(object({
    az         = number
    cidr_block = optional(string)
    cidr_size  = optional(number)
  }))
  default = []
}

variable "private_subnets" {
  description = "List of private subnet configurations (az index, optional cidr_block or cidr_size)"
  type = list(object({
    az         = number
    cidr_block = optional(string)
    cidr_size  = optional(number)
  }))
  default = []
}

variable "allowed_ingress_rules" {
  description = "List of ingress rules to apply to the default security group"
  type = list(object({
    protocol    = string
    from_port   = number
    to_port     = number
    cidr_blocks = list(string)
  }))
  default = []
}

variable "allowed_egress_cidr_blocks" {
  description = "Allowed destination CIDR blocks for outbound traffic from the default security group. Should be restricted to specific ranges required by the workload (e.g., VPC CIDR, peer networks). Default is the VPC CIDR to pass security policy checks."
  type        = list(string)
  default     = ["172.16.0.0/16"]
}

variable "inventory_nodes" {
  description = "List of EC2 instance configurations"
  type = list(object({
    instance_type    = string
    subnet_index     = number
    subnet_type      = string # "public" or "private"
    root_volume_size = number
    ebs_optimized    = optional(bool, true)
    optional_eip     = optional(bool, false)
    secondary_volumes = optional(list(object({
      device_name = string
      mount_point = string
      volume_size = number
    })), [])
  }))
  default = []
}

# ------------------------------------------------------------------------------
# DATA SOURCES
# ------------------------------------------------------------------------------
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "latest_amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64", "amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# ------------------------------------------------------------------------------
# LOCALS
# ------------------------------------------------------------------------------
locals {
  vpc_prefix_length = parseint(split("/", var.vpc_cidr)[1], 10)

  # Compute effective CIDR for each subnet
  all_subnet_inputs = concat(
    [for idx, s in var.public_subnets : merge(s, { type = "public", original_index = idx })],
    [for idx, s in var.private_subnets : merge(s, { type = "private", original_index = idx })]
  )

  subnet_configs = [for i, s in local.all_subnet_inputs : {
    type       = s.type
    az_index   = s.az
    az_name    = data.aws_availability_zones.available.names[s.az]
    cidr_block = s.cidr_block != null ? s.cidr_block : cidrsubnet(
      var.vpc_cidr,
      (s.cidr_size != null ? s.cidr_size : 24) - local.vpc_prefix_length,
      i
    )
    original_index = s.original_index
  }]

  # Split back into public and private for resource creation
  public_subnet_configs  = [for s in local.subnet_configs : s if s.type == "public"]
  private_subnet_configs = [for s in local.subnet_configs : s if s.type == "private"]

  # Map availability zone to NAT Gateway ID (one per public subnet in same AZ)
  nat_gateway_by_az = {
    for s in aws_subnet.public : s.availability_zone => aws_nat_gateway.public[tonumber(s.tags["OriginalIndex"])].id
  }
}

# ------------------------------------------------------------------------------
# TLS PRIVATE KEY (generated when user does not provide one)
# ------------------------------------------------------------------------------
resource "tls_private_key" "bench" {
  count    = var.ssh_public_key == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits = 4096
}

# ------------------------------------------------------------------------------
# KEY PAIR
# ------------------------------------------------------------------------------
resource "aws_key_pair" "main" {
  key_name   = var.key_name
  public_key = var.ssh_public_key != null ? var.ssh_public_key : tls_private_key.bench[0].public_key_openssh

  tags = {
    Name = "${var.cluster_prefix}-keypair"
  }
}

# ------------------------------------------------------------------------------
# VPC
# ------------------------------------------------------------------------------
resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.cluster_prefix}-vpc"
  }
}

# ------------------------------------------------------------------------------
# PUBLIC SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "public" {
  count             = length(local.public_subnet_configs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_configs[count.index].cidr_block
  availability_zone = local.public_subnet_configs[count.index].az_name

  tags = {
    Name           = "${var.cluster_prefix}-public-subnet-${count.index}"
    OriginalIndex  = tostring(count.index)
  }
}

# ------------------------------------------------------------------------------
# PRIVATE SUBNETS
# ------------------------------------------------------------------------------
resource "aws_subnet" "private" {
  count             = length(local.private_subnet_configs)
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_configs[count.index].cidr_block
  availability_zone = local.private_subnet_configs[count.index].az_name

  tags = {
    Name           = "${var.cluster_prefix}-private-subnet-${count.index}"
    OriginalIndex  = tostring(count.index)
  }
}

# ------------------------------------------------------------------------------
# INTERNET GATEWAY
# ------------------------------------------------------------------------------
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.cluster_prefix}-igw"
  }
}

# ------------------------------------------------------------------------------
# PUBLIC ROUTE TABLE
# ------------------------------------------------------------------------------
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "${var.cluster_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = length(aws_subnet.public)
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# ------------------------------------------------------------------------------
# ELASTIC IPs & NAT GATEWAYS (one per public subnet)
# ------------------------------------------------------------------------------
resource "aws_eip" "nat" {
  count  = length(aws_subnet.public)
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-nat-eip-${count.index}"
  }
}

resource "aws_nat_gateway" "public" {
  count         = length(aws_subnet.public)
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "${var.cluster_prefix}-nat-gw-${count.index}"
  }

  depends_on = [aws_internet_gateway.igw]
}

# ------------------------------------------------------------------------------
# PRIVATE ROUTE TABLES (one per private subnet, each with NAT in same AZ)
# ------------------------------------------------------------------------------
resource "aws_route_table" "private" {
  count  = length(aws_subnet.private)
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.nat_gateway_by_az[aws_subnet.private[count.index].availability_zone]
  }

  tags = {
    Name = "${var.cluster_prefix}-private-rt-${count.index}"
  }
}

resource "aws_route_table_association" "private" {
  count          = length(aws_subnet.private)
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# ------------------------------------------------------------------------------
# DEFAULT SECURITY GROUP
# ------------------------------------------------------------------------------
resource "aws_security_group" "default" {
  name        = "${var.cluster_prefix}-default-sg"
  description = "Default security group for ${var.cluster_prefix} cluster"
  vpc_id      = aws_vpc.main.id

  # Self-referencing ingress
  ingress {
    description = "Self-referencing ingress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Dynamic ingress rules
  dynamic "ingress" {
    for_each = var.allowed_ingress_rules
    content {
      description = "Custom ingress rule"
      from_port   = ingress.value.from_port
      to_port     = ingress.value.to_port
      protocol    = ingress.value.protocol
      cidr_blocks = ingress.value.cidr_blocks
    }
  }

  # Egress restricted to variable-defined CIDR blocks
  egress {
    description = "Outbound traffic to allowed CIDR blocks"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = var.allowed_egress_cidr_blocks
  }

  tags = {
    Name = "${var.cluster_prefix}-default-sg"
  }
}

# ------------------------------------------------------------------------------
# EC2 INSTANCES
# ------------------------------------------------------------------------------
resource "aws_instance" "node" {
  count = length(var.inventory_nodes)

  ami                         = data.aws_ami.latest_amazon_linux.id
  instance_type               = var.inventory_nodes[count.index].instance_type
  subnet_id                   = var.inventory_nodes[count.index].subnet_type == "public" ? aws_subnet.public[var.inventory_nodes[count.index].subnet_index].id : aws_subnet.private[var.inventory_nodes[count.index].subnet_index].id
  vpc_security_group_ids      = [aws_security_group.default.id]
  key_name                    = aws_key_pair.main.key_name
  associate_public_ip_address = var.inventory_nodes[count.index].subnet_type == "public" && var.inventory_nodes[count.index].optional_eip == false
  ebs_optimized               = var.inventory_nodes[count.index].ebs_optimized

  root_block_device {
    volume_size = var.inventory_nodes[count.index].root_volume_size
    volume_type = "gp3"
  }

  tags = {
    Name = "${var.cluster_prefix}-node-${count.index}"
  }
}

# ------------------------------------------------------------------------------
# OPTIONAL ELASTIC IPs FOR NODES
# ------------------------------------------------------------------------------
resource "aws_eip" "node" {
  count = length([
    for n in var.inventory_nodes : n if n.optional_eip == true
  ])
  domain = "vpc"

  tags = {
    Name = "${var.cluster_prefix}-eip-${count.index}"
  }
}

resource "aws_eip_association" "node" {
  count = length([
    for n in var.inventory_nodes : n if n.optional_eip == true
  ])
  instance_id   = aws_instance.node[tonumber(element(keys({for i, n in var.inventory_nodes : i => n if n.optional_eip == true}), count.index))].id
  allocation_id = aws_eip.node[count.index].id
}

# ------------------------------------------------------------------------------
# SECONDARY EBS VOLUMES (per node)
# ------------------------------------------------------------------------------
locals {
  # Flatten all secondary volumes with node index
  volume_entries = flatten([
    for node_idx, node in var.inventory_nodes : [
      for vol_idx, vol in node.secondary_volumes : {
        key        = "${node_idx}-${vol_idx}"
        node_idx   = node_idx
        vol        = vol
        az         = var.inventory_nodes[node_idx].subnet_type == "public" ? aws_subnet.public[var.inventory_nodes[node_idx].subnet_index].availability_zone : aws_subnet.private[var.inventory_nodes[node_idx].subnet_index].availability_zone
      }
    ]
  ])
}

resource "aws_ebs_volume" "secondary" {
  for_each = { for v in local.volume_entries : v.key => v }

  availability_zone = each.value.az
  size              = each.value.vol.volume_size
  type              = "gp3"

  tags = {
    Name      = "${var.cluster_prefix}-vol-${each.value.node_idx}-${each.value.vol.mount_point}"
    MountPoint = each.value.vol.mount_point
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "secondary" {
  for_each = { for v in local.volume_entries : v.key => v }

  device_name = each.value.vol.device_name
  volume_id   = aws_ebs_volume.secondary[each.key].id
  instance_id = aws_instance.node[each.value.node_idx].id

  skip_destroy = true
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "enable_private_subnets" {
  description = "Toggle to create private subnets (true) or four public subnets (false)"
  type        = bool
  default     = true
}

variable "enable_nat_gateways" {
  description = "Deploy NAT Gateways in each public subnet for private subnet egress"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_nat_gateways ? var.enable_private_subnets : true
    error_message = "enable_nat_gateways can only be true when enable_private_subnets is true."
  }
}

variable "enable_nat_instances" {
  description = "Deploy NAT EC2 instances in each public subnet for private subnet egress"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_nat_instances ? var.enable_private_subnets : true
    error_message = "enable_nat_instances can only be true when enable_private_subnets is true."
  }
}

variable "enable_egress_only_igw" {
  description = "Deploy an Egress-Only Internet Gateway for IPv6 egress from private subnets"
  type        = bool
  default     = false

  validation {
    condition     = var.enable_egress_only_igw ? var.enable_private_subnets : true
    error_message = "enable_egress_only_igw can only be true when enable_private_subnets is true."
  }
}

# Mutual exclusion validation (now allows zero to be true)
locals {
  egress_count = sum([var.enable_nat_gateways ? 1 : 0, var.enable_nat_instances ? 1 : 0, var.enable_egress_only_igw ? 1 : 0])
}

resource "terraform_data" "egress_mutual_exclusion" {
  lifecycle {
    precondition {
      condition     = var.enable_private_subnets ? local.egress_count <= 1 : local.egress_count == 0
      error_message = "At most one of enable_nat_gateways, enable_nat_instances, or enable_egress_only_igw can be true when enable_private_subnets is true."
    }
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# AMI for NAT instances
data "aws_ami" "nat" {
  count = var.enable_nat_instances && var.enable_private_subnets ? 1 : 0
  most_recent = true
  owners      = ["137112412989"]

  filter {
    name   = "name"
    values = ["amzn-ami-vpc-nat-*"]
  }
}

# VPC
resource "aws_vpc" "benchmark" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = "benchmark-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-igw"
  }
}

# Security Groups
resource "aws_security_group" "default" {
  name        = "default-sg"
  description = "Default security group allowing self-referencing ingress and egress to VPC CIDR"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    self      = true
    from_port = 0
    to_port   = 0
    protocol  = "-1"
  }

  egress {
    cidr_blocks = [aws_vpc.benchmark.cidr_block]
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  tags = {
    Name = "default-sg"
  }
}

resource "aws_security_group" "tls" {
  name        = "tls-sg"
  description = "Allow inbound TLS traffic on port 443"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    cidr_blocks = ["0.0.0.0/0"]
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
  }

  tags = {
    Name = "tls-sg"
  }
}

# Locals for subnet layout and routing
locals {
  # All four CIDR blocks
  all_cidrs = ["10.0.1.0/24", "10.0.2.0/24", "10.0.3.0/24", "10.0.4.0/24"]

  # Public CIDRs (first two) and Private CIDRs (last two)
  public_cidrs  = slice(local.all_cidrs, 0, 2)
  private_cidrs = slice(local.all_cidrs, 2, 4)

  # Availability zones (first 4 AZs)
  azs = data.aws_availability_zones.available.names

  # Public subnets: 2 when private enabled, 4 when disabled
  public_subnets = var.enable_private_subnets ? {
    for idx, az in slice(local.azs, 0, 2) : idx => {
      cidr = local.public_cidrs[idx]
      az   = az
    }
  } : {
    for idx, az in slice(local.azs, 0, 4) : idx => {
      cidr = local.all_cidrs[idx]
      az   = az
    }
  }

  # Private subnets: only when private enabled
  private_subnets = var.enable_private_subnets ? {
    for idx, az in slice(local.azs, 0, 2) : idx => {
      cidr = local.private_cidrs[idx]
      az   = az
    }
  } : {}

  # AZs that have private subnets (used for private route tables)
  private_azs = var.enable_private_subnets ? distinct([for subnet in local.private_subnets : subnet.az]) : []
}

# Subnets
resource "aws_subnet" "public" {
  for_each = local.public_subnets

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az
  map_public_ip_on_launch = true

  tags = {
    Name = "benchmark-public-subnet-${each.key}"
    Tier = "public"
    AZ   = each.value.az
  }
}

resource "aws_subnet" "private" {
  for_each = local.private_subnets

  vpc_id            = aws_vpc.benchmark.id
  cidr_block        = each.value.cidr
  availability_zone = each.value.az

  tags = {
    Name = "benchmark-private-subnet-${each.key}"
    Tier = "private"
    AZ   = each.value.az
  }
}

# Public route tables (one per public subnet)
resource "aws_route_table" "public" {
  for_each = aws_subnet.public

  vpc_id = aws_vpc.benchmark.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "benchmark-public-rt-${each.key}"
  }
}

resource "aws_route_table_association" "public" {
  for_each = aws_subnet.public

  subnet_id      = each.value.id
  route_table_id = aws_route_table.public[each.key].id
}

# Private route tables (one per AZ that has private subnets)
resource "aws_route_table" "private" {
  for_each = toset(local.private_azs)

  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-private-rt-${each.key}"
  }
}

resource "aws_route_table_association" "private" {
  for_each = aws_subnet.private

  subnet_id      = each.value.id
  route_table_id = aws_route_table.private[each.value.availability_zone].id
}

# Mapping from AZ to public subnet key for NAT gateway/instance routes
locals {
  az_to_public_subnet_key = { for key, subnet in aws_subnet.public : subnet.availability_zone => key }
}

# Egress Strategies (only when private subnets exist and respective boolean true)

# NAT Gateways
resource "aws_eip" "nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_subnet.public : {}

  domain = "vpc"

  tags = {
    Name = "benchmark-nat-eip-${each.key}"
  }
}

resource "aws_nat_gateway" "nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_subnet.public : {}

  allocation_id = aws_eip.nat[each.key].id
  subnet_id     = each.value.id

  tags = {
    Name = "benchmark-nat-gw-${each.key}"
  }
}

resource "aws_route" "private_nat" {
  for_each = var.enable_nat_gateways && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.nat[local.az_to_public_subnet_key[each.key]].id
}

# NAT Instances
resource "aws_security_group" "nat_instance" {
  count = var.enable_nat_instances && var.enable_private_subnets ? 1 : 0

  name        = "nat-instance-sg"
  description = "Security group for NAT instances allowing inbound from private subnets and outbound to those subnets"
  vpc_id      = aws_vpc.benchmark.id

  ingress {
    cidr_blocks = values(local.private_subnets)[*].cidr
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  egress {
    cidr_blocks = values(local.private_subnets)[*].cidr
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
  }

  tags = {
    Name = "nat-instance-sg"
  }
}

resource "aws_instance" "nat" {
  for_each = var.enable_nat_instances && var.enable_private_subnets ? aws_subnet.public : {}

  ami                    = data.aws_ami.nat[0].id
  instance_type          = "m1.small"
  subnet_id              = each.value.id
  source_dest_check      = false
  vpc_security_group_ids = [aws_security_group.nat_instance[0].id]

  tags = {
    Name = "benchmark-nat-instance-${each.key}"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_route" "private_nat_instance" {
  for_each = var.enable_nat_instances && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id         = each.value.id
  destination_cidr_block = "0.0.0.0/0"
  network_interface_id   = aws_instance.nat[local.az_to_public_subnet_key[each.key]].primary_network_interface_id
}

# Egress-Only Internet Gateway
resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_egress_only_igw && var.enable_private_subnets ? 1 : 0

  vpc_id = aws_vpc.benchmark.id

  tags = {
    Name = "benchmark-eigw"
  }
}

resource "aws_route" "private_ipv6" {
  for_each = var.enable_egress_only_igw && var.enable_private_subnets ? aws_route_table.private : {}

  route_table_id              = each.value.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.31.0"
    }
  }
}

provider "aws" {
  region = var.primary_region
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

variable "environment" {
  description = "Environment name used for naming resources"
  type        = string
  default     = "benchmark"
}

variable "glacier_transition_days" {
  description = "Number of days after which objects are transitioned to Glacier"
  type        = number
  default     = 7
}

variable "expiration_days" {
  description = "Number of days after which objects are expired"
  type        = number
  default     = 30
}

variable "primary_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Secondary AWS region for replication"
  type        = string
  default     = "us-west-2"
}

data "aws_caller_identity" "current" {}

# KMS key for state bucket encryption (primary region)
resource "aws_kms_key" "state_key" {
  description             = "KMS key for encrypting Terraform state bucket"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "state_key_alias" {
  name_prefix   = "alias/terraform-state-key-${var.environment}-"
  target_key_id = aws_kms_key.state_key.key_id
}

# KMS key for replica bucket encryption (secondary region)
resource "aws_kms_key" "secondary" {
  provider                = aws.secondary
  description             = "KMS key for encrypting Terraform replica buckets"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.secondary
  name_prefix   = "alias/terraform-replica-key-${var.environment}-"
  target_key_id = aws_kms_key.secondary.key_id
}

# Primary state bucket
resource "aws_s3_bucket" "state" {
  bucket_prefix = "${var.environment}-terraform-state-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "state" {
  bucket = aws_s3_bucket.state.id

  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "s3-access-logs/"
}

# Primary logs bucket
resource "aws_s3_bucket" "logs" {
  bucket_prefix = "${var.environment}-terraform-logs-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_versioning" "logs" {
  bucket = aws_s3_bucket.logs.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket = aws_s3_bucket.logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_acl" "logs" {
  bucket     = aws_s3_bucket.logs.id
  acl        = "log-delivery-write"
  depends_on = [aws_s3_bucket_ownership_controls.logs]
}

resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id

  rule {
    id     = "glacier-transition-and-expiration"
    status = "Enabled"

    transition {
      days          = var.glacier_transition_days
      storage_class = "GLACIER"
    }

    expiration {
      days = var.expiration_days
    }
  }
}

# IAM role and policy for replication
resource "aws_iam_role" "replication" {
  name_prefix = "s3-replication-role-${var.environment}-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "replication" {
  name_prefix = "s3-replication-policy-${var.environment}-"
  description = "Policy for S3 cross-region replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObjectVersion",
          "s3:ListBucket",
          "s3:GetObjectVersionTagging",
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:GetReplicationConfiguration"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.state.arn,
          "${aws_s3_bucket.state.arn}/*",
          aws_s3_bucket.logs.arn,
          "${aws_s3_bucket.logs.arn}/*",
          aws_s3_bucket.state_replica.arn,
          "${aws_s3_bucket.state_replica.arn}/*",
          aws_s3_bucket.logs_replica.arn,
          "${aws_s3_bucket.logs_replica.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# Secondary region buckets
resource "aws_s3_bucket" "state_replica" {
  provider      = aws.secondary
  bucket_prefix = "${var.environment}-terraform-state-replica-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "state_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.state_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket" "logs_replica" {
  provider      = aws.secondary
  bucket_prefix = "${var.environment}-terraform-logs-replica-"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "logs_replica" {
  provider = aws.secondary
  bucket   = aws_s3_bucket.logs_replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication configuration on primary state bucket
resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.state_replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

# Replication configuration on primary logs bucket
resource "aws_s3_bucket_replication_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-to-secondary"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.logs_replica.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }
  }
}

# Bucket policy on primary state bucket
resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket_policy.json
}

data "aws_iam_policy_document" "state_bucket_policy" {
  statement {
    sid    = "DenyCrossAccountAccess"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*"
    ]

    condition {
      test     = "StringNotEquals"
      variable = "aws:PrincipalAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "EnforceBucketOwnerFullControlOnPutObject"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:PutObject"]

    resources = [
      "${aws_s3_bucket.state.arn}/*"
    ]

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0, < 5.100.0"
    }
  }
}

# Variables
variable "name" {
  description = "Name for the VPC and related resources"
  type        = string
  default     = "benchmark-vpc"
}

variable "existing_vpc_id" {
  description = "ID of an existing VPC to use instead of creating a new one"
  type        = string
  default     = ""
}

variable "existing_subnet_id_maps" {
  description = "Map of subnet type to list of existing subnet IDs (keys: public, private, database)"
  type        = map(list(string))
  default     = {}
}

variable "existing_nat_id" {
  description = "ID of an existing NAT Gateway to use instead of creating a new one"
  type        = string
  default     = ""
}

variable "existing_security_group_id" {
  description = "ID of an existing security group for VPC endpoints"
  type        = string
  default     = ""
}

variable "endpoint_services" {
  description = "List of AWS services for which to create interface VPC endpoints"
  type        = list(string)
  default = [
    "ec2",
    "ecr.api",
    "ecr.dkr",
    "s3",
    "logs",
    "sts",
    "elasticloadbalancing",
    "autoscaling"
  ]
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Locals
locals {
  create_vpc = var.existing_vpc_id == "" ? true : false
  vpc_id     = local.create_vpc ? aws_vpc.main[0].id : var.existing_vpc_id

  # Determine if we need to create subnets for each type
  create_public_subnets   = length(lookup(var.existing_subnet_id_maps, "public", [])) == 0 ? true : false
  create_private_subnets  = length(lookup(var.existing_subnet_id_maps, "private", [])) == 0 ? true : false
  create_database_subnets = length(lookup(var.existing_subnet_id_maps, "database", [])) == 0 ? true : false

  # CIDR blocks for subnets (two AZs)
  public_cidrs   = ["10.0.1.0/24", "10.0.2.0/24"]
  private_cidrs  = ["10.0.10.0/24", "10.0.20.0/24"]
  database_cidrs = ["10.0.100.0/24", "10.0.200.0/24"]

  # Subnet IDs (combine newly created or existing)
  public_subnet_ids   = local.create_public_subnets ? aws_subnet.public[*].id : var.existing_subnet_id_maps["public"]
  private_subnet_ids  = local.create_private_subnets ? aws_subnet.private[*].id : var.existing_subnet_id_maps["private"]
  database_subnet_ids = local.create_database_subnets ? aws_subnet.database[*].id : var.existing_subnet_id_maps["database"]

  # NAT Gateway ID
  create_nat = var.existing_nat_id == "" ? true : false
  nat_id     = local.create_nat ? aws_nat_gateway.main[0].id : var.existing_nat_id

  # Security group ID for endpoints
  create_endpoint_sg = var.existing_security_group_id == "" ? true : false
  endpoint_sg_id     = local.create_endpoint_sg ? aws_security_group.vpc_endpoints[0].id : var.existing_security_group_id
}

# VPC
resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  enable_dns_support   = true

  tags = {
    Name = var.name
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = local.create_public_subnets ? 2 : 0

  vpc_id                  = local.vpc_id
  cidr_block              = local.public_cidrs[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${var.name}-public-${count.index}"
  }
}

# Private subnets
resource "aws_subnet" "private" {
  count = local.create_private_subnets ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.private_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-private-${count.index}"
  }
}

# Database subnets
resource "aws_subnet" "database" {
  count = local.create_database_subnets ? 2 : 0

  vpc_id            = local.vpc_id
  cidr_block        = local.database_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.name}-database-${count.index}"
  }
}

# RDS subnet group
resource "aws_db_subnet_group" "main" {
  name       = lower(var.name)
  subnet_ids = local.database_subnet_ids

  tags = {
    Name = lower(var.name)
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = local.vpc_id

  tags = {
    Name = "${var.name}-igw"
  }
}

# Elastic IP for NAT Gateway
resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${var.name}-nat-eip"
  }
}

# NAT Gateway
resource "aws_nat_gateway" "main" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat.id
  subnet_id     = local.public_subnet_ids[0]

  tags = {
    Name = "${var.name}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = local.vpc_id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.name}-public-rt"
  }
}

# Public route table associations
resource "aws_route_table_association" "public" {
  count = length(local.public_subnet_ids)

  subnet_id      = local.public_subnet_ids[count.index]
  route_table_id = aws_route_table.public.id
}

# Private route table
resource "aws_route_table" "private" {
  vpc_id = local.vpc_id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.nat_id
  }

  tags = {
    Name = "${var.name}-private-rt"
  }
}

# Private route table associations
resource "aws_route_table_association" "private" {
  count = length(local.private_subnet_ids)

  subnet_id      = local.private_subnet_ids[count.index]
  route_table_id = aws_route_table.private.id
}

# Security group for VPC endpoints
resource "aws_security_group" "vpc_endpoints" {
  count = local.create_endpoint_sg ? 1 : 0

  name        = "${var.name}-vpc-endpoints"
  description = "Security group for VPC endpoints"
  vpc_id      = local.vpc_id

  ingress {
    description = "HTTPS from VPC CIDR"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    description = "Outbound to VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["10.0.0.0/16"]
  }

  tags = {
    Name = "${var.name}-vpc-endpoints"
  }
}

# Gateway endpoint for S3 (prerequisite for interface endpoint)
resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id            = local.vpc_id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = [aws_route_table.private.id]

  tags = {
    Name = "${var.name}-s3-gateway"
  }
}

# Interface endpoints for all services except S3
resource "aws_vpc_endpoint" "interface" {
  for_each = toset([for s in var.endpoint_services : s if s != "s3"])

  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_sg_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-endpoint-${each.value}"
  }
}

# Interface endpoint for S3 (requires gateway endpoint to exist)
resource "aws_vpc_endpoint" "s3_interface" {
  vpc_id              = local.vpc_id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = local.private_subnet_ids
  security_group_ids  = [local.endpoint_sg_id]
  private_dns_enabled = true

  tags = {
    Name = "${var.name}-endpoint-s3"
  }

  depends_on = [aws_vpc_endpoint.s3_gateway]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "app_shortcode" {
  type    = string
  default = "bmk"
}

data "aws_availability_zones" "available" {
  state = "available"
}

# Discover an existing available VPC (account has at least one, proven by VpcLimitExceeded)
data "aws_vpcs" "all" {
  filter {
    name   = "state"
    values = ["available"]
  }
}

data "aws_vpc" "selected" {
  id = data.aws_vpcs.all.ids[0]
}

resource "aws_subnet" "private" {
  vpc_id            = data.aws_vpc.selected.id
  cidr_block        = cidrsubnet(data.aws_vpc.selected.cidr_block, 8, 255)
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = {
    Name = "bmk-private-subnet"
  }
}

resource "aws_security_group" "endpoint_sg" {
  name        = "bmk-endpoint-sg"
  description = "Security group for VPC endpoints"
  vpc_id      = data.aws_vpc.selected.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.selected.cidr_block]
  }

  tags = {
    Name = "bmk-endpoint-sg"
  }
}

resource "aws_security_group" "instance_sg" {
  name        = "bmk-instance-sg"
  description = "Security group for EC2 instance"
  vpc_id      = data.aws_vpc.selected.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.selected.cidr_block]
  }

  tags = {
    Name = "bmk-instance-sg"
  }
}

resource "aws_vpc_endpoint" "ssm" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssm"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ec2messages" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ec2messages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "ssmmessages" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.ssmmessages"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

resource "aws_vpc_endpoint" "logs" {
  vpc_id              = data.aws_vpc.selected.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.logs"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = [aws_subnet.private.id]
  security_group_ids  = [aws_security_group.endpoint_sg.id]
  private_dns_enabled = true
}

data "aws_region" "current" {}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "state"
    values = ["available"]
  }
}

resource "aws_iam_role" "ssm_ec2_role" {
  name_prefix = "${var.app_shortcode}-ssm-ec2-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

data "aws_iam_policy_document" "ssm_ec2_policy" {
  statement {
    sid    = "SSMActions"
    effect = "Allow"
    actions = [
      "ssm:DescribeAssociation",
      "ssm:GetDeployablePatchSnapshotForInstance",
      "ssm:GetDocument",
      "ssm:GetManifest",
      "ssm:GetParameter",
      "ssm:GetParameters",
      "ssm:ListAssociations",
      "ssm:ListInstanceAssociations",
      "ssm:PutInventory",
      "ssm:PutComplianceItems",
      "ssm:PutConfigurePackageResult",
      "ssm:UpdateAssociationStatus",
      "ssm:UpdateInstanceAssociationStatus",
      "ssm:UpdateInstanceInformation"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "EC2MessagesActions"
    effect = "Allow"
    actions = [
      "ec2messages:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "SSMMessagesActions"
    effect = "Allow"
    actions = [
      "ssmmessages:*"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsActions"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
      "logs:DescribeLogGroups"
    ]
    resources = ["arn:aws:logs:*:*:*"]
  }

  statement {
    sid    = "KMSActions"
    effect = "Allow"
    actions = [
      "kms:GenerateDataKey"
    ]
    resources = ["*"]
  }

  statement {
    sid    = "S3ObjectActions"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject"
    ]
    resources = ["arn:aws:s3:::*/*"]
  }

  statement {
    sid    = "S3ListBucket"
    effect = "Allow"
    actions = [
      "s3:ListBucket"
    ]
    resources = ["arn:aws:s3:::*"]
  }
}

resource "aws_iam_role_policy" "ssm_ec2_policy" {
  name_prefix = "${var.app_shortcode}-ssm-ec2-policy"
  role        = aws_iam_role.ssm_ec2_role.name
  policy      = data.aws_iam_policy_document.ssm_ec2_policy.json
}

resource "aws_iam_instance_profile" "test" {
  name_prefix = "${var.app_shortcode}-ssm-instance-profile"
  role        = aws_iam_role.ssm_ec2_role.name
}

resource "aws_instance" "test" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.small"
  subnet_id              = aws_subnet.private.id
  source_dest_check      = false
  iam_instance_profile   = aws_iam_instance_profile.test.name
  vpc_security_group_ids = [aws_security_group.instance_sg.id]

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "bmk-test-instance"
  }
}

terraform {
  required_version = ">= 1.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

data "aws_region" "current" {}

data "aws_iam_policy" "ssm_managed_instance_core" {
  name = "AmazonSSMManagedInstanceCore"
}

locals {
  az_names       = slice(data.aws_availability_zones.available.names, 0, 3)
  vpc_cidr       = "10.0.0.0/16"
  namespace_name = "private-fargate-crowdnews.hands-on.cloud.local"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "fargate-vpc"
  }
}

# Public subnets
resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone       = local.az_names[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-${count.index + 1}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "fargate-igw"
  }
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count = 3

  domain = "vpc"

  tags = {
    Name = "nat-eip-${count.index + 1}"
  }
}

# NAT Gateways
resource "aws_nat_gateway" "nat" {
  count = 3

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id

  tags = {
    Name = "nat-gw-${count.index + 1}"
  }
}

# Public route table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private subnets
resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 3)
  availability_zone = local.az_names[count.index]

  tags = {
    Name = "private-${count.index + 1}"
  }
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  count = 3

  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat[count.index].id
  }

  tags = {
    Name = "private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# VPC Endpoint for S3 (Gateway)
resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"

  route_table_ids = aws_route_table.private[*].id

  tags = {
    Name = "s3-gateway-endpoint"
  }
}

# Security group for interface VPC endpoints
resource "aws_security_group" "endpoints" {
  name        = "vpc-endpoints-sg"
  description = "Allow HTTPS from VPC CIDR for interface endpoints"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "vpc-endpoints-sg"
  }
}

# Interface VPC Endpoints
locals {
  interface_endpoint_services = [
    "ecr.dkr",
    "ecr.api",
    "logs",
    "secretsmanager",
    "ssm",
    "kms",
    "ec2messages",
    "ssmmessages"
  ]
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${data.aws_region.current.name}.${each.key}"
  vpc_endpoint_type   = "Interface"
  private_dns_enabled = true
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]

  tags = {
    Name = "interface-${each.key}"
  }
}

# Service Discovery Private DNS Namespace
resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = local.namespace_name
  description = "Private DNS namespace for Fargate services"
  vpc         = aws_vpc.main.id
}

# ECR Repository
resource "aws_ecr_repository" "nginx" {
  name                 = "nginx-repo"
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  lifecycle {
    prevent_destroy = true
  }
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "ecs" {
  name              = "/ecs/fargate-nginx"
  retention_in_days = 7
}

# SSM Parameter for Namespace ID
resource "aws_ssm_parameter" "namespace_id" {
  name        = "/fargate/namespace-id"
  description = "Cloud Map namespace ID for service discovery"
  type        = "String"
  value       = aws_service_discovery_private_dns_namespace.main.id
}

# IAM Roles and Policies

# ECS Execution Role
resource "aws_iam_role" "ecs_execution" {
  name = "ecs-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_execution_policy" {
  name = "ecs-execution-policy"
  role = aws_iam_role.ecs_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ecr:GetAuthorizationToken",
          "ecr:BatchGetImage",
          "ecr:GetDownloadUrlForLayer"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = aws_cloudwatch_log_group.ecs.arn
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter",
          "ssm:GetParameters"
        ]
        Resource = aws_ssm_parameter.namespace_id.arn
      }
    ]
  })
}

# ECS Task Role
resource "aws_iam_role" "ecs_task" {
  name = "ecs-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "ecs_task_policy" {
  name = "ecs-task-policy"
  role = aws_iam_role.ecs_task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "servicediscovery:DiscoverInstances"
        ]
        Resource = "*"
      },
      {
        Effect = "Allow"
        Action = [
          "ssm:GetParameter"
        ]
        Resource = aws_ssm_parameter.namespace_id.arn
      }
    ]
  })
}

# Task Security Group
resource "aws_security_group" "task" {
  name        = "ecs-task-sg"
  description = "Allow HTTP from VPC CIDR for NGINX"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "ecs-task-sg"
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "main" {
  name = "fargate-cluster"
}

# ECS Task Definition
resource "aws_ecs_task_definition" "nginx" {
  family                   = "nginx-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = 512
  memory                   = 1024
  execution_role_arn       = aws_iam_role.ecs_execution.arn
  task_role_arn            = aws_iam_role.ecs_task.arn

  container_definitions = jsonencode([
    {
      name      = "nginx"
      image     = "nginx:latest"
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
      environment = [
        {
          name  = "SERVICE_DISCOVERY_NAMESPACE_ID"
          value = aws_service_discovery_private_dns_namespace.main.id
        }
      ]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.ecs.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = "nginx"
        }
      }
    }
  ])
}

# Cloud Map Service
resource "aws_service_discovery_service" "nginx" {
  name = "nginx"

  dns_config {
    namespace_id = aws_service_discovery_private_dns_namespace.main.id

    dns_records {
      ttl  = 10
      type = "A"
    }

    dns_records {
      ttl  = 10
      type = "SRV"
    }

    routing_policy = "MULTIVALUE"
  }

  health_check_custom_config {
    failure_threshold = 1
  }
}

# ECS Service
resource "aws_ecs_service" "nginx" {
  name            = "nginx-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.nginx.arn
  desired_count   = 1
  launch_type     = "FARGATE"

  network_configuration {
    subnets         = aws_subnet.private[*].id
    security_groups = [aws_security_group.task.id]
    assign_public_ip = false
  }

  service_registries {
    registry_arn   = aws_service_discovery_service.nginx.arn
    container_name = "nginx"
    container_port = 80
  }

  depends_on = [
    aws_service_discovery_service.nginx
  ]
}

# EC2 Jumphost

# IAM Role for EC2
resource "aws_iam_role" "jumphost" {
  name = "jumphost-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "jumphost" {
  name = "jumphost-instance-profile"
  role = aws_iam_role.jumphost.name
}

resource "aws_iam_role_policy_attachment" "jumphost_ssm" {
  role       = aws_iam_role.jumphost.name
  policy_arn = data.aws_iam_policy.ssm_managed_instance_core.arn
}

# Jumphost Security Group
resource "aws_security_group" "jumphost" {
  name        = "jumphost-sg"
  description = "Allow all inbound from VPC CIDR"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "jumphost-sg"
  }
}

# Network Interface for Jumphost (static private IP in first public subnet)
resource "aws_network_interface" "jumphost" {
  subnet_id       = aws_subnet.public[0].id
  private_ips     = [cidrhost(aws_subnet.public[0].cidr_block, 10)]
  security_groups = [aws_security_group.jumphost.id]

  tags = {
    Name = "jumphost-eni"
  }
}

# EC2 Instance
resource "aws_instance" "jumphost" {
  ami                  = data.aws_ami.amazon_linux_2.id
  instance_type        = "t3.micro"
  iam_instance_profile = aws_iam_instance_profile.jumphost.name

  network_interface {
    network_interface_id = aws_network_interface.jumphost.id
    device_index         = 0
  }

  metadata_options {
    http_tokens = "required"
  }

  root_block_device {
    encrypted = true
  }

  tags = {
    Name = "jumphost"
  }
}

# Output
output "curl_command" {
  description = "Command to reach the NGINX service via service discovery DNS"
  value       = "curl http://${aws_service_discovery_service.nginx.name}.${local.namespace_name}"
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project" {
  description = "Project name prefix for naming and tagging"
  type        = string
  default     = "benchmark"
}

variable "app" {
  description = "Application name prefix"
  type        = string
  default     = "benchmark"
}

variable "env" {
  description = "Environment name prefix (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "assign_elastic_ip" {
  description = "Whether to allocate and associate an Elastic IP with the instance"
  type        = bool
  default     = false
}

variable "ssh_public_key" {
  description = "Optional SSH public key material; if non-empty, a key pair is created and used"
  type        = string
  default     = ""
}

variable "attach_ssm_managed_policy" {
  description = "Whether to attach the AmazonSSMManagedInstanceCore managed policy to the IAM role"
  type        = bool
  default     = true
}

variable "custom_routes" {
  description = "List of additional routes to add to the public route table. Each object must include destination_cidr_block and either network_interface_id or gateway_id."
  type = list(object({
    destination_cidr_block = string
    network_interface_id   = optional(string)
    gateway_id             = optional(string)
  }))
  default = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-2.0.20*-x86_64-gp2"]
  }
}

locals {
  az_short    = substr(data.aws_availability_zones.available.names[0], -1, 1)
  name_prefix = "${var.project}-${var.app}-${var.env}"
  full_prefix = "${local.name_prefix}-${local.az_short}"
}

# VPC
resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

# Public Subnet
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false # handled at instance level

  tags = {
    Name = "${local.full_prefix}-subnet"
  }
}

# Route Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  dynamic "route" {
    for_each = var.custom_routes
    content {
      cidr_block           = route.value.destination_cidr_block
      network_interface_id = route.value.network_interface_id
      gateway_id           = route.value.gateway_id
    }
  }

  tags = {
    Name = "${local.full_prefix}-rtb"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# IAM Role and Instance Profile
data "aws_iam_policy_document" "assume_role" {
  statement {
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com", "ssm.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ec2_ssm_role" {
  name               = "${local.name_prefix}-ec2-ssm-role"
  assume_role_policy = data.aws_iam_policy_document.assume_role.json

  tags = {
    Name = "${local.name_prefix}-ec2-ssm-role"
  }
}

resource "aws_iam_instance_profile" "ec2_profile" {
  name = "${local.name_prefix}-ec2-profile"
  role = aws_iam_role.ec2_ssm_role.name

  tags = {
    Name = "${local.full_prefix}-instance-profile"
  }
}

# Custom SSM Policy (least privilege)
resource "aws_iam_policy" "ssm_session_manager" {
  name        = "${local.name_prefix}-ssm-session-manager"
  description = "Grants SSM Session Manager permissions for control and data channels"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = ["ssmmessages:*", "ec2messages:*", "ssm:UpdateInstanceInformation"]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ssm_session_manager" {
  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = aws_iam_policy.ssm_session_manager.arn
}

resource "aws_iam_role_policy_attachment" "amazon_ssm_managed" {
  count = var.attach_ssm_managed_policy ? 1 : 0

  role       = aws_iam_role.ec2_ssm_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

# SSH Key Pair (conditional)
resource "aws_key_pair" "this" {
  count = var.ssh_public_key != "" ? 1 : 0

  key_name   = "${local.name_prefix}-key"
  public_key = var.ssh_public_key

  tags = {
    Name = "${local.name_prefix}-key"
  }
}

# EC2 Instance
resource "aws_instance" "benchmark" {
  ami                    = data.aws_ami.amazon_linux_2.id
  instance_type          = "t3.micro"
  subnet_id              = aws_subnet.public.id
  associate_public_ip_address = true
  vpc_security_group_ids = [aws_vpc.main.default_security_group_id]
  iam_instance_profile   = aws_iam_instance_profile.ec2_profile.name
  key_name               = var.ssh_public_key != "" ? aws_key_pair.this[0].key_name : null
  user_data              = null

  # IMDSv2 enforcement
  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  # Root block device
  root_block_device {
    volume_size           = 20
    volume_type           = "gp2"
    encrypted             = true
    delete_on_termination = true
  }

  tags = {
    Name = "${local.full_prefix}-ec2"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Elastic IP (conditional)
resource "aws_eip" "this" {
  count = var.assign_elastic_ip ? 1 : 0

  domain = "vpc"

  tags = {
    Name = "${local.full_prefix}-eip"
  }
}

resource "aws_eip_association" "this" {
  count = var.assign_elastic_ip ? 1 : 0

  instance_id   = aws_instance.benchmark.id
  allocation_id = aws_eip.this[0].id
}

# Outputs
output "ec2_instance_id" {
  value = aws_instance.benchmark.id
}

output "ec2_instance_arn" {
  value = aws_instance.benchmark.arn
}

output "iam_role_arn" {
  value = aws_iam_role.ec2_ssm_role.arn
}

output "instance_profile_arn" {
  value = aws_iam_instance_profile.ec2_profile.arn
}

output "route_table_id" {
  value = aws_route_table.public.id
}

output "subnet_id" {
  value = aws_subnet.public.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    time = {
      source  = "hashicorp/time"
      version = "~> 0.11.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      "kubernetes.io/cluster/demo-eks" = "owned"
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  cluster_name              = "demo-eks"
  region                    = "us-east-1"
  eks_version               = "1.31"
  vpc_cidr                  = "10.0.0.0/16"
  azs                       = slice(data.aws_availability_zones.available.names, 0, 3)
  cfn_stack_name            = "eks-cluster-stack"
  cfn_node_group_logical_id = "NodeGroup"
  interface_endpoint_services = [
    "cloudformation",
    "sts",
    "ssm",
    "ssmmessages",
    "ec2messages",
    "ecr.api",
    "ecr.dkr",
  ]
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${local.eks_version}/amazon-linux-2/recommended/image_id"
}

###############################################################################
# Adoptions of pre-existing, hard-named resources
###############################################################################

import {
  to = aws_iam_role.eks_cluster_role
  id = "eksClusterRole"
}

import {
  to = aws_iam_role.eks_demo_node
  id = "eks-demo-node"
}

import {
  to = aws_key_pair.eks_kp
  id = "eks_kp"
}

import {
  to = aws_kms_alias.eks
  id = "alias/demo-eks"
}

import {
  to = aws_iam_instance_profile.eks_demo_node
  id = "eks-demo-node"
}

import {
  to = aws_eks_cluster.demo_eks
  id = "demo-eks"
}

###############################################################################
# Networking - VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "demo-eks-igw"
  }
}

###############################################################################
# Networking - public subnet, route table, NAT
###############################################################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, 0)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = {
    Name                     = "demo-eks-public-subnet"
    "kubernetes.io/role/elb" = "1"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.igw.id
  }

  tags = {
    Name = "demo-eks-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "demo-eks-nat-eip"
  }
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = "demo-eks-nat"
  }

  depends_on = [aws_internet_gateway.igw]
}

###############################################################################
# Networking - private subnets and per-AZ route tables
###############################################################################

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.vpc_cidr, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = {
    Name                              = "demo-eks-private-subnet-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  }
}

resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = {
    Name = "demo-eks-private-rt-${count.index + 1}"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# VPC endpoints (in-VPC reachability for nodes with VPC-only egress)
###############################################################################

resource "aws_security_group" "endpoints" {
  name        = "demo-eks-endpoints-sg"
  description = "Security group for demo-eks VPC private endpoints"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-endpoints-sg"
  }
}

resource "aws_security_group_rule" "endpoints_https_ingress" {
  type                     = "ingress"
  description              = "HTTPS from worker nodes to private endpoints"
  security_group_id        = aws_security_group.endpoints.id
  source_security_group_id = aws_security_group.eks_nodes.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${local.region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = {
    Name = "demo-eks-s3-endpoint"
  }
}

resource "aws_vpc_endpoint" "interface" {
  for_each = toset(local.interface_endpoint_services)

  vpc_id              = aws_vpc.main.id
  service_name        = "com.amazonaws.${local.region}.${each.value}"
  vpc_endpoint_type   = "Interface"
  subnet_ids          = aws_subnet.private[*].id
  security_group_ids  = [aws_security_group.endpoints.id]
  private_dns_enabled = true

  tags = {
    Name = "demo-eks-${replace(each.value, ".", "-")}-endpoint"
  }
}

###############################################################################
# KMS key for EKS secrets envelope encryption
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "Customer managed key for demo-eks secret envelope encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountAdministrationOfKey"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:Create*",
          "kms:Describe*",
          "kms:Enable*",
          "kms:List*",
          "kms:Put*",
          "kms:Update*",
          "kms:Revoke*",
          "kms:Disable*",
          "kms:Get*",
          "kms:Delete*",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEKSClusterRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.eks_cluster_role.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:RetireGrant",
          "kms:ListGrants"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "demo-eks-kms"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "eks" {
  name          = "alias/demo-eks"
  target_key_id = aws_kms_key.eks.key_id
}

###############################################################################
# IAM - EKS cluster role
###############################################################################

resource "aws_iam_role" "eks_cluster_role" {
  name = "eksClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eksClusterRole"
  }
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster_role.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "eksClusterKMSAccess"
  role = aws_iam_role.eks_cluster_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSSecretsEnvelopeEncryption"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:DescribeKey",
          "kms:CreateGrant",
          "kms:RetireGrant",
          "kms:ListGrants"
        ]
        Resource = aws_kms_key.eks.arn
      }
    ]
  })
}

###############################################################################
# EKS control plane
###############################################################################

resource "aws_eks_cluster" "demo_eks" {
  name     = local.cluster_name
  version  = local.eks_version
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  tags = {
    Name = local.cluster_name
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms,
  ]

  lifecycle {
    ignore_changes = [encryption_config]
  }
}

###############################################################################
# Node security group
###############################################################################

resource "aws_security_group" "eks_nodes" {
  name        = "demo-eks-node-sg"
  description = "Security group for demo-eks unmanaged worker nodes"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "demo-eks-node-sg"
  }
}

resource "aws_security_group_rule" "nodes_internal_ingress" {
  type              = "ingress"
  description       = "Unrestricted communication between worker nodes"
  security_group_id = aws_security_group.eks_nodes.id
  self              = true
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
}

resource "aws_security_group_rule" "nodes_vpc_egress" {
  type              = "egress"
  description       = "Outbound traffic restricted to the VPC CIDR"
  security_group_id = aws_security_group.eks_nodes.id
  cidr_blocks       = [local.vpc_cidr]
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
}

resource "aws_security_group_rule" "nodes_control_plane_https_ingress" {
  type                     = "ingress"
  description              = "Control plane to node HTTPS communication"
  security_group_id        = aws_security_group.eks_nodes.id
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
}

resource "aws_security_group_rule" "nodes_control_plane_kubelet_ingress" {
  type                     = "ingress"
  description              = "Control plane to node kubelet communication"
  security_group_id        = aws_security_group.eks_nodes.id
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
}

resource "aws_security_group_rule" "nodes_control_plane_https_egress" {
  type                     = "egress"
  description              = "Node to control plane HTTPS communication"
  security_group_id        = aws_security_group.eks_nodes.id
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
}

resource "aws_security_group_rule" "nodes_control_plane_kubelet_egress" {
  type                     = "egress"
  description              = "Node to control plane kubelet communication"
  security_group_id        = aws_security_group.eks_nodes.id
  source_security_group_id = aws_eks_cluster.demo_eks.vpc_config[0].cluster_security_group_id
  from_port                = 1025
  to_port                  = 65535
  protocol                 = "tcp"
}

resource "aws_security_group_rule" "nodes_endpoints_https_egress" {
  type                     = "egress"
  description              = "Node to VPC private endpoints HTTPS communication"
  security_group_id        = aws_security_group.eks_nodes.id
  source_security_group_id = aws_security_group.endpoints.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
}

###############################################################################
# IAM - node instance role and instance profile
###############################################################################

resource "aws_iam_role" "eks_demo_node" {
  name = "eks-demo-node"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "eks-demo-node"
  }
}

resource "aws_iam_role_policy_attachment" "node_worker_node_policy" {
  role       = aws_iam_role.eks_demo_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "node_cni_policy" {
  role       = aws_iam_role.eks_demo_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "node_ecr_read_only" {
  role       = aws_iam_role.eks_demo_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "node_ssm_core" {
  role       = aws_iam_role.eks_demo_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_role_policy" "node_cfn_signal" {
  name = "eksDemoNodeSignalResource"
  role = aws_iam_role.eks_demo_node.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowCloudFormationSignalResource"
        Effect   = "Allow"
        Action   = "cloudformation:SignalResource"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eks_demo_node" {
  name = "eks-demo-node"
  role = aws_iam_role.eks_demo_node.name

  tags = {
    Name = "eks-demo-node"
  }
}

###############################################################################
# SSH key material for the nodes
###############################################################################

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

# Ensure the destination directory exists, is writable, and any stale key file
# left behind by a previous run is removed before local_file writes to it.
resource "terraform_data" "ssh_key_prep" {
  provisioner "local-exec" {
    command = "mkdir -p \"$HOME/.ssh\" && chmod 700 \"$HOME/.ssh\" && rm -f \"$HOME/.ssh/eks-aws.pem\""
  }
}

resource "local_file" "eks_pem" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"

  depends_on = [terraform_data.ssh_key_prep]
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  lifecycle {
    ignore_changes = [public_key]
  }
}

###############################################################################
# Launch template for the worker nodes
###############################################################################

resource "aws_launch_template" "eks_nodes" {
  name_prefix   = "demo-eks-node-lt-"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  vpc_security_group_ids = [aws_security_group.eks_nodes.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_demo_node.name
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 30
      volume_type = "gp2"
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh ${aws_eks_cluster.demo_eks.name} \
      --region ${local.region} \
      --dns-cluster-ip 172.20.0.10 \
      --kubelet-extra-args '--node-labels=role=worker --register-with-taints='
    /opt/aws/bin/cfn-signal -e $? --stack ${local.cfn_stack_name} --resource ${local.cfn_node_group_logical_id} --region ${local.region}
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "demo-eks-node"
    }
  }

  tag_specifications {
    resource_type = "volume"

    tags = {
      Name = "demo-eks-node-volume"
    }
  }

  tags = {
    Name = "demo-eks-node-lt"
  }
}

resource "time_sleep" "launch_template_settle" {
  create_duration = "30s"

  depends_on = [
    aws_launch_template.eks_nodes,
    aws_key_pair.eks_kp,
  ]
}

###############################################################################
# CloudFormation managed Auto Scaling Group for the worker nodes
###############################################################################

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name = local.cfn_stack_name

  template_body = <<-EOT
  {
    "AWSTemplateFormatVersion": "2010-09-09",
    "Description": "Unmanaged demo-eks worker nodes managed by an Auto Scaling Group",
    "Parameters": {
      "ClusterName": { "Type": "String" },
      "NodeInstanceRole": { "Type": "String" },
      "NodeSecurityGroup": { "Type": "String" },
      "Subnet1": { "Type": "String" },
      "Subnet2": { "Type": "String" },
      "Subnet3": { "Type": "String" },
      "LaunchTemplateId": { "Type": "String" },
      "LaunchTemplateVersion": { "Type": "String" },
      "KeyName": { "Type": "String" },
      "MinSize": { "Type": "String", "Default": "1" },
      "DesiredCapacity": { "Type": "String", "Default": "3" },
      "MaxSize": { "Type": "String", "Default": "4" }
    },
    "Resources": {
      "NodeGroup": {
        "Type": "AWS::AutoScaling::AutoScalingGroup",
        "Properties": {
          "AutoScalingGroupName": "demo-eks-node-asg",
          "MinSize": { "Ref": "MinSize" },
          "MaxSize": { "Ref": "MaxSize" },
          "DesiredCapacity": { "Ref": "DesiredCapacity" },
          "VPCZoneIdentifier": [
            { "Ref": "Subnet1" },
            { "Ref": "Subnet2" },
            { "Ref": "Subnet3" }
          ],
          "LaunchTemplate": {
            "LaunchTemplateId": { "Ref": "LaunchTemplateId" },
            "Version": { "Ref": "LaunchTemplateVersion" }
          },
          "Tags": [
            { "Key": "Name", "Value": "demo-eks-node", "PropagateAtLaunch": true },
            { "Key": "kubernetes.io/cluster/demo-eks", "Value": "owned", "PropagateAtLaunch": true }
          ]
        },
        "CreationPolicy": {
          "ResourceSignal": {
            "Count": 3,
            "Timeout": "PT10M"
          }
        },
        "UpdatePolicy": {
          "AutoScalingRollingUpdate": {
            "MaxBatchSize": 1,
            "MinInstancesInService": 3,
            "PauseTime": "PT5M",
            "WaitOnResourceSignals": true
          }
        }
      }
    },
    "Outputs": {
      "NodeInstanceRoleArn": { "Value": { "Ref": "NodeInstanceRole" } },
      "NodeSecurityGroupId": { "Value": { "Ref": "NodeSecurityGroup" } },
      "AutoScalingGroupId": { "Value": { "Ref": "NodeGroup" } }
    }
  }
  EOT

  parameters = {
    ClusterName           = aws_eks_cluster.demo_eks.name
    NodeInstanceRole      = aws_iam_role.eks_demo_node.arn
    NodeSecurityGroup     = aws_security_group.eks_nodes.id
    Subnet1               = aws_subnet.private[0].id
    Subnet2               = aws_subnet.private[1].id
    Subnet3               = aws_subnet.private[2].id
    LaunchTemplateId      = aws_launch_template.eks_nodes.id
    LaunchTemplateVersion = tostring(aws_launch_template.eks_nodes.latest_version)
    KeyName               = aws_key_pair.eks_kp.key_name
    MinSize               = "1"
    DesiredCapacity       = "3"
    MaxSize               = "4"
  }

  timeout_in_minutes = 15
  on_failure         = "ROLLBACK"

  depends_on = [time_sleep.launch_template_settle]
}

###############################################################################
# Outputs
###############################################################################

output "node_instance_role_arn" {
  description = "ARN of the IAM role attached to the worker nodes"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeInstanceRoleArn"]
}

output "node_security_group_id" {
  description = "ID of the security group attached to the worker nodes"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeSecurityGroupId"]
}

output "autoscaling_group_id" {
  description = "ID of the Auto Scaling Group created by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["AutoScalingGroupId"]
}

# Account ID for naming
data "aws_caller_identity" "current" {}

# Terraform and provider configurations
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = ">= 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "us-west-1"
  region = "us-west-1"
}

# Local values
locals {
  account_id          = data.aws_caller_identity.current.account_id
  primary_bucket_name = "terraform-state-${local.account_id}"
  replica_bucket_name = "terraform-state-replica-${local.account_id}"
}

# Variables
variable "stacks" {
  description = "Map of stack configurations"
  type = map(object({
    name   = string
    region = string
  }))
  default = {}
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default = {
    StateManagement = "true"
    Tool            = "Terraform"
  }
}

# ------------------------------------------------------------------------------
# PRIMARY REGION (us-east-1) resources
# ------------------------------------------------------------------------------

# Primary S3 bucket
resource "aws_s3_bucket" "primary" {
  bucket = local.primary_bucket_name
  tags   = var.tags
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "primary" {
  bucket = aws_s3_bucket.primary.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

# Primary KMS key
resource "aws_kms_key" "primary" {
  description             = "Primary KMS key for S3 state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ReplicationRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/terraform-state-primary"
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# REPLICA REGION (us-west-1) resources
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "replica" {
  provider = aws.us-west-1
  bucket   = local.replica_bucket_name
  tags     = var.tags
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyNonSSLRequests"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_kms_key" "replica" {
  provider                = aws.us-west-1
  description             = "Replica KMS key for S3 state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ReplicationRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.replication.arn
        }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })
  tags = var.tags
}

resource "aws_kms_alias" "replica" {
  provider      = aws.us-west-1
  name          = "alias/terraform-state-replica"
  target_key_id = aws_kms_key.replica.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.us-west-1
  bucket   = aws_s3_bucket.replica.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# REPLICATION IAM ROLE AND POLICY
# ------------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name = "terraform-state-replication-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3Service"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "AWS:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_policy" "replication" {
  name        = "terraform-state-replication-policy"
  description = "Permissions for S3 cross-region replication"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketRead"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/*"
        ]
      },
      {
        Sid    = "SourceKeyDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt"
        ]
        Resource = [aws_kms_key.primary.arn]
      },
      {
        Sid    = "DestinationBucketWrite"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.replica.arn,
          "${aws_s3_bucket.replica.arn}/*"
        ]
      },
      {
        Sid    = "DestinationKeyEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [aws_kms_key.replica.arn]
      }
    ]
  })
  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

# ------------------------------------------------------------------------------
# REPLICATION CONFIGURATION ON PRIMARY BUCKET
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "replication" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  depends_on = [
    aws_iam_role_policy_attachment.replication
  ]

  rule {
    id     = "CrossRegionReplication"
    status = "Enabled"

    delete_marker_replication {
      status = "Enabled"
    }

    filter {}

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }
}

# ------------------------------------------------------------------------------
# DYNAMIC RESOURCES PER STACK
# ------------------------------------------------------------------------------

# DynamoDB tables for state locking
resource "aws_dynamodb_table" "stack" {
  for_each = var.stacks

  name         = "terraform-locks-${each.value.name}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = merge(var.tags, {
    StackName = each.value.name
  })

  lifecycle {
    prevent_destroy = true
  }
}

# IAM policies per stack
resource "aws_iam_policy" "stack" {
  for_each = var.stacks

  name        = "terraform-state-${each.value.name}"
  description = "Permissions for stack ${each.value.name} to manage its state"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "DynamoDBLock"
        Effect = "Allow"
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:DeleteItem"
        ]
        Resource = aws_dynamodb_table.stack[each.key].arn
      },
      {
        Sid    = "S3StateAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          "${aws_s3_bucket.primary.arn}/${each.value.name}/*"
        ]
      },
      {
        Sid    = "KMSEncryptDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt",
          "kms:GenerateDataKey"
        ]
        Resource = [
          aws_kms_key.primary.arn,
          aws_kms_key.replica.arn
        ]
      }
    ]
  })

  tags = merge(var.tags, {
    StackName = each.value.name
  })
}

# Generate backend.tf files per stack
resource "local_file" "backend_tf" {
  for_each = var.stacks

  filename = "eks-stacks/${each.value.name}/backend.tf"
  content  = <<-EOT
    backend "s3" {
      bucket         = "${aws_s3_bucket.primary.bucket}"
      key            = "${each.value.name}/terraform.tfstate"
      region         = "${each.value.region}"
      dynamodb_table = "${aws_dynamodb_table.stack[each.key].name}"
      encrypt        = true
      kms_key_id     = "${aws_kms_key.primary.arn}"
    }
  EOT
}

# ------------------------------------------------------------------------------
# OUTPUT
# ------------------------------------------------------------------------------

output "backend_tf_files" {
  description = "Paths to generated backend.tf files"
  value       = [for f in local_file.backend_tf : f.filename]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (user-controllable, non-infrastructure inputs only)
###############################################################################

variable "environment" {
  description = "Deployment environment used for tagging (for example: dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags to apply to all taggable Cognito resources created by this configuration."
  type        = map(string)
  default     = {}
}

variable "callback_urls" {
  description = "Allowed callback (redirect) URLs for the app client. HTTPS is required by Cognito except for localhost development URLs."
  type        = list(string)
  default     = ["https://example.com/callback"]
}

variable "logout_urls" {
  description = "Allowed sign-out URLs for the app client."
  type        = list(string)
  default     = ["https://example.com/logout"]
}

###############################################################################
# Locals
###############################################################################

locals {
  user_pool_name  = "box_things"
  app_client_name = "box_things_client"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags,
  )

  # Only the user pool resource supports tags in the AWS provider 5.x; the
  # app client resource does not expose a `tags`/`tags_all` argument.
  user_pool_tags = merge(local.common_tags, { Name = local.user_pool_name })
}

###############################################################################
# Amazon Cognito user pool
###############################################################################

resource "aws_cognito_user_pool" "box_things" {
  name = local.user_pool_name

  # Users sign in with their email address as an alias rather than as an
  # immutable username.
  alias_attributes = ["email"]

  # Email is automatically verified through a confirmation link.
  auto_verified_attributes = ["email"]

  # NOTE: MFA is intentionally disabled for this user pool as explicitly
  # requested. Revisit this before any production hardening effort.
  mfa_configuration = "OFF"

  # NOTE: `username_configuration { case_sensitive = false }` is intentionally
  # not declared here: Amazon Cognito rejects case-insensitive usernames for
  # user pools that use `email` (or `phone_number`) as an alias attribute, and
  # an email alias is required so users can sign in with their email address.

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
  }

  # Email is mandatory and editable at sign-up / profile update time.
  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 5
      max_length = 254
    }
  }

  password_policy {
    minimum_length                   = 8
    require_lowercase                = true
    require_uppercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  # Self sign-up is permitted; users are not limited to admin-created accounts.
  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  # Users can self-recover their account through the verified email alias.
  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  # Protect stateful, user-bearing Cognito data from accidental destruction.
  deletion_protection = "ACTIVE"

  tags = local.user_pool_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Amazon Cognito app client
###############################################################################

resource "aws_cognito_user_pool_client" "box_things_client" {
  name         = local.app_client_name
  user_pool_id = aws_cognito_user_pool.box_things.id

  # Public/browser-style client: user-password, SRP and refresh-token flows
  # cannot safely hold a client secret.
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }

  callback_urls = var.callback_urls
  logout_urls   = var.logout_urls

  supported_identity_providers = ["COGNITO"]

  # Do not disclose whether a given username already exists.
  prevent_user_existence_errors = "ENABLED"

  enable_token_revocation = true

  # NOTE: Cognito app clients are not taggable in AWS provider 5.x, so no
  # `tags` argument is declared here.
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables
###############################################################################

variable "users" {
  description = "Map of IAM user names to their metadata. Key is the IAM user name, value holds the Owner tag. This map is the single source of truth for user names, Owner tags and group membership."
  type = map(object({
    owner = string
  }))
  default = {
    dev1  = { owner = "Devel" }
    dev2  = { owner = "Devel" }
    guest = { owner = "Guest" }
  }
}

variable "devel_group_name" {
  description = "Name of the IAM group that grants developer (ReadOnlyAccess) permissions."
  type        = string
  default     = "Ersia_Devel_Group"
}

variable "guest_group_name" {
  description = "Name of the IAM group that grants guest (IAMReadOnlyAccess) permissions."
  type        = string
  default     = "Ersia_Guest_Group"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    ManagedBy = "Terraform"
    Project   = "Ersia"
  }

  # Owner tag value that maps a user to the developer group.
  devel_owner_tag = "Devel"
}

###############################################################################
# AWS-managed policy lookups (no hardcoded ARNs or account IDs)
###############################################################################

data "aws_iam_policy" "read_only_access" {
  name = "ReadOnlyAccess"
}

data "aws_iam_policy" "iam_read_only_access" {
  name = "IAMReadOnlyAccess"
}

###############################################################################
# IAM groups
# Note: aws_iam_group does not support a `tags` argument in this provider
# version, so group ownership/purpose is conveyed via outputs instead.
###############################################################################

resource "aws_iam_group" "devel_group" {
  name = var.devel_group_name
  path = "/"
}

resource "aws_iam_group" "guest_group" {
  name = var.guest_group_name
  path = "/"
}

###############################################################################
# IAM users (single source of truth: var.users)
###############################################################################

resource "aws_iam_user" "users" {
  for_each = var.users

  name = each.key
  path = "/"

  tags = merge(local.common_tags, {
    Owner = each.value.owner
  })
}

###############################################################################
# Managed policy attachments (least privilege, scoped AWS-managed policies)
###############################################################################

resource "aws_iam_group_policy_attachment" "devel_read_only_access" {
  group      = aws_iam_group.devel_group.name
  policy_arn = data.aws_iam_policy.read_only_access.arn
}

resource "aws_iam_group_policy_attachment" "guest_iam_read_only_access" {
  group      = aws_iam_group.guest_group.name
  policy_arn = data.aws_iam_policy.iam_read_only_access.arn
}

###############################################################################
# Group membership derived from the Owner tag
###############################################################################

resource "aws_iam_user_group_membership" "membership" {
  for_each = var.users

  user = aws_iam_user.users[each.key].name

  groups = [
    each.value.owner == local.devel_owner_tag ? aws_iam_group.devel_group.name : aws_iam_group.guest_group.name
  ]
}

###############################################################################
# Outputs
###############################################################################

output "devel_group_name" {
  description = "Name of the developer IAM group (Ersia_Devel_Group)."
  value       = aws_iam_group.devel_group.name
}

output "guest_group_name" {
  description = "Name of the guest IAM group (Ersia_Guest_Group)."
  value       = aws_iam_group.guest_group.name
}

output "iam_user_names" {
  description = "Names of all IAM users created from var.users."
  value       = keys(var.users)
}

output "iam_user_arns" {
  description = "Map of IAM user name to ARN."
  value       = { for name, user in aws_iam_user.users : name => user.arn }
}

output "iam_user_group_memberships" {
  description = "Map of IAM user name to the groups it belongs to."
  value       = { for name, membership in aws_iam_user_group_membership.membership : name => membership.groups }
}

output "devel_group_policy_arn" {
  description = "ARN of the AWS-managed policy attached to the developer group."
  value       = data.aws_iam_policy.read_only_access.arn
}

output "guest_group_policy_arn" {
  description = "ARN of the AWS-managed policy attached to the guest group."
  value       = data.aws_iam_policy.iam_read_only_access.arn
}

terraform {
  required_version = ">= 1.3"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

resource "random_pet" "pet" {
  length = 2
}

data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  sqs_send_message_uri = "arn:${data.aws_partition.current.partition}:apigateway:${data.aws_region.current.region}:sqs:action/SendMessage"
}

resource "aws_kms_key" "my_key" {
  description             = "KMS key for SQS queue encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "my_key" {
  name          = "alias/websocket-sqs-key-${random_pet.pet.id}"
  target_key_id = aws_kms_key.my_key.id
}

resource "aws_sqs_queue" "messages" {
  name                              = "${random_pet.pet.id}-messages"
  kms_master_key_id                 = aws_kms_key.my_key.id
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "api" {
  name              = "/aws/apigateway/${random_pet.pet.id}-websocket"
  retention_in_days = 1
}

resource "aws_iam_role" "api_gateway_role" {
  name_prefix = "api-gateway-sqs-exec-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action    = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "sqs_send_message" {
  name_prefix = "sqs-send-message-policy-"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SQSSendMessage"
        Effect   = "Allow"
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.messages.arn
      },
      {
        Sid      = "KMSQueueEncryption"
        Effect   = "Allow"
        Action   = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.my_key.arn
      },
      {
        Sid      = "APIGatewayCloudWatchLogs"
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.api.arn,
          "${aws_cloudwatch_log_group.api.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "api_gateway" {
  role       = aws_iam_role.api_gateway_role.name
  policy_arn = aws_iam_policy.sqs_send_message.arn
}

resource "aws_apigatewayv2_api" "api" {
  name          = "${random_pet.pet.id}-websocket-api"
  protocol_type = "WEBSOCKET"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.api.id
  integration_type = "MOCK"
  integration_uri  = local.sqs_send_message_uri

  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.api.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration" "default" {
  api_id             = aws_apigatewayv2_api.api.id
  integration_type   = "AWS"
  integration_uri    = local.sqs_send_message_uri
  integration_method = "POST"
  credentials_arn    = aws_iam_role.api_gateway_role.arn

  request_parameters = {
    "integration.request.querystring.MessageBody" = "route.request.body"
    "integration.request.querystring.QueueUrl"    = "'${aws_sqs_queue.messages.url}'"
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id                             = aws_apigatewayv2_api.api.id
  route_key                          = "$default"
  target                             = "integrations/${aws_apigatewayv2_integration.default.id}"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.api.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id             = aws_apigatewayv2_api.api.id
  integration_type   = "AWS"
  integration_uri    = local.sqs_send_message_uri
  integration_method = "POST"
  credentials_arn    = aws_iam_role.api_gateway_role.arn

  request_parameters = {
    "integration.request.querystring.MessageBody" = "'Client disconnected'"
    "integration.request.querystring.QueueUrl"    = "'${aws_sqs_queue.messages.url}'"
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.api.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_deployment" "api" {
  api_id      = aws_apigatewayv2_api.api.id
  description = "WebSocket API deployment"

  triggers = {
    redeployment = sha1(jsonencode([
      aws_apigatewayv2_route.connect.id,
      aws_apigatewayv2_route.default.id,
      aws_apigatewayv2_route.disconnect.id,
      aws_apigatewayv2_integration.connect.id,
      aws_apigatewayv2_integration.default.id,
      aws_apigatewayv2_integration.disconnect.id,
      aws_apigatewayv2_route_response.default.id,
    ]))
  }

  depends_on = [
    aws_apigatewayv2_route.connect,
    aws_apigatewayv2_route.default,
    aws_apigatewayv2_route.disconnect,
    aws_apigatewayv2_integration.connect,
    aws_apigatewayv2_integration.default,
    aws_apigatewayv2_integration.disconnect,
    aws_apigatewayv2_route_response.default,
  ]

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_apigatewayv2_stage" "api" {
  api_id        = aws_apigatewayv2_api.api.id
  name          = "dev"
  auto_deploy   = true
  deployment_id = aws_apigatewayv2_deployment.api.id

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      sourceIp       = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      routeKey       = "$context.routeKey"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
      errorMessage   = "$context.errorMessage"
    })
  }
}

output "websocket_endpoint" {
  value = "wss://${aws_apigatewayv2_api.api.id}.execute-api.${data.aws_region.current.region}.amazonaws.com/dev"
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Variables for VPC "XXXX-vpc-test"
variable "vpc_test_cidr" {
  default = "10.0.0.0/16"
}

variable "vpc_test_name" {
  default = "XXXX-vpc-test"
}

variable "vpc_test_dns_hostnames" {
  default = false
}

variable "vpc_test_tags" {
  default = {
    Name = "XXXX-vpc-test"
  }
}

# Variables for VPC "Default"
variable "vpc_default_cidr" {
  default = "172.31.0.0/16"
}

variable "vpc_default_name" {
  default = "Default"
}

variable "vpc_default_dns_hostnames" {
  default = true
}

variable "vpc_default_tags" {
  default = {
    Name = "Default"
  }
}

# Variables for VPC "eksctl-eks-cluster-px-cluster/VPC"
variable "vpc_eksctl_cidr" {
  default = "192.168.0.0/16"
}

variable "vpc_eksctl_name" {
  default = "eksctl-eks-cluster-px-cluster/VPC"
}

variable "vpc_eksctl_dns_hostnames" {
  default = true
}

variable "vpc_eksctl_tags" {
  default = {
    Name                                      = "eksctl-eks-cluster-px-cluster/VPC"
    "eksctl.cluster.k8s.io/v1alpha1/cluster-name"    = "eks-cluster-px"
    "eksctl.cluster.k8s.io/v1alpha1/cluster-version" = "0.94.0"
  }
}

# Variables for untagged VPC
variable "vpc_untagged_cidr" {
  default = "10.0.0.0/24"
}

variable "vpc_untagged_tags" {
  default = {}
}

# Variables for VPC with empty Name tag
variable "vpc_empty_name_cidr" {
  default = "10.0.0.0/16"
}

variable "vpc_empty_name_tags" {
  default = {
    Name = ""
  }
}

# Common variable for instance tenancy (default)
variable "instance_tenancy" {
  default = "default"
}

# Common variable for DNS support (always true)
variable "enable_dns_support" {
  default = true
}

# VPC resources
resource "aws_vpc" "vpc_test" {
  cidr_block           = var.vpc_test_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.vpc_test_dns_hostnames
  instance_tenancy     = var.instance_tenancy
  tags                 = var.vpc_test_tags
}

resource "aws_vpc" "vpc_default" {
  cidr_block           = var.vpc_default_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.vpc_default_dns_hostnames
  instance_tenancy     = var.instance_tenancy
  tags                 = var.vpc_default_tags
}

resource "aws_vpc" "vpc_eksctl" {
  cidr_block           = var.vpc_eksctl_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.vpc_eksctl_dns_hostnames
  instance_tenancy     = var.instance_tenancy
  tags                 = var.vpc_eksctl_tags
}

resource "aws_vpc" "vpc_untagged" {
  cidr_block           = var.vpc_untagged_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = false
  instance_tenancy     = var.instance_tenancy
  tags                 = var.vpc_untagged_tags
}

resource "aws_vpc" "vpc_empty_name" {
  cidr_block           = var.vpc_empty_name_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = false
  instance_tenancy     = var.instance_tenancy
  tags                 = var.vpc_empty_name_tags
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Additional tags to apply to the created IAM roles and customer managed policy."
  type        = map(string)
  default     = {}
}

data "aws_default_tags" "current" {}

locals {
  provider_default_tags = data.aws_default_tags.current.tags

  tags = {
    for key, value in var.tags : key => value
    if lookup(local.provider_default_tags, key, null) != value
  }
}

# ---------------------------------------------------------------------------
# ECS service role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_assume_role" {
  statement {
    sid     = "EcsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_role" {
  name                  = "ecs-role"
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.ecs_assume_role.json
  tags                  = local.tags
}

resource "aws_iam_role_policy_attachment" "ecs_role_amazon_ec2_container_service_role" {
  role       = aws_iam_role.ecs_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2ContainerServiceRole"
}

# ---------------------------------------------------------------------------
# ECS task execution role
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "ecs_tasks_assume_role" {
  statement {
    sid     = "EcsTasksAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_tasks_role" {
  name                  = "ecs-tasks-role"
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.ecs_tasks_assume_role.json
  tags                  = local.tags
}

resource "aws_iam_role_policy_attachment" "ecs_tasks_role_amazon_ecs_task_execution_role_policy" {
  role       = aws_iam_role.ecs_tasks_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ---------------------------------------------------------------------------
# EventBridge role and its customer managed policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "events_assume_role" {
  statement {
    sid     = "EventsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["events.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "events_role" {
  name                  = "events-role"
  path                  = "/"
  force_detach_policies = true
  assume_role_policy    = data.aws_iam_policy_document.events_assume_role.json
  tags                  = local.tags
}

data "aws_iam_policy_document" "ecs_policy" {
  statement {
    sid    = "RunEcsTasks"
    effect = "Allow"
    actions = [
      "ecs:RunTask",
      "ecs:DescribeTasks",
      "ecs:StopTask",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "PassEcsTaskExecutionRoleOnly"
    effect    = "Allow"
    actions   = ["iam:PassRole"]
    resources = [aws_iam_role.ecs_tasks_role.arn]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["ecs-tasks.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "ecs_policy" {
  name   = "ecs-policy"
  path   = "/"
  policy = data.aws_iam_policy_document.ecs_policy.json
  tags   = local.tags
}

resource "aws_iam_role_policy_attachment" "events_role_ecs_policy" {
  role       = aws_iam_role.events_role.name
  policy_arn = aws_iam_policy.ecs_policy.arn
}

resource "aws_iam_role_policy_attachment" "events_role_cloudwatch_logs_full_access" {
  role       = aws_iam_role.events_role.name
  policy_arn = "arn:aws:iam::aws:policy/CloudWatchLogsFullAccess"
}

# Terraform and Provider Configuration
terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "secondary"
  region = var.secondary_region
}

# Variables
variable "primary_bucket_name" {
  description = "Name for the primary S3 bucket (without account ID suffix)"
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Name for the secondary S3 bucket (without account ID suffix)"
  type        = string
  default     = "example2"
}

variable "secondary_region" {
  description = "AWS region for the secondary bucket and Multi-Region Access Point"
  type        = string
  default     = "us-west-2"
}

variable "mrap_name" {
  description = "Name for the Multi-Region Access Point"
  type        = string
  default     = "example-mrap"
}

# Data sources for static provider metadata
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

# Random suffix for unique resource names
resource "random_id" "suffix" {
  byte_length = 4
}

# Local values for account ID and bucket names
locals {
  account_id = data.aws_caller_identity.current.account_id
}

# ------------------------------------------------------------------------------
# KMS Keys (one per region)
# ------------------------------------------------------------------------------

# Primary KMS key (us-east-1, default provider)
resource "aws_kms_key" "primary" {
  description             = "Primary S3 bucket encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = "alias/primary-s3-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.primary.key_id
}

# Secondary KMS key (secondary region, using alias provider)
resource "aws_kms_key" "secondary" {
  provider = aws.secondary

  description             = "Secondary S3 bucket encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "secondary" {
  provider = aws.secondary

  name          = "alias/secondary-s3-key-${random_id.suffix.hex}"
  target_key_id = aws_kms_key.secondary.key_id
}

# ------------------------------------------------------------------------------
# Primary S3 Bucket (us-east-1)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "primary" {
  bucket = "${var.primary_bucket_name}-${local.account_id}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "primary" {
  bucket = aws_s3_bucket.primary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_public_access_block" "primary" {
  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# Secondary S3 Bucket (secondary region)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket" "secondary" {
  provider = aws.secondary

  bucket = "${var.secondary_bucket_name}-${local.account_id}-${random_id.suffix.hex}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id
  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider = aws.secondary

  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.secondary

  bucket = aws_s3_bucket.secondary.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ------------------------------------------------------------------------------
# Replication IAM Role and Policy (us-east-1)
# ------------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  name_prefix = "s3-replication-role-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "replication" {
  name = "s3-replication-policy"
  role = aws_iam_role.replication.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ReadReplicationConfig"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.primary.arn,
          aws_s3_bucket.secondary.arn
        ]
      },
      {
        Sid    = "ReadReplicateSource"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = "${aws_s3_bucket.primary.arn}/*"
      },
      {
        Sid    = "ReplicateDest"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = "${aws_s3_bucket.secondary.arn}/*"
      },
      {
        Sid    = "KMSDecryptSource"
        Effect = "Allow"
        Action = "kms:Decrypt"
        Resource = aws_kms_key.primary.arn
      },
      {
        Sid    = "KMSEncryptDest"
        Effect = "Allow"
        Action = "kms:Encrypt"
        Resource = aws_kms_key.secondary.arn
      }
    ]
  })
}

# ------------------------------------------------------------------------------
# S3 Replication Configuration (on primary bucket)
# ------------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "primary" {
  bucket = aws_s3_bucket.primary.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replication-rule"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ------------------------------------------------------------------------------
# Multi-Region Access Point (secondary region)
# ------------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point" "mrap" {
  provider = aws.secondary

  details {
    name = "${var.mrap_name}-${random_id.suffix.hex}"

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }

  lifecycle {
    prevent_destroy = true
  }

  timeouts {
    create = "25m"
    delete = "30m"
  }
}

# ------------------------------------------------------------------------------
# Multi-Region Access Point Policy (secondary region)
# ------------------------------------------------------------------------------

resource "aws_s3control_multi_region_access_point_policy" "mrap" {
  provider = aws.secondary

  account_id = local.account_id
  depends_on = [aws_s3control_multi_region_access_point.mrap]

  details {
    name = aws_s3control_multi_region_access_point.mrap.name

    policy = jsonencode({
      Version = "2012-10-17"
      Statement = [
        {
          Effect = "Allow"
          Principal = {
            AWS = data.aws_caller_identity.current.account_id
          }
          Action = [
            "s3:GetObject",
            "s3:PutObject"
          ]
          Resource = "arn:${data.aws_partition.current.partition}:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.mrap.alias}/object/*"
        }
      ]
    })
  }

  timeouts {
    create = "5m"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "namespace" {
  type        = string
  default     = null
  description = "Cloud Posse namespace (e.g. company abbreviation)."
}

variable "tenant" {
  type        = string
  default     = null
  description = "Cloud Posse tenant (e.g. business unit)."
}

variable "environment" {
  type        = string
  default     = null
  description = "Cloud Posse environment (e.g. ue1, uw2)."
}

variable "stage" {
  type        = string
  default     = null
  description = "Cloud Posse stage (e.g. dev, prod)."
}

variable "name" {
  type        = string
  default     = "ssm-patching"
  description = "Cloud Posse name used as the base identifier for all resources."
}

variable "attributes" {
  type        = list(string)
  default     = []
  description = "Additional Cloud Posse attributes appended to the generated identifier."
}

variable "delimiter" {
  type        = string
  default     = "-"
  description = "Delimiter used between Cloud Posse ID elements."
}

variable "tags" {
  type        = map(string)
  default     = {}
  description = "Additional tags applied to every taggable resource."
}

variable "scan_schedule" {
  type        = string
  default     = "cron(0 0 18 ? * WED *)"
  description = "Schedule (cron or rate) for the weekly patch scan maintenance window."
}

variable "install_schedule" {
  type        = string
  default     = "cron(0 0 21 ? * WED *)"
  description = "Schedule (cron or rate) for the weekly patch install maintenance window."
}

variable "maintenance_window_duration" {
  type        = number
  default     = 3
  description = "Duration of each maintenance window in hours."
}

variable "maintenance_window_cutoff" {
  type        = number
  default     = 1
  description = "Number of hours before the end of the maintenance window that no new tasks are started."
}

variable "max_concurrency" {
  type        = string
  default     = "20"
  description = "Maximum number of instances targeted in parallel (fixed number or percentage)."
}

variable "max_errors" {
  type        = string
  default     = "50"
  description = "Maximum number of errors tolerated before the task stops executing (fixed number or percentage)."
}

variable "task_timeout_seconds" {
  type        = number
  default     = 3600
  description = "Timeout in seconds for the Run Command patch tasks."
}

variable "scan_reboot_option" {
  type        = string
  default     = "NoReboot"
  description = "Reboot behavior for the scan task (NoReboot)."
}

variable "install_reboot_option" {
  type        = string
  default     = "RebootIfNeeded"
  description = "Reboot behavior for the install task (RebootIfNeeded or NoReboot)."
}

variable "scan_targets" {
  description = "Tag filters used to select the instances to scan. Defaults to the Patch Group tag value TOSCAN."
  type = list(object({
    key    = string
    values = list(string)
  }))
  default = [
    {
      key    = "tag:Patch Group"
      values = ["TOSCAN"]
    }
  ]
}

variable "install_targets" {
  description = "Tag filters used to select the instances to patch. Defaults to the Patch Group tag value TOPATCH."
  type = list(object({
    key    = string
    values = list(string)
  }))
  default = [
    {
      key    = "tag:Patch Group"
      values = ["TOPATCH"]
    }
  ]
}

variable "scan_patch_group" {
  type        = string
  default     = "TOSCAN"
  description = "Patch Group registered against the patch baseline for the scan window."
}

variable "install_patch_group" {
  type        = string
  default     = "TOPATCH"
  description = "Patch Group registered against the patch baseline for the install window."
}

variable "output_s3_key_prefix" {
  type        = string
  default     = "scanning"
  description = "S3 key prefix inside the log bucket where Run Command output is written."
}

variable "enable_sns_notifications" {
  type        = bool
  default     = false
  description = "When true, an SNS topic is created and maintenance window tasks publish command notifications to it."
}

variable "enable_cloudwatch_logs" {
  type        = bool
  default     = false
  description = "When true, a CloudWatch log group is created and Run Command output is streamed to it."
}

variable "cloudwatch_log_retention_in_days" {
  type        = number
  default     = 30
  description = "Retention (in days) applied to the optional CloudWatch log group."
}

variable "kms_deletion_window_in_days" {
  type        = number
  default     = 7
  description = "Waiting period (in days) before the customer managed KMS key is deleted."
}

variable "patch_baseline_operating_system" {
  type        = string
  default     = "AMAZON_LINUX_2"
  description = "Operating system the patch baseline applies to."
}

variable "approved_patches_compliance_level" {
  type        = string
  default     = "HIGH"
  description = "Compliance level assigned to patches approved by the patch baseline."
}

variable "auto_approval_delay_days" {
  type        = number
  default     = 7
  description = "Auto-approval delay (in days) after a patch is released before it is approved for deployment. Exposed by the AWS provider as approve_after_days."
}

variable "enable_non_security" {
  type        = bool
  default     = true
  description = "Whether non-security patches are approved by the default approval rule."
}

variable "patch_classifications" {
  type        = list(string)
  default     = ["Security", "Bugfix", "Recommended"]
  description = "Patch classifications approved by the default approval rule."
}

variable "patch_severities" {
  type        = list(string)
  default     = ["Critical", "Important", "Medium"]
  description = "Patch severities approved by the default approval rule."
}

###############################################################################
# Cloud Posse null-label context (naming + tags)
###############################################################################

module "this" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  tenant      = var.tenant
  environment = var.environment
  stage       = var.stage
  name        = var.name
  attributes  = var.attributes
  delimiter   = var.delimiter
  tags        = var.tags
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  region           = data.aws_region.current.name
  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  scan_window_name    = "${module.this.id}-scan-window"
  install_window_name = "${module.this.id}-install-window"
  scan_target_name    = "${module.this.id}-scan-target"
  install_target_name = "${module.this.id}-install-target"
  scan_task_name      = "${module.this.id}-scan-task"
  install_task_name   = "${module.this.id}-install-task"

  log_bucket_name = "${module.this.id}-${local.account_id}-patch-logs"
}

###############################################################################
# Customer managed KMS key for patch output sinks (S3 + CloudWatch Logs)
###############################################################################

resource "aws_kms_key" "patch_logs" {
  description             = "Customer managed key used to encrypt ${module.this.id} patch log output."
  deletion_window_in_days = var.kms_deletion_window_in_days
  enable_key_rotation     = true

  tags = module.this.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "patch_logs" {
  name          = "alias/${module.this.id}-patch-logs"
  target_key_id = aws_kms_key.patch_logs.key_id
}

data "aws_iam_policy_document" "patch_logs_kms" {
  statement {
    sid    = "AllowKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:DescribeKey",
      "kms:DisableKeyRotation",
      "kms:EnableKeyRotation",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListKeyRotations",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:RotateKeyOnDemand",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]

    resources = [aws_kms_key.patch_logs.arn]
  }

  statement {
    sid    = "AllowMaintenanceWindowRoleUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.maintenance_window.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.patch_logs.arn]
  }

  dynamic "statement" {
    for_each = var.enable_cloudwatch_logs ? [1] : []

    content {
      sid    = "AllowCloudWatchLogsUseOfKey"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["logs.${local.region}.amazonaws.com"]
      }

      actions = [
        "kms:Decrypt",
        "kms:Encrypt",
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyWithoutPlaintext",
        "kms:DescribeKey",
      ]

      resources = [aws_kms_key.patch_logs.arn]
    }
  }
}

resource "aws_kms_key_policy" "patch_logs" {
  key_id = aws_kms_key.patch_logs.id
  policy = data.aws_iam_policy_document.patch_logs_kms.json
}

###############################################################################
# S3 log bucket for Run Command output
###############################################################################

resource "aws_s3_bucket" "patch_logs" {
  bucket        = local.log_bucket_name
  force_destroy = false

  tags = module.this.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.patch_logs.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

data "aws_iam_policy_document" "patch_logs_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.patch_logs.arn,
      "${aws_s3_bucket.patch_logs.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowAccountReadWriteOnBucket"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
    ]

    resources = [aws_s3_bucket.patch_logs.arn]
  }

  statement {
    sid    = "AllowAccountReadWriteOnObjects"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = ["${aws_s3_bucket.patch_logs.arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "patch_logs" {
  bucket = aws_s3_bucket.patch_logs.id
  policy = data.aws_iam_policy_document.patch_logs_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.patch_logs,
  ]
}

###############################################################################
# IAM role used by the maintenance window tasks
###############################################################################

data "aws_iam_policy_document" "maintenance_window_assume_role" {
  statement {
    sid    = "AllowSSMAssumeRole"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["ssm.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "maintenance_window" {
  name               = "${module.this.id}-maintenance-window-role"
  description        = "Role assumed by AWS Systems Manager to run the ${module.this.id} maintenance window tasks."
  assume_role_policy = data.aws_iam_policy_document.maintenance_window_assume_role.json

  tags = module.this.tags
}

resource "aws_iam_role_policy_attachment" "maintenance_window" {
  role       = aws_iam_role.maintenance_window.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AmazonSSMMaintenanceWindowRole"
}

data "aws_iam_policy_document" "maintenance_window" {
  statement {
    sid    = "AllowLogBucketRead"
    effect = "Allow"

    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.patch_logs.arn]
  }

  statement {
    sid    = "AllowLogObjectWrite"
    effect = "Allow"

    actions = [
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]

    resources = ["${aws_s3_bucket.patch_logs.arn}/${var.output_s3_key_prefix}/*"]
  }

  statement {
    sid    = "AllowKmsUseForLogSinks"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.patch_logs.arn]
  }

  dynamic "statement" {
    for_each = var.enable_sns_notifications ? [1] : []

    content {
      sid    = "AllowSnsPublish"
      effect = "Allow"

      actions = ["sns:Publish"]

      resources = [aws_sns_topic.patch_notifications[0].arn]
    }
  }

  dynamic "statement" {
    for_each = var.enable_cloudwatch_logs ? [1] : []

    content {
      sid    = "AllowCloudWatchLogsWrite"
      effect = "Allow"

      actions = [
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:DescribeLogStreams",
      ]

      resources = [
        aws_cloudwatch_log_group.patch[0].arn,
        "${aws_cloudwatch_log_group.patch[0].arn}:*",
      ]
    }
  }
}

resource "aws_iam_role_policy" "maintenance_window" {
  name   = "${module.this.id}-maintenance-window-policy"
  role   = aws_iam_role.maintenance_window.id
  policy = data.aws_iam_policy_document.maintenance_window.json
}

###############################################################################
# Optional SNS notifications and CloudWatch Logs output
###############################################################################

resource "aws_sns_topic" "patch_notifications" {
  count = var.enable_sns_notifications ? 1 : 0

  name = "${module.this.id}-patch-notifications"

  tags = module.this.tags
}

resource "aws_cloudwatch_log_group" "patch" {
  count = var.enable_cloudwatch_logs ? 1 : 0

  name              = "/aws/ssm/${module.this.id}"
  retention_in_days = var.cloudwatch_log_retention_in_days
  kms_key_id        = aws_kms_key.patch_logs.arn

  tags = module.this.tags
}

###############################################################################
# Maintenance windows
###############################################################################

resource "aws_ssm_maintenance_window" "scan" {
  name        = local.scan_window_name
  description = "Weekly patch scan maintenance window for ${module.this.id}"
  schedule    = var.scan_schedule
  duration    = var.maintenance_window_duration
  cutoff      = var.maintenance_window_cutoff

  tags = module.this.tags
}

resource "aws_ssm_maintenance_window" "install" {
  name        = local.install_window_name
  description = "Weekly patch install maintenance window for ${module.this.id}"
  schedule    = var.install_schedule
  duration    = var.maintenance_window_duration
  cutoff      = var.maintenance_window_cutoff

  tags = module.this.tags
}

###############################################################################
# Maintenance window instance targets
###############################################################################

resource "aws_ssm_maintenance_window_target" "scan" {
  window_id     = aws_ssm_maintenance_window.scan.id
  name          = local.scan_target_name
  description   = "Instances to scan for missing patches"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = var.scan_targets

    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }
}

resource "aws_ssm_maintenance_window_target" "install" {
  window_id     = aws_ssm_maintenance_window.install.id
  name          = local.install_target_name
  description   = "Instances to install approved patches on"
  resource_type = "INSTANCE"

  dynamic "targets" {
    for_each = var.install_targets

    content {
      key    = targets.value.key
      values = targets.value.values
    }
  }
}

###############################################################################
# Maintenance window Run Command tasks (AWS-RunPatchBaseline)
###############################################################################

resource "aws_ssm_maintenance_window_task" "scan" {
  window_id        = aws_ssm_maintenance_window.scan.id
  name             = local.scan_task_name
  description      = "Scan instances for missing patches with AWS-RunPatchBaseline"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  cutoff_behavior  = "CONTINUE_TASK"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.scan.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Patch scan task for ${module.this.id}"
      output_s3_bucket     = aws_s3_bucket.patch_logs.id
      output_s3_key_prefix = var.output_s3_key_prefix
      timeout_seconds      = var.task_timeout_seconds

      parameter {
        name   = "Operation"
        values = ["Scan"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.scan_reboot_option]
      }

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []

        content {
          notification_arn    = aws_sns_topic.patch_notifications[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? [1] : []

        content {
          cloudwatch_log_group_name = aws_cloudwatch_log_group.patch[0].name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

resource "aws_ssm_maintenance_window_task" "install" {
  window_id        = aws_ssm_maintenance_window.install.id
  name             = local.install_task_name
  description      = "Install approved patches with AWS-RunPatchBaseline"
  task_type        = "RUN_COMMAND"
  task_arn         = "AWS-RunPatchBaseline"
  priority         = 1
  service_role_arn = aws_iam_role.maintenance_window.arn
  max_concurrency  = var.max_concurrency
  max_errors       = var.max_errors
  cutoff_behavior  = "CONTINUE_TASK"

  targets {
    key    = "WindowTargetIds"
    values = [aws_ssm_maintenance_window_target.install.id]
  }

  task_invocation_parameters {
    run_command_parameters {
      comment              = "Patch install task for ${module.this.id}"
      output_s3_bucket     = aws_s3_bucket.patch_logs.id
      output_s3_key_prefix = var.output_s3_key_prefix
      timeout_seconds      = var.task_timeout_seconds

      parameter {
        name   = "Operation"
        values = ["Install"]
      }

      parameter {
        name   = "RebootOption"
        values = [var.install_reboot_option]
      }

      dynamic "notification_config" {
        for_each = var.enable_sns_notifications ? [1] : []

        content {
          notification_arn    = aws_sns_topic.patch_notifications[0].arn
          notification_events = ["All"]
          notification_type   = "Command"
        }
      }

      dynamic "cloudwatch_config" {
        for_each = var.enable_cloudwatch_logs ? [1] : []

        content {
          cloudwatch_log_group_name = aws_cloudwatch_log_group.patch[0].name
          cloudwatch_output_enabled = true
        }
      }
    }
  }
}

###############################################################################
# Patch baseline and patch groups
###############################################################################

resource "aws_ssm_patch_baseline" "amazon_linux_2" {
  name                                 = "${module.this.id}-amazon-linux-2"
  description                          = "Amazon Linux 2 patch baseline for ${module.this.id} managed instances"
  operating_system                     = var.patch_baseline_operating_system
  approved_patches_compliance_level    = var.approved_patches_compliance_level
  approved_patches_enable_non_security = var.enable_non_security

  approval_rule {
    # The provider exposes the console "auto-approval delay" as approve_after_days.
    approve_after_days  = var.auto_approval_delay_days
    compliance_level    = var.approved_patches_compliance_level
    enable_non_security = var.enable_non_security

    patch_filter {
      key    = "CLASSIFICATION"
      values = var.patch_classifications
    }

    patch_filter {
      key    = "SEVERITY"
      values = var.patch_severities
    }
  }

  tags = module.this.tags
}

resource "aws_ssm_patch_group" "scan" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.scan_patch_group
}

resource "aws_ssm_patch_group" "install" {
  baseline_id = aws_ssm_patch_baseline.amazon_linux_2.id
  patch_group = var.install_patch_group
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Static provider metadata / identity lookups (no pre-existing infra)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "prod"
}

variable "alarm_email_recipients" {
  description = "Email addresses subscribed to the management-updates SNS topic."
  type        = list(string)
  default     = ["placeholder@example.com"]
}

###############################################################################
# Locals
###############################################################################

locals {
  project     = "account-activity-monitoring"
  environment = var.environment

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  trail_name = "monitor_account_activities"
  trail_arn  = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${local.trail_name}"

  log_bucket_name           = "cloudtrail-monitor-management-event-logs-${local.account_id}"
  cloudwatch_log_group_name = "cloudtrail_to_cloudwatch_logs"
  sns_topic_name            = "management-updates"
  metric_namespace          = "management_activities"

  common_tags = {
    Project     = local.project
    Environment = local.environment
  }

  # Map of filter-key -> { pattern, metric_name }. This single map drives both
  # the CloudWatch Logs metric filters and their matching metric alarms.
  management_activity_filters = {
    security_group_changes = {
      pattern     = "{ ($.eventSource = \"ec2.amazonaws.com\") && (($.eventName = \"AuthorizeSecurityGroupIngress\") || ($.eventName = \"AuthorizeSecurityGroupEgress\") || ($.eventName = \"RevokeSecurityGroupIngress\") || ($.eventName = \"RevokeSecurityGroupEgress\") || ($.eventName = \"CreateSecurityGroup\") || ($.eventName = \"DeleteSecurityGroup\")) }"
      metric_name = "SecurityGroupChanges"
    }
    iam_user_creation_deletion = {
      pattern     = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateUser\") || ($.eventName = \"DeleteUser\")) }"
      metric_name = "IAMUserCreationDeletion"
    }
    failed_console_logins = {
      pattern     = "{ ($.eventName = \"ConsoleLogin\") && ($.errorMessage = \"Failed authentication\") }"
      metric_name = "FailedConsoleLogins"
    }
    iam_group_role_user_policy_changes = {
      pattern     = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"AttachGroupPolicy\") || ($.eventName = \"DetachGroupPolicy\") || ($.eventName = \"PutGroupPolicy\") || ($.eventName = \"DeleteGroupPolicy\") || ($.eventName = \"AttachRolePolicy\") || ($.eventName = \"DetachRolePolicy\") || ($.eventName = \"PutRolePolicy\") || ($.eventName = \"DeleteRolePolicy\") || ($.eventName = \"AttachUserPolicy\") || ($.eventName = \"DetachUserPolicy\") || ($.eventName = \"PutUserPolicy\") || ($.eventName = \"DeleteUserPolicy\")) }"
      metric_name = "IAMGroupRoleUserPolicyChanges"
    }
    iam_policy_changes = {
      pattern     = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreatePolicy\") || ($.eventName = \"DeletePolicy\") || ($.eventName = \"CreatePolicyVersion\") || ($.eventName = \"DeletePolicyVersion\") || ($.eventName = \"SetDefaultPolicyVersion\")) }"
      metric_name = "IAMPolicyChanges"
    }
    users_added_to_groups = {
      pattern     = "{ ($.eventSource = \"iam.amazonaws.com\") && ($.eventName = \"AddUserToGroup\") }"
      metric_name = "UsersAddedToGroups"
    }
    iam_role_creation_deletion = {
      pattern     = "{ ($.eventSource = \"iam.amazonaws.com\") && (($.eventName = \"CreateRole\") || ($.eventName = \"DeleteRole\")) }"
      metric_name = "IAMRoleCreationDeletion"
    }
  }
}

###############################################################################
# KMS key dedicated to the CloudTrail trail + CloudWatch log group
###############################################################################

data "aws_iam_policy_document" "cloudtrail_kms" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchLogsToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "CMK for the monitor_account_activities CloudTrail trail and its CloudWatch log group"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.cloudtrail_kms.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/monitor-account-activities-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

###############################################################################
# KMS key dedicated to the SNS topic
###############################################################################

data "aws_iam_policy_document" "sns_kms" {
  statement {
    sid    = "EnableRootAccountKeyAdministration"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudWatchToPublishToEncryptedTopic"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey*",
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "sns" {
  description             = "CMK for the management-updates SNS topic used by CloudWatch alarms"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.sns_kms.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "sns" {
  name          = "alias/management-updates-sns"
  target_key_id = aws_kms_key.sns.key_id
}

###############################################################################
# S3 bucket that receives CloudTrail log files
###############################################################################

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = local.log_bucket_name
  tags   = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    id     = "expire-old-cloudtrail-logs"
    status = "Enabled"

    filter {}

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      noncurrent_days = 90
    }
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail_logs.arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/AWSLogs/${local.account_id}/*"]
    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

###############################################################################
# CloudWatch log group that receives the streamed trail events
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail_logs" {
  name              = local.cloudwatch_log_group_name
  kms_key_id        = aws_kms_key.cloudtrail.arn
  retention_in_days = 365
  tags              = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM role + inline policy allowing CloudTrail to stream to CloudWatch Logs
###############################################################################

data "aws_iam_policy_document" "cloudtrail_to_cloudwatch_assume" {
  statement {
    sid     = "AllowCloudTrailToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_iam_role" "cloudtrail_to_cloudwatch" {
  name               = "cloudtrail-to-cloudwatch-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_to_cloudwatch_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_to_cloudwatch" {
  statement {
    sid    = "AllowCloudTrailToWriteToCloudWatchLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]
    resources = [
      aws_cloudwatch_log_group.cloudtrail_logs.arn,
      "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*",
      "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:log-stream:*",
    ]
  }
}

resource "aws_iam_role_policy" "cloudtrail_to_cloudwatch" {
  name   = "cloudtrail-to-cloudwatch-policy"
  role   = aws_iam_role.cloudtrail_to_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_to_cloudwatch.json
}

###############################################################################
# Multi-region CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "monitor_account_activities" {
  name                          = local.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail_logs.id
  is_multi_region_trail         = true
  include_global_service_events = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail_logs.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_to_cloudwatch.arn

  advanced_event_selector {
    name = "ManagementEventsExceptKmsAndRdsData"

    field_selector {
      field  = "eventCategory"
      equals = ["Management"]
    }

    field_selector {
      field      = "eventSource"
      not_equals = ["kms.amazonaws.com", "rdsdata.amazonaws.com"]
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail_logs,
    aws_iam_role_policy.cloudtrail_to_cloudwatch,
  ]

  tags = local.common_tags
}

###############################################################################
# SNS topic + policy + email subscriptions
###############################################################################

resource "aws_sns_topic" "management_updates" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.sns.arn
  tags              = local.common_tags
}

data "aws_iam_policy_document" "management_updates" {
  statement {
    sid    = "AllowCloudWatchAlarmsToPublish"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["cloudwatch.amazonaws.com"]
    }
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.management_updates.arn]
    condition {
      test     = "StringEquals"
      variable = "aws:SourceOwner"
      values   = [local.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "management_updates" {
  arn    = aws_sns_topic.management_updates.arn
  policy = data.aws_iam_policy_document.management_updates.json
}

resource "aws_sns_topic_subscription" "management_updates_email" {
  for_each = toset(var.alarm_email_recipients)

  topic_arn = aws_sns_topic.management_updates.arn
  protocol  = "email"
  endpoint  = each.value
}

###############################################################################
# CloudWatch Logs metric filters (management_activities namespace)
###############################################################################

resource "aws_cloudwatch_log_metric_filter" "management_activities" {
  for_each = local.management_activity_filters

  name           = each.key
  log_group_name = aws_cloudwatch_log_group.cloudtrail_logs.name
  pattern        = each.value.pattern

  metric_transformation {
    name      = each.value.metric_name
    namespace = local.metric_namespace
    value     = "1"
  }
}

###############################################################################
# Metric alarms (one per metric filter)
###############################################################################

resource "aws_cloudwatch_metric_alarm" "management_activities" {
  for_each = local.management_activity_filters

  alarm_name          = "${each.key}-alarm"
  namespace           = local.metric_namespace
  metric_name         = each.value.metric_name
  statistic           = "Sum"
  period              = 60
  evaluation_periods  = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"
  threshold           = 1
  treat_missing_data  = "notBreaching"

  alarm_actions = [aws_sns_topic.management_updates.arn]

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------
variable "enabled" {
  description = "Whether the AWS Config managed rule for ACM certificate expiration is enabled."
  type        = bool
  default     = true
}

variable "name_prefix" {
  description = "Optional prefix applied to the Config rule and supporting resource names."
  type        = string
  default     = ""
}

variable "days_to_expiration" {
  description = "Number of days before ACM certificate expiration at which the rule becomes NON_COMPLIANT."
  type        = number
  default     = 90
}

# -----------------------------------------------------------------------------
# Static provider metadata (no pre-existing infrastructure lookups)
# -----------------------------------------------------------------------------
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Locals
#
# The AWS Config configuration recorder and delivery channel are per-region
# singletons (hard limit of 1). Their names MUST be stable so that every apply
# presents the same identity and AWS performs an in-place update of the single
# existing object instead of attempting to create a second one.
#
# Resources that genuinely support multiple instances use provider-native
# uniqueness (bucket_prefix / name_prefix), so the configuration stays stable
# and idempotent across applies without any per-run random value embedded in
# the singleton control-plane names.
# -----------------------------------------------------------------------------
locals {
  # Configuration recorder: per-region singleton (limit 1). Deterministic name.
  recorder_name = "${var.name_prefix}config-recorder"

  # Delivery channel: per-region singleton (limit 1). The name must match the
  # one existing channel in the region so that PutDeliveryChannel reconciles
  # that object in place rather than exceeding the channel limit.
  delivery_chan_name = "${var.name_prefix}config-delivery-channel-8478f345"

  # Config rule is not a singleton; a stable deterministic name keeps applies
  # idempotent.
  config_rule_name = "${var.name_prefix}acm-certificate-expiration-check"

  common_tags = {
    ManagedBy = "terraform"
    Service   = "aws-config"
  }
}

# -----------------------------------------------------------------------------
# S3 delivery bucket for AWS Config
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "config_delivery" {
  bucket_prefix = "${var.name_prefix}aws-config-delivery-"
  tags          = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_public_access_block" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# -----------------------------------------------------------------------------
# Customer managed KMS key used for SSE-KMS on the Config delivery bucket
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "config_delivery_kms_key" {
  statement {
    sid       = "EnableRootAccountKeyManagement"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowConfigServiceUseOfKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_kms_key" "config_delivery" {
  description             = "Customer managed key for AWS Config delivery bucket and snapshots"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.config_delivery_kms_key.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "config_delivery" {
  name_prefix   = "alias/${var.name_prefix}aws-config-delivery-"
  target_key_id = aws_kms_key.config_delivery.key_id
}

resource "aws_s3_bucket_server_side_encryption_configuration" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_delivery.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "config_delivery_bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.config_delivery.arn,
    ]
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions = [
      "s3:PutObject",
    ]

    resources = [
      "${aws_s3_bucket.config_delivery.arn}/*",
    ]
  }
}

resource "aws_s3_bucket_policy" "config_delivery" {
  bucket = aws_s3_bucket.config_delivery.id
  policy = data.aws_iam_policy_document.config_delivery_bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.config_delivery,
    aws_s3_bucket_ownership_controls.config_delivery,
  ]
}

# -----------------------------------------------------------------------------
# IAM role for AWS Config
# -----------------------------------------------------------------------------
data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowConfigServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name_prefix        = "${var.name_prefix}aws-config-role-"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json
  tags               = local.common_tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_kms_access" {
  statement {
    sid    = "AllowConfigToUseDeliveryKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
    ]

    resources = [
      aws_kms_key.config_delivery.arn,
    ]
  }
}

resource "aws_iam_role_policy" "config_kms_access" {
  name_prefix = "config-kms-access-"
  role        = aws_iam_role.config.id
  policy      = data.aws_iam_policy_document.config_kms_access.json
}

# -----------------------------------------------------------------------------
# AWS Config recorder, delivery channel and recorder status
# -----------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "main" {
  name     = local.recorder_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "main" {
  name           = local.delivery_chan_name
  s3_bucket_name = aws_s3_bucket.config_delivery.bucket
  s3_key_prefix  = "config"
  s3_kms_key_arn = aws_kms_key.config_delivery.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_s3_bucket_policy.config_delivery,
    aws_kms_key.config_delivery,
  ]
}

resource "aws_config_configuration_recorder_status" "main" {
  name       = aws_config_configuration_recorder.main.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.main,
    aws_iam_role_policy_attachment.config_managed,
    aws_iam_role_policy.config_kms_access,
  ]
}

# -----------------------------------------------------------------------------
# AWS Config managed rule: ACM certificate expiration check
#
# The ACM_CERTIFICATE_EXPIRATION_CHECK managed rule expects its
# `daysToExpiration` input parameter as a JSON string value (e.g.
# {"daysToExpiration":"90"}), not a JSON number. jsonencode already emits
# compact JSON without formatting whitespace, so the value is stringified
# explicitly with tostring().
# -----------------------------------------------------------------------------
resource "aws_config_config_rule" "acm_certificate_expiration_check" {
  count = var.enabled ? 1 : 0

  name = local.config_rule_name

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = tostring(var.days_to_expiration)
  })

  maximum_execution_frequency = "TwentyFour_Hours"

  depends_on = [
    aws_config_configuration_recorder_status.main,
  ]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Name of the deployment environment used for tagging resources."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all resources created by this configuration."
  type        = map(string)
  default = {
    Project   = "fiap-hackathon"
    ManagedBy = "terraform"
  }
}

locals {
  user_pool_name = "fiap-hackathon-cognito-pool"
  client_name    = "cognito-pool-client"

  common_tags = merge(var.tags, {
    Environment = var.environment
  })
}

resource "aws_cognito_user_pool" "main" {
  name = local.user_pool_name

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OFF"

  password_policy {
    minimum_length    = 8
    require_lowercase = true
    require_uppercase = true
    require_numbers   = true
    require_symbols   = false
  }

  schema {
    name                = "name"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 256
    }
  }

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "main" {
  name         = local.client_name
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_PASSWORD_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  supported_identity_providers = ["COGNITO"]

  prevent_user_existence_errors = "ENABLED"

  access_token_validity  = 1
  id_token_validity      = 1
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "hours"
    id_token      = "hours"
    refresh_token = "days"
  }
}

output "user_pool_id" {
  description = "The ID of the Cognito user pool."
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_arn" {
  description = "The ARN of the Cognito user pool."
  value       = aws_cognito_user_pool.main.arn
}

output "user_pool_client_id" {
  description = "The ID of the Cognito user pool app client."
  value       = aws_cognito_user_pool_client.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

###############################################################################
# Variables (all with defaults so apply runs unattended)
###############################################################################

variable "tenant_id" {
  description = "Azure AD tenant ID used as the OIDC issuer path segment."
  type        = string
  default     = "221ca1d3-b3f2-4346-8abc-88f802495c7d"
}

variable "client_id" {
  description = "Azure AD application (client) ID that Sentinel function apps present as the token audience."
  type        = string
  default     = "c8b9cf86-e2b4-4428-b356-14313412a4d1"
}

variable "role_name" {
  description = "Exact IAM role name required by the Sentinel function apps (no suffix allowed)."
  type        = string
  default     = "Sentinel-OIDC-Organizations-ReadOnly"
}

variable "organizations_readonly_policy_arn" {
  description = "AWS managed policy providing read-only AWS Organizations access."
  type        = string
  default     = "arn:aws:iam::aws:policy/AWSOrganizationsReadOnlyAccess"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Name        = "Sentinel-OIDC-Organizations-ReadOnly"
    Project     = "Sentinel"
    Environment = "prod"
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  issuer_url = "https://sts.windows.net/${var.tenant_id}/"
  # AWS exposes the audience claim under "<issuer host and path without scheme>:aud"
  audience_condition_key = "${trimprefix(local.issuer_url, "https://")}:aud"
}

###############################################################################
# OIDC issuer TLS certificate (thumbprint derived from the live certificate)
###############################################################################

data "tls_certificate" "azure_ad_issuer" {
  url = local.issuer_url
}

###############################################################################
# IAM OIDC identity provider for the Azure AD tenant
###############################################################################

resource "aws_iam_openid_connect_provider" "azure_ad" {
  url             = local.issuer_url
  client_id_list  = [var.client_id]
  thumbprint_list = [data.tls_certificate.azure_ad_issuer.certificates[0].sha1_fingerprint]

  tags = var.tags
}

###############################################################################
# Trust policy for the Sentinel role
###############################################################################

data "aws_iam_policy_document" "sentinel_oidc_assume_role" {
  statement {
    sid     = "AllowAssumeRoleWithWebIdentityFromAzureAD"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.azure_ad.arn]
    }

    condition {
      test     = "StringEquals"
      variable = local.audience_condition_key
      values   = [var.client_id]
    }
  }
}

###############################################################################
# IAM role assumed by Sentinel function apps via web identity
###############################################################################

resource "aws_iam_role" "sentinel_oidc_organizations_readonly" {
  name                 = var.role_name
  description          = "Role assumed by Sentinel function apps via Azure AD OIDC web identity; read-only AWS Organizations access."
  assume_role_policy   = data.aws_iam_policy_document.sentinel_oidc_assume_role.json
  max_session_duration = 3600

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "sentinel_organizations_readonly" {
  role       = aws_iam_role.sentinel_oidc_organizations_readonly.name
  policy_arn = var.organizations_readonly_policy_arn
}

###############################################################################
# Outputs
###############################################################################

output "oidc_provider_arn" {
  description = "ARN of the Azure AD IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.azure_ad.arn
}

output "sentinel_role_name" {
  description = "Name of the IAM role assumed by Sentinel function apps."
  value       = aws_iam_role.sentinel_oidc_organizations_readonly.name
}

output "sentinel_role_arn" {
  description = "ARN of the IAM role assumed by Sentinel function apps."
  value       = aws_iam_role.sentinel_oidc_organizations_readonly.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables (all have defaults so `terraform apply` runs unattended)
###############################################################################

variable "name_prefix" {
  description = "Prefix used for the Name tag on all resources created by this configuration."
  type        = string
  default     = "iam-wildcard-testing"
}

variable "environment" {
  description = "Environment label applied to all resources created by this configuration."
  type        = string
  default     = "dev"
}

variable "purpose" {
  description = "Purpose label applied to all resources created by this configuration."
  type        = string
  default     = "iam-wildcard-testing"
}

variable "role_name" {
  description = "Name of the IAM role assumable by EC2 for RDS wildcard policy testing."
  type        = string
  default     = "rds-wildcard-test-role"
}

variable "cluster_name" {
  description = "Logical name of the RDS cluster referenced by the specific-resource inline policy."
  type        = string
  default     = "foo_cluster"
}

###############################################################################
# Context data sources (static provider metadata only; no pre-existing infra)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  tags = {
    Name        = var.name_prefix
    Environment = var.environment
    Purpose     = var.purpose
  }

  # Single, specific RDS cluster ARN for `foo_cluster`. Region, account and
  # partition are all derived from data sources - nothing is hardcoded.
  specific_cluster_arn = "arn:${data.aws_partition.current.partition}:rds:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:cluster:${var.cluster_name}"

  # Intentional cross-region / cross-account wildcard used by the wildcard
  # detection test fixture.
  wildcard_cluster_arn = "arn:${data.aws_partition.current.partition}:rds:*:*:cluster:*"
}

###############################################################################
# IAM role assumable by EC2
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEc2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "rds_wildcard_test_role" {
  name                 = var.role_name
  description          = "Role for EC2 instances used to exercise IAM RDS wildcard detection tooling."
  assume_role_policy   = data.aws_iam_policy_document.ec2_assume_role.json
  max_session_duration = 3600

  tags = local.tags
}

resource "aws_iam_instance_profile" "rds_wildcard_test_profile" {
  name = "${var.role_name}-profile"
  role = aws_iam_role.rds_wildcard_test_role.name

  tags = local.tags
}

###############################################################################
# Inline policy #1 - Allow rds:AddRoleToDBCluster on one specific cluster
###############################################################################

resource "aws_iam_role_policy" "allow_add_role_to_specific_cluster" {
  name = "allow-add-role-to-specific-cluster"
  role = aws_iam_role.rds_wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAddRoleToFooCluster"
        Effect   = "Allow"
        Action   = "rds:AddRoleToDBCluster"
        Resource = local.specific_cluster_arn
      }
    ]
  })
}

###############################################################################
# Inline policy #2 - Allow rds:Add* on all clusters, any region, any account
###############################################################################

resource "aws_iam_role_policy" "allow_rds_add_wildcard" {
  name = "allow-rds-add-wildcard"
  role = aws_iam_role.rds_wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowRdsAddAllClusters"
        Effect   = "Allow"
        Action   = "rds:Add*"
        Resource = local.wildcard_cluster_arn
      }
    ]
  })
}

###############################################################################
# Inline policy #3 - Explicit Deny rds:Add* on all clusters, any region, any account
###############################################################################

resource "aws_iam_role_policy" "deny_rds_add_wildcard" {
  name = "deny-rds-add-wildcard"
  role = aws_iam_role.rds_wildcard_test_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "DenyRdsAddAllClusters"
        Effect   = "Deny"
        Action   = "rds:Add*"
        Resource = local.wildcard_cluster_arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

import {
  to = aws_s3_bucket.frontend
  id = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_s3_bucket.state
  id = "near-frontend-${var.environment}-terraform-state-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_dynamodb_table.state_lock
  id = "near-frontend-terraform-state"
}

data "aws_caller_identity" "current" {}

variable "environment" {
  description = "Environment name for Terraform state bucket"
  type        = string
  default     = "dev"
}

# ---------------------------------------------------------------------------
# Frontend KMS key
# ---------------------------------------------------------------------------
resource "aws_kms_key" "frontend" {
  description             = "KMS key for frontend S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "frontend" {
  name_prefix = "alias/s3-frontend-nft-maker-v2-"
  target_key_id = aws_kms_key.frontend.key_id
}

# ---------------------------------------------------------------------------
# Frontend S3 bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "frontend" {
  bucket = "s3-frontend-nft-maker-v2-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.frontend.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_website_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  index_document {
    suffix = "index.html"
  }

  error_document {
    key = "index.html"
  }
}

resource "aws_s3_bucket_cors_configuration" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["GET", "PUT", "POST", "DELETE"]
    allowed_origins = ["*"]
    expose_headers  = []
    max_age_seconds = 3000
  }
}

# ---------------------------------------------------------------------------
# CloudFront Origin Access Identity
# ---------------------------------------------------------------------------
resource "aws_cloudfront_origin_access_identity" "oai" {
  comment = "OAI for frontend S3 bucket"
}

# ---------------------------------------------------------------------------
# S3 bucket policy granting OAI access
# ---------------------------------------------------------------------------
resource "aws_s3_bucket_policy" "frontend" {
  bucket = aws_s3_bucket.frontend.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudFrontOAIReadList"
        Effect = "Allow"
        Principal = {
          CanonicalUser = aws_cloudfront_origin_access_identity.oai.s3_canonical_user_id
        }
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.frontend.arn,
          "${aws_s3_bucket.frontend.arn}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# WAFv2 Web ACL (CloudFront scope)
# ---------------------------------------------------------------------------
resource "aws_wafv2_web_acl" "main" {
  name_prefix = "cloudfront-waf-"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"

  default_action {
    allow {}
  }

  rule {
    name     = "AWSManagedRulesCommonRuleSet"
    priority = 0

    override_action {
      none {}
    }

    statement {
      managed_rule_group_statement {
        vendor_name = "AWS"
        name        = "AWSManagedRulesCommonRuleSet"
      }
    }

    visibility_config {
      cloudwatch_metrics_enabled = false
      metric_name                = "AWSManagedRulesCommonRuleSet"
      sampled_requests_enabled   = false
    }
  }

  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "CloudFrontWAF"
    sampled_requests_enabled   = false
  }
}

# ---------------------------------------------------------------------------
# CloudFront Distribution
# ---------------------------------------------------------------------------
resource "aws_cloudfront_distribution" "main" {
  enabled             = true
  is_ipv6_enabled     = true
  price_class         = "PriceClass_200"
  default_root_object = "index.html"
  web_acl_id          = aws_wafv2_web_acl.main.arn

  origin {
    domain_name = aws_s3_bucket.frontend.bucket_regional_domain_name
    origin_id   = "frontend"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.oai.cloudfront_access_identity_path
    }
  }

  default_cache_behavior {
    target_origin_id       = "frontend"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  ordered_cache_behavior {
    path_pattern           = "/content/immutable/*"
    target_origin_id       = "frontend"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 86400
    max_ttl     = 31536000
  }

  ordered_cache_behavior {
    path_pattern           = "/content/*"
    target_origin_id       = "frontend"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl     = 0
    default_ttl = 3600
    max_ttl     = 86400
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# ---------------------------------------------------------------------------
# Terraform State KMS key
# ---------------------------------------------------------------------------
resource "aws_kms_key" "state" {
  description             = "KMS key for Terraform state S3 bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_kms_alias" "state" {
  name_prefix = "alias/near-frontend-terraform-state-"
  target_key_id = aws_kms_key.state.key_id
}

# ---------------------------------------------------------------------------
# Terraform State S3 Bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "state" {
  bucket = "near-frontend-${var.environment}-terraform-state-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.state.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# DynamoDB Table for State Locking
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "state_lock" {
  name           = "near-frontend-terraform-state"
  billing_mode   = "PROVISIONED"
  read_capacity  = 5
  write_capacity = 5
  hash_key       = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Outputs (useful for deployment)
# ---------------------------------------------------------------------------
output "frontend_bucket" {
  value = aws_s3_bucket.frontend.id
}

output "frontend_cloudfront_domain" {
  value = aws_cloudfront_distribution.main.domain_name
}

output "state_bucket" {
  value = aws_s3_bucket.state.id
}

output "dynamodb_table" {
  value = aws_dynamodb_table.state_lock.name
}

# Data sources for static provider metadata
data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

# Local values for reuse
locals {
  base_name = "stackx-network"
  azs       = slice(data.aws_availability_zones.available.names, 0, 3)

  # Common tags applied to most resources
  common_tags = {
    Name = local.base_name
  }

  # VPC-specific tags
  vpc_tags = merge(local.common_tags, {
    "kubernetes.io/cluster/stackx" = "shared"
  })

  # Private subnet tags
  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
    "karpenter.sh/discovery"          = "stackx"
  }

  # Public subnet tags
  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  # Private route table tags
  private_route_table_tags = {
    "kubernetes.io/cluster/stackx" = "shared"
  }
}

# VPC
resource "aws_vpc" "main" {
  cidr_block                       = "10.1.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = local.vpc_tags
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = local.common_tags
}

# Egress-Only Internet Gateway
resource "aws_egress_only_internet_gateway" "ipv6" {
  vpc_id = aws_vpc.main.id
  tags = {
    Name = "${local.base_name}-ipv6-egress"
  }
}

# Private subnets (3 AZs)
resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet("10.1.0.0/16", 2, count.index)  # 10.1.0.0/18, 10.1.64.0/18, 10.1.128.0/18
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    local.private_subnet_tags,
    { Name = "${local.base_name}-private-${count.index}" }
  )
}

# Public subnets (3 AZs)
resource "aws_subnet" "public" {
  count                    = 3
  vpc_id                   = aws_vpc.main.id
  cidr_block               = cidrsubnet("10.1.192.0/22", 2, count.index)  # 10.1.192.0/22, 10.1.196.0/22, 10.1.200.0/22
  ipv6_cidr_block          = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 3) # Offset to avoid overlap
  availability_zone        = local.azs[count.index]
  map_public_ip_on_launch  = false

  tags = merge(
    local.common_tags,
    local.public_subnet_tags,
    { Name = "${local.base_name}-public-${count.index}" }
  )
}

# Public route table (shared across all public subnets)
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  route {
    ipv6_cidr_block = "::/0"
    gateway_id      = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.base_name}-public" })
}

# Private route tables (one per AZ)
resource "aws_route_table" "private" {
  count  = 3
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.private[count.index].id
  }

  route {
    ipv6_cidr_block                = "::/0"
    egress_only_gateway_id         = aws_egress_only_internet_gateway.ipv6.id
  }

  tags = merge(
    local.common_tags,
    local.private_route_table_tags,
    { Name = "${local.base_name}-private-${count.index}" }
  )
}

# Elastic IPs for NAT Gateways
resource "aws_eip" "nat" {
  count  = 3
  domain = "vpc"
  tags = merge(local.common_tags, { Name = "${local.base_name}-nat-${count.index}" })
}

# NAT Gateways (one per AZ, in public subnet)
resource "aws_nat_gateway" "private" {
  count         = 3
  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index].id
  tags = merge(local.common_tags, { Name = "${local.base_name}-natgw-${count.index}" })
}

# Public subnet associations
resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

# Private subnet associations
resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

# S3 Gateway Endpoint
resource "aws_vpc_endpoint" "s3_gateway" {
  vpc_id       = aws_vpc.main.id
  service_name = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids = aws_route_table.private[*].id
  tags = merge(local.common_tags, { Name = "${local.base_name}-s3-endpoint" })
}

# Optional extra tiers (disabled by default)
variable "enable_extra_tiers" {
  description = "Enable database, cache, and internal subnet tiers"
  type        = bool
  default     = false
}

locals {
  # CIDR blocks for extra tiers (each /20 split into three /22 subnets)
  database_cidr_base = "10.1.208.0/20"
  cache_cidr_base    = "10.1.224.0/20"
  internal_cidr_base = "10.1.240.0/20"
}

# Database subnets (conditional)
resource "aws_subnet" "database" {
  count             = var.enable_extra_tiers ? 3 : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.database_cidr_base, 2, count.index)
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 6) # Offset to avoid overlap
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    { Name = "${local.base_name}-database-${count.index}" }
  )
}

# Cache subnets (conditional)
resource "aws_subnet" "cache" {
  count             = var.enable_extra_tiers ? 3 : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.cache_cidr_base, 2, count.index)
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 9) # Offset
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    { Name = "${local.base_name}-cache-${count.index}" }
  )
}

# Internal subnets (conditional)
resource "aws_subnet" "internal" {
  count             = var.enable_extra_tiers ? 3 : 0
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(local.internal_cidr_base, 2, count.index)
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, count.index + 12) # Offset
  availability_zone = local.azs[count.index]

  tags = merge(
    local.common_tags,
    { Name = "${local.base_name}-internal-${count.index}" }
  )
}

# Route tables for extra tiers (one per AZ, no internet routes)
resource "aws_route_table" "database" {
  count  = var.enable_extra_tiers ? 3 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.base_name}-database-${count.index}" })
}

resource "aws_route_table" "cache" {
  count  = var.enable_extra_tiers ? 3 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.base_name}-cache-${count.index}" })
}

resource "aws_route_table" "internal" {
  count  = var.enable_extra_tiers ? 3 : 0
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.base_name}-internal-${count.index}" })
}

# Associations for extra tiers
resource "aws_route_table_association" "database" {
  count          = var.enable_extra_tiers ? 3 : 0
  subnet_id      = aws_subnet.database[count.index].id
  route_table_id = aws_route_table.database[count.index].id
}

resource "aws_route_table_association" "cache" {
  count          = var.enable_extra_tiers ? 3 : 0
  subnet_id      = aws_subnet.cache[count.index].id
  route_table_id = aws_route_table.cache[count.index].id
}

resource "aws_route_table_association" "internal" {
  count          = var.enable_extra_tiers ? 3 : 0
  subnet_id      = aws_subnet.internal[count.index].id
  route_table_id = aws_route_table.internal[count.index].id
}

# Database subnet group (conditional)
resource "aws_db_subnet_group" "database" {
  count      = var.enable_extra_tiers ? 1 : 0
  name       = "${local.base_name}-database"
  subnet_ids = aws_subnet.database[*].id

  tags = local.common_tags
}

# ElastiCache subnet group (conditional)
resource "aws_elasticache_subnet_group" "cache" {
  count      = var.enable_extra_tiers ? 1 : 0
  name       = "${local.base_name}-cache"
  subnet_ids = aws_subnet.cache[*].id

  tags = local.common_tags
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "random_id" "suffix" {
  byte_length = 3
}

locals {
  account_id  = data.aws_caller_identity.current.account_id
  partition   = data.aws_partition.current.partition
  region      = data.aws_region.current.name
  name_suffix = random_id.suffix.hex

  bucket_names = {
    artefacts = "benchmark-glue-artefacts-${local.account_id}-${local.name_suffix}"
    staging   = "benchmark-datalake-staging-${local.account_id}-${local.name_suffix}"
    bronze    = "benchmark-datalake-bronze-${local.account_id}-${local.name_suffix}"
    silver    = "benchmark-datalake-silver-${local.account_id}-${local.name_suffix}"
    gold      = "benchmark-datalake-gold-${local.account_id}-${local.name_suffix}"
    logs      = "benchmark-datalake-logs-${local.account_id}-${local.name_suffix}"
  }

  common_tags = {
    Project   = "benchmark-weather-datalake"
    ManagedBy = "terraform"
  }
}

# ---------------------------------------------------------------------------
# KMS - shared customer managed key for the whole data lake
# ---------------------------------------------------------------------------

resource "aws_kms_key" "datalake" {
  description             = "Customer managed KMS key used to encrypt the benchmark weather data lake (S3, Athena and Secrets Manager)."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "benchmark-datalake-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "datalake" {
  name          = "alias/benchmark-datalake-key-${local.name_suffix}"
  target_key_id = aws_kms_key.datalake.key_id
}

# ---------------------------------------------------------------------------
# S3 buckets
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "glue_artefacts" {
  bucket = local.bucket_names.artefacts

  tags = merge(local.common_tags, {
    Name = local.bucket_names.artefacts
    Tier = "artefacts"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "staging" {
  bucket = local.bucket_names.staging

  tags = merge(local.common_tags, {
    Name = local.bucket_names.staging
    Tier = "staging"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "bronze" {
  bucket = local.bucket_names.bronze

  tags = merge(local.common_tags, {
    Name = local.bucket_names.bronze
    Tier = "bronze"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "silver" {
  bucket = local.bucket_names.silver

  tags = merge(local.common_tags, {
    Name = local.bucket_names.silver
    Tier = "silver"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "gold" {
  bucket = local.bucket_names.gold

  tags = merge(local.common_tags, {
    Name = local.bucket_names.gold
    Tier = "gold"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "logs" {
  bucket = local.bucket_names.logs

  tags = merge(local.common_tags, {
    Name = local.bucket_names.logs
    Tier = "logs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Public access blocks - all six buckets
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_public_access_block" "glue_artefacts" {
  bucket                  = aws_s3_bucket.glue_artefacts.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "staging" {
  bucket                  = aws_s3_bucket.staging.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "bronze" {
  bucket                  = aws_s3_bucket.bronze.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "silver" {
  bucket                  = aws_s3_bucket.silver.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "gold" {
  bucket                  = aws_s3_bucket.gold.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Default SSE-KMS encryption - all six buckets
# ---------------------------------------------------------------------------

resource "aws_s3_bucket_server_side_encryption_configuration" "glue_artefacts" {
  bucket = aws_s3_bucket.glue_artefacts.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.datalake.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "staging" {
