# ---------------------------------------------------------------------------
# Glue job scripts uploaded into the artefacts bucket (inline content)
# ---------------------------------------------------------------------------

resource "aws_s3_object" "extrai_dados_script" {
  bucket                 = aws_s3_bucket.glue_artefacts.id
  key                    = "scripts/extraiDados.py"
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.datalake.arn

  content = <<-EOT
    import sys
    from awsglue.transforms import *
    from awsglue.utils import getResolvedOptions
    from pyspark.context import SparkContext
    from awsglue.context import GlueContext
    from awsglue.job import Job

    args = getResolvedOptions(
        sys.argv,
        ["JOB_NAME", "city", "staging_bucket", "api_key"],
    )

    sc = SparkContext()
    glueContext = GlueContext(sc)
    spark = glueContext.spark_session
    job = Job(glueContext)
    job.init(args["JOB_NAME"], args)

    # Extraction entrypoint: reads weather data for the requested city and
    # writes the raw payload into the staging bucket.
    city = args["city"]
    staging_bucket = args["staging_bucket"]
    api_key = args["api_key"]

    print("Extracting weather data for city '%s' into %s" % (city, staging_bucket))

    # Weather extraction logic is provided here so the object is created
    # entirely from the template.

    job.commit()
  EOT

  tags = merge(local.common_tags, {
    Name = "glue-script-extrai-dados"
  })
}

resource "aws_s3_object" "transforma_dados_script" {
  bucket                 = aws_s3_bucket.glue_artefacts.id
  key                    = "scripts/transformaDados.py"
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.datalake.arn

  content = <<-EOT
    import sys
    from awsglue.transforms import *
    from awsglue.utils import getResolvedOptions
    from pyspark.context import SparkContext
    from awsglue.context import GlueContext
    from awsglue.job import Job

    args = getResolvedOptions(
        sys.argv,
        ["JOB_NAME", "staging_bucket", "bronze_bucket", "silver_bucket", "translation_key"],
    )

    sc = SparkContext()
    glueContext = GlueContext(sc)
    spark = glueContext.spark_session
    job = Job(glueContext)
    job.init(args["JOB_NAME"], args)

    # Transformation entrypoint: reads staging data, lands curated bronze
    # tables and promotes them into the silver Iceberg tables.
    staging_bucket = args["staging_bucket"]
    bronze_bucket = args["bronze_bucket"]
    silver_bucket = args["silver_bucket"]
    translation_key = args["translation_key"]

    print("Transforming data from %s into %s and %s" % (staging_bucket, bronze_bucket, silver_bucket))

    # Transformation logic is provided here so the object is created
    # entirely from the template.

    job.commit()
  EOT

  tags = merge(local.common_tags, {
    Name = "glue-script-transforma-dados"
  })
}

resource "aws_s3_object" "lib_zip" {
  bucket                 = aws_s3_bucket.glue_artefacts.id
  key                    = "scripts/lib.zip"
  server_side_encryption = "aws:kms"
  kms_key_id             = aws_kms_key.datalake.arn
  # Minimal valid (empty) ZIP archive encoded as Base64.
  content_base64 = "UEsFBgAAAAAAAAAAAAAAAAAAAAAAAA=="

  tags = merge(local.common_tags, {
    Name = "glue-lib-zip"
  })
}

