}

# ---------------------------------------------------------------------------
# Computed references used by the IAM policies
# ---------------------------------------------------------------------------

locals {
  s3_bucket_arns = [
    aws_s3_bucket.glue_artefacts.arn,
    aws_s3_bucket.staging.arn,
    aws_s3_bucket.bronze.arn,
    aws_s3_bucket.silver.arn,
    aws_s3_bucket.gold.arn,
    aws_s3_bucket.logs.arn,
  ]

  s3_object_arns = [for arn in local.s3_bucket_arns : "${arn}/*"]

  secret_arns = [
    aws_secretsmanager_secret.api_key.arn,
    aws_secretsmanager_secret.translation_key.arn,
  ]
}

# ---------------------------------------------------------------------------
# IAM role and policy for AWS Glue
# ---------------------------------------------------------------------------

resource "aws_iam_role" "glue" {
  name        = "benchmark-glue-role-${local.name_suffix}"
  description = "Execution role assumed by the benchmark weather data lake Glue jobs."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "glue.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "benchmark-glue-role"
  })
}

resource "aws_iam_role_policy" "glue" {
  name = "benchmark-glue-policy"
  role = aws_iam_role.glue.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "GlueServiceActions"
        Effect = "Allow"
        Action = [
          "glue:CreateJob",
          "glue:UpdateJob",
          "glue:StartJobRun",
          "glue:GetJob",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:GetJobBookmark",
          "glue:ResetJobBookmark",
          "glue:BatchStopJobRun",
          "glue:GetDatabase",
          "glue:GetDatabases",
          "glue:GetTable",
          "glue:GetTables",
          "glue:GetPartition",
          "glue:GetPartitions",
          "glue:CreateTable",
          "glue:UpdateTable",
          "glue:CreateDatabase",
          "glue:BatchCreatePartition",
          "glue:BatchGetPartition",
          "glue:GetCatalogImportStatus",
          "glue:GetConnection",
          "glue:GetDataCatalogEncryptionSettings"
        ]
        Resource = "*"
      },
      {
        Sid    = "CloudWatchLogsAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams",
          "logs:GetLogEvents",
          "logs:AssociateKmsKey"
        ]
        Resource = [
          "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*",
          "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws-glue/*:*"
        ]
      },
      {
        Sid    = "SecretsManagerAccess"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue",
          "secretsmanager:DescribeSecret"
        ]
        Resource = local.secret_arns
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:Encrypt",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = [aws_kms_key.datalake.arn]
      },
      {
        Sid    = "DataLakeBucketListing"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation",
          "s3:ListBucketMultipartUploads"
        ]
        Resource = local.s3_bucket_arns
      },
      {
        Sid    = "DataLakeObjectAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:DeleteObjectVersion",
          "s3:AbortMultipartUpload",
          "s3:ListMultipartUploadParts"
        ]
        Resource = local.s3_object_arns
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Glue jobs
# ---------------------------------------------------------------------------

resource "aws_glue_job" "extrai_dados" {
  name              = "glue-job-extrai-dados-${local.name_suffix}"
  description       = "Extracts raw weather data into the staging bucket."
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    python_version  = "3"
    script_location = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.extrai_dados_script.key}"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.bucket}/tmp/extrai-dados/"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-continuous-log-filter"     = "true"
    "--continuous-log-logGroup"          = "/aws-glue/jobs/extrai-dados"
    "--job-language"                     = "python"
  }

  tags = merge(local.common_tags, {
    Name = "glue-job-extrai-dados"
  })
}

resource "aws_glue_job" "transforma_dados" {
  name              = "glue-job-transforma-dados-${local.name_suffix}"
  description       = "Transforms staged weather data into the bronze and silver Iceberg tables."
  role_arn          = aws_iam_role.glue.arn
  glue_version      = "4.0"
  worker_type       = "G.1X"
  number_of_workers = 20
  max_retries       = 0
  timeout           = 2880

  execution_property {
    max_concurrent_runs = 2
  }

  command {
    name            = "glueetl"
    python_version  = "3"
    script_location = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.transforma_dados_script.key}"
  }

  default_arguments = {
    "--TempDir"                          = "s3://${aws_s3_bucket.logs.bucket}/tmp/transforma-dados/"
    "--datalake-formats"                 = "iceberg"
    "--extra-py-files"                   = "s3://${aws_s3_bucket.glue_artefacts.bucket}/${aws_s3_object.lib_zip.key}"
    "--enable-continuous-cloudwatch-log" = "true"
    "--enable-continuous-log-filter"     = "true"
    "--continuous-log-logGroup"          = "/aws-glue/jobs/transforma-dados"
    "--job-language"                     = "python"
  }

  tags = merge(local.common_tags, {
    Name = "glue-job-transforma-dados"
  })
}

# ---------------------------------------------------------------------------
# IAM role and policy for Step Functions
# ---------------------------------------------------------------------------

resource "aws_iam_role" "sfn" {
  name        = "benchmark-sfn-role-${local.name_suffix}"
  description = "Execution role assumed by the weather data lake Step Functions state machine."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "states.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "benchmark-sfn-role"
  })
}

resource "aws_iam_role_policy" "sfn" {
  name = "benchmark-sfn-policy"
  role = aws_iam_role.sfn.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RunGlueJobs"
        Effect = "Allow"
        Action = [
          "glue:StartJobRun",
          "glue:GetJobRun",
          "glue:GetJobRuns",
          "glue:GetJobRunHistory",
          "glue:BatchStopJobRun"
        ]
        Resource = [
          aws_glue_job.extrai_dados.arn,
          aws_glue_job.transforma_dados.arn
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Step Functions state machine orchestrating the pipeline
# ---------------------------------------------------------------------------

resource "aws_sfn_state_machine" "weather_pipeline" {
  name     = "benchmark-weather-data-lake-pipeline-${local.name_suffix}"
  role_arn = aws_iam_role.sfn.arn
  type     = "STANDARD"

  definition = jsonencode({
    Comment = "Scheduled weather-data lake pipeline: extraction followed by transformation."
    StartAt = "RunExtractionJob"
    States = {
      RunExtractionJob = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.extrai_dados.name
          Arguments = {
            "--city"           = "Sao Paulo"
            "--staging-bucket" = aws_s3_bucket.staging.bucket
            "--api-key"        = "{{resolve:secretsmanager:${aws_secretsmanager_secret.api_key.name}:SecretString:apiKey}}"
          }
        }
        Next = "RunTransformationJob"
      }
      RunTransformationJob = {
        Type     = "Task"
        Resource = "arn:${local.partition}:states:::glue:startJobRun.sync"
        Parameters = {
          JobName = aws_glue_job.transforma_dados.name
          Arguments = {
            "--staging-bucket"  = aws_s3_bucket.staging.bucket
            "--bronze-bucket"   = aws_s3_bucket.bronze.bucket
            "--silver-bucket"   = aws_s3_bucket.silver.bucket
            "--translation-key" = "{{resolve:secretsmanager:${aws_secretsmanager_secret.translation_key.name}:SecretString:translationKey}}"
          }
        }
        End = true
      }
    }
  })

  tags = merge(local.common_tags, {
    Name = "benchmark-weather-data-lake-pipeline"
  })
}

# ---------------------------------------------------------------------------
# EventBridge hourly trigger
# ---------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "hourly" {
  name                = "benchmark-weather-pipeline-hourly-${local.name_suffix}"
  description         = "Triggers the weather data lake Step Functions pipeline every hour."
  schedule_expression = "rate(1 hour)"

  tags = merge(local.common_tags, {
    Name = "benchmark-weather-pipeline-hourly"
  })
}

resource "aws_iam_role" "eventbridge" {
  name        = "benchmark-eventbridge-role-${local.name_suffix}"
  description = "Execution role assumed by EventBridge to start the weather data lake state machine."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "benchmark-eventbridge-role"
  })
}

resource "aws_iam_role_policy" "eventbridge" {
  name = "benchmark-eventbridge-policy"
  role = aws_iam_role.eventbridge.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartWeatherPipeline"
        Effect   = "Allow"
        Action   = ["states:StartExecution"]
        Resource = [aws_sfn_state_machine.weather_pipeline.arn]
      }
    ]
  })
}

resource "aws_cloudwatch_event_target" "weather_pipeline" {
  rule      = aws_cloudwatch_event_rule.hourly.name
  target_id = "benchmark-weather-pipeline"
  arn       = aws_sfn_state_machine.weather_pipeline.arn
  role_arn  = aws_iam_role.eventbridge.arn
}

variable "tags" {
  description = "Tags to apply to all resources"
  type        = map(string)
  default     = {}
}

variable "enable_artifact_bucket_logging" {
  description = "Enable access logging for the artifact bucket"
  type        = bool
  default     = false
}

variable "enable_pipeline_notifications" {
  description = "Enable SNS notifications for pipeline events"
  type        = bool
  default     = false
}

variable "codestar_connection_arn" {
  description = "ARN of CodeStar connection (if using CodeStar instead of GitHub webhook)"
  type        = string
  default     = ""
}

variable "github_owner" {
  description = "GitHub owner (user or organization)"
  type        = string
  default     = "placeholder-owner"
}

variable "github_repo" {
  description = "GitHub repository name"
  type        = string
  default     = "placeholder-repo"
}

variable "github_branch" {
  description = "GitHub branch to trigger pipeline"
  type        = string
  default     = "master"
}

variable "domain_name" {
  description = "Optional custom domain for CloudFront distribution"
  type        = string
  default     = ""
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  common_tags = merge(var.tags, {
    CreatedBy = "Terraform"
  })
  artifact_bucket_name = "benchmark-cicd-artifacts-${local.account_id}-${random_id.suffix.hex}"
  target_bucket_name   = "benchmark-cicd-target-${local.account_id}-${random_id.suffix.hex}"
  cloudfront_origin_access_identity = aws_cloudfront_origin_access_identity.website_oai.cloudfront_access_identity_path
}

data "aws_caller_identity" "current" {}

resource "random_id" "suffix" {
  byte_length = 4
}

# KMS Key
resource "aws_kms_key" "cicd_kms_key" {
  description             = "KMS key for CI/CD bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  tags = merge(local.common_tags, {
    Name = "cicd-kms-key"
  })
}

resource "aws_kms_alias" "cicd_kms_key_alias" {
  name_prefix   = "alias/cicd-kms-key-"
  target_key_id = aws_kms_key.cicd_kms_key.id
}

# Target S3 Bucket
resource "aws_s3_bucket" "target_bucket" {
  bucket        = local.target_bucket_name
  force_destroy = false
  tags = merge(local.common_tags, {
    Name = local.target_bucket_name
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "target_bucket" {
  bucket                  = aws_s3_bucket.target_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "target_bucket" {
  bucket = aws_s3_bucket.target_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "target_bucket" {
  bucket = aws_s3_bucket.target_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Artifact S3 Bucket
resource "aws_s3_bucket" "artifact_bucket" {
  bucket        = local.artifact_bucket_name
  force_destroy = false
  tags = merge(local.common_tags, {
    Name = local.artifact_bucket_name
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_bucket" {
  bucket                  = aws_s3_bucket.artifact_bucket.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_bucket" {
  bucket = aws_s3_bucket.artifact_bucket.id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact_bucket" {
  bucket = aws_s3_bucket.artifact_bucket.id
  versioning_configuration {
    status = "Enabled"
  }
}

# Artifact bucket policy
data "aws_iam_policy_document" "artifact_bucket" {
  statement {
    sid       = "DenyNonTLS"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.artifact_bucket.arn,
      "${aws_s3_bucket.artifact_bucket.arn}/*"
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
    principals {
      type        = "AWS"
      identifiers = ["*"]
    }
  }
  statement {
    sid       = "AllowPipelineAndBuild"
    effect    = "Allow"
    actions   = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:DeleteObject"
    ]
    resources = [
      aws_s3_bucket.artifact_bucket.arn,
      "${aws_s3_bucket.artifact_bucket.arn}/*"
    ]
    principals {
      type        = "AWS"
      identifiers = [
        aws_iam_role.codepipeline_service_role.arn,
        aws_iam_role.codebuild_service_role.arn
      ]
    }
  }
}

resource "aws_s3_bucket_policy" "artifact_bucket" {
  bucket = aws_s3_bucket.artifact_bucket.id
  policy = data.aws_iam_policy_document.artifact_bucket.json
}

# Optional artifact bucket logging
resource "aws_s3_bucket" "artifact_log_bucket" {
  count         = var.enable_artifact_bucket_logging ? 1 : 0
  bucket        = "${local.artifact_bucket_name}-logs"
  force_destroy = false
  tags = merge(local.common_tags, {
    Name = "${local.artifact_bucket_name}-logs"
  })
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifact_log_bucket" {
  count                   = var.enable_artifact_bucket_logging ? 1 : 0
  bucket                  = aws_s3_bucket.artifact_log_bucket[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_log_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_log_bucket[0].id
  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cicd_kms_key.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "artifact_log_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_log_bucket[0].id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "artifact_bucket" {
  count  = var.enable_artifact_bucket_logging ? 1 : 0
  bucket = aws_s3_bucket.artifact_bucket.id
  target_bucket = aws_s3_bucket.artifact_log_bucket[0].id
  target_prefix = "logs/"
}

# CloudFront
resource "aws_cloudfront_origin_access_identity" "website_oai" {
  comment = "OAI for static website"
}

data "aws_iam_policy_document" "target_bucket_cloudfront" {
  statement {
    effect = "Allow"
    actions = ["s3:GetObject"]
    resources = [
      aws_s3_bucket.target_bucket.arn,
      "${aws_s3_bucket.target_bucket.arn}/*"
    ]
    principals {
      type = "AWS"
      identifiers = [aws_cloudfront_origin_access_identity.website_oai.iam_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "target_bucket_cloudfront" {
  bucket = aws_s3_bucket.target_bucket.id
  policy = data.aws_iam_policy_document.target_bucket_cloudfront.json
}

# WAFv2 Web ACL for CloudFront
resource "aws_wafv2_web_acl" "cloudfront_waf" {
  name        = "cloudfront-waf-${random_id.suffix.hex}"
  description = "WAF for CloudFront distribution"
  scope       = "CLOUDFRONT"
  default_action {
    allow {}
  }
  visibility_config {
    cloudwatch_metrics_enabled = false
    metric_name                = "cloudfront-waf-${random_id.suffix.hex}"
    sampled_requests_enabled   = false
  }
  tags = merge(local.common_tags, {
    Name = "cloudfront-waf"
  })
}

resource "aws_cloudfront_distribution" "website_distribution" {
  origin {
    domain_name = aws_s3_bucket.target_bucket.bucket_regional_domain_name
    origin_id   = "s3-${aws_s3_bucket.target_bucket.id}"
    s3_origin_config {
      origin_access_identity = local.cloudfront_origin_access_identity
    }
  }
  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"
  aliases             = var.domain_name != "" ? [var.domain_name] : []
  web_acl_id          = aws_wafv2_web_acl.cloudfront_waf.arn
  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3-${aws_s3_bucket.target_bucket.id}"
    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }
    viewer_protocol_policy = "redirect-to-https"
    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
  }
  price_class = "PriceClass_100"
  viewer_certificate {
    cloudfront_default_certificate = true
  }
  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
  tags = merge(local.common_tags, {
    Name = "website-distribution"
  })
}

# CodeBuild Role and Policy
data "aws_iam_policy_document" "codebuild_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codebuild.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codebuild_service_role" {
  name_prefix        = "CodeBuildServiceRole-"
  assume_role_policy = data.aws_iam_policy_document.codebuild_assume.json
  tags = merge(local.common_tags, {
    Name = "codebuild-service-role"
  })
}

data "aws_iam_policy_document" "codebuild_policy" {
  statement {
    sid    = "Logs"
    effect = "Allow"
    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents"
    ]
    resources = ["*"]
  }
  statement {
    sid    = "S3Target"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.target_bucket.arn,
      "${aws_s3_bucket.target_bucket.arn}/*"
    ]
  }
  statement {
    sid    = "S3Artifact"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket"
    ]
    resources = [
      aws_s3_bucket.artifact_bucket.arn,
      "${aws_s3_bucket.artifact_bucket.arn}/*"
    ]
  }
  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.cicd_kms_key.arn]
  }
  statement {
    sid    = "CloudFront"
    effect = "Allow"
    actions = [
      "cloudfront:CreateInvalidation",
      "cloudfront:GetDistribution"
    ]
    resources = [aws_cloudfront_distribution.website_distribution.arn]
  }
  statement {
    sid    = "SSM"
    effect = "Allow"
    actions = [
      "ssm:GetParameter",
      "ssm:PutParameter"
    ]
    resources = [
      aws_ssm_parameter.github_token.arn,
      aws_ssm_parameter.github_webhook_secret.arn
    ]
  }
}

resource "aws_iam_role_policy" "codebuild_service_role_policy" {
  name   = "CodeBuildServiceRolePolicy"
  role   = aws_iam_role.codebuild_service_role.id
  policy = data.aws_iam_policy_document.codebuild_policy.json
}

resource "aws_codebuild_project" "site_build" {
  name          = "site-build"
  description   = "Builds the static website"
  service_role  = aws_iam_role.codebuild_service_role.arn
  build_timeout = 5

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type = "NO_CACHE"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
    environment_variable {
      name  = "TARGET_BUCKET"
      value = aws_s3_bucket.target_bucket.id
    }
    environment_variable {
      name  = "CLOUDFRONT_DISTRIBUTION_ID"
      value = aws_cloudfront_distribution.website_distribution.id
    }
    environment_variable {
      name  = "INVALIDATION_FLAG"
      value = "true"
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = "buildspec.yml"
  }

  logs_config {
    cloudwatch_logs {
      status = "ENABLED"
    }
  }

  tags = merge(local.common_tags, {
    Name = "site-build"
  })
}

# CodePipeline Role and Policy
data "aws_iam_policy_document" "codepipeline_assume" {
  statement {
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["codepipeline.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "codepipeline_service_role" {
  name_prefix        = "CodePipelineServiceRole-"
  assume_role_policy = data.aws_iam_policy_document.codepipeline_assume.json
  tags = merge(local.common_tags, {
    Name = "codepipeline-service-role"
  })
}

data "aws_iam_policy_document" "codepipeline_policy" {
  statement {
    sid    = "S3Artifact"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.artifact_bucket.arn,
      "${aws_s3_bucket.artifact_bucket.arn}/*"
    ]
  }
  statement {
    sid    = "KMS"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.cicd_kms_key.arn]
  }
  statement {
    sid    = "CodeBuild"
    effect = "Allow"
    actions = [
      "codebuild:StartBuild",
      "codebuild:BatchGetBuilds"
    ]
    resources = [aws_codebuild_project.site_build.arn]
  }
  dynamic "statement" {
    for_each = var.codestar_connection_arn != "" ? [1] : []
    content {
      sid    = "CodeStarConnection"
      effect = "Allow"
      actions = ["codestar-connections:UseConnection"]
      resources = [var.codestar_connection_arn]
    }
  }
}

resource "aws_iam_role_policy" "codepipeline_service_role_policy" {
  name   = "CodePipelineServiceRolePolicy"
  role   = aws_iam_role.codepipeline_service_role.id
  policy = data.aws_iam_policy_document.codepipeline_policy.json
}

# SSM Parameters
resource "aws_ssm_parameter" "github_token" {
  name        = "/github/token-${random_id.suffix.hex}"
  description = "GitHub OAuth token for CodePipeline"
  type        = "SecureString"
  value       = "placeholder-token"
  overwrite   = true
  tags = merge(local.common_tags, {
    Name = "github-token"
  })
}

resource "aws_ssm_parameter" "github_webhook_secret" {
  name        = "/github/webhook-secret-${random_id.suffix.hex}"
  description = "GitHub webhook secret for HMAC authentication"
  type        = "SecureString"
  value       = "placeholder-secret"
  overwrite   = true
  tags = merge(local.common_tags, {
    Name = "github-webhook-secret"
  })
}

# GitHub Webhook (only if not using CodeStar)
resource "aws_codepipeline_webhook" "github_webhook" {
  count           = var.codestar_connection_arn == "" ? 1 : 0
  name            = "github-webhook"
  authentication  = "GITHUB_HMAC"
  target_action   = "Source"
  target_pipeline = aws_codepipeline.main_pipeline.name

  filter {
    json_path    = "$.ref"
    match_equals = "refs/heads/${var.github_branch}"
  }

  authentication_configuration {
    secret_token = aws_ssm_parameter.github_webhook_secret.value
  }

  tags = merge(local.common_tags, {
    Name = "github-webhook"
  })
}

# CodePipeline
locals {
  source_stage = var.codestar_connection_arn != "" ? {
    name     = "Source"
    category = "Source"
    owner    = "AWS"
    provider = "CodeStarSourceConnection"
    version  = "1"
    configuration = {
      ConnectionArn    = var.codestar_connection_arn
      FullRepositoryId = "${var.github_owner}/${var.github_repo}"
      BranchName       = var.github_branch
    }
  } : {
    name     = "Source"
    category = "Source"
    owner    = "ThirdParty"
    provider = "GitHub"
    version  = "1"
    configuration = {
      Owner      = var.github_owner
      Repo       = var.github_repo
      Branch     = var.github_branch
      OAuthToken = aws_ssm_parameter.github_token.value
    }
  }
}

resource "aws_codepipeline" "main_pipeline" {
  name     = "main-pipeline"
  role_arn = aws_iam_role.codepipeline_service_role.arn
  tags = merge(local.common_tags, {
    Name = "main-pipeline"
  })

  artifact_store {
    location = aws_s3_bucket.artifact_bucket.id
    type     = "S3"
    encryption_key {
      id   = aws_kms_key.cicd_kms_key.arn
      type = "KMS"
    }
  }

  stage {
    name = "Source"
    action {
      name             = local.source_stage.name
      category         = local.source_stage.category
      owner            = local.source_stage.owner
      provider         = local.source_stage.provider
      version          = local.source_stage.version
      configuration    = local.source_stage.configuration
      output_artifacts = ["source_output"]
    }
  }

  stage {
    name = "Build"
    action {
      name            = "Build"
      category        = "Build"
      owner           = "AWS"
      provider        = "CodeBuild"
      version         = "1"
      input_artifacts = ["source_output"]
      configuration = {
        ProjectName = aws_codebuild_project.site_build.name
      }
    }
  }
}

# Optional pipeline notifications
resource "aws_sns_topic" "pipeline_notifications" {
  count = var.enable_pipeline_notifications ? 1 : 0
  name  = "pipeline-notifications"
  tags = merge(local.common_tags, {
    Name = "pipeline-notifications"
  })
}

resource "aws_codestarnotifications_notification_rule" "pipeline_notifications" {
  count       = var.enable_pipeline_notifications ? 1 : 0
  name        = "pipeline-notification-rule"
  resource    = aws_codepipeline.main_pipeline.arn
  detail_type = "BASIC"
  event_type_ids = [
    "codepipeline-pipeline-pipeline-execution-failed",
    "codepipeline-pipeline-pipeline-execution-cancelled",
    "codepipeline-pipeline-pipeline-execution-succeeded"
  ]
  target {
    address = aws_sns_topic.pipeline_notifications[0].arn
    type    = "SNS"
  }
  status = "ENABLED"
  tags = merge(local.common_tags, {
    Name = "pipeline-notification-rule"
  })
}

terraform {
  required_version = ">= 1.0, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# Variables
variable "enable_creation" {
  description = "Toggle to enable or disable creation of all resources in this module."
  type        = bool
  default     = true
}

variable "subnet_definitions" {
  description = "List of subnet definitions. Each object: name (string), class (public/private/intra), cidr_block (optional, computed from VPC CIDR if not provided), db_subnet_group (bool, default false), elasticache_subnet_group (bool, default false)."
  type = list(object({
    name                     = string
    class                    = string
    cidr_block               = optional(string)
    db_subnet_group          = optional(bool, false)
    elasticache_subnet_group = optional(bool, false)
  }))
  default = []
}

variable "nat_gateway_mode" {
  description = "NAT gateway mode: 'single' (one NAT gateway in the first public subnet) or 'per_az' (one NAT gateway per availability zone)."
  type        = string
  default     = "single"
  validation {
    condition     = contains(["single", "per_az"], var.nat_gateway_mode)
    error_message = "nat_gateway_mode must be 'single' or 'per_az'."
  }
}

# Data sources
data "aws_availability_zones" "available" {
  state = "available"
}

# Locals
locals {
  azs = data.aws_availability_zones.available.names

  # Determine if any subnet of each class exists
  has_public  = length([for d in var.subnet_definitions : d if d.class == "public"]) > 0
  has_private = length([for d in var.subnet_definitions : d if d.class == "private"]) > 0
  has_intra   = length([for d in var.subnet_definitions : d if d.class == "intra"]) > 0

  # Sets of AZs that have subnets of each class
  public_azs  = toset(flatten([for d in var.subnet_definitions : local.azs if d.class == "public"]))
  private_azs = toset(flatten([for d in var.subnet_definitions : local.azs if d.class == "private"]))
  intra_azs   = toset(flatten([for d in var.subnet_definitions : local.azs if d.class == "intra"]))

  # Compute total number of subnets to allocate CIDR blocks
  total_subnets = length(var.subnet_definitions) * length(local.azs)
  newbits       = max(8, ceil(log(local.total_subnets, 2)) + 4) # ensure at least /24

  # Build a flat list of subnet objects with computed CIDR blocks
  subnet_list = flatten([
    for def_idx, def in var.subnet_definitions : [
      for az_idx, az in local.azs : {
        key        = "${def.name}-${def.class}-${az}"
        name       = def.name
        class      = def.class
        az         = az
        cidr_block = def.cidr_block != null ? def.cidr_block : cidrsubnet(aws_vpc.main[0].cidr_block, local.newbits, def_idx * length(local.azs) + az_idx)
      }
    ]
  ])

  # Map from definition name to list of subnet IDs
  subnet_ids_by_def = {
    for def in var.subnet_definitions : def.name => [
      for s in local.subnet_list : aws_subnet.this[s.key].id if s.name == def.name
    ]
  }

  # Map from AZ to public subnet ID (for NAT gateway attachment)
  public_subnet_ids_by_az = {
    for s in local.subnet_list : s.az => aws_subnet.this[s.key].id if s.class == "public"
  }

  # AZs where NAT gateways will be created (guarded against empty public_azs)
  nat_azs = local.has_public ? (
    var.nat_gateway_mode == "single" ? [element(sort(tolist(local.public_azs)), 0)] : sort(tolist(setintersection(local.public_azs, local.private_azs)))
  ) : []

  # Number of NAT gateways
  nat_gateway_count = var.enable_creation && local.has_private && local.has_public ? (
    var.nat_gateway_mode == "single" ? 1 : length(local.nat_azs)
  ) : 0

  # Map from AZ to NAT gateway ID (for private route tables)
  nat_gateway_id_by_az = {
    for idx, az in local.nat_azs : az => aws_nat_gateway.main[idx].id
  }

  # Subnet group definitions
  db_subnet_group_defs          = { for def in var.subnet_definitions : def.name => def if def.db_subnet_group }
  elasticache_subnet_group_defs = { for def in var.subnet_definitions : def.name => def if def.elasticache_subnet_group }
}

# VPC
resource "aws_vpc" "main" {
  count = var.enable_creation ? 1 : 0

  cidr_block                       = "10.0.0.0/16"
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = false
  assign_generated_ipv6_cidr_block = false

  tags = {
    Name = "main"
  }

  lifecycle {
    prevent_destroy = true
  }
}

# Subnets
resource "aws_subnet" "this" {
  for_each = var.enable_creation && length(var.subnet_definitions) > 0 ? { for s in local.subnet_list : s.key => s } : {}

  vpc_id            = aws_vpc.main[0].id
  cidr_block        = each.value.cidr_block
  availability_zone = each.value.az

  tags = {
    Name = "${each.value.name}-${each.value.class}-${each.value.az}"
  }
}

# Internet Gateway
resource "aws_internet_gateway" "main" {
  count = var.enable_creation && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "main"
  }
}

# Elastic IPs and NAT Gateways
resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = {
    Name = "nat-gateway-${count.index}"
  }
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = local.public_subnet_ids_by_az[local.nat_azs[count.index]]

  tags = {
    Name = "nat-gateway-${count.index}"
  }

  depends_on = [aws_internet_gateway.main]
}

# Route Tables
# Public route table (shared)
resource "aws_route_table" "public" {
  count = var.enable_creation && local.has_public ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = {
    Name = "public"
  }
}

# Private route tables (one per AZ) — only if both private and public subnets exist
resource "aws_route_table" "private" {
  for_each = var.enable_creation && local.has_private && local.has_public ? local.private_azs : toset([])

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = local.nat_gateway_id_by_az[each.key]
  }

  tags = {
    Name = "private-${each.key}"
  }
}

# Intra route tables (one per AZ, no internet route)
resource "aws_route_table" "intra" {
  for_each = var.enable_creation && local.has_intra ? local.intra_azs : toset([])

  vpc_id = aws_vpc.main[0].id

  tags = {
    Name = "intra-${each.key}"
  }
}

# Route table associations
resource "aws_route_table_association" "this" {
  for_each = var.enable_creation && length(var.subnet_definitions) > 0 ? { for s in local.subnet_list : s.key => s } : {}

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = each.value.class == "public" ? aws_route_table.public[0].id : (
    each.value.class == "private" ? aws_route_table.private[each.value.az].id : aws_route_table.intra[each.value.az].id
  )
}

# DB Subnet Groups
resource "aws_db_subnet_group" "this" {
  for_each = var.enable_creation ? local.db_subnet_group_defs : {}

  name        = each.key
  description = "DB subnet group for ${each.key}"
  subnet_ids  = local.subnet_ids_by_def[each.key]

  tags = {
    Name = each.key
  }
}

# ElastiCache Subnet Groups
resource "aws_elasticache_subnet_group" "this" {
  for_each = var.enable_creation ? local.elasticache_subnet_group_defs : {}

  name        = each.key
  description = "ElastiCache subnet group for ${each.key}"
  subnet_ids  = local.subnet_ids_by_def[each.key]

  tags = {
    Name = each.key
  }
}

# Outputs
output "vpc_id" {
  description = "ID of the VPC"
  value       = var.enable_creation ? aws_vpc.main[0].id : null
}

output "subnet_ids_by_definition" {
  description = "Map of definition name to list of subnet IDs"
