}

output "db_subnet_group_arns" {
  description = "Map of definition name to DB subnet group ARN"
  value       = var.enable_creation ? { for k, sg in aws_db_subnet_group.this : k => sg.arn } : {}
}

output "elasticache_subnet_group_names" {
  description = "Map of definition name to ElastiCache subnet group name"
  value       = var.enable_creation ? { for k, sg in aws_elasticache_subnet_group.this : k => sg.name } : {}
}

output "elasticache_subnet_group_arns" {
  description = "Map of definition name to ElastiCache subnet group ARN"
  value       = var.enable_creation ? { for k, sg in aws_elasticache_subnet_group.this : k => sg.arn } : {}
}

