terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  dlq_name = "aggregation-lambda-dead-letter-queue"

  dlq_url = "https://sqs.${data.aws_region.current.name}.amazonaws.com/${data.aws_caller_identity.current.account_id}/${local.dlq_name}"

  common_tags = {
    Name        = "aggregation-lambda-dead-letter-queue"
    ManagedBy   = "terraform"
    Environment = "production"
    Purpose     = "dead-letter-queue"
  }
}

import {
  to = aws_sqs_queue.aggregation_lambda_dead_letter_queue
  id = local.dlq_url
}

data "aws_iam_policy_document" "aggregation_lambda_dlq" {
  statement {
    sid    = "AllowAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:DisableKeyRotation",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription"
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSQSDecryptAndGenerateDataKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sqs.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["sqs.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "aggregation_lambda_dlq" {
  description             = "Customer-managed KMS key used to encrypt the aggregation-lambda-dead-letter-queue SQS dead-letter queue"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_key_policy" "aggregation_lambda_dlq" {
  key_id = aws_kms_key.aggregation_lambda_dlq.id
  policy = data.aws_iam_policy_document.aggregation_lambda_dlq.json
}

resource "aws_sqs_queue" "aggregation_lambda_dead_letter_queue" {
  name = local.dlq_name

  message_retention_seconds         = 1209600
  kms_master_key_id                 = aws_kms_key.aggregation_lambda_dlq.arn
  kms_data_key_reuse_period_seconds = 300

  tags = merge(local.common_tags, { Name = local.dlq_name })

  lifecycle {
    prevent_destroy = true
  }
}

output "dead_letter_queue_arn" {
  description = "ARN of the aggregation Lambda SQS dead-letter queue, for use in Lambda dead_letter_config.target_arn."
  value       = aws_sqs_queue.aggregation_lambda_dead_letter_queue.arn
}

output "dead_letter_queue_url" {
  description = "URL of the aggregation Lambda SQS dead-letter queue."
  value       = aws_sqs_queue.aggregation_lambda_dead_letter_queue.url
}

output "dead_letter_queue_name" {
  description = "Name of the aggregation Lambda SQS dead-letter queue."
  value       = aws_sqs_queue.aggregation_lambda_dead_letter_queue.name
}

output "dead_letter_queue_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for SSE-KMS on the dead-letter queue."
  value       = aws_kms_key.aggregation_lambda_dlq.arn
}

terraform {
