terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

locals {
  log_group_name_prefix = "logs"
  log_group_retention   = 7

  common_tags = {
    ManagedBy = "terraform"
    Purpose   = "cloudwatch-logs-write"
  }
}

resource "random_pet" "log_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "logs" {
  name              = "${local.log_group_name_prefix}-${random_pet.log_suffix.id}"
  retention_in_days = local.log_group_retention
  skip_destroy      = false

  tags = merge(local.common_tags, {
    Name = "${local.log_group_name_prefix}-${random_pet.log_suffix.id}"
  })
}

data "aws_iam_policy_document" "cloudwatch_logs_write" {
  statement {
    sid    = "AllowCloudWatchLogsWriteOnLogGroup"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
    ]

    resources = [
      "${aws_cloudwatch_log_group.logs.arn}:*",
    ]
  }
}

resource "aws_iam_policy" "cloudwatch_logs_write" {
  name        = "cloudwatch-logs-write-${random_pet.log_suffix.id}"
  description = "Allows writing log streams and events to the ${aws_cloudwatch_log_group.logs.name} log group only."
  policy      = data.aws_iam_policy_document.cloudwatch_logs_write.json

  tags = merge(local.common_tags, {
    Name = "cloudwatch-logs-write-${random_pet.log_suffix.id}"
  })
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enable_ssm_automation_logging" {
  description = "When true, creates the SSM Automation script output CloudWatch log group, enables Automation logging to it, and disables public sharing of Systems Manager documents."
  type        = bool
  default     = true
}

locals {
  ssm_automation_log_group_name             = "/aws/ssm/automation/executeScript"
  ssm_automation_logging_setting_id         = "/ssm/automation/customer-script-log-group-name"
  ssm_automation_log_destination_setting_id = "/ssm/automation/customer-script-log-destination"
  ssm_automation_log_destination_value      = "CloudWatch"
  ssm_public_sharing_setting_id             = "/ssm/documents/console/public-sharing-permission"
  ssm_public_sharing_setting_value          = "Disable"
  ssm_resource_tag                          = "ssm-automation-logging"
}

resource "aws_cloudwatch_log_group" "ssm_automation" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  name              = local.ssm_automation_log_group_name
  retention_in_days = 14

  tags = {
    Name      = local.ssm_automation_log_group_name
    Purpose   = local.ssm_resource_tag
    ManagedBy = "terraform"
  }
}

resource "aws_ssm_service_setting" "automation_script_log_destination" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = local.ssm_automation_log_destination_setting_id
  setting_value = local.ssm_automation_log_destination_value
}

resource "aws_ssm_service_setting" "automation_execute_script_logging" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = local.ssm_automation_logging_setting_id
  setting_value = aws_cloudwatch_log_group.ssm_automation[0].name

  depends_on = [
    aws_ssm_service_setting.automation_script_log_destination,
    aws_cloudwatch_log_group.ssm_automation,
  ]
}

resource "aws_ssm_service_setting" "documents_public_sharing" {
  count = var.enable_ssm_automation_logging ? 1 : 0

  setting_id    = local.ssm_public_sharing_setting_id
  setting_value = local.ssm_public_sharing_setting_value
}

output "ssm_automation_log_group_name" {
  description = "Name of the CloudWatch log group receiving SSM Automation script output."
  value       = one(aws_cloudwatch_log_group.ssm_automation[*].name)
}

output "ssm_automation_log_group_arn" {
  description = "ARN of the CloudWatch log group receiving SSM Automation script output."
  value       = one(aws_cloudwatch_log_group.ssm_automation[*].arn)
}

output "ssm_automation_script_log_destination_setting" {
  description = "SSM service setting that routes Automation script logging to CloudWatch."
  value = one([
    for setting in aws_ssm_service_setting.automation_script_log_destination : {
      id    = setting.setting_id
      value = setting.setting_value
      arn   = setting.arn
    }
  ])
}

output "ssm_automation_logging_setting" {
  description = "SSM service setting that points Automation script logging at the CloudWatch log group."
  value = one([
    for setting in aws_ssm_service_setting.automation_execute_script_logging : {
      id    = setting.setting_id
      value = setting.setting_value
      arn   = setting.arn
    }
  ])
}

output "ssm_documents_public_sharing_setting" {
  description = "SSM service setting that controls public sharing of Systems Manager documents."
  value = one([
    for setting in aws_ssm_service_setting.documents_public_sharing : {
      id    = setting.setting_id
      value = setting.setting_value
      arn   = setting.arn
    }
  ])
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "project_name" {
  description = "Non-infrastructure label applied to resources for cost/ownership reporting."
  type        = string
  default     = "ddb-backup-automation"
}

variable "environment" {
  description = "Non-infrastructure environment label applied to resources for cost/ownership reporting."
  type        = string
  default     = "prod"
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  dynamodb_table_arn_pattern  = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*"
  dynamodb_backup_arn_pattern = "arn:${local.partition}:dynamodb:${local.region}:${local.account_id}:table/*/backup/*"

  lambda_log_group_arn_pattern  = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*"
  lambda_log_stream_arn_pattern = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/lambda/*:*"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "create_ddb_backup_role" {
  name                 = "create_ddb_backup_role"
  description          = "Execution role for the Lambda function that creates DynamoDB on-demand backups."
  path                 = "/"
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name                 = "remove_ddb_backup_role"
  description          = "Execution role for the Lambda function that lists and deletes DynamoDB backups."
  path                 = "/"
  assume_role_policy   = data.aws_iam_policy_document.lambda_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

data "aws_iam_policy_document" "create_ddb_backup_policy" {
  statement {
    sid    = "CreateDynamoDBBackups"
    effect = "Allow"

    actions = [
      "dynamodb:CreateBackup",
      "dynamodb:DescribeTable",
      "dynamodb:ListTables",
      "dynamodb:DescribeBackup",
    ]

    resources = [
      local.dynamodb_table_arn_pattern,
      local.dynamodb_backup_arn_pattern,
    ]
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Least-privilege permissions required to create DynamoDB backups for tables in this account."
  path        = "/"
  policy      = data.aws_iam_policy_document.create_ddb_backup_policy.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "remove_ddb_backup_policy" {
  statement {
    sid    = "ListAndDeleteDynamoDBBackups"
    effect = "Allow"

    actions = [
      "dynamodb:ListBackups",
      "dynamodb:DescribeBackup",
      "dynamodb:DeleteBackup",
    ]

    resources = [
      local.dynamodb_table_arn_pattern,
      local.dynamodb_backup_arn_pattern,
    ]
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Least-privilege permissions required to list and delete DynamoDB backups in this account."
  path        = "/"
  policy      = data.aws_iam_policy_document.remove_ddb_backup_policy.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "lambda_logging" {
  statement {
    sid    = "WriteLambdaCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      local.lambda_log_group_arn_pattern,
      local.lambda_log_stream_arn_pattern,
    ]
  }
}

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Shared customer-managed policy granting CloudWatch Logs write permissions for Lambda functions."
  path        = "/"
  policy      = data.aws_iam_policy_document.lambda_logging.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_policy_to_create_ddb_backup_role" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_to_create_ddb_backup_role" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_policy_to_remove_ddb_backup_role" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "lambda_logging_to_remove_ddb_backup_role" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role assumable by Lambda for creating DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumable by Lambda for creating DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role assumable by Lambda for listing and deleting DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role assumable by Lambda for listing and deleting DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "lambda_logging_policy_arn" {
  description = "ARN of the shared customer-managed CloudWatch Logs policy attached to both Lambda execution roles."
  value       = aws_iam_policy.lambda_logging.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# ---------------------------------------------------------------------------
# AWS-managed policy lookups
#
# Every policy attached below is an AWS-managed policy, resolved by name
# through a data source. No policy ARN strings are hardcoded anywhere in this
# configuration, so the template is portable across accounts and partitions.
# ---------------------------------------------------------------------------
data "aws_iam_policy" "administrator_access" {
  name = "AdministratorAccess"
}

data "aws_iam_policy" "read_only_access" {
  name = "ReadOnlyAccess"
}

data "aws_iam_policy" "amazon_s3_full_access" {
  name = "AmazonS3FullAccess"
}

data "aws_iam_policy" "iam_user_change_password" {
  name = "IAMUserChangePassword"
}

# ---------------------------------------------------------------------------
# IAM groups
# ---------------------------------------------------------------------------
resource "aws_iam_group" "admin" {
  name = "admin"
}

resource "aws_iam_group" "admin_read_only" {
  name = "admin_read_only"
}

resource "aws_iam_group" "developer_group" {
  name = "developer_group"
}

# ---------------------------------------------------------------------------
# Policy attachments
#
# The admin group intentionally receives the broad AWS-managed
# AdministratorAccess policy because that is an explicit, signed-off customer
# requirement for the platform administration team. It is a deliberate,
# scoped-by-group exception rather than an oversight.
#
# Every other attachment below is limited strictly to the AWS-managed
# policies requested (ReadOnlyAccess, AmazonS3FullAccess and
# IAMUserChangePassword). No additional inline policies, wildcard policies,
# or customer-managed policies are created or attached by this configuration.
#
# aws_iam_group_policy_attachment is used (never the destructive
# aws_iam_policy_attachment) so the AWS-managed policies remain AWS-managed
# and are attached to the group rather than inlined.
# ---------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "admin_administrator_access" {
  group      = aws_iam_group.admin.name
  policy_arn = data.aws_iam_policy.administrator_access.arn
}

resource "aws_iam_group_policy_attachment" "admin_read_only_read_only_access" {
  group      = aws_iam_group.admin_read_only.name
  policy_arn = data.aws_iam_policy.read_only_access.arn
}

resource "aws_iam_group_policy_attachment" "developer_group_amazon_s3_full_access" {
  group      = aws_iam_group.developer_group.name
  policy_arn = data.aws_iam_policy.amazon_s3_full_access.arn
}

resource "aws_iam_group_policy_attachment" "developer_group_iam_user_change_password" {
  group      = aws_iam_group.developer_group.name
  policy_arn = data.aws_iam_policy.iam_user_change_password.arn
}

# ---------------------------------------------------------------------------
# Group memberships
#
# Each membership resource is created up front with an empty `users` list so
# the team structures exist immediately after apply. Future members are added
# by declaring aws_iam_user resources in this same file and referencing their
# names in the list below - never by hardcoding user names or ARNs that live
# outside this configuration.
# ---------------------------------------------------------------------------
resource "aws_iam_group_membership" "admin_team" {
  name  = "admin_team"
  group = aws_iam_group.admin.name
  users = []
}

resource "aws_iam_group_membership" "read_only_admin_team" {
  name  = "read_only_admin_team"
  group = aws_iam_group.admin_read_only.name
  users = []
}

resource "aws_iam_group_membership" "developers" {
  name  = "developers"
  group = aws_iam_group.developer_group.name
  users = []
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "tls" {}

###############################################################################
# Locals
###############################################################################

locals {
  github_oidc_url      = "https://token.actions.githubusercontent.com"
  github_oidc_audience = "sts.amazonaws.com"

  # Combine the live CA SHA-1 fingerprints from the issuer TLS chain with
  # GitHub's two published thumbprints, de-duplicated for determinism.
  github_oidc_thumbprints = distinct(concat(
    [for certificate in data.tls_certificate.github.certificates : certificate.sha1_fingerprint],
    var.github_thumbprints,
  ))

  # Flatten per-role managed policy attachments into a single keyed map so the
  # attachment resources can use for_each (stable keys, no count).
  role_managed_policy_attachments = merge([
    for role_key, role in var.github_roles : {
      for policy_arn in role.managed_policy_arns :
      "${role_key}::${policy_arn}" => {
        role_key   = role_key
        policy_arn = policy_arn
      }
    }
  ]...)

  # Flatten per-role inline policies into a single keyed map.
  role_inline_policies = merge([
    for role_key, role in var.github_roles : {
      for policy_name, policy_document in role.inline_policies :
      "${role_key}::${policy_name}" => {
        role_key        = role_key
        policy_name     = policy_name
        policy_document = policy_document
      }
    }
  ]...)
}

###############################################################################
# Variables
###############################################################################

variable "github_thumbprints" {
  description = <<-EOT
    GitHub's published OIDC thumbprints. These are merged with the CA
    fingerprints read from the live token.actions.githubusercontent.com TLS
    chain so the resulting thumbprint list is deterministic and overridable.
  EOT
  type        = list(string)
  default = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  validation {
    condition     = length(var.github_thumbprints) > 0 && alltrue([for t in var.github_thumbprints : can(regex("^[0-9a-fA-F]{40}$", t))])
    error_message = "Each github_thumbprints entry must be a 40-character hexadecimal SHA-1 fingerprint."
  }
}

variable "github_roles" {
  description = <<-EOT
    Optional GitHub-federated IAM roles. Empty by default, so no roles are
    created unless entries are explicitly supplied. Each entry maps to a single
    aws_iam_role whose trust policy is scoped to the given repository (and
    subject patterns) via the OIDC provider created by this configuration.
  EOT
  type = map(object({
    role_name           = string
    repository          = string
    subject_patterns    = optional(list(string), ["*"])
    managed_policy_arns = optional(list(string), [])
    inline_policies     = optional(map(string), {})
    max_session_seconds = optional(number, 3600)
    tags                = optional(map(string), {})
  }))
  default = {}

  validation {
    condition = alltrue([
      for role_key, role in var.github_roles :
      can(regex("^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$", role.repository))
    ])
    error_message = "Each github_roles entry must set repository to \"<org>/<repo>\"."
  }

  validation {
    condition = alltrue([
      for role_key, role in var.github_roles :
      length(role.role_name) > 0 && length(role.subject_patterns) > 0
    ])
    error_message = "Each github_roles entry must have a non-empty role_name and at least one subject pattern."
  }

  validation {
    condition = alltrue([
      for role_key, role in var.github_roles :
      role.max_session_seconds >= 3600 && role.max_session_seconds <= 43200
    ])
    error_message = "max_session_seconds must be between 3600 and 43200."
  }

  validation {
    condition = alltrue([
      for role_key, role in var.github_roles : alltrue([
        for arn in role.managed_policy_arns : can(regex("^arn:aws[a-zA-Z-]*:iam::[0-9]{12}:policy/", arn))
      ])
    ])
    error_message = "managed_policy_arns entries must be valid IAM policy ARNs."
  }
}

###############################################################################
# Data sources
###############################################################################

data "tls_certificate" "github" {
  url = local.github_oidc_url
}

###############################################################################
# GitHub Actions OIDC identity provider
###############################################################################

resource "aws_iam_openid_connect_provider" "github" {
  url             = local.github_oidc_url
  client_id_list  = [local.github_oidc_audience]
  thumbprint_list = local.github_oidc_thumbprints

  tags = {
    Name = "github-actions-oidc"
  }
}

###############################################################################
# Optional GitHub-federated IAM roles (none created by default)
###############################################################################

data "aws_iam_policy_document" "github_assume_role" {
  for_each = var.github_roles

  statement {
    sid     = "AllowGitHubActionsAssumeRoleWithWebIdentity"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = [local.github_oidc_audience]
    }

    condition {
      test     = "StringLike"
      variable = "token.actions.githubusercontent.com:sub"
      values = [
        for pattern in each.value.subject_patterns :
        "repo:${each.value.repository}:${pattern}"
      ]
    }
  }
}

resource "aws_iam_role" "github" {
  for_each = var.github_roles

  name                 = each.value.role_name
  description          = "GitHub Actions federated role for ${each.value.repository}"
  assume_role_policy   = data.aws_iam_policy_document.github_assume_role[each.key].json
  max_session_duration = each.value.max_session_seconds

  tags = merge(
    {
      Name       = each.value.role_name
      Repository = each.value.repository
      ManagedBy  = "terraform"
    },
    each.value.tags,
  )
}

resource "aws_iam_role_policy_attachment" "github" {
  for_each = local.role_managed_policy_attachments

  role       = aws_iam_role.github[each.value.role_key].name
  policy_arn = each.value.policy_arn
}

resource "aws_iam_role_policy" "github" {
  for_each = local.role_inline_policies

  name   = each.value.policy_name
  role   = aws_iam_role.github[each.value.role_key].id
  policy = each.value.policy_document
}

###############################################################################
# Outputs
###############################################################################

output "oidc_provider_arn" {
  description = "ARN of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.arn
}

output "oidc_provider_url" {
  description = "URL (issuer) of the GitHub Actions IAM OIDC identity provider."
  value       = aws_iam_openid_connect_provider.github.url
}

output "oidc_provider_thumbprints" {
  description = "Combined thumbprint list configured on the OIDC provider."
  value       = aws_iam_openid_connect_provider.github.thumbprint_list
}

output "github_role_arns" {
  description = "Map of GitHub-federated role keys to their ARNs (empty unless roles are supplied)."
  value       = { for role_key, role in aws_iam_role.github : role_key => role.arn }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  project = "projectvpc"

  azs = data.aws_availability_zones.available.names

  common_tags = {
    Project = local.project
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.project
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = local.azs[1]

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-subnet"
    Tier = "private"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-public-rt"
    Tier = "public"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.project}-nat-eip"
  })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = "${local.project}-nat-gateway"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.project}-private-rt"
    Tier = "private"
  })
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.3.0"

