  vpc_id = aws_vpc.dev.id

  tags = merge(local.common_tags, {
    Name        = "dev-private-rt"
    Environment = "dev"
    Tier        = "private"
  })
}

################################################################################
# Route Tables - test
################################################################################

resource "aws_route_table" "test_public" {
  vpc_id = aws_vpc.test.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.test.id
  }

  tags = merge(local.common_tags, {
    Name        = "test-public-rt"
    Environment = "test"
    Tier        = "public"
  })
}

resource "aws_route_table" "test_private" {
  vpc_id = aws_vpc.test.id

  tags = merge(local.common_tags, {
    Name        = "test-private-rt"
    Environment = "test"
    Tier        = "private"
  })
}

################################################################################
# Route Table Associations - dev
################################################################################

resource "aws_route_table_association" "dev_public_1" {
  subnet_id      = aws_subnet.dev_public_1.id
  route_table_id = aws_route_table.dev_public.id
}

resource "aws_route_table_association" "dev_public_2" {
  subnet_id      = aws_subnet.dev_public_2.id
  route_table_id = aws_route_table.dev_public.id
}

resource "aws_route_table_association" "dev_private_1" {
  subnet_id      = aws_subnet.dev_private_1.id
  route_table_id = aws_route_table.dev_private.id
}

resource "aws_route_table_association" "dev_private_2" {
  subnet_id      = aws_subnet.dev_private_2.id
  route_table_id = aws_route_table.dev_private.id
}

################################################################################
# Route Table Associations - test
################################################################################

resource "aws_route_table_association" "test_public_1" {
  subnet_id      = aws_subnet.test_public_1.id
  route_table_id = aws_route_table.test_public.id
}

resource "aws_route_table_association" "test_public_2" {
  subnet_id      = aws_subnet.test_public_2.id
  route_table_id = aws_route_table.test_public.id
}

resource "aws_route_table_association" "test_private_1" {
  subnet_id      = aws_subnet.test_private_1.id
  route_table_id = aws_route_table.test_private.id
}

resource "aws_route_table_association" "test_private_2" {
  subnet_id      = aws_subnet.test_private_2.id
  route_table_id = aws_route_table.test_private.id
}

################################################################################
# VPC Peering
################################################################################

resource "aws_vpc_peering_connection" "dev_test" {
  vpc_id      = aws_vpc.dev.id
  peer_vpc_id = aws_vpc.test.id
  auto_accept = true

  accepter {
    allow_remote_vpc_dns_resolution = true
  }

  requester {
    allow_remote_vpc_dns_resolution = true
  }

  tags = merge(local.common_tags, {
    Name = "dev-test-vpc-peer"
  })
}

################################################################################
# Peer Routes - dev
################################################################################

resource "aws_route" "dev_public_to_test" {
  route_table_id            = aws_route_table.dev_public.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "dev_private_to_test" {
  route_table_id            = aws_route_table.dev_private.id
  destination_cidr_block    = aws_vpc.test.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

################################################################################
# Peer Routes - test
################################################################################

resource "aws_route" "test_public_to_dev" {
  route_table_id            = aws_route_table.test_public.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
  vpc_peering_connection_id = aws_vpc_peering_connection.dev_test.id
}

resource "aws_route" "test_private_to_dev" {
  route_table_id            = aws_route_table.test_private.id
  destination_cidr_block    = aws_vpc.dev.cidr_block
