terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  role_names = {
    test-role  = aws_iam_role.test_role.name
    test-role2 = aws_iam_role.test_role2.name
  }

  ec2_describe_actions = [
    "ec2:DescribeInstances",
    "ec2:DescribeImages",
    "ec2:DescribeVolumes",
    "ec2:DescribeSnapshots",
    "ec2:DescribeSecurityGroups",
    "ec2:DescribeSubnets",
    "ec2:DescribeVpcs",
  ]

  common_tags = {
    ManagedBy = "terraform"
    Purpose   = "iam-testing"
  }
}

###############################################################################
# Assume role policy document (shared by both roles)
###############################################################################

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    sid     = "AllowEC2AssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

###############################################################################
# IAM roles
###############################################################################

resource "aws_iam_role" "test_role" {
  name               = "test-role"
  description        = "Test role assumable by EC2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "test-role"
  })
}

resource "aws_iam_role" "test_role2" {
  name               = "test-role2"
  description        = "Second test role assumable by EC2"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "test-role2"
  })
}

###############################################################################
# EC2 describe-only policy document (shared by all three policies)
###############################################################################

data "aws_iam_policy_document" "ec2_describe_only" {
  statement {
    sid       = "AllowEC2DescribeOnly"
    effect    = "Allow"
    actions   = local.ec2_describe_actions
    resources = ["*"]
  }
}

###############################################################################
# Customer managed policies
###############################################################################

resource "aws_iam_policy" "test_policy" {
  name        = "test-policy"
  description = "Allows EC2 describe actions only"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = merge(local.common_tags, {
    Name = "test-policy"
  })
}

resource "aws_iam_policy" "test_policy2" {
  name        = "test-policy2"
  description = "Allows EC2 describe actions only"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = merge(local.common_tags, {
    Name = "test-policy2"
  })
}

resource "aws_iam_policy" "test_policy3" {
  name        = "test-policy3"
  description = "Allows EC2 describe actions only"
  policy      = data.aws_iam_policy_document.ec2_describe_only.json

  tags = merge(local.common_tags, {
    Name = "test-policy3"
  })
}

###############################################################################
# Individual attachments: test-policy and test-policy2 to both roles
###############################################################################

resource "aws_iam_role_policy_attachment" "test_policy_to_test_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_policy_to_test_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy.arn
}

resource "aws_iam_role_policy_attachment" "test_policy2_to_test_role" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

resource "aws_iam_role_policy_attachment" "test_policy2_to_test_role2" {
  role       = aws_iam_role.test_role2.name
  policy_arn = aws_iam_policy.test_policy2.arn
}

###############################################################################
# Single named attachment (test-attachment5) applying test-policy3 to both roles
###############################################################################

resource "aws_iam_role_policy_attachment" "test_attachment5" {
  for_each = local.role_names

  role       = each.value
  policy_arn = aws_iam_policy.test_policy3.arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

variable "tags" {
  type        = map(string)
  description = "Tags to apply to the CloudHealth IAM role and policy."

  default = {
    Name      = "CloudHealth-IAM-Role"
    Purpose   = "CloudHealth cost analysis"
    ManagedBy = "terraform"
  }
}

resource "random_password" "external_id" {
  length  = 32
  special = false
  upper   = true
  lower   = true
  numeric = true

  keepers = {
    rotation_epoch = "1"
  }
}

resource "aws_secretsmanager_secret" "cloudhealth_external_id" {
  name_prefix             = "CloudHealth-IAM-Role-"
  description             = "External ID used by the CloudHealth SaaS platform to assume the CloudHealth-IAM-Role cross-account role."
  recovery_window_in_days = 0

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "cloudhealth_external_id" {
  secret_id     = aws_secretsmanager_secret.cloudhealth_external_id.id
  secret_string = random_password.external_id.result
}

data "aws_iam_policy_document" "assume_role_policy" {
  statement {
    sid     = "AllowCloudHealthAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [random_password.external_id.result]
    }
  }
}

data "aws_iam_policy_document" "cloudhealth_policy" {
  statement {
    sid     = "CostExplorerRead"
    effect  = "Allow"
    actions = [
      "ce:Describe*",
      "ce:Get*",
      "ce:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "OrganizationsRead"
    effect  = "Allow"
    actions = [
      "organizations:Describe*",
      "organizations:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "TagRead"
    effect  = "Allow"
    actions = [
      "tag:Get*",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "ComputeDatabaseNetworkDescribeList"
    effect  = "Allow"
    actions = [
      "autoscaling:Describe*",
      "ec2:Describe*",
      "elasticloadbalancing:Describe*",
      "rds:Describe*",
      "dynamodb:Describe*",
      "dynamodb:List*",
      "lambda:List*",
      "sns:List*",
      "sqs:List*",
      "cloudwatch:Describe*",
      "cloudwatch:List*",
      "logs:Describe*",
      "logs:List*",
      "route53:List*",
      "s3:ListAllMyBuckets",
      "iam:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "CloudWatchMetricsRead"
    effect  = "Allow"
    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:GetDashboard",
      "cloudwatch:GetInsightRuleReport",
      "cloudwatch:ListTagsForResource",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "IAMRead"
    effect  = "Allow"
    actions = [
      "iam:Get*",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "S3AccountRead"
    effect  = "Allow"
    actions = [
      "s3:GetAccountPublicAccessBlock",
    ]
    resources = ["*"]
  }

  statement {
    sid     = "S3BucketRead"
    effect  = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:GetBucketCORS",
      "s3:GetBucketLocation",
      "s3:GetBucketLogging",
      "s3:GetBucketNotification",
      "s3:GetBucketPolicy",
      "s3:GetBucketRequestPayment",
      "s3:GetBucketTagging",
      "s3:GetBucketVersioning",
      "s3:GetBucketWebsite",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:ListBucketVersions",
    ]
    resources = ["arn:aws:s3:::*"]
  }

  statement {
    sid     = "S3ObjectRead"
    effect  = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:GetObjectTagging",
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["arn:aws:s3:::*/*"]
  }

  statement {
    sid     = "DynamoDBTableRead"
    effect  = "Allow"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeContributorInsights",
      "dynamodb:DescribeBackup",
      "dynamodb:DescribeGlobalTable",
      "dynamodb:DescribeGlobalTableSettings",
      "dynamodb:DescribeTableReplicaAutoScaling",
      "dynamodb:ListTagsOfResource",
    ]
    resources = ["arn:aws:dynamodb:*:*:*"]
  }

  statement {
    sid     = "LambdaRead"
    effect  = "Allow"
    actions = [
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetPolicy",
      "lambda:GetAlias",
      "lambda:GetEventSourceMapping",
      "lambda:GetFunctionCodeSigningConfig",
      "lambda:ListTags",
    ]
    resources = ["arn:aws:lambda:*:*:function:*"]
  }

  statement {
    sid     = "SNSRead"
    effect  = "Allow"
    actions = [
      "sns:GetTopicAttributes",
      "sns:GetSubscriptionAttributes",
      "sns:ListTagsForResource",
    ]
    resources = ["arn:aws:sns:*:*:*"]
  }

  statement {
    sid     = "SQSRead"
    effect  = "Allow"
    actions = [
      "sqs:GetQueueAttributes",
      "sqs:ListQueueTags",
    ]
    resources = ["arn:aws:sqs:*:*:*"]
  }

  statement {
    sid     = "LogsRead"
    effect  = "Allow"
    actions = [
      "logs:GetLogEvents",
      "logs:GetLogGroupFields",
      "logs:GetQueryResults",
      "logs:FilterLogEvents",
      "logs:ListTagsLogGroup",
    ]
    resources = ["arn:aws:logs:*:*:log-group:*"]
  }

  statement {
    sid     = "Route53Read"
    effect  = "Allow"
    actions = [
      "route53:GetHostedZone",
      "route53:GetHostedZoneCount",
      "route53:GetHealthCheck",
      "route53:GetCheckerIpRanges",
      "route53:ListTagsForResource",
    ]
    resources = [
      "arn:aws:route53:::hostedzone/*",
      "arn:aws:route53:::healthcheck/*",
    ]
  }

  statement {
    sid     = "RDSTagsRead"
    effect  = "Allow"
    actions = [
      "rds:ListTagsForResource",
    ]
    resources = ["arn:aws:rds:*:*:*"]
  }

  statement {
    sid     = "EC2ResourceRead"
    effect  = "Allow"
    actions = [
      "ec2:GetConsoleOutput",
      "ec2:GetConsoleScreenshot",
      "ec2:GetPasswordData",
    ]
    resources = ["arn:aws:ec2:*:*:instance/*"]
  }

  statement {
    sid     = "CostAndUsageReportRead"
    effect  = "Allow"
    actions = [
      "cur:DescribeReportDefinitions",
      "cur:GetClassicReport",
      "cur:GetClassicReportPreferences",
      "cur:GetUsageReport",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_role" "cloudhealth_iam_role" {
  name_prefix          = "CloudHealth-IAM-Role-"
  description          = "Cross-account role for the CloudHealth SaaS platform to perform read-only cost and usage analysis across AWS services."
  assume_role_policy   = data.aws_iam_policy_document.assume_role_policy.json
  max_session_duration = 3600

  tags = var.tags
}

resource "aws_iam_policy" "cloudhealth_iam_policy" {
  name_prefix = "CloudHealth-IAM-Role-"
  description = "Customer-managed read-only policy for CloudHealth cost and usage analysis across AWS services."
  policy      = data.aws_iam_policy_document.cloudhealth_policy.json

  tags = var.tags
}

resource "aws_iam_role_policy_attachment" "cloudhealth_attach" {
  role       = aws_iam_role.cloudhealth_iam_role.name
  policy_arn = aws_iam_policy.cloudhealth_iam_policy.arn
}

output "cloudhealth_iam_role_arn" {
  description = "ARN of the CloudHealth cross-account IAM role."
  value       = aws_iam_role.cloudhealth_iam_role.arn
}

output "cloudhealth_iam_role_name" {
  description = "Name of the CloudHealth cross-account IAM role."
  value       = aws_iam_role.cloudhealth_iam_role.name
}

output "cloudhealth_iam_policy_arn" {
  description = "ARN of the customer-managed CloudHealth read-only IAM policy."
  value       = aws_iam_policy.cloudhealth_iam_policy.arn
}

output "cloudhealth_external_id_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the generated external ID for CloudHealth role assumption. Retrieve the value out-of-band (e.g. aws secretsmanager get-secret-value)."
  value       = aws_secretsmanager_secret.cloudhealth_external_id.arn
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "role_name" {
  description = "Name of the IAM role that GitHub Actions assumes through OIDC web identity federation."
  type        = string
  default     = "github-actions-oidc-role"
}

variable "github_repositories" {
  description = "List of GitHub Actions OIDC subject patterns allowed to assume the role (e.g. \"repo:my-org/my-repo:ref:refs/heads/main\"). Empty by default so no repository is trusted until patterns are supplied."
  type        = list(string)
  default     = []
}

variable "managed_policy_arns" {
  description = "List of AWS managed policy ARNs to attach to the role. Empty by default so no managed policies are attached."
  type        = list(string)
  default     = []
}

variable "inline_policy_statements" {
  description = "Optional list of least-privilege inline policy statements to add to the role. Empty by default so no inline policy is created."
  type = list(object({
    actions   = list(string)
    resources = list(string)
  }))
  default = []
}

variable "tags" {
  description = "Additional tags to apply to the resources created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  github_oidc_url      = "https://token.actions.githubusercontent.com"
  github_oidc_host     = "token.actions.githubusercontent.com"
  github_oidc_audience = "sts.amazonaws.com"

  # Thumbprints of the root CA certificates that sign the GitHub Actions OIDC
  # provider certificates.
  github_oidc_thumbprints = [
    "6938fd4d98bab03faadb97b34396831e3780aea1",
    "1c58a3a8518e8759bf075b76b750d4f2df264fcd",
  ]

  github_oidc_audience_condition_key = "${local.github_oidc_host}:aud"
  github_oidc_issuer_condition_key   = "${local.github_oidc_host}:iss"
  github_oidc_subject_condition_key  = "${local.github_oidc_host}:sub"

  # Deterministic, non-matching subject pattern used when no repository patterns
  # are configured. It keeps the trust policy valid while granting no access.
  github_no_match_subject = "repo:none/none:ref:refs/heads/none"

  github_subject_patterns = length(var.github_repositories) > 0 ? var.github_repositories : [local.github_no_match_subject]
  github_single_pattern   = length(local.github_subject_patterns) == 1

  # A single supplied pattern is matched exactly with StringEquals.
  github_string_equals_conditions = merge(
    {
      (local.github_oidc_audience_condition_key) = [local.github_oidc_audience]
      (local.github_oidc_issuer_condition_key)   = [local.github_oidc_url]
    },
    {
      for key, value in { (local.github_oidc_subject_condition_key) = local.github_subject_patterns } : key => value
      if local.github_single_pattern
    },
  )

  # Multiple supplied patterns are matched with StringLike (no wildcard fallback).
  github_string_like_conditions = {
    for key, value in { (local.github_oidc_subject_condition_key) = local.github_subject_patterns } : key => value
    if !local.github_single_pattern
  }

  github_web_identity_condition = merge(
    {
      "StringEquals" = local.github_string_equals_conditions
    },
    {
      for operator, conditions in { "StringLike" = local.github_string_like_conditions } : operator => conditions
      if !local.github_single_pattern
    },
  )

  github_actions_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowGitHubActionsWebIdentityFederation"
        Effect = "Allow"
        Principal = {
          Federated = aws_iam_openid_connect_provider.github_actions.arn
        }
        Action    = "sts:AssumeRoleWithWebIdentity"
        Condition = local.github_web_identity_condition
      },
    ]
  })

  tags = merge(
    {
      Name      = var.role_name
      ManagedBy = "Terraform"
      Component = "github-actions-oidc"
    },
    var.tags,
  )
}

###############################################################################
# GitHub Actions OIDC identity provider
###############################################################################

resource "aws_iam_openid_connect_provider" "github_actions" {
  url             = local.github_oidc_url
  client_id_list  = [local.github_oidc_audience]
  thumbprint_list = local.github_oidc_thumbprints

  tags = local.tags
}

###############################################################################
# IAM role for GitHub Actions
###############################################################################

resource "aws_iam_role" "github_actions" {
  name                  = var.role_name
  path                  = "/"
  description           = "IAM role assumed by GitHub Actions workflows through OpenID Connect web identity federation."
  assume_role_policy    = local.github_actions_assume_role_policy
  force_detach_policies = true

  tags = local.tags
}

###############################################################################
# Managed policy attachments (only what the caller explicitly supplies)
###############################################################################

resource "aws_iam_role_policy_attachment" "managed" {
  for_each = toset(var.managed_policy_arns)

  role       = aws_iam_role.github_actions.name
  policy_arn = each.value
}

###############################################################################
# Optional least-privilege inline policy (created only when statements exist)
###############################################################################

resource "aws_iam_role_policy" "inline" {
  count = length(var.inline_policy_statements) > 0 ? 1 : 0

  name = "${var.role_name}-inline"
  role = aws_iam_role.github_actions.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      for statement in var.inline_policy_statements : {
        Effect   = "Allow"
        Action   = statement.actions
        Resource = statement.resources
      }
    ]
  })
}

###############################################################################
# Outputs
###############################################################################

output "role_arn" {
  description = "ARN of the IAM role that GitHub Actions assumes via OIDC web identity federation."
  value       = aws_iam_role.github_actions.arn
}

output "role_name" {
  description = "Name of the IAM role that GitHub Actions assumes via OIDC web identity federation."
  value       = aws_iam_role.github_actions.name
}

output "role_path" {
  description = "Path of the IAM role that GitHub Actions assumes via OIDC web identity federation."
  value       = aws_iam_role.github_actions.path
}

output "role_unique_id" {
  description = "Stable unique identifier of the IAM role that GitHub Actions assumes via OIDC web identity federation."
  value       = aws_iam_role.github_actions.unique_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Additional tags to apply to the managed force-MFA IAM policy."
  type        = map(string)

  default = {
    Project   = "force-mfa"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id

  common_tags = {
    Project     = "force-mfa"
    ManagedBy   = "terraform"
    Environment = "shared-services"
  }

  tags = merge(local.common_tags, var.tags)
}

data "aws_iam_policy_document" "force_mfa" {
  version = "2012-10-17"

  statement {
    sid    = "AllowListActions"
    effect = "Allow"

    actions = [
      "iam:ListVirtualMFADevices",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowUserToCreateVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
    ]

    resources = [
      "arn:aws:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${local.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowUserToDeactivateVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:DeactivateMFADevice",
    ]

    resources = [
      "arn:aws:iam::${local.account_id}:mfa/$${aws:username}",
      "arn:aws:iam::${local.account_id}:user/$${aws:username}",
    ]
  }

  statement {
    sid    = "AllowUserToSeePasswordPolicyInformation"
    effect = "Allow"

    actions = [
      "iam:GetAccountPasswordPolicy",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowUserToChangeOwnPassword"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowBasicSelfInspection"
    effect = "Allow"

    actions = [
      "iam:GetUser",
      "iam:ListUsers",
      "iam:ListMFADevices",
      "iam:ListAccountAliases",
      "iam:GetAccountSummary",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "DenyMostAccessUnlessSignedInWithMFA"
    effect = "Deny"

    not_actions = [
      "iam:CreateVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ResyncMFADevice",
      "iam:DeactivateMFADevice",
      "iam:ListVirtualMFADevices",
      "iam:ListMFADevices",
      "iam:ChangePassword",
      "iam:GetUser",
      "iam:ListUsers",
      "iam:GetAccountPasswordPolicy",
      "iam:GetAccountSummary",
      "iam:ListAccountAliases",
    ]

    resources = ["*"]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "managed_force_mfa_policy" {
  name        = "managed-force-mfa-policy"
  path        = "/"
  description = "Customer-managed policy that enforces MFA: allows IAM users to view basic account information and manage their own password and virtual MFA device, permits MFA deactivation only for the caller's own MFA/user ARNs, and denies broader access unless the session is MFA-authenticated."

  policy = data.aws_iam_policy_document.force_mfa.json

  tags = local.tags
}

output "managed_force_mfa_policy_arn" {
  description = "ARN of the customer-managed force-MFA IAM policy."
  value       = aws_iam_policy.managed_force_mfa_policy.arn
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# Random passwords for console login
resource "random_password" "billing_password" {
  length           = 8
  special          = true
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "admin_password" {
  length           = 8
  special          = true
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

resource "random_password" "suport_password" {
  length           = 8
  special          = true
  min_special      = 1
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# IAM Groups
resource "aws_iam_group" "billing_group" {
  name = "BillingGroup"
}

resource "aws_iam_group" "admin_group" {
  name = "AdminGroup"
}

resource "aws_iam_group" "suport_group" {
  name = "SuportGroup"
}

# IAM Users
resource "aws_iam_user" "billing_user" {
  name = "Billing"
}

resource "aws_iam_user" "admin_user" {
  name = "Admin"
}

resource "aws_iam_user" "suport_user" {
  name = "Suport"
}

# Console login profiles
resource "aws_iam_user_login_profile" "billing_login" {
  user                    = aws_iam_user.billing_user.name
  password_reset_required = true
  password_length         = 8
}

resource "aws_iam_user_login_profile" "admin_login" {
  user                    = aws_iam_user.admin_user.name
  password_reset_required = true
  password_length         = 8
}

resource "aws_iam_user_login_profile" "suport_login" {
  user                    = aws_iam_user.suport_user.name
  password_reset_required = true
  password_length         = 8
}

# Group memberships
resource "aws_iam_group_membership" "billing_membership" {
  name  = "billing-membership"
  group = aws_iam_group.billing_group.name
  users = [aws_iam_user.billing_user.name]
}

resource "aws_iam_group_membership" "admin_membership" {
  name  = "admin-membership"
  group = aws_iam_group.admin_group.name
  users = [aws_iam_user.admin_user.name]
}

resource "aws_iam_group_membership" "suport_membership" {
  name  = "suport-membership"
  group = aws_iam_group.suport_group.name
  users = [aws_iam_user.suport_user.name]
}

# Custom policies
resource "aws_iam_policy" "billing_policy" {
  name        = "BillingPolicy"
  description = "Read-only billing, usage, budget, cost, and pricing visibility"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "aws-portal:ViewBilling",
          "aws-portal:ViewUsage",
          "aws-portal:ViewPaymentMethods",
          "aws-portal:ViewAccount",
          "budgets:ViewBudget",
          "budgets:DescribeBudgetAction",
          "ce:DescribeReport",
          "ce:GetCostAndUsage",
          "pricing:GetProducts",
          "pricing:GetAttributeValues"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy" "suport_policy" {
  name        = "SuportPolicy"
  description = "Read-only access to EC2, S3, CloudWatch, and RDS"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "ec2:List*",
          "s3:Describe*",
          "s3:Get*",
          "s3:List*",
          "cloudwatch:Describe*",
          "cloudwatch:Get*",
          "cloudwatch:List*",
          "rds:Describe*",
          "rds:Get*",
          "rds:List*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Policy attachments
resource "aws_iam_group_policy_attachment" "billing_attach" {
  group      = aws_iam_group.billing_group.name
  policy_arn = aws_iam_policy.billing_policy.arn
}

resource "aws_iam_group_policy_attachment" "admin_attach" {
  group      = aws_iam_group.admin_group.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_group_policy_attachment" "suport_attach" {
  group      = aws_iam_group.suport_group.name
  policy_arn = aws_iam_policy.suport_policy.arn
}

# Outputs
output "billing_username" {
  value = aws_iam_user.billing_user.name
}

output "billing_password" {
  value     = random_password.billing_password.result
  sensitive = true
}

output "admin_username" {
  value = aws_iam_user.admin_user.name
}

output "admin_password" {
  value     = random_password.admin_password.result
  sensitive = true
}

output "suport_username" {
  value = aws_iam_user.suport_user.name
}

output "suport_password" {
  value     = random_password.suport_password.result
  sensitive = true
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

resource "aws_efs_file_system" "shared_storage" {
  encrypted        = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_backup_policy" "shared_storage" {
  file_system_id = aws_efs_file_system.shared_storage.id

  backup_policy {
    status = "ENABLED"
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  project     = "nlp-pipeline"
  environment = "dev"

  common_tags = {
    Project     = "nlp-pipeline"
    Environment = "dev"
    ManagedBy   = "terraform"
  }

  account_id     = data.aws_caller_identity.current.account_id
  aws_region     = data.aws_region.current.name
  aws_partition  = "aws"
  state_bucket   = "my-terraform-state-bucket-${data.aws_caller_identity.current.account_id}"

  nlp_pipeline_bucket_arn         = "arn:aws:s3:::nlp-pipeline-bucket"
  nlp_pipeline_bucket_objects_arn = "arn:aws:s3:::nlp-pipeline-bucket/*"

  nlp_results_table_arn = "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/NLPResults"

  state_machine_arn = "arn:aws:states:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:stateMachine:YourStateMachineName"

  lambda_functions_arn = "arn:aws:lambda:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:function:*"

  glue_jobs_arn = "arn:aws:glue:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:job/*"

  # Reusable least-privilege policy document for S3 object read/write access
  # against the nlp-pipeline-bucket (bucket-scoped ARNs only).
  s3_object_access_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowListBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          local.nlp_pipeline_bucket_arn
        ]
      },
      {
        Sid    = "AllowObjectReadWrite"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          local.nlp_pipeline_bucket_objects_arn
        ]
      }
    ]
  })
}

############################################################################
# Terraform remote state storage
############################################################################

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed KMS key for Terraform remote state encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountFullAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3ServiceUseOfKey"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:Decrypt"
        ]
        Resource = "*"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_s3_bucket" "terraform_state" {
  bucket        = local.state_bucket
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.terraform_state.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_dynamodb_table" "terraform_locks" {
  name         = "terraform-locks"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

############################################################################
# AWS Glue service role
############################################################################

data "aws_iam_policy_document" "glue_assume_role" {
  statement {
    sid     = "AllowGlueAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["glue.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "glue_service_role" {
  name               = "glue-service-role"
  description        = "Service role assumed by AWS Glue jobs in the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.glue_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "glue_service_role_managed" {
  role       = aws_iam_role.glue_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSGlueServiceRole"
}

resource "aws_iam_role_policy" "glue_service_role_s3" {
  name   = "glue-service-role-s3-object-access"
  role   = aws_iam_role.glue_service_role.id
  policy = local.s3_object_access_policy
}

############################################################################
# Amazon Comprehend service role
############################################################################

data "aws_iam_policy_document" "comprehend_assume_role" {
  statement {
    sid     = "AllowComprehendAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["comprehend.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "comprehend_service_role" {
  name               = "comprehend-service-role"
  description        = "Service role assumed by Amazon Comprehend in the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.comprehend_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy" "comprehend_service_role_s3" {
  name   = "comprehend-service-role-s3-object-access"
  role   = aws_iam_role.comprehend_service_role.id
  policy = local.s3_object_access_policy
}

############################################################################
# AWS Lambda execution role
############################################################################

data "aws_iam_policy_document" "lambda_assume_role" {
  statement {
    sid     = "AllowLambdaAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name               = "lambda-execution-role"
  description        = "Execution role for Lambda functions in the NLP data pipeline"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_execution_role_managed" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "aws_iam_policy_document" "lambda_execution_role_inline" {
  statement {
    sid    = "AllowNlpPipelineBucketList"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation"
    ]
    resources = [
      local.nlp_pipeline_bucket_arn
    ]
  }

  statement {
    sid    = "AllowNlpPipelineBucketObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = [
      local.nlp_pipeline_bucket_objects_arn
    ]
  }

  statement {
    sid    = "AllowNlpResultsTableWrite"
    effect = "Allow"
    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:UpdateItem"
    ]
    resources = [
      local.nlp_results_table_arn
    ]
  }

  statement {
    sid       = "AllowStartNlpStateMachine"
    effect    = "Allow"
    actions   = ["states:StartExecution"]
    resources = [local.state_machine_arn]
  }
}

resource "aws_iam_role_policy" "lambda_execution_role_inline" {
  name   = "lambda-execution-role-nlp-pipeline-access"
  role   = aws_iam_role.lambda_execution_role.id
  policy = data.aws_iam_policy_document.lambda_execution_role_inline.json
}

############################################################################
# AWS Step Functions service role
############################################################################

data "aws_iam_policy_document" "step_functions_assume_role" {
  statement {
    sid     = "AllowStepFunctionsAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["states.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "step_functions_service_role" {
  name               = "step-functions-service-role"
  description        = "Service role assumed by the NLP pipeline Step Functions state machine"
  assume_role_policy = data.aws_iam_policy_document.step_functions_assume_role.json

  tags = local.common_tags
}

data "aws_iam_policy_document" "step_functions_service_role_inline" {
  statement {
    sid       = "AllowInvokeLambdaFunctions"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = [local.lambda_functions_arn]
  }

  statement {
    sid     = "AllowStartGlueJobRuns"
    effect  = "Allow"
    actions = ["glue:StartJobRun"]
    resources = [
      local.glue_jobs_arn
    ]
  }

  statement {
    sid    = "AllowReadGlueJobRuns"
    effect = "Allow"
    actions = [
      "glue:GetJobRun",
      "glue:GetJobRuns",
      "glue:BatchStopJobRun",
      "glue:GetJob",
      "glue:GetJobBookmark"
    ]
    resources = [
      local.glue_jobs_arn
    ]
  }
}

resource "aws_iam_role_policy" "step_functions_service_role_inline" {
  name   = "step-functions-service-role-orchestration-access"
  role   = aws_iam_role.step_functions_service_role.id
  policy = data.aws_iam_policy_document.step_functions_service_role_inline.json
}

###############################################################################
# NOTE: The `provider "aws"` block is intentionally omitted. The deployment
# harness injects the provider configuration (region/credentials); a backend
# block is likewise managed externally.
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

###############################################################################
# Static / account metadata lookups (no pre-existing infrastructure queried)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name

  # Tagging convention applied to every taggable resource. Declared once so the
  # convention cannot be omitted on an individual resource.
  common_tags = {
    managedBy   = "terraform"
    application = "demo"
  }

  # Bucket name must be lowercase and globally unique; derived from the live
  # AWS account ID.
  artifact_bucket_name = "demo-artifact-store-${local.account_id}"

  ecr_repository_name = "zenml-kubernetes"
}

###############################################################################
# Customer-managed KMS key used for the artifact store's default encryption
###############################################################################

resource "aws_kms_key" "artifact_store" {
  description             = "Customer-managed KMS key for the ZenML demo S3 artifact store"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = local.artifact_bucket_name
  })
}

# NOTE: aws_kms_alias does not expose a `tags` argument in the AWS provider, so
# the managedBy/application convention is carried by the KMS key above.
resource "aws_kms_alias" "artifact_store" {
  name          = "alias/demo-artifact-store"
  target_key_id = aws_kms_key.artifact_store.key_id
}

###############################################################################
# S3 artifact store bucket
###############################################################################

# NOTE / documented deviation from the standard stateful-resource policy:
# `lifecycle { prevent_destroy = true }` is intentionally OMITTED on this
# bucket because `force_destroy = true` was explicitly requested. Combining the
# two would generate a conflicting, self-contradicting plan, so force_destroy
# takes precedence for this demo artifact store.
resource "aws_s3_bucket" "artifact_store" {
  bucket        = local.artifact_bucket_name
  force_destroy = true

  tags = merge(local.common_tags, {
    Name = local.artifact_bucket_name
  })
}

# Bucket-owner-preferred object ownership (replaces the deprecated ACL resource).
resource "aws_s3_bucket_ownership_controls" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

# Private access is enforced via public-access-block + ownership controls;
# the deprecated `aws_s3_bucket_acl` resource is deliberately NOT declared.
resource "aws_s3_bucket_public_access_block" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default SSE-KMS encryption using the new customer-managed key (no hardcoded ARN).
resource "aws_s3_bucket_server_side_encryption_configuration" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifact_store.arn
    }

    bucket_key_enabled = true
  }
}

# Artifact stores are stateful: versioning protects artifact history.
resource "aws_s3_bucket_versioning" "artifact_store" {
  bucket = aws_s3_bucket.artifact_store.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# ECR repository for ZenML container images
###############################################################################

resource "aws_ecr_repository" "zenml_kubernetes" {
  name                 = local.ecr_repository_name
  image_tag_mutability = "IMMUTABLE"

  image_scanning_configuration {
    scan_on_push = true
  }

  tags = merge(local.common_tags, {
    Name = local.ecr_repository_name
  })
}

###############################################################################
# Generated ZenML stack definition (local file)
###############################################################################

resource "local_file" "zenml_stack" {
  filename        = "${path.module}/zenml_stack.yaml"
  file_permission = "0644"

  # Contains NO secret values or credentials - only references to the AWS
  # resources created by this configuration.
  content = <<-EOT
    zenml_version: "0.12.0"

    artifact_store:
      flavor: s3
      name: demo-artifact-store
      path: s3://${aws_s3_bucket.artifact_store.bucket}
      config:
        path: s3://${aws_s3_bucket.artifact_store.bucket}
        region_name: ${data.aws_region.current.name}

    container_registry:
      flavor: aws
      name: zenml-kubernetes
      uri: ${aws_ecr_repository.zenml_kubernetes.repository_url}
      config:
        uri: ${aws_ecr_repository.zenml_kubernetes.repository_url}
        region_name: ${data.aws_region.current.name}

    secrets_manager:
      flavor: aws
      name: demo-secrets-manager
      config:
        region_name: ${data.aws_region.current.name}
    EOT
}

locals {
  name_prefix = "nim"
}

resource "aws_iam_role" "task_execution" {
  name = "${local.name_prefix}-ecs_task_execution-"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "task_execution_managed" {
  role       = aws_iam_role.task_execution.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

resource "aws_secretsmanager_secret" "reposecret" {
  name = "${local.name_prefix}-reposecret-"
}

resource "aws_secretsmanager_secret_version" "reposecret" {
  secret_id     = aws_secretsmanager_secret.reposecret.id
  secret_string = jsonencode({
    username = "AWS"
    password = ""
  })
}

resource "aws_iam_role_policy" "ecs_task_access_secrets" {
  name   = "ECSTaskAccessSecretsPolicy"
  role   = aws_iam_role.task_execution.id
