    Version = "2012-10-17"
    Statement = [
      {
        Action   = "secretsmanager:GetSecretValue"
        Effect   = "Allow"
        Resource = aws_secretsmanager_secret.reposecret.arn
      }
    ]
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Inputs
###############################################################################

variable "organizational_units" {
  description = <<-EOT
    Optional list of slash-delimited organizational unit paths, nesting up to
    five levels deep from the organization root (for example
    "Platform/Networking/Prod" creates Platform > Networking > Prod).
    Defaults to an empty list, which creates no organizational units.
  EOT
  type        = list(string)
  default     = []
}

###############################################################################
# Locals: normalise the supplied paths and derive one entry per OU to create
###############################################################################

locals {
  # Trim whitespace from each segment of every supplied path and drop empty
  # segments (e.g. " A / /B/ " becomes ["A", "B"]).
  path_segments = {
    for path in var.organizational_units :
    path => [
      for segment in split("/", path) : trimspace(segment)
      if trimspace(segment) != ""
    ]
  }

  # Re-join the cleaned segments and drop duplicates / empty paths.
  normalized_paths = distinct([
    for path, segments in local.path_segments :
    join("/", segments)
    if length(segments) > 0
  ])

  # Expand every normalised path into its ancestor prefixes. Each prefix is a
  # single organizational unit with its level and fully-qualified parent path.
  path_items = flatten([
    for path in local.normalized_paths : [
      for index, segment in split("/", path) : {
        path        = join("/", slice(split("/", path), 0, index + 1))
        name        = segment
        level       = index + 1
        parent_path = index == 0 ? null : join("/", slice(split("/", path), 0, index))
      }
    ]
  ])

  # Keying by path deduplicates OUs that are shared by several supplied paths.
  ou_items = { for item in local.path_items : item.path => item }

  ou_level1 = { for path, item in local.ou_items : path => item if item.level == 1 }
  ou_level2 = { for path, item in local.ou_items : path => item if item.level == 2 }
  ou_level3 = { for path, item in local.ou_items : path => item if item.level == 3 }
  ou_level4 = { for path, item in local.ou_items : path => item if item.level == 4 }
  ou_level5 = { for path, item in local.ou_items : path => item if item.level == 5 }
}

###############################################################################
# Organization with all features and the required policy types enabled
###############################################################################

resource "aws_organizations_organization" "main" {
  feature_set = "ALL"

  enabled_policy_types = [
    "AISERVICES_OPT_OUT_POLICY",
    "BACKUP_POLICY",
    "SERVICE_CONTROL_POLICY",
    "TAG_POLICY",
  ]
}

###############################################################################
# Level 1 organizational units (children of the organization root)
###############################################################################

resource "aws_organizations_organizational_unit" "level1" {
  for_each = local.ou_level1

  name      = each.value.name
  parent_id = aws_organizations_organization.main.roots[0].id
}

###############################################################################
# Level 2 organizational units (children of the matching level 1 OU)
###############################################################################

resource "aws_organizations_organizational_unit" "level2" {
  for_each = local.ou_level2

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level1[each.value.parent_path].id
}

###############################################################################
# Level 3 organizational units (children of the matching level 2 OU)
###############################################################################

resource "aws_organizations_organizational_unit" "level3" {
  for_each = local.ou_level3

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level2[each.value.parent_path].id
}

###############################################################################
# Level 4 organizational units (children of the matching level 3 OU)
###############################################################################

resource "aws_organizations_organizational_unit" "level4" {
  for_each = local.ou_level4

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level3[each.value.parent_path].id
}

###############################################################################
# Level 5 organizational units (children of the matching level 4 OU)
###############################################################################

resource "aws_organizations_organizational_unit" "level5" {
  for_each = local.ou_level5

  name      = each.value.name
  parent_id = aws_organizations_organizational_unit.level4[each.value.parent_path].id
}

