  default_network_acl_id = aws_vpc.swe_vpc.default_network_acl_id

  ingress {
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_vpc.swe_vpc.cidr_block
    from_port  = 0
    to_port    = 0
    protocol   = "-1"
  }

  ingress {
    rule_no    = 200
    action     = "deny"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
    protocol   = "tcp"
