# ---------------------------------------------------------------------------------------------------------------------
# INPUT VARIABLES
# ---------------------------------------------------------------------------------------------------------------------
variable "namespace" {
  description = "Namespace for Cloud Posse label (e.g., org or company name)"
  type        = string
  default     = "eg"
}

variable "environment" {
  description = "Environment name (e.g., dev, staging, prod)"
  type        = string
  default     = "dev"
}

variable "stage" {
  description = "Stage name (e.g., build, test, deploy)"
  type        = string
  default     = "test"
}

variable "name" {
  description = "Name of the application or component"
  type        = string
  default     = "guardduty"
}

variable "attributes" {
  description = "Additional attributes for the label (e.g., list of strings)"
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags (map of strings)"
  type        = map(string)
  default     = {}
}

variable "enable_finding_notifications" {
  description = "Set to true to create SNS topic and EventBridge rule for GuardDuty findings"
  type        = bool
  default     = false
}

# ---------------------------------------------------------------------------------------------------------------------
# CLOUD POSSE LABEL
# ---------------------------------------------------------------------------------------------------------------------
module "label" {
  source     = "cloudposse/label/null"
  version    = "0.25.0"

  namespace  = var.namespace
  environment = var.environment
  stage      = var.stage
  name       = var.name
  attributes = var.attributes
  tags       = var.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# GUARDDUTY DETECTOR
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_guardduty_detector" "this" {
  enable = true

  datasources {
    s3_logs {
      enable = false
    }
  }

  tags = module.label.tags
}

# ---------------------------------------------------------------------------------------------------------------------
# OPTIONAL SNS TOPIC AND EVENTBRIDGE RULE FOR FINDINGS
# ---------------------------------------------------------------------------------------------------------------------
resource "aws_sns_topic" "this" {
  count = var.enable_finding_notifications ? 1 : 0

  name              = module.label.id
  kms_master_key_id = "alias/aws/sns"  # AWS managed key

  tags = module.label.tags
}

resource "aws_sns_topic_policy" "this" {
  count = var.enable_finding_notifications ? 1 : 0

  arn = aws_sns_topic.this[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowEventsServiceToPublish"
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action   = "sns:Publish"
        Resource = aws_sns_topic.this[0].arn
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "guardduty_findings" {
  count = var.enable_finding_notifications ? 1 : 0

  name        = "${module.label.id}-guardduty-findings"
  description = "Capture all GuardDuty findings"

  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })

  tags = module.label.tags
}

resource "aws_cloudwatch_event_target" "guardduty_findings_to_sns" {
  count = var.enable_finding_notifications ? 1 : 0

  rule      = aws_cloudwatch_event_rule.guardduty_findings[0].name
  target_id = "SendToSNS"
  arn       = aws_sns_topic.this[0].arn
}

# Random suffix for resource names
resource "random_string" "suffix" {
  length  = 6
  special = false
  upper   = false
  lower   = true
  numeric = true
}

locals {
  prefix = "sudo-backup-${random_string.suffix.result}"
}

# KMS key for backup vault encryption
resource "aws_kms_key" "backup_key" {
  description             = "${local.prefix} backup vault encryption key"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy = data.aws_iam_policy_document.kms_key_policy.json

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowBackupRoleEncryptionDecryption"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.backup_role.arn]
    }
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey"
    ]
    resources = ["*"]
  }
}

data "aws_caller_identity" "current" {}

# Backup vault
resource "aws_backup_vault" "backup_vault" {
  name        = "${local.prefix}-backup-vault"
  kms_key_arn = aws_kms_key.backup_key.arn

  lifecycle {
    prevent_destroy = true
  }
}

# Backup plan
resource "aws_backup_plan" "backup_plan" {
  name = "${local.prefix}-backup-plan"

  rule {
    rule_name         = "${local.prefix}-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 12 * * ? *)"

    recovery_point_tags = {
      Name = local.prefix
    }
  }
}

# IAM role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "${local.prefix}-backup-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

# Attach the AWS managed backup service role policy
resource "aws_iam_role_policy_attachment" "backup_role_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

# Backup selection
resource "aws_backup_selection" "backup_selection" {
  name         = "${local.prefix}-backup-selection"
  plan_id      = aws_backup_plan.backup_plan.id
  iam_role_arn = aws_iam_role.backup_role.arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "backup"
    value = "true"
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

# Cognito User Pool
resource "aws_cognito_user_pool" "coop_tweets" {
  name = "coop-tweets"

  admin_create_user_config {
    allow_admin_create_user_only = true
  }

  password_policy {
    minimum_length    = 6
    require_numbers   = true
    require_uppercase = true
    require_symbols   = true
  }
}

# Cognito User Pool Domain
resource "aws_cognito_user_pool_domain" "coop_tweets_domain" {
  domain       = "coop-tweets-domain"
  user_pool_id = aws_cognito_user_pool.coop_tweets.id
}

# Cognito Identity Pool
resource "aws_cognito_identity_pool" "coop_tweets" {
  identity_pool_name               = "coop tweets"
  allow_unauthenticated_identities = false
}

# IAM Role for Authenticated Identities
resource "aws_iam_role" "cognito_auth_role" {
  name = "coop-tweets_cognito_auth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      }
    ]
  })
}

# IAM Role for Unauthenticated Identities
resource "aws_iam_role" "cognito_unauth_role" {
  name = "coop-tweets_cognito_unauth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.coop_tweets.id
          }
        }
      }
    ]
  })
}

# Customer-managed policy for Authenticated Role
resource "aws_iam_policy" "cognito_kibana_auth" {
  name        = "cognito_kibana_auth_coop-tweets"
  description = "Policy for authenticated Cognito identities"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach policy to auth role
resource "aws_iam_role_policy_attachment" "auth_attachment" {
  role       = aws_iam_role.cognito_auth_role.name
  policy_arn = aws_iam_policy.cognito_kibana_auth.arn
}

# Customer-managed policy for Unauthenticated Role
resource "aws_iam_policy" "cognito_kibana_unauth" {
  name        = "cognito_kibana_unauth_coop-tweets"
  description = "Policy for unauthenticated Cognito identities"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "mobileanalytics:PutEvents",
          "cognito-sync:*",
          "cognito-identity:*"
        ]
        Resource = "*"
      }
    ]
  })
}

# Attach policy to unauth role
resource "aws_iam_role_policy_attachment" "unauth_attachment" {
  role       = aws_iam_role.cognito_unauth_role.name
  policy_arn = aws_iam_policy.cognito_kibana_unauth.arn
}

# Identity Pool Roles Attachment
resource "aws_cognito_identity_pool_roles_attachment" "coop_tweets" {
  identity_pool_id = aws_cognito_identity_pool.coop_tweets.id

  roles = {
    "authenticated"   = aws_iam_role.cognito_auth_role.arn
    "unauthenticated" = aws_iam_role.cognito_unauth_role.arn
  }
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "enable_s3_export" {
  type        = bool
  default     = false
  description = "If true, enables optional GuardDuty findings export to an S3 bucket."
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "guardduty_kms" {
  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }
  statement {
    sid    = "AllowGuardDutyToUseKey"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
    actions = [
      "kms:GenerateDataKey",
      "kms:Decrypt"
    ]
    resources = ["*"]
  }
}

resource "aws_kms_key" "guardduty" {
  description             = "KMS key for GuardDuty findings encryption"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.guardduty_kms.json
}

resource "aws_kms_alias" "guardduty" {
  name          = "alias/guardduty"
  target_key_id = aws_kms_key.guardduty.id
}

resource "aws_guardduty_detector" "main" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"
}

resource "aws_cloudwatch_event_rule" "guardduty_finding_events" {
  name        = "guardduty-finding-events"
  description = "Matches GuardDuty Finding events"
  event_pattern = jsonencode({
    source      = ["aws.guardduty"]
    detail-type = ["GuardDuty Finding"]
  })
}

# Conditional S3 export resources
resource "aws_s3_bucket" "findings_export" {
  count         = var.enable_s3_export ? 1 : 0
  bucket        = "guardduty-findings-export-${data.aws_caller_identity.current.account_id}"
  force_destroy = false

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings_export" {
  count                  = var.enable_s3_export ? 1 : 0
  bucket                 = aws_s3_bucket.findings_export[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_export" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "guardduty_s3" {
  count = var.enable_s3_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyToPutObjects"
    effect = "Allow"
    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
    actions = [
      "s3:PutObject",
      "s3:GetBucketLocation"
    ]
    resources = [
      aws_s3_bucket.findings_export[0].arn,
      "${aws_s3_bucket.findings_export[0].arn}/*"
    ]
  }
}

resource "aws_s3_bucket_policy" "findings_export" {
  count  = var.enable_s3_export ? 1 : 0
  bucket = aws_s3_bucket.findings_export[0].id
  policy = data.aws_iam_policy_document.guardduty_s3[0].json
}

resource "aws_guardduty_publishing_destination" "s3" {
  count           = var.enable_s3_export ? 1 : 0
  detector_id     = aws_guardduty_detector.main.id
  destination_arn = aws_s3_bucket.findings_export[0].arn
  kms_key_arn     = aws_kms_key.guardduty.arn
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "bucket_prefix" {
  type    = string
  default = "private-bucket-"
}

resource "aws_kms_key" "this" {
  description             = "S3 bucket encryption key"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "this" {
  bucket_prefix = var.bucket_prefix
  force_destroy = true
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = "Disabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

# ------------------------------------------------------------------------------
# IAM Roles
# ------------------------------------------------------------------------------
resource "aws_iam_role" "billing_full_access" {
  name               = "billing-full-access"
  assume_role_policy = data.aws_iam_policy_document.billing_full_access_trust.json
}

resource "aws_iam_role" "billing_view_access" {
  name               = "billing-view-access"
  assume_role_policy = data.aws_iam_policy_document.billing_view_access_trust.json
}

data "aws_iam_policy_document" "billing_full_access_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "billing_view_access_trust" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

# ------------------------------------------------------------------------------
# Customer Managed Policies (Permissions)
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "billing_full_access" {
  name        = "billing-full-access"
  description = "Full access to AWS Billing and Cost Management console"
  policy      = data.aws_iam_policy_document.billing_full_access_permissions.json
}

data "aws_iam_policy_document" "billing_full_access_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:*",
      "aws-billing-console:*",
      "budgets:*",
      "purchase-orders:*",
      "tax:*",
      "account:*",
      "ce:*",
      "cur:*",
      "freetier:*",
      "invoicing:*",
      "payments:*",
      "pricing:*",
      "support:*",
      "usage-profiles:*"
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "billing_view_access" {
  name        = "billing-view-access"
  description = "View-only access to AWS Billing and Cost Management console"
  policy      = data.aws_iam_policy_document.billing_view_access_permissions.json
}

data "aws_iam_policy_document" "billing_view_access_permissions" {
  statement {
    effect = "Allow"
    actions = [
      "aws-portal:View*",
      "aws-portal:Get*",
      "aws-portal:Describe*",
      "aws-portal:List*",
      "aws-billing-console:View*",
      "aws-billing-console:Get*",
      "aws-billing-console:Describe*",
      "aws-billing-console:List*",
      "budgets:View*",
      "budgets:Get*",
      "budgets:Describe*",
      "budgets:List*",
      "purchase-orders:View*",
      "purchase-orders:Get*",
      "purchase-orders:Describe*",
      "purchase-orders:List*",
      "tax:View*",
      "tax:Get*",
      "tax:Describe*",
      "tax:List*",
      "account:Get*",
      "account:List*",
      "ce:Get*",
      "ce:List*",
      "ce:Describe*",
      "cur:Get*",
      "cur:Describe*",
      "freetier:Get*",
      "invoicing:Get*",
      "invoicing:List*",
      "payments:Get*",
      "payments:List*",
      "pricing:Get*",
      "pricing:Describe*",
      "pricing:List*",
      "support:Get*",
      "support:Describe*",
      "usage-profiles:Get*",
      "usage-profiles:List*"
    ]
    resources = ["*"]
  }
}

# ------------------------------------------------------------------------------
# Attach Policies to Roles
# ------------------------------------------------------------------------------
resource "aws_iam_role_policy_attachment" "billing_full_access" {
  role       = aws_iam_role.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access.arn
}

resource "aws_iam_role_policy_attachment" "billing_view_access" {
  role       = aws_iam_role.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access.arn
}

# ------------------------------------------------------------------------------
# IAM Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group" "billing_full_access" {
  name = "billing-full-access"
  path = "/"
}

resource "aws_iam_group" "billing_view_access" {
  name = "billing-view-access"
  path = "/"
}

# ------------------------------------------------------------------------------
# Assume Role Policies for Groups
# ------------------------------------------------------------------------------
resource "aws_iam_policy" "billing_full_access_assume_role" {
  name        = "billing-full-access-assume-role"
  description = "Allows members of billing-full-access group to assume the billing-full-access role"
  policy      = data.aws_iam_policy_document.billing_full_access_assume_role.json
}

data "aws_iam_policy_document" "billing_full_access_assume_role" {
  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_full_access.arn]
  }
}

resource "aws_iam_policy" "billing_view_access_assume_role" {
  name        = "billing-view-access-assume-role"
  description = "Allows members of billing-view-access group to assume the billing-view-access role"
  policy      = data.aws_iam_policy_document.billing_view_access_assume_role.json
}

data "aws_iam_policy_document" "billing_view_access_assume_role" {
  statement {
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.billing_view_access.arn]
  }
}

# ------------------------------------------------------------------------------
# Attach Assume Role Policies to Groups
# ------------------------------------------------------------------------------
resource "aws_iam_group_policy_attachment" "billing_full_access" {
  group      = aws_iam_group.billing_full_access.name
  policy_arn = aws_iam_policy.billing_full_access_assume_role.arn
}

resource "aws_iam_group_policy_attachment" "billing_view_access" {
  group      = aws_iam_group.billing_view_access.name
  policy_arn = aws_iam_policy.billing_view_access_assume_role.arn
}

# ------------------------------------------------------------------------------
# Outputs
# ------------------------------------------------------------------------------
output "billing_full_access_role_arn" {
  value = aws_iam_role.billing_full_access.arn
}

output "billing_view_access_role_arn" {
  value = aws_iam_role.billing_view_access.arn
}

output "billing_full_access_group_arn" {
  value = aws_iam_group.billing_full_access.arn
}

output "billing_view_access_group_arn" {
  value = aws_iam_group.billing_view_access.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# ---------------------------------------------------------------------------
# Helper lookups: current partition, region, and account ID. These static
# provider metadata values are used to build every ARN in this configuration.
# ---------------------------------------------------------------------------
data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id
}

# ---------------------------------------------------------------------------
# Random naming / secrets
# ---------------------------------------------------------------------------
resource "random_pet" "suffix" {
  separator = "-"
  length    = 2
}

locals {
  base_name      = "cognito-${random_pet.suffix.id}"
  user_pool_name = replace(local.base_name, "-", "_")
}

resource "random_string" "sms_external_id" {
  length  = 16
  upper   = true
  lower   = false
  numeric = true
  special = false

  lifecycle {
    ignore_changes = []
  }
}

# ---------------------------------------------------------------------------
# User pool
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool" "main" {
  name                     = local.user_pool_name
  mfa_configuration        = "OFF"
  auto_verified_attributes = ["email"]

  schema {
    name                     = "email"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = true

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "phone_number"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = false
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "profile_user_id"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "first_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "last_name"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "gender"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "age"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  schema {
    name                     = "persona"
    attribute_data_type      = "String"
    developer_only_attribute = false
    mutable                  = true
    required                 = false

    string_attribute_constraints {
      min_length = 1
      max_length = 2048
    }
  }

  sms_configuration {
    external_id    = random_string.sms_external_id.result
    sns_caller_arn = aws_iam_role.cognito_sms.arn
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# IAM role Cognito assumes to deliver SMS through SNS
# ---------------------------------------------------------------------------
resource "aws_iam_role" "cognito_sms" {
  name = "${local.base_name}-sms-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoSmsAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cognito-idp.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "sts:ExternalId" = random_string.sms_external_id.result
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "cognito_sms" {
  name = "${local.base_name}-sms-policy"
  role = aws_iam_role.cognito_sms.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishSmsToSns"
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = "*"
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# User pool app client (no client secret)
# ---------------------------------------------------------------------------
resource "aws_cognito_user_pool_client" "main" {
  name            = local.base_name
  user_pool_id    = aws_cognito_user_pool.main.id
  generate_secret = false
}

# ---------------------------------------------------------------------------
# Identity pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = local.base_name
  allow_unauthenticated_identities = true

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.main.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = false
  }

  lifecycle {
    prevent_destroy = true
  }
}

# ---------------------------------------------------------------------------
# Authenticated (signed-in) users role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "signed_users" {
  name = "${local.base_name}-signed-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoAuthenticatedAssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
            "cognito-identity.amazonaws.com:amr" = "authenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "signed_users" {
  name = "${local.base_name}-signed-users-policy"
  role = aws_iam_role.signed_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoIdentityAccess"
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:GetCredentialsForIdentity"
        ]
        Resource = [
          "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
        ]
      },
      {
        Sid    = "CognitoSyncAccess"
        Effect = "Allow"
        Action = [
          "cognito-sync:ListRecords",
          "cognito-sync:UpdateRecords"
        ]
        Resource = [
          "arn:${local.partition}:cognito-sync:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}/*"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Unauthenticated (anonymous) users role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "anonymous_users" {
  name = "${local.base_name}-anonymous-users"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoUnauthenticatedAssumeRoleWithWebIdentity"
        Effect = "Allow"
        Principal = {
          Federated = "cognito-identity.amazonaws.com"
        }
        Action = "sts:AssumeRoleWithWebIdentity"
        Condition = {
          StringEquals = {
            "cognito-identity.amazonaws.com:aud" = aws_cognito_identity_pool.main.id
            "cognito-identity.amazonaws.com:amr" = "unauthenticated"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "anonymous_users" {
  name = "${local.base_name}-anonymous-users-policy"
  role = aws_iam_role.anonymous_users.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CognitoIdentityAccess"
        Effect = "Allow"
        Action = [
          "cognito-identity:GetId",
          "cognito-identity:GetOpenIdToken",
          "cognito-identity:GetCredentialsForIdentity"
        ]
        Resource = [
          "arn:${local.partition}:cognito-identity:${local.region}:${local.account_id}:identitypool/${aws_cognito_identity_pool.main.id}"
        ]
      }
    ]
  })
}

# ---------------------------------------------------------------------------
# Attach both roles to the identity pool
# ---------------------------------------------------------------------------
resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated   = aws_iam_role.signed_users.arn
    unauthenticated = aws_iam_role.anonymous_users.arn
  }
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

locals {
  name_prefix = "${terraform.workspace}-batch"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ssm_parameter" "ecs_optimized_ami" {
  name = "/aws/service/ecs/optimized-ami/amazon-linux-2023/recommended/image_id"
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "ecs_for_ec2" {
  name = "AmazonEC2ContainerServiceforEC2Role"
}

data "aws_iam_policy" "batch_service" {
  name = "AWSBatchServiceRole"
}

resource "aws_vpc" "main" {
  cidr_block           = "192.168.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.0.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "192.168.10.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = {
    Name = local.name_prefix
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "batch" {
  name        = local.name_prefix
  description = "Security group for Batch compute environment"
  vpc_id      = aws_vpc.main.id

  egress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_role" "ecs_instance" {
  name = local.name_prefix
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_role_policy_attachment" "ecs_instance" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = data.aws_iam_policy.ecs_for_ec2.arn
}

resource "aws_iam_instance_profile" "batch" {
  name = local.name_prefix
  role = aws_iam_role.ecs_instance.name

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_policy" "ecs_s3" {
  name        = "ecs_s3_policy"
  description = "Custom S3 and KMS permissions for Batch instances"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "S3ReadListAll"
        Effect   = "Allow"
        Action   = ["s3:Get*", "s3:List*"]
        Resource = "*"
      },
      {
        Sid      = "S3ReadWriteDeleteOnResultsBucket"
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::benchmark-batch-results-${data.aws_caller_identity.current.account_id}",
          "arn:aws:s3:::benchmark-batch-results-${data.aws_caller_identity.current.account_id}/*"
        ]
      },
      {
        Sid    = "KMSDecryptGenerateDataKeyOnBucketKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.s3.arn
      }
    ]
  })

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_role_policy_attachment" "ecs_s3" {
  role       = aws_iam_role.ecs_instance.name
  policy_arn = aws_iam_policy.ecs_s3.arn
}

resource "aws_iam_role" "batch_service" {
  name = "${local.name_prefix}-service"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "batch.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_iam_role_policy_attachment" "batch_service" {
  role       = aws_iam_role.batch_service.name
  policy_arn = data.aws_iam_policy.batch_service.arn
}

resource "aws_kms_key" "s3" {
  description             = "KMS key for Batch results bucket"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable Root Account Administration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow ECS Instance Role to Use Key"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.ecs_instance.arn
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.name_prefix}"
  target_key_id = aws_kms_key.s3.id
}

resource "aws_s3_bucket" "results" {
  bucket = "benchmark-batch-results-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_s3_bucket_public_access_block" "results" {
  bucket = aws_s3_bucket.results.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "results" {
  bucket = aws_s3_bucket.results.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.s3.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_versioning" "results" {
  bucket = aws_s3_bucket.results.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_batch_compute_environment" "batch" {
  compute_environment_name = local.name_prefix
  type                     = "MANAGED"
  state                    = "ENABLED"
  service_role             = aws_iam_role.batch_service.arn

  compute_resources {
    type                = "EC2"
    allocation_strategy = "BEST_FIT"
    instance_type       = ["optimal"]
    image_id            = data.aws_ssm_parameter.ecs_optimized_ami.value
    min_vcpus           = 0
    max_vcpus           = 4
    security_group_ids  = [aws_security_group.batch.id]
    subnets             = [aws_subnet.private.id]
    instance_role       = aws_iam_instance_profile.batch.arn
  }

  tags = {
    Name = local.name_prefix
  }
}

resource "aws_batch_job_queue" "batch" {
  name     = "${local.name_prefix}-queue"
  state    = "ENABLED"
  priority = 1

  compute_environment_order {
    order           = 1
    compute_environment = aws_batch_compute_environment.batch.arn
  }

  tags = {
    Name = local.name_prefix
  }
}

terraform {
  required_version = ">= 1.3.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

import {
  to = aws_s3_bucket.endpoint_backup
  id = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

import {
  to = aws_iam_user.endpoint_backup
  id = "endpoint-backup"
}

import {
  to = aws_iam_policy.endpoint_backup_bucket_access
  id = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:policy/endpoint-backup-bucket-read-write-access"
}

resource "aws_kms_key" "backup" {
  description             = "Customer-managed key for endpoint-backup S3 bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "Enable IAM User Permissions"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "Allow endpoint-backup user to use key"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${data.aws_caller_identity.current.account_id}:user/endpoint-backup"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.backup.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "endpoint_backup_bucket_policy" {
  statement {
    sid       = "DenyInsecureConnections"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyComplianceModeRetentionOver90Days"
    effect    = "Deny"
    actions   = ["s3:PutObjectRetention"]
    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = [90]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket_policy.json
}

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

resource "aws_iam_policy" "endpoint_backup_bucket_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Grants read/write access to endpoint-backup S3 bucket and S3 KMS key"

  policy = data.aws_iam_policy_document.endpoint_backup_bucket_access.json
}

data "aws_iam_policy_document" "endpoint_backup_bucket_access" {
  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObjectLegalHold",
      "s3:RestoreObject"
    ]
    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*"
    ]
  }

  statement {
    sid    = "KMSKeyAccess"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey"
    ]
    resources = [aws_kms_key.backup.arn]
  }
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_access.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "uds_distribution_callback_urls" {
  description = "OAuth callback URLs for the Unity UDS distribution app client."
  type        = list(string)
  default     = ["https://api.example.com/uds-distribution/oauth2/callback"]
}

variable "uds_distribution_logout_urls" {
  description = "OAuth logout URLs for the Unity UDS distribution app client."
  type        = list(string)
  default     = ["https://api.example.com/uds-distribution/logout"]
}

variable "localhost_jupyterhub_callback_urls" {
  description = "OAuth callback URLs for the local JupyterHub app client."
  type        = list(string)
  default     = ["http://localhost:8000/hub/oauth_callback"]
}

variable "localhost_jupyterhub_logout_urls" {
  description = "OAuth logout URLs for the local JupyterHub app client."
  type        = list(string)
  default     = ["http://localhost:8000/logout"]
}

variable "app_to_app_callback_urls" {
  description = "OAuth callback URLs for the Unity app-to-app client."
  type        = list(string)
  default     = ["https://api.example.com/app-to-app/oauth2/callback"]
}

variable "app_to_app_logout_urls" {
  description = "OAuth logout URLs for the Unity app-to-app client."
  type        = list(string)
  default     = ["https://api.example.com/app-to-app/logout"]
}

variable "uads_jupyter_development_callback_urls" {
  description = "OAuth callback URLs for the UADS Jupyter development client."
  type        = list(string)
  default     = ["http://localhost:8888/login"]
}

variable "uads_jupyter_development_logout_urls" {
  description = "OAuth logout URLs for the UADS Jupyter development client."
  type        = list(string)
  default     = ["http://localhost:8888/logout"]
}

variable "hysds_ui_callback_urls" {
