}

variable "localhost_hysds_ui_callback_urls" {
  description = "OAuth callback URLs for the local HySDS UI client."
  type        = list(string)
  default     = ["http://localhost:8080/callback"]
}

variable "localhost_hysds_ui_logout_urls" {
  description = "OAuth logout URLs for the local HySDS UI client."
  type        = list(string)
  default     = ["http://localhost:8080/logout"]
}

resource "aws_cognito_user_pool" "shared_services" {
  name = "unity-shared-services-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  admin_create_user_config {
    allow_admin_create_user_only = true

    invite_message_template {
      email_subject = "Your Unity Shared Services temporary password"
      email_message = "Welcome to Unity Shared Services. Your username is {username} and your temporary password is {####}."
      sms_message   = "Unity Shared Services: username {username}, temporary password {####}"
    }
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ssm_parameter" "user_pool_id" {
  name  = "/unity/cs/security/shared-services-cognito-user-pool/user-pool-id"
  type  = "String"
  value = aws_cognito_user_pool.shared_services.id

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_domain" "shared_services_domain" {
  domain       = "unity-shared-services-test"
  user_pool_id = aws_cognito_user_pool.shared_services.id
}

resource "aws_cognito_user_pool_client" "uds_distribution" {
  name         = "unity-uds-distribution-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = true

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.uds_distribution_callback_urls
  logout_urls   = var.uds_distribution_logout_urls
}

resource "aws_cognito_user_pool_client" "localhost_jupyterhub" {
  name         = "localhost-jupyterhub-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = true

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.localhost_jupyterhub_callback_urls
  logout_urls   = var.localhost_jupyterhub_logout_urls
}

resource "aws_cognito_user_pool_client" "app_to_app" {
  name         = "unity-app-to-app-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = true

  explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.app_to_app_callback_urls
  logout_urls   = var.app_to_app_logout_urls
}

resource "aws_cognito_user_pool_client" "uads_jupyter_development" {
  name         = "uads-jupyter-development-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = true

  explicit_auth_flows = ["ALLOW_REFRESH_TOKEN_AUTH"]

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.uads_jupyter_development_callback_urls
  logout_urls   = var.uads_jupyter_development_logout_urls
}

resource "aws_cognito_user_pool_client" "hysds_ui" {
  name         = "hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = false

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.hysds_ui_callback_urls
  logout_urls   = var.hysds_ui_logout_urls
}

resource "aws_cognito_user_pool_client" "localhost_hysds_ui" {
  name         = "localhost-hysds-ui-client-user-pool-client"
  user_pool_id = aws_cognito_user_pool.shared_services.id

  generate_secret = false

  allowed_oauth_flows_user_pool_client = true
  allowed_oauth_flows                  = ["code"]
  allowed_oauth_scopes                 = ["email", "openid"]
  supported_identity_providers         = ["COGNITO"]

  callback_urls = var.localhost_hysds_ui_callback_urls
  logout_urls   = var.localhost_hysds_ui_logout_urls
}

resource "aws_cognito_user_group" "unity_admin" {
  name         = "Unity_Admin"
  user_pool_id = aws_cognito_user_pool.shared_services.id
}

resource "aws_cognito_user_group" "unity_viewer" {
  name         = "Unity_Viewer"
  user_pool_id = aws_cognito_user_pool.shared_services.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "app_name" {
  description = "Application name used for tagging and naming resources."
  type        = string
  default     = "terraform"
}

variable "environment" {
  description = "Deployment environment name used for tagging and naming resources."
  type        = string
  default     = "testing"
}

variable "vpc_name" {
  description = "Name tag applied to the VPC and used as a prefix for child resource names."
  type        = string
  default     = "vpc-terraform-testing"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block."
  }
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public subnets, one per availability zone."
  type        = list(string)
  default = [
    "10.0.10.0/24",
    "10.0.20.0/24",
    "10.0.30.0/24",
  ]

  validation {
    condition     = length(var.public_subnet_cidrs) == 3
    error_message = "Exactly three public subnet CIDR blocks are required."
  }
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets, one per availability zone."
  type        = list(string)
  default = [
    "10.0.11.0/24",
    "10.0.22.0/24",
    "10.0.33.0/24",
  ]

  validation {
    condition     = length(var.private_subnet_cidrs) == 3
    error_message = "Exactly three private subnet CIDR blocks are required."
  }
}

variable "enable_transit_gateway_attachment" {
  description = "When true, create a transit gateway and attach the VPC private subnets to it."
  type        = bool
  default     = false
}

variable "enable_ipv6_egress" {
  description = "When true, assign an IPv6 CIDR to the VPC and create IPv6 egress-only internet access."
  type        = bool
  default     = false
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    App         = var.app_name
    Environment = var.environment
  }

  availability_zones = slice(data.aws_availability_zones.available.names, 0, 3)
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  enable_dns_support               = true
  enable_dns_hostnames             = false
  assign_generated_ipv6_cidr_block = var.enable_ipv6_egress

  tags = merge(
    local.common_tags,
    {
      Name = var.vpc_name
    }
  )
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.public_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  # Public reachability is provided by the public route table's 0.0.0.0/0
  # route to the internet gateway, not by launch-time public IP assignment.
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-public-${local.availability_zones[count.index]}"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = local.availability_zones[count.index]

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-private-${local.availability_zones[count.index]}"
      Tier = "private"
    }
  )
}

###############################################################################
# Internet gateway and public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# NAT gateway and private routing
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-nat-eip"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-nat"
    }
  )

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-private-rt"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Optional IPv6 egress-only internet access (disabled by default)
###############################################################################

resource "aws_egress_only_internet_gateway" "main" {
  count = var.enable_ipv6_egress ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-eigw"
    }
  )
}

resource "aws_route" "private_ipv6_egress" {
  count = var.enable_ipv6_egress ? 1 : 0

  route_table_id              = aws_route_table.private.id
  destination_ipv6_cidr_block = "::/0"
  egress_only_gateway_id      = aws_egress_only_internet_gateway.main[0].id
}

###############################################################################
# RDS subnet group spanning the private subnets
###############################################################################

resource "aws_db_subnet_group" "main" {
  name       = "db-subnet-terraform-testing"
  subnet_ids = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "db-subnet-terraform-testing"
    }
  )
}

###############################################################################
# Optional transit gateway attachment (disabled by default)
###############################################################################

resource "aws_ec2_transit_gateway" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  description                     = "Transit gateway for ${var.vpc_name}"
  default_route_table_association = "enable"
  default_route_table_propagation = "enable"

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-tgw"
    }
  )
}

resource "aws_ec2_transit_gateway_vpc_attachment" "main" {
  count = var.enable_transit_gateway_attachment ? 1 : 0

  transit_gateway_id = aws_ec2_transit_gateway.main[0].id
  vpc_id             = aws_vpc.main.id
  subnet_ids         = aws_subnet.private[*].id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.vpc_name}-tgw-attachment"
    }
  )
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "The IPv4 CIDR block of the VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_name" {
  description = "The Name tag of the VPC."
  value       = var.vpc_name
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "public_subnet_cidr_blocks" {
  description = "CIDR blocks of the public subnets."
  value       = aws_subnet.public[*].cidr_block
}

output "public_subnet_availability_zones" {
  description = "Availability zones of the public subnets."
  value       = aws_subnet.public[*].availability_zone
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_subnet_cidr_blocks" {
  description = "CIDR blocks of the private subnets."
  value       = aws_subnet.private[*].cidr_block
}

output "private_subnet_availability_zones" {
  description = "Availability zones of the private subnets."
  value       = aws_subnet.private[*].availability_zone
}

output "default_security_group_id" {
  description = "ID of the VPC default security group."
  value       = aws_vpc.main.default_security_group_id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the shared private route table."
  value       = aws_route_table.private.id
}

output "nat_gateway_id" {
  description = "ID of the NAT gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Public Elastic IP address associated with the NAT gateway."
  value       = aws_eip.nat.public_ip
}

output "nat_gateway_allocation_id" {
  description = "Allocation ID of the Elastic IP used by the NAT gateway."
  value       = aws_eip.nat.id
}

output "nat_gateway_subnet_id" {
  description = "ID of the public subnet hosting the NAT gateway."
  value       = aws_nat_gateway.main.subnet_id
}

output "db_subnet_group_name" {
  description = "Name of the DB subnet group spanning the private subnets."
  value       = aws_db_subnet_group.main.name
}

output "transit_gateway_id" {
  description = "ID of the transit gateway, if the optional attachment is enabled."
  value       = try(aws_ec2_transit_gateway.main[0].id, null)
}

output "transit_gateway_attachment_id" {
  description = "ID of the transit gateway VPC attachment, if enabled."
  value       = try(aws_ec2_transit_gateway_vpc_attachment.main[0].id, null)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

variable "project_name" {
  description = "Project name used for resource tagging."
  type        = string
  default     = "gitops-bridge"
}

variable "environment" {
  description = "Deployment environment name used for resource tagging."
  type        = string
  default     = "dev"
}

locals {
  iam_user_name       = "gitops-bridge-gitops"
  iam_policy_name     = "gitops-bridge-gitops"
  secret_name_prefix  = "codecommit-key-"

  ssh_directory        = pathexpand("~/.ssh")
  ssh_private_key_path = pathexpand("~/.ssh/gitops_ssh.pem")
  ssh_config_path      = pathexpand("~/.ssh/config")

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

resource "aws_codecommit_repository" "gitops_apps" {
  repository_name = "gitops-apps"
  description     = "Argo CD GitOps bridge repository for application workloads."

  tags = local.common_tags
}

resource "aws_codecommit_repository" "gitops_platform" {
  repository_name = "gitops-platform"
  description     = "Argo CD GitOps bridge repository for platform components."

  tags = local.common_tags
}

resource "aws_codecommit_repository" "gitops_addons" {
  repository_name = "gitops-addons"
  description     = "Argo CD GitOps bridge repository for cluster add-ons."

  tags = local.common_tags
}

resource "aws_iam_user" "gitops_bridge_gitops" {
  name = local.iam_user_name
  path = "/"

  tags = local.common_tags
}

resource "tls_private_key" "gitops_bridge" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_iam_user_ssh_key" "gitops_bridge" {
  username   = aws_iam_user.gitops_bridge_gitops.name
  encoding   = "SSH"
  public_key = tls_private_key.gitops_bridge.public_key_openssh
  status     = "Active"
}

data "aws_iam_policy_document" "gitops_bridge_gitops" {
  statement {
    sid    = "CodeCommitGitPullPush"
    effect = "Allow"

    actions = [
      "codecommit:GitPull",
      "codecommit:GitPush",
    ]

    resources = [
      aws_codecommit_repository.gitops_apps.arn,
      aws_codecommit_repository.gitops_platform.arn,
      aws_codecommit_repository.gitops_addons.arn,
    ]
  }
}

resource "aws_iam_policy" "gitops_bridge_gitops" {
  name        = local.iam_policy_name
  description = "Least-privilege Git pull and push access to the GitOps bridge CodeCommit repositories."

  policy = data.aws_iam_policy_document.gitops_bridge_gitops.json

  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "gitops_bridge_gitops" {
  user       = aws_iam_user.gitops_bridge_gitops.name
  policy_arn = aws_iam_policy.gitops_bridge_gitops.arn
}

resource "random_string" "secret_suffix" {
  length  = 5
  upper   = false
  special = false
}

resource "aws_secretsmanager_secret" "codecommit_key" {
  name        = "${local.secret_name_prefix}${random_string.secret_suffix.result}"
  description = "SSH private key for the ${local.iam_user_name} IAM user used to access the GitOps bridge CodeCommit repositories."

  recovery_window_in_days = 0

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_secretsmanager_secret_version" "codecommit_key" {
  secret_id     = aws_secretsmanager_secret.codecommit_key.id
  secret_string = tls_private_key.gitops_bridge.private_key_pem
}

resource "terraform_data" "ssh_directory" {
  triggers_replace = {
    ssh_directory = local.ssh_directory
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = "mkdir -p ~/.ssh && chmod 700 ~/.ssh"
  }
}

resource "local_file" "gitops_ssh_private_key" {
  filename        = local.ssh_private_key_path
  content         = tls_private_key.gitops_bridge.private_key_pem
  file_permission = "0600"

  depends_on = [terraform_data.ssh_directory]
}

resource "local_file" "ssh_config" {
  filename        = local.ssh_config_path
  file_permission = "0600"

  content = <<-EOT
    Host git-codecommit.*.amazonaws.com
      User ${aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id}
      IdentityFile ~/.ssh/gitops_ssh.pem
  EOT

  depends_on = [
    terraform_data.ssh_directory,
    local_file.gitops_ssh_private_key,
  ]
}

output "iam_user_name" {
  description = "Name of the GitOps bridge IAM user."
  value       = aws_iam_user.gitops_bridge_gitops.name
}

output "iam_policy_arn" {
  description = "ARN of the customer-managed least-privilege CodeCommit policy."
  value       = aws_iam_policy.gitops_bridge_gitops.arn
}

output "codecommit_ssh_key_id" {
  description = "SSH public key identifier used as the SSH username for CodeCommit."
  value       = aws_iam_user_ssh_key.gitops_bridge.ssh_public_key_id
  sensitive   = true
}

output "codecommit_key_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the generated SSH private key."
  value       = aws_secretsmanager_secret.codecommit_key.arn
  sensitive   = true
}

output "codecommit_repository_clone_urls" {
  description = "SSH clone URLs for the GitOps bridge CodeCommit repositories."
  value = {
    gitops-apps     = aws_codecommit_repository.gitops_apps.clone_url_ssh
    gitops-platform = aws_codecommit_repository.gitops_platform.clone_url_ssh
    gitops-addons   = aws_codecommit_repository.gitops_addons.clone_url_ssh
  }
  sensitive = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  name_prefix = "benchmark"

  common_tags = merge(
    {
      Environment = "benchmark"
      ManagedBy   = "terraform"
      Module      = "single-ec2-instance"
    },
    var.tags
  )

  # Use the caller-supplied public key when present, otherwise fall back to a
  # valid, plan-time generated OpenSSH public key. Only the public half is ever
  # consumed by resources; no private key material is exposed anywhere.
  ssh_public_key = var.ssh_public_key != "" ? var.ssh_public_key : tls_private_key.generated.public_key_openssh
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "vpc_cidr" {
  description = "CIDR block for the VPC created by the module."
  type        = string
  default     = "10.70.0.0/16"
}

variable "subnet_cidr" {
  description = "CIDR block for the single subnet created by the module."
  type        = string
  default     = "10.70.0.0/24"
}

variable "instance_type" {
  description = "EC2 instance type for the benchmark instance."
  type        = string
  default     = "t2.micro"
}

variable "root_volume_size" {
  description = "Size in GiB of the encrypted gp2 root volume."
  type        = number
  default     = 10
}

variable "ssh_public_key" {
  description = "Public key material used to create the benchmark SSH key pair. When left empty (default), a valid OpenSSH key pair is generated at plan time and its public half is used instead."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

variable "extra_ebs_volumes" {
  description = "Optional extra EBS volumes keyed by logical name. Defaults to none."
  type = map(object({
    size        = number
    volume_type = optional(string, "gp3")
    device_name = string
  }))
  default = {}
}

variable "extra_network_interfaces" {
  description = "Optional extra network interfaces (each with its own Elastic IP). Defaults to none."
  type = map(object({
    private_ip   = optional(string)
    device_index = optional(number, 1)
  }))
  default = {}
}

# -----------------------------------------------------------------------------
# Data sources
# -----------------------------------------------------------------------------

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "ubuntu" {
  most_recent = true

  owners = ["099720109477"] # Canonical

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd/ubuntu-jammy-22.04-amd64-server-*"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

data "aws_iam_policy_document" "ec2_assume_role" {
  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

# -----------------------------------------------------------------------------
# Generated key material (fallback when no public key is supplied)
# -----------------------------------------------------------------------------

resource "tls_private_key" "generated" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

# -----------------------------------------------------------------------------
# Network
# -----------------------------------------------------------------------------

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-vpc"
  })
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidr
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-subnet"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-igw"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

# -----------------------------------------------------------------------------
# Security group (dedicated, no ingress, VPC-scoped egress only)
# -----------------------------------------------------------------------------

resource "aws_security_group" "instance" {
  name        = "${local.name_prefix}-instance-sg"
  description = "Dedicated security group for the benchmark EC2 instance."
  vpc_id      = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-sg"
  })
}

resource "aws_vpc_security_group_egress_rule" "allow_vpc_egress" {
  security_group_id = aws_security_group.instance.id
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-egress-vpc"
  })
}

# -----------------------------------------------------------------------------
# SSH key pair
# -----------------------------------------------------------------------------

resource "aws_key_pair" "benchmark" {
  key_name   = "benchmark-d8bc612be4e0-key"
  public_key = local.ssh_public_key

  tags = merge(local.common_tags, {
    Name = "benchmark-d8bc612be4e0-key"
  })
}

# -----------------------------------------------------------------------------
# IAM role and instance profile
# -----------------------------------------------------------------------------

resource "aws_iam_role" "ec2" {
  name               = "${local.name_prefix}-ec2-role"
  assume_role_policy = data.aws_iam_policy_document.ec2_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-role"
  })
}

resource "aws_iam_role_policy_attachment" "ec2_ssm_core" {
  role       = aws_iam_role.ec2.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "ec2" {
  name = "${local.name_prefix}-ec2-profile"
  role = aws_iam_role.ec2.name

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ec2-profile"
  })
}

# -----------------------------------------------------------------------------
# EC2 instance
# -----------------------------------------------------------------------------

resource "aws_instance" "benchmark_instance" {
  ami                         = data.aws_ami.ubuntu.id
  instance_type               = var.instance_type
  subnet_id                   = aws_subnet.public.id
  vpc_security_group_ids      = [aws_security_group.instance.id]
  key_name                    = aws_key_pair.benchmark.key_name
  associate_public_ip_address = true
  monitoring                  = true
  iam_instance_profile        = aws_iam_instance_profile.ec2.name

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  root_block_device {
    volume_size           = var.root_volume_size
    volume_type           = "gp2"
    encrypted             = true
    delete_on_termination = true
  }

  tags = merge(local.common_tags, {
    Name = "benchmark-instance"
  })
}

# -----------------------------------------------------------------------------
# Elastic IP for the primary instance
# -----------------------------------------------------------------------------

resource "aws_eip" "benchmark" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eip"
  })
}

resource "aws_eip_association" "benchmark" {
  allocation_id = aws_eip.benchmark.id
  instance_id   = aws_instance.benchmark_instance.id
}

# -----------------------------------------------------------------------------
# Optional extra EBS volumes (default: none)
# -----------------------------------------------------------------------------

resource "aws_ebs_volume" "extra" {
  for_each = var.extra_ebs_volumes

  availability_zone = aws_instance.benchmark_instance.availability_zone
  size              = each.value.size
  type              = each.value.volume_type
  encrypted         = true

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-ebs-${each.key}"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_volume_attachment" "extra" {
  for_each = var.extra_ebs_volumes

  device_name = each.value.device_name
  volume_id   = aws_ebs_volume.extra[each.key].id
  instance_id = aws_instance.benchmark_instance.id
}

# -----------------------------------------------------------------------------
# Optional extra network interfaces with Elastic IPs (default: none)
# -----------------------------------------------------------------------------

resource "aws_network_interface" "extra" {
  for_each = var.extra_network_interfaces

  subnet_id       = aws_subnet.public.id
  private_ips     = each.value.private_ip == null ? null : [each.value.private_ip]
  security_groups = [aws_security_group.instance.id]

  attachment {
    instance     = aws_instance.benchmark_instance.id
    device_index = each.value.device_index
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni-${each.key}"
  })
}

resource "aws_eip" "extra" {
  for_each = var.extra_network_interfaces

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-eni-eip-${each.key}"
  })
}

resource "aws_eip_association" "extra" {
  for_each = var.extra_network_interfaces

  allocation_id        = aws_eip.extra[each.key].id
  network_interface_id = aws_network_interface.extra[each.key].id
}

# -----------------------------------------------------------------------------
# CloudWatch alarm with automatic reboot action
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_metric_alarm" "status_check_failed_instance" {
  alarm_name          = "${local.name_prefix}-instance-status-check-failed"
  namespace           = "AWS/EC2"
  metric_name         = "StatusCheckFailed_Instance"
  statistic           = "Maximum"
  period              = 60
  evaluation_periods  = 5
  threshold           = 1
  comparison_operator = "GreaterThanOrEqualToThreshold"

  dimensions = {
    InstanceId = aws_instance.benchmark_instance.id
  }

  alarm_description = "Reboot benchmark-instance when instance status checks fail."
  alarm_actions     = ["arn:${data.aws_partition.current.partition}:automate:${data.aws_region.current.name}:ec2:reboot"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-instance-status-check-failed"
  })
}

# -----------------------------------------------------------------------------
# Outputs
# -----------------------------------------------------------------------------

output "instance_id" {
  description = "ID of the benchmark EC2 instance."
  value       = aws_instance.benchmark_instance.id
}

output "instance_private_ip" {
  description = "Private IP address of the benchmark EC2 instance."
  value       = aws_instance.benchmark_instance.private_ip
}

output "elastic_ip" {
  description = "Elastic IP address associated with the benchmark instance."
  value       = aws_eip.benchmark.public_ip
}

output "public_ip" {
  description = "Public IP address of the benchmark EC2 instance."
  value       = aws_instance.benchmark_instance.public_ip
}

output "subnet_id" {
  description = "ID of the subnet created by the module."
  value       = aws_subnet.public.id
}

output "vpc_id" {
  description = "ID of the VPC created by the module."
  value       = aws_vpc.main.id
}

output "security_group_id" {
  description = "ID of the instance security group."
  value       = aws_security_group.instance.id
}

output "iam_instance_profile_name" {
  description = "Name of the IAM instance profile attached to the instance."
  value       = aws_iam_instance_profile.ec2.name
}

output "cloudwatch_alarm_name" {
  description = "Name of the instance status check CloudWatch alarm."
  value       = aws_cloudwatch_metric_alarm.status_check_failed_instance.alarm_name
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
