resource "aws_iam_role" "s3_replication" {
  name = "s3-cross-region-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Env     = local.env
    Name    = "s3-cross-region-replication-role"
    Purpose = "s3-replication"
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least-privilege policy for S3 cross-region replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketRead"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          aws_s3_bucket.log1a.arn,
          "${aws_s3_bucket.log1a.arn}/*",
          aws_s3_bucket.log1b.arn,
          "${aws_s3_bucket.log1b.arn}/*",
          aws_s3_bucket.log2a.arn,
          "${aws_s3_bucket.log2a.arn}/*",
          aws_s3_bucket.log2b.arn,
          "${aws_s3_bucket.log2b.arn}/*"
        ]
      },
      {
        Sid    = "DestinationBucketWrite"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          aws_s3_bucket.log1a_replica1.arn,
          "${aws_s3_bucket.log1a_replica1.arn}/*",
          aws_s3_bucket.log1b_replica1.arn,
          "${aws_s3_bucket.log1b_replica1.arn}/*",
          aws_s3_bucket.log2a_replica1.arn,
          "${aws_s3_bucket.log2a_replica1.arn}/*",
          aws_s3_bucket.log2b_replica1.arn,
          "${aws_s3_bucket.log2b_replica1.arn}/*",
          aws_s3_bucket.log1a_replica2.arn,
          "${aws_s3_bucket.log1a_replica2.arn}/*",
          aws_s3_bucket.log1b_replica2.arn,
          "${aws_s3_bucket.log1b_replica2.arn}/*",
          aws_s3_bucket.log2a_replica2.arn,
          "${aws_s3_bucket.log2a_replica2.arn}/*",
          aws_s3_bucket.log2b_replica2.arn,
          "${aws_s3_bucket.log2b_replica2.arn}/*"
        ]
      },
      {
        Sid    = "SourceKmsDecrypt"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = [
          aws_kms_key.source_key_1.arn,
          aws_kms_key.source_key_2.arn
        ]
      },
      {
        Sid    = "ReplicaKmsEncrypt"
        Effect = "Allow"
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey",
          "kms:ReEncryptFrom",
          "kms:ReEncryptTo"
        ]
        Resource = [
          aws_kms_key.replica_key_1.arn,
          aws_kms_key.replica_key_2.arn
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

resource "aws_s3_bucket_policy" "source1" {
  for_each = {
    log1a = aws_s3_bucket.log1a.id
    log1b = aws_s3_bucket.log1b.id
  }

  bucket = each.value

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3ReplicationSourceAccess"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.s3_replication.arn
        }
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "arn:${local.partition}:s3:::${each.value}",
          "arn:${local.partition}:s3:::${each.value}/*"
        ]
      },
      {
        Sid       = "DenyNonTLS"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          "arn:${local.partition}:s3:::${each.value}",
          "arn:${local.partition}:s3:::${each.value}/*"
        ]
        Condition = {
          Bool = {
            "aws:SecureTransport" = "false"
          }
        }
      }
    ]
  })
}

