resource "aws_s3_bucket_replication_configuration" "log1a" {
  bucket = aws_s3_bucket.log1a.id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "log1a-to-replica1"
    priority = 1
    status   = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.log1a_replica1.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key_1.arn
      }
    }
  }

  rule {
    id       = "log1a-to-replica2"
    priority = 2
    status   = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
