      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica_key_2.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.log1a,
    aws_s3_bucket_versioning.log1a_replica1,
    aws_s3_bucket_versioning.log1a_replica2,
    aws_s3_bucket_policy.source1,
    aws_s3_bucket_policy.replica1,
    aws_s3_bucket_policy.replica2,
    aws_iam_role_policy_attachment.s3_replication
  ]
}

