terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

variable "repository_url" {
  description = "Repository URL of the module, applied as the Repository tag on all taggable resources."
  type        = string
  default     = "https://github.com/example/terraform-aws-guardduty"
}

variable "name_prefix" {
  description = "Prefix used to name created resources."
  type        = string
  default     = "guardduty"
}

variable "tags" {
  description = "Additional tags merged with the module Repository tag."
  type        = map(string)
  default     = {}
}

variable "replica_region" {
  description = "Destination region used for cross-region replication of findings."
  type        = string
  default     = "us-west-2"
}

variable "enable_findings_filters" {
  description = "Create a GuardDuty findings filter."
  type        = bool
  default     = false
}

variable "enable_trusted_ip_sets" {
  description = "Create a GuardDuty trusted IP set backed by S3."
  type        = bool
  default     = false
}

variable "enable_threat_intel_sets" {
  description = "Create a GuardDuty threat intelligence set backed by S3."
  type        = bool
  default     = false
}

variable "enable_malware_protection_plan" {
  description = "Create a GuardDuty malware protection plan for an S3 bucket."
  type        = bool
  default     = false
}

variable "enable_findings_export" {
  description = "Export GuardDuty findings to a versioned, encrypted, access-logged and replicated S3 bucket."
  type        = bool
  default     = false
}

variable "findings_filter" {
  description = "GuardDuty findings filter configuration (used only when enable_findings_filters is true)."
  type = object({
    name        = string
    action      = string
    rank        = number
    description = string
    criteria = list(object({
      field                 = string
      equals                = optional(list(string))
      not_equals            = optional(list(string))
      greater_than          = optional(string)
      less_than             = optional(string)
      greater_than_or_equal = optional(string)
      less_than_or_equal    = optional(string)
    }))
  })
  default = {
    name        = "high-severity"
    action      = "ARCHIVE"
    rank        = 1
    description = "Managed by Terraform"
    criteria = [
      {
        field  = "severity"
        equals = ["8"]
      }
    ]
  }
}

variable "trusted_ip_set_name" {
  description = "Name of the GuardDuty trusted IP set."
  type        = string
  default     = "trusted-ip-set"
}

variable "trusted_ip_set_ips" {
  description = "List of trusted IP addresses or CIDR ranges."
  type        = list(string)
  default     = []
}

variable "threat_intel_set_name" {
  description = "Name of the GuardDuty threat intelligence set."
  type        = string
  default     = "threat-intel-set"
}

variable "threat_intel_set_ips" {
  description = "List of threat intelligence IP addresses or CIDR ranges."
  type        = list(string)
  default     = []
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.name
  tags       = merge({ Repository = var.repository_url }, var.tags)
}

resource "aws_guardduty_detector" "this" {
  enable                       = true
  finding_publishing_frequency = "FIFTEEN_MINUTES"

  tags = local.tags
}

resource "aws_guardduty_detector_feature" "s3_data_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "S3_DATA_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "rds_login_events" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RDS_LOGIN_EVENTS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "lambda_network_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "LAMBDA_NETWORK_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "eks_audit_logs" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EKS_AUDIT_LOGS"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "ebs_malware_protection" {
  detector_id = aws_guardduty_detector.this.id
  name        = "EBS_MALWARE_PROTECTION"
  status      = "ENABLED"
}

resource "aws_guardduty_detector_feature" "runtime_monitoring" {
  detector_id = aws_guardduty_detector.this.id
  name        = "RUNTIME_MONITORING"
  status      = "ENABLED"

  additional_configuration {
    name   = "EKS_ADDON_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "ECS_FARGATE_AGENT_MANAGEMENT"
    status = "DISABLED"
  }

  additional_configuration {
    name   = "EC2_AGENT_MANAGEMENT"
    status = "DISABLED"
  }
}

resource "terraform_data" "malware_scan_settings" {
  triggers_replace = {
    detector_id = aws_guardduty_detector.this.id
    account_id  = local.account_id
  }

  provisioner "local-exec" {
    command = "aws guardduty update-malware-scan-settings --detector-id ${aws_guardduty_detector.this.id} --ebs-snapshot-preservation NO_RETENTION"
  }

  depends_on = [
    aws_guardduty_detector.this,
    aws_guardduty_detector_feature.ebs_malware_protection,
  ]
}

resource "aws_guardduty_filter" "this" {
  count = var.enable_findings_filters ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = var.findings_filter.name
  action      = var.findings_filter.action
  rank        = var.findings_filter.rank
  description = var.findings_filter.description

  finding_criteria {
    dynamic "criterion" {
      for_each = var.findings_filter.criteria
      content {
        field                 = criterion.value.field
        equals                = criterion.value.equals
        not_equals            = criterion.value.not_equals
        greater_than          = criterion.value.greater_than
        less_than             = criterion.value.less_than
        greater_than_or_equal = criterion.value.greater_than_or_equal
        less_than_or_equal    = criterion.value.less_than_or_equal
      }
    }
  }

  tags = local.tags
}

resource "aws_s3_bucket" "trusted_ipset" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  bucket = "${var.name_prefix}-trusted-ipset-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "trusted_ipset" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  bucket                  = aws_s3_bucket.trusted_ipset[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "trusted_ipset" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  bucket = aws_s3_bucket.trusted_ipset[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_object" "trusted_ipset" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  bucket       = aws_s3_bucket.trusted_ipset[0].id
  key          = "trusted-ip-set.txt"
  content      = join("\n", var.trusted_ip_set_ips)
  content_type = "text/plain"

  depends_on = [aws_s3_bucket_public_access_block.trusted_ipset]
}

resource "aws_guardduty_ipset" "this" {
  count = var.enable_trusted_ip_sets ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = var.trusted_ip_set_name
  format      = "TXT"
  location    = "s3://${aws_s3_bucket.trusted_ipset[0].bucket}/${aws_s3_object.trusted_ipset[0].key}"
  activate    = true

  tags = local.tags
}

resource "aws_s3_bucket" "threat_intel_set" {
  count = var.enable_threat_intel_sets ? 1 : 0

  bucket = "${var.name_prefix}-threat-intel-set-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "threat_intel_set" {
  count = var.enable_threat_intel_sets ? 1 : 0

  bucket                  = aws_s3_bucket.threat_intel_set[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "threat_intel_set" {
  count = var.enable_threat_intel_sets ? 1 : 0

  bucket = aws_s3_bucket.threat_intel_set[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_object" "threat_intel_set" {
  count = var.enable_threat_intel_sets ? 1 : 0

  bucket       = aws_s3_bucket.threat_intel_set[0].id
  key          = "threat-intel-set.txt"
  content      = join("\n", var.threat_intel_set_ips)
  content_type = "text/plain"

  depends_on = [aws_s3_bucket_public_access_block.threat_intel_set]
}

resource "aws_guardduty_threatintelset" "this" {
  count = var.enable_threat_intel_sets ? 1 : 0

  detector_id = aws_guardduty_detector.this.id
  name        = var.threat_intel_set_name
  format      = "TXT"
  location    = "s3://${aws_s3_bucket.threat_intel_set[0].bucket}/${aws_s3_object.threat_intel_set[0].key}"
  activate    = true

  tags = local.tags
}

resource "aws_s3_bucket" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  bucket = "${var.name_prefix}-malware-protection-plan-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  bucket                  = aws_s3_bucket.malware_protection_plan[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  bucket = aws_s3_bucket.malware_protection_plan[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

data "aws_iam_policy_document" "malware_protection_plan_assume" {
  count = var.enable_malware_protection_plan ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["malware-protection-plan.guardduty.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  statement {
    sid    = "S3BucketAccess"
    effect = "Allow"
    actions = [
      "s3:GetBucketLocation",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.malware_protection_plan[0].arn]
  }

  statement {
    sid    = "S3ObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:PutObjectTagging",
    ]
    resources = ["${aws_s3_bucket.malware_protection_plan[0].arn}/*"]
  }
}

resource "aws_iam_role" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  name               = "${var.name_prefix}-malware-protection-plan"
  assume_role_policy = data.aws_iam_policy_document.malware_protection_plan_assume[0].json

  tags = local.tags
}

resource "aws_iam_role_policy" "malware_protection_plan" {
  count = var.enable_malware_protection_plan ? 1 : 0

  name   = "${var.name_prefix}-malware-protection-plan"
  role   = aws_iam_role.malware_protection_plan[0].id
  policy = data.aws_iam_policy_document.malware_protection_plan[0].json
}

resource "aws_guardduty_malware_protection_plan" "this" {
  count = var.enable_malware_protection_plan ? 1 : 0

  role = aws_iam_role.malware_protection_plan[0].arn

  protected_resource {
    s3_bucket {
      bucket_name = aws_s3_bucket.malware_protection_plan[0].bucket
    }
  }

  actions {
    tagging {
      status = "ENABLED"
    }
  }

  tags = local.tags
}

data "aws_iam_policy_document" "replication_assume" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name               = "${var.name_prefix}-findings-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "gd_findings_kms" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AccountKeyAdministration"
    effect = "Allow"
    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:EnableKeyRotation",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:PutKeyPolicy",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowGuardDutyUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowS3ServiceUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid    = "AllowReplicationRoleUse"
    effect = "Allow"
    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication[0].arn]
    }
  }
}

resource "aws_kms_key" "gd_findings" {
  count = var.enable_findings_export ? 1 : 0

  description             = "KMS key used by GuardDuty findings export"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.gd_findings_kms[0].json

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "gd_findings" {
  count = var.enable_findings_export ? 1 : 0

  name          = "alias/${var.name_prefix}-findings"
  target_key_id = aws_kms_key.gd_findings[0].key_id
}

resource "aws_s3_bucket" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = "${var.name_prefix}-findings-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = "${var.name_prefix}-access-logs-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = "${var.name_prefix}-findings-replica-${local.account_id}"

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket                  = aws_s3_bucket.findings[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket                  = aws_s3_bucket.access_logs[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket                  = aws_s3_bucket.findings_replica[0].id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.gd_findings[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.gd_findings[0].arn
      sse_algorithm     = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "findings_replica" {
  count    = var.enable_findings_export ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.findings_replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_logging" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id

  target_bucket = aws_s3_bucket.access_logs[0].id
  target_prefix = "logs/"
}

data "aws_iam_policy_document" "findings_bucket" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AllowGuardDutyPutObject"
    effect = "Allow"

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]

    principals {
      type        = "Service"
      identifiers = ["guardduty.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = ["arn:${local.partition}:guardduty:${local.region}:${local.account_id}:detector/${aws_guardduty_detector.this.id}"]
    }
  }

  statement {
    sid    = "DenyNonTLS"
    effect = "Deny"

    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.findings[0].arn,
      "${aws_s3_bucket.findings[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  policy = data.aws_iam_policy_document.findings_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.findings]
}

data "aws_iam_policy_document" "access_logs_bucket" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "AllowS3ServerAccessLogging"
    effect = "Allow"

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.access_logs[0].arn}/logs/*"]

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.findings[0].arn]
    }
  }

  statement {
    sid    = "DenyNonTLS"
    effect = "Deny"

    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.access_logs[0].arn,
      "${aws_s3_bucket.access_logs[0].arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "access_logs" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.access_logs[0].id
  policy = data.aws_iam_policy_document.access_logs_bucket[0].json

  depends_on = [aws_s3_bucket_public_access_block.access_logs]
}

data "aws_iam_policy_document" "replication" {
  count = var.enable_findings_export ? 1 : 0

  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.findings[0].arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = ["${aws_s3_bucket.findings[0].arn}/*"]
  }

  statement {
    sid    = "DestinationObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = ["${aws_s3_bucket.findings_replica[0].arn}/*"]
  }

  statement {
    sid    = "SourceKmsPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]
    resources = [aws_kms_key.gd_findings[0].arn]
  }
}

resource "aws_iam_policy" "replication" {
  count = var.enable_findings_export ? 1 : 0

  name   = "${var.name_prefix}-findings-replication"
  policy = data.aws_iam_policy_document.replication[0].json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "replication" {
  count = var.enable_findings_export ? 1 : 0

  role       = aws_iam_role.replication[0].name
  policy_arn = aws_iam_policy.replication[0].arn
}

resource "aws_s3_bucket_replication_configuration" "findings" {
  count = var.enable_findings_export ? 1 : 0

  bucket = aws_s3_bucket.findings[0].id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "guardduty-findings-replication"
    status = "Enabled"

    filter {}

    destination {
      bucket        = aws_s3_bucket.findings_replica[0].arn
      storage_class = "STANDARD"
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.findings,
    aws_s3_bucket_versioning.findings_replica,
  ]
}

resource "aws_guardduty_publishing_destination" "this" {
  count = var.enable_findings_export ? 1 : 0

  detector_id      = aws_guardduty_detector.this.id
  destination_arn  = aws_s3_bucket.findings[0].arn
  kms_key_arn      = aws_kms_key.gd_findings[0].arn
  destination_type = "S3"
}

output "guardduty_detector_id" {
  description = "The ID of the GuardDuty detector."
  value       = aws_guardduty_detector.this.id
}

output "guardduty_detector_arn" {
  description = "The ARN of the GuardDuty detector."
  value       = aws_guardduty_detector.this.arn
}

output "guardduty_publishing_destination_arn" {
  description = "The ARN of the GuardDuty findings publishing destination, when enabled."
  value       = one(aws_guardduty_publishing_destination.this[*].arn)
}

output "guardduty_findings_bucket_name" {
  description = "The name of the GuardDuty findings export bucket, when enabled."
  value       = one(aws_s3_bucket.findings[*].bucket)
}

output "guardduty_findings_bucket_arn" {
  description = "The ARN of the GuardDuty findings export bucket, when enabled."
  value       = one(aws_s3_bucket.findings[*].arn)
}
